import io
from typing import List, Tuple, Union

class BytesIOMerger:
    def __init__(self):
        self.streams = []
        self.total_size = 0
        self.checksums = []

    def add_stream(self, stream: io.BytesIO) -> None:
        self.streams.append(stream)
        self.total_size += stream.tell()
        self.checksums.append(0)

    def merge(self) -> Tuple[io.BytesIO, List[int]]:
        output_stream = io.BytesIO()
        buffer = bytearray()

        for i, stream in enumerate(self.streams):
            while True:
                chunk = stream.read(4096)
                if not chunk:
                    break

                # Update the checksum
                output_stream.write(chunk)
                self.checksums[i] += sum(bytearray(chunk))

                # Add to the buffer
                buffer.extend(chunk)

        return output_stream, buffer

    def resume_merge(self, stream: io.BytesIO) -> None:
        for i, s in enumerate(self.streams):
            while True:
                chunk = s.read(4096)
                if not chunk:
                    break

                # Update the checksum
                stream.write(chunk)
                self.checksums[i] += sum(bytearray(chunk))

    def get_checksums(self) -> List[int]:
        return self.checksums

