function asyncReduce(arr, initialValue, callback) {
    if (!Array.isArray(arr)) throw new Error('Input must be an array');
    if (!callback || typeof callback !== 'function') throw new Error('Callback function is required');

    let accumulatedValue = initialValue;
    let hasError = false;

    (function iterate(array) {
        if (!array.length) return;

        const currentNumber = array.shift();
        if (typeof currentNumber !== 'number' && !isFinite(currentNumber)) {
            hasError = true;
            callback(accumulatedValue, null, () => {
                if (!hasError) asyncReduce(arr, initialValue, callback);
            });
            return;
        }

        callback((error, result) => {
            if (error) {
                hasError = true;
                asyncReduce(array, accumulatedValue, callback);
            } else {
                accumulatedValue = result;
                iterate(array);
            }
        }, accumulatedValue, currentNumber);
    })(arr);

    return new Promise((resolve, reject) => {
        callback(undefined, accumulatedValue, () => {
            if (!hasError) resolve(accumulatedValue);
            else reject(new Error('Error occurred during reduction'));
        });
    });
}
