```
function renderFooterScripts(scripts) {
  const scriptElems = [];
  scripts.forEach((script) => {
    if (!('src' in script) || !('type' in script) || !('key' in script)) {
      throw new Error(`Script object is missing required properties: src, type, and key`);
    }

    let scriptContent;
    try {
      if (script.src) {
        const cachedScript = caches.open('scripts').match(script.src);
        if (!cachedScript) {
          const response = await fetch(script.src);
          const blob = await response.blob();
          caches.open('scripts').put(script.src, blob);
          scriptContent = await blob.text();
        } else {
          scriptContent = await cachedScript.text();
        }
      } else {
        scriptContent = script.code;
      }
    } catch (error) {
      console.error(`Error fetching or parsing script: ${error}`);
      return '';
    }

    const scriptElem = document.createElement('script');
    scriptElem.src = script.src || 'javascript:void(0)';
    scriptElem.type = script.type;
    scriptElem.key = script.key;
    scriptElem.textContent = scriptContent;
    scriptElems.push(scriptElem);
  });

  return scriptElems.map((script) => script.outerHTML).join('');
}
