<?php
function updateClinicStatus($clinicId, $newStatus, $ipAddress) {
    // Configuration variables
    $dbHost = 'localhost';
    $dbName = 'clinics';
    $dbUsername = 'root';
    $dbPassword = 'password';
    $apiUrl = 'https://example.com/api/notify';
    $rateLimitPeriod = 60; // seconds
    $rateLimitCount = 5;

    // Establish database connection
    try {
        $dbConnection = new PDO("mysql:host=$dbHost;dbname=$dbName", $dbUsername, $dbPassword);
        $dbConnection->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
    } catch (PDOException $e) {
        error_log('Database connection failed: ' . $e->getMessage());
        return false;
    }

    // Update clinic status
    try {
        $stmt = $dbConnection->prepare("UPDATE clinics SET status = ?, lastModifiedIP = ?, lastModifiedDate = NOW() WHERE id = ?");
        $stmt->execute(array($newStatus, $ipAddress, $clinicId));
    } catch (PDOException $e) {
        error_log('Update query failed: ' . $e->getMessage());
        return false;
    }

    // Log update action
    try {
        $stmt = $dbConnection->prepare("INSERT INTO updates (clinicId, status, ipAddress, timestamp) VALUES (?, ?, ?, NOW())");
        $stmt->execute(array($clinicId, $newStatus, $ipAddress));
    } catch (PDOException $e) {
        error_log('Update log query failed: ' . $e->getMessage());
        return false;
    }

    // Check for rate limiting
    if (!isset($_SESSION['rateLimit'])) {
        $_SESSION['rateLimit'] = array();
    }
    if (!isset($_SESSION['rateLimit'][$ipAddress])) {
        $_SESSION['rateLimit'][$ipAddress] = 0;
    }
    if ($_SESSION['rateLimit'][$ipAddress] < $rateLimitCount) {
        $_SESSION['rateLimit'][$ipAddress]++;
    } else {
        // Rate limiting exceeded
        return false;
    }

    // Notify API service (only for "closed" or "emergency" status)
    if ($newStatus === 'closed' || $newStatus === 'emergency') {
        try {
            $ch = curl_init($apiUrl);
            curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
            curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode(array('clinicId' => $clinicId, 'status' => $newStatus)));
            $response = curl_exec($ch);
            if (curl_errno($ch)) {
                error_log('API service notification failed: ' . curl_error($ch));
            }
        } catch (Exception $e) {
            error_log('API service notification failed: ' . $e->getMessage());
        }
    }

    return true;
}
