```rust
use std::fs::{self, DirEntry};
use std::path::{Path, PathBuf};
use std::time::{Instant, Duration};
use std::process::Command;
use rustc_driver::{CrateBuilder, catch_with_error};
use log::{info, warn, error};

fn compile_directory(path: &Path) -> Result<(), Box<dyn std::error::Error>> {
    let start_time = Instant::now();

    // Install a custom logging hook
    log::set_logger(&Logger {}).max_level(log::Level::Info);

    let mut total_compile_time = Duration::from_secs(0);

    for entry in fs::read_dir(path)? {
        let entry = entry?;
        if let Ok(file_path) = entry.path().to_str().unwrap_or("") {
            if file_path.ends_with(".rs") || file_path.ends_with(".rlib") {
                info!("Compiling {}", file_path);

                // Measure peak memory usage
                let mem_usage = Command::new("pmap")
                    .arg("-x")
                    .output()
                    .expect("Failed to measure memory usage");

                let crate_builder = CrateBuilder::new();
                let result = catch_with_error(|| {
                    let output = crate_builder.compile_file(&file_path)?;
                    info!("Compilation of {} complete", file_path);
                    Ok(output)
                });

                match result {
                    Ok(_) => total_compile_time += start_time.elapsed(),
                    Err(err) => error!("Error compiling {}: {}", file_path, err),
                };
            }
        }
    }

    // Measure total compilation time
    info!("Total compilation time: {:?}", start_time.elapsed());

    // Upload summary to remote build server API

    Ok(())
}

struct Logger {}
impl log::Log for Logger {
    fn enabled(&self, _metadata: &log::Metadata) -> bool {
        true
    }

    fn log(&self, record: &log::Record) {
        match record.level() {
            log::Level::Info => info!("{}", record.args()),
            log::Level::Warn => warn!("{}", record.args()),
            log::Level::Error => error!("{}", record.args()),
            _ => {}
        }
    }
}
