```rust
use std::fs;
use std::path::{Path, PathBuf};
use std::process::exit;

fn create_directory(dir_name: &str) -> Result<PathBuf, Box<dyn std::error::Error>> {
    let dir_path = dirs_dir().join(dir_name);
    match fs::create_dir_all(&dir_path) {
        Ok(_) => Ok(dir_path),
        Err(err) if err.kind() == std::io::ErrorKind::AlreadyExists => {
            println!("Directory already exists: {}", &dir_path.display());
            Ok(dir_path)
        }
        Err(err) => {
            eprintln!("Failed to create directory: {}", &err);
            exit(1);
        }
    }
}

fn dirs_dir() -> PathBuf {
    dirs::home_dir().unwrap_or_else(|| std::env::current_dir().unwrap())
}

fn set_env_var(dir_path: &Path) -> Result<(), Box<dyn std::error::Error>> {
    match std::env::set_var("MY_DIR", dir_path.to_string_lossy()) {
        Ok(_) => Ok(()),
        Err(err) => {
            eprintln!("Failed to set environment variable: {}", &err);
            exit(1);
        }
    }
}

fn cleanup(dir_path: &Path) -> Result<(), Box<dyn std::error::Error>> {
    if let Some(entry) = fs::read_dir(dir_path)? {
        for entry in entry {
            let entry = entry?;
            if !entry.path().is_file() {
                fs::remove_dir(&entry.path())?;
            }
        }
    }
    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Create the directory and set the environment variable
    let dir_path = create_directory("my_directory")?;
    set_env_var(&dir_path)?;

    // Clean up old directories
    if let Some(old_dir) = dirs_dir().join("old_directory").try_into_path_buf() {
        cleanup(&old_dir)?;
    }

    Ok(())
}
