```rust
use std::fs;
use std::path::{Path, PathBuf};
use std::thread;
use std::sync::{Arc, Mutex};

use itertools::Itertools;

mod lexer;
mod parser;
mod ir_generator;

struct Configuration {
    optimize: bool,
}

impl Default for Configuration {
    fn default() -> Self {
        Self { optimize: false }
    }
}

fn generate_ir(config: &Configuration, dir_path: &Path) -> Result<(), String> {
    let config = Arc::new(Mutex::new(*config));
    let dir_path = dir_path.clone();

    thread::scope().for_each(|| {
        if let Err(e) = process_dir(dir_path.clone(), config.clone()) {
            eprintln!("Error processing {}: {}", dir_path.display(), e);
        }
    });

    Ok(())
}

fn process_dir(dir_path: PathBuf, config: Arc<Mutex<Configuration>>) -> Result<(), String> {
    if !dir_path.exists() || !dir_path.is_dir() {
        return Err("Invalid directory path".to_string());
    }

    let mut iter = dir_path.read_dir().unwrap();
    for entry in iter.filter_map(|e| e.ok()).filter(|e| e.path().extend_ext(".rs")) {
        let file_path = entry.path();
        match fs::read_to_string(file_path) {
            Ok(src) => {
                if let Err(e) = process_file(&src, config.clone()) {
                    return Err(format!("Error processing {}: {}", file_path.display(), e));
                }
            },
            Err(_) => {
                eprintln!("Invalid or unreadable file: {}", file_path.display());
                continue;
            }
        }
    }

    Ok(())
}

fn process_file(src: &str, config: Arc<Mutex<Configuration>>) -> Result<(), String> {
    let ast = parser::parse(src)?;
    let ir = ir_generator::generate_ir(&ast, &config.lock().unwrap().optimize);

    println!("Parsed AST:\n{:?}", ast);
    println!("Generated LLVM IR:\n{}", ir);

    Ok(())
}

fn main() {
    let config = Configuration::default();
    if let Err(e) = generate_ir(&config, Path::new(".")) {
        eprintln!("{}", e);
        std::process::exit(1);
    }
}
