#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* trimAndCapitalize(char* str, int sizeLimit, char** wordsToRemove) {
    if (str == NULL || sizeLimit <= 0 || wordsToRemove == NULL) {
        return NULL;
    }

    // Trim leading and trailing spaces
    while (*str != '\0' && isspace(*(str - 1))) {
        str++;
    }
    int len = strlen(str);
    while (len > 0 && isspace(str[len - 1])) {
        str[--len] = '\0';
    }

    // Trim specified words from the string
    for (int i = 0; wordsToRemove[i]; i++) {
        size_t wordLen = strlen(wordsToRemove[i]);
        if (strncmp(str, wordsToRemove[i], wordLen) == 0 && !strncasecmp(&str[wordLen], str, len - wordLen)) {
            memmove(str, &str[wordLen], len - wordLen + 1);
            len -= wordLen;
        }
    }

    // Check if the resulting string does not exceed the size limit
    if (len > sizeLimit) {
        return NULL;
    }

    // Capitalize the first letter of each word and return the modified string
    for (size_t i = 0; i < len; i++) {
        if (i == 0 || isspace(str[i - 1])) {
            str[i] = toupper(str[i]);
        }
    }

    char* result = (char*) malloc(len + 1);
    strcpy(result, str);
    return result;
}

