#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/sem.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define SEM_KEY 12345
#define MAX_SEMAPHORES 10

typedef struct {
    int value;
    char name[16];
} Semaphore;

Semaphore semaphores[MAX_SEMAPHORES];

int current_semaphores = 0;

void* semaphore_ptr = NULL;
sem_t* sem = NULL;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void create_semaphore(char *name, int value) {
    if (current_semaphores >= MAX_SEMAPHORES) {
        printf("Max number of semaphores reached.\n");
        return;
    }

    key_t key = ftok("semaphore_system", SEM_KEY);
    if ((sem = sem_open(key, O_CREAT | O_EXCL, 0600, value)) == SEM_FAILED) {
        printf("Error creating semaphore: %s\n", strerror(errno));
        return;
    }

    strcpy(semaphores[current_semaphores].name, name);
    semaphores[current_semaphores++].value = value;

    if (sem_unlink(key) != 0) {
        printf("Error unlinking semaphore: %s\n", strerror(errno));
    }

    sem_close(sem);
}

void delete_semaphore(char *name) {
    int i;
    for (i = 0; i < current_semaphores; i++) {
        if (strcmp(semaphores[i].name, name) == 0) {
            key_t key = ftok("semaphore_system", SEM_KEY);
            sem_close(sem);
            sem_unlink(key);
            memmove(&semaphores[i], &semaphores[i+1], sizeof(Semaphore) * (current_semaphores - i));
            current_semaphores--;
            return;
        }
    }

    printf("Semaphore not found.\n");
}

void increment_semaphore(char *name, int value) {
    if (value < 0) {
        printf("Semaphore value cannot be negative.\n");
        return;
    }

    int i;
    for (i = 0; i < current_semaphores; i++) {
        if (strcmp(semaphores[i].name, name) == 0) {
            sem_wait(sem);
            semaphores[i].value += value;
            sem_post(sem);
            return;
        }
    }

    printf("Semaphore not found.\n");
}

void decrement_semaphore(char *name, int value) {
    if (value < 0) {
        printf("Semaphore value cannot be negative.\n");
        return;
    }

    int i;
    for (i = 0; i < current_semaphores; i++) {
        if (strcmp(semaphores[i].name, name) == 0) {
            sem_wait(sem);
            if (semaphores[i].value - value < 0) {
                printf("Semaphore value is not enough.\n");
            } else {
                semaphores[i].value -= value;
            }
            sem_post(sem);
            return;
        }
    }

    printf("Semaphore not found.\n");
}

void log_semaphore_operation(char *name, int value, char* operation) {
    // Implement external logging mechanism here
}
