import hashlib
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives import hashes

def process_file(filename):
    try:
        with open(filename, 'r') as file:
            lines = file.readlines()
            sorted_lines = sorted(lines)
            last_line = sorted_lines[-1].strip()
            sequence_number = int(last_line.split()[-1])

            hash_functions = {}
            ciphers = {}

            for line in sorted_lines[:-1]:
                name = line.strip().split()[0]

                if name in hashlib.algorithms_genuine:
                    hash_functions[name] = (hashlib, getattr(hashlib, name))
                elif name in algorithms.names:
                    ciphers[name] = (Cipher, algorithms.get(name), modes.ECB())
                else:
                    continue

            for func, details in ((hash_functions, 'Hash'), (ciphers, 'Cipher')):
                for name, info in func.items():
                    print(f"{info[1]} {name} is available.")

    except FileNotFoundError:
        print("File not found.")
    except Exception as e:
        print(f"An error occurred: {e}")
