function renderScriptsFooter(scripts) {
    const maxConcurrentRequests = 3; // configurable limit
    let concurrentRequests = 0;
    let scriptQueue = [];
    let inlineScripts = [];

    function loadScript(script) {
        return new Promise((resolve, reject) => {
            if (script.src) {
                ++concurrentRequests;
                const xhr = new XMLHttpRequest();
                xhr.open('GET', script.src, true);
                xhr.onload = () => {
                    if (xhr.status === 200) {
                        resolve(xhr.responseText);
                    } else {
                        reject(`Failed to load script: ${script.src}`);
                    }
                    --concurrentRequests;
                };
                xhr.onerror = () => {
                    reject(`Error loading script: ${script.src}`);
                    --concurrentRequests;
                };
                xhr.timeout = 5000; // timeout after 5 seconds
                xhr.ontimeout = () => {
                    reject(`Timeout loading script: ${script.src}`);
                    --concurrentRequests;
                };
                xhr.send();
            } else {
                resolve(script.code);
            }
        });
    }

    function loadScripts() {
        return Promise.all(scriptQueue.map(loadScript)).then((results) => {
            let html = '';
            for (let i = 0; i < results.length; ++i) {
                const script = scripts[i];
                if (script.src) {
                    html += `<script type="text/javascript" key="${script.key}" ${script.src ? '' : `innerHTML="${results[i]}"`}></script>`;
                } else {
                    inlineScripts.push(results[i]);
                }
            }
            return html;
        });
    }

    function executeInlineScripts() {
        if (inlineScripts.length > 0) {
            let script = document.createElement('script');
            script.text = inlineScripts.join('');
            document.body.appendChild(script);
        }
    }

    return loadScripts().then(() => {
        // execute all scripts, including inline ones
        executeInlineScripts();
    }).catch((error) => {
        console.error(error);
        // provide a fallback mechanism for external scripts that fail to load
        alert(`Failed to load script: ${error}`);
    });
}
