    [Serializable]
    public class ConfigSettings
    {
        public int TileSize { get; set; }
        public int WorldWidth { get; set; }
        public int WorldHeight { get; set; }
        public float CameraSpeed { get; set; }
    }

    class Program
    {
        static void Main(string[] args)
        {
            ConfigSettings settings = LoadConfig();
            Console.WriteLine($"Tile size: {settings.TileSize}");
            Console.WriteLine($"World width: {settings.WorldWidth}");
            Console.WriteLine($"World height: {settings.WorldHeight}");
            Console.WriteLine($"Camera speed: {settings.CameraSpeed}");

            CreateDirAndSetEnv("NewDirectory");
        }

        static ConfigSettings LoadConfig()
        {
            XmlSerializer serializer = new XmlSerializer(typeof(ConfigSettings));
            using (FileStream stream = File.OpenRead("config.xml"))
            {
                return (ConfigSettings)serializer.Deserialize(stream);
            }
        }

        [DllImport("kernel32")]
        static extern IntPtr GetEnvironmentVariable(string lpValue);

        static void CreateDirAndSetEnv(string dirName)
        {
            string envVar = "MY_DIR";
            IntPtr ptr = GetEnvironmentVariable(envVar);
            if (ptr == IntPtr.Zero) // Env variable not set, create new directory and set it
            {
                string path = Path.Combine(Path.GetTempPath(), dirName);
                Directory.CreateDirectory(path);
                SetEnvironmentVariable(envVar, path);
            }
        }

        [DllImport("kernel32")]
        static extern bool SetEnvironmentVariable(string lpValue, string lpString);
    }
}
