import java.util.Arrays;
import java.util.concurrent.TimeUnit;

public class DisjointPairFinder {

    public static int findDisjointPairs(int[] arr) throws Exception {
        int n = arr.length;
        UnionFind uf = new UnionFind(n);

        long startTime = System.nanoTime();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (!uf.find(arr[i], arr[j])) {
                    System.out.println("Disjoint pair found: " + Arrays.toString(new int[]{arr[i], arr[j]}));
                    long endTime = System.nanoTime();
                    long duration = endTime - startTime;
                    System.out.println("Time taken to check this pair: " + TimeUnit.NANOSECONDS.toMillis(duration) + " milliseconds");
                }
            }
        }

        return uf.getComponentCount() - 1; // subtract 1 because the component count includes the original components
    }

    public static void main(String[] args) throws Exception {
        int[] arr = {1, 2, 3, 4, 5};
        int disjointPairs = findDisjointPairs(arr);
        System.out.println("Total number of disjoint pairs: " + disjointPairs);
    }
}

class UnionFind {
    private int[] parent;
    private int[] rank;

    public UnionFind(int n) {
        parent = new int[n];
        rank = new int[n];

        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public boolean find(int x, int y) {
        if (parent[x] == parent[y]) return true;

        if (rank[x] > rank[y]) {
            parent[y] = x;
        } else if (rank[x] < rank[y]) {
            parent[x] = y;
        } else {
            parent[x] = y;
            rank[y]++;
        }

        return false;
    }

    public int getComponentCount() {
        int count = 0;
        for (int i = 0; i < parent.length; i++) {
            if (parent[i] == i) count++;
        }
        return count;
    }
}
