int fetchWordList(const char* input, char** wordList, int* size);

// Function prototype for dynamically trimming and capitalizing a string
char* dynamicTrimAndCapitalize(const char* input) {
    // Fetch the word list from the external data source
    int numWords;
    char** words = NULL;
    if (fetchWordList(input, &words, &numWords)) {
        // Calculate the size limit based on the length of the fetched word list and average word length
        int sizeLimit = (numWords * 10) + strlen(input);

        // Initialize the result string
        char* result = NULL;
        if (asprintf(&result, "%s", input) == -1) {
            free(words);
            return NULL; // Failed to allocate memory for the result string
        }

        // Trim and capitalize each word in the input string
        int i;
        char* pos = result;
        for (i = 0; i < strlen(result); i++) {
            if (strncmp(result, words[i], strlen(words[i])) == 0) {
                if (strlen(pos) + 1 > sizeLimit) {
                    free(result);
                    return NULL; // Result string exceeds the adjusted size limit
                }
                strcat(pos, toupper(result[i]));
                pos = pos + strlen(pos);
            } else {
                if (pos != result && pos[0] != '\0' && strncmp(pos, words[i], strlen(words[i])) == 0) {
                    *pos = '\0';
                }
                strcpy(pos, result + i);
                pos += strlen(result) - i;
                i--;
            }
        }

        // Deallocate the memory for the word list
        int j;
        for (j = 0; j < numWords; j++) {
            free(words[j]);
        }
        free(words);

        return result;
    } else {
        return NULL; // Failed to fetch the word list
    }
}

