#include <semaphore.h>
#include <stdio.h>

int convert_jpeg_to_pdf(const char* input_file_name, const char* output_file_name) {
    sem_t* semaphore;
    int sem_val = 1;

    if (sem_open("/my_semaphore", O_CREAT | O_EXCL, S_IRUSR | S_IWUSR, sem_val) == -1) {
        return 1;
    }

    semaphore = sem_open("/my_semaphore", O_RDWR);
    if (!semaphore) {
        return 1;
    }

    int ret = sem_wait(semaphore);
    if (ret < 0) {
        return 1;
    }

    // Perform conversion here using a third-party tool
    system("third_party_tool input_file_name output_file_name");

    ret = sem_post(semaphore);

    if (ret < 0) {
        return 1;
    }

    sem_close(semaphore);
    sem_unlink("/my_semaphore");
    return 0;
}
