class Cache:
    def __init__(self):
        self.images = {}

    def get_image(self, image_id):
        if image_id in self.images:
            return self.images[image_id]
        else:
            return None

    def cache_image(self, image_id, image_data):
        self.images[image_id] = image_data

    def invalidate_image(self, image_id):
        if image_id in self.images:
            del self.images[image_id]

def get_or_download_image(image_id):
