  async function runTest(testFunction) {
    try {
      await testFunction();
    } catch (error) {
      console.error(`Test ${testFunction.name} failed: ${error}`);
    }
  }

  for (let i = 0; i < testLabels.length; i++) {
    const testLabel = testLabels[i];
    const testFunction = testFunctions[i];

    try {
      blueslip.reset();

      console.log(`Running test: ${testLabel}...`);
      await runTest(testFunction);
      console.log(`Test ${testLabel} passed.`);
    } catch (error) {
      console.error(`Error running test ${testLabel}: ${error}`);
    }
  }

  blueslip.reset();
}
