#include <semaphore.h>
#include <pthread.h>
#include <stdio.h>

int create_semaphore(const char *name, int initial_value) {
    sem_t *sem = sem_open(name, O_CREAT | O_EXCL, 0644, initial_value, NULL);
    if (sem == SEM_FAILED) {
        perror("sem_open");
        return -1;
    }
    return sem_id(sem);
}

int acquire_semaphore(int semaphore_id) {
    int ret = sem_wait(semaphore_id);
    if (ret == -1) {
        perror("sem_wait");
        return -1;
    }
    return 0;
}

int release_semaphore(int semaphore_id) {
    int ret = sem_post(semaphore_id);
    if (ret == -1) {
        perror("sem_post");
        return -1;
    }
    return 0;
}

void delete_semaphore(const char *name) {
    sem_unlink(name);
}
