#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define CAPACITY 10
#define NUM_PRODUCERS 5
#define NUM_CONSUMERS 3

sem_t empty, full;
int front = -1, rear = -1;
int queue[CAPACITY];
int stop_signal = 0;

void* producer(void* ptr);
void* consumer(void* ptr);

int main() {
    sem_init(&empty, 0, CAPACITY);
    sem_init(&full, 0, 0);

    pthread_t producers[NUM_PRODUCERS], consumers[NUM_CONSUMERS];

    for (int i = 0; i < NUM_PRODUCERS; i++) {
        pthread_create(&producers[i], NULL, producer, NULL);
    }
    for (int i = 0; i < NUM_CONSUMERS; i++) {
        pthread_create(&consumers[i], NULL, consumer, NULL);
    }

    while (!stop_signal) {
        sleep(1);
    }

    for (int i = 0; i < NUM_PRODUCERS; i++) {
        pthread_join(producers[i], NULL);
    }
    for (int i = 0; i < NUM_CONSUMERS; i++) {
        pthread_join(consumers[i], NULL);
    }

    sem_destroy(&empty);
    sem_destroy(&full);

    return 0;
}

void* producer(void* ptr) {
    int id = *(int*)ptr;
    printf("Producer %d started...\n", id);

    while (!stop_signal) {
        sem_wait(&empty);
        // enqueue operation
        printf("Producer %d: Enqueueing data...\n", id);

        rear = (rear + 1) % CAPACITY;
        queue[rear] = id;

        sem_post(&full);
    }

    return NULL;
}

void* consumer(void* ptr) {
    int id = *(int*)ptr;
    printf("Consumer %d started...\n", id);

    while (!stop_signal) {
        sem_wait(&full);
        // dequeue operation
        printf("Consumer %d: Dequeuing data...\n", id);

        if (front == -1 || front == rear) {
            stop_signal = 1;
            return NULL;
        }

        int item = queue[front];
        front = (front + 1) % CAPACITY;

        sem_post(&empty);
    }

    return NULL;
}
