#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

// Define structure type
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the mock database system
#define DB_SIZE 100000
NFAPI_CRC_INDICATION_PDU_T* db[DB_SIZE];
int db_size = 0;
pthread_mutex_t db_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void create_crc_indication_pdu_list(int N) {
    int i, flag;
    srand(time(NULL)); // seed for random number generation

    pthread_mutex_lock(&db_lock); // lock the database

    printf("Creating and populating CRC indication PDU list...\n");

    for (i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!pdu) {
            fprintf(stderr, "Error: Insufficient memory to create CRC indication PDU.\n");
            return;
        }

        // Generate random RNTI
        pdu->rnti = rand() % 1000;

        // Generate unique CRC flag for the current structure
        flag = 0;
        while (flag < 256) {
            flag = rand() % 256;

            // Check if the generated flag is already in use
            bool flag_in_use = false;
            pthread_mutex_unlock(&db_lock);
            for (int j = 0; j < db_size; j++) {
                if (db[j]->crc_ind_rel8.crcflag == flag) {
                    flag_in_use = true;
                    break;
                }
            }
            pthread_mutex_lock(&db_lock);

            // If the flag is in use, generate a new one
            if (flag_in_use) continue;

            pdu->crc_ind_rel8.crcflag = flag;
            break;
        }

        // Assign random RX_UE_INFORMATION_TAG to the structure
        pdu->rx_ue_info.tag = rand() % 1000;

        // Add the newly created PDU to the database
        pthread_mutex_lock(&db_lock);
        db[db_size++] = pdu;
    }

    pthread_mutex_unlock(&db_lock);

    printf("List creation and population complete.\n");
}

// Function to log the creation and population process
void log_crc_indication_pdu_list(int N) {
    printf("CRC indication PDU list: %d structures created and populated.\n", N);
}
