# Function to update an existing resource using HTTP PUT method
def update_resource(resource_api):
    @resource_api.route('/resources/<int:resource_id>', methods=['PUT'])
    def put_resource():
        try:
            resource_id = int(request.args.get('id'))
            data = request.get_json()
            # Logic to update the resource with provided data goes here
            return jsonify({'message': 'Resource updated successfully'}), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

# Function to calculate MD5 hash of a file given its path
def calculate_md5_hash(file_api):
    @file_api.route('/files/<path:file_path>', methods=['GET'])
    def get_md5_hash():
        try:
            file_path = request.args.get('path')
            if not os.path.exists(file_path):
                return jsonify({'error': 'File not found'}), 404
            md5_hash = hashlib.md5()
            with open(file_path, 'rb') as file:
                chunk = file.read(4096)
                while chunk:
                    md5_hash.update(chunk)
                    chunk = file.read(4096)
            return jsonify({'md5': md5_hash.hexdigest()}), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

