import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;

import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.Random;
import java.util.concurrent.TimeUnit;

public class JSONParser {
    private Map<String, Factory> factoryRegistry = new HashMap<>();
    private ObjectMapper mapper = new ObjectMapper();

    public JSONParser() {
        mapper.enable(SerializationFeature.INDENTATION);
    }

    public void addFactoryFunction(String id, Factory factory) {
        factoryRegistry.put(id, factory);
    }

    public Object fromJSON(String jsonString) throws IOException {
        JsonNode jsonNode = mapper.readTree(jsonString);
        return mapper.treeToValue(jsonNode, Object.class);
    }

    public String toJSON(Object object) throws IOException {
        return mapper.writeValueAsString(object);
    }

    public void startService() {
        new Thread(() -> {
            try {
                while (true) {
                    // Start service
                    System.out.println("Service started");

                    // Random delay before stopping the service
                    long delay = new Random().nextInt(10000) + 1;
                    TimeUnit.MILLISECONDS.sleep(delay);

                    // Stop the service
                    System.out.println("Service stopped");
                    // Send message to messaging system
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }).start();
    }

    public interface Factory<T> {
        T createObject(String jsonString);
    }
}
