#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <md5.h>

struct record {
    int key;
};

char* get_max_value(const char *range) {
    // parse the range and return the maximum value
    char *end = (char *)NULL;
    int max = (int)strtol(range, &end, 10);
    if (*end != '-' || *end != '\0') {
        printf("Invalid range format\n");
        exit(1);
    }
    return NULL;
}

struct record* generate_records(const char *range, const char *keys, int *key_count) {
    // parse the range to determine the maximum value
    int max = get_max_value(range);

    // allocate memory for and initialize two arrays
    long *offsets = (long *)malloc((max - 1) * sizeof(long));
    int *keys_array = (int *)malloc(strlen(keys) + 1);
    strcpy(keys_array, keys);
    char *token = strtok(keys_array, ",");
    int key_index = 0;
    while (token != NULL) {
        *(keys_array + ++key_index) = atoi(token);
        token = strtok(NULL, ",");
    }
    *key_count = key_index;

    // allocate memory for and initialize an array of 'record' structures
    struct record *records = (struct record *)malloc((max - 1) * sizeof(struct record));
    for (int i = 0; i < max - 1; i++) {
        records[i].key = rand() % (max - 1);
    }

    return records;
}

char* get_md5_hash(const char *keys, int key_count) {
    // calculate and return the MD5 hash of the comma-separated list of keys
    unsigned char result[16];
    MD5_CTX md5;
    MD5_Init(&md5);
    const char *end = keys + strlen(keys);
    for (int i = 0; i < key_count; i++) {
        MD5_Update(&md5, &keys[i], end - (keys + i));
    }
    MD5_Final(result, &md5);

    // convert the result to hexadecimal and return it
    char *hash = (char *)malloc(33);
    for (int i = 0; i < 16; i++) {
        sprintf(hash + i * 2, "%02x", result[i]);
    }
    hash[32] = '\0';
    return hash;
}

