from functools import lru_cache
from typing import List, Tuple, Dict

async def copy_data_chunks(chunks: List[Tuple[str, asyncio.Future]], 
                          initial_dict: Dict[str, bytes], 
                          aggregation_callback: callable) -> Dict[str, bytes]:
    @lru_cache(maxsize=None)
    async def fetch_chunk(source_id: str, chunk_future: asyncio.Future):
        try:
            data = await chunk_future
            if not isinstance(data, bytes):
                raise ValueError(f"Invalid data format for {source_id}")
            return source_id, data
        except Exception as e:
            print(f"Error fetching data from {source_id}: {str(e)}")
            # Retry with exponential backoff
            import time
            for _ in range(3):
                await asyncio.sleep(2 ** (_ + 1))
                try:
                    return await fetch_chunk(source_id, chunk_future)
                except Exception as e:
                    print(f"Error fetching data from {source_id} after retry: {str(e)}")
                    raise

    @lru_cache(maxsize=None)
    async def prioritize_chunks(chunks: List[Tuple[str, asyncio.Future]]) -> Dict[str, bytes]:
        prioritized_chunks = {}
        for source_id, chunk_future in chunks:
            # Prioritize based on source identifier or metadata
            if priority_function(source_id):
                prioritized_chunks[source_id] = await fetch_chunk(source_id, chunk_future)
            else:
                prioritized_chunks[source_id] = await fetch_chunk(source_id, chunk_future)

        return prioritized_chunks

    @lru_cache(maxsize=None)
    async def aggregate_data(chunks: Dict[str, bytes]) -> Dict[str, bytes]:
        aggregated_dict = {}
        for source_id, data in chunks.items():
            if not initial_dict.get(source_id):
                initial_dict[source_id] = b''

            aggregated_dict[source_id] = initial_dict[source_id] + data
        return aggregated_dict

    prioritized_chunks = await prioritize_chunks(chunks)
    return await aggregation_callback(prioritized_chunks)

