#include <string.h>

#define LOG_FILE "/path/to/error.log"
#define MAX_LOG_MESSAGE_LENGTH 1024

typedef enum { INFO, WARNING, ERROR } log_severity;

FILE *open_log_file();
void write_log_entry(FILE *, const char *, int);
void close_log_file(FILE *);

int logCondition(const char *condition, int severity, const char *format, ...)
{
    if (!condition) return 0; // Do not log if condition is false

    FILE *log_file = open_log_file();

    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    va_list args;
    va_start(args, format);
    char message[MAX_LOG_MESSAGE_LENGTH];
    vsnprintf(message, MAX_LOG_MESSAGE_LENGTH, format, args);

    write_log_entry(log_file, message, severity);

    close_log_file(log_file);

    va_end(args);

    return 0;
}

FILE *open_log_file()
{
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL)
    {
        perror("Error opening log file");
        return NULL;
    }
    return log_file;
}

void write_log_entry(FILE *file, const char *message, int severity)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);

    fprintf(file, "[%04d-%02d-%02d %02d:%02d:%02d] ", t->tm_year + 1900, t->tm_mon, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec);

    switch (severity)
    {
        case LOG_ERROR:
            fprintf(file, "ERROR: ");
            break;
        case LOG_WARNING:
            fprintf(file, "WARNING: ");
            break;
        case LOG_INFO:
            fprintf(file, "INFO: ");
            break;
    }

    fprintf(file, "%s\n", message);
}

void close_log_file(FILE *file)
{
    if (fclose(file) != 0)
    {
        perror("Error closing log file");
    }
}
