using System;
using System.Security.Cryptography;
using System.Text;

public class HashGenerator
{
    private readonly ILogger _logger;

    public HashGenerator(ILogger logger)
    {
        _logger = logger;
    }

    public string GenerateMd5(string input)
    {
        return GenerateHash(input, "MD5");
    }

    public string GenerateSha1(string input)
    {
        return GenerateHash(input, "SHA1");
    }

    public string GenerateSha256(string input)
    {
        return GenerateHash(input, "SHA256");
    }

    public string GenerateMd5(byte[] input)
    {
        return GenerateHash(input, "MD5");
    }

    public string GenerateSha1(byte[] input)
    {
        return GenerateHash(input, "SHA1");
    }

    public string GenerateSha256(byte[] input)
    {
        return GenerateHash(input, "SHA256");
    }

    private string GenerateHash(string input, string algorithm)
    {
        using var hashAlgorithm = GetHashAlgorithm(algorithm);
        var inputBytes = Encoding.UTF8.GetBytes(input);
        var hashValue = HashValue(hashAlgorithm, inputBytes);
        return BitConverter.ToString(hashValue).Replace("-", "").ToLower();
    }

    private string GenerateHash(byte[] input, string algorithm)
    {
        using var hashAlgorithm = GetHashAlgorithm(algorithm);
        var hashValue = HashValue(hashAlgorithm, input);
        return BitConverter.ToString(hashValue).Replace("-", "").ToLower();
    }

    private HashAlgorithm GetHashAlgorithm(string algorithm)
    {
        switch (algorithm.ToLower())
        {
            case "md5":
                return MD5.Create();
            case "sha1":
                return SHA1.Create();
            case "sha256":
                return SHA256.Create();
            default:
                throw new ArgumentException("Invalid hash algorithm", nameof(algorithm));
        }
    }

    private byte[] HashValue(HashAlgorithm algorithm, byte[] input)
    {
        using var hasher = algorithm;
        var hashBytes = hasher.ComputeHash(input);
        return hashBytes;
    }
}

public interface ILogger
{
    void LogError(string message);
    void LogWarning(string message);
}
