void create_directory_set_env_var() {
    DIR *dir;
    struct dirent *ent;
    char path[1024];

    // Create directory
    dir = opendir("path_to_directory");
    if (dir != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
                continue;
            sprintf(path, "path_to_directory/%s", ent->d_name);
            unlink(path);
        }
        closedir(dir);

        // Create new directory
        mkdir("path_to_directory/new_dir");

    } else {
        perror ("Error opening directory");
    }

    // Set environment variable
    setenv("PATH_TO_DIRECTORY/new_dir", "path_to_directory/new_dir");

    // Add OpenSSL primitives to library
    for (int i = 0; i < MAX_PRIMITIVES; i++) {
        const char* primitive_name = get_primitive_names(i);
        if (!primitive_name) {
            continue;
        }
        int error;
        // Check availability of each cipher and digest before adding them
        EVP_add_primitive(primitive_name, &error);
        if (error) {
            fprintf(stderr, "Error: Primitive %s not available\n", primitive_name);
        } else {
            // Add primitives to library and verify successful addition
            // ...
        }
    }

    // Clean up unused or redundant cryptographic primitives
    EVP_cleanup();

    // Handle missing dependencies gracefully
    if (EVP_get_builtin_support() == 0) {
        fprintf(stderr, "Error: Missing OpenSSL dependency\n");
    }
}
