#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *key;
    void *value;
} ResourceBundleItem;

int loadResourceBundle(const char *path) {
    FILE *file = fopen(path, "r");
    if (!file) {
        fprintf(stderr, "Error: Unable to open file '%s'.\n", path);
        return -1; // File not found
    }

    int itemCount = 0;
    ResourceBundleItem *bundleItems = NULL;

    while (1) {
        char line[256];
        if (!fgets(line, sizeof(line), file)) break;

        char *keyEnd = strchr(line, '=');
        if (!keyEnd || keyEnd - line > sizeof(line) - 2) {
            fprintf(stderr, "Error: Invalid data format in file '%s'.\n", path);
            fclose(file);
            return -2; // Invalid data format
        }

        *keyEnd = '\0';
        char *key = line;
        char *valueStart = keyEnd + 1;

        if (strcmp(valueStart, "\"") == 0) {
            valueStart++;
            while (*valueStart && *valueStart != '\"') {
                valueStart++;
            }
            *valueStart = '\0';
        } else if (strspn(valueStart, "0123456789.-") > 0 || strspn(valueStart, "\"'") == 0) {
            // Assume it's a float
            double val;
            sscanf(valueStart, "%lf", &val);
            valueStart = (void *)(&val);
        } else {
            valueStart++;
            while (*valueStart && *valueStart != '\"') {
                valueStart++;
            }
            *valueStart = '\0';
        }

        bundleItems = realloc(bundleItems, (itemCount + 1) * sizeof(*bundleItems));
        if (!bundleItems) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            fclose(file);
            return -3; // Memory allocation failure
        }

        bundleItems[itemCount].key = strdup(line);
        bundleItems[itemCount].value = valueStart;

        itemCount++;
    }

    fclose(file);

    int count;
    if (bundleItems) {
        count = itemCount;
        free(bundleItems);
    } else {
        count = -1; // Memory allocation failure
    }

    return count;
}
