using System;
using System.Xml.XPath;
using System.IO;
using System.Collections.Generic;

public class XmlParser
{
    private readonly CacheStore _cache;
    private readonly ConfigLoader _configLoader;

    public XmlParser(CacheStore cache, ConfigLoader configLoader)
    {
        _cache = cache;
        _configLoader = configLoader;
    }

    public XElement GetElement(string xpathQuery)
    {
        string xmlDocPath = _configLoader.LoadConfig();
        XPathDocument doc;
        if (_cache.TryGetValue(xmlDocPath, out doc))
        {
            try
            {
                XPathNavigator nav = doc.CreateNavigator();
                XPathExpression expr = nav.Compile(xpathQuery);
                XPathNodeIterator iterator = nav.Select(expr);
                XElement element = null;
                while (iterator.MoveNext())
                {
                    element = new XElement(iterator.Current.Name);
                    return element;
                }
            }
            catch (XPathException ex)
            {
                throw new Exception("Invalid XPath query: " + ex.Message);
            }
        }
        else
        {
            doc = new XPathDocument(xmlDocPath);
            _cache.Store(xmlDocPath, doc);
        }
    }
}

public class CacheStore
{
    private readonly Dictionary<string, object> _cache;

    public CacheStore()
    {
        _cache = new Dictionary<string, object>();
    }

    public void Store(string key, object value)
    {
        _cache.Add(key, value);
    }

    public bool TryGetValue(string key, out object value)
    {
        return _cache.TryGetValue(key, out value);
    }
}

public class ConfigLoader
{
    private readonly string _configPath;

    public ConfigLoader(string configPath)
    {
        _configPath = configPath;
    }

    public string LoadConfig()
    {
        try
        {
            return File.ReadAllText(_configPath);
        }
        catch (FileNotFoundException ex)
        {
            throw new Exception("Configuration file not found: " + ex.Message);
        }
        catch (Exception ex)
        {
            throw new Exception("Error loading configuration file: " + ex.Message);
        }
    }
}
