```java
import java.util.Arrays;

class UnionFindDisjointPairs {
    private DisjointSet unionFind;
    private int[] originalArray;

    public UnionFindDisjointPairs(int[] array) {
        if (array == null || array.length == 0) {
            throw new NullPointerException("Input array is empty or null");
        }
        originalArray = Arrays.copyOf(array, array.length);
        unionFind = new DisjointSet();
        for (int i : array) {
            if (!isValidElement(i)) {
                throw new RuntimeException("Invalid element in the input array");
            }
            unionFind.makeSet(i);
        }
    }

    public void addNewElement(int element) {
        if (!isValidElement(element)) {
            throw new RuntimeException("Invalid element to be added");
        }
        unionFind.makeSet(element);
    }

    public int countDisjointPairs() {
        int disjointCount = 0;
        for (int i = 0; i < originalArray.length; i++) {
            for (int j = i + 1; j < originalArray.length; j++) {
                if (!unionFind.find(originalArray[i]).equals(unionFind.find(originalArray[j]))) {
                    disjointCount++;
                }
            }
        }
        return disjointCount;
    }

    private boolean isValidElement(int element) {
        for (int i : originalArray) {
            if (i == element) {
                return true;
            }
        }
        return false;
    }
}

class DisjointSet {
    private int[] parent;
    private int[] rank;

    public DisjointSet() {
        parent = new int[0];
        rank = new int[0];
    }

    public void makeSet(int element) {
        if (parent.length == 0) {
            parent = new int[]{element};
            rank = new int[]{1};
            return;
        }
        int[] newParent = Arrays.copyOf(parent, parent.length + 1);
        int[] newRank = Arrays.copyOf(rank, rank.length + 1);
        newParent[newParent.length - 1] = element;
        newRank[newRank.length - 1] = 1;
        parent = newParent;
        rank = newRank;
    }

    public String find(int element) {
        if (parent.length == 0 || element < 0 || element >= parent.length) {
            return "Invalid element";
        }
        if (parent[element] != element) {
            parent[findHelper(element)] = find(parent[element]);
            pathCompression(element);
        }
        return String.valueOf(element);
    }

    private int findHelper(int element) {
        for (int i = 0; i < parent.length; i++) {
            if (parent[i] == element) {
                return i;
            }
        }
        return -1;
    }

    private void pathCompression(int element) {
        while (element != parent[element]) {
            parent[findHelper(element)] = parent[parent[findHelper(element)]];
            element = parent[findHelper(element)];
        }
    }

    public int union(int x, int y) {
        if (x < 0 || x >= parent.length || y < 0 || y >= parent.length) {
            return -1;
        }
        int rootX = find(x);
        int rootY = find(y);
        if (rootX == rootY) {
            return -1; // Already disjoint
        }
        if (rank[rootX] > rank[rootY]) {
            parent[findHelper(rootY)] = x;
            pathCompression(x);
        } else if (rank[rootX] < rank[rootY]) {
            parent[findHelper(rootX)] = y;
            pathCompression(y);
        } else {
            parent[findHelper(rootY)] = x;
            rank[rootX]++;
            pathCompression(x);
        }
        return 0; // Successfully unionized
    }
}
