class ImageConverter {
public:
    enum ConversionStatus { SUCCESS, FAILURE };

    ImageConverter(int quality = 75) : quality(quality), logger(nullptr) {}

    void setLogger(std::function<void(const std::string&)> loggerFunc) {
        this->logger = loggerFunc;
    }

    ConversionStatus convertAndSave(const std::string& inputPath, const std::string& outputPath, const std::string& format) {
        // Convert and save the image using ImageMagick
        // Handle errors and return status accordingly
        if (/*conversion failed*/) {
            return FAILURE;
        }
        return SUCCESS;
    }

    ConversionStatus batchConvertAndSave(const std::vector<std::tuple<std::string, std::string, std::string>>& conversions) {
        int threads = 4; // Default number of threads for parallel conversion
        if (/*numCoresAvailable*/) {
            threads = /*numCoresAvailable*/;
        }

        std::vector<std::thread> threadPool(threads);

        for (int i = 0; i < conversions.size(); i += threads) {
            int start = i;
            int end = std::min(i + threads, conversions.size());

            threadPool[i % threads] = std::thread([this, &conversions, start, end]() {
                for (auto it = std::make_move_iterator(conversions.begin() + start); it != std::make_move_iterator(conversions.begin() + end); ++it) {
                    const auto& [inputPath, outputPath, format] = *it;
                    convertAndSave(inputPath, outputPath, format);
                }
            });
        }

        for (auto& thread : threadPool) {
            thread.join();
        }

        return SUCCESS;
    }

private:
    int quality;
    std::function<void(const std::string&)> logger;

    void logConversionStatus(const std::string& inputPath, const std::string& outputPath, ConversionStatus status) {
        if (logger) {
            // Log the conversion status and details
            logger(std::to_string(status) + ": Converted " + inputPath + " to " + outputPath);
        }
    }
};
