import java.io.IOException;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingDeque;

public class RemoteConnectionHandler {
    private final Selector selector;
    private final List<ServerSocketChannel> channels;
    private final BlockingQueue<Runnable> messageQueue;
    private final KafkaProducer kafkaProducer;

    public RemoteConnectionHandler(int port) throws IOException {
        this.channels = new ArrayList<>();
        this.selector = Selector.open();
        ServerSocketChannel channel = ServerSocketChannel.open();
        channel.bind(new java.net.InetSocketAddress(port));
        channel.configureBlocking(false);
        channel.register(selector, SelectionKey.OP_ACCEPT);
        channels.add(channel);

        this.messageQueue = new LinkedBlockingDeque<>();
        this.kafkaProducer = new KafkaProducer("localhost:9092");
    }

    public void start() {
        while (true) {
            try {
                selector.select();
                for (SelectionKey key : selector.selectedKeys()) {
                    if (key.isAcceptable()) {
                        ServerSocketChannel channel = (ServerSocketChannel) key.channel();
                        SocketChannel socketChannel = channel.accept();
                        socketChannel.configureBlocking(false);
                        socketChannel.register(selector, SelectionKey.OP_READ);

                        // Handle connection state change
                        logger.info("New connection established from {}:{}", socketChannel.getRemoteAddress(), socketChannel.getLocalAddress());

                        // Asynchronously send messages to the message queue system
                        new SendMessageTask(socketChannel).submit(messageQueue);
                    } else if (key.isReadable()) {
                        SocketChannel socketChannel = (SocketChannel) key.channel();
                        try {
                            int bytesRead = socketChannel.read(buffer);
                            if (bytesRead == -1) {
                                // Handle connection timeout or error
                                logger.info("Connection closed from {}:{}", socketChannel.getRemoteAddress(), socketChannel.getLocalAddress());
                            } else {
                                // Process incoming data
                                processIncomingData(socketChannel, buffer);
                            }
                        } catch (IOException e) {
                            logger.error("Error processing incoming data", e);
                            // Handle connection timeout or error
                            socketChannel.close();
                            selector.keys().remove(key);
                        }
                    }
                }
            } catch (IOException e) {
                logger.error("Error handling connections", e);
            }
        }
    }

    private void processIncomingData(SocketChannel socketChannel, ByteBuffer buffer) {
        // Implement data processing logic here
    }

    private class SendMessageTask implements Runnable {
        private final SocketChannel socketChannel;
        public SendMessageTask(SocketChannel socketChannel) { this.socketChannel = socketChannel; }

        @Override
        public void run() {
            try {
                kafkaProducer.send(socketChannel.getLocalAddress(), "Message sent from client");
            } catch (Exception e) {
                logger.error("Error sending message", e);
            }
        }
    }
}
