function asyncArrayReduce(array, initial, callback) {
  const concurrencyLimit = 5; // adjust as needed
  let semaphore = 0;
  let reducedValue = initial;

  (async function() {
    for await (const element of array) {
      if (semaphore >= concurrencyLimit) {
        await new Promise(resolve => setTimeout(() => resolve(), 100)); // wait for previous operations to finish
      }
      try {
        const result = await callback(reducedValue, element);
        reducedValue = result;
      } catch (error) {
        return { error: 'Callback returned an error' };
      } finally {
        semaphore++;
      }
    }
    return reducedValue;
  })().then(result => result).catch(error => ({ error }));
}
