function updateUserPassword(userId, password) {
  // Validate password object properties
  if (!password.password || !password.strengthValidation || !password.key) {
    return 'Error: Password object missing required properties';
  }

  // Validate password strength
  const strengthCheck = validatePasswordStrength(password);
  if (!strengthCheck.valid) {
    return `Error: Password does not meet strength criteria. ${strengthCheck.message}`;
  }

  try {
    // Update user's password in database using DAO class
    const dao = new DAO();
    const result = dao.updateUserPassword(userId, password.password, password.key);
    if (!result) {
      throw new Error('Error updating user password');
    }
    return 'Password updated successfully';
  } catch (error) {
    return `Error: ${error.message}`;
  }
}

// Helper function for password strength validation
function validatePasswordStrength(password) {
  const minLength = 8;
  const hasUpper = /(?=.*[A-Z])/;
  const hasLower = /(?=.*[a-z])/;
  const hasNumber = /(?=.*\d)/;

  if (password.password.length < minLength) {
    return { valid: false, message: `Password must be at least ${minLength} characters long` };
  }

  if (!hasUpper.test(password.password)) {
    return { valid: false, message: 'Password must contain at least one uppercase letter' };
  }

  if (!hasLower.test(password.password)) {
    return { valid: false, message: 'Password must contain at least one lowercase letter' };
  }

  if (!hasNumber.test(password.password)) {
    return { valid: false, message: 'Password must contain at least one number' };
  }

  return { valid: true };
}

