<?php
function handleUserRequest() {
    $request = $_POST;

    if (!isset($request['sub_action']) || !in_array($request['sub_action'], ['create', 'update'])) {
        return json_encode(['status' => 'error', 'message' => 'Invalid sub-action']);
    }

    switch ($request['sub_action']) {
        case 'create':
            if (!validateEmailUnique()) {
                return json_encode(['status' => 'error', 'message' => 'Email already in use']);
            }
            if (!validatePassword($request['password'], $request['confirm_password'])) {
                return json_encode(['status' => 'error', 'message' => 'Invalid password']);
            }
            break;
        case 'update':
            if (!isset($request['id'])) {
                return json_encode(['status' => 'error', 'message' => 'ID is required for update']);
            }
            if (isset($request['password']) && !validatePassword($request['password'], $request['confirm_password'])) {
                return json_encode(['status' => 'error', 'message' => 'Invalid password']);
            }
            break;
        case 'delete':
            if (!isset($request['id'])) {
                return json_encode(['status' => 'error', 'message' => 'ID is required for delete']);
            }
            break;
    }

    try {
        $db = new PDO('mysql:host=localhost;dbname=database', 'user', 'password');
        $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        if ($request['sub_action'] == 'create') {
            $stmt = $db->prepare("INSERT INTO users (name, email, password) VALUES (:name, :email, :password)");
            $stmt->execute([':name' => $request['name'], ':email' => $request['email'], ':password' => password_hash($request['password'], PASSWORD_BCRYPT)]);
        } elseif ($request['sub_action'] == 'update') {
            if (isset($request['password'])) {
                $stmt = $db->prepare("UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id");
                $stmt->execute([':name' => $request['name'], ':email' => $request['email'], ':password' => password_hash($request['password'], PASSWORD_BCRYPT), ':id' => $request['id']]);
            } else {
                $stmt = $db->prepare("UPDATE users SET name = :name, email = :email WHERE id = :id");
                $stmt->execute([':name' => $request['name'], ':email' => $request['email'], ':id' => $request['id']]);
            }
        } elseif ($request['sub_action'] == 'delete') {
            $stmt = $db->prepare("DELETE FROM users WHERE id = :id");
            $stmt->execute([':id' => $request['id']]);
        }

        return json_encode(['status' => 'success', 'message' => 'User created, updated or deleted successfully', 'data' => ['id' => $request['id'], 'name' => $request['name'], 'email' => $request['email']]]);
    } catch (PDOException $e) {
        return json_encode(['status' => 'error', 'message' => 'Database error: ' . $e->getMessage()]);
    }

    function validateEmailUnique() {
        $stmt = $db->prepare("SELECT 1 FROM users WHERE email = :email");
        $stmt->execute([':email' => $request['email']]);
