use std::fs;
use std::path::{Path, PathBuf};
use reqwest;

const CONFIG_SERVICE_URL: &str = "https://config-service.example.com";
const DEFAULT_CONFIG_DIR_NAME: &str = "my_app_config";

async fn get_config_dir_path() -> Result<PathBuf, Box<dyn std::error::Error>> {
    let client = reqwest::Client::new();
    let response = client.get(CONFIG_SERVICE_URL).send().await?;
    if !response.status().is_success() {
        return Err(format!("Failed to retrieve config directory path: {}", response.status()).into());
    }
    let config_dir_path: String = response.text().await?.trim_matches('\n').to_string();
    Ok(Path::new(&config_dir_path).to_path_buf())
}

async fn create_local_config_dir(path: &Path) -> Result<(), Box<dyn std::error::Error>> {
    if !path.exists() {
        fs::create_dir_all(path)?;
    }
    Ok(())
}

fn main() {
    let config_dir_path = get_config_dir_path().await;
    match config_dir_path {
        Ok(dir_path) => {
            println!("Using existing config directory: {}", dir_path.display());
            // Use the retrieved path for your application's configuration
        }
        Err(err) => {
            eprintln!("Error getting config directory path: {:?}", err);
            let local_config_dir = Path::new(DEFAULT_CONFIG_DIR_NAME).to_path_buf();
            create_local_config_dir(&local_config_dir).await;
            println!("Created new local config directory: {}", local_config_dir.display());
            // Use the created local directory for your application's configuration
        }
    }
}
