import java.util.*;

public class PacketProcessor {
    public static Pair<Integer, Long> processPackets(Packet[] packets) {
        // Initialize sliding window metrics
        int filteredCount = 0;
        long totalPacketSize = 0;
        int maxPacketSize = 0;
        long maxPacketId = 0;

        // Initialize sliding window of recent packets
        PriorityQueue<Packet> slidingWindow = new PriorityQueue<>();
        for (int i = 0; i < 100; i++) {
            slidingWindow.add(new Packet(0, "0.0.0.0", 0, System.currentTimeMillis()));
        }

        // Process each packet
        for (Packet packet : packets) {
            if (packet.getSize() > 1024 || !isValidSourceIP(packet.getSource()) || !isValidDestinationPort(packet.getPort())) {
                filteredCount++;
                continue;
            }

            // Update sliding window metrics
            totalPacketSize += packet.getSize();
            maxPacketSize = Math.max(maxPacketSize, packet.getSize());
            if (packet.getId() > maxPacketId) {
                maxPacketId = packet.getId();
            }

            // Add packet to sliding window and trim it to the last 100 packets
            slidingWindow.poll();
            slidingWindow.add(packet);

            // Check for potential network latency issues
            if (slidingWindow.size() > 100) {
                System.out.println("Packet processing delayed due to high latency!");
            }
        }

        return new Pair<>(maxPacketSize, maxPacketId);
    }

    private static boolean isValidSourceIP(String sourceIP) {
        // Implement IP validation logic here
        return true;
    }

    private static boolean isValidDestinationPort(int port) {
        // Implement port validation logic here
        return true;
    }
}

class Packet implements Comparable<Packet> {
    int size;
    String sourceIP;
    int port;
    long id;

    public Packet(int size, String sourceIP, int port, long id) {
        this.size = size;
        this.sourceIP = sourceIP;
        this.port = port;
        this.id = id;
    }

    public int getSize() {
        return size;
    }

    public String getSource() {
        return sourceIP;
    }

    public int getPort() {
        return port;
    }

    public long getId() {
        return id;
    }

    @Override
    public int compareTo(Packet o) {
        return Long.compare(id, o.id);
    }
}

class Pair<T, U> {
    T first;
    U second;

    public Pair(T first, U second) {
        this.first = first;
        this.second = second;
    }
}
