BookModel.findAll().then(books => {
  const bookList = books.map(book => book.name);
  // Use regular expression to match Old Testament book names
  const regex = new RegExp(`(${bookList.join('|')})`, 'i');

  app.use(express.json());

  app.post('/process', (req, res) => {
    // Process incoming text data stream
    const texts = req.body;
    let results = {};

    for (const text of texts) {
      const match = regex.exec(text);
      while (match) {
        const bookName = match[1].trim().toLowerCase();
        if (!results[bookName]) {
          results[bookName] = 0;
        }
        results[bookName]++;
        match = regex.exec(text);
      }
    }

    // Cache results for future requests
    cache.set('old-testament-books', results);

    res.json(results);
  });

  app.get('/results', (req, res) => {
