import com.jcraft.jsch.Channel;
import com.jcraft.jsch CHANNEL_SFTP;
import com.jcraft.jsch.JSch;
import com.jcraft.jsch.Session;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashMap;
import java.util.Map;

public class SSHClient {
    private Map<String, String> credentials = new HashMap<>();
    private int timeout = 3000; // default timeout in milliseconds

    public void setCredentials(String host, String username, String password) {
        this.credentials.put("host", host);
        this.credentials.put("username", username);
        this.credentials.put("password", password);
    }

    public void setTimeout(int timeoutMs) {
        this.timeout = timeoutMs;
    }

    public void executeCommand(String command) throws Exception {
        JSch jsch = new JSch();
        Session session = jsch.getSession(credentials.get("username"), credentials.get("host"), 22);
        session.setPassword(credentials.get("password"));
        session.setConfig("StrictHostKeyChecking", "no");
        session.connect();

        Channel channel = session.openChannel(CHANNEL_SFTP);
        ((ChannelSftp)channel).exec(command);

        BufferedReader reader = new BufferedReader(new InputStreamReader(channel.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            System.out.println(line);
        }

        channel.disconnect();
    }

    public void deleteFile(String filePath) throws Exception {
        JSch jsch = new JSch();
        Session session = jsch.getSession(credentials.get("username"), credentials.get("host"), 22);
        session.setPassword(credentials.get("password"));
        session.setConfig("StrictHostKeyChecking", "no");
        session.connect();

        Channel channel = session.openChannel(CHANNEL_SFTP);
        ((ChannelSftp)channel).rm(filePath);

        channel.disconnect();
    }

    public void close() {
        JSch jsch = new JSch();
        for (Session session : jsch.getActiveSessions()) {
            session.disconnect();
        }
    }
}
