import asyncio
import aiohttp
from typing import List, Dict

class UserProfileAggregator:
    async def aggregate_profiles(self, api_endpoints: List[str], user_profile_dict: Dict):
        tasks = []

        for endpoint in api_endpoints:
            task = self.fetch_data(endpoint, user_profile_dict)
            tasks.append(task)

        await asyncio.gather(*tasks)

    async def fetch_data(self, endpoint: str, user_profile_dict: Dict):
        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(endpoint) as response:
                    data = await response.json()

                    if 'data' in data:
                        for key, value in data['data'].items():
                            if key not in user_profile_dict or not isinstance(user_profile_dict[key], list):
                                user_profile_dict.setdefault(key, []).append(value)
        except aiohttp.ClientError as e:
            print(f"Error fetching data from {endpoint}: {e}")

        return asyncio.create_task(self.aggregate_profiles(api_endpoints, user_profile_dict))

async def main():
    aggregator = UserProfileAggregator()
    api_endpoints = [
        'https://api1.com/user_data',
        'https://api2.com/social_media',
        'https://api3.com/location'
    ]

    user_profile_dict = {'name': ['John', 'Doe'], 'location': []}

    await aggregator.aggregate_profiles(api_endpoints, user_profile_dict)

if __name__ == '__main__':
    asyncio.run(main())
