function runTests(moduleLabel, testSuites, config) {
  const { concurrency, timeout, resourceLimit } = config;
  const blueslip = require('blueslip');

  // Initialize the mocking library
  blueslip.reset();

  // Define a function to execute tests in parallel
  async function parallelTestExecuter(tests) {
    const results = [];
    for await (const test of tests) {
      try {
        await test();
        results.push({ status: 'success' });
      } catch (error) {
        results.push({ status: 'failure', error });
      }
    }
    return results;
  }

  // Define a function to execute tests in series
  async function serialTestExecuter(tests) {
    const results = [];
    for await (const test of tests) {
      try {
        await test();
        results.push({ status: 'success' });
      } catch (error) {
        results.push({ status: 'failure', error });
      }
    }
    return results;
  }

  // Define a function to execute test suites in parallel
  async function parallelSuiteExecuter(suites, concurrencyLimit) {
    const queue = [];
    let currentConcurrency = 0;

    for (const suite of suites) {
      if (currentConcurrency < concurrencyLimit) {
        queue.push(suite);
        currentConcurrency++;
      } else {
        // Execute the previous set of tests and reset the counter
        const results = await parallelTestExecuter(queue);
        console.log(`Finished executing ${results.length} tests`);
        for (const result of results) {
          if (result.status === 'failure') {
            throw result.error;
          }
        }
        queue = [];
        currentConcurrency = 0;
      }
    }

    // Execute the remaining tests
    if (queue.length > 0) {
      const results = await parallelTestExecuter(queue);
      console.log(`Finished executing ${results.length} tests`);
      for (const result of results) {
        if (result.status === 'failure') {
          throw result.error;
        }
      }
    }
  }

  // Define the main function to run tests
  async function run() {
    try {
      // Initialize the test execution framework
      const logger = require('logger');

      // Filter out skipped tests or suites based on command-line arguments or environment variables
      const filteredTestSuites = testSuites.filter((suite) => !suite.skip);

      // Execute the test suites in parallel, respecting the concurrency limit
      await parallelSuiteExecuter(filteredTestSuites, concurrency);

      // Log a summary of the test execution results
      logger.info(`Finished executing tests for ${moduleLabel}`);
    } catch (error) {
      console.error(error);
    }
  }

  run();
}
