#include <openssl/aes.h>
#include <openssl/err.h>
#include <openssl/kdf.h>
#include <openssl/rand.h>
#include <string.h>

typedef struct {
    unsigned char* salt;
    unsigned char* key;
    int salt_len;
    int key_len;
} CipherContext;

CipherContext* init_aes_cipher(const char* password, int password_len, int iv_len, int key_len, int iterations);

void cleanup_cipher(CipherContext* ctx) {
    if (ctx == NULL) return;
    OPENSSL_free(ctx->salt);
    OPENSSL_free(ctx->key);
    OPENSSL_free(ctx);
}

CipherContext* init_aes_cipher(const char* password, int password_len, int iv_len, int key_len, int iterations) {
    CipherContext* ctx = OPENSSL_malloc(sizeof(CipherContext));
    if (ctx == NULL) return NULL;

    // Generate random salt
    unsigned char* salt = OPENSSL_malloc(iv_len);
    RAND_bytes(salt, iv_len);
    ctx->salt = salt;
    ctx->salt_len = iv_len;

    // Derive key from password using SHA-256 and PBKDF2
    unsigned char* derived_key = OPENSSL_malloc(key_len);
    PKCS5_PBKDF2_HMAC_SHA256(password, password_len, salt, iv_len, iterations, key_len, derived_key);
    ctx->key = derived_key;
    ctx->key_len = key_len;

    // Initialize AES-256-CBC cipher
    unsigned char* iv = OPENSSL_malloc(iv_len);
    RAND_bytes(iv, iv_len);
    ctx->iv = iv;
    AES_CTX* aes_ctx = AES_new();
    if (aes_ctx == NULL) {
        cleanup_cipher(ctx);
        return NULL;
    }
    AES_set_encrypt_key(ctx->key, key_len, &aes_ctx->rctx);
    AES_cbc_encrypt(NULL, NULL, 0, aes_ctx, iv, iv_len);

    return ctx;
}

