#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <string.h>

typedef enum { ERROR, WARNING, INFO } severity_t;

// Function prototypes
void asyncLogCondition(severity_t level, char* format, ...);
void log_message(FILE*, severity_t, const char*, ...);
int open_log_file(const char*);
void close_log_file(FILE*);
void copy_data_to_dict(void** futures, int num_futures, void* initial_dict, void (*callback)(void**, void*));

// Function implementations
void asyncLogCondition(severity_t level, char* format, ...) {
    FILE* log_file = NULL;
    if ((log_file = fopen("error_log.txt", "a")) == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        return;
    }

    va_list args;
    va_start(args, format);
    log_message(log_file, level, format, args);
    va_end(args);

    fclose(log_file);
}

void log_message(FILE* log_file, severity_t level, const char* format, ...) {
    time_t now = time(NULL);
    struct tm* timestamp = localtime(&now);
    char buffer[64];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timestamp);

    va_list args;
    va_start(args, format);
    fprintf(log_file, "[%s] [Severity: %s] ", buffer, (level == ERROR) ? "ERROR" : ((level == WARNING) ? "WARNING" : "INFO"));
    vfprintf(log_file, format, args);
    va_end(args);
}

int open_log_file(const char* filename) {
    FILE* file = fopen(filename, "a");
    if (!file) {
        return -1;
    }
    return 0;
}

void close_log_file(FILE* log_file) {
    fclose(log_file);
}

void copy_data_to_dict(void** futures, int num_futures, void* initial_dict, void (*callback)(void**, void*)) {
    for (int i = 0; i < num_futures; i++) {
        callback(futures + i, initial_dict);
    }
}
