function copyBytes(chunks, ranges) {
  const buffers = [];
  for (const { buffer, start, end } of ranges) {
    let chunk;
    if (!buffer || !Buffer.isBuffer(buffer)) {
      // handle file or other non-buffer data source
      chunk = new Uint8Array(end - start);
      fs.readFile('file', (err, data) => {
        if (err) throw err;
        Buffer.from(data).copy(chunk, 0, start, end);
      });
    } else {
      chunk = buffer.slice(start, end);
    }
    buffers.push(new Uint8Array(chunk));
  }
  return Buffer.concat(buffers);
}
