```csharp
using System;
using System.Security.Cryptography;
using System.Threading.Tasks;

public interface IHashAlgorithm
{
    Task<string> GenerateAsync(string input);
    Task<string> GenerateAsync(byte[] input);
}

public class SecureHashGenerator : IDisposable
{
    private readonly ILogger _logger;
    private readonly RateLimiter _rateLimiter;

    public SecureHashGenerator(ILogger logger, RateLimiter rateLimiter)
    {
        _logger = logger;
        _rateLimiter = rateLimiter;
    }

    public Task<string> GenerateMd5Async(string input) => GenerateHashAsync(input, "MD5");
    public Task<string> GenerateMd5Async(byte[] input) => GenerateHashAsync(input, "MD5");

    public Task<string> GenerateSha1Async(string input) => GenerateHashAsync(input, "SHA1");
    public Task<string> GenerateSha1Async(byte[] input) => GenerateHashAsync(input, "SHA1");

    public Task<string> GenerateSha256Async(string input) => GenerateHashAsync(input, "SHA256");
    public Task<string> GenerateSha256Async(byte[] input) => GenerateHashAsync(input, "SHA256");

    private async Task<string> GenerateHashAsync(string input, string algorithm)
    {
        await _rateLimiter.Wait();

        try
        {
            using var hash = CreateHashAlgorithm(algorithm);
            return BitConverter.ToString(hash.ComputeHash(Encoding.UTF8.GetBytes(input))).Replace("-", String.Empty).ToLower();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error generating {algorithm} hash", algorithm);
            throw;
        }
    }

    private async Task<string> GenerateHashAsync(byte[] input, string algorithm)
    {
        await _rateLimiter.Wait();

        try
        {
            using var hash = CreateHashAlgorithm(algorithm);
            return BitConverter.ToString(hash.ComputeHash(input)).Replace("-", String.Empty).ToLower();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error generating {algorithm} hash", algorithm);
            throw;
        }
    }

    private IHashAlgorithm CreateHashAlgorithm(string algorithm)
    {
        switch (algorithm.ToLower())
        {
            case "md5":
                return new Md5HashAlgorithm();
            case "sha1":
                return new Sha1HashAlgorithm();
            case "sha256":
                return new Sha256HashAlgorithm();
            default:
                throw new ArgumentException("Invalid hash algorithm", nameof(algorithm));
        }
    }

    public void Dispose()
    {
        _logger.Dispose();
        _rateLimiter.Dispose();
    }
}

public class Md5HashAlgorithm : IHashAlgorithm
{
    public Task<string> GenerateAsync(string input) => Task.Run(() => BitConverter.ToString(MD5.Create().ComputeHash(Encoding.UTF8.GetBytes(input))).Replace("-", String.Empty).ToLower());
    public Task<string> GenerateAsync(byte[] input) => Task.Run(() => BitConverter.ToString(MD5.Create().ComputeHash(input)).Replace("-", String.Empty).ToLower());
}

public class Sha1HashAlgorithm : IHashAlgorithm
{
    public Task<string> GenerateAsync(string input) => Task.Run(() => BitConverter.ToString(Sha1.Create().ComputeHash(Encoding.UTF8.GetBytes(input))).Replace("-", String.Empty).ToLower());
    public Task<string> GenerateAsync(byte[] input) => Task.Run(() => BitConverter.ToString(Sha1.Create().ComputeHash(input)).Replace("-", String.Empty).ToLower());
}

public class Sha256HashAlgorithm : IHashAlgorithm
{
    public Task<string> GenerateAsync(string input) => Task.Run(() => BitConverter.ToString(Sha256.Create().ComputeHash(Encoding.UTF8.GetBytes(input))).Replace("-", String.Empty).ToLower());
    public Task<string> GenerateAsync(byte[] input) => Task.Run(() => BitConverter.ToString(Sha256.Create().ComputeHash(input)).Replace("-", String.Empty).ToLower());
}

public class RateLimiter : IDisposable
{
    private readonly int _maxRequestsPerSecond;
    private readonly System.Timers.Timer _timer;

    public RateLimiter(int maxRequestsPerSecond)
    {
        _maxRequestsPerSecond = maxRequestsPerSecond;
        _timer = new System.Timers.Timer(maxRequestsPerSecond / 1000.0);
        _timer.Elapsed += (sender, e) => { Interlocked.Decrement(ref _timer.Requests); };
        _timer.Start();
    }

    public Task Wait()
    {
        if (!Interlocked.CompareExchange(ref _timer.Requests, 1, 0).Equals(0))
        {
            throw new InvalidOperationException("Rate limit exceeded");
        }
        return Task.Delay(_maxRequestsPerSecond / 1000);
    }

    public void Dispose()
    {
        _timer.Stop();
        _timer.Dispose();
    }
}
