```c
#include <openssl/err.h>
#include <openssl/tls.h>

TLS_CTX* tls_init(const char* password, const char* cert_file, const char* key_file) {
    SSL_CTX* ssl_ctx = SSL_CTX_new(TLS_client_method());
    if (!ssl_ctx) {
        return NULL;
    }

    // Set the cipher suite
    SSL_CTX_set_ciphersuites(ssl_ctx, TLS_AES_256_GCM_SHA384Protocol::TLS_AES_256_GCM_SHA384);

    // Set the password to derive the encryption key
    EVP_CIPHER_CTX* evp_ctx = EVP_CIPHER_CTX_new();
    if (!evp_ctx) {
        ERR_free_strings();
        SSL_CTX_free(ssl_ctx);
        return NULL;
    }

    // Derive the encryption key from the password
    int err = EVP_SealInit(evp_ctx, NULL, password, strlen(password));
    if (err <= 0) {
        ERR_error_string(ERR_get_error(), NULL);
        EVP_CIPHER_CTX_free(evp_ctx);
        SSL_CTX_free(ssl_ctx);
        return NULL;
    }

    // Set the client certificate
    X509* cert = PEM_read_X509_AUX(cert_file, NULL);
    if (!cert) {
        ERR_error_string(ERR_get_error(), NULL);
        EVP_CIPHER_CTX_free(evp_ctx);
        SSL_CTX_free(ssl_ctx);
        return NULL;
    }
    SSL_CTX_set_client_cert_chain(ssl_ctx, cert);

    // Set the private key
    FILE* key_file_fp = fopen(key_file, "rb");
    if (!key_file_fp) {
        ERR_error_string(ERR_get_error(), NULL);
        EVP_CIPHER_CTX_free(evp_ctx);
        SSL_CTX_free(ssl_ctx);
        return NULL;
    }
    PEM_read_RSAPrivateKey(key_file_fp, &cert, NULL);
    fclose(key_file_fp);

    // Enable the TLS connection
    SSL_CTX_set_mode(ssl_ctx, SSL_MODE_ENABLE_PARTIAL_WRITE);
    return (TLS_CTX*) ssl_ctx;
}

void tls_disable(TLS_CTX* ctx) {
    SSL_CTX_free((SSL_CTX*)ctx);
}

void tls_cleanup() {
    ERR_free_strings();
}
