import re
import json
import requests
from io import StringIO
from contextlib import closing

LOG_FILE = 'large_log_file.log'
API_URL = 'https://your_api_url.com/api/log_stats'

def process_log_file(log_file):
    with closing(open(log_file, 'r')) as f:
        chunk_size = 1024 ** 2  # 1MB chunks
        for chunk in iter(lambda: f.read(chunk_size), b''):
            for line in StringIO(chunk.decode('utf-8')).readlines():
                if not line.strip():
                    continue

                match = re.match(r'(\d+\.\d+.\d+.\d+) - \[(\d{1,3}-\d{1,3}-\d{4}:\d{2}:\d{2}:\d{2})] "(\w+) (.*) HTTP\/(\d)(.*) " (\d{3})', line)
                if match:
                    ip_address = match.group(1)
                    request_time = match.group(2)
                    request_method = match.group(3)
                    response_status_code = int(match.group(8))

                    # Aggregate statistics
                    stats = {'ip_address': ip_address, 'average_response_time': 0}
                    if ip_address not in stats:
                        stats[ip_address] = {'count': 1, 'total_response_time': response_status_code}

                    else:
                        stats[ip_address]['count'] += 1
                        stats[ip_address]['total_response_time'] += response_status_code

                    # Report statistics to API
                    try:
                        api_request_data = {
                            'ip_address': ip_address,
                            'average_response_time': (stats[ip_address]['total_response_time'] / stats[ip_address]['count']) if stats[ip_address]['count'] > 0 else None
                        }
                        response = requests.post(API_URL, json=api_request_data)
                        if not response.ok:
                            print(f'Error reporting statistics for {ip_address}: {response.text}')
                    except Exception as e:
                        print(f'Error processing log file: {e}')

# Process the log file
process_log_file(LOG_FILE)

