#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <json-c/json.h>

#define JSON_OBJECT_SIZE 1024

char* generateUniqueFilename(const char* base_filename) {
    CURL *curl;
    CURLcode res;
    struct json_object *metadata = NULL, *file_type = NULL, *digit_count = NULL;

    // Initialize curl
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        // Set URL for metadata service
        char url[1024];
        sprintf(url, "https://metadata-service.com/get-type-and-count?base_filename=%s", base_filename);

        // Perform HTTP request
        curl_easy_setopt(curl, CURLOPT_URL, url);
        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            json_object_free(metadata);
            free(curl);
            return NULL;
        }

        // Parse JSON response
        json_object *root = json_object_from_file("response.json");
        metadata = json_object_object_get(root, "metadata");

        file_type = json_object_object_get(metadata, "file_type");
        digit_count = json_object_object_get(metadata, "digit_count");

        // Generate unique filename based on file type and digit count
        char* new_filename = (char*)malloc(strlen(base_filename) + strlen(json_object_get_string(file_type)) + 2 * atoi(json_object_get_string(digit_count)));
        sprintf(new_filename, "%s-%s%d", base_filename, json_object_get_string(file_type), atoi(json_object_get_string(digit_count)));

        // Free resources
        json_object_free(root);
        free(curl);

        return new_filename;
    } else {
        // Handle error
        return NULL;
    }
}
