#include <openssl/err.h>
#include <openssl/evp.h>

void load_cryptographic_primitives() {
    // Load OpenSSL configuration files
    const char* config_files[] = {"file1", "file2"};
    for (const char* file : config_files) {
        if (!load_config_file(file)) {
            log_error(ERR_ERROR_LOADING_CONFIG_FILE, file);
        }
    }

    // Add AES block cipher
    if (!EVP_add_cipher("AES-128-CBC")) {
        log_error(ERR_ERROR_ADDING_AES_CIPHER, "AES-128-CBC");
    }
    if (!EVP_add_cipher("AES-256-GCM")) {
        log_error(ERR_ERROR_ADDING_AES_CIPHER, "AES-256-GCM");
    }

    // Add Camellia block cipher
    if (!EVP_add_cipher("Camellia-128-CBC")) {
        log_error(ERR_ERROR_ADDING_CAMELLIA_CIPHER, "Camellia-128-CBC");
    }
    if (!EVP_add_cipher("Camellia-256-GCM")) {
        log_error(ERR_ERROR_ADDING_CAMELLIA_CIPHER, "Camellia-256-GCM");
    }

    // Add MD5 digest
    if (!EVP_add_digest("MD5")) {
        log_error(ERR_ERROR_ADDING_MD5_DIGEST, "MD5");
    }
    if (!EVP_add_digest_alias("md5", "MD5")) {
        log_error(ERR_ERROR_ADDING_MD5_ALIAS, "md5 -> MD5");
    }

    // Add SHA-1 digest
    if (!EVP_add_digest("SHA1")) {
        log_error(ERR_ERROR_ADDING_SHA1_DIGEST, "SHA1");
    }
    if (!EVP_add_digest_alias("sha1", "SHA1")) {
        log_error(ERR_ERROR_ADDING_SHA1_ALIAS, "sha1 -> SHA1");
    }

    // Add SHA-256 and SHA-512 digests
    for (int i = 224; i <= 1024; i += 128) {
        char buffer[10];
        sprintf(buffer, "SHA-%i", i);
        if (!EVP_add_digest(buffer)) {
            log_error(ERR_ERROR_ADDING_SHA_DIGEST, buffer);
        }
        sprintf(buffer, "%x", i);
        sprintf(buffer + 2, "-256");
        if (!EVP_add_digest_alias(buffer, buffer)) {
            log_error(ERR_ERROR_ADDING_SHA_ALIAS, buffer);
        }
    }

    // Add RSA with SHA1
    if (!EVP_add_cipher("RSA")) {
        log_error(ERR_ERROR_ADDING_RSA_CIPHER, "RSA");
    }
    if (!EVP_add_digest_alias("sha1", "SHA1")) {
        log_error(ERR_ERROR_ADDING_SHA_ALIAS, "sha1 -> SHA1");
    }

    // Cache successful primitive additions
    cached_primitives = EVP_get_ciphers();

    // Optimize performance by reusing cached primitives
    if (cached_primitives) {
        EVP_set_ciphers(cached_primitives);
    }
}
