<?php

function authenticateUser($clientId, $clientSecret, $redirectUri, $code) {
    // Initialize OAuth 2.0 client
    $oauthClient = new \League\OAuth2\Client\Provider\Facebook([
        'clientId' => $clientId,
        'clientSecret' => $clientSecret,
        'redirectUri' => $redirectUri,
    ]);

    try {
        // Exchange authorization code for access token
        $accessToken = $oauthClient->getAccessToken('authorization_code', ['code' => $code]);

        // Store access token securely in session variable
        $_SESSION['access_token'] = $accessToken;

        // Use access token to retrieve user information
        $userInformation = $oauthClient->getUserInfo();

        // Cache user data for improved performance and rate limiting
        $cache = new Redis();
        $cache->set('user:' . $userInformation->getId(), json_encode($userInformation));

        // Log authentication attempt with success message
        \Monolog\Logger::getInstance()->info("User authenticated successfully");

    } catch (\League\OAuth2\Client\Provider\Exception\IdentityProviderException $e) {
        // Log error and throw exception if identity provider error occurs
        \Monolog\Logger::getInstance()->error($e->getMessage());
        throw $e;
    } catch (Exception $e) {
        // Log error and rethrow exception for any other errors
        \Monolog\Logger::getInstance()->error($e->getMessage());
        throw $e;
    }

    // Implement rate limiting using Redis or Memcached
    if ($cache->get('rate_limit') >= 10) {
        \Monolog\Logger::getInstance()->warn("Rate limit exceeded");
        return null;
    }

    // Store user information in session variable for subsequent requests
    $_SESSION['user'] = $userInformation;

    // Return authenticated user data
    return $userInformation;
}

