```rust
use std::sync::{Arc, Mutex};
use std::thread;
use tokio::net::HttpsStream;
use tokio_tls::TlsConnector;

struct HttpClient {
    tls_connector: Arc<Mutex<TlsConnector>>,
    logger: Arc<Mutex<dyn Fn(String) -> () + Sync>>,
}

impl HttpClient {
    async fn new() -> Self {
        let tls_connector = TlsConnector::from_memory(None).await.unwrap();
        let logger = Arc::new(Mutex::new(|_| ()));
        Self { tls_connector, logger }
    }

    async fn get(&self, url: &str) -> Result<String, Box<dyn std::error::Error>> {
        let mut stream = self.tls_connector.connect(url).await?;
        let mut buffer = Vec::new();
        stream.read_to_end(&mut buffer).await?;

        let response = String::from_utf8(buffer)?;
        (self.logger.lock().unwrap())("GET Request: ".to_string() + &url);

        Ok(response)
    }

    async fn post(&self, url: &str, data: &str) -> Result<String, Box<dyn std::error::Error>> {
        let mut stream = self.tls_connector.connect(url).await?;
        stream.write_all(data.as_bytes()).await?;

        let mut buffer = Vec::new();
        stream.read_to_end(&mut buffer).await?;

        let response = String::from_utf8(buffer)?;
        (self.logger.lock().unwrap())("POST Request: ".to_string() + &url);

        Ok(response)
    }

    async fn handle_request(&self, url: &str) -> Result<String, Box<dyn std::error::Error>> {
        match url.find('/') {
            Some(i) => {
                if i == 0 {
                    (self.logger.lock().unwrap())("Invalid URL: ".to_string() + &url);
                    Err("Invalid URL".into())
                } else {
                    let path = &url[i..];
                    match path.as_bytes()[..].parse::<u16>() {
                        Ok(80) => self.get(url).await,
                        _ => self.post(url, "POST DATA").await
                    }
                }
            }
            None => {
                (self.logger.lock().unwrap())("Invalid URL: ".to_string() + &url);
                Err("Invalid URL".into())
            }
        }
    }

    async fn run(&self) -> Result<(), Box<dyn std::error::Error>> {
        let urls = vec!["https://example.com", "https://other.example.com"];
        for url in urls {
            match self.handle_request(url).await {
                Ok(_) => println!("Request successful"),
                Err(err) => eprintln!("Error: {}", err),
            }
        }

        Ok(())
    }
}

#[tokio::main]
async fn main() {
    let client = HttpClient::new().await;
    client.run().await;
}
