use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;
use git2::{Repository, CredentialHelper};
use sysinfo::{System, SystemExt};
use rusqlite::Connection;

struct CompilationResult {
    time: i32,
    memory_usage: u64,
    error: Option<String>,
}

async fn compile_file(path: &Path) -> Result<CompilationResult, String> {
    // Fetch source file from remote repository
    let repo = Repository::open(&path).unwrap();
    let head_commit = repo.head().unwrap().commit().unwrap();

    // Measure memory usage before compilation
    let system = System::new_all();
    let resident_set_size_before = system.get ResidentSetSize();

    // Compile the source file using rustc
    let output = Command::new("rustc")
        .arg("--edition=2021")
        .arg(path)
        .output()
        .expect("Failed to execute process");

    // Measure memory usage after compilation
    let resident_set_size_after = system.get ResidentSetSize();

    // Parse the output for errors
    let error = if output.status.success() {
        None
    } else {
        Some(String::from_utf8_lossy(&output.stdout).to_string())
    };

    // Calculate compilation time
    let time_taken = format!("{} seconds", output.duration().as_secs());

    // Return the result
    Ok(CompilationResult {
        time: time_taken.parse().unwrap(),
        memory_usage: resident_set_size_after - resident_set_size_before,
        error,
    })
}

// Example usage:
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let path = Path::new("path/to/source/file.rs");
    let result = compile_file(path).await?;
    println!("Compilation time: {}", result.time);
    println!("Memory usage: {} KB", result.memory_usage / 1024);
    if let Some(err) = &result.error {
        println!("Error: {}", err);
    }
    Ok(())
}
