#include <forward_list>
#include <algorithm>
#include <functional>

void insertAfter(std::forward_list<std::string>& lst, const std::string& target,
                 const std::string& strToInsert, std::function<bool(const std::string&)> comp = std::less<>()) {
    auto it = std::find_if(lst.begin(), lst.end(), [comp](const std::string& s) { return comp(s) == comp(target); });
    if (it != lst.end()) {
        lst.insert_after(it, strToInsert);
    } else {
        lst.append(strToInsert);
    }
}
