import hashlib
import os
from typing import Dict

class FileAggregator:
    def __init__(self):
        self.aggregated_file = None
        self.file_chunks: Dict[str, bytes] = {}
        self.checksums: Dict[str, str] = {}

    def add_file(self, file_path: str) -> None:
        if not os.path.exists(file_path):
            raise FileNotFoundError(f"File {file_path} does not exist")
        with open(file_path, 'rb') as file:
            chunk = file.read(1024 * 1024)  # Read 1MB at a time
            while chunk:
                self.file_chunks[file_path] = chunk
                checksum = hashlib.sha256(chunk).hexdigest()
                self.checksums[file_path] = checksum
                chunk = file.read(1024 * 1024)

    def combine_files(self) -> None:
        if not self.file_chunks:
            return

        with open('aggregated_file', 'wb') as aggregated_file:
            for file, chunk in self.file_chunks.items():
                aggregated_file.write(chunk)
                del self.file_chunks[file]

    def verify_checksums(self) -> None:
        for file, checksum in self.checksums.items():
            calculated_checksum = hashlib.sha256(open(file, 'rb').read()).hexdigest()
            if checksum != calculated_checksum:
                raise ValueError(f"Checksum mismatch for file {file}")

if __name__ == '__main__':
    aggregator = FileAggregator()

    # Add files to the aggregator
    aggregator.add_file('file1.txt')
    aggregator.add_file('file2.bin')

    # Combine files
    aggregator.combine_files()

    # Verify checksums
    aggregator.verify_checksums()
