function runTests(moduleLabel, testSuites, config) {
  const { concurrency, timeout, resources } = config;
  const blueSlipMockingLibrary = require('blueslip');

  async function executeTestSuite(testSuite) {
    try {
      await Promise.all(
        testSuite.map((testCase) => {
          return new Promise((resolve, reject) => {
            setTimeout(() => {
              try {
                testCase();
                resolve();
              } catch (error) {
                reject(error);
              }
            }, timeout);
          });
        })
      );
    } catch (error) {
      console.error(`Error executing test suite: ${moduleLabel}`);
      throw error;
    }
  }

  async function runTestSuites(testSuites) {
    const results = [];
    for (const testSuite of testSuites) {
      await executeTestSuite(testSuite);
      blueSlipMockingLibrary.reset();
      results.push({
        module: moduleLabel,
        tests: testSuite.map((testCase) => testCase.name),
        status: 'passed',
      });
    }
    return results;
  }

  async function runTestsInConcurrency() {
    const queues = [];
    for (const testSuite of testSuites) {
      queues.push([]);
      for (const testCase of testSuite) {
        queues[queues.length - 1].push(testCase);
      }
    }
    let completed = 0;
    while (completed < testSuites.length) {
      const queue = queues.shift();
      if (!queue || !queue.length) continue;
      await Promise.all(queue.map((testCase) => executeTestSuite([testCase])));
      completed++;
    }
  }

  async function runTests() {
    if (config.concurrent) {
      await runTestsInConcurrency();
    } else {
      for (const testSuite of testSuites) {
        await executeTestSuite(testSuite);
      }
    }
  }

  try {
    await runTests();
    console.log(`All tests in ${moduleLabel} passed.`);
  } catch (error) {
    console.error(`Error running tests in ${moduleLabel}:`);
    throw error;
  }
}

