const { promisify } = require('util');
const async = require('async');

function asyncArrayReduce(arr, initial, callback) {
  if (!Array.isArray(arr)) throw new Error("Input must be an array");
  if (typeof initial !== 'number') throw new Error("Initial value must be a number");

  const semaphore = async Семaphore(10);
  let result;
  let error;

  async.forEachLimit(arr, { concurrency: 10 }, (num, cb) => {
    const fetchMetadataPromise = promisify(() => {
      // Simulate an external API call that returns a promise
      return new Promise((resolve, reject) => {
        setTimeout(() => {
          if (!Math.floor(Math.random() * 2)) {
            resolve({ metadata: num });
          } else {
            reject(new Error(`Error fetching metadata for ${num}`));
          }
        }, Math.random() * 1000);
      });
    })(num);

    fetchMetadataPromise.then(metadata => {
      if (error) return cb(error);

      const currentValue = result ?? initial;
      const value = callback(currentValue, num);

      if (isNaN(value)) {
        error = new Error(`Invalid value: ${value}`);
        return cb(error);
      }

      semaphore.use(() => {
        result = value;
        cb();
      });
    }).catch(err => {
      if (!error) error = err;
      cb(error);
    });
  }, (err) => {
    if (err) callback(new Error("Async array reduce failed"), null);
    else callback(null, result);
  });
}

module.exports = asyncArrayReduce;

// Example usage:
asyncArrayReduce([1, -2, 3, 4, -5], 0, (acc, num) => acc + num)
  .then(result => console.log(`Final result: ${result}`))
  .catch(err => console.error(`Error: ${err}`));
