using System;
using System.Xml;
using System.Xml.XPath;

public class XmlParser
{
    private readonly IConfigFileLoader _configFileLoader;
    private readonly IXPathEvaluator _xpathEvaluator;
    private readonly ICachingMechanism _cachingMechanism;

    public XmlParser(IConfigFileLoader configFileLoader, IXPathEvaluator xpathEvaluator, ICachingMechanism cachingMechanism)
    {
        _configFileLoader = configFileLoader;
        _xpathEvaluator = xpathEvaluator;
        _cachingMechanism = cachingMechanism;
    }

    public string GetElementValue(string nodeName, string xmlFilePath)
    {
        string result = null;

        try
        {
            // Load the XML document from file path or cache
            XmlDocument xmlDoc = _cachingMechanism.GetDocument(xmlFilePath);

            if (xmlDoc == null)
            {
                xmlDoc = new XmlDocument();
                xmlDoc.Load(_configFileLoader.LoadXmlFile(xmlFilePath));
                _cachingMechanism.AddDocument(xmlFilePath, xmlDoc);
            }

            // Evaluate the XPath query
            XPathNavigator navigator = xmlDoc.CreateNavigator();

            XPathExpression expression = navigator.Compile($"//{nodeName}[namespace-uri()='']");

            if (expression != null)
            {
                XPathNodeIterator nodes = navigator.Select(expression);

                if (nodes.Count == 1)
                {
                    result = nodes.Current.Value;
                }
                else
                {
                    throw new Exception("Multiple elements found with the given name.");
                }
            }
            else
            {
                throw new Exception("Invalid XPath query or missing namespace declaration.");
            }
        }
        catch (Exception ex)
        {
            throw new Exception("Error parsing XML document.", ex);
        }

        return result;
    }
}

public interface IConfigFileLoader
{
    string LoadXmlFile(string filePath);
}

public interface IXPathEvaluator
{
    XPathExpression Compile(string query);
}

public interface ICachingMechanism
{
    XmlDocument GetDocument(string filePath);

    void AddDocument(string filePath, XmlDocument document);
}
