using System;
using System.Diagnostics;
using System.IO;
using System.Threading;

public class WebsiteManager
{
    public void AddAndStartSite(string directoryPath, string siteName)
    {
        try
        {
            // Check if web.config file exists in the directory
            if (!Directory.Exists(directoryPath))
                throw new DirectoryNotFoundException($"The directory '{directoryPath}' does not exist.");

            // Validate that the directory path is valid and accessible
            if (!new DirectoryInfo(directoryPath).Exists)
                throw new DirectoryNotFoundException($"The directory '{directoryPath}' does not exist or is inaccessible.");

            // Check for existing site with same name
            string existingSite = GetExistingSiteName(directoryPath, siteName);
            if (string.IsNullOrEmpty(existingSite))
                siteName += "_" + Guid.NewGuid().ToString("N");

            // Validate and retrieve additional settings from external configuration database
            int portNumber;
            string startupParameters;

            try
            {
                using (var dbConnection = new DatabaseConnection())
                {
                    dbConnection.Open();
                    var result = dbConnection.ExecuteQuery($"SELECT * FROM sites WHERE name = '{siteName}'");
                    if (!result.IsSuccess)
                        throw new Exception("Failed to retrieve site settings from database");

                    portNumber = int.Parse(result["port_number"].ToString());
                    startupParameters = result["startup_parameters"].ToString();
                }
            }
            catch (Exception ex)
            {
                LogError($"Failed to retrieve site settings: {ex.Message}");
                throw;
            }

            // Start the site using Process class
            try
            {
                using (var process = new Process())
                {
                    process.StartInfo.FileName = "iisexpress.exe";
                    process.StartInfo.Arguments = $"-port:{portNumber} -siteName:{siteName} {startupParameters}";
                    process.Start();
                    LogAction($"Started site '{siteName}' on port {portNumber}");
                }
            }
            catch (Exception ex)
            {
                LogError($"Failed to start site: {ex.Message}");
                throw;
            }

            // Retry starting the site in case of transient failures
            int retryCount = 0;
            while (true)
            {
                try
                {
                    process.WaitForExit();
                    break;
                }
                catch (Exception ex) when (retryCount < 3)
                {
                    Thread.Sleep(TimeSpan.FromSeconds(5));
                    LogError($"Site '{siteName}' failed to start: {ex.Message}");
                    retryCount++;
                }
            }

            // Clean up after site addition and startup
            process.Dispose();
        }
        catch (Exception ex)
        {
            LogError(ex.Message);
            throw;
        }
    }

