import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;

public class MD5Hasher {
    private static final int MAX_THREADS = 10;
    private static final int CACHE_SIZE = 1000;
    private static final String MAX_LENGTH_PROPERTY = "md5.max.length";
    private static final int DEFAULT_MAX_LENGTH = 1000;

    private ExecutorService executor;
    private Map<String, byte[]> cache;
    private BlockingQueue<Callable<byte[]>> taskQueue;

    public MD5Hasher(int maxThreads, int cacheSize) {
        this.MAX_THREADS = maxThreads;
        this.CACHE_SIZE = cacheSize;
        this.executor = createThreadPool();
        this.cache = new HashMap<>(cacheSize);
        this.taskQueue = new LinkedBlockingQueue<>();
    }

    public byte[] computeMD5(String input) throws IOException {
        if (input == null || input.length() > getMaxLength()) {
            throw new IOException("Invalid input string");
        }

        String hashKey = input.toLowerCase();
        if (cache.containsKey(hashKey)) {
            return cache.get(hashKey);
        }

        Callable<byte[]> task = () -> computeMD5Hash(input);
        taskQueue.add(task);

        try {
            byte[] result = executor.submit(task).get(MAX_THREADS, TimeUnit.MILLISECONDS);
            cache.put(hashKey, result);
            return result;
        } catch (InterruptedException | ExecutionException e) {
            logger.error("Error computing MD5 hash", e);
            return null;
        }
    }

    private int getMaxLength() {
        String maxLengthStr = System.getProperty(MAX_LENGTH_PROPERTY);
        return maxLengthStr != null ? Integer.parseInt(maxLengthStr) : DEFAULT_MAX_LENGTH;
    }

    private ExecutorService createThreadPool() {
        return java.util.concurrent.Executors.newFixedThreadPool(MAX_THREADS);
    }

    private byte[] computeMD5Hash(String input) throws IOException {
        try (MessageDigest md = MessageDigest.getInstance("MD5")) {
            md.update(input.getBytes());
            return md.digest();
        } catch (NoSuchAlgorithmException e) {
            logger.error("Error computing MD5 hash", e);
            return null;
        }
    }

    private void evictLeastRecentlyUsedEntry() {
        // Implement LRU eviction logic here
    }

    public static void main(String[] args) throws Exception {
        MD5Hasher md5 = new MD5Hasher(MAX_THREADS, CACHE_SIZE);
        String input = "Hello World";
        byte[] result = md5.computeMD5(input);
        // Use the computed hash here
    }
}
