const OLD_TESTAMENT_BOOKS = ["Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy", "Joshua", "Judges", "Ruth", "1Samuel", "2Samuel", "1Kings", "2Kings", "1Chronicles", "2Chronicles", "Ezra", "Nehemiah", "Esther", "Job", "Psalms", "Proverbs", "Ecclesiastes", "SongOfSolomon", "Isaiah", "Jeremiah", "Lamentations", "Ezekiel", "Daniel", "Hosea", "Joel", "Amos", "Obadiah", "Jonah", "Micah", "Zephaniah", "Habakkuk", "Zechariah", "Malachi"];
const NEW_TESTAMENT_BOOKS = ["Matthew", "Mark", "Luke", "John", "Acts", "Romans", "1Corinthians", "2Corinthians", "Galatians", "Ephesians", "Philippians", "Colossians", "1Thessalonians", "2Thessalonians", "1Timothy", "2Timothy", "Titus", "Philemon", "Hebrews", "James", "1Peter", "2Peter", "1John", "2John", "3John", "Jude", "Revelation"];

function extractBibleBookNames(text) {
  if (typeof text !== 'string') throw new Error('Invalid input type. Please provide a string.');

  const TEXT_REGEXP = /^[a-zA-Z\s]+$/; // Matches only letters and spaces
  const PUNCTUATION_REGEXP = /[^\w\s]/g; // Matches all non-word characters

  let cleanedText = text.replace(PUNCTUATION_REGEXP, '').toLowerCase();
  let bookNames = {};

  OLD_TESTAMENT_BOOKS.forEach((book) => {
    if (cleanedText.includes(TEXT_REGEXP.test(book))) {
      if (!bookNames[book]) bookNames[book] = 0;
      bookNames[book]++;
    }
  });

  NEW_TESTAMENT_BOOKS.forEach((book) => {
    if (cleanedText.includes(TEXT_REGEXP.test(book))) {
      if (!bookNames[book]) bookNames[book] = 0;
      bookNames[book]++;
    }
  });

  return bookNames;
}

// Example usage:
const text = "The book of Genesis is mentioned in the Bible. The Gospel of Matthew and John are also important.";
try {
  const result = extractBibleBookNames(text);
  console.log(result); // Output: { Genesis: 1, Matthew: 2, John: 2 }
} catch (error) {
  console.error(error);
}
