const { semaphore } = require('async-semaphore');
const { throttle } = require('lodash.throttle');
const { promisify } = require('util');

class AsyncArrayReduce {
  constructor(concurrency = 5) {
    this.semaphore = new semaphore(concurrency);
    this.cache = {};
    this.authToken = null;
  }

  async reduce(arr, initVal, callback) {
    let result = initVal;
    let error = null;

    const asyncCallback = (acc, val) => new Promise((resolve, reject) => {
      this.semaphore.take(() => {
        setTimeout(() => {
          try {
            if (typeof val === 'function') {
              val(result, acc).then(next => {
                result = next;
              }).catch(err => {
                error = err;
                resolve();
              });
            } else {
              const promise = promisify(val);
              promise().then(next => {
                result = next;
              }).catch(err => {
                error = err;
                resolve();
              });
            }
          } catch (err) {
            error = err;
            resolve();
          } finally {
            this.semaphore.release();
          }
        }, 0);
      });
    });

    await Promise.all(arr.map(asyncCallback));

    if (error) return { error };

    return result;
  }

  asyncCustomAccumulator(acc, val) {
    // Custom accumulator implementation
  }

  getAuthToken() {
    // Get authentication token
  }

  setAuthToken(token) {
    this.authToken = token;
  }
}

module.exports = AsyncArrayReduce;
