    this.testLabels = testLabels;
    this.testFunctions = testFunctions;
    this.dataSources = dataSources;
    this.cleanupFunctions = cleanupFunctions;
  }

  async runTests() {
    try {
      const { default: module } = await import(`./${this.moduleLabel}`);
      for (const [i, test] of this.testLabels.entries()) {
        console.log(`Running test ${test}...`);
        await Promise.all(
          this.dataSources.map((dataSource) => dataSource.fetchData())
        );
        await test();
        console.log(`Test ${test} passed.`);
        if (process.env.BLUESLIP_ENABLED) {
          await require('blueslip').reset();
        }
      }
    } catch (error) {
      console.error(`Error running tests: ${error}`);
    } finally {
      for (const cleanup of this.cleanupFunctions) {
        try {
          await cleanup();
        } catch (error) {
          console.error(`Error cleaning up after test: ${error}`);
        }
      }
    }
  }
}
