using System;
using System.Security.Cryptography;
using System.Text;

public class TripleDesDecryptor
{
    private readonly object _syncLock = new object();
    private readonly Dictionary<string, TripleDESAlg> _keysIVs = new Dictionary<string, TripleDESAlg>();

    public TripleDesDecryptor()
    {
        // Initialize the CSP provider
        using (var csp = new CustomCSPProvider())
        {
            foreach (var key in csp.GetKeysAndIVs())
            {
                _keysIVs.Add(key.Key, new TripleDESAlg(csp.GetKey(key.Key), csp.GetIV(key.Key)));
            }
        }
    }

    public string DecryptMessage(string base64EncodedMessage)
    {
        try
        {
            var encryptedBytes = Convert.FromBase64String(base64EncodedMessage);
            var decryptedBytes = Decrypt(encryptedBytes);
            return Encoding.UTF8.GetString(decryptedBytes);
        }
        catch (Exception ex)
        {
            // Log the error and throw a meaningful exception
            Console.WriteLine("Error decrypting message: " + ex.Message);
            throw;
        }
    }

    private byte[] Decrypt(byte[] encryptedBytes)
    {
        lock (_syncLock)
        {
            var decryptedBytes = new byte[encryptedBytes.Length];
            foreach (var keyIV in _keysIVs)
            {
                try
                {
                    using (var des = new TripleDESCryptoServiceProvider())
                    {
                        des.Key = keyIV.Value.Key;
                        des.IV = keyIV.Value.IV;
                        var decryptedBuffer = Decrypt(des, encryptedBytes);
                        Array.Copy(decryptedBuffer, decryptedBytes, decryptedBuffer.Length);
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine("Error decrypting with key " + keyIV.Key + ": " + ex.Message);
                }
            }
            return decryptedBytes;
        }
    }

    private byte[] Decrypt(TripleDESCryptoServiceProvider des, byte[] encryptedBytes)
    {
        using (var memoryStream = new MemoryStream(encryptedBytes))
        {
            var cryptoStream = new CryptoStream(memoryStream, des.CreateDecryptor(), CryptoStreamMode.Read);
            return ReadFully(cryptoStream);
        }
    }

    private byte[] ReadFully(Stream stream)
    {
        using (var bufferStream = new MemoryStream())
        {
            var buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = stream.Read(buffer, 0, buffer.Length)) > 0)
            {
                bufferStream.Write(buffer, 0, bytesRead);
            }
            return bufferStream.ToArray();
        }
    }

    private class TripleDESAlg
    {
        public byte[] Key { get; set; }
        public byte[] IV { get; set; }

        public TripleDESAlg(byte[] key, byte[] iv)
        {
            Key = key;
            IV = iv;
        }
    }
}

