import argparse
import json
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import urlparse, parse_qs

class ConfigError(Exception):
    pass

def read_config(file_path):
    try:
        with open(file_path, 'r') as f:
            config = json.load(f)
    except FileNotFoundError:
        raise ConfigError(f"Configuration file {file_path} not found.")
    except json.JSONDecodeError:
        raise ConfigError(f"Invalid configuration file format: {file_path}")

    return config

def start_server(port, host, allowed_ips, debug=False, log_file=None):
    class RequestHandler(BaseHTTPRequestHandler):
        def do_GET(self):
            parsed_url = urlparse(self.path)
            query_params = parse_qs(parsed_url.query)

            if 'ip' in query_params:
                client_ip = query_params['ip'][0]

                if client_ip not in allowed_ips:
                    self.send_response(403)
                    self.end_headers()
                    return

                self.send_response(200)
                self.end_headers()
                self.wfile.write(b"Hello, client from {client_ip}!")
            else:
                self.send_response(404)
                self.end_headers()
                self.wfile.write(b"Not Found")

        def log_message(self, format, *args):
            if log_file:
                with open(log_file, 'a') as f:
                    print(format % args, file=f)
            else:
                print(format % args)

    server_address = (host, port)

    if debug:
        print(f"Starting HTTP server on {server_address} in debug mode.")
    else:
        print(f"Starting HTTP server on {server_address}.")

    if log_file:
        print(f"Writing logs to file {log_file}.")
    else:
        print("Writing logs to console.")

    httpd = HTTPServer(server_address, RequestHandler)

    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        print("Stopping server.")
        httpd.shutdown()
        print("Server stopped.")

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Start a simple HTTP server with configuration from a file and optional debug mode and log file.")
    parser.add_argument("config_file", help="Path to the configuration file.")
    parser.add_argument("-d", "--debug", action="store_true", help="Run the server in debug mode.")
    parser.add_argument("-l", "--log-file", help="Specify an alternative log file.")

    args = parser.parse_args()

    try:
        config = read_config(args.config_file)

        port = int(config.get("port", 8080))
        host = config.get("host", "localhost")
        allowed_ips = [ip.strip() for ip in config.get("allowed_ips", "").split(",")]

        start_server(port, host, allowed_ips, debug=args.debug, log_file=args.log_file)
    except ConfigError as e:
        print(f"Error: {e}")
