#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define SEM_MAX_NAME 32
#define SEM_MAX_COUNT 1000
#define SEM_FLAG_SET 1
#define SEM_FLAG_CLEAR 0

typedef struct {
    pthread_mutex_t mutex;
    int value;
    char name[SEM_MAX_NAME];
} Semaphore;

Semaphore *semaphores = NULL;
int semaphore_count = 0;

void sem_create(const char *name) {
    pthread_mutex_init(&((semaphores + semaphore_count)->mutex), NULL);
    strcpy((semaphores + semaphore_count)->name, name);
    (semaphores + semaphore_count)->value = SEM_FLAG_SET;
    semaphore_count++;
}

int sem_delete(const char *name) {
    int i;
    for (i = 0; i < semaphore_count; i++) {
        if (!strcmp((semaphores + i)->name, name)) {
            pthread_mutex_destroy(&((semaphores + i)->mutex));
            memmove((semaphores + i), (semaphores + i + 1), (semaphore_count - i - 1) * sizeof(Semaphore));
            semaphore_count--;
            return 0;
        }
    }
    return -1; // Semaphore not found
}

void sem_increment(const char *name, int value) {
    pthread_mutex_lock(&((semaphores + find_semaphore(name))->mutex));
    (semaphores + find_semaphore(name))->value += value;
    if ((semaphores + find_semaphore(name))->value > SEM_MAX_COUNT)
        (semaphores + find_semaphore(name))->value = SEM_FLAG_SET;
    pthread_mutex_unlock(&((semaphores + find_semaphore(name))->mutex));
}

int sem_decrement(const char *name, int value) {
    pthread_mutex_lock(&((semaphores + find_semaphore(name))->mutex));
    if ((semaphores + find_semaphore(name))->value - value < SEM_FLAG_CLEAR)
        (semaphores + find_semaphore(name))->value = SEM_FLAG_SET;
    else
        (semaphores + find_semaphore(name))->value -= value;
    pthread_mutex_unlock(&((semaphores + find_semaphore(name))->mutex));
}

int find_semaphore(const char *name) {
    int i;
    for (i = 0; i < semaphore_count; i++) {
        if (!strcmp((semaphores + i)->name, name))
            return i;
    }
    return -1; // Semaphore not found
}

void sem_log(const char *operation, const char *name) {
    printf("Semaphore %s %s.\n", name, operation);
}

int main() {
    int choice = 0;

    while (choice != -1) {
        printf("1. Create semaphore\n");
        printf("2. Delete semaphore\n");
        printf("3. Increment semaphore\n");
        printf("4. Decrement semaphore\n");
        printf("5. Log all semaphore operations and errors.\n");
        printf("-1. Exit program.\n");

        scanf("%d", &choice);

        switch (choice) {
            case 1:
                char name[SEM_MAX_NAME];
                printf("Enter the name of the semaphore: ");
                scanf("%s", name);
                sem_create(name);
                break;
            case 2:
                char name_to_delete[SEM_MAX_NAME];
                printf("Enter the name of the semaphore to delete: ");
                scanf("%s", name_to_delete);
                if (sem_delete(name_to_delete) == -1)
                    printf("Semaphore not found.\n");
                else
                    printf("Semaphore deleted.\n");
                break;
            case 3:
                char name_to_increment[SEM_MAX_NAME];
                int value;
                printf("Enter the name of the semaphore to increment: ");
                scanf("%s", name_to_increment);
                printf("Enter the value to increment by: ");
                scanf("%d", &value);
                sem_increment(name_to_increment, value);
                break;
            case 4:
                char name_to_decrement[SEM_MAX_NAME];
                int decrement_value;
                printf("Enter the name of the semaphore to decrement: ");
                scanf("%s", name_to_decrement);
                printf("Enter the value to decrement by: ");
                scanf("%d", &decrement_value);
                sem_decrement(name_to_decrement, decrement_value);
                break;
            case 5:
                for (int i = 0; i < semaphore_count; i++) {
                    sem_log("created", (semaphores + i)->name);
                    sem_log("incremented", (semaphores + i)->name);
                    sem_log("decremented", (semaphores + i)->name);
                }
                break;
            case -1:
                printf("Exiting program.\n");
                break;
            default:
                printf("Invalid choice. Please try again.\n");
        }
    }

    return 0;
}
