            _cspProvider = cspProvider;
            _cachedKeysAndIvs = new Lazy<CachedKeysAndIvs>(() => new CachedKeysAndIvs(cspProvider));
        }

        public string DecryptMessage(string base64EncodedMessage, string contextId)
        {
            try
            {
                var keysAndIvs = _cachedKeysAndIvs.Value.GetKeysAndIvs(contextId);
                using var tripleDesAlg = TripleDes.Create();
                tripleDesAlg.Key = Encoding.UTF8.GetBytes(keysAndIvs.Key);
                tripleDesAlg.IV = Encoding.UTF8.GetBytes(keysAndIvs.Iv);

                using var memoryStream = new MemoryStream(Convert.FromBase64String(base64EncodedMessage));
                using var cryptoStream = new CryptoStream(memoryStream, tripleDesAlg.CreateDecryptor(), CryptoStreamMode.Read);
                var decryptedBuffer = new byte[memoryStream.Length];
                cryptoStream.Read(decryptedBuffer, 0, decryptedBuffer.Length);

                return Encoding.UTF8.GetString(decryptedBuffer);
            }
            catch (Exception ex)
            {
                LogError(ex);
                throw;
            }
        }

        private void LogError(Exception exception)
        {
            // Implement logging mechanism to log the error
        }

        public void Dispose()
        {
            _cspProvider.Dispose();
            _cachedKeysAndIvs.Value.Dispose();
        }
    }

    public class CachedKeysAndIvs : IDisposable
    {
        private readonly ICspProvider _cspProvider;
        private readonly Dictionary<string, KeysAndIv> _keysAndIvsCache;

        public CachedKeysAndIvs(ICspProvider cspProvider)
        {
            _cspProvider = cspProvider;
            _keysAndIvsCache = new Dictionary<string, KeysAndIv>();
        }

        public KeysAndIv GetKeysAndIvs(string contextId)
        {
            try
            {
                if (!_keysAndIvsCache.TryGetValue(contextId, out var cachedKeysAndIv))
                {
                    cachedKeysAndIv = _cspProvider.GetKeysAndIv(contextId);
                    _keysAndIvsCache[contextId] = cachedKeysAndIv;
                }

                return cachedKeysAndIv;
            }
            catch (Exception ex)
            {
                LogError(ex);
                throw;
            }
        }

        public void Dispose()
        {
            // Implement disposal logic
        }
    }

    public class KeysAndIv
    {
        public byte[] Key { get; set; }
        public byte[] Iv { get; set; }
    }
}
