import os
import logging
from PIL import Image
from io import BytesIO

class ThemeCache:
    def __init__(self, max_cache_size=1000, default_theme_dir='default'):
        self.max_cache_size = max_cache_size
        self.default_theme_dir = default_theme_dir
        self.theme_cache = {}
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)

    def _load_bitmap(self, bitmap_id):
        try:
            with Image.open(os.path.join(self._get_theme_dir(bitmap_id), f"{bitmap_id}.png")) as img:
                return BytesIO(img.tobytes())
        except (FileNotFoundError, OSError) as e:
            self.logger.error(f"Failed to load theme bitmap {bitmap_id}: {e}")
            return None

    def _get_theme_dir(self, bitmap_id):
        try:
            return os.path.join(bitmap_id)
        except Exception as e:
            self.logger.error(f"Failed to determine theme directory for {bitmap_id}: {e}")
            return self.default_theme_dir

    def get_bitmap(self, bitmap_id):
        if bitmap_id in self.theme_cache:
            return self.theme_cache[bitmap_id]
        else:
            img_data = self._load_bitmap(bitmap_id)
            if img_data:
                self.theme_cache[bitmap_id] = img_data
                return img_data
            else:
                return None

    def put_bitmap(self, bitmap_id, img_data):
        if len(self.theme_cache) >= self.max_cache_size:
            oldest_bitmap_id = min(self.theme_cache.keys())
            del self.theme_cache[oldest_bitmap_id]
        self.theme_cache[bitmap_id] = img_data
