#include <openssl/evp.h>
#include <stdlib.h>
#include <string.h>

EVP_CIPHER_CTX *cipher_init(const char *mode, int key_len) {
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;

    // KDF (Key Derivation Function)
    if (key_len > EVP_MAX_KEY_LENGTH) {
        // Key stretching using PBKDF2
        unsigned char derived_key[EVP_MAX_KEY_LENGTH];
        int ret = PKCS5_PBKDF2("password", 8, "salt", 4, 1024, key_len, derived_key);
        if (ret <= 0) return NULL;
    }

    // Select the cipher based on the mode
    switch (strcmp(mode, "ECB")) {
        case 0:
            cipher = EVP_des_ecb();
            break;
        case -8: // EDE
            cipher = EVP_des_ede_cbc();
            break;
        case -9: // EDE3
            cipher = EVP_des_ede3_cbc();
            break;
        case -10: // CFB
            int iv_len = 0;
            printf("Enter IV length (8 or variable): ");
            scanf("%d", &iv_len);
            if (iv_len < 1 || iv_len > EVP_MAX_IV_LENGTH) {
                return NULL; // Invalid IV length
            }
            cipher = EVP_des_cfb(iv_len, 64); // Default block size for CFB
            break;
        default:
            return NULL; // Unknown mode
    }

    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    if (EVP_CipherInit_ex(ctx, cipher, NULL, key_len, NULL) <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}
