public class TripleDesDecryptor : IDisposable
{
    private readonly ICryptoServiceProvider _csp;
    private readonly object _lock = new object();
    private readonly Dictionary<string, TripleDesKey> _keyCache;
    private readonly int _maxConnections;

    public TripleDesDecryptor(ICryptoServiceProvider csp, int maxConnections)
    {
        _csp = csp;
        _keyCache = new Dictionary<string, TripleDesKey>();
        _maxConnections = maxConnections;
    }

    public void Dispose()
    {
        _csp.Dispose();
    }

    public string DecryptMessage(string message, int clearanceLevel, bool useAsyncCsp)
    {
        // Validate message structure
        if (!ValidateMessage(message))
        {
            return "Invalid message format";
        }

        // Get the appropriate key based on clearance level
        TripleDesKey key;
        lock (_lock)
        {
            if (!_keyCache.TryGetValue(clearanceLevel.ToString(), out key) || !key.IsLoaded)
            {
                key = _csp.GetTripleDesKey(clearanceLevel);
                _keyCache.Add(key.ClearanceLevel, key);
            }
        }

        // Decrypt the message
        byte[] decodedBytes;
        if (useAsyncCsp)
        {
            byte[] encryptedBytes = Convert.FromBase64String(message);
            CancellationTokenSource cts = new CancellationTokenSource(TimeSpan.FromSeconds(10));
            try
            {
                decodedBytes = _csp.DecryptAsync(encryptedBytes, key).GetAwaiter().GetResult();
            }
            catch (OperationCanceledException)
            {
                return "Decryption timed out";
            }
        }
        else
        {
            byte[] encryptedBytes = Convert.FromBase64String(message);
            decodedBytes = _csp.DecryptSync(encryptedBytes, key);
        }

        // Log decryption attempt and result
        if (decodedBytes == null)
        {
            Logging.AuditLog("Decryption failed for message: " + message);
            return "Decryption failed";
        }
        else
        {
            Logging.AuditLog("Decrypted message: " + message);
            return Encoding.UTF8.GetString(decodedBytes);
        }
    }

    private bool ValidateMessage(string message)
    {
        // Implement custom validation logic here
        // For example:
        string[] parts = Regex.Split(message, @"[|,;]");
        if (parts.Length < 3 || !int.TryParse(parts[1], out int clearanceLevel))
        {
            return false;
        }
        return true;
    }

    public class TripleDesKey : IDisposable
    {
        public int ClearanceLevel { get; set; }
        public bool IsLoaded { get; set; }
        public string KeyData { get; set; }

        public void Dispose()
        {
            // Implement key disposal logic here
        }
    }
}
