#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/types.h>
#include <pthread.h>

#define BUFFER_SIZE 1024
#define MAX_CONVERSIONS 10

typedef struct {
    char* inputDir;
    char* outputFile;
    int (*progressCallback)(int, void*);
} ConversionContext;

void* convertThread(void* context) {
    ConversionContext* ctx = (ConversionContext*)context;
    DIR* dir = opendir(ctx->inputDir);
    if (!dir) {
        // Error opening directory
        return NULL;
    }

    struct dirent* ent;
    while ((ent = readdir(dir)) != NULL) {
        char filePath[BUFFER_SIZE];
        sprintf(filePath, "%s/%s", ctx->inputDir, ent->d_name);

        int extensionLen = strlen(ent->d_name) - 3; // Get the file name without .jpg extension
        if (strcasecmp(ent->d_name + extensionLen, "jpg") == 0 || strcasecmp(ent->d_name + extensionLen, "jpeg") == 0) {
            char pdfPath[BUFFER_SIZE];
            sprintf(pdfPath, "%s/%s.pdf", ctx->outputFile, ent->d_name);

            FILE* file = fopen(filePath, "rb");
            if (!file) {
                // Error reading file
                continue;
            }

            fclose(file);

            // Call the third-party tool to convert JPEG to PDF here...

            int result = 0; // Assume successful conversion for this example
            ctx->progressCallback(result, ctx);
        }
    }
    closedir(dir);
    return NULL;
}

int convertFiles(const char* inputDir, const char* outputFile, int (*progressCallback)(int, void*)) {
    ConversionContext ctx;
    ctx.inputDir = inputDir;
    ctx.outputFile = outputFile;
    ctx.progressCallback = progressCallback;

    pthread_t threads[MAX_CONVERSIONS];
    for (int i = 0; i < MAX_CONVERSIONS; i++) {
        int result = pthread_create(&threads[i], NULL, convertThread, &ctx);
        if (result) {
            // Error creating thread
            return -1;
        }
    }

    for (int i = 0; i < MAX_CONVERSIONS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
