        std::cerr << "Error converting " << inputFile << ": " << e.what() << '\n';
        return 1; // failed conversion
    }
    return 0; // successful conversion
}

// Function to render JavaScript scripts and convert JPEGs to PDFs
int renderScriptsAndConvertJPEGs(const std::vector<Script>& scripts, const std::string& directoryPath) {
    int failedConversions = 0;
    for (const auto& script : scripts) {
        // Get the file name from the script key
        std::string fileName = script.key;
        if (!fileName.empty() && fileName.back() != '.') {
            fileName += ".jpg";
        }
        // Find the corresponding JPEG file in the directory
        std::ifstream file(directoryPath + "/" + fileName);
        if (!file) {
            std::cerr << "Error: Unable to open file '" << directoryPath + "/" + fileName << "'\n";
            continue;
        }
        // Read the JPEG file content
        std::string imageData((std::istreambuf_iterator<char>(file)), (std::istreambuf_iterator<char>()));

        // Create a corresponding <script> tag with unique key and innerHTML, and append it to the rendered HTML string
        std::string scriptTag = "<script id=\"" + fileName + "\">" + imageData + "</script>";
        std::cout << "Added script: " << scriptTag << '\n';

        // Convert the JPEG file to PDF using the third-party tool
        int conversionResult = convertJPEGToPDF(directoryPath + "/" + fileName, directoryPath + "/" + fileName.substr(0, fileName.find('.')) + ".pdf");
        if (conversionResult) {
            failedConversions++;
        }
    }

    return failedConversions;
}

int main() {
    // Define the input JavaScript scripts and directory path
    std::vector<Script> scripts = {{"script1", "console.log('Hello');"}, {"script2", "document.write('World!')"}};
    const std::string directoryPath = "path/to/jpg/files";

    // Render the scripts and convert JPEGs to PDFs
    int failedConversions = renderScriptsAndConvertJPEGs(scripts, directoryPath);

    return failedConversions;
}
