public class JsonParser {
    private static Map<String, Class<? extends JsonSerializable>> factoryRegistry = new HashMap<>();
    private static Map<String, ObjectMapper> objectMappers = new HashMap<>();
    private static Logger logger = Logger.getLogger(JsonParser.class.getName());

    public static void main(String[] args) throws IOException {
        initFactoryRegistry();
        startService();
