        File factoryFile = new File("factory_functions.json");
        ObjectMapper mapper = new ObjectMapper(new JsonMapper());
        JsonNode root = mapper.readTree(factoryFile);
        for (JsonNode node : root) {
            String id = node.get("id").asText();
            Class<? extends JsonSerializable> clazz = (Class<? extends JsonSerializable>) Class.forName(node.get("class").asText());
            factoryRegistry.put(id, clazz);
        }
    }

    private static void startService() throws InterruptedException {
        while (true) {
            Random random = new Random();
            int delay = random.nextInt(10000); // 0-10 seconds
            Thread.sleep(delay);

            try {
                startServiceNow();
            } catch (Exception e) {
                logger.error("Error starting service", e);
                stopService();
            }
        }
    }

    private static void startServiceNow() throws Exception {
        // Start service logic here
    }

    private static void stopService() {
        // Stop service logic here
    }
}
