        char* processedString = malloc(strlen(inputString));
        if(userSettings->trimFlag && userSettings->capitalizeFlag) {
            // Trim and capitalize the input string
            processedString = trimAndCapitalize(inputString);
        } else {
            // Copy the original input string
            strcpy(processedString, inputString);
        }

        // Set the processed string as the CURLOPT_POSTFIELDS
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, processedString);

        // Perform the CURL request
        res = curl_easy_perform(curl);

        // Check for errors and handle API rate limiting
        if(res != CURLE_OK) {
            // Handle API rate limiting or network failures
            printf("Failed to fetch user settings: %s\n", curl_easy_strerror(res));
        } else {
            // Process the response from the API
            char* response = malloc(1024);
            res = curl_easy_perform(curl, &response);
            if(res != CURLE_OK) {
                printf("Failed to process response: %s\n", curl_easy_strerror(res));
            } else {
                printf("User settings processed successfully: %s\n", response);
                free(response);
            }
        }

        // Free CURL resources
        curl_easy_cleanup(curl);

        // Free memory allocated for the processed string
        free(processedString);
    }

    return NULL;
}

