use std::fs;
use std::path::{Path, PathBuf};
use std::process;
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use log::{info, warn, error};
use serde::{Deserialize, Serialize};

#[derive(Serialize, Deserialize)]
struct Config {
    max_directories: u32,
    cleanup_interval: u64,
}

fn create_directory(name: &str) -> Result<PathBuf, Box<dyn std::error::Error>> {
    let path = Path::new("path").join(name);
    fs::create_dir(&path)?;
    Ok(path)
}

fn set_environment_variable(var_name: &str, dir_path: &Path) -> Result<(), Box<dyn std::error::Error>> {
    use std::process::Command;
    Command::new("setenv")
        .arg(var_name)
        .arg(dir_path.to_str())
        .run()?;
    Ok(())
}

fn main() {
    let config_file = "config.json";
    let mut config = Config::deserialize_from_file(config_file).unwrap();

    let dir_map: Arc<Mutex<HashMap<String, PathBuf>>> = Arc::new(Mutex::new(HashMap::new()));
    let (tx, rx) = std::sync::mpsc::channel();
    std::thread::spawn(move || {
        loop {
            thread::sleep(std::time::Duration::from_millis(config.cleanup_interval));
            let mut dir_map_copy = dir_map.lock().unwrap().clone();
            for (name, path) in dir_map_copy.iter() {
                if !rx.try_recv().is_ok() {
                    fs::remove_dir(path)?;
                    info!("Deleted directory: {}", path.to_str());
                }
            }
        }
    });

    let config_clone = config.clone();
    std::thread::spawn(move || {
        loop {
            thread::sleep(std::time::Duration::from_millis(config_clone.cleanup_interval));
            let mut dir_map_copy = dir_map.lock().unwrap().clone();
            for (name, path) in dir_map_copy.iter() {
                if !rx.try_recv().is_ok() {
                    fs::remove_dir(path)?;
                    info!("Deleted directory: {}", path.to_str());
                }
            }
        }
    });

    loop {
        let mut input = String::new();
        println!("Enter a directory name to create:");
        std::io::stdin().read_line(&mut input).unwrap();
        let dir_name = input.trim();
        match create_directory(dir_name) {
            Ok(path) => {
                *dir_map.lock().unwrap().entry(dir_name.to_string()).or_insert(path.clone());
                set_environment_variable("PATH", &path)?;
                info!("Created directory: {}", path.to_str());
            },
            Err(e) => {
                error!("Error creating directory: {}", e);
                process::exit(1);
            }
        }
    }
}
