    public XmlNode GetXmlNode(string xpathQuery)
    {
        string configFilePath = LoadConfigFile();
        string xmlFilePath = LoadXmlFilePathFromConfig(configFilePath);
        XmlDocument document;
        if (_cache.TryGetValue(xmlFilePath, out document))
        {
            return ParseXPathQuery(document, xpathQuery);
        }
        else
        {
            try
            {
                document = LoadXmlDocument(xmlFilePath);
                _cache.Add(xmlFilePath, document);
                return ParseXPathQuery(document, xpathQuery);
            }
            catch (Exception ex)
            {
                throw new Exception("Error parsing XML document", ex);
            }
        }
    }

    private XmlDocument LoadXmlDocument(string filePath)
    {
        using (FileStream stream = File.OpenRead(filePath))
        {
            return new XmlDocument();
        }
    }

