    {
        // load config file logic here
    }

    private XmlNode ParseXPathQuery(XmlDocument document, string xpathQuery)
    {
        XPathNavigator navigator = document.CreateNavigator();
        try
        {
            XPathNodeIterator nodes = navigator.Select(xpathQuery);
            if (!nodes.MoveNext())
            {
                throw new Exception("No elements found with the given name");
            }
            else if (nodes.Count > 1)
            {
                throw new Exception("Multiple elements found with the given name");
            }
            return nodes.Current as XmlNode;
        }
        catch (Exception ex)
        {
            throw new Exception("Error parsing XPath query", ex);
        }
    }

