class JSONBase:
    _registry = {}
    _registry_lock = threading.Lock()

    @classmethod
    def get_registry(cls):
        return cls._registry

    @classmethod
    def register_factory(cls, factory_func):
        with cls._registry_lock:
            if not hasattr(factory_func, '__qualname__'):
                raise ValueError("Factory function must have a __qualname__ attribute")
            cls._registry[factory_func.__qualname__] = factory_func

    @classmethod
    def discover_subclasses(cls, directory):
        for file in os.listdir(directory):
            if file.endswith('.py') and not file.startswith('__'):
                try:
                    module = importlib.import_module(f"{file[:-3]}")
                    subclass = getattr(module, 'JSONBaseSubclass', None)
                    if subclass:
                        cls.register_factory(subclass.create_instance)
                except ImportError as e:
                    logging.error(f"Error importing {file}: {e}")
