char* dynamicTrimAndCapitalize(char* input) {
    // Fetch the list of words to be trimmed
    Word* word_list = get_word_list(input);
    if (!word_list) return NULL;

    // Calculate the adjusted size limit based on the length of the fetched word list and average word length
    int adjusted_size_limit = 0;
    for (int i = 0; i < strlen(input); i++) {
        Word* current_word = &word_list[i];
        adjusted_size_limit += current_word->length + 1; // add 1 for space between words
    }

    // Trim the specified words from the beginning and end of the input string
    char* trimmed_input = (char*)malloc((strlen(input) - word_list[0]->length) * sizeof(char));
    strcpy(trimmed_input, &input[word_list[0]->length]);
    int remaining_size = strlen(trimmed_input);
    for (int i = 1; i < strlen(input); i++) {
        if (!strchr(&trimmed_input[0], ' ') && remaining_size >= word_list[i]->length) {
            trimmed_input = (char*)realloc(trimmed_input, (remaining_size - word_list[i]->length + 1) * sizeof(char));
            strcpy(trimmed_input, &trimmed_input[word_list[i]->length]);
        } else break;
    }

    // Capitalize the first letter of each word in the resulting string
    for (int i = 0; i < remaining_size; i++) {
        if (i == 0 || trimmed_input[i - 1] == ' ') {
            trimmed_input[i] = toupper(trimmed_input[i]);
        }
    }

    // Check if the total length exceeds the adjusted size limit
    if (remaining_size > adjusted_size_limit) return NULL;

    return trimmed_input;
}

