const semaphore = require('semaphore');
const { setTimeout } = require('timers');

function asyncArrayReduce(arr, initialValue, callback) {
  const cache = {};
  let accumulatedValue = initialValue;
  let completedOperations = 0;

  const throttleTimeout = () => {
    return new Promise(resolve => setTimeout(() => resolve(), 100));
  };

  const reduceAsync = (index) => {
    if (!arr[index]) return;

    const currentValue = arr[index];
    const accumulatorFunc = callback.bind(null, accumulatedValue, currentValue);
    semaphore.acquire((err, available) => {
      if (err) throw err;
      if (available < 5) { // control concurrency level
        reduceAsync(index + 1);
      } else {
        throttleTimeout().then(() => {
          const result = accumulatorFunc();
          accumulatedValue = result[0];
          completedOperations = result[1];

          semaphore.release();

          if (index === arr.length - 1) {
            callback(null, accumulatedValue);
          } else {
            reduceAsync(index + 1);
          }
        });
      }
    });
  };

  reduceAsync(0);

  return { value: accumulatedValue, completedOperations };
}
