    this.dependencies = [];
    this.loadingFiles = [];
    this.configured = false;

    if (configPath) {
      this.loadConfig(configPath);
    }
  }

  async loadConfig(configPath) {
    try {
      const configData = await fs.promises.readFile(configPath, 'utf8');
      this.config = JSON.parse(configData);

      if (!this.config || !Array.isArray(this.config.modules)) {
        throw new Error('Invalid configuration file');
      }

      this.configured = true;
    } catch (error) {
      console.error(`Error loading config: ${error.message}`);
    }
  }

  async start() {
    if (!this.configured) return;

    for await (const module of this.config.modules) {
      await this.loadModule(module);
    }
  }

  async loadModule(module) {
    const { path, dependencies } = module;
    const fileUrl = new URL(path, import.meta.url);

    if (this.cache[path]) {
      // If the file is cached and up-to-date, use it
      return this.executeModule(this.cache[path]);
    }

    // Check for cache invalidation
    if (this.dependencies.includes(module.path)) {
      await this.invalidateCache(module.path);
    }

    try {
      const response = await https.get(fileUrl);

      if (!response.ok) {
        throw new Error(`Failed to load file: ${fileUrl}`);
      }

      const fileContent = await response.text();
      this.cache[path] = fileContent;

      // Execute the module
      return this.executeModule(fileContent);
    } catch (error) {
      console.error(`Error loading file: ${fileUrl} - ${error.message}`);
    }
  }

  async executeModule(moduleCode) {
    try {
      // Try to execute the module
      await new Function('return ' + moduleCode)();

      return true;
    } catch (error) {
      console.error(`Error executing module: ${module.path} - ${error.message}`);
      return false;
    }
  }

  async invalidateCache(filePath) {
    const fileTime = await fs.promises.stat(filePath).mtimeMs;

    for (const [file, timestamp] of Object.entries(this.cache)) {
      if (+timestamp > fileTime) this.cache[file] = null;
    }
  }

  getCacheStatus() {
    return `Loaded files: ${Object.keys(this.cache).length} - Cached: ${JSON.stringify(this.cache)}`
  }
}

// Example usage:
const moduleLoader = new ModuleLoader('config.json');
moduleLoader.start();
console.log(moduleLoader.getCacheStatus());
