function handle_user_request() {
    $db = new mysqli("localhost", "username", "password", "database");
    if ($db->connect_error) {
        return json_encode(['message' => 'error', 'error' => 'Database connection failed']);
    }

    $request = $_REQUEST;
    $sub_action = $request['sub_action'] ?? null;
    $id = $request['id'] ?? null;
    $name = $request['name'];
    $email = $request['email'];
    $password = $request['password'];
    $confirm_password = $request['confirm_password'];

    if ($sub_action === 'delete') {
        if (!$id) {
            return json_encode(['message' => 'error', 'error' => 'No ID provided']);
        }

        $query = "DELETE FROM users WHERE id = ?";
        $stmt = $db->prepare($query);
        $stmt->bind_param('i', $id);
        $stmt->execute();
        $stmt->close();
        return json_encode(['message' => 'success']);
    }

    if ($sub_action === 'create') {
        if (!$name || !$email || !$password || !$confirm_password) {
            return json_encode(['message' => 'error', 'error' => 'All fields are required']);
        }

        if ($password !== $confirm_password) {
            return json_encode(['message' => 'error', 'error' => 'Passwords do not match']);
        }

        // Validate email
        $query = "SELECT COUNT(*) AS count FROM users WHERE email = ?";
        $stmt = $db->prepare($query);
        $stmt->bind_param('s', $email);
        $stmt->execute();
        $result = $stmt->get_result();
        $count = $result->fetch_assoc()['count'];

        if ($count > 0) {
            return json_encode(['message' => 'error', 'error' => 'Email already exists']);
        }

        // Save data
        $query = "INSERT INTO users (name, email, password) VALUES (?, ?, ?)";
        $stmt = $db->prepare($query);
        $stmt->bind_param('ssi', $name, $email, md5($password));
        $stmt->execute();
        $stmt->close();

        return json_encode(['message' => 'success']);
    }

    if ($sub_action === 'update') {
        if (!$id || !$name || !$email) {
            return json_encode(['message' => 'error', 'error' => 'All fields are required']);
        }

        // Validate email
        $query = "SELECT COUNT(*) AS count FROM users WHERE email = ? AND id != ?";
        $stmt->bind_param('ssi', $email, $id);
        $result = $stmt->get_result();
        $count = $result->fetch_assoc()['count'];

        if ($count > 0) {
            return json_encode(['message' => 'error', 'error' => 'Email already exists']);
        }

        // Save data
        $query = "UPDATE users SET name = ?, email = ? WHERE id = ?";
        $stmt->bind_param('ssi', $name, $email, $id);
        $stmt->execute();
        $stmt->close();

        return json_encode(['message' => 'success']);
    }

    return json_encode(['message' => 'error', 'error' => 'Invalid request']);
}

db_close($db); // Closing the database connection
