import re
import os
import hashlib
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
try:
    from cryptography.hazmat.backends import default_backend
except ImportError as e:
    print(f"Error importing cryptography library: {e}")

class CryptoConfig:
    def __init__(self):
        self.config = {}

    def read_config(self, filename):
        try:
            with open(filename, 'r') as f:
                for line in f:
                    match = re.match(r'(\w+):(.*)', line.strip())
                    if match:
                        name, func_or_cipher = match.groups()
                        if 'hash' in func_or_cipher:
                            self.config[name] = {'name': name, 'function': getattr(hashlib, func_or_cipher)}
                        elif 'cipher' in func_or_cipher:
                            algo, mode = func_or_cipher.split(' ')
                            algo = algorithms.get_algorithm(algo)
                            self.config[name] = {'name': name, 'algorithm': algo, 'mode': modes.get_mode(mode), 'backend': default_backend()}
        except FileNotFoundError as e:
            print(f"Error reading config file: {e}")
        except Exception as e:
            print(f"Unexpected error: {e}")

    def sort_and_get_last_sequence(self):
        sorted_names = sorted(self.config.keys())
        last_entry = self.config[sorted_names[-1]]
        return last_entry.get('sequence_number', None)

def main():
    config = CryptoConfig()
    config.read_config('config.txt')
    print(config.sort_and_get_last_sequence())

if __name__ == "__main__":
    main()

