import os
import threading
import logging

def set_user_config_dir(parent_dir=None, max_retries=3):
    user_config_dir = os.environ.get('USER_CONFIG_DIR')

    if not user_config_dir:
        parent_dir_path = os.path.join(os.getenv('APPDATA') if 'win32' in os.name else os.path.expanduser('~/.config'), 'user_settings')

        def create_dir(path):
            for _ in range(max_retries):
                try:
                    os.makedirs(path)
                    break
                except PermissionError as e:
                    logging.warning(f"Permission error creating directory '{path}' - retrying...")
                    continue
                except Exception as e:
                    logging.error(f"An unexpected error occurred: {e}")
                    return False
            return True

        if not parent_dir:
            parent_dir_path = os.path.abspath(parent_dir_path)
        else:
            parent_dir_path = os.path.join(os.path.abspath(parent_dir), 'user_settings')

        if create_dir(parent_dir_path):
            user_config_dir = parent_dir_path
        else:
            logging.error(f"Failed to create directory '{parent_dir_path}' after {max_retries} retries")

    return user_config_dir
