function refreshDialogFields(fieldNames, resourceId, url) {
  const cache = {};
  const messages = [];

  async function refreshField(fieldName) {
    try {
      const response = await fetch(`${url}/${resourceId}/${fieldName}`);
      const data = await response.json();
      const success = true;
      messages.push({ fieldName, success });
      return { data, success };
    } catch (error) {
      console.error(`Error refreshing field ${fieldName}:`, error);
      const success = false;
      messages.push({ fieldName, success });
      return { data: null, success };
    }
  }

  async function refreshFields() {
    for (const fieldName of fieldNames) {
      if (!cache[fieldName]) {
        const result = await refreshField(fieldName);
        cache[fieldName] = result.data;
      } else {
        messages.push({ fieldName, success: true });
      }
    }
  }

  async function sendMessages() {
    for (const message of messages) {
      postMessage(message);
    }
  }

  async function updateFields() {
    for (const message of messages) {
      if (message.success) {
        // Update the corresponding dialog field with the refreshed data
      } else {
        console.error(`Failed to refresh field ${message.fieldName}`);
      }
    }
  }

  async function main() {
    await refreshFields();
    await sendMessages();
    await updateFields();
  }

  main().then(() => {
    // Log refresh attempts and outcomes for debugging and monitoring purposes
  });
}

