const asyncReduce = (arr, initValue, callback) => {
  const convertToStrings = arr.map((num) =>
    typeof num === 'number' ? num.toString() : num
  );
  const stringArray = convertToStrings.filter((str) => str.includes('.'));

  if (stringArray.length > 0) {
    return Promise.reject('Error: Array contains non-numeric values');
  }

  let accumulator = initValue;
  let parallelOperations = 5; // rate-limiting feature
  let ongoingOperations = 0;
  let results = [];

  const processChunk = (chunk, callback) => {
    chunk.forEach((num) => {
      if (ongoingOperations >= parallelOperations) {
        setTimeout(() => {
          processChunk(chunk, callback);
        }, 10); // introduce a delay to avoid CPU strain
      } else {
        ongoingOperations++;
        const result = callback(accumulator, parseInt(num));

        if (!result) {
          return Promise.reject('Error: Callback returned undefined');
        }

        accumulator = result;
        results.push(result);
        ongoingOperations--;

        if (ongoingOperations === 0) {
          setTimeout(() => {
            console.log('Reduction complete:', accumulator);
          }, 10); // log the final result after processing
        }
      }
    });
  };

  const startProcessing = () => {
    let i = 0;

    processChunk(convertToStrings, (acc, num) => {
      i++;
      console.log(`Processing element ${i} out of ${convertToStrings.length}`);

      return acc + parseInt(num);
    })
      .then(() => accumulator)
      .catch((error) => Promise.reject(error));
  };

  startProcessing();
};

// Example usage:
asyncReduce([1, 2, '3', 4, 5], 0, (acc, num) => {
  return acc + parseInt(num);
})
  .then((result) => console.log('Final result:', result))
  .catch((error) => console.error(error));
