const AWS = require('aws-sdk');
const fs = require('fs');
const { promisify } = require('util');

// Initialize AWS S3 with your credentials
AWS.config.update({
    accessKeyId: 'YOUR_ACCESS_KEY',
    secretAccessKey: 'YOUR_SECRET_KEY',
    region: 'YOUR_REGION'
});

const s3 = new AWS.S3({ signatureVersion: 'v4' });
const bucketName = 'YOUR_BUCKET_NAME';

// Helper function to upload a file in chunks
async function uploadFile(file, key) {
    const partSize = 10 * 1024 * 1024; // 10 MB
    const chunkCount = Math.ceil(file.size / partSize);

    for (let i = 0; i < chunkCount; i++) {
        const start = i * partSize;
        const end = Math.min(start + partSize, file.size);
        const chunk = file.slice(start, end);

        try {
            await s3.upload({
                Bucket: bucketName,
                Key: key,
                PartNumber: i + 1,
                UploadId: '',
                Body: chunk
            }).promise();
        } catch (error) {
            console.error(error);
            // Fallback strategy for interrupted uploads
            if (i < chunkCount - 1) {
                await uploadFile(file, key);
                return;
            }
            throw error;
        }
    }

    try {
        await s3.completeMultipartUpload({
            Bucket: bucketName,
            Key: key,
            UploadId: '',
            MultipartUpload: {
                Parts: Array(chunkCount).fill(0).map((_, i) => ({
                    ETag: chunk.hash(),
                    PartNumber: i + 1
                }))
            }
        }).promise();
    } catch (error) {
        console.error(error);
        throw error;
    }

    return `https://${bucketName}.s3.amazonaws.com/${key}`;
}

// Main upload function that handles file and URL validation
async function cloudStorageUpload(file, url) {
    if (!file || !url) {
        throw new Error('Invalid file or URL');
    }

    // Validate the file type (e.g., images, documents)
    const allowedMimeTypes = ['image/jpeg', 'application/pdf'];
    if (!allowedMimeTypes.includes(file.type)) {
        throw new Error(`Unsupported file type: ${file.type}`);
    }

    try {
        // Get the file contents
        const fileBuffer = await fs.promises.readFile(url);

        // Generate a unique key for the uploaded file
        const key = `${Date.now()}-${Math.random().toString(36).substr(2, 9)}${url.split('/').pop()}`;

        return uploadFile(fileBuffer, key);
    } catch (error) {
        console.error(error);
        throw error;
    }
}

module.exports = cloudStorageUpload;
