#include <openssl/rsa.h>
#include <openssl/pem.h>
#include <openssl/aes.h>

// Function to initialize RSA context with given private key file and password
void rsa_init(char* priv_key_file, char* password) {
    // Load the private key from file
    FILE* key_file = fopen(priv_key_file, "rb");
    if (!key_file) {
        printf("Error opening private key file\n");
        return;
    }
    PEM_read_RSAPrivateKey(key_file, NULL, NULL, NULL);
    fclose(key_file);

    // Securely derive the encryption and decryption keys from the password
    EVP_BytesToKey(EVP_aes_256_cfb8(), EVP_sha256(), password, password, strlen(password), 32, key->private_key, key->private_key_len);

    // Enable PKCS1 OAEP padding scheme
    RSA_set_padding_callback(key, RSA_PKCS1_OAEP_MGF1);
}

// Function to clean up and disable the RSA context when it is no longer needed
void rsa_free(RSA* key) {
    // Free allocated memory for private key
    if (key->private_key) free(key->private_key);
    RSA_free(key);
}

// Example usage:
int main() {
    char* priv_key_file = "path/to/private/key.pem";
    char* password = "your_password";

    RSA* key = RSA_new();
    rsa_init(priv_key_file, password);

    // Use the RSA context for encryption/decryption operations

    rsa_free(key);
}
