import heapq
import io
from typing import List, Union

def merge_sorted_lists(*lists: List[Union[int, float]]) -> List[int]:
    if not all(isinstance(lst, list) for lst in lists):
        raise ValueError("Input must be a variable number of lists")

    for lst in lists:
        if len(set(map(int, lst))) != len(lst):
            raise ValueError("Each input list must contain only integers")

        for val in lst:
            if not isinstance(val, int):
                raise ValueError("Each input list must contain only integers")

    heapq.heapify([iter(lst) for lst in lists])

    result = []

    while any(heap):
        current_min = [next(iter(h)) for h in heapq.nsmallest(1, heapq.heappop() for h in heapq.heappop())]

        if not isinstance(current_min[0], int):
            raise ValueError("Input list contains non-integer values")

        result.append(current_min[0])

    return result
