const express = require('express');
const app = express();
const { createClient } = require('@supabase/supabase-js');
const supabaseUrl = process.env.SUPABASE_URL;
const supabaseKey = process.env.SUPABASE_KEY;

// Initialize Supabase client
const supabase = createClient(supabaseUrl, supabaseKey);

// Define regex pattern for Old Testament book names (ignoring punctuation and special characters)
const otRegex = new RegExp('^(?:(Amos|Ezra|Esther|Exodus|Genesis|Habakkuk|Haggai|Hosea|Isaiah|Jeremiah|Job|Joshua|Judges|Kings|Leviticus|Malachi|Micah|Numbers|Obadiah|Psalms|Ruth|SongOfSolomon|Zechariah|Zephaniah)(?!.*\\s))$');

// Define API endpoint for processing text data
app.post('/process', async (req, res) => {
  const { body } = req;

  // Check input format and validate data
  if (!body || typeof body !== 'string') {
    return res.status(400).send({ error: 'Invalid input format' });
  }

  try {
    // Extract Old Testament book names from text data using regex
    const otBookNames = body.match(otRegex);

    // Get list of Old Testament books from Supabase
    const { data } = await supabase.from('ot_books').select('*');

    // Count occurrences of each Old Testament book name in the processed data
    const counts = {};
    if (Array.isArray(otBookNames)) {
      for (const bookName of otBookNames) {
        if (!counts[bookName]) {
          counts[bookName] = 1;
        } else {
          counts[bookName]++;
        }
      }
    }

    // Return object containing the count of each Old Testament book name found
