Here is the C code for the `loadResourceBundle` function:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <err.h>

#define MAX_LINE_LENGTH 1024
#define MAX_BUNDLE_ITEMS 1000

struct resource_bundle {
    int size;
    char **keys;
    void **values;
};

int loadResourceBundle(const char *path) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        err(1, "Failed to open file: %s", path);
    }

    struct resource_bundle *bundle = malloc(sizeof(struct resource_bundle));
    if (!bundle) {
        fclose(fp);
        err(1, "Memory allocation failed for bundle");
    }

    bundle->size = 0;
    bundle->keys = malloc(MAX_BUNDLE_ITEMS * sizeof(char *));
    bundle->values = malloc(MAX_BUNDLE_ITEMS * sizeof(void **));

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, fp)) {
        char *key_end = strchr(line, '=');
        if (!key_end) {
            fclose(fp);
            free(bundle);
            err(1, "Invalid data format: %s", path);
        }
        *key_end = '\0';
        bundle->keys[bundle->size] = strdup(strstrip(line));
        char *value_start = key_end + 1;
        if (*value_start == '"') {
            // string value
            size_t length = strlen(value_start) - 2;
            bundle->values[bundle->size] = malloc((length + 1) * sizeof(char));
            strcpy(bundle->values[bundle->size], value_start + 1);
        } else if (isdigit(*value_start)) {
            // int or float value
            size_t length = strlen(value_start);
            bundle->values[bundle->size] = malloc((length + 1) * sizeof(char));
            strcpy(bundle->values[bundle->size], value_start);
        } else {
            fclose(fp);
            free(bundle);
            err(1, "Invalid value format: %s", path);
        }
        bundle->size++;
    }

    fclose(fp);

    return bundle->size;
}

void *get_resource_value(struct resource_bundle *bundle, const char *key) {
    // implement this function to retrieve a value from the bundle
}
