use std::env;
use std::fs;
use std::path::Path;

fn create_directory_and_set_env_var(directory_name: &str) -> Result<(), String> {
    let path = Path::new(directory_name);
    if path.exists() {
        // directory already exists, return immediately
        return Ok(());
    }

    fs::create_dir_all(path)?;
    env::set Var("MY_VAR", &path.display().to_string())?;

    Ok(())
}
