```java
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;

import java.io.IOException;
import java.util.*;

public class JsonExtractor {

    private Map<String, Object> cache = new HashMap<>();
    private ObjectMapper mapper = new ObjectMapper();

    public String extractData(String jsonPath) {
        try {
            JsonNode node = mapper.readTree(jsonPath);
            return extractDataRecursive(node, null);
        } catch (IOException e) {
            return "Error parsing JSON: " + e.getMessage();
        }
    }

    private String extractDataRecursive(JsonNode node, List<String> path) {
        if (!node.isContainer()) {
            return node.toString();
        }

        for (String key : node.fieldNames()) {
            JsonNode child = node.get(key);
            List<String> newPath = new ArrayList<>(path == null ? Collections.singletonList(key) : path);
            newPath.add(key);

            String result = extractDataRecursive(child, newPath);
            if (!result.isEmpty()) {
                return result;
            }
        }

        return "";
    }

    public void cacheResult(String jsonPath, String result) {
        cache.put(jsonPath, result);
    }

    public String getCachedResult(String jsonPath) {
        return (String) cache.getOrDefault(jsonPath, "");
    }

