import os
import concurrent.futures
from contextlib import closing

def merge_files(file_paths, dest_path):
    with open(dest_path, 'wb') as out_file:
        with closing(concurrent.futures.ThreadPoolExecutor()) as executor:
            futures = [executor.submit(read_file, file) for file in file_paths]

            while True:
                done, pending = concurrent.futures.wait(futures, return_when=concurrent.futures.FIRST_COMPLETED)

                for future in done:
                    try:
                        chunk = future.result()
                    except Exception as e:
                        print(f"Error reading file: {str(e)}")
                        continue

                    if not chunk:
                        break

                for future in pending:
                    future.cancel()

                if len(done) == len(file_paths):
                    break

            out_file.write(b'\0'.join(chunk))
