```csharp
using System;
using UnityEngine;

public class RandomValueGenerator
{
    private float _minValue;
    private float _maxValue;
    private int _generationCount = 0;
    private readonly object _syncLock = new object();

    public RandomValueGenerator(float minValue, float maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Min value must be less than or equal to Max value");

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(_minValue, _maxValue + 1);
    }

    public int GetRandomInt()
    {
        return (int)GetRandomFloat();
    }

    public List<int> GetUniqueRandomInts(int n)
    {
        if (n > (_maxValue - _minValue) || n < 0)
            throw new ArgumentException("Number of random integers exceeds the range size or is less than 0");

        HashSet<int> uniqueValues = new HashSet<int>();
        while (uniqueValues.Count < n)
        {
            int value = GetRandomInt();
            if (_minValue <= value && value <= _maxValue)
                uniqueValues.Add(value);
            else
                Interlocked.Increment(ref _generationCount);
        }
        return new List<int>(uniqueValues);
    }

    public override string ToString()
    {
        return $"Random Value Generator: Min={_minValue}, Max={_maxValue}";
    }
}
