import urllib.request
from urllib.parse import urlparse
from hashlib import md5

class Script:
    def __init__(self, id, src, fallback):
        self.id = id
        self.src = src
        self.fallback = fallback

def generate_footer(scripts, cache={}):
    footer = '<footer>'
    for script in scripts:
        if md5(script.src.encode()).hexdigest() in cache:
            content = cache[md5(script.src.encode()).hexdigest()]
        else:
            try:
                response = urllib.request.urlopen(script.src)
                content = response.read().decode()
                cache[md5(script.src.encode()).hexdigest()] = content
            except Exception as e:
                print(f"Error loading script {script.id}: {e}")
                content = script.fallback

        footer += f'<script id="{script.id}" src="data:text/html;base64,{content.encode().decode("utf-8", "replace")}" type="text/javascript"></script>'
    footer += '</footer>'
    return footer
