    private readonly ICspProvider _backupCsp;
    private readonly object _lock = new object();
    private readonly Dictionary<string, X509Certificate2> _caches = new();
    private readonly int _maxConcurrentOperations;

    public AsynchronousDataDecryptor(ICspProvider primaryCsp, ICspProvider backupCsp)
    {
        _primaryCsp = primaryCsp;
        _backupCsp = backupCsp;
        _maxConcurrentOperations = Environment.GetEnvironmentVariable("MAX_CONCURRENT_OPERATIONS") == null ? 10 : int.Parse(Environment.GetEnvironmentVariable("MAX_CONCURRENT_OPERATIONS"));
