            throw new ArgumentNullException(nameof(base64EncodedMessage));

        await ValidateMessageStructure(base64EncodedMessage);

        try
        {
            X509Certificate2 key;
            lock (_lock)
            {
                if (!_caches.TryGetValue(clearanceLevel.ToString(), out key))
                {
                    key = FetchKey(_primaryCsp, clearanceLevel);
                    _caches.Add(clearanceLevel.ToString(), key);
                }
            }

            return DecryptMessageInternal(base64EncodedMessage, key);
        }
        catch (Exception ex)
        {
            await LogDecryptionError(ex);
            throw;
        }
