import re
import heapq
from collections import deque

class LogAnalyzer:
    def __init__(self):
        self.buffer = deque(maxlen=1000)
        self.total_entries = 0
        self.filtered_entries = 0
        self.successful_requests = 0

    def process_log_entry(self, entry):
        # Implement logic to filter log entries based on request method, user agent, referrer, request path, and response status code
        if re.match(r"GET|POST", entry["method"]):
            if "User-Agent" in entry and "referrer" in entry:
                if re.match(r"/path.*", entry["request_path"]):
                    if entry["response_status_code"] == 200:
                        self.successful_requests += 1
        return True

    def analyze_log_file(self, log_file_path):
        try:
            with open(log_file_path, "r") as file:
                for line in file:
                    entry = re.split(r"\s+", line.strip())
                    if len(entry) == 10 and all(isinstance(x, str) for x in entry):
                        self.buffer.append({"timestamp": int(entry[0]), "method": entry[3], "user_agent": entry[5], "referrer": entry[6], "request_path": entry[7], "response_status_code": int(entry[8]), "response_size": int(entry[9])})
                        if not self.process_log_entry(dict(zip(["timestamp", "method", "user_agent", "referrer", "request_path", "response_status_code", "response_size"], entry))):
                            break
                    else:
                        continue
            self.total_entries = len(self.buffer)
            self.filtered_entries = sum(1 for x in self.buffer if self.process_log_entry(x))
        except (IOError, TypeError):
            print("Error processing log file")
        finally:
            return max((x["response_size"], x) for x in self.buffer), self.buffer[0]["timestamp"]

    def adjust_buffer_size(self, current_processing_load):
        # Implement logic to dynamically adjust the size of the rolling buffer based on the current processing load
        if current_processing_load > 50:
            self.buffer = deque(maxlen=self.buffer.maxlen * 2)
        elif current_processing_load < 10:
            self.buffer = deque(maxlen=self.buffer.maxlen // 2)

    def get_log_entry_metrics(self):
        return {"total_entries": self.total_entries, "filtered_entries": self.filtered_entries, "successful_requests_percentage": (self.successful_requests / self.total_entries) * 100}
