import hashlib
import os
import boto3
from logging import Logger

class MD5Calculator:
    def __init__(self, s3_bucket_name: str):
        self.s3 = boto3.client('s3', region_name='your-region')
        self.logger = Logger('file_hash_calculator')

    def calculate_md5(self, file_path: str) -> str:
        md5_hash = hashlib.md5()

        if not os.path.exists(file_path):
            try:
                self.s3.download_file('your-bucket-name', file_path.split('/')[-1], file_path)
            except Exception as e:
                self.logger.error(f"Failed to download the file: {e}")
                return ""

        with open(file_path, 'rb') as f:
            chunk = f.read(8192)  # Read in chunks of 8KB
            while chunk:
                md5_hash.update(chunk)
                chunk = f.read(8192)

        return md5_hash.hexdigest()
