import json
from threading import Lock
from flask import Flask, request, jsonify
from flask_cors import CORS
import requests

app = Flask(__name__)
CORS(app)

# Initialize the property management system connection
property_management_system_url = 'https://example.com/api'
pm_connection = None

# Initialize the graph database
graph_db = {}

# Lock for concurrent updates
lock = Lock()

@app.route('/config', methods=['POST'])
def process_config():
    try:
        config_json = request.get_json()
        if not config_json:
            return jsonify({'error': 'Invalid JSON configuration'}), 400

        for operation in config_json['operations']:
            if operation['type'] == 'add_vertex':
                add_vertex(operation)
            elif operation['type'] == 'add_edge':
                add_edge(operation)
            elif operation['type'] == 'set_property':
                set_property(operation)

        return jsonify({'status': 'Configuration processed successfully'})
    except Exception as e:
        app.logger.error(f'Error processing configuration: {str(e)}')
        return jsonify({'error': str(e)}), 500

def add_vertex(vertex_config):
    vertex_id = vertex_config['id']
    graph_db[vertex_id] = {'vertices': [], 'edges': []}

    # Set properties for the newly added vertex
    set_properties(vertex_id, vertex_config.get('properties'))

def add_edge(edge_config):
    source_vertex_id = edge_config['source']
    target_vertex_id = edge_config['target']

    with lock:
        if source_vertex_id not in graph_db or target_vertex_id not in graph_db:
            raise Exception(f'One or both vertices do not exist')

        if edge_config['type'] == 'UNDIRECTED':
            # Add an undirected edge
            for vertex_id in [source_vertex_id, target_vertex_id]:
                if vertex_id not in graph_db[vertex_id]['vertices']:
                    graph_db[vertex_id]['vertices'].append(vertex_id)
                if source_vertex_id != target_vertex_id:
                    add_edge_to_vertex(vertex_id, target_vertex_id)

        else:  # DIRECTED
            # Add a directed edge
            add_edge_to_vertex(source_vertex_id, target_vertex_id)

def set_property(vertex_id, properties):
    if vertex_id not in graph_db:
        raise Exception(f'Vertex does not exist')

    graph_db[vertex_id]['properties'] = properties

    # Update the property management system
    try:
        response = requests.put(f'{property_management_system_url}/vertices/{vertex_id}', json={'properties': properties})
        if response.status_code != 200:
            app.logger.error(f'Failed to update vertex {vertex_id} in property management system: {response.text}')
    except Exception as e:
        app.logger.error(f'Error updating vertex {vertex_id} in property management system: {str(e)}')

def add_edge_to_vertex(vertex_id, adjacent_vertex_id):
    if vertex_id not in graph_db or adjacent_vertex_id not in graph_db:
        raise Exception(f'One or both vertices do not exist')

    with lock:
        if adjacent_vertex_id not in graph_db[vertex_id]['edges']:
            graph_db[vertex_id]['edges'].append(adjacent_vertex_id)

if __name__ == '__main__':
    app.run(debug=True)
