#include <stdlib.h>
#include <string.h>

char* expandWithSlash(const char* str, size_t sizeLimit, size_t bufferSz) {
    if (str == NULL || sizeLimit <= 0 || bufferSz <= 0) return NULL;

    size_t len = strlen(str);
    size_t totalLen = len + 1;

    if (totalLen > sizeLimit || totalLen > bufferSz) {
        char* result = malloc(totalLen);
        if (result == NULL) return NULL;

        strncpy(result, str, len);
        result[totalLen - 1] = '/';
        result[totalLen] = '\0';
        return result;
    }

    size_t newSize = totalLen + 1; // account for the null terminator
    char* newStr = realloc(str, newSize * sizeof(char));
    if (newStr == NULL) return NULL;
    newStr[newSize - 1] = '/';
    newStr[newSize] = '\0';
    return newStr;
}
