#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

record* initializeRecords(int numRecords) {
    if (numRecords <= 0) {
        return NULL; // Handle invalid input
    }

    // Query the database to fetch the number of records needed for initialization
    int* offsetValues = malloc(numRecords * sizeof(int));
    int* keys = malloc(numRecords * sizeof(int));

    // Check for memory allocation issues
    if (offsetValues == NULL || keys == NULL) {
        free(offsetValues);
        free(keys);
        return NULL;
    }

    record* records = malloc(numRecords * sizeof(record));
    if (records == NULL) {
        free(offsetValues);
        free(keys);
        return NULL;
    }

    // Initialize each record with a random value within the specified range
    srand(time(NULL)); // Seed random number generator
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % 10001; // Generate random value between 0 and 10000
    }

    free(offsetValues);
    free(keys);

    return records;
}
