    fn cleanup(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        thread::sleep(std::time::Duration::from_millis(self.interval));

        let mut to_delete = Vec::new();
        for (dir_name, dir_path) in self.dirs.iter() {
            if !fs::metadata(dir_path).unwrap().is_dir() || fs::read_dir(dir_path).unwrap().count() == 0 {
                to_delete.push(*dir_name);
            }
        }

        for &dir_name in &to_delete {
            self.remove_dir(&dir_name)?;
        }

        Ok(())
    }

