const { readdir, open, read } = require('fs').promises;
const { join } = require('path');
const { parallel, then } = require('p-map');

async function readDirectoryFiles(directory, extension, fileSizeThreshold, buffer_size) {
  try {
    const files = await readdir(directory);
    const filteredFiles = files.filter(file => file.endsWith(extension));
    const cachedResults = {};

    const tasks = filteredFiles.map(async (file) => {
      if (cachedResults[file]) return cachedResults[file];

      const filePath = join(directory, file);
      let contentLength;
      try {
        const fileSize = await open(filePath, 'r');
        contentLength = await read(fileSize, buffer_size).then((buffer) => buffer.length);
        await fileSize.close();
      } catch (error) {
        console.error(`Error reading ${file}: ${error}`);
        return null;
      }

      if (contentLength > fileSizeThreshold * 1024 * 1024) {
        console.log(`Excluding file ${file} due to size limit (${fileSizeThreshold} MB)`);
        return null;
      }

      const content = await read(filePath, buffer_size);
      cachedResults[file] = { content, length: content.length };
      console.log(`Processing ${file} (length: ${contentLength} bytes)`);
      await logFileContent(file, content);

      return content;
    });

    const results = await parallel(tasks, 5);
    const concatenatedContent = results.filter(Boolean).map((content) => content.content).join('');

    return concatenatedContent;
  } catch (error) {
    console.error(`Error reading directory: ${error}`);
  }
}

async function logFileContent(file, content) {
  try {
    console.log(`${file} - length: ${content.length} bytes`);
  } catch (error) {
    console.error(`Error logging file content: ${error}`);
  }
}
