class DynamicFileProcessor {
public:
    DynamicFileProcessor(const std::string& metadataToken, int maxParallelOps)
        : metadataToken_(metadataToken), maxParallelOps_(maxParallelOps) {}

    void processFiles(const std::string& filePath) {
        std::ifstream inputFile(filePath);
        if (!inputFile) {
            std::cerr << "Error: Unable to open file " << filePath << ".\n";
            return;
        }

        std::vector<std::string> filePaths;
        std::string line;
        while (std::getline(inputFile, line)) {
            filePaths.push_back(line);
        }
        inputFile.close();

        // Process files in parallel
        std::vector<std::thread> threads;
        std::mutex mtx;
        std::condition_variable cv;
        int totalProcessed = 0;

        for (const auto& filePath : filePaths) {
            threads.emplace_back(&DynamicFileProcessor::processFile, this, filePath, &mtx, &cv, &totalProcessed);
        }

        // Wait for all threads to finish
        for (auto& thread : threads) {
            thread.join();
        }

        // Rename the original file with timestamp and total processed count
        std::time_t time = std::time(nullptr);
        std::string newFilePath = filePath + "_" + std::to_string(time) + "_processed_" + std::to_string(totalProcessed);
        std::rename(filePath.c_str(), newFilePath.c_str());

        // Run callback function to report progress
        reportProgressCallback_(totalProcessed);

        // Execute commands for each file in the background using asynchronous I/O and signal handling
        executeCommands_(filePaths, maxParallelOps_);
    }

private:
    void processFile(const std::string& filePath, std::mutex* mtx, std::condition_variable* cv, int* totalProcessed) {
        // Fetch metadata about the file path
        std::string metaData;
        fetchMetadata_(filePath, metadataToken_, metaData);

        // Process the file based on the metadata
        if (processFileBasedOnMetaData_(filePath, metaData)) {
            (*totalProcessed)++;
            // Run a command for each processed file in the background using asynchronous I/O and signal handling
            executeCommand_(filePath);
        }

        // Signal to the main thread that the operation is complete
