public class XmlParser : IXmlParser
{
    private readonly object _lock = new object();
    private Dictionary<string, List<XmlNode>> _cachedResults = new Dictionary<string, List<XmlNode>>();

    public void LogException(Exception exception)
    {
        // implement logging mechanism here
    }

    public void LogPerformanceMetrics(double executionTime)
    {
        // implement performance metric logging here
    }

    public string GetSingleElementValue(string xpathExpression)
    {
        List<XmlNode> results = _GetCachedResults(xpathExpression);
        if (results.Count > 0)
        {
            return results[0].InnerText;
        }
        try
        {
            results = _GetElementsValues(xpathExpression);
            if (results.Count > 1)
            {
                throw new MultipleElementException("Multiple elements found for XPath expression: " + xpathExpression);
            }
            else if (results.Count == 0)
            {
                throw new FileNotFoundException("No elements found for XPath expression: " + xpathExpression);
            }
            return results[0].InnerText;
        }
        catch (Exception ex)
        {
            LogException(ex);
            throw;
        }
    }

    public List<string> GetElementsValues(string xpathExpression)
    {
        try
        {
            List<XmlNode> results = _GetCachedResults(xpathExpression);
            if (results.Count > 0)
            {
                return results.Select(node => node.InnerText).ToList();
            }
            else
            {
                XmlDocument document = new XmlDocument();
                document.LoadXml(_LoadDocument());
                XmlElement root = document.DocumentElement;
                XmlNodeList nodes = root.SelectNodes(xpathExpression);
                if (nodes == null || nodes.Count == 0)
                {
                    return new List<string>();
                }
                results = nodes.Cast<XmlNode>().ToList();
                _CacheResults(xpathExpression, results);
                return results.Select(node => node.InnerText).ToList();
            }
        }
        catch (Exception ex)
        {
            LogException(ex);
            throw;
        }
    }

    private string _LoadDocument()
    {
        // implement loading XML document logic here
        return "";
    }

    private List<XmlNode> _GetCachedResults(string xpathExpression)
    {
        lock (_lock)
        {
            if (!_cachedResults.ContainsKey(xpathExpression))
                return new List<XmlNode>();
            return _cachedResults[xpathExpression];
        }
    }

    private void _CacheResults(string xpathExpression, List<XmlNode> results)
    {
        lock (_lock)
        {
            _cachedResults[xpathExpression] = results;
        }
    }
}

public class MultipleElementException : Exception
{
    public MultipleElementException(string message) : base(message)
    {
    }
