#include <fstream>
#include <iostream>
#include <stdexcept>
#include <sstream>

class ResourceLoader {
public:
    static std::shared_ptr<JavaSerializable> loadResource(const std::string& path) {
        // Load the resource bundle from the file
        std::ifstream file(path);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open the resource file");
        }

        // Count the number of items in the bundle
        int count = 0;
        while (std::getline(file, "")) {
            count++;
        }

        // Allocate memory for the bundle and its items
        std::shared_ptr<char[]> buffer(new char[count]);
        file.seekg(0);
        file.read(buffer.get(), count);

        // Read the resource bundle data as a byte array
        std::vector<char> dataArray(buffer.get(), buffer.get() + count);

        // Deserialize the byte array into an object of the specified class
        std::shared_ptr<JavaSerializable> obj = nullptr;
        try {
            std::istringstream iss(&dataArray[0]);
            obj.reset(new ObjectInputStream(iss));
            JavaSerializable* deserializedObj = dynamic_cast<JavaSerializable*>(obj->readObject());
            if (deserializedObj == nullptr) {
                throw std::runtime_error("Failed to deserialize the object");
            }
            return std::shared_ptr<JavaSerializable>(deserializedObj);
        } catch (const std::exception& e) {
            throw std::runtime_error("Error deserializing the object: " + e.what());
        }

        // Clean up
        file.close();
        if (!obj) {
            delete[] buffer.get();
        }
    }
};
