#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/sha.h>

// Function prototypes
void processUserInput(char* user_settings, char* input_string);
int clean_up_cipher(AES_CTX* cipher);

// User settings structure
typedef struct {
    int max_length;
    bool trim;
    bool capitalize;
    char* password;
} USER_SETTINGS;

// AES context structure
typedef struct {
    EVP_CIPHER_CTX* ctx;
    uint8_t iv[16];
    uint8_t key[32];
} AES_CTX;

void processUserInput(char* user_settings, char* input_string) {
    // Parse user settings from the provided string
    USER_SETTINGS* settings = (USER_SETTINGS*)malloc(sizeof(USER_SETTINGS));
    sscanf(user_settings, "%d %s %s", &settings->max_length, &settings->trim, &settings->capitalize);
    settings->password = strdup(input_string);

    // Initialize AES context
    AES_CTX* cipher = (AES_CTX*)malloc(sizeof(AES_CTX));
    cipher->ctx = EVP_CIPHER_CTX_new();
    SHA1(settings->password, strlen(settings->password), cipher->key, 32);
    EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, cipher->key, cipher->iv);

    // Process input string based on user settings
    char* processed_string = (char*)malloc((settings->max_length + 1) * sizeof(char));
    if (*input_string >= 'A' && *input_string <= 'Z') {
        // Capitalize the first character
        processed_string[0] = toupper(*input_string);
    } else {
        processed_string[0] = tolower(*input_string);
    }
    for (int i = 1; i < settings->max_length; i++) {
        if (*input_string >= 'A' && *input_string <= 'Z') {
            // Capitalize the rest of the string
            processed_string[i] = toupper(*(input_string + i));
        } else {
            processed_string[i] = tolower(*(input_string + i));
        }
    }

    // Truncate input string if it exceeds the max length
    size_t len = strlen(input_string);
    if (len > settings->max_length) {
        len = settings->max_length;
        memcpy(processed_string, input_string, len);
        processed_string[len] = '\0';
    } else {
        strcpy(processed_string, input_string);
    }

    // Encrypt the processed string
    unsigned char* encrypted_data = (unsigned char*)malloc((len + 1) * sizeof(unsigned char));
    int encrypted_len;
    EVP_EncryptUpdate(cipher->ctx, encrypted_data, &encrypted_len, processed_string, len);

    // Clean up and disable cipher when it is no longer needed
    free(processed_string);
    clean_up_cipher(cipher);

    free(settings->password);
    free(settings);
}

int clean_up_cipher(AES_CTX* cipher) {
    EVP_CIPHER_CTX_free(cipher->ctx);
    free(cipher);
    return 0;
}
