struct Cleaner {
    interval: u64,
    last_run: AtomicUsize,
}

impl Cleaner {
    fn new(interval: u64) -> Self {
        Cleaner { interval, last_run: AtomicUsize::new(0) }
    }

    fn run(&self) {
        let now = std::time::Instant::now().as_secs() as usize;
        if now > self.last_run.load(Ordering::Relaxed) + self.interval {
            self.last_run.store(now, Ordering::Relaxed);
