use std::path::{Path, PathBuf};
use std::fs::File;
use std::io::{Write, BufReader};
use std::collections::HashMap;
use llvm::{LLVMContext, LLVMBuilder, LLVMLinker, LLVMModuleInLinker};

struct Compiler {
    context: LLVMContext,
    builder: LLVMBuilder,
    linker: LLVMLinker,
}

impl Compiler {
    fn new() -> Self {
        let mut context = LLVMContext::new();
        let mut builder = LLVMBuilder::new(&context);
        let mut linker = LLVMLinker::new(&context);

        Compiler { context, builder, linker }
    }

    fn compile_file(&mut self, path: &str) -> Result<String, String> {
        // Read file contents
        let file_path = Path::new(path);
        let mut file = File::open(file_path)?;
        let reader = BufReader::new(file);

        // Parse Rust source code
        let rust_code = reader.lines().collect::<String>();

        // Generate LLVM IR
        let llc = self.builder.compile(&rust_code)?;

        // Optimize the generated LLVM IR
        let optimized_llc = self.linker.optimize(llc, &["-O3", "-disable-printer"])?;

        Ok(optimized_llc.to_string())
    }
}

fn main() {
    let compiler = Compiler::new();

    let dir_path = Path::new("/path/to/directory");
    if !dir_path.is_dir() {
        eprintln!("Directory not found: {}", dir_path.display());
        return;
    }

    let mut optimization_passes = Vec::new();
    // Apply custom optimization passes
    optimization_passes.push("-passes-through");

    for entry in dir_path.read_dir().unwrap() {
        let entry = entry.unwrap();
        let path = entry.path();

        if path.extension().unwrap_or_default() == "rs" {
            let optimized_llc = compiler.compile_file(&path.to_string_lossy().to_string());
            match optimized_llc {
                Ok(llc) => {
                    // Write the optimized LLVM IR to a separate file
                    let output_path = Path::new(path.with_extension("ll"));
                    File::create(output_path).write_all(llc.as_bytes())?;
                }
                Err(err) => {
                    // Log error and skip this file
                    eprintln!("Error compiling {}: {}", path.display(), err);
                }
            };
        }
    }
}
