    {
        if (min > max)
            throw new ArgumentException("Min value cannot be greater than Max value");

        this.min = min;
        this.max = max;
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(min, max);
    }

    public int GetRandomInt()
    {
        return (int)GetRandomFloat();
    }

    public List<int> GetRandomIntegerList(int size)
    {
        List<int> list = new List<int>();

        while (list.Count < size)
        {
            int randomValue = GetRandomInt();

            if (!list.Contains(randomValue))
                list.Add(randomValue);
        }

        return list;
    }

    public override string ToString()
    {
        return $"Range: {min} to {max}\nGenerated Lists:\n{GetGeneratedListsString()}";
    }

    private string GetGeneratedListsString()
    {
        List<int> floatList = GetRandomIntegerList(10);
        List<int> intList = GetRandomIntegerList(5);

        StringBuilder sb = new StringBuilder();

        foreach (int value in floatList)
            sb.AppendLine(value.ToString());

        foreach (int value in intList)
            sb.AppendLine(value.ToString());

        return sb.ToString();
    }
}
