const { Buffer } = require('buffer');
const { Readable } = require('stream');

function copyBytes(sources, byteRange) {
  const buffers = [];
  const totalLength = 0;

  function getBuffer(source) {
    if (source instanceof Readable) {
      return new Promise((resolve, reject) => {
        let buffer = Buffer.alloc(0);
        source.on('data', (chunk) => {
          buffer = Buffer.concat([buffer, chunk]);
        });
        source.on('end', () => resolve(buffer));
        source.on('error', (err) => reject(err));
      });
    } else if (Buffer.isBuffer(source)) {
      return Promise.resolve(source);
    }
    throw new Error('Unsupported data source');
  }

  function combineBuffers() {
    const combined = Buffer.alloc(0);
    for (const buffer of buffers) {
      combined = Buffer.concat([combined, buffer]);
    }
    return combined;
  }

  async function copyChunk(chunkIndex) {
    let currentOffset = byteRange.start;
    while (currentOffset < byteRange.end) {
      const sourceLength = totalLength - currentOffset;
      if (sourceLength > 0) {
        const chunkEnd = Math.min(currentOffset + byteRange.end, totalLength);
        const chunk = await getBuffer(sources[chunkIndex]).slice(currentOffset, chunkEnd);
        buffers.push(chunk);
        totalLength += chunk.length;
        currentOffset = chunkEnd;
      } else {
        break;
      }
    }
  }

  for (let i = 0; i < sources.length; i++) {
    await copyChunk(i);
  }

  return combineBuffers();
}
