#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long offset;
    timestamp;
} record;

record* init_records(int num_records) {
    record* records = NULL;
    long* offsets = NULL;
    int* keys = NULL;

    // Allocate memory for arrays
    if (!(offsets = (long*)malloc(num_records * sizeof(long)))) {
        perror("Offset array allocation failed");
        return NULL;
    }
    if (!(keys = (int*)malloc(num_records * sizeof(int)))) {
        free(offsets);
        offsets = NULL;
        perror("Key array allocation failed");
        return NULL;
    }
    if (!(records = (record*)malloc(num_records * sizeof(record)))) {
        free(offsets);
        free(keys);
        offsets = NULL;
        keys = NULL;
        perror("Record array allocation failed");
        return NULL;
    }

    // Initialize arrays with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand();
        keys[i] = rand() % 100;
    }

    // Set timestamps to current time plus a random delay within [1, 10) seconds
    timestamp ts;
    ts = time(NULL) + rand() % 9 + 1;

    for (int i = 0; i < num_records; i++) {
        records[i].offset = offsets[i];
        records[i].timestamp = ts;
    }

    return records;
}

void free_resources(record* records, long* offsets, int* keys) {
    if (records) free(records);
    if (offsets) free(offsets);
    if (keys) free(keys);
}
