class FileLoader {
  constructor() {
    this.queue = [];
    this.runningQueue = [];
    this.fallbackFiles = {};
    this.logger = console;
  }

  addFile(file) {
    if (!this.queue.includes(file)) {
      this.queue.push(file);
      this.executeNext();
    }
  }

  removeFile(file) {
    const index = this.queue.indexOf(file);
    if (index !== -1) {
      this.queue.splice(index, 1);
      this.executeNext();
    }
  }

  loadAndExecute() {
    return new Promise((resolve, reject) => {
      (async () => {
        while (this.runningQueue.length < this.queue.length) {
          const file = this.queue.shift();
          try {
            await import(file);
            this.runningQueue.push(file);
          } catch (error) {
            if (!this.fallbackFiles[file]) {
              this.logger.error(`Failed to load and execute ${file}. Falling back to default behavior.`);
              this.fallbackFiles[file] = true;
            }
          }
        }
        resolve();
      })();
    });
  }

  executeNext() {
    const file = this.queue.shift();
    if (file) {
      this.loadAndExecute().then(() => this.executeNext()).catch((error) => {
        this.logger.error('Error loading and executing files:', error);
        this.runningQueue = [];
      });
    }
  }
}

const loader = new FileLoader();

// Example usage:
loader.addFile('script1.js');
loader.addFile('script2.js');
loader.addFile('script3.js');

loader.loadAndExecute().then(() => {
  console.log('All files loaded and executed successfully!');
}).catch((error) => {
  console.error('Error loading and executing files:', error);
});

// Dynamic update example:
setInterval(() => {
  loader.removeFile('script1.js');
}, 3000);

setInterval(() => {
  loader.addFile('newScript.js');
}, 6000);
