function getFileHash($filePath) {
    $privateKey = file_get_contents('path_to_private_key.pem');
    $certificate = file_get_contents('path_to_certificate.pem');
    $pemFile = implode('', array_merge(array("-----BEGIN CERTIFICATE-----", $certificate, "-----END CERTIFICATE-----"), array("-----BEGIN PRIVATE KEY-----", $privateKey, "-----END PRIVATE KEY-----")));

    $fp = fopen($filePath, 'rb');
    $fileChunks = [];
    while (!feof($fp)) {
        $chunk = fread($fp, 4096);
        $fileChunks[] = $chunk;
    }
    fclose($fp);

    $fileHash = hash('md5', implode('', $fileChunks));

    return $fileHash;
}

