#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "logging.h"

typedef struct {
    int RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG RX_UE_INFORMATION;
    NFAPI_CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8;
} NFAPI_CRC_INDICATION_PDU_T;

int generateNfalist(int num_structures, NFAPI_CRC_INDICATION_PDU_T **nfalist, const char *rules_config_file) {
    // Initialize JSON parsing and CRC flag validation rules
    json_t *root = NULL;
    json_error_t error;
    root = json_load_file(rules_config_file, 0, &error);
    if (!root) {
        log_error("Failed to load CRC flag validation rules from file: %s", error.message);
        return -1;
    }

    // Allocate memory for the list of structures
    *nfalist = (NFAPI_CRC_INDICATION_PDU_T **)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!*nfalist) {
        log_error("Memory allocation failed");
        json_decref(root);
        return -1;
    }

    // Populate each structure with unique RX_UE_INFORMATION_TAG and RNTI values
    for (int i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T *structure = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!structure) {
            log_error("Memory allocation failed");
            free(*nfalist);
            json_decref(root);
            return -1;
        }

        structure->RX_UE_INFORMATION = generate_unique_tag();
        structure->CRC_INDICATION_REL8 = (NFAPI_CRC_INDICATION_REL8_TAG){i, false};

        // Set the CRCFLAG based on the rules from the JSON file
        json_t *rule_json = json_object_get(root, json_string_to_pointer_printf("RNTI_%d", i));
        if (rule_json) {
            structure->CRC_INDICATION_REL8.CRCFLAG = json_boolean_value(rule_json);
            json_decref(rule_json);
        } else {
            log_warning("No CRC flag validation rule found for RNTI %d", i);
        }

        // Log the creation of each structure
        log_structure_creation(structure);

        (*nfalist)[i] = structure;
    }

    // Validate the populated structures against the CRC flag rules specified in the JSON file
    for (int i = 0; i < num_structures; i++) {
        if ((*nfalist)[i]->CRC_INDICATION_REL8.CRCFLAG != get_CRC_flag((*nfalist)[i]->RX_UE_INFORMATION)) {
            log_error("Mismatched CRC flag value for RNTI %d", i);
            return -1;
        }
    }

    json_decref(root);

    return 0;
}
