#include <iostream>
#include <string>
#include "poppler/poppler.h"

enum CompressionStatus {
    SUCCESS,
    FAILURE
};

class PDFCompressor {
public:
    PDFCompressor(const std::string& inputPDFPath, const std::string& outputPDFPath, int compressionLevel, bool disableImages, bool disableFonts) 
        :inputPDFPath(inputPDFPath), outputPDFPath(outputPDFPath), compressionLevel(compressionLevel), disableImages(disableImages), disableFonts(disableFonts){}

    CompressionStatus compressAndSave() {
        // Initialize Poppler
        CuReport::init();
        CuException::setHandler(new CuReport::ExceptionHandler());

        // Load the PDF file using Poppler
        std::unique_ptr<pdf::Document> pdfDoc = pdf::Document::load(inputPDFPath);

        if (!pdfDoc) {
            return FAILURE;
        }

        // Compress the PDF based on the compression level and settings
        if (compressionLevel > 0) {
            // Disable images and fonts as per settings
            if (disableImages) {
                // Set image compression to disabled
                pdfDoc->setImageCompression(PDFImageCompression::Disabled);
            }
            if (disableFonts) {
                // Set font compression to disabled
                pdfDoc->setFontCompression(PDFFontCompression::Disabled);
            }

            // Apply the specified compression level
            pdfDoc->setCompressionLevel(compressionLevel);
        }

        try {
            // Save the compressed PDF file
            pdfDoc->save(outputPDFPath);
        } catch (const std::exception& e) {
            return FAILURE;
        }

        return SUCCESS;
    }

    CompressionStatus getCompressionStatus() const {
        return status;
    }

private:
    std::string inputPDFPath;
    std::string outputPDFPath;
    int compressionLevel;
    bool disableImages;
    bool disableFonts;
    CompressionStatus status = SUCCESS;
};

