import java.io.*;
import java.util.*;

public class DynamicTestLoader {
    public void loadAndExecuteTests(String moduleName) throws Exception {
        // Load tests from file
        List<Test> tests = loadTestsFromModuleFile(moduleName);

        // Reset blueslip mocking library after each test
        for (Test test : tests) {
            try {
                test.execute();
            } finally {
                Blueslip.reset();
            }
        }

        // Caching mechanism to store state objects
        Cache cache = new Cache(10); // configure the maximum size

        // Read state objects from file and update cache if necessary
        File file = new File("state_objects");
        ObjectInputStream inputStream = null;
        try {
            inputStream = new ObjectInputStream(new FileInputStream(file));
            StateObject stateObject = (StateObject) inputStream.readObject();
            while (stateObject != null) {
                cache.put(stateObject.getId(), stateObject);
                stateObject = (StateObject) inputStream.readObject();
            }
        } catch (IOException e) {
            // log error
            System.out.println("Error reading from file: " + e.getMessage());
        } finally {
            if (inputStream != null) {
                try {
                    inputStream.close();
                } catch (IOException e) {
                    // log error
                    System.out.println("Error closing input stream: " + e.getMessage());
                }
            }
        }

        // Check state management service for updates and update cache
        StateManagementService service = new StateManagementService();
        List<StateObject> updatedObjects = service.getUpdatedStateObjects();
        for (StateObject object : updatedObjects) {
            cache.put(object.getId(), object);
        }

        // Log loading process information
        System.out.println("Loaded and executed tests for module " + moduleName);
    }
}

class Cache {
    Map<String, StateObject> objects;
    int maxSize;

    public Cache(int maxSize) {
        this.maxSize = maxSize;
        this.objects = new HashMap<>();
    }

    public void put(String id, StateObject object) {
        if (objects.size() >= maxSize) {
            // evict the least recently used item
            String leastRecentlyUsedId = null;
            long oldestTimeAccessed = Long.MAX_VALUE;
            for (Map.Entry<String, StateObject> entry : objects.entrySet()) {
                long timeAccessed = System.currentTimeMillis();
                if (timeAccessed < oldestTimeAccessed) {
                    oldestTimeAccessed = timeAccessed;
                    leastRecentlyUsedId = entry.getKey();
                }
            }
            objects.remove(leastRecentlyUsedId);
        }
        objects.put(id, object);
    }

    public StateObject get(String id) {
        return objects.get(id);
    }
}
```

