const axios = require('axios');

function asyncReducePokemonWeaknesses(pokemonArray, callback) {
  const pokemonTypes = {};
  const weaknessString = [];

  (async () => {
    try {
      for await (const pokemon of pokemonArray) {
        if (!pokemon.name || !pokemon.level) throw new Error('Invalid Pokemon data');

        const response = await axios.get(`https://api.pokemon.com/pokemon/${pokemon.name}`);
        const { type, weaknesses } = response.data;

        switch (type) {
          case 'grass':
            weaknessString.push(...weaknesses.filter(weakness => ['poison', 'fire'].includes(weakness)));
            break;
          case 'water':
            weaknessString.push(...weaknesses.filter(weakness => ['grass', 'electric'].includes(weakness)));
            break;
          case 'fire':
            weaknessString.push(...weaknesses.filter(weakness => ['water', 'rock'].includes(weakness)));
            break;
          default:
            throw new Error(`Unsupported Pokemon type: ${type}`);
        }
      }

      callback(null, `Combined weaknesses: ${weaknessString.join(', ')}`);

    } catch (error) {
      callback(error);
    } finally {
      // Release any held references to prevent memory leaks
      pokemonTypes = null;
      weaknessString = null;
    }
  })();
}

module.exports = asyncReducePokemonWeaknesses;

