                createClinicRecord($data);
                break;
            case 'update':
                updateClinicRecord($data);
                break;
            case 'delete':
                deleteClinicRecord($clinicId);
                break;
        }

        // Commit transaction
        $transaction->commit();
    } catch (Exception $e) {
        // Rollback transaction and log error
        $transaction->rollBack();
        error_log('Error: ' . $e->getMessage());
    }
