use std::path::Path;

fn create_log_directory(log_dir_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let log_dir_path = format!("logs/{}", log_dir_name);
    let current_log_dir = env::var("LOG_DIR")?;

    if Path::new(&current_log_dir).exists() && !Path::new(&log_dir_path).exists() {
        fs::create_dir_all(&log_dir_path)?;
        env::set_var("LOG_DIR", &log_dir_path)?;
        println!("Created log directory: {}", log_dir_path);
    } else if !Path::new(&current_log_dir).exists() {
        fs::create_dir_all(&log_dir_path)?;
        env::set_var("LOG_DIR", &log_dir_path)?;
        println!("Created log directory: {}", log_dir_path);
    }
    Ok(())
}

