from flask import Flask, request, jsonify
import hashlib
import os
import logging
from flask_cors import cross_origin
from flask_sqlalchemy import SQLAlchemy
from flask_login import LoginManager, UserMixin, login_user, logout_user
from flask_restful import Api, Resource, reqparse
from datetime import datetime

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:////tmp/test.db'
db = SQLAlchemy(app)

class Transaction(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    timestamp = db.Column(db.DateTime, default=datetime.utcnow)
    details = db.Column(db.String)

class User(UserMixin):
    id = db.Column(db.Integer, primary_key=True)

login_manager = LoginManager()
login_manager.init_app(app)

@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))

@app.route('/transaction', methods=['POST'])
@cross_origin(origin='*', headers=['Content-Type'])
def record_transaction():
    parser = reqparse.RequestParser()
    parser.add_argument('details')
    args = parser.parse_args()

    if request.authorization and request.authorization['username'] == 'admin' and request.authorization['password'] == 'password':
        transaction = Transaction(details=args['details'])
        db.session.add(transaction)
        db.session.commit()
        return {'message': 'Transaction recorded successfully'}, 201
    else:
        return {'error': 'Unauthorized access'}, 401

@app.route('/file', methods=['POST'])
@cross_origin(origin='*', headers=['Content-Type'])
def calculate_hash():
    parser = reqparse.RequestParser()
    parser.add_argument('path')
    args = parser.parse_args()

    if os.path.exists(args['path']):
        with open(args['path'], 'rb') as f:
            md5 = hashlib.md5(f.read(65536))
            while f.peek(1):
                f.seek(-65536, 1)
                md5.update(f.read(65536))
        return {'hash': md5.hexdigest()}, 200
    else:
        return {'error': 'File not found'}, 404

if __name__ == '__main__':
    app.run(debug=True)

