```
class JsonParser {
  constructor() {
    this.registry = {};
    this.serializer = new TextSerializer();
  }

  fromJson(jsonString) {
    return JSON.parse(jsonString);
  }

  toJson(data) {
    return JSON.stringify(data);
  }

  registerFactory(id, factory) {
    this.registry[id] = factory;
  }
}

class TextSerializer {
  serialize(data, indentLevel = 0) {
    const output = [];
    for (const key in data) {
      if (data.hasOwnProperty(key)) {
        output.push(`  `.repeat(indentLevel) + `${key}: ${this.serializeValue(data[key], indentLevel + 1)}`);
      }
    }
    return output.join('\n');
  }

  serializeValue(value, indentLevel = 0) {
    if (typeof value === 'object') {
      return `{${this.serializeObject(value, indentLevel)}}`;
    } else if (Array.isArray(value)) {
      return `[${value.map((v) => this.serializeValue(v)).join(', ')}]`;
    } else {
      return JSON.stringify(value);
    }
  }

  serializeObject(data, indentLevel = 0) {
    const output = [];
    for (const key in data) {
      if (data.hasOwnProperty(key)) {
        output.push(`  ` + `${key}: ${this.serializeValue(data[key], indentLevel + 1)}`);
      }
    }
    return `{${output.join(', ')}}`;
  }
