#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_STRUCTS 100000
typedef struct {
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *dynamicTestLoader(int numStructs) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int i, flag = 0;
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(numStructs * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!list) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (i = 0; i < numStructs; i++) {
        pthread_mutex_lock(&lock);
        flag++;
        list[i].CRCFLAG = flag;
        pthread_mutex_unlock(&lock);

        if (!blueslip_set_flag(flag)) {
            free(list);
            fprintf(stderr, "Error setting CRC flag\n");
            return NULL;
        }
    }

    for (i = 0; i < numStructs; i++) {
        pthread_mutex_lock(&lock);
        printf("Created structure %d with CRCFLAG %d\n", i, list[i].CRCFLAG);
        pthread_mutex_unlock(&lock);
    }

    blueslip_reset();

    return list;
}

void logTestLoader(int numStructs) {
    FILE *logFile = fopen("test_loader.log", "w");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    fprintf(logFile, "Loaded %d NFAPI_CRC_INDICATION_PDU_T structures with unique CRCFLAG values\n", numStructs);
    fclose(logFile);
}
