```rust
use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::Mutex;

lazy_static! {
    static ref LOGGER: Mutex<Logger> = Mutex::new(Logger::default());
}

struct Logger {
    file_path: String,
}

impl Default for Logger {
    fn default() -> Self {
        Self {
            file_path: "log.txt".to_string(),
        }
    }
}

impl Logger {
    fn log(&self, message: &str) {
        let mut file = fs::OpenOptions::new()
            .write(true)
            .append(true)
            .open(self.file_path.clone())
            .unwrap();
        writeln!(file, "{}", message).unwrap();
    }
}

fn create_directory(dir_name: &str) -> Result<String, String> {
    let timestamp = ureq::time::now_utc().to_string();
    let dir_path = format!("runs/{}", dir_name);
    let sub_dir_path = format!("{}/run_{}", dir_path, timestamp);

    if env::var("DIR_PATH").is_ok() {
        let existing_dir_path = env::var("DIR_PATH").unwrap();
        fs::create_dir_all(&sub_dir_path)?;
        env::set_var("DIR_PATH", &sub_dir_path);
        LOGGER.lock().unwrap().log(&format!("Created subdirectory {} under {}", sub_dir_path, existing_dir_path));
    } else {
        fs::create_dir_all(dir_path)?;
        env::set_var("DIR_PATH", dir_path.as_str());
        LOGGER.lock().unwrap().log(&format!("Created directory {}", dir_path));
    }

    let temp_subdir_path = format!("{}/run_{}", &env::var("DIR_PATH").unwrap(), timestamp);
    if fs::read_dir(temp_subdir_path.as_str()).is_ok() {
        fs::remove_dir_all(&temp_subdir_path)?;
        LOGGER.lock().unwrap().log(&format!("Deleted temporary subdirectory {}", temp_subdir_path));
    }

    Ok(env::var("DIR_PATH").unwrap())
}
