#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int verify_oauth_token(char* json_obj) {
    char *token_type;
    int expires_in;
    char *access_token;
    char *refresh_token;

    cJSON *root = cJSON_Parse(json_obj);
    if (!root) {
        return 0; // JSON parse error
    }

    access_token = cJSON_GetStringValue(cJSON_GetObjectItem(root, "access_token"));
    token_type = cJSON_GetStringValue(cJSON_GetObjectItem(root, "token_type"));
    expires_in = cJSON_GetIntValue(cJSON_GetObjectItem(root, "expires_in"));

    if (!access_token || strlen(access_token) == 0 ||
        strcmp(token_type, "Bearer") != 0 || expires_in <= 0) {
        return 0;
    }

    refresh_token = cJSON_GetStringValue(cJSON_GetObjectItem(root, "refresh_token"));
    if (refresh_token && strlen(refresh_token) > 0) {
        // Check the length or contents of the refresh token if necessary
    }

    cJSON_Delete(root);
    return 1; // Token is valid
}
