@app.route('/calculate-md5/<path:path>')
def calculate_md5(path):
    md5_hash = hashlib.md5()

    with open(path, 'rb') as file:
        while True:
            chunk = file.read(4096)
            if not chunk:
                break
            md5_hash.update(chunk)

    return jsonify({'md5_hash': md5_hash.hexdigest()})
