function updateClinicStatus(int $clinicId, string $newStatus, ?string $lastModifiedIp = null) {
    // Database connection
    $db = new mysqli('localhost', 'username', 'password', 'database');

    if ($db->connect_error) {
        throw new Exception("Database connection failed: " . $db->connect_error);
    }

    try {
        // Check for potential closure reasons due to extreme weather conditions
        $weatherApi = new WeatherAPI();
        if ($newStatus === 'closed' || $newStatus === 'emergency') {
            $reason = $weatherApi->getExtremeWeatherReason();
            if (!$reason) {
                throw new Exception("Failed to retrieve extreme weather reason");
            }
        } else {
            $reason = null;
        }

        // Check for overlapping appointments
        $schedulingSystem = new PatientSchedulingSystem();
        if ($newStatus !== 'closed' && $newStatus !== 'emergency') {
            $schedulingSystem->checkForOverlappingAppointments($clinicId);
        }

        // Update clinic status, last modified IP address, and last modified date
        $db->begin_transaction();
        try {
            $query = "UPDATE clinics SET status=?, last_modified_ip=?, last_modified_date=NOW() WHERE id=?";
            $stmt = $db->prepare($query);
            $stmt->bind_param('ssi', $newStatus, $lastModifiedIp ?? '', $clinicId);
            $stmt->execute();
        } catch (Exception $e) {
            // Roll back transaction and rethrow the exception
            $db->rollback();
            throw $e;
        }

        // Commit transaction
        $db->commit_transaction();

        // Notify external API service and emergency response team if necessary
        if ($newStatus === 'closed' || $newStatus === 'emergency') {
            $apiService = new ExternalAPIService();
            try {
                $apiService->notify($reason);
            } catch (Exception $e) {
                // Send error report to administrators
                sendErrorReport('External API service', $e);
            }

            // Notify hospital's emergency response team via email
            try {
                notifyEmergencyTeam($reason);
            } catch (Exception $e) {
                // Send error report to administrators
                sendErrorReport('Emergency response team', $e);
            }
        }

        return 'Clinic status updated successfully';
    } catch (Exception $e) {
        // Handle general exceptions and log the error
        logError($e);
        return 'Failed to update clinic status';
    } finally {
        // Close database connection
        if ($db->connected()) {
            $db->close();
        }
    }
}
