import paho.mqtt.client as mqtt
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.backends import default_backend
from requests.auth import HTTPBasicAuth
from logging.handlers import RotatingFileHandler
import logging
import time
import threading
import json

# Set API credentials and URL
api_url = "https://your-api-url.com"
username = "your-username"
password = "your-password"

# Set MQTT broker details
mqtt_broker_url = "localhost:1883"
device_topics = {
    "device1": "$SYS/DEVICES/device1",
    "device2": "$SYS/DEVICES/device2",
}

class IoTDeviceManager:
    def __init__(self):
        self.api_token = None
        self.device_keys = {}
        self.mqtt_client = mqtt.Client()
        self.mqtt_client.on_connect = self.on_mqtt_connect
        self.mqtt_client.on_disconnect = self.on_mqtt_disconnect
        self.log_handler = RotatingFileHandler("iot_device_manager.log", maxBytes=1000000, backupCount=3)
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.DEBUG)
        self.logger.addHandler(self.log_handler)

    def register_api_client(self):
        auth = HTTPBasicAuth(username, password)
        response = requests.post(api_url + "/register", auth=auth)
        if response.status_code == 200:
            self.api_token = response.json()["token"]
        else:
            self.logger.error("Failed to register API client")

    def establish_mqtt_connections(self):
        for device in devices_topics:
            self.mqtt_client.connect(device_topics[device], 60)  # Establish connection with a timeout of 1 minute
            time.sleep(0.5)  # Allow the connection to stabilize

    def subscribe_to_topics(self):
        for topic in device_topics.values():
            self.mqtt_client.subscribe(topic)

    def publish_command(self, device_id, command):
        self.mqtt_client.publish(device_topics[device_id], json.dumps(command).encode())

    def handle_response(self, device_id, response):
        if response:
            self.logger.info(f"Received response from {device_id}: {response}")
        else:
            self.logger.warning(f"No response received from {device_id}")

    def on_mqtt_connect(self, client, userdata, flags, rc):
        if rc == 0:
            self.logger.info("MQTT connection established")
        else:
            self.logger.error("Failed to establish MQTT connection")

    def on_mqtt_disconnect(self, client, userdata, rc):
        if rc == 0:
            self.logger.info("MQTT connection lost")
        else:
            self.logger.error("Failed to disconnect from MQTT broker")

if __name__ == "__main__":
    manager = IoTDeviceManager()
    manager.register_api_client()
    manager.establish_mqtt_connections()
    manager.subscribe_to_topics()

    # Example usage: publish a command and handle the response
    device_id = "device1"
    command = {"command": "start"}
    manager.publish_command(device_id, command)
    time.sleep(2)  # Allow the command to be processed
    response = manager.mqtt_client.recv()
    manager.handle_response(device_id, response)

    # Clean up when exiting
    manager.mqtt_client.disconnect()
