    private readonly int _maxAllowedStringLength;
    private readonly bool _trimAndCapitalize;

    public DynamicTextProcessor(ILogger logger, IApiService apiService, int maxAllowedStringLength = 1073741824, bool trimAndCapitalize = false)
    {
        _logger = logger;
        _apiService = apiService;
        _maxAllowedStringLength = maxAllowedStringBuilderCheck(maxAllowedStringLength);
        _trimAndCapitalize = trimAndCapitalize;
    }

    public async Task<string> ProcessUserInputAsync(string input, HashAlgorithmType hashAlgorithm)
    {
        if (string.IsNullOrEmpty(input))
        {
            throw new ArgumentException("Input cannot be null or empty.");
        }

        await ValidateInputLengthAsync(input);

        try
        {
            using var stream = new MemoryStream(Encoding.UTF8.GetBytes(input));
            using var algorithm = GetHashAlgorithm(hashAlgorithm);
            var hashBytes = await ComputeHashAsync(stream, algorithm);
            return BitConverter.ToString(hashBytes).Replace("-", string.Empty).ToLowerInvariant();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing input.");
            throw;
        }
    }

    private int maxAllowedStringBuilderCheck(int maxAllowedStringLength)
    {
        if (maxAllowedStringLength < 1 || maxAllowedStringLength > 1073741824)
        {
            throw new ArgumentException("Maximum allowed string length must be between 1 and 1073741824 bytes.");
        }
        return maxAllowedStringLength;
    }

    private async Task ValidateInputLengthAsync(string input)
    {
        if (input.Length > _maxAllowedStringLength)
        {
            throw new ArgumentException($"Input cannot exceed {_maxAllowedStringLength} bytes.");
        }
    }

    private HashAlgorithm GetHashAlgorithm(HashAlgorithmType hashAlgorithm)
    {
        switch (hashAlgorithm)
        {
            case HashAlgorithmType.MD5:
                return MD5.Create();
            case HashAlgorithmType.SHA1:
                return SHA1.Create();
            case HashAlgorithmType.SHA256:
                return SHA256.Create();
            default:
                throw new ArgumentException("Invalid hash algorithm.");
        }
    }

    private async Task<byte[]> ComputeHashAsync(Stream input, HashAlgorithm algorithm)
    {
        using var hash = algorithm;
        var buffer = new byte[0x10000];
        using var output = new MemoryStream();

        while (true)
        {
            int readCount = await input.ReadAsync(buffer, 0, buffer.Length);
            if (readCount == 0) break;

            using var hashStream = new MemoryStream(buffer.Take(readCount).ToArray());
            hash.ComputeHash(hashStream);

            var chunkBytes = hash.GetBytes();
            await output.WriteAsync(chunkBytes);
        }

        return output.ToArray();
    }
}

public enum HashAlgorithmType
{
    MD5,
    SHA1,
    SHA256
}
