import xml.etree.ElementTree as ET
import requests
from collections import defaultdict
import hashlib

class XMLProcessor:
    def __init__(self):
        self.cached_responses = {}
        self.field_extractions_rules = {}

    def get_xml_from_api(self, url):
        if url not in self.cached_responses:
            response = requests.get(url)
            self.cached_responses[url] = ET.fromstring(response.content)
        return self.cached Responses[url]

    def extract_fields(self, xml, fields):
        result = defaultdict(dict)

        def recursive_extraction(node, current_path=""):
            for child in node:
                if child.tag not in result[current_path]:
                    result[current_path][child.tag] = {}
                if "fields" in child.attrib and child.attrib["fields"]:
                    recursive_extraction(child, f"{current_path}/{child.tag}")
                elif "xsl" in child.attrib and child.attrib["xsl"]:
                    try:
                        xslt_tree = ET.parse(f"xsl/{child.attrib['xsl']}.xsl")
                        transformed_node = ET.XSLT(xslt_tree).transform(ET.tostring(child))
                        result[current_path][child.tag] = ET.fromstring(transformed_node).find(".//{0}".format(fields[0])).text
                    except (Exception):
                        pass
                else:
                    if child.text and child.tag in fields:
                        try:
                            field_value = child.text.strip()
                            if len(field_value) > 10 and not isinstance(result[current_path][child.tag], list):
                                result[current_path][child.tag] = [field_value]
                            else:
                                result[current_path][child.tag].append(field_value)
                        except (Exception):
                            pass

        recursive_extraction(xml, "")

        return dict(result)

    def add_field_extraction_rule(self, field_name, rule_function):
        self.field_extractions_rules[field_name] = rule_function

    def process_xml(self, url, fields):
        try:
            xml = self.get_xml_from_api(url)
            result = self.extract_fields(xml, fields)

            for key in result.keys():
                if isinstance(result[key], dict):
                    for sub_key, value in result[key].items():
                        for field_name, rule_function in self.field_extractions_rules.items():
                            if sub_key == field_name:
                                try:
                                    value = rule_function(value)
                                except (Exception):
                                    pass

            return result
        except Exception as e:
            print(f"An error occurred: {e}")
            return None

