const { createCipheriv, createDecipheriv } = require('crypto');
const { getOldTestamentBooks } = require('./old-testament-books-db');
const { cache } = require('./caching-middleware');

class AsyncDataCopier {
  constructor(cspKey, cspIv, rateLimit) {
    this.cspKey = cspKey;
    this.cspIv = cspIv;
    this.rateLimit = rateLimit;
    this.oldTestamentBooks = {};
    this.cache = cache;
  }

  async process(dataStream) {
    const oldTestamentBookCounts = {};

    for await (const dataChunk of dataStream) {
      try {
        const decryptedData = await this.decryptData(dataChunk);
        const bookMatches = this.findOldTestamentBooks(decryptedData);

        bookMatches.forEach((bookMatch) => {
          if (!oldTestamentBookCounts[bookMatch]) {
            oldTestamentBookCounts[bookMatch] = 0;
          }
          oldTestamentBookCounts[bookMatch]++;
        });
      } catch (error) {
        console.error(`Error processing data chunk: ${error}`);
      }
    }

    return oldTestamentBookCounts;
  }

  async decryptData(dataChunk) {
    const csp = createDecipheriv('aes-256-cbc', this.cspKey, this.cspIv);
    const decryptedData = Buffer.concat([csp.update(Buffer.from(dataChunk)), csp.final()]);

    return decryptedData.toString();
  }

  findOldTestamentBooks(text) {
    const regexPattern = /(\b(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1Samuel|2Samuel|1Kings|2Kings|1Chronicles|2Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|SongOfSolomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah| Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\b)/i;
    const matches = text.match(regexPattern);

    return matches ? matches.map((match) => match.replace(/[^\w]/g, '')) : [];
  }

  async getOldTestamentBooksFromDatabase() {
    this.oldTestamentBooks = await getOldTestamentBooks();
  }
}

module.exports = AsyncDataCopier;
