import java.io.BufferedReader;
import java.io.Closeable;
import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.util.Calendar;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class StateLoader {
    private static final int CACHE_MAX_SIZE = 1000; // adjust as needed
    private Map<String, State> cache = new ConcurrentHashMap<>();
    private Lock lock = new ReentrantLock();
    private boolean useExternalService = true; // toggle to use file or external service
    private String externalServiceUrl;
    private Logger logger;

    public StateLoader(String externalServiceUrl, Logger logger) {
        this.externalServiceUrl = externalServiceUrl;
        this.logger = logger;
    }

    public State loadState(String stateId) {
        State state = cache.get(stateId);
        if (state != null && isValid(state.getLastUpdate())) { // cache hit
            logger.info("Cache hit: " + stateId);
            return state;
        }

        state = loadFromExternalService(stateId);
        if (state != null) {
            cache.put(stateId, state); // add to cache
            if (cache.size() > CACHE_MAX_SIZE) { // evict oldest entry when full
                Iterator<Map.Entry<String, State>> it = cache.entrySet().iterator();
                while (it.hasNext()) {
                    Map.Entry<String, State> entry = it.next();
                    if (entry.getValue().getLastUpdate().before(Calendar.getInstance())) {
                        it.remove();
                        break;
                    }
                }
            }
        } else { // cache miss
            state = loadFromLocalFile(stateId);
            if (state != null) {
                cache.put(stateId, state); // add to cache
            } else {
                logger.error("Failed to retrieve state: " + stateId);
            }
        }

        return state;
    }

    private State loadFromExternalService(String stateId) {
        try (Closeable connection = new Connection(externalServiceUrl)) {
            BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String line;
            StringBuilder sb = new StringBuilder();
            while ((line = reader.readLine()) != null) {
                sb.append(line);
            }
            return State.fromJson(sb.toString());
        } catch (IOException e) {
            logger.error("Failed to load state from external service: " + stateId, e);
            return null;
        }
    }

    private State loadFromLocalFile(String stateId) {
        try (BufferedReader reader = new BufferedReader(new FileReader(new File("states/" + stateId + ".json")))) {
            String line;
            StringBuilder sb = new StringBuilder();
            while ((line = reader.readLine()) != null) {
                sb.append(line);
            }
            return State.fromJson(sb.toString());
        } catch (IOException e) {
            logger.error("Failed to load state from local file: " + stateId, e);
            return null;
        }
    }

    private boolean isValid(Calendar lastUpdate) {
        // adjust the validity period as needed
        Calendar now = Calendar.getInstance();
        return lastUpdate.before(now.add(Calendar.DAY_OF_MONTH, 1));
    }
}
