import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import org.apache.kafka.streams.KafkaStreams;
import org.apache.kafka.streams.StreamsBuilder;
import org.apache.kafka.streams.kstream.KStream;
import org.apache.kafka.streams.state.ThreadSafeMap;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;

public class MetricExtractor {
    private KafkaStreams streams;
    private ThreadSafeMap<String, List<Metric>> metricCache = new ThreadSafeMap<>();

    public MetricExtractor(StreamsBuilder builder) {
        this.streams = new KafkaStreams(builder.build(), builder.configuration());
        streams.start();
    }

    public void extractMetrics(String[] metricsToExtract) {
        KStream<String, JsonNode> logs = streams.builder().stream("logs");

        // Process and extract specific metrics from JSON logs
        for (String metric : metricsToExtract) {
            logs.map((key, value) -> extractMetric(metric, value))
                .peek((k, v) -> cacheMetric(metric, v));
        }
    }

    private JsonNode extractMetric(String metricName, JsonNode log) {
        try {
            ObjectMapper mapper = new ObjectMapper();
            ObjectNode node = (ObjectNode) mapper.readTree(log.toString());
            return node.get(metricName);
        } catch (Exception e) {
            // Handle malformed logs or missing fields
            System.out.println("Error extracting metric: " + e.getMessage());
            return null;
        }
    }

    private void cacheMetric(String metricName, JsonNode value) {
        List<Metric> cachedMetrics = metricCache.getOrDefault(metricName, new ArrayList<>());
        cachedMetrics.add(new Metric(metricName, value));
        metricCache.put(metricName, cachedMetrics);
    }

    // Implement real-time aggregation and alerting based on predefined thresholds
    public void aggregateAndAlert(String metricName, double threshold) {
        List<Metric> metrics = metricCache.getOrDefault(metricName, new ArrayList<>());

        if (metrics.size() > 0) {
            double sum = 0;
            for (Metric m : metrics) {
                sum += m.getValue().doubleValue();
            }

            if (sum > threshold) {
                // Send alert
                System.out.println("Alert: " + metricName + " exceeded threshold");
            } else {
                // No alert needed
            }
        } else {
            // No data to aggregate or alert on
        }
    }

    public static class Metric {
        private String name;
        private JsonNode value;

        public Metric(String name, JsonNode value) {
            this.name = name;
            this.value = value;
        }

        public String getName() {
            return name;
        }

        public JsonNode getValue() {
            return value;
        }
    }
}
