import json
import paramiko
import os
import time
import logging
from concurrent.futures import ThreadPoolExecutor, as_completed
import hashlib
import requests

class ServerConfig:
    def __init__(self):
        self.config_file = 'server_config.json'
        self.load_config()

    def load_config(self):
        with open(self.config_file, 'r') as f:
            config = json.load(f)
        self.servers = {server['name']: Server(server, config.get('rate_limit', 5)) for server in config.get('servers', [])}
        self.commands = {command['name']: Command(command) for command in config.get('commands', [])}

class Server:
    def __init__(self, credentials, rate_limit):
        self.name = credentials['name']
        self.username = credentials['username']
        self.password = credentials['password']
        self.host = credentials['host']
        self.rate_limit = rate_limit

    def connect(self):
        try:
            ssh = paramiko.SSHClient()
            ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            ssh.connect(self.host, username=self.username, password=self.password)
            return ssh
        except Exception as e:
            logging.error(f"Failed to connect to {self.name}: {str(e)}")

    def execute_command(self, command):
        try:
            stdin, stdout, stderr = self.connect().exec_command(command)
            output = stdout.read().decode()
            if stderr.read():
                logging.error(output)
            return output
        except Exception as e:
            logging.error(f"Failed to execute {command} on {self.name}: {str(e)}")

    def transfer_file(self, local_path):
        try:
            sftp = self.connect().open_sftp()
            remote_path = os.path.join('/path/to/remote', os.path.basename(local_path))
            sftp.put(local_path, remote_path)
        except Exception as e:
            logging.error(f"Failed to transfer {local_path} to {self.name}: {str(e)}")

class Command:
    def __init__(self, config):
        self.name = config['name']
        self.command = config['command']

class FileVerification:
    def __init__(self, local_path):
        self.local_path = local_path
        self.md5_checksum = hashlib.md5(open(local_path, 'rb').read()).hexdigest()

    def verify(self, remote_path):
        try:
            remote_md5_checksum = paramiko.SFTPClient.from_socket(paramiko.open_sftp_client(self.connect().get_transport())).stat(remote_path).st_size
            return self.md5_checksum == remote_md5_checksum
        except Exception as e:
            logging.error(f"Failed to verify {self.local_path} on the server: {str(e)}")

class DiskMonitoring:
    def __init__(self, server):
        self.server = server

    def monitor(self):
        try:
            disk_usage = self.server.connect().exec_command('df -h').stdout.read().decode()
            if float(disk_usage.split('%')[1].strip()) > 80:
                logging.error(f"Disk usage on {self.server.name} exceeded 80% threshold!")
        except Exception as e:
            logging.error(f"Failed to monitor disk usage on {self.server.name}: {str(e)}")

    def send_notification(self):
        try:
            requests.post('https://your-monitoring-system.com/api/disk_usage', json={'server': self.server.name, 'disk_usage': 80})
        except Exception as e:
            logging.error(f"Failed to send disk usage notification: {str(e)}")

def main():
    config = ServerConfig()
    with ThreadPoolExecutor() as executor:
        for server in config.servers.values():
            for command in config.commands.values():
                if command.execute_command(server.name):
                    try:
                        file_verification = FileVerification('path/to/local/file')
                        if not file_verification.verify('/path/to/remote'):
                            logging.error(f"File verification failed on {server.name}!")
                    except Exception as e:
                        logging.error(f"Failed to verify file transfer: {str(e)}")
                else:
                    executor.submit(server.execute_command, command.name)
            try:
                disk_monitoring = DiskMonitoring(server)
                disk_monitoring.monitor()
                if server.rate_limit > 5:
                    disk_monitoring.send_notification()
            except Exception as e:
                logging.error(f"Failed to monitor disk usage on {server.name}: {str(e)}")

if __name__ == '__main__':
    main()

