```java
package configurable_component;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.LoadingCache;

import java.io.File;
import java.io.IOException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;

public abstract class ConfigurableComponent {

    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();
    static {
        OBJECT_MAPPER.enable(SerializationFeature.INDENT_OUTPUT);
    }

    public interface Factory {
        Object getInstance(Map<String, Object> config);
    }

    private static final Map<String, Factory> REGISTRY = CacheBuilder.newBuilder()
            .initialCapacity(1000)
            .maximumSize(10000)
            .expireAfterWrite(10, TimeUnit.MINUTES)
            .build(() -> new HashMap<>());

    public static void registerFactory(String id, Factory factory) {
        REGISTRY.put(id, factory);
    }

    public static Object getInstanceFromJson(String json, String id) throws IOException {
        Map<String, Object> config = OBJECT_MAPPER.readValue(json, Map.class);
        return REGISTRY.getIfPresent(id).map(factory -> factory.getInstance(config)).orElse(null);
    }

    public static void saveRegistryToFile(File file) throws IOException {
        OBJECT_MAPPER.writeValue(file, REGISTRY.asMap());
    }

    public static List<String> getRegisteredIds() {
        return new ArrayList<>(REGISTRY.keySet());
    }
}

package configurable_component;

import com.google.common.reflect.TypeToken;
import java.io.File;
import java.util.List;

public class Registry {

    private final LoadingCache<String, ConfigurableComponent.Factory> registry = CacheBuilder.newBuilder()
            .initialCapacity(1000)
            .maximumSize(10000)
            .expireAfterWrite(10, TimeUnit.MINUTES)
            .build(() -> new HashMap<>());

    public void scanDirectory(String directory) {
        File file = new File(directory);
        for (File subclass : file.listFiles()) {
            if (subclass.isFile() && subclass.getName().endsWith(".class")) {
                String id = subclass.getName().substring(0, subclass.getName().length() - 6).toLowerCase();
                try {
                    Class<?> clazz = Class.forName("subclasses." + id);
                    ConfigurableComponent.Factory factory = () -> (ConfigurableComponent) clazz.getConstructor(Map.class).newInstance(new HashMap<>());
                    registry.put(id, factory);
                } catch (ClassNotFoundException e) {
                    // Ignore
                }
            }
        }
    }

    public List<String> getRegisteredIds() {
        return new ArrayList<>(registry.asMap().keySet());
    }
}

