#include <websocketpp/config/asio_client.hpp>
#include <websocketpp/stream/websocket_server.hpp>

using namespace websocketpp;

class WebSocketClient {
public:
    WebSocketClient(asio::ip::address_v4 address, uint16_t port) 
        : client_(asio::ip::address_v4(address), port) {}

    void connect() {
        client_.set_tls_init_func([](boost::asio::ssl::context& ctx) {
            ctx.set_options(ssl::context::client)
                .set_verify_mode(ssl::context::verify_peer | ssl::context::verify_fail_if_no_peer_cert);

            // Load client certificate
            boost::asio::io_service io;
            boost::asio::ssl::context tls_ctx(io);
            tls_ctx.set_options(tls_ctx.client());
            tls_ctx.load_verify_file("path_to_client_certificate.pem", true);

            // Set private key and pre-shared key for deriving encryption keys
            tls_ctx.private_key_file("path_to_private_key.pem");
            tls_ctx.set_password_callback([this](const std::string& password) {
                return "password_for_private_key";
            });
        });

        client_.connect();
    }

    void send(const std::string& message) {
        boost::asio::streambuf buffer;
        boost::asio::write(buffer, boost::asio::buffer(message));
        client_.send(buffer.str());
    }

    void receive(std::function<void(const std::string&)> callback) {
        client_.set_message_handler([this, &callback](websocketpp::connection_hdl hdl, websocketpp::frame::easy_frame f) {
            const std::string& message = f.get_payload();
            callback(message);
        });
    }

    void reconnect() {
        if (!client_.is_connected()) {
            connect();
        }
    }

    void heartbeat() {
        // Send a heartbeat message to the server
        client_.send("heartbeat");
    }

    ~WebSocketClient() {
        if (client_.is_connected()) {
            client_.shutdown();
        }
    }

private:
    websocketpp::client<websocketpp::config::asio_client> client_;
};

