use std::env;
use std::fs::{create_dir_all, read_dir};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

use serde_json::{Error, JSONValue};

struct WorkspaceManager {
    config: Arc<Mutex<JsonValue>>,
}

impl WorkspaceManager {
    fn new(config_path: &str) -> Result<Self, Error> {
        let config = Arc::new(Mutex::new(JSONValue::null()));
        match read_config(config_path, config.clone()) {
            Ok(_) => Ok(WorkspaceManager { config }),
            Err(e) => Err(e),
        }
    }

    fn create_dir(&self, dir_name: &str) -> Result<(), std::io::Error> {
        let mut lock = self.config.lock();
        let dir_path = PathBuf::from(env::var("PROJECT_WORKSPACE_DIR").unwrap_or_default());
        let new_dir_path = dir_path.join(dir_name);
        create_dir_all(&new_dir_path)?;
        *lock = JSONValue::Object(vec![("PROJECT_WORKSPACE_DIR".to_string(), new_dir_path.to_str().unwrap().into())]);
        Ok(())
    }

    fn cleanup_dirs(&self) {
        thread::spawn(move || {
            let lock = self.config.lock();
            match read_dir(&Path::new(&env::var("PROJECT_WORKSPACE_DIR").unwrap_or_default())) {
                Ok(mut dir_iter) => {
                    loop {
                        match dir_iter.next() {
                            Some(Ok(entry)) => {
                                let entry_path = &entry.path;
                                if !is_used_workspace(&entry_path, lock.as_ref()) {
                                    std::fs::remove_dir_all(&entry_path)?;
                                }
                            }
                            _ => break,
                        }
                    }
                }
                Err(_) => {}
            }
        });
    }

    fn api_interact(&self) {
        // API interactions will go here
    }
}

fn read_config(config_path: &str, config: Arc<Mutex<JsonValue>>) -> Result<(), Error> {
    let content = std::fs::read_to_string(config_path)?;
    *config = JSONValue::parse_str(&content)?;
    Ok(())
}

fn is_used_workspace(path: &Path, lock: &Mutex<JsonValue>) -> bool {
    let lock = lock.lock();
    match lock.get("PROJECT_WORKSPACE_DIR") {
        Some(value) => value.as_str().unwrap_or_default() == path.to_str().unwrap(),
        None => false,
    }
}
