// Module structures and functions
typedef struct {
    const char *name;
    void (*init)(void);
    void (*destroy)(void);
    int (*aes_encrypt)(const unsigned char *, size_t, unsigned char *, size_t);
    // ... other cipher functions ...
} CipherModule;

CipherModule *cipher_modules[] = {
    {"AES", aes_init, aes_destroy, aes_encrypt},
    {"Camellia", camellia_init, camellia_destroy, camellia_encrypt},
    // ... add more modules ...
};

void load_module(const char *module_name) {
    for (int i = 0; i < sizeof(cipher_modules) / sizeof(*cipher_modules); i++) {
        if (strcmp(module_name, cipher_modules[i]->name) == 0) {
            cipher_modules[i]->init();
            return;
        }
    }
}

void unload_module(const char *module_name) {
    for (int i = 0; i < sizeof(cipher_modules) / sizeof(*cipher_modules); i++) {
        if (strcmp(module_name, cipher_modules[i]->name) == 0) {
            cipher_modules[i]->destroy();
