function runUnitTests(moduleLabel, testSuites, config = {}) {
    const {
        concurrency = 1,
        timeout = 3000,
        retries = 3,
        delay = 100,
    } = config;

    async function runTestSuite(suite) {
        let testsPassed = 0;
        try {
            await Promise.all(
                suite.map((test) => {
                    return new Promise((resolve, reject) => {
                        // Run test with concurrency
                        const startTime = Date.now();
                        (async () => {
                            try {
                                await test();
                                resolve();
                            } catch (err) {
                                reject(err);
                            }
                        })();
                        setTimeout(() => {
                            if (Date.now() - startTime > timeout) {
                                throw new Error(`Test timeout exceeded`);
                            }
                        }, timeout);
                    });
                })
            );
            testsPassed = suite.length;
        } catch (err) {
            console.error(`Error running test suite ${suite.name}: ${err}`);
        }

        // Log test results
        if (testsPassed > 0) {
            console.log(`Test suite ${suite.name} passed: ${testsPassed}/${suite.length}`);
        }
    }

    const runner = require(config.runner);
    await Promise.all(
        testSuites.map((suite, index) => runTestSuite(suite))
    );

    // Log overall test results
    if (testSuites.every((suite) => suite.every((test) => !test.error))) {
        console.log(`All tests passed: ${testSuites.length}/${testSuites.length}`);
    } else {
        console.log(`Some tests failed: ${testSuites.length - testsPassed}/${testSuites.length}`);
    }
}
