use std::path::{Path, PathBuf};
use std::io;
use git2::{Repository, Config};
use reqwest;

async fn get_remote_config_dir(repo_url: &str) -> Result<PathBuf, io::Error> {
    let repo = Repository::open(&repo_url)?;
    let config = repo.find_commit("main")?.tree()?;
    let dir_path = config.find_path("config")?;
    Ok(dir_path.path())
}

async fn create_local_config_dir() -> Result<PathBuf, io::Error> {
    let local_dir = Path::new(".config");
    if !local_dir.exists() {
        try_create_dir(local_dir)?;
    }
    Ok(local_dir.to_path_buf())
}

async fn clone_remote_repo(repo_url: &str) -> Result<(), io::Error> {
    let repo = Repository::clone(&repo_url, ".temp")?;
    Ok(())
}

async fn init_local_config_dir() -> Result<(), io::Error> {
    let local_dir = Path::new(".config");
    if !local_dir.exists() {
        try_create_dir(local_dir)?;
    }
    Ok(())
}

async fn push_local_config_dir() -> Result<(), io::Error> {
    let repo = Repository::open(".")?;
    let _ = repo.push("origin", "main")?;
    Ok(())
}

fn try_create_dir(path: &Path) -> Result<(), io::Error> {
    if !path.exists() {
        std::fs::create_dir_all(&path)?;
    }
    Ok(())
}

async fn main() -> Result<(), reqwest::Error> {
    let repo_url = "https://github.com/user/config-repo";
    let local_dir = create_local_config_dir().await?;

    match get_remote_config_dir(repo_url).await {
        Ok(remote_dir) => {
            if remote_dir.exists() {
                clone_remote_repo(repo_url).await?;
                init_local_config_dir().await?;
                push_local_config_dir().await?;
            } else {
                // Create a new local directory
                try_create_dir(&local_dir)?;
                // Push to the remote repository
                push_local_config_dir().await?;
            }
        },
        Err(err) => {
            eprintln!("Error: {}", err);
            std::process::exit(1);
        }
    }

    Ok(())
}

#[tokio::main]
async fn run() -> Result<(), reqwest::Error> {
    main().await
}
