public void establishConnection(String remoteAddress) throws IOException {
    SocketChannel channel = SocketChannel.open();
    channel.connect(new InetSocketAddress(remoteAddress));

    channel.configureBlocking(true);
    while (true) {
        int status = channel.status();
        if (status == ChannelStatus.CONNECTED) {
            System.out.println("Connected to " + remoteAddress);
            break;
        } else if (status == ChannelStatus.DISCONNECTED) {
            System.out.println("Disconnected from " + remoteAddress);
            return;
        }
    }

    // Handle connection state changes
    channel.register(selector, SelectionKey.OP_READ | SelectionKey.OP_WRITE);
}
