```csharp
using System;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;

public abstract class DynamicTextProcessor
{
    public static readonly HttpClient _httpClient = new();
    private readonly ILoggingService _loggingService;
    private readonly HashSet<HashAlgorithmFactory> _hashFactories = new();

    protected DynamicTextProcessor(ILoggingService loggingService)
    {
        _loggingService = loggingService;
        AddHashAlgorithms();
    }

    public void AddHashAlgorithms()
    {
        _hashFactories.Add(new Md5HashAlgorithmFactory());
        _hashFactories.Add(new Sha1HashAlgorithmFactory());
        _hashFactories.Add(new Sha256HashAlgorithmFactory());
    }

    public async Task<string> ProcessUserInput(string userInput, string algorithm)
    {
        if (string.IsNullOrEmpty(userInput))
            throw new ArgumentException("Input cannot be null or empty");

        var maxAllowedLength = await GetUserSettingsAsync();
        if (userInput.Length > maxAllowedLength)
            throw new InvalidOperationException($"Input exceeds the maximum allowed length: {maxAllowedLength}");

        try
        {
            using var memoryStream = new MemoryStream(userInput.GetBytes());
            var hashAlgorithmFactory = _hashFactories.Find(f => f.AlgorithmName == algorithm);
            if (hashAlgorithmFactory == null)
                throw new ArgumentException("Invalid hash algorithm");

            var stopwatch = Stopwatch.StartNew();
            var hashValue = await ProcessHashAsync(memoryStream, hashAlgorithmFactory.Create());
            stopwatch.Stop();

            _loggingService.LogInformation($"Processed input of length {userInput.Length} using algorithm {algorithm} in {stopwatch.ElapsedMilliseconds} ms");
            return hashValue;
        }
        catch (HttpRequestException ex)
        {
            _loggingService.LogError("Failed to process user input", ex);
            throw;
        }
    }

    private async Task<int> GetUserSettingsAsync()
    {
        // Fetch user settings from API
        var response = await _httpClient.GetAsync("user/settings");
        if (!response.IsSuccessStatusCode)
            throw new HttpRequestException("Failed to fetch user settings");

        return int.Parse(await response.Content.ReadAsStringAsync());
    }

    private async Task<string> ProcessHashAsync(Stream stream, HashAlgorithm hashAlgorithm)
    {
        using var md5Stream = new MemoryStream();
        await hashAlgorithm.ComputeHashAsync(stream, md5Stream);
        return md5Stream.ToArray().ToHexString();
    }
}

public interface ILoggingService
{
    void LogInformation(string message);
    void LogError(string message, Exception ex);
}

public class LoggingService : ILoggingService
{
    public void LogInformation(string message)
    {
        Console.WriteLine(message);
    }

    public void LogError(string message, Exception ex)
    {
        Console.WriteLine($"Error: {message} ({ex.Message})");
    }
}

public interface HashAlgorithmFactory
{
    string AlgorithmName { get; }
    HashAlgorithm Create();
}

public class Md5HashAlgorithmFactory : HashAlgorithmFactory
{
    public override string AlgorithmName => "MD5";

    public override HashAlgorithm Create() => new MD5CryptoServiceProvider();
}

public class Sha1HashAlgorithmFactory : HashAlgorithmFactory
{
    public override string AlgorithmName => "SHA1";

    public override HashAlgorithm Create() => new SHA1CryptoServiceProvider();
}

public class Sha256HashAlgorithmFactory : HashAlgorithmFactory
{
    public override string AlgorithmName => "SHA256";

    public override HashAlgorithm Create() => new SHA256CryptoServiceProvider();
}

public abstract class HashAlgorithm
{
    public abstract byte[] ComputeHash(Stream stream);
}

public class MD5CryptoServiceProvider : HashAlgorithm
{
    public override byte[] ComputeHash(Stream stream)
    {
        using var md5 = MD5.Create();
        return md5.ComputeHash(stream);
    }
}

public class SHA1CryptoServiceProvider : HashAlgorithm
{
    public override byte[] ComputeHash(Stream stream)
    {
        using var sha1 = SHA1.Create();
        return sha1.ComputeHash(stream);
    }
}

public class SHA256CryptoServiceProvider : HashAlgorithm
{
    public override byte[] ComputeHash(Stream stream)
    {
        using var sha256 = SHA256.Create();
        return sha256.ComputeHash(stream);
    }
}
