import asyncio
import os
from aiofiles import open as aio_open
from concurrent.futures import ThreadPoolExecutor
from typing import List

class MergeFiles:
    def __init__(self):
        self.pool = ThreadPoolExecutor()

    async def merge_files(self, file_paths: List[str], destination_path: str):
        chunk_size = 1024 * 1024 * 10  # adjust this value based on your needs
        retry_count = 3

        async def read_file(file_path):
            try:
                reader, writer = await asyncio.open_unix_connection(file_path)
                return await reader.read()
            except (OSError, asyncio.exceptions.ConnectionError) as e:
                if retry_count > 0:
                    await asyncio.sleep(1)  # wait before re-trying
                    return await read_file(file_path)
                else:
                    raise Exception(f"Failed to open file {file_path}: {e}")

        async def write_chunk(destination_writer, chunk):
            while True:
                try:
                    destination_writer.write(chunk[:chunk_size])
                    break
                except OSError as e:
                    if retry_count > 0:
                        await asyncio.sleep(1)  # wait before re-trying
                        continue
                    else:
                        raise Exception(f"Failed to write to {destination_path}: {e}")

        async def merge_file_chunks():
            destination_writer = await aio_open(destination_path, 'wb')
            file_contents = await asyncio.gather(*[read_file(file_path) for file_path in file_paths])
            for chunk in [b"".join(chunk.split(b"")) for chunk in zip(*[file_content[i:i+chunk_size] for i, file_content in enumerate(file_contents)])]:
                await write_chunk(destination_writer, chunk)
            await destination_writer.close()

        await merge_file_chunks()
