                case 'create':
                    // Create new user account
                    if (!empty($_POST['id'])) {
                        $status = 'error';
                        $message = 'Error: User with the provided ID already exists.';
                    } elseif (empty($_POST['password']) || empty($_POST['confirm_password'])) {
                        $status = 'error';
                        $message = 'Error: Password and confirm password cannot be blank.';
                    } elseif (!preg_match('/^[a-zA-Z0-9_]+$/', $_POST['name'])) {
                        $status = 'error';
                        $message = 'Error: Invalid user name. Only letters, numbers, and underscores are allowed.';
                    } elseif (!filter_var($_POST['email'], FILTER_VALIDATE_EMAIL)) {
                        $status = 'error';
                        $message = 'Error: Invalid email address.';
                    } elseif ($_POST['password'] !== $_POST['confirm_password']) {
                        $status = 'error';
                        $message = 'Error: Passwords do not match.';
                    } else {
                        // Check if the provided email is unique in the database
                        $uniqueEmail = db_query("SELECT 1 FROM users WHERE email = ?", array($_POST['email']))->fetchAll();
                        if (empty($uniqueEmail)) {
                            // Create new user account
                            db_query("INSERT INTO users (name, email, password) VALUES (?, ?, ?)", array($_POST['name'], $_POST['email'], $_POST['password']));
                            $data = array('id' => db_last_insert_id(), 'name' => $_POST['name'], 'email' => $_POST['email']);
                        } else {
                            $status = 'error';
                            $message = 'Error: Email address already exists.';
                        }
                    }
                    break;
                case 'update':
                    // Update existing user account
                    if (empty($_POST['id'])) {
                        $status = 'error';
                        $message = 'Error: User ID is required for update operation.';
                    } elseif (empty($_POST['password']) && empty($_POST['confirm_password'])) {
                        // Only update non-password fields
                        db_query("UPDATE users SET name = ?, email = ? WHERE id = ?", array($_POST['name'], $_POST['email'], $_POST['id']));
                        $data = array('id' => $_POST['id'], 'name' => $_POST['name'], 'email' => $_POST['email']);
                    } elseif (!preg_match('/^[a-zA-Z0-9_]+$/', $_POST['name'])) {
                        $status = 'error';
                        $message = 'Error: Invalid user name. Only letters, numbers, and underscores are allowed.';
                    } elseif (!filter_var($_POST['email'], FILTER_VALIDATE_EMAIL)) {
                        $status = 'error';
                        $message = 'Error: Invalid email address.';
                    } elseif ($_POST['password'] !== $_POST['confirm_password']) {
                        $status = 'error';
                        $message = 'Error: Passwords do not match.';
                    } else {
                        // Update existing user account
                        db_query("UPDATE users SET name = ?, email = ? WHERE id = ?", array($_POST['name'], $_POST['email'], $_POST['id']));
                        $data = array('id' => $_POST['id'], 'name' => $_POST['name'], 'email' => $_POST['email']);
                    }
                    break;
                case 'delete':
                    // Delete user account
                    if (empty($_POST['id'])) {
                        $status = 'error';
                        $message = 'Error: User ID is required for delete operation.';
                    } else {
                        db_query("DELETE FROM users WHERE id = ?", array($_POST['id']));
                        $data = array('id' => $_POST['id'], 'name' => '', 'email' => '');
                    }
                    break;
                default:
                    $status = 'error';
                    $message = 'Error: Invalid sub_action. Only create, update, and delete operations are supported.';
            }
        } else {
            // Handle request with no sub_action
            if (!empty($_POST['id'])) {
                // Delete user account by ID
                db_query("DELETE FROM users WHERE id = ?", array($_POST['id']));
                $data = array('id' => $_POST['id'], 'name' => '', 'email' => '');
