#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_RETRIES 3
#define RETRY_DELAY 1000 // in milliseconds

int async_aggregate_data(pthread_t* sources, int num_sources, int initial_semaphore_value) {
    pthread_mutex_t semaphore = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    int aggregated_data[initial_semaphore_value];

    for (int i = 0; i < initial_semaphore_value; i++) {
        aggregated_data[i] = 0;
    }

    pthread_mutex_init(&semaphore, NULL);
    pthread_cond_init(&cond, NULL);

    pthread_t semaphore_thread = pthread_create(NULL, NULL, semaphore_thread_func, &semaphore);
    if (semaphore_thread) {
        return 1; // error creating thread
    }

    for (int i = 0; i < num_sources; i++) {
        int source_id;
        void* future_value;

        pthread_mutex_lock(&semaphore);

        source_id = sources[i].first;
        future_value = sources[i].second.get(); // blocking call

        if (!future_value) {
            for (int retry = 0; retry < MAX_RETRIES; retry++) {
                printf("Source %d: Waiting for data... Retrying in %d milliseconds.\n", source_id, RETRY_DELAY);
                sleep(RETRY_DELAY / 1000); // convert milliseconds to seconds
                future_value = sources[i].second.get(); // blocking call
                if (future_value) break;
            }
        }

        pthread_mutex_unlock(&semaphore);

        if (!future_value) {
            printf("Source %d: Failed to retrieve data. Ignoring.\n", source_id);
            continue; // move on to the next source
        }

        int value = *(int*)future_value;

        pthread_mutex_lock(&semaphore);
        aggregated_data[value]++;
        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&semaphore);
    }

    pthread_join(semaphore_thread, NULL);

    return 0;
}

void* semaphore_thread_func(void* arg) {
    pthread_mutex_t* semaphore = (pthread_mutex_t*)arg;

    for (;;) {
        pthread_cond_wait(&cond, &semaphore->mutex);
        // process aggregated data here
    }

    return NULL;
}
