namespace GameSettingsService
{
    public class SettingsManager
    {
        private readonly HttpClient _httpClient;
        private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1);

        public SettingsManager(HttpClient httpClient)
        {
            _httpClient = httpClient;
        }

        public async Task LoadGameSettings()
        {
            try
            {
                using (var response = await _httpClient.GetAsync("game-settings"))
                {
                    response.EnsureSuccessStatusCode();
                    var settingsJson = await response.Content.ReadAsStringAsync();

                    // Deserialize JSON and update game resources
                    var settings = JsonConvert.DeserializeObject<GameSettings>(settingsJson);
                    UpdateGameResources(settings);

                    Console.WriteLine("Game settings loaded successfully.");
                }
            }
            catch (HttpRequestException ex)
            {
                Console.WriteLine($"Error loading game settings: {ex.Message}");
            }
        }

        public void SaveGameSettings(GameSettings settings)
        {
            try
            {
                using (var content = new StringContent(JsonConvert.SerializeObject(settings), Encoding.UTF8, "application/json"))
                {
                    _httpClient.PostAsync("game-settings", content).Wait();
                }
            }
            catch (HttpRequestException ex)
            {
                Console.WriteLine($"Error saving game settings: {ex.Message}");
            }
        }

        private void UpdateGameResources(GameSettings settings)
        {
            // Update tile size, world dimensions, and camera speed
            TileSize = settings.TileSize;
            WorldDimensions = settings.WorldDimensions;
            CameraSpeed = settings.CameraSpeed;

            // Notify other parts of the game that settings have changed
            GameUpdated();
        }

        public event EventHandler GameUpdated;

        private int _tileSize;
        public int TileSize { get => _tileSize; set { _semaphore.Wait(); try { _tileSize = value; } finally { _semaphore.Release(); } } }

        private Rectangle _worldDimensions;
        public Rectangle WorldDimensions { get => _worldDimensions; set { _semaphore.Wait(); try { _worldDimensions = value; } finally { _semaphore.Release(); } } }

        private float _cameraSpeed;
        public float CameraSpeed { get => _cameraSpeed; set { _semaphore.Wait(); try { _cameraSpeed = value; } finally { _semaphore.Release(); } } }
    }

    public class GameSettings
    {
        public int TileSize { get; set; }
        public Rectangle WorldDimensions { get; set; }
        public float CameraSpeed { get; set; }
    }

    public class GameForm : Form
    {
        private readonly SettingsManager _settingsManager;

        public GameForm(SettingsManager settingsManager)
        {
            _settingsManager = settingsManager;
            InitializeComponent();
        }

