from datetime import datetime, timedelta
from configparser import ConfigParser
from requests import get

class ConfigSettings:
    pass  # Implement your custom config class here

def load_config(config_file_path: str, cache_expiration_time: int = 3600):
    lock = threading.Lock()

    def init_cache():
        nonlocal cache
        cache = {}

    cache = {}
    init_cache()
    cache_lock = lock

    def get_cached_config(file_name: str) -> dict:
        with cache_lock:
            if file_name in cache and datetime.now() - cache[file_name]['last_update'] <= timedelta(seconds=cache_expiration_time):
                return cache[file_name]['config']
        return None

    def set_cache(file_name: str, config):
        nonlocal cache
        with cache_lock:
            cache[file_name] = {'config': config, 'last_update': datetime.now()}

    def read_config_from_file(file_path):
        try:
            with open(file_path, 'r') as file:
                return json.load(file)
        except (FileNotFoundError, json.JSONDecodeError):
            return None

    def check_for_updates(config_file_name: str) -> dict:
        url = f'https://config-service.com/{config_file_name}'
        response = get(url)
        if response.status_code == 200:
            try:
                return response.json()
            except json.JSONDecodeError:
                pass
        return None

    def load_config_from_service(config_file_name: str) -> dict:
        url = f'https://config-service.com/{config_file_name}'
        response = get(url)
        if response.status_code == 200:
            try:
                return response.json()
            except json.JSONDecodeError:
                pass
        return None

    def load_config_helper(file_path):
        config_file_name = os.path.basename(file_path)
        cached_config = get_cached_config(config_file_name)

        if cached_config is not None:
            print(f'Loaded configuration from cache ({config_file_name}).')
            return cached_config

        latest_config = check_for_updates(config_file_name)
        if latest_config is not None:
            print(f'Updated configuration found on service for {config_file_name}.')
            set_cache(config_file_name, latest_config)
            return latest_config

        config = read_config_from_file(file_path)

        if isinstance(config, dict) and isinstance(config.get('type'), str):
            if config['type'] == ConfigSettings.__name__:
                print(f'Loaded configuration from file ({config_file_name}).')
                set_cache(config_file_name, config)
                return config
            else:
                return None

        print(f'Failed to load configuration for {config_file_name}.')
        return None

    return load_config_helper(config_file_path)

