use std::fs;
use std::path::{Path, PathBuf};
use std::error::Error;
use regex::Regex;

pub struct ConfigManager {
    config_dir: String,
}

impl ConfigManager {
    pub fn new(config_dir: &str) -> Result<Self, Box<dyn Error>> {
        let config_manager = Self { config_dir: config_dir.to_string() };
        config_manager.create_config_dir()?;
        Ok(config_manager)
    }

    pub fn create_config_dir(&self) -> Result<(), Box<dyn Error>> {
        fs::create_dir_all(&PathBuf::from(self.config_dir.clone()))?;
        Ok(())
    }

    pub fn get_cryptographic_functions(&self) -> Vec<String> {
        let mut cryptographic_functions = vec![];
        for entry in fs::read_dir(&PathBuf::from(self.config_dir.clone())).unwrap() {
            let entry = entry.unwrap();
            let path = entry.path();
            if path.is_file() && path.extension().unwrap_or_default().to_string_lossy().eq("config") {
                let config_contents = fs::read_to_string(path).unwrap();
                let re = Regex::new(r"^[a-zA-Z]+$").unwrap();
                for line in config_contents.lines() {
                    if re.is_match(line) {
                        cryptographic_functions.push(line.to_string());
                    }
                }
            }
        }
        cryptographic_functions.sort_unstable();
        cryptographic_functions
    }

    pub fn get_last_sequence_number(&self) -> Result<u32, Box<dyn Error>> {
        let entries = fs::read_dir(&PathBuf::from(self.config_dir.clone())).unwrap();
        let mut last_entry = None;
        for entry in entries {
            let entry = entry.unwrap();
            let path = entry.path();
            if path.is_file() && path.extension().unwrap_or_default().to_string_lossy().eq("config") {
                let config_contents = fs::read_to_string(path).unwrap();
                let re = Regex::new(r"sequence_number=\d+").unwrap();
                for line in config_contents.lines() {
                    if let Some(capture) = re.captures(line) {
                        let sequence_number: u32 = capture.get(1).unwrap().as_str().parse()?;
                        last_entry = Some((path.clone(), sequence_number));
                    }
                }
            }
        }
        match last_entry {
            None => Err("No config files found".into()),
            Some((_, sequence_number)) => Ok(*sequence_number),
        }
    }
}

