from flask import Flask, request, jsonify
import hashlib
import psycopg2

app = Flask(__name__)

@app.route('/update_resource', methods=['PUT'])
def update_resource():
    resource_id = request.args.get('resource_id')
    version = request.args.get('version')

    # Connect to database and update the resource
    conn = psycopg2.connect(
        host='localhost',
        database='mydatabase',
        user='myuser',
        password='mypassword'
    )
    cursor = conn.cursor()

    if not resource_id:
        return jsonify({'error': 'Resource ID is required'}), 400

    try:
        cursor.execute("UPDATE resources SET data = %s WHERE id = %s AND version = %s", (request.get_json(), resource_id, version))
        conn.commit()
    except psycopg2.Error as e:
        conn.rollback()
        return jsonify({'error': str(e)}), 500
    finally:
        if conn:
            cursor.close()
            conn.close()

    return jsonify({'message': 'Resource updated successfully'}), 200

@app.route('/calculate_md5', methods=['POST'])
def calculate_md5():
    file_path = request.args.get('file_path')

    if not file_path:
        return jsonify({'error': 'File path is required'}), 400

    try:
        md5_hash = hashlib.md5()

        with open(file_path, 'rb') as file:
            while True:
                chunk = file.read(4096)
                if not chunk:
                    break
                md5_hash.update(chunk)

        return jsonify({'md5': md5_hash.hexdigest()}), 200

    except FileNotFoundError:
        return jsonify({'error': 'File not found'}), 404
    except Exception as e:
        return jsonify({'error': str(e)}), 500

