#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <semaphore.h>
#include <pthread.h>

// Define the structure for a named semaphore
typedef struct {
    sem_t* sem;
    char name[64];
} Semaphore;

// Function to create a named semaphore with an initial value
Semaphore* create_semaphore(const char* name, int value) {
    Semaphore* sem = (Semaphore*)malloc(sizeof(Semaphore));
    sem->sem = sem_open(name, O_CREAT | O_EXCL | O_RDWR, 0644);
    sem_init(sem->sem, 1, value);
    strcpy(sem->name, name);
    return sem;
}

// Function to delete a named semaphore
void delete_semaphore(Semaphore* sem) {
    sem_close(sem->sem);
    free(sem);
}

// Function to acquire a semaphore (wait if necessary)
void acquire_semaphore(Semaphore* sem) {
    sem_wait(sem->sem);
}

// Function to release a semaphore
void release_semaphore(Semaphore* sem) {
    sem_post(sem->sem);
}

// Function to get the current value of a semaphore
int get_semaphore_value(Semaphore* sem) {
    return sem_getvalue(sem->sem);
}

// Function to set the value of a semaphore
void set_semaphore_value(Semaphore* sem, int value) {
    sem_close(sem->sem);
    sem_init(sem->sem, 1, value);
    sem_open(sem->name, O_CREAT | O_EXCL | O_RDWR, 0644);
}

// Function to log semaphore operations and errors
void log_semaphore_operation(Semaphore* sem, const char* operation) {
    printf("%s: Semaphore %s operation completed.\n", operation, sem->name);
}
