const { Semaphore } = require('semaphore-promised');
const { LRU } = require('lru-cache');

function asyncArrayReduce(arr, initial, callback) {
  const semaphore = new Semaphore(5); // Limit concurrency to 5
  const cache = new LRU({ max: 1000 }); // Cache results for 1000 elements

  function accumulator(acc, current, index) {
    return Promise.resolve(current).then((value) => {
      if (index < arr.length - 1) {
        return acc + value;
      } else {
        return acc;
      }
    });
  }

  async function reduce(arr) {
    let result = initial;

    for (let i = 0; i < arr.length; i++) {
      const current = arr[i];

      if (!cache.has(i)) {
        // Cache miss, make an external API call
        try {
          const token = await fetchToken();
          const response = await apiCall(current, token);
          const result = await accumulator(result, response.data, i);

          cache.set(i, result); // Cache the result
        } catch (error) {
          return { error };
        }
      } else {
        // Cache hit, use cached result
        result = cache.get(i);
      }

      if (callback) {
        try {
          const progress = { completed: i + 1, accumulated: result };
          await callback(progress);
        } catch (error) {
          return { error };
        }
      }

      semaphore.acquire().then(() => {
        reduce(arr.slice(i + 1));
        semaphore.release();
      });
    }

    return { result };
  }

  async function throttle(apiCall, token, current) {
    const throttled = await apiCall(current, token);
    await new Promise((resolve) => setTimeout(resolve, 500)); // Throttle API calls to 2 per second
    return throttled;
  }

  async function fetchToken() {
    // Fetch authentication token securely from a key manager or environment variables
    const token = await getKeyManager().getToken();
    return token;
  }

  return reduce(arr);
}
