public class AsyncXmlReduce
{
    public static async Task<double> ReduceAsync(string[] xmlDocuments, double initialValue, 
        int? parallelism = null, int? throttleRate = null, 
        string[] namespacesToUse = null, 
        bool validateDataAgainstSchema = false)
    {
        // Initialize the result and cache
        double result = initialValue;
        Dictionary<string, object> cache = new Dictionary<string, object>();

        foreach (string xmlDocument in xmlDocuments)
        {
            await ProcessXmlDocumentAsync(xmlDocument, result, parallelism, throttleRate, 
                namespacesToUse, validateDataAgainstSchema, cache);
        }

        return result;
    }

    private static async Task ProcessXmlDocumentAsync(string xmlDocument, double accumulator, 
        int? parallelism, int? throttleRate, string[] namespacesToUse, bool validateDataAgainstSchema, Dictionary<string, object> cache)
    {
        // Parse the XML document
        XmlDocument xmlDoc = new XmlDocument();
        xmlDoc.Load(xmlDocument);

        // Get the root node of the XML document
        XmlElement rootNode = xmlDoc.DocumentElement;

        // Initialize the XPath object with the specified namespaces
        XPathNavigator navigator = xmlDoc.CreateNavigator();
        navigator.NamespaceManager.NameTable.AddNamespace("", "http://example.com");

        // Process each node in the XML document
        await foreach (XmlNode node in TraverseXmlNodesAsync(rootNode, navigator))
        {
            string path = GetXPathPath(node);

            // Check if the node is cached and reuse its value if available
            object cachedValue;
            if (cache.TryGetValue(path, out cachedValue) && cachedValue != null)
            {
                accumulator += Convert.ToDouble(cachedValue);
                continue;
