            // Calculate the accumulated value for this node
            double newNodeAccumulator = AccumulateValuesForNodeAsync(node, navigator, accumulator);

            // Cache the result for future reuse
            cache[path] = newNodeAccumulator;

            // Update the accumulator with the new value
            accumulator += newNodeAccumulator;
        }
    }

    private static async IAsyncEnumerable<XmlNode> TraverseXmlNodesAsync(XmlElement node, XPathNavigator navigator)
