async function asyncArrayReduce(arr, initialVal, callback) {
  const semaphore = new AsyncSemaphore();
  let accumulator = initialVal;
  let numOperationsCompleted = 0;

  async function reduceAccumulator(accumVal, currNum) {
    try {
      await callback(accumVal, currNum);
      accumulator += accumVal + currNum;
    } catch (err) {
      // Handle error
    }
    return accumulator;
  }

  const maxParallelOps = 5; // Set your desired concurrency level here

  async function parallelReduce() {
    for (let i = 0; i < arr.length; i++) {
      await semaphore.take();
      try {
        accumulator = await reduceAccumulator(accumulator, arr[i]);
        numOperationsCompleted++;
      } catch (err) {
        // Handle error
      }
      await semaphore.release();
    }
  }

  parallelReduce().then(() => {
    console.log(`Accumulated value: ${accumulator}, Number of completed operations: ${numOperationsCompleted}`);
  });
}

class AsyncSemaphore {
  constructor(limit = 1) {
    this.limit = limit;
    this.queue = [];
    this.signal = new Promise(resolve => (this.resolve = resolve));
  }

  take() {
    return new Promise((resolve, reject) => {
      if (this.queue.length < this.limit) {
        resolve();
      } else {
        this.queue.push({ resolve, reject });
      }
      this.signal.then(() => this.processQueue()).then(resolve).catch(reject);
    });
  }

  release() {
    this.resolve();
    this.signal = new Promise((resolve, reject) => (this.resolve = resolve));
  }

  processQueue() {
    while (this.queue.length > 0) {
      const { resolve } = this.queue.shift();
      resolve();
    }
    this.signal = new Promise(resolve => (this.resolve = resolve));
  }
}
