    console.log(`Running tests for ${moduleLabel} - Suite: ${testSuite.name}`);

    parallel(
      testSuite.testCases.map((testCase) => {
        return (callback) => {
          try {
            const module = loadModule(moduleLabel);
            blueslipMocker.reset();

            // Run the test case
            testCase(module, config.loggingLevel);

            console.log(`Test: ${testCase.name} - Passed`);
          } catch (error) {
            console.error(`Test: ${testCase.name} - Failed with error: ${error}`);
          } finally {
            blueslipMocker.reset();
          }

        };
      }),
      { concurrency, timeout },
      (err) => {
        if (err) {
          console.error(err);
        }
        callback();
      }
    );
  });
}

module.exports = runTests;
