  try {
    await paymentProcessor.authenticateUser(req.query.redirectUri);
    const transactionData = await paymentProcessor.verifyTransaction(req.query.transactionId);

    // Process the transaction
    await paymentProcessor.processPayment(transactionData.orderId, transactionData.customerDetails, transactionData.paymentStatus);

    res.send('Transaction processed successfully!');
  } catch (error) {
    Logger.error('Error processing payment:', error);
    res.status(500).send('Internal Server Error');
  }
});

app.listen(3000, () => {
