import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SocketChannel;

public class RemoteConnection {
    public void establishConnection(String remoteAddress) throws IOException {
        SocketChannel channel = SocketChannel.open();
        channel.connect(new InetSocketAddress(remoteAddress));

        // Handle connection state changes
        channel.configureBlocking(true);
        while (channel.isConnected()) {
            if (channel.isConnectionPending()) {
                System.out.println("Connecting...");
                channel.finishConnect();
            } else if (channel.isConnectionFailed()) {
                System.out.println("Connection failed.");
            }
            try {
                Thread.sleep(1000); // Handle connection state changes
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }
}
