**C Function**
```c
#include <json-c/json.h>
#include <stdio.h>

bool validateOAuth2TokenResponse(const char *tokenJson) {
    json_object *token = json_object_from_string(tokenJson);
    if (!token) return false; // JSON object creation failed

    if (json_object_get_type(token, "access_token") != json_type_string) return false;
    if (json_object_get_type(token, "expires_in") != json_type_integer) return false;
    if (json_object_get_type(token, "token_type") != json_type_string) return false;

    const char *accessToken = json_object_get_string(token, "access_token");
    int expiresIn = json_object_get_int(token, "expires_in");
    const char *tokenType = json_object_get_string(token, "token_type");

    if (!accessToken || !expiresIn || !tokenType) return false; // Required fields missing

    if (strcmp(tokenType, "Bearer") != 0) return false;
    if (expiresIn <= 0) return false;

    json_object *refreshToken = json_object_get_object(token, "refresh_token");
    if (refreshToken) {
        const char *refreshTokenType = json_object_get_string(refreshToken, "token_type");
        int refreshTokenExpiresIn = json_object_get_int(refreshToken, "expires_in");

        if (strcmp(refreshTokenType, "Bearer") != 0 || refreshTokenExpiresIn <= 0) return false;
    }

    json_object_put(token); // Release JSON object
    return true; // Token is valid
}
```

