```rust
// http_client.rs
use reqwest;
use serde_json::json;

pub async fn make_request(url: &str) -> Result<String, Box<dyn std::error::Error>> {
    let client = reqwest::Client::new();
    let response = client.get(url).send().await?;

    match response.status() {
        200 => Ok(response.text().await?),
        _ => Err(From::new(format!("Request failed with status code {}", response.status()))),
    }
}

pub async fn make_request_with_cert_validation(
    url: &str,
    cert_file: &str,
) -> Result<String, Box<dyn std::error::Error>> {
    let client = reqwest::Client::builder()
        .danger_accept_invalid_certs(false)
        .cert(cert_file);

    let response = client.get(url).send().await?;

    match response.status() {
        200 => Ok(response.text().await?),
        _ => Err(From::new(format!("Request failed with status code {}", response.status()))),
    }
}

pub async fn make_request_with_retries(
    url: &str,
    max_retries: u32,
) -> Result<String, Box<dyn std::error::Error>> {
    let client = reqwest::Client::new();
    let mut retries = 0;
    loop {
        match client.get(url).send().await {
            Ok(response) => {
                if response.status() == 200 {
                    return Ok(response.text().await?);
                }
                retries += 1;
                if retries >= max_retries {
                    return Err(From::new(format!("Request failed after {} retries", retries)));
                }
            },
            Err(_) => {
                retries += 1;
                if retries >= max_retries {
                    return Err(From::new(format!("Request failed after {} retries", retries)));
                }
            }
        }
    }
}
