```c
#include <semaphore.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>

#define SEM_NAME "my_semaphore"
#define LOG_FILE "semaphore_log.txt"

typedef struct {
    sem_t *sem;
    int initialized;
} Semaphore;

Semaphore* create_semaphore(int value) {
    Semaphore* semaphore = (Semaphore*)malloc(sizeof(Semaphore));
    if (!semaphore) {
        return NULL;
    }

    semaphore->sem = sem_open(SEM_NAME, O_CREAT | O_EXCL | O_RDWR, S_IRUSR | S_IWUSR, value);
    if (semaphore->sem == SEM_FAILED) {
        free(semaphore);
        return NULL;
    }

    semaphore->initialized = 1;
    return semaphore;
}

int increment_semaphore(Semaphore* semaphore, int value) {
    if (!semaphore || !semaphore->initialized) {
        return -1; // invalid or uninitialized semaphore
    }

    sem_wait(semaphore->sem);
    int result = sem_getvalue(semaphore->sem) + value;
    sem_post(semaphore->sem);

    return result;
}

int decrement_semaphore(Semaphore* semaphore, int value) {
    if (!semaphore || !semaphore->initialized) {
        return -1; // invalid or uninitialized semaphore
    }

    sem_wait(semaphore->sem);
    int result = sem_getvalue(semaphore->sem) - value;
    sem_post(semaphore->sem);

    return result;
}

int delete_semaphore(Semaphore* semaphore) {
    if (!semaphore || !semaphore->initialized) {
        return -1; // invalid or uninitialized semaphore
    }

    int result = sem_close(semaphore->sem);
    if (result == 0) {
        free(semaphore);
    }

    return result;
}

void log_semaphore_operation(Semaphore* semaphore, int value, char* operation) {
    FILE* file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s semaphore with value %d.\n", operation, value);
        fclose(file);
    }
}

int main() {
    Semaphore* semaphore = create_semaphore(5);

    if (semaphore) {
        int result1 = increment_semaphore(semaphore, 2);
        log_semaphore_operation(semaphore, result1, "incremented");

        int result2 = decrement_semaphore(semaphore, 1);
        log_semaphore_operation(semaphore, result2, "decremented");

        delete_semaphore(semaphore);
    }

    return 0;
}
