import hashlib
import hmac
from collections import OrderedDict

class CryptoManager:
    def __init__(self, config_file_path):
        self.config = self.load_config(config_file_path)
        self.cryptographic_functions = {}
        self.cipher_instances = {}

    def load_config(self, config_file_path):
        try:
            with open(config_file_path, "r") as f:
                return [line.strip() for line in f.readlines()]
        except FileNotFoundError:
            return []

    def get_cryptographic_function(self, name):
        if name not in self.cryptographic_functions:
            self.cryptographic_functions[name] = getattr(hashlib, name)
        return self.cryptographic_functions[name]

    def get_cipher_instance(self, name):
        if name not in self.cipher_instances:
            self.cipher_instances[name] = hmac.new(key=b"secret_key", digestmod=name)
        return self.cipher_instances[name]

    def sort_cryptographic_functions(self):
        sorted_config = sorted(self.config, key=lambda x: x.lower())
        return [self.get_cryptographic_function(name) for name in sorted_config]

    def get_sequence_number(self):
        try:
            last_entry = self.config[-1]
            sequence_number = int(re.match(r"(\d+)", last_entry).group(1))
            return sequence_number
        except (AttributeError, IndexError):
            return None

# Example usage
crypto_manager = CryptoManager("path/to/config/file.txt")
sorted_functions = crypto_manager.sort_cryptographic_functions()
sequence_number = crypto_manager.get_sequence_number()

# For concurrent operations and memory management:
import concurrent.futures
with concurrent.futures.ThreadPoolExecutor() as executor:
    futures = [executor.submit(crypto_manager.get_cipher_instance, name) for name in self.config]
    results = [future.result() for future in futures]

