using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public abstract class SecureDataProcessor
{
    public static readonly SecureDataProcessor Instance = new SecureDataProcessor();

    protected abstract Task<string> GenerateHashAsync(string input);
    protected abstract Task<byte[]> GenerateHashBytesAsync(byte[] input);

    public async Task<string> GenerateMd5Async(string input)
    {
        return await GenerateHashAsync(input);
    }

    public async Task<string> GenerateSha1Async(string input)
    {
        return await GenerateHashAsync(input);
    }

    public async Task<string> GenerateSha256Async(string input)
    {
        return await GenerateHashAsync(input);
    }

    public async Task<byte[]> GenerateMd5BytesAsync(byte[] input)
    {
        return await GenerateHashBytesAsync(input);
    }

    public async Task<byte[]> GenerateSha1BytesAsync(byte[] input)
    {
        return await GenerateHashBytesAsync(input);
    }

    public async Task<byte[]> GenerateSha256BytesAsync(byte[] input)
    {
        return await GenerateHashBytesAsync(input);
    }
}

public class Md5SecureDataProcessor : SecureDataProcessor
{
    protected override async Task<string> GenerateHashAsync(string input)
    {
        using (var md5 = MD5.Create())
        {
            var hashBytes = Encoding.UTF8.GetBytes(input);
            var hash = await CalculateHashAsync(md5, hashBytes);
            return Convert.ToHexString(hash);
        }
    }

    protected override async Task<byte[]> GenerateHashBytesAsync(byte[] input)
    {
        using (var md5 = MD5.Create())
        {
            var hash = await CalculateHashAsync(md5, input);
            return hash;
        }
    }
}

public class Sha1SecureDataProcessor : SecureDataProcessor
{
    protected override async Task<string> GenerateHashAsync(string input)
    {
        using (var sha1 = SHA1.Create())
        {
            var hashBytes = Encoding.UTF8.GetBytes(input);
            var hash = await CalculateHashAsync(sha1, hashBytes);
            return Convert.ToHexString(hash);
        }
    }

    protected override async Task<byte[]> GenerateHashBytesAsync(byte[] input)
    {
        using (var sha1 = SHA1.Create())
        {
            var hash = await CalculateHashAsync(sha1, input);
            return hash;
        }
    }
}

public class Sha256SecureDataProcessor : SecureDataProcessor
{
    protected override async Task<string> GenerateHashAsync(string input)
    {
        using (var sha256 = SHA256.Create())
        {
            var hashBytes = Encoding.UTF8.GetBytes(input);
            var hash = await CalculateHashAsync(sha256, hashBytes);
            return Convert.ToHexString(hash);
        }
    }

    protected override async Task<byte[]> GenerateHashBytesAsync(byte[] input)
    {
        using (var sha256 = SHA256.Create())
        {
            var hash = await CalculateHashAsync(sha256, input);
            return hash;
        }
    }
}

public static class SecureDataProcessorExtensions
{
    public static async Task<string> CalculateHashAsync(this HashAlgorithm algorithm, byte[] input)
    {
        using (var stream = new MemoryStream(input))
        {
            var hashBytes = await CalculateHashAsync(algorithm, stream);
            return Convert.ToHexString(hashBytes);
        }
    }

    public static async Task<byte[]> CalculateHashAsync(this HashAlgorithm algorithm, Stream stream)
    {
        var hashBytes = new byte[algorithm.HashSize / 8];
        using (var hashStream = algorithm.Createdigest())
        {
            await new CryptoStream(stream, hashStream, CryptoStreamMode.Read).CopyToAsync(hashStream);
            return hashBytes;
        }
    }
}
