```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

// Define a struct to hold semaphore information
typedef struct {
    sem_t* semaphore;
    char name[20];
} SemaphoreInfo;

// Function to create a semaphore with initial value from command-line argument
void* create_semaphore(void* arg) {
    int initial_value = atoi((char*)arg);
    SemaphoreInfo* info = (SemaphoreInfo*)malloc(sizeof(SemaphoreInfo));

    // Initialize semaphore name and create the semaphore
    sprintf(info->name, "semaphore_%d", getpid());
    if(sem_open(info->name, O_CREAT | O_EXCL, 0644, initial_value) == -1) {
        perror("sem_open");
        exit(1);
    }

    // Set the semaphore info structure and return
    info->semaphore = (sem_t*)sem_open(info->name, O_RDWR);
    free(arg);
    return info;
}

// Function to delete a semaphore
void* delete_semaphore(void* arg) {
    SemaphoreInfo* info = (SemaphoreInfo*)arg;

    // Close the semaphore and remove it
    if(sem_close(info->semaphore) == -1) {
        perror("sem_close");
        exit(1);
    }
    sem_unlink(info->name);
    free(arg);
}

// Function to manage semaphore operations (create, delete)
void* semaphore_manager(void* arg) {
    while(1) {
        // Wait for semaphore operation request
        pthread_mutex_lock(NULL);  // Assume a global mutex here

        // Handle create or delete operation based on received command
        if(strcmp((char*)arg, "create") == 0) {
            SemaphoreInfo* info = (SemaphoreInfo*)malloc(sizeof(SemaphoreInfo));
            char initial_value_str[10];
            fgets(initial_value_str, sizeof(initial_value_str), stdin);
            int initial_value = atoi(initial_value_str);

            // Create the semaphore
            pthread_t thread;
            if(pthread_create(&thread, NULL, create_semaphore, (void*)initial_value_str) != 0) {
                perror("pthread_create");
                exit(1);
            }
            pthread_join(thread, NULL);
        } else if(strcmp((char*)arg, "delete") == 0) {
            // Get the semaphore name from user input
            char semaphore_name[20];
            fgets(semaphore_name, sizeof(semaphore_name), stdin);

            // Delete the semaphore
            SemaphoreInfo* info = (SemaphoreInfo*)malloc(sizeof(SemaphoreInfo));
            strcpy(info->name, semaphore_name);
            pthread_t thread;
            if(pthread_create(&thread, NULL, delete_semaphore, (void*)info) != 0) {
                perror("pthread_create");
                exit(1);
            }
            pthread_join(thread, NULL);
        } else {
            printf("Invalid command. Please enter 'create' or 'delete'.\n");
        }

        // Release the global mutex
        pthread_mutex_unlock(NULL);
    }
}

int main() {
    // Initialize logging and user interface
    // ...

    // Create a thread to manage semaphore operations
    pthread_t manager_thread;
    if(pthread_create(&manager_thread, NULL, semaphore_manager, (void*)"") != 0) {
        perror("pthread_create");
        exit(1);
    }

    // Wait for the manager thread to finish
    pthread_join(manager_thread, NULL);

    return 0;
}
