    return /([A-Z][a-z]+ [A-Z][a-z]+ (Testament)?)/;
  }

  constructor(text) {
    if (!text || typeof text !== 'string') {
      throw new Error('Invalid input: expected a non-empty string');
    }
    this.text = text.toLowerCase();
  }

  getBookNames() {
    const results = [];
    for (const book of [...this.OLD_TESTAMENT_BOOKS, ...this.NEW_TESTAMENT_BOOKS]) {
      if (!book.includes("Testament")) {
        const regex = new RegExp(`(${book.replace(" ", " ")})`, 'i');
        const matches = this.text.match(regex);
        if (matches) {
          results.push(...matches.map((match) => match.trim()));
        }
      }
    }
