```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class EncryptionService
{
    private readonly string _key;
    private readonly string _iv;

    public EncryptionService(string key, string iv)
    {
        _key = key;
        _iv = iv;
    }

    public async Task<string> DecryptAndValidateAsync(string base64EncodedMessage)
    {
        try
        {
            // Convert Base64-encoded message to bytes
            var encryptedBytes = Convert.FromBase64String(base64EncodedMessage);

            // Triple DES decryption
            using (var tripleDes = TripleDES.Create())
            {
                tripleDes.Key = Encoding.ASCII.GetBytes(_key);
                tripleDes.IV = Encoding.ASCII.GetBytes(_iv);
                var decryptedBytes = Decrypt(encryptedBytes, tripleDes);

                // HMAC SHA256 validation
                var hmacSha256 = new HMACSHA256(Encoding.ASCII.GetBytes(_key));
                using (var ms = new MemoryStream(decryptedBytes))
                {
                    var hash = hmacSha256.ComputeHash(ms);
                    if (!CompareHashes(hash, decryptedBytes))
                    {
                        throw new AuthenticationException("Decrypted message failed authentication");
                    }
                }

                return Encoding.UTF8.GetString(decryptedBytes);
            }
        }
        catch (FormatException ex) when (ex.Message.Contains("invalid Base64"))
        {
            throw new Exception("Invalid Base64 encoding in the message", ex);
        }
        catch (CryptographicException ex)
        {
            throw new Exception("Decryption failed: " + ex.Message, ex);
        }
    }

    private static byte[] Decrypt(byte[] data, TripleDES tripleDes)
    {
        using (var ms = new MemoryStream())
        {
            using (var cs = new CryptoStream(ms, tripleDes.CreateDecryptor(), CryptoStreamMode.Write))
            {
                cs.Write(data, 0, data.Length);
                cs.FlushFinalBlock();
                return ms.ToArray();
            }
        }
    }

    private static bool CompareHashes(byte[] hash, byte[] data)
    {
        using (var hmacSha256 = new HMACSHA256(Encoding.ASCII.GetBytes(_key)))
        {
            var computedHash = hmacSha256.ComputeHash(data);
            return BitConverter.ToString(hash).Equals(BitConverter.ToString(computedHash));
        }
    }
}

public class AuthenticationException : Exception
{
    public AuthenticationException(string message) : base(message)
    {
    }
}
