```javascript
const { readdir, stat, readFileSync } = require('fs');
const { join } = require('path');
const { promisify } = require('util');
const { logger } = require('./logger');

class ReadDirectoryFiles {
  constructor(directory, extensions = ['txt'], buffer_size = 1024 * 1024, max_concurrency = 10, max_retries = 3) {
    this.directory = directory;
    this.extensions = extensions;
    this.buffer_size = buffer_size;
    this.max_concurrency = max_concurrency;
    this.max_retries = max_retries;
    this.cache = {};
  }

  async readFiles(recursive = false) {
    const files = await this.readdir(this.directory, recursive);
    return Promise.all(files.map(file => this.readFile(file)));
  }

  async readFile(file) {
    try {
      if (this.shouldExcludeFile(file)) return null;

      const filePath = join(this.directory, file);
      const stats = await promisify(stat)(filePath);

      if (!stats.isFile()) return null;

      let content;
      for (let i = 0; i < this.max_retries; i++) {
        try {
          content = readFileSync(filePath, 'utf8', { highWaterMark: this.buffer_size });
          break;
        } catch (error) {
          if (i === this.max_retries - 1) throw error;

          // Backoff before retrying
          await new Promise(resolve => setTimeout(() => resolve(), Math.pow(2, i)));
        }
      }

      logger.info(`Read file: ${file} | Size: ${stats.size}`);
      return content;
    } catch (error) {
      logger.error(`Error reading file: ${file}`, error);
    }
  }

  shouldExcludeFile(file) {
    const stats = statSync(join(this.directory, file));
    if (!stats.isFile()) return true;

    if (stats.size > 1024 * 1024) return true; // File size exceeds threshold
    return false;
  }

  async readdir(directory, recursive = false) {
    const files = await promisify(readdir)(directory);

    if (!recursive) return files.filter(file => !file.startsWith('.'));

    const subdirectories = await Promise.all(files.map(async file => {
      const filePath = join(directory, file);
      const stats = statSync(filePath);

      if (!stats.isDirectory()) return [filePath];

      return this.readdir(filePath, true).then(subfiles => subfiles.map(subfile => join(filePath, subfile)));
    }));

    return files.concat(...subdirectories.flat());
  }
}

module.exports = ReadDirectoryFiles;
