    public static PacketProcessingResult filterAndProcessNetworkPackets(String clientId, String clientSecret, int packetSizeThreshold, String sourceIp, int destinationPort) throws IOException {
        // Authenticate the user using OAuth 2.0 client credentials
        if (accessToken == null || accessToken.isEmpty()) {
