        }

        // Initialize metrics
        int filteredPackets = 0;
        int totalPackets = 0;
        double averagePacketSize = 0;

        PacketProcessingResult result = new PacketProcessingResult();

        // Process and filter packets
        for (NetworkPacket packet : getNetworkPackets()) {
            if (packet.getSize() >= packetSizeThreshold && packet.getSourceIp().equals(sourceIp) && packet.getDestinationPort() == destinationPort) {
                slidingWindow.add(packet);
                totalPackets++;
                averagePacketSize += packet.getSize();
            } else {
                filteredPackets++;
            }

            // Check for network latency issues and ensure processing doesn't introduce significant delays
            if (slidingWindow.size() > 1000) { // adjust this value based on your specific requirements
                slidingWindow.remove(0);
            }
        }

        // Update metrics
        averagePacketSize /= totalPackets;

        // Combine private key and certificate from filtered packets into a single PEM file
        String pemFile = combinePrivateKeysAndCertificates(slidingWindow);

        // Encode the PEM file in base64
        String encodedPemFile = Base64.getEncoder().encodeToString(pemFile.getBytes());

        result.setMaxPacketSize(getMaxPacketSize(slidingWindow));
        result.setPacketId(getPacketId(slidingWindow));

        return result;
    }

