import java.util.ArrayList;
import java.util.List;

public class PokemonWeaknessService {

    private static final String DEFAULT_WEAKNESS = "Unknown";

    public interface PokemonApi {
        List<PokemonType> getPokemonsTypes(String pokemonId);
    }

    public interface DatabaseConnector {
        PokemonWeakness getWeakness(String pokemonId);
    }

    private PokemonApi pokemonApi;
    private DatabaseConnector databaseConnector;

    public PokemonWeaknessService(PokemonApi pokemonApi, DatabaseConnector databaseConnector) {
        this.pokemonApi = pokemonApi;
        this.databaseConnector = databaseConnector;
    }

    public String getPokemonWeakness(Pokemon pokemon) {
        List<String> weaknesses = new ArrayList<>();
        for (PokemonType type : getTypes(pokemon)) {
            switch (type.getType()) {
                case "fire":
                    weaknesses.add(getWeakness("Fire"));
                    break;
                case "water":
                    weaknesses.add(getWeakness("Water"));
                    break;
                // Add more types as needed
                default:
                    weaknesses.add(DEFAULT_WEAKNESS);
            }
        }
        return String.join(", ", weaknesses);
    }

    private List<PokemonType> getTypes(Pokemon pokemon) {
        try {
            return pokemonApi.getPokemonsTypes(pokemon.getId());
        } catch (Exception e) {
            // fallback to default types
            return Arrays.asList(new PokemonType("Unknown"), new PokemonType("Unknown"));
        }
    }

    private String getWeakness(String type) {
        try {
            return databaseConnector.getWeakness(type).getStrength();
        } catch (Exception e) {
            // fallback to default weakness data
            return DEFAULT_WEAKNESS;
        }
    }
}

public class PokemonType {
    private String type;

    public PokemonType(String type) {
        this.type = type;
    }

    public String getType() {
        return type;
    }
}

public class PokemonWeakness {
    private String strength;

    public PokemonWeakness(String strength) {
        this.strength = strength;
    }

    public String getStrength() {
        return strength;
    }
