use reqwest::blocking::{get, put};
use tokio::sync::mpsc;
use std::collections::{HashMap, HashSet};
use serde_json::Value;

struct WeatherAPI {
    base_url: String,
}

impl WeatherAPI {
    fn new(base_url: &str) -> Self {
        WeatherAPI { base_url: base_url.to_string() }
    }

    async fn get_weather(&self, city: &str) -> Result<Value, reqwest::Error> {
        let url = format!("{}/weather?q={}&units=metric", self.base_url, city);
        get(&url).send().await?
    }

    async fn get_forecast(&self, city: &str) -> Result<Value, reqwest::Error> {
        let url = format!("{}/forecast/daily?q={}&units=metric&cnt=24", self.base_url, city);
        get(&url).send().await?
    }
}

async fn fetch_weather(city: &str, weather_api: &WeatherAPI) -> Result<Value, reqwest::Error> {
    loop {
        match weather_api.get_weather(city).await {
            Ok(data) => return Ok(data),
            Err(err) => if err.is_rate_limit_exceeded() {
                println!("Rate limit exceeded. Waiting for 1 minute...");
                tokio::time::sleep(std::time::Duration::from_millis(60 * 1000)).await;
            } else {
                return Err(err);
            },
        }
    }
}

async fn fetch_forecast(city: &str, weather_api: &WeatherAPI) -> Result<Value, reqwest::Error> {
    loop {
        match weather_api.get_forecast(city).await {
            Ok(data) => return Ok(data),
            Err(err) => if err.is_rate_limit_exceeded() {
                println!("Rate limit exceeded. Waiting for 1 minute...");
                tokio::time::sleep(std::time::Duration::from_millis(60 * 1000)).await;
            } else {
                return Err(err);
            },
        }
    }
}

async fn main(city: &str, weather_api_url: &str) -> Result<(), reqwest::Error> {
    let mut weather_api = WeatherAPI::new(weather_api_url);

    // Fetch current weather
    let current_weather = fetch_weather(city, &weather_api).await?;

    // Fetch forecast
    let forecast = fetch_forecast(city, &weather_api).await?;

    println!("Current weather: {}", current_weather);
    println!("Forecast: {}", forecast);

    Ok(())
}

#[tokio::main]
async fn run() -> Result<(), reqwest::Error> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: cargo run <city> <weather_api_url>");
        return Ok(());
    }

    let city = &args[1];
    let weather_api_url = &args[2];

    main(city, weather_api_url).await
}
