function runTests(moduleLabel, testSuites, config, loggingLevel) {
  const { concurrencyLimit, timeoutLimit, resourceLimits } = config;
  const logger = require('logger')(loggingLevel);

  async function executeTestSuite(suite) {
    try {
      await Promise.all(
        suite.map((test) => {
          if (test.async) {
            return new Promise((resolve) => setTimeout(() => resolve(test.fn()), test.delay));
          }
          return test.fn();
        })
      );
    } catch (error) {
      logger.error(`Test ${suite.name} failed: ${error}`);
    }
  }

  async function runTestsConcurrently(testSuites, concurrencyLimit) {
    const chunkedSuites = [];
    for (let i = 0; i < testSuites.length; i += concurrencyLimit) {
      chunkedSuites.push(testSuites.slice(i, i + concurrencyLimit));
    }

    await Promise.all(
      chunkedSuites.map((suite) => executeTestSuite(suite))
    );
  }

  async function runTestsSequentially(testSuites) {
    for (const suite of testSuites) {
      await executeTestSuite(suite);
    }
  }

  async function retryFailedTests(testSuites, retryCount, delay) {
    let attempts = 0;
    do {
      await runTestsConcurrently(testSuites, concurrencyLimit);
      if (!testSuites.some((suite) => suite.some((test) => test.failed))) break;
      await new Promise((resolve) => setTimeout(() => resolve(), delay));
      attempts++;
    } while (attempts < retryCount);
  }

  try {
    logger.info(`Running tests for module ${moduleLabel}`);

    if (config.concurrent) {
      await runTestsConcurrently(testSuites, concurrencyLimit);
    } else {
      await runTestsSequentially(testSuites);
    }
  } catch (error) {
    logger.error('Error running tests:', error);
  } finally {
    logger.info(`Tests for module ${moduleLabel} completed`);
  }
}
