#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sqlite3.h>

typedef struct {
    long offset;
    int key;
    long timestamp;
} Record;

void* allocate_array(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    return ptr;
}

int generate_records(Record** records, int num_records, sqlite3* db) {
    srand(time(NULL));

    // Generate random values for offset and key arrays
    long* offsets = (long*) allocate_array(num_records * sizeof(long));
    int* keys = (int*) allocate_array(num_records * sizeof(int));

    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % 1000000;
        keys[i] = rand() % 1000;
    }

    // Generate record structures with random timestamps
    Record* record_ptr = allocate_array(num_records * sizeof(Record));
    for (int i = 0; i < num_records; i++) {
        record_ptr[i].offset = offsets[i];
        record_ptr[i].key = keys[i];
        record_ptr[i].timestamp = time(NULL) + rand() % 10000;
    }

    // Integrate with database system
    sqlite3_stmt* stmt;
    const char* query = "INSERT INTO records (offset, key, timestamp) VALUES (?, ?, ?)";
    int rc = sqlite3_prepare_v2(db, query, strlen(query), &stmt, NULL);
    if (rc != SQLITE_OK) {
        printf("Error preparing statement: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    for (int i = 0; i < num_records; i++) {
        rc = sqlite3_bind_int(stmt, 1, record_ptr[i].offset);
        if (rc != SQLITE_OK) {
            printf("Error binding parameter: %s\n", sqlite3_errmsg(db));
            return -1;
        }
        rc = sqlite3_bind_int(stmt, 2, record_ptr[i].key);
        if (rc != SQLITE_OK) {
            printf("Error binding parameter: %s\n", sqlite3_errmsg(db));
            return -1;
        }
        rc = sqlite3_bind_int(stmt, 3, record_ptr[i].timestamp);
        if (rc != SQLITE_OK) {
            printf("Error binding parameter: %s\n", sqlite3_errmsg(db));
            return -1;
        }
        rc = sqlite3_step(stmt);
        if (rc != SQLITE_DONE) {
            printf("Error executing statement: %s\n", sqlite3_errmsg(db));
            return -1;
        }
    }

    // Periodically flush records to the database
    int batch_size = 100;
    for (int i = 0; i < num_records; i += batch_size) {
        int end_index = i + batch_size > num_records ? num_records : i + batch_size;
        for (int j = i; j < end_index; j++) {
            record_ptr[j].timestamp = time(NULL);
        }
        rc = sqlite3_exec(db, query, NULL, NULL, NULL);
        if (rc != SQLITE_OK) {
            printf("Error executing statement: %s\n", sqlite3_errmsg(db));
            return -1;
        }
    }

    // Free memory and resources
    free(offsets);
    free(keys);
    free(record_ptr);

    return 0;
}

int main() {
    sqlite3* db;
    int rc = sqlite3_open("records.db", &db);
    if (rc != SQLITE_OK) {
        printf("Error opening database: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    Record** records = allocate_array(100 * sizeof(Record*));
    for (int i = 0; i < 100; i++) {
        records[i] = generate_records(records + i, 100, db);
    }

    sqlite3_close(db);

    return 0;
}
