import subprocess

def modify_config_file(config_dict, file_path):
    try:
        with open(file_path, 'r') as f:
            config = f.read()

        for key, value in config_dict.items():
            config = config.replace(f'{{{{{key}}}}}', str(value))

        with open('modified_' + file_path, 'w') as f:
            f.write(config)
