import subprocess

def generate_llvm_ir(file_path):
    try:
        process = subprocess.run(['llc', '-o', 'generated.ll', file_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if process.returncode != 0:
            raise Exception(f"LLVM IR generation failed with code {process.returncode}")

        print("Parsed nodes:")
        for line in process.stdout.decode('utf-8').splitlines():
            print(line)

        print("\nGenerated LLVM IR code:")
        with open('generated.ll', 'r') as f:
            print(f.read())
    except subprocess.CalledProcessError:
        raise Exception("LLVM IR generation failed")
