import javax.xml.bind.DatatypeConverter;
import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.*;

public class Md5Hasher {

    private static final int DEFAULT_CACHE_SIZE = 1000;
    private static final int DEFAULT_MAX_THREADS = 5;
    private static final int MAX_FILE_LENGTH = 1000;

    private final ExecutorService threadPool;
    private final LRU Cache cache;

    public Md5Hasher(int maxThreads, int cacheSize) {
        this.threadPool = Executors.newFixedThreadPool(maxThreads);
        this.cache = new LRUCache(cacheSize);
    }

    public Md5Hasher() {
        this(DEFAULT_MAX_THREADS, DEFAULT_CACHE_SIZE);
    }

    public String computeMd5(String filePath) throws Exception {

        if (filePath == null || filePath.length() > MAX_FILE_LENGTH) {
            throw new InvalidInputException("Invalid file path");
        }

        try {
            Path path = Paths.get(filePath);

            if (!Files.exists(path)) {
                return null;
            }

            File file = path.toFile();

            Md5HashRequest request = new Md5HashRequest(file);
            CompletableFuture<String> future = new CompletableFuture<>();

            threadPool.submit(() -> {
                try {
                    MessageDigest md = MessageDigest.getInstance("MD5");
                    DigestInputStream dis = new DigestInputStream(new FileInputStream(file), md);

                    byte[] buffer = new byte[4096];
                    int bytesRead;

                    while ((bytesRead = dis.read(buffer)) != -1) {
                        dis.update(buffer, 0, bytesRead);
                    }

                    String hash = DatatypeConverter.printHexBinary(md.digest()).toUpperCase();
                    future.complete(hash);
                } catch (Exception e) {
                    log.error("Error computing MD5 hash for file " + filePath, e);
                    future.completeExceptionally(e);
                }
            });

            return future.get(10000, TimeUnit.MILLISECONDS); // timeout after 10 seconds
        } finally {
            threadPool.shutdown();
        }
    }

    private void log(Object obj) {
        // implement logging mechanism using SLF4J or another logging system
    }
}
