import time
from typing import Dict

class PaymentGatewayAPI:
    def __init__(self):
        self.api_key = "YOUR_API_KEY"
        self.api_secret = "YOUR_API_SECRET"
        self.rate_limit = 100  # requests per minute
        self.retry_count = 0
        self.max_retries = 3

    def make_request(self, method: str, url: str, data: Dict) -> Dict:
        if self.retry_count > self.max_retries:
            print(f"Failed to process transaction after {self.max_retries} retries. Giving up.")
            return {}

        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json"
        }
        response = requests.request(method, url, json=data, headers=headers)

        if 200 <= response.status_code < 300:
            self.retry_count = 0
            return response.json()
        elif response.status_code == 429:  # rate limit exceeded
            time.sleep(60)  # wait for a minute before retrying
            self.retry_count += 1
            return self.make_request(method, url, data)
        else:
            if response.status_code >= 500:  # server error
                self.retry_count = 0
                print(f"Server error {response.status_code}. Retrying...")
                return self.make_request(method, url, data)
            elif response.status_code == 404:  # not found
                print("Transaction not found. Giving up.")
                return {}
            else:
                print(f"Error processing transaction: {response.text}")
                return {}

    def process_transaction(self, transaction_data: Dict) -> str:
        try:
            response = self.make_request("POST", "https://payment-gateway-api.com/transactions", transaction_data)
            if not response.get("transaction_token"):
                raise Exception("Invalid or missing transaction token")
            return response["transaction_token"]
        except Exception as e:
            logging.error(f"Error processing transaction: {str(e)}")
            time.sleep(1)  # wait for a second before retrying
            self.retry_count += 1
            if self.retry_count <= self.max_retries:
                return self.process_transaction(transaction_data)
            else:
                raise

    def validate_response(self, response: Dict) -> None:
        if not response.get("status"):
            print(f"Invalid or missing transaction status: {response}")
