import java.util.ArrayList;
import java.util.List;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.SQLException;

public class PacketProcessor {
    private static final int SLIDING_WINDOW_SIZE = 1000; // adjust as needed
    private Connection conn;
    private PreparedStatement ps;
    private List<Packet> packetQueue = new ArrayList<>();
    private int filteredPackets = 0;
    private int totalPackets = 0;
    private double averagePacketSize = 0.0;

    public PacketProcessor() {
        try {
            // initialize database connection
            conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/packet_analysis", "username", "password");
            ps = conn.prepareStatement("INSERT INTO packets (packet_size, source_ip, dest_port, arrival_time, payload) VALUES (?, ?, ?, ?, ?)");
        } catch (SQLException e) {
            System.out.println("Error initializing database connection: " + e.getMessage());
        }
    }

    public void processPacket(Packet packet) {
        // maintain a sliding window of the most recent packets
        packetQueue.add(packet);
        if (packetQueue.size() > SLIDING_WINDOW_SIZE) {
            packetQueue.remove(0); // remove oldest packet
        }

        // filter packets based on criteria
        if (!filterBySize(packet.getPacketSize()) || 
            !filterBySourceIP(packet.getSourceIP()) || 
            !filterByDestPort(packet.getDestPort(), packet.getArrivalTime()) || 
            !filterByPayload(packet.getPayload())) {
            filteredPackets++;
            System.out.println("Filtered out packet due to: " + getFilterReason());
        } else {
            // process and store valid packets in the database
            try {
                ps.setInt(1, packet.getPacketSize());
                ps.setString(2, packet.getSourceIP());
                ps.setInt(3, packet.getDestPort());
                ps.setTimestamp(4, packet.getArrivalTime());
                ps.setString(5, packet.getPayload());
                ps.execute();
                totalPackets++;
                averagePacketSize = (totalPackets > 0) ? ((double)packet.getPacketSize() + averagePacketSize * (totalPackets - 1)) / totalPackets : 0.0;
            } catch (SQLException e) {
                System.out.println("Error storing packet in database: " + e.getMessage());
            }
        }

        // update metrics
        System.out.println("Filtered packets: " + filteredPackets);
        System.out.println("Total packets: " + totalPackets);
        System.out.println("Average packet size: " + averagePacketSize);
    }

    private boolean filterBySize(int packetSize) {
        // implement custom filtering logic for packet size
        return true; // default to allowing all packets of this size
    }

    private boolean filterBySourceIP(String sourceIP) {
        // implement custom filtering logic for source IP address
        return true; // default to allowing all packets from this IP
    }

    private boolean filterByDestPort(int destPort, long arrivalTime) {
        // implement custom filtering logic for destination port and packet arrival time
