import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerConfig;
import org.apache.kafka.clients.producer.ProducerRecord;
import java.util.HashMap;
import java.util.Map;

public class ChatMessageProcessor {
    private KafkaProducer<String, String> producer;
    private Map<String, Long> userThrottleMap;
    private Map<String, Long> roomThrottleMap;

    public ChatMessageProcessor() {
        producer = new KafkaProducer<>();
        producer.config(ProducerConfig.BOOTSTRAP_SERVERS, "localhost:9092");
        producer.config(ProducerConfig.KEY_SERIALIZER, "org.apache.kafka.common.serialization.StringSerializer");
        producer.config(ProducerConfig.VALUE_SERIALIZER, "org.apache.kafka.common.serialization.StringSerializer");

        userThrottleMap = new HashMap<>();
        roomThrottleMap = new HashMap<>();
    }

    public String processMessage(String userId, String roomId, String message) {
        if (!isValidUser(userId)) {
            return "Invalid user ID: " + userId;
        }
        if (!isValidRoom(roomId)) {
            return "Invalid room ID: " + roomId;
        }

        // Perform deduplication and throttling
        long userThrottle = userThrottleMap.computeIfAbsent(userId, k -> 0L);
        if (userThrottle < System.currentTimeMillis() / 1000) {
            userThrottleMap.put(userId, System.currentTimeMillis());
        } else {
            return "User throttled: " + userId;
        }

        long roomThrottle = roomThrottleMap.computeIfAbsent(roomId, k -> 0L);
        if (roomThrottle < System.currentTimeMillis() / 1000) {
            roomThrottleMap.put(roomId, System.currentTimeMillis());
        } else {
            return "Room throttled: " + roomId;
        }

        // Send message to Kafka
        ProducerRecord<String, String> record = new ProducerRecord<>("chat_messages", userId, message);
        try {
            producer.send(record).get();
        } catch (Exception e) {
            // Retry logic for transient failures
            if (e instanceof org.apache.kafka.common.errors.RecordTooLongException) {
                return "Message too long: " + message;
            }
            return "Error sending message: " + e.getMessage();
        }

        // Log message processing attempt and result
        logMessageAttempt(userId, roomId, message);

        return "Message sent successfully";
    }

    private boolean isValidUser(String userId) {
        // Validate user ID against internal user database
        return true;
    }

    private boolean isValidRoom(String roomId) {
        // Validate room ID against internal room database
        return true;
    }

    private void logMessageAttempt(String userId, String roomId, String message) {
        // Log message processing attempt and result using a logging framework
    }
}
