use reqwest::blocking::get;
use reqwest::{Client, header};
use serde_json::json;
use redis::Client as RedisClient;

async fn fetch_weather_data(api_key: &str, region: &str) -> Result<String, String> {
    let client = Client::new();
    let mut res = client.get(&format!("https://api.weather.com/api/v1.0/weather/{}?apiKey={}", region, api_key)).await?;

    if res.status().is_success() {
        let body = res.text().await?;
        Ok(body)
    } else {
        Err(format!("Failed to fetch weather data: {}", res.status()))
    }
}

async fn update_weather_data(drones: &Vec<String>, interval: u64) -> Result<(), String> {
    let mut redis_client = RedisClient::open("redis://localhost").unwrap();
    for drone in drones.iter() {
        let key = format!("drone:{}:weather", drone);
        redis_client.set(&key, "Updating weather data...".to_string()).await?;
    }
    tokio::time::sleep(std::time::Duration::from_millis(interval)).await;
    for drone in drones.iter() {
        let key = format!("drone:{}:weather", drone);
        match redis_client.get(&key).await {
            Ok(data) => println!("{} weather data updated at {}", drone, data),
            Err(err) => eprintln!("Error fetching {} weather data: {}", drone, err),
        }
    }
}

async fn configure_update_interval(json_config: &str) -> Result<u64, String> {
    let config: serde_json::Value = json::parse(json_config).unwrap();
    if let Some(interval) = config.get("updateInterval") {
        return interval.as_u64().map_err(|_| "Invalid update interval in JSON configuration".to_string());
    }
    Err("JSON configuration does not contain 'updateInterval' key".to_string())
}

async fn main() -> Result<(), String> {
    let api_key = "YOUR_API_KEY";
    let json_config = "{\"updateInterval\": 30000}";
    let mut redis_client = RedisClient::open("redis://localhost").unwrap();
    let interval = configure_update_interval(json_config).await?;
    loop {
        for drone in vec!["drone1", "drone2"].iter() {
            match fetch_weather_data(api_key, drone) {
                Ok(data) => println!("{} weather data: {}", drone, data),
                Err(err) => eprintln!("Error fetching {} weather data: {}", drone, err),
            }
        }
        update_weather_data(&vec!["drone1", "drone2"], interval).await?;
    }
}

#[tokio::main]
async fn run() -> Result<(), String> {
    main().await
}
