```
import org.neo4j.driver.*;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

import java.util.ArrayList;
import java.util.List;

@SpringBootApplication
@RestController
public class GraphDatabaseService {

    @Bean
    public Driver driver() {
        return GraphDatabase.driver("bolt://localhost:7687", AuthTokens.basic("neo4j", "password"));
    }

    @PostMapping("/addVertex")
    public String addVertex(@RequestBody VertexConfig vertexConfig) {
        try (Session session = driver().session()) {
            Node node = session.run("CREATE (n {properties}) RETURN n").single().get(0).asNode();
            return node.getId().toString();
        }
    }

    @PostMapping("/addEdge")
    public String addEdge(@RequestBody EdgeConfig edgeConfig) {
        try (Session session = driver()) {
            session.run("MATCH (a:Vertex {id:{source}}), (b:Vertex {id:{target}}) CREATE (a)-[:RELATIONSHIP]->(b)", 
                    Map.of("source", edgeConfig.getSource(), "target", edgeConfig.getTarget()));
            return "Edge added successfully";
        }
    }

    @PostMapping("/setVertexProperty")
    public String setVertexProperty(@RequestBody VertexPropertyConfig vertexPropertyConfig) {
        try (Session session = driver()) {
            session.run("MATCH (n:Vertex {id:{vertexId}}) SET n.{propertyName} = {propertyValue}", 
                    Map.of("vertexId", vertexPropertyConfig.getVertexId(), "propertyName", vertexPropertyConfig.getPropertyName(), "propertyValue", vertexPropertyConfig.getPropertyValue()));
            return "Vertex property set successfully";
        }
    }

    @PostMapping("/setEdgeProperty")
    public String setEdgeProperty(@RequestBody EdgePropertyConfig edgePropertyConfig) {
        try (Session session = driver()) {
            session.run("MATCH (a:Vertex {id:{source}})-[r:RELATIONSHIP]->(b:Vertex {id:{target}}) SET r.{propertyName} = {propertyValue}", 
                    Map.of("source", edgePropertyConfig.getSource(), "target", edgePropertyConfig.getTarget(), "propertyName", edgePropertyConfig.getPropertyName(), "propertyValue", edgePropertyConfig.getPropertyValue()));
            return "Edge property set successfully";
        }
    }

    @PostMapping("/getVertex")
    public String getVertex(@RequestBody VertexIdConfig vertexIdConfig) {
        try (Session session = driver()) {
            Result result = session.run("MATCH (n:Vertex {id:{vertexId}}) RETURN n", 
                    Map.of("vertexId", vertexIdConfig.getVertexId()));
            return result.single().get(0).asNode().toString();
        }
    }

    @PostMapping("/getEdges")
    public String getEdges(@RequestBody VertexIdConfig vertexIdConfig) {
        try (Session session = driver()) {
            Result result = session.run("MATCH (n:Vertex {id:{vertexId}})-[r]-() RETURN r", 
                    Map.of("vertexId", vertexIdConfig.getVertexId()));
            return result.list().stream().map(r -> r.asRelationship()).collect(Collectors.toList());
        }
    }

    @PostMapping("/getGraph")
    public String getGraph(@RequestBody VertexIdConfig vertexIdConfig) {
        try (Session session = driver()) {
            Result result = session.run("MATCH (n:Vertex {id:{vertexId}})-[r]-() RETURN n, r", 
                    Map.of("vertexId", vertexIdConfig.getVertexId()));
            return result.list().stream().map(r -> r.asMap().toString()).collect(Collectors.toList());
        }
    }

    public static void main(String[] args) {
        SpringApplication.run(GraphDatabaseService.class, args);
    }
}
