const express = require('express');
const app = express();
const { Client } = require('@elastic/elasticsearch');
const { Database } = require('./database');
const { Cache } = require('./cache');

// Set up the database
const db = new Database();

// Set up the cache
const cache = new Cache();

// Set up the Elasticsearch client
const esClient = new Client({ node: 'https://your-elasticsearch-node.com' });

// Define the regular expressions for matching book names
const oldTestamentRegex = /(\b[A-Za-z\s]+[a-z]*\s*\([0-9]+\)\s*\(([^)]+)\))/i;
const newTestamentRegex = /(\b[A-Za-z\s]+[a-z]*\s*\([0-9]+\)\s*\(([^)]+)\) [Nn][Ee][Ww]\s*\([0-9]+\)\s*\(([^)]+)\))/i;

// Define the API endpoint
app.post('/process', async (req, res) => {
  try {
    const { data } = req.body;
    if (!data || !Array.isArray(data)) {
      return res.status(400).send({ error: 'Invalid input' });
    }

    // Process each piece of text data
    const bookCounts = {};
    for (const textData of data) {
      // Ignore punctuation and special characters
      const cleanedText = textData.replace(/[^\w\s]/gi, '');

      // Match Old Testament book names
      const oldTestamentMatches = cleanedText.match(oldTestamentRegex);
      if (oldTestamentMatches) {
        for (const match of oldTestamentMatches) {
          const bookName = match[1].trim().toLowerCase();
          bookCounts[bookName] = (bookCounts[bookName] || 0) + 1;
        }
      }

      // Match New Testament book names
      const newTestamentMatches = cleanedText.match(newTestamentRegex);
      if (newTestamentMatches) {
        for (const match of newTestamentMatches) {
          const bookName = match[2].trim().toLowerCase();
          bookCounts[bookName] = (bookCounts[bookName] || 0) + 1;
        }
      }
    }

    // Store the book counts in the cache
    await cache.set('book-counts', JSON.stringify(bookCounts));

    // Retrieve the list of books from the database
    const books = await db.getBooks();

    // Create a response object containing the book counts and list of books
    res.send({ bookCounts, books });
  } catch (error) {
    console.error(error);
    res.status(500).send({ error: 'Internal Server Error' });
  }
});

// Define the cache expiration time in milliseconds
const cacheExpirationTime = 60 * 1000; // 1 minute

// Start the service
app.listen(3000, () => {
  console.log('Service started on port 3000');
});
