import os
from urllib.parse import urlparse, urlunparse
from http.client import HTTPException
from queue import LifoQueue
from typing import Dict, Any

class URLFetcher:
    def __init__(self):
        self.max_connections = int(os.environ.get('MAX_CONNECTIONS', 50))
        self.cache_size = int(os.environ.get('CACHE_SIZE', 1000))
        self.cache = {}  # type: Dict[str, LifoQueue]
        self.connection_pool = []  # type: List[http.client.HTTPConnection]

    def fetch(self, url: str) -> Any:
        if not isinstance(url, str):
            raise TypeError("Invalid URL")
        parsed_url = urlparse(url)
        if len(parsed_url.path) > 1000:
            raise ValueError("URL path exceeds maximum length")

        headers = None
        content_length = None

        if url in self.cache:
            cache_entry = self.cache[url]
            try:
                headers, _ = cache_entry.get_nowait()
                return headers, content_length
            except queue.Empty:
                pass  # not available yet

        for connection in self.connection_pool:
            if connection is not None and connection.isconnected():
                try:
                    response = connection.getresponse()
                    if response.status == 200:
                        headers = dict(response.getheaders())
                        content_length = int(response.getheader('Content-Length'))
                    else:
                        raise HTTPException(f"Server returned status {response.status}")

                    self.cache[url] = LifoQueue(maxsize=1)
                    self.cache[url].put_nowait((headers, content_length))
                    return headers, content_length
                except (HTTPException, TimeoutError):
                    # handle timeouts and other exceptions
                    pass

        new_connection = http.client.HTTPConnection(parsed_url.netloc, timeout=10)
        self.connection_pool.append(new_connection)

        try:
            response = new_connection.getresponse()
            if response.status == 200:
                headers = dict(response.getheaders())
                content_length = int(response.getheader('Content-Length'))
            else:
                raise HTTPException(f"Server returned status {response.status}")

            self.cache[url] = LifoQueue(maxsize=1)
            self.cache[url].put_nowait((headers, content_length))
            return headers, content_length
        except (HTTPException, TimeoutError):
            # handle timeouts and other exceptions
            pass

    def get_logger(self) -> logging.Logger:
        logger = logging.getLogger('url-fetcher')
        logger.setLevel(logging.INFO)
        handler = logging.StreamHandler()
        handler.setFormatter(logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s'))
        logger.addHandler(handler)
        return logger

    def get_cache_size(self) -> int:
        return self.cache_size

    def set_cache_size(self, size: int):
        self.cache_size = size

