using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.SignalR;
using System;
using System.Threading.Tasks;

namespace MyWebApp
{
    public class UpdatePageSectionHub : Hub<IUpdatePageSection>
    {
        private readonly IPermissionService _permissionService;
        private readonly IHtmlContentService _htmlContentService;

        public UpdatePageSectionHub(IPermissionService permissionService, IHtmlContentService htmlContentService)
        {
            _permissionService = permissionService;
            _htmlContentService = htmlContentService;
        }

        [HttpPost]
        public async Task<IActionResult> HandleUpdate(int pageSectionId, string elementId, string newHtmlContent)
        {
            if (string.IsNullOrEmpty(elementId) || string.IsNullOrEmpty(newHtmlContent))
                return BadRequest("Element ID and HTML content must be provided");

            if (!_permissionService.HasPermissionToUpdate(pageSectionId, elementId))
                return Forbid();

            try
            {
                await _htmlContentService.UpdateHtmlContent(pageSectionId, elementId, newHtmlContent);
            }
            catch (ConcurrencyException)
            {
                return Conflict("Concurrent update conflict detected");
            }
            catch (Exception ex)
            {
                return StatusCode(500, "An unexpected error occurred: " + ex.Message);
            }

            await Clients.All.SendAsync("RefreshPageSection", pageSectionId);

            return Ok("Update successful");
        }
    }
}
