        (*nfalist)[i].RNTI = i + 2;

        int crc_flag_rule = crc_flag_rules[i % sizeof(crc_flag_rules) / sizeof(crc_flag_rules[0])];
        if (crc_flag_rule == 1) {
            (*nfalist)[i].CRCFLAG = 1;
        } else {
