#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* trimAndCapitalize(char* str, int sizeLimit, char** words) {
    // Create a copy of the input string
    char* temp = (char*)malloc(strlen(str) + 1);
    strcpy(temp, str);

    // Trim leading and trailing spaces from the copied string
    while (*temp == ' ') {
        memmove(temp, temp + 1, strlen(temp));
    }
    int len = strlen(temp);
    while (len > 0 && temp[len - 1] == ' ') {
        len--;
    }
    temp[len] = '\0';

    // Trim specified words from the beginning and end of the string
    for (int i = 0; i < sizeof(words) / sizeof(char*); i++) {
        int j = 0;
        while (j < strlen(temp) && strncmp(&temp[j], words[i], strlen(words[i])) == 0) {
            memmove(&temp[j + strlen(words[i])], &temp[j + 1], strlen(temp) - j);
            len -= strlen(words[i]);
            j = 0;
        }
    }

    // Check if the resulting string does not exceed the size limit
    if (strlen(temp) > sizeLimit) {
        free(temp);
        return NULL;
    }

    // Capitalize the first letter of each word and return the modified string
    char* result = (char*)malloc(strlen(temp) + 1);
    strcpy(result, temp);

    for (int i = 0; i < strlen(result); i++) {
        if (result[i] == ' ') {
            *(result + i + 1) = toupper(*(result + i + 1));
        }
    }

    free(temp);
    return result;
}

int main() {
    char* str = "   Hello World, it's a beautiful day!";
    int sizeLimit = 20;
    char* words[] = {"Hello", "World"};
    char* result = trimAndCapitalize(str, sizeLimit, words);

    if (result != NULL) {
        printf("Modified string: %s\n", result);
        free(result);
    } else {
        printf("String exceeds the size limit.\n");
    }

    return 0;
}
