import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

public class Md5Service {

    private static final Logger logger = LoggerFactory.getLogger(Md5Service.class);

    private ExecutorService executor;
    private Cache<String, String> cache;
    private RedisTemplate<String, String> redisTemplate;
    private int maxThreads;
    private int cacheSize;

    public Md5Service(int maxThreads, int cacheSize) {
        this.maxThreads = maxThreads;
        this.cacheSize = cacheSize;
        this.executor = new ThreadPoolExecutor(maxThreads, maxThreads, 0L, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<Runnable>());
        this.cache = new LfuCache<String, String>(cacheSize);
    }

    public Map.Entry<String, String> computeMd5(String input) throws InterruptedException {
        if (input == null || input.length() > 1000) {
            return null;
        }

        try {
            MessageDigest md = MessageDigest.getInstance("MD5");

            // Convert the string to bytes using the specified encoding
            byte[] bytes = input.getBytes("UTF-8");

            // Compute the MD5 hash
            byte[] digest = md.digest(bytes);

            String hexHash = DatatypeConverter.printHexBinary(digest).toLowerCase();

            // Cache the result
            cache.put(input, hexHash);

            // Store it in Redis for persistence and data integrity
            redisTemplate.opsForValue().set(input, hexHash);

            return new AbstractMap.SimpleEntry<>(input, hexHash);
        } catch (NoSuchAlgorithmException | IOException e) {
            logger.error("Error computing MD5 hash", e);
            return null;
        }
    }

