import org.json.JSONObject;

public class MessageDecrypter {

    private static final String AES_ALGORITHM = "AES";
    private static final String HMAC_SHA256_ALGORITHM = "HmacSHA256";

    public String decryptMessages(String encryptedJson) {
        JSONObject encryptedData = new JSONObject(encryptedJson);
        List<DecryptedMessage> decryptedMessages = new ArrayList<>();

        for (int i = 0; i < encryptedData.length(); i++) {
            JSONObject message = encryptedData.getJSONObject(i);
            String encryptedText = message.getString("text");
            String key = message.getString("key");
            String iv = message.getString("iv");

            try {
                // Decrypt the message
                Cipher cipher = Cipher.getInstance(AES_ALGORITHM);
                IvParameterSpec ivParams = new IvParameterSpec(iv.getBytes());
                cipher.init(Cipher.DECRYPT_MODE, generateAESKey(key), ivParams);

                byte[] decryptedBytes = cipher.doFinal(encryptedText.getBytes());

                String decryptedText = new String(decryptedBytes, "UTF-8");
                JSONObject decryptedMessage = message.put("text", decryptedText);
                boolean isValid = validateHMAC(decryptedMessage, key);

                DecryptedMessage dm = new DecryptedMessage(decryptedMessage, isValid);
                decryptedMessages.add(dm);
            } catch (Exception e) {
                // Handle decryption error
                System.out.println("Decryption failed: " + e.getMessage());
            }
        }

        return new JSONObject()
                .put("decrypted_messages", new JSONArray(decryptedMessages))
                .toString();
    }

    private SecretKeySpec generateAESKey(String keyString) {
        byte[] keyBytes = DatatypeConverter.parseHexBinaryString(keyString);
        return new SecretKeySpec(keyBytes, AES_ALGORITHM);
    }

    private boolean validateHMAC(JSONObject message, String key) {
        // Implement HMAC validation logic using the provided key
        // Return true if valid, false otherwise
    }
}

class DecryptedMessage {
    public JSONObject message;
    public boolean isValid;

    public DecryptedMessage(JSONObject message, boolean isValid) {
        this.message = message;
        this.isValid = isValid;
    }
}
