// Function to set file type based on filename extension
void set_file_type(char* filename, char** new_filename) {
    const char* extensions[] = {"txt", "jpg", "png", "pdf"};
    int num_extensions = sizeof(extensions) / sizeof(extensions[0]);

    for (int i = 0; i < num_extensions; i++) {
        if (strstr(filename, "." + strlen(extensions[i])) != NULL) {
            strcpy(new_filename[1], extensions[i]);
            return;
        }
    }
}

// Function to determine the number of digits based on file type
void set_digit_count(char* filename, char** new_filename) {
    const char* image_extensions[] = {"jpg", "png"};
    int num_image_extensions = sizeof(image_extensions) / sizeof(image_extensions[0]);

    for (int i = 0; i < num_image_extensions; i++) {
        if (strstr(filename, "." + strlen(image_extensions[i])) != NULL) {
            sprintf(new_filename[2], "%03d", rand() % 1000);
            return;
        }
    }
}

// Function to modify the filename extension
void modify_filename(char* filename, char** new_filename) {
    // Remove any existing file type and create a new one
    int len = strlen(filename);
    if (filename[len - 4] == '.') {
        memmove(&filename[len - 4], &filename[len]);
    }

    *new_filename[0] = '\0';
    strcat(*new_filename, filename);
}

