    // Parse the filename
    char* filename = argv[1];
    int len = strlen(filename);

    // Check for edge cases: filenames starting with a dot and empty filenames
    if (len > 0 && !isalpha(filename[0])) {
        log_error("Invalid filename. It must start with a letter.");
        return -1;
    }

    if (!filename[len - 4]) {
        log_error("The filename has no extension.");
        return -1;
    }

    // Determine the number of digits
    set_digit_count(filename, new_filename);

    // Set the file type
    set_file_type(filename, new_filename);

    // Modify the filename extension
    modify_filename(filename, new_filename);

    log_info("Modified filename: %s", *new_filename[0]);

    for (int i = 0; i < 3; i++) {
        free(new_filename[i]);
    }

    return 0;
}

