import csv
import sys
from typing import List, Dict

def process_csv_files(args: List[str]) -> None:
    try:
        input_file = None
        output_file = None
        separator = ','
        filter_column = None
        filter_value = None
        for arg in args[1:]:
            if arg.startswith('-s'):
                separator = arg.split('=')[1]
            elif arg.startswith('-o'):
                output_file = arg.split('=')[1]
            elif arg.startswith('-f'):
                filter_column, filter_value = map(str.strip, arg.split('='))

        with open(args[0], 'r') as csvfile:
            reader = csv.reader(csvfile, delimiter=separator)
            if output_file:
                writer = csv.writer(open(output_file, 'w', newline=''), delimiter=separator)
            else:
                writer = csv.writer(sys.stdout, delimiter=separator)

            for row in reader:
                extracted_data = []
                for column_name in [filter_column]:
                    try:
                        extracted_data.append(row[row.index(column_name)])
                    except ValueError:
                        print(f"Column '{column_name}' not found.")
                        continue
                if filter_value and filter_column:
                    try:
                        if int(filter_value) > int(extracted_data[0]):
                            writer.writerow(extracted_data)
                    except (ValueError, IndexError):
                        print("Invalid filter value or column name. Skipping this row.")
                        continue
                else:
                    writer.writerow(extracted_data)

    except FileNotFoundError:
        print(f"File '{args[0]}' not found.")
    except (IndexError, KeyError, ValueError):
        print(f"Invalid input file or CSV format.")
    except Exception as e:
        print(f"An error occurred: {str(e)}")

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python csv_processor.py <input_file> [-s <separator>] [-o <output_file>] [-f <filter_column>=<filter_value>]")
        sys.exit(1)
    process_csv_files(sys.argv)
