import random
import uuid
from threading import Lock
import logging

class NetworkConfig:
    def __init__(self, server_id: str, port_number: int, weight: int):
        self.server_id = server_id
        self.port_number = port_number
        self.weight = weight


def generate_unique_config(config_list: list) -> NetworkConfig:
    while True:
        try:
            config_id = uuid.uuid4().hex
            port_number = random.randint(1, 65535)
            weight = random.randint(1, 100)

            if not any(c.server_id == config_id and c.port_number == port_number for c in config_list):
                return NetworkConfig(config_id, port_number, weight)
        except Exception as e:
            logging.error(f"Error generating unique config: {str(e)}")


class LoadBalancerManager:
    def __init__(self):
        self.config_list = []
        self.lock = Lock()

    def add_config(self) -> None:
        with self.lock:
            try:
                config = generate_unique_config(self.config_list)
                if not 1 <= config.weight <= 100:
                    raise ValueError("Weight must be within the range 1-100")
                self.config_list.append(config)
                logging.info(f"Added config {config.server_id}:{config.port_number} with weight {config.weight}")
            except Exception as e:
                logging.error(f"Failed to add config: {str(e)}")

    def get_config(self, server_id: str, port_number: int) -> NetworkConfig:
        with self.lock:
            try:
                for config in self.config_list:
                    if config.server_id == server_id and config.port_number == port_number:
                        return config
                logging.error(f"Config {server_id}:{port_number} not found")
                return None
            except Exception as e:
                logging.error(f"Error retrieving config: {str(e)}")

    def update_config(self, server_id: str, port_number: int, new_weight: int) -> None:
        with self.lock:
            try:
                for i, config in enumerate(self.config_list):
                    if config.server_id == server_id and config.port_number == port_number:
                        if not 1 <= new_weight <= 100:
                            raise ValueError("Weight must be within the range 1-100")
                        self.config_list[i].weight = new_weight
                        logging.info(f"Updated config {config.server_id}:{config.port_number} with weight {new_weight}")
                        return
                logging.error(f"Config {server_id}:{port_number} not found")
            except Exception as e:
                logging.error(f"Error updating config: {str(e)}")

    def delete_config(self, server_id: str, port_number: int) -> None:
        with self.lock:
            try:
                for i, config in enumerate(self.config_list):
                    if config.server_id == server_id and config.port_number == port_number:
                        del self.config_list[i]
                        logging.info(f"Deleted config {server_id}:{port_number}")
                        return
                logging.error(f"Config {server_id}:{port_number} not found")
            except Exception as e:
                logging.error(f"Error deleting config: {str(e)}")

    def get_config_count(self) -> int:
        with self.lock:
            try:
                return len(self.config_list)
            except Exception as e:
                logging.error(f"Error retrieving config count: {str(e)}")
