class AdvancedPasswordManager {
    private $hashedPassword = '';
    private $saltRoundCount = 12;
    private $characterSet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-={}:<>?,.';
    private $passwordAttemptLog = [];
    private $cachedStrings = [];

    public function generateSecureRandomString($length) {
        if (isset($this->cachedStrings[$length])) {
            return $this->cachedStrings[$length];
        }

        $secureRandomString = '';
        for ($i = 0; $i < $length; $i++) {
            $secureRandomString .= $this->characterSet[mt_rand(0, strlen($this->characterSet) - 1)];
        }
        $this->cachedStrings[$length] = $secureRandomString;
        return $secureRandomString;
    }

    public function hashPassword($password) {
        if (rand() % 60 < 10 && count($this->passwordAttemptLog) >= 100) { // Rate limiting
            sleep(1); // Wait for 1 minute before allowing next request
        }

        $hashedPassword = password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
        $this->hashedPassword = $hashedPassword;
    }

    public function checkPassword($password) {
        if (password_verify($password, $this->hashedPassword)) {
            return true;
        } else {
            $this->logPasswordAttempts($_SERVER['REMOTE_ADDR'], false);
            return false;
        }
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds < 12 || $rounds > 31) {
            $this->saltRoundCount = 12; // Default value
        } else {
            $this->saltRoundCount = $rounds;
        }
    }

    public function validateCharacterSet($characterSet) {
        if (strlen($characterSet) < 10) { // Minimum length for the character set
            return 'Invalid character set. Please provide at least 10 unique characters.';
        } elseif (!preg_match('/[A-Z]/', $characterSet)) {
            return 'Character set should contain at least one uppercase letter.';
        } elseif (!preg_match('/[a-z]/', $characterSet)) {
            return 'Character set should contain at least one lowercase letter.';
        } elseif (!preg_match('/\d/', $characterSet)) {
            return 'Character set should contain at least one digit.';
        } elseif (!preg_match('/[^A-Za-z0-9]/', $characterSet)) { // Special character
            return 'Character set should contain at least one special character.Fallbacking to default character set.' . $this->getFallbackCharacterSet();
        }

        return true;
    }

    private function getFallbackCharacterSet() {
        return 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-={}:<>?,.';
    }

    public function resetPassword() {
        if ($this->hashedPassword) {
            $this->hashedPassword = '';
        }

        foreach ($this->cachedStrings as $length => $string) {
            unset($this->cachedStrings[$length]);
        }

        array_splice($this->passwordAttemptLog, 0, -100); // Clearing the log
    }

    public function logPasswordAttempts($ipAddress, $result) {
        if (count($this->passwordAttemptLog) >= 100) {
            array_shift($this->passwordAttemptLog);
        }

        $this->passwordAttemptLog[] = [$ipAddress, $result];
    }
}
