    }

    private void startAndStopLogging() throws InterruptedException {
        LogProcessor processor = factoryMap.get("jsonfactory").apply(new ObjectMapper().readValue("{\"log\":\"entry\"}", JsonNode.class));
        processor.start();
        try {
            Thread.sleep(30000); // Run for 30 seconds
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Propagate interrupt
        }
        processor.stop();
    }

    public void stop() {
        scheduler.shutdown();
    }
}

interface LogProcessor extends AutoCloseable {

    void start();

    void stop();
