template<typename Alloc = std::allocator<std::string>>
void insertAfter(std::forward_list<std::string, Alloc>& list, const std::string& target, const std::string& value) {
    auto it = std::find_if(list.begin(), list.end(),
        [target](const std::string& str) { return 0 == std::compare(target, 0, str, 0, target.size()); });

    if (it != list.end()) {
        list.insert_after(it, value);
    } else {
        list.append(value);
    }
}
