using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Transactions;

public class DataDeserializer
{
    private const string ErrorLogFilePath = @"C:\ErrorLog.txt";
    private const string DatabaseConnectionString = "Server=server_name;Database=database_name;User ID=user_id;Password=password;";
    private readonly FileStream _fileStream;
    private readonly BinaryFormatter _formatter;

    public DataDeserializer(string filePath)
    {
        _fileStream = File.Open(filePath, FileMode.OpenOrCreate);
        _formatter = new BinaryFormatter();
    }

    public void DeserializeAndValidate()
    {
        try
        {
            using (var transactionScope = new TransactionScope())
            {
                var data = _formatter.Deserialize(_fileStream) as CustomDataStructure;

                // Validate the loaded data against a predefined schema
                if (!data.IsValid())
                {
                    LogError("Invalid data detected during deserialization.");
                    return;
                }

                // Persist any changes made to the custom data structure in an external database
                using (var connection = new SqlConnection(DatabaseConnectionString))
                {
                    connection.Open();
                    using (var command = new SqlCommand("INSERT INTO table_name VALUES (@data)", connection))
                    {
                        command.Parameters.AddWithValue("@data", data);
                        command.ExecuteNonQuery();
                    }
                }

                transactionScope.Complete();
            }
        }
        catch (SerializationException ex)
        {
            LogError(ex.Message);
        }
        catch (SqlException ex)
        {
            // Handle database connection issues and transaction rollbacks efficiently
            using (var connection = new SqlConnection(DatabaseConnectionString))
            {
                connection.Open();
                using (var command = new SqlCommand("ROLLBACK TRANSACTION", connection))
                {
                    command.ExecuteNonQuery();
                }
            }
            LogError(ex.Message);
        }
        finally
        {
            _fileStream.Dispose();
        }
    }

    private void LogError(string errorMessage)
    {
        using (var fileStream = File.Create(ErrorLogFilePath, 1024, FileOptions.WriteThrough))
        {
            using (var writer = new StreamWriter(fileStream))
            {
                writer.WriteLine(errorMessage);
            }
        }
    }
}

