class AdvancedPasswordManager {
    private $hashedPassword;
    private $saltRoundCount = 12;
    private $characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890!@#$%^&*()_-+={}:<>?,.';
    private $cachedStrings = [];
    private $logFile;

    public function __construct($logFile) {
        $this->logFile = $logFile;
        $this->resetPassword();
    }

    public function generateSecureRandomString($length) {
        if (isset($this->cachedStrings[$length])) {
            return $this->cachedStrings[$length];
        }

        $string = '';
        for ($i = 0; $i < $length; $i++) {
            $char = $this->characterSet[rand(0, strlen($this->characterSet) - 1)];
            $string .= $char;
        }

        $this->cachedStrings[$length] = $string;
        return $string;
    }

    public function hashPassword($password) {
        $this->hashedPassword = password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
    }

    public function checkPassword($password) {
        return password_verify($password, $this->hashedPassword);
    }

    public function validateCharacterSet($characterSet) {
        if (!preg_match('/[A-Z]/', $characterSet) ||
            !preg_match('/[a-z]/', $characterSet) ||
            !preg_match('/\d/', $characterSet) ||
            !preg_match('/[^A-Za-z0-9]/', $characterSet)) {
            return 'Please provide a valid character set. A corrected suggestion is: ' . $this->characterSet;
        }

        return true;
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds < 12 || $rounds > 31) {
            throw new Exception('Invalid salt round count. The minimum value is 12 and the maximum is 31.');
        }

        $this->saltRoundCount = $rounds;
    }

    public function resetPassword() {
        $this->hashedPassword = null;
        $this->cachedStrings = [];
    }

    public function logPasswordAttempts($ipAddress, $result) {
        // Implement logging mechanism using a database or file
        // For simplicity, assume a simple text-based log for demonstration purposes
        file_put_contents($this->logFile, date('Y-m-d H:i:s') . " Attempt from IP: $ipAddress with result: $result\n", FILE_APPEND);
    }

    public function enforceTwoFactorAuthentication() {
        // Implement two-factor authentication mechanism using temporary codes sent via SMS or email
        // For simplicity, assume a simple text-based prompt for demonstration purposes
        echo 'Enter your 2FA code: ';
    }
}
