void callback(int, double, double);

int adaptiveStringProcessor(char* inputStr, int maxSize) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int numWords = 0;
    char* wordList[10];
    Word* words;

    // Initialize system load and average word length
    double sysLoad = 0.5;
    double avgWordLen = 4.2;

    // Get the list of words to be removed from input string
    pthread_mutex_lock(&mutex);
    wordList = getWordList();
    pthread_mutex_unlock(&mutex);

    numWords = sizeof(wordList) / sizeof(Word*);

    if (numWords > maxSize) {
        printf("Error: Word list size exceeds maximum allowed size.\n");
        return NULL;
    }

    // Calculate the adjusted size limit based on system load and average word length
    int adjustedSize = (int)((1 - sysLoad) * avgWordLen * numWords + 10);

    if (adjustedSize > maxSize) {
        adjustedSize = maxSize;
    }

    char* resultStr = malloc((adjustedSize + 1) * sizeof(char));
    strcpy(resultStr, inputStr);

    // Remove words from the beginning and end of the input string
    for (int i = 0; i < numWords; i++) {
        int pos = 0;
        while ((pos = strstr(resultStr, wordList[i]->word)) != NULL) {
            if (pos == resultStr || pos + wordList[i]->size - 1 == strlen(resultStr)) {
                break;
            }
            pos += wordList[i]->size;
            strncat(&resultStr[0], &resultStr[pos - wordList[i]->size], adjustedSize);
        }
    }

    // Capitalize the first letter of each remaining word
    char* p = resultStr;
    while (*p != '\0') {
        if (isspace(*p)) {
            p++;
            continue;
        }
        *p = toupper(*p);
        p++;
    }

    free(resultStr);

    return resultStr;
}

Word* getWordList() {
    // Implement fetching the word list from an external data source
    // For demonstration purposes, a hardcoded example is used here.
    Word* words = (Word*)malloc(3 * sizeof(Word));
    words[0].word = "the";
    words[0].size = 3;
    words[1].word = "and";
    words[1].size = 4;
    words[2].word = "a";
    words[2].size = 1;
    return words;
}

int processString(char* str, int size) {
    // Implement the processing logic for each word
    // For demonstration purposes, a hardcoded example is used here.
    printf("Processing string: %s\n", str);
    return size;
}

void callback(int numOps, double accumValue, double estRemTime) {
