        for (String url : urls) {
            // Submit an image loading task to the executor
            Future<byte[]> future = executor.submit(() -> {
                try {
                    return cache.loadImage(url, quality);
                } catch (IOException e) {
                    throw new RuntimeException("Error loading image: " + e.getMessage());
                }
            });

            futures.add(future);
        }

        // Wait for all the images to load
        for (Future<byte[]> future : futures) {
            try {
                byte[] image = future.get();
                // Use the loaded image as needed
            } catch (InterruptedException | ExecutionException e) {
                throw new RuntimeException("Error loading image: " + e.getMessage());
            }
        }
    }
}

