public class DynamicServiceManager {

    private Map<String, ServiceFactory> serviceRegistry = new HashMap<>();
    private ExecutorService executor = Executors.newCachedThreadPool();
    private ObjectMapper mapper = new ObjectMapper();

    public void registerService(String id, ServiceFactory factory) {
        serviceRegistry.put(id, factory);
    }

    public void startService(String id) throws Exception {
        ServiceFactory factory = serviceRegistry.get(id);
        if (factory == null) {
            throw new Exception("No such service registered: " + id);
        }
        JsonNode config = mapper.readTree(factory.getServiceConfig());
        if (!config.hasNonNull("type")) {
            throw new Exception("Invalid service configuration: " + id);
        }
        Service instance = factory.createInstance(config);
        instance.start();
        executor.submit(() -> {
            try {
                Thread.sleep((long) (Math.random() * 10000));
                instance.stop();
                sendStopMessage(id);
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
        });
