public class CloudStorageClient {
    private Map<String, String> accessKeys;
    private List<CloudStorageProvider> providers;
    private int maxRetries;
    private int initialBackoffTimeMs;
    private int maxBackoffTimeMs;
    private Map<String, Long> lastSuccessfulUploadTimestamps;
    private Map<String, Long> lastSuccessfulDownloadTimestamps;

    public CloudStorageClient(Map<String, String> accessKeys) {
        this.accessKeys = accessKeys;
        providers = new ArrayList<>();
        // Initialize cloud storage providers
        providers.add(new S3CloudStorageProvider(accessKeys.get("S3_ACCESS_KEY"), accessKeys.get("S3_SECRET_KEY")));
        providers.add(new GCSCloudStorageProvider(accessKeys.get("GCS_CREDENTIALS")));
        providers.add(new AzureBlobStorageProvider(accessKeys.get("AZURE_STORAGE_ACCOUNT_KEY"), accessKeys.get("AZURE_STORAGE_ACCOUNT_NAME")));

        maxRetries = 5;
        initialBackoffTimeMs = 500;
        maxBackoffTimeMs = 30000;

        lastSuccessfulUploadTimestamps = new HashMap<>();
        lastSuccessfulDownloadTimestamps = new HashMap<>();
    }

    public void uploadFile(String bucketName, String filePath) {
        CloudStorageProvider currentProvider = getPreferredProvider();
        for (int i = 0; i <= maxRetries && !isUploadSuccessful(bucketName); i++) {
            try {
                currentProvider.uploadFile(bucketName, filePath);
                lastSuccessfulUploadTimestamps.put(bucketName, System.currentTimeMillis());
                break;
            } catch (Exception e) {
                logError(e);
                if (i < maxRetries - 1) {
                    // Perform exponential backoff
                    long backoffTimeMs = Math.min(initialBackoffTimeMs * (2 ^ i), maxBackoffTimeMs);
                    try {
                        Thread.sleep(backoffTimeMs);
                    } catch (InterruptedException ie) {
                        logError(ie);
                    }
                }
            }
        }
    }

    public void downloadFile(String bucketName, String filePath) {
        CloudStorageProvider currentProvider = getPreferredProvider();
        for (int i = 0; i <= maxRetries && !isDownloadSuccessful(bucketName); i++) {
            try {
                currentProvider.downloadFile(bucketName, filePath);
                lastSuccessfulDownloadTimestamps.put(bucketName, System.currentTimeMillis());
                break;
            } catch (Exception e) {
                logError(e);
                if (i < maxRetries - 1) {
                    // Perform exponential backoff
                    long backoffTimeMs = Math.min(initialBackoffTimeMs * (2 ^ i), maxBackoffTimeMs);
                    try {
                        Thread.sleep(backoffTimeMs);
                    } catch (InterruptedException ie) {
                        logError(ie);
                    }
                }
            }
        }
    }

    private CloudStorageProvider getPreferredProvider() {
        // Implement logic to determine the preferred provider based on current load and performance metrics
        return providers.get(0); // Default to the first provider
    }

    private boolean isUploadSuccessful(String bucketName) {
        // Check if the upload was successful based on storage provider-specific metadata or logging
