#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>

typedef enum {
    ECB_MODE,
    EDE_MODE,
    EDE3_MODE,
    CFB_MODE
} CipherMode;

typedef struct _Cipher {
    void* handle;
    int (*encrypt)(void*, char*, int);
    int (*decrypt)(void*, char*, int);
} Cipher;

Cipher* load_cipher(const char* name) {
    Cipher* cipher = (Cipher*)malloc(sizeof(Cipher));
    cipher->handle = dlopen(name, RTLD_LAZY);
    if (!cipher->handle) {
        printf("Error: Failed to load cipher module %s\n", name);
        return NULL;
    }
    cipher->encrypt = (int (*)(void*, char*, int))dlsym(cipher->handle, "des_encrypt");
    cipher->decrypt = (int (*)(void*, char*, int))dlsym(cipher->handle, "des_decrypt");
    if (!cipher->encrypt || !cipher->decrypt) {
        dlclose(cipher->handle);
        free(cipher);
        return NULL;
    }
    return cipher;
}

int main() {
    Cipher* ecb = load_cipher("ecb.so");
    Cipher* ede = load_cipher("ede.so");
    Cipher* cfb = load_cipher("cfb.so");

    if (!ecb || !ede || !cfb) {
        printf("Error: Unable to load cipher modules\n");
        return -1;
    }

    // Example usage
    int key[8] = {1, 2, 3, 4, 5, 6, 7, 8};
    char data[] = "Hello, World!";
    int len = strlen(data);

    printf("ECB Mode: %s\n", (char*)malloc(len+1));
    ecb->encrypt(key, data, len);

    printf("EDE Mode: %s\n", (char*)malloc(len+1));
    ede->encrypt(key, data, len);

    printf("CFB Mode: %s\n", (char*)malloc(len+1));
    cfb->encrypt(key, data, len);

    free(cipher.handle);
}

