#include <iostream>
#include <string>
#include <curl/curl.h>
#include <chrono>
#include <map>
#include <mutex>

// Test double for NetworkClient class
class MockNetworkClient {
public:
    std::string FetchDataFromApi(std::string url) override {
        if (url.find("success") != std::string::npos)
            return "{\"weather\": \"sunny\"}";
        else if (url.find("failure") != std::string::npos)
            return "{\"error\": \"API failure\"}";
        else
            return "{\"weather\": \"unknown\"}";
    }
};

// Caching mechanism using a map and lock for thread safety
class WeatherCache {
private:
    std::map<std::string, std::string> cache;
    std::mutex mutex;

public:
    bool SetWeatherData(std::string key, std::string value) {
        std::unique_lock<std::mutex> lock(mutex);
        if (cache.find(key) != cache.end()) {
            return false;  // Cache already contains this data
        }
        cache[key] = value;
        return true;
    }

    std::string GetWeatherData(std::string key) {
        std::unique_lock<std::mutex> lock(mutex);
        auto it = cache.find(key);
        if (it != cache.end())
            return it->second;
        else
            return "";
    }
};

// Logger class for recording API calls, cache hits, and cache misses
class Logger {
public:
    void LogApiCall(std::string message) {
        std::cout << "API Call: " << message << std::endl;
    }

    void LogCacheHit() {
        std::cout << "Cache Hit" << std::endl;
    }

    void LogCacheMiss() {
        std::cout << "Cache Miss" << std::endl;
    }
};

// Main program
int main() {
    MockNetworkClient networkClient;
    WeatherCache cache;
    Logger logger;

    // User-provided coordinates
    double latitude = 37.7749;
    double longitude = -122.4194;

    // Caching time-to-live (TTL) in seconds
    int ttl = 60;  // Cache data for 1 minute

    // Simulate a cache miss and API call
    if (!cache.SetWeatherData(std::to_string(latitude) + "_" + std::to_string(longitude), "")) {
        logger.LogApiCall("API call initiated");
        std::string weatherData = networkClient.FetchDataFromApi("https://api.weather.com/success");
        cache.SetWeatherData(std::to_string(latitude) + "_" + std::to_string(longitude), weatherData);
    }

    // Simulate a cache hit
    logger.LogCacheHit();
    std::string cachedWeatherData = cache.GetWeatherData(std::to_string(latitude) + "_" + std::to_string(longitude));
    if (cachedWeatherData.empty()) {
        logger.LogApiCall("API call initiated");
        weatherData = networkClient.FetchDataFromApi("https://api.weather.com/failure");
        cache.SetWeatherData(std::to_string(latitude) + "_" + std::to_string(longitude), weatherData);
    }

    // Simulate a cache miss after TTL expiration
    sleep(ttl);  // Wait for the caching TTL to expire
    logger.LogCacheMiss();
    if (!cache.GetWeatherData(std::to_string(latitude) + "_" + std::to_string(longitude)).empty()) {
        logger.LogApiCall("API call initiated");
        weatherData = networkClient.FetchDataFromApi("https://api.weather.com/success");
        cache.SetWeatherData(std::to_string(latitude) + "_" + std::to_string(longitude), weatherData);
    }

    return 0;
}

