        model = GraphConfig

@app.route('/graph', methods=['POST'])
def create_graph():
    graph_config = GraphConfig()
    vertices = []
    edges = []
    for vertex in request.json['vertices']:
        v = Vertex(properties=vertex['properties'])
        db.session.add(v)
        vertices.append(v.id)
    for edge in request.json['edges']:
        e = Edge(source_vertex_id=edge['source_vertex_id'], target_vertex_id=edge['target_vertex_id'])
        db.session.add(e)
        edges.append(e.id)
    graph_config.vertices = [v for v in Vertex.query.all() if v.id in vertices]
    graph_config.edges = [e for e in Edge.query.all() if e.id in edges]
    db.session.commit()
    return jsonify({'graph': vertices, 'edges': edges})

