import java.util.ArrayList;
import java.util.List;

class UnionFind {
    private int[] parent;
    private int[] rank;

    public UnionFind(int n) {
        parent = new int[n];
        rank = new int[n];

        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public void makeSet(int x) {
        parent[x] = x;
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX == rootY) {
            return;
        }

        if (rank[rootX] < rank[rootY]) {
            parent[rootX] = rootY;
        } else if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
    }

    public boolean connected(int x, int y) {
        return find(x) == find(y);
    }
}

public class DisjointPairCounter {

    private static final int MAX_SIZE = 100000;

    public static void main(String[] args) throws Exception {
        List<int[]> arrays = new ArrayList<>();

        // Add your arrays here
        arrays.add(new int[]{1, 2, 3});
        arrays.add(new int[]{4, 5, 6});

        for (int[] array : arrays) {
            long startTime = System.currentTimeMillis();
            int disjointPairs = countDisjointPairs(array);
            long endTime = System.currentTimeMillis();

            System.out.println("Number of disjoint pairs: " + disjointPairs);
            System.out.println("Time taken: " + (endTime - startTime) + " milliseconds");

            logToAPI(disjointPairs, array.length, endTime - startTime);
        }
    }

    public static int countDisjointPairs(int[] array) {
        UnionFind unionFind = new UnionFind(MAX_SIZE);

        for (int i = 0; i < array.length; i++) {
            unionFind.makeSet(array[i]);
        }

        int disjointPairs = 0;
        for (int i = 0; i < array.length; i++) {
            for (int j = i + 1; j < array.length; j++) {
                if (!unionFind.connected(array[i], array[j])) {
                    disjointPairs++;
                    unionFind.union(array[i], array[j]);
                }
            }
        }

        return disjointPairs;
    }

    public static void logToAPI(int disjointPairs, int size, long time) throws Exception {
        // Replace with your API endpoint
        String url = "https://your-api-endpoint.com/disjoint-pairs";
        String payload = "{\"disjoint_pairs\": \"" + disjointPairs + "\", \"size\": \"" + size + "\", \"time\": \"" + time + "\"}";

