import java.util.Random;
import java.util.concurrent.atomic.AtomicInteger;

public class ServiceStarter {
    private static final int MAX_CONSECUTIVE_FAILURES = 3;
    private static final int MIN_DELAY = 1000; // in milliseconds
    private static final int MAX_DELAY = 60000; // in milliseconds

    public static void main(String[] args) {
        AtomicInteger consecutiveFailures = new AtomicInteger(0);
        Random random = new Random();

        while (true) {
            try {
                startService();
                consecutiveFailures.set(0);

                long delay = random.nextInt((MAX_DELAY - MIN_DELAY) + 1) + MIN_DELAY;
                Thread.sleep(delay);

            } catch (InterruptedException e) {
                logError("Thread interrupted: " + e.getMessage());
                System.exit(-1);
            } catch (ServiceException e) {
                consecutiveFailures.incrementAndGet();
                if (consecutiveFailures.get() >= MAX_CONSECUTIVE_FAILURES) {
                    stopService();
                    logError("Maximum consecutive failures reached. Stopping service.");
                    break;
                }

                try {
                    Thread.sleep(random.nextInt((MAX_DELAY - MIN_DELAY) + 1) + MIN_DELAY);
                } catch (InterruptedException ex) {
                    logError("Thread interrupted: " + ex.getMessage());
                    System.exit(-1);
                }
            }
        }

        stopService();
    }

    private static void startService() throws ServiceException {
        // implement your service starting code here
    }

    private static void stopService() {
        // implement your service stopping code here

        logInfo("Service stopped.");
    }

    private static void logError(String message) {
        // implement your logging mechanism here
    }

    private static void logInfo(String message) {
        // implement your logging mechanism here
    }
}

class ServiceException extends Exception {
