        // Update database table with new status and last modified information
        if (!updateDatabase($clinicId, $status, $ipAddress, $logId)) {
            // Rollback transaction on error
            db()->rollBack();
            return '{"error": "Database update failed"}';
        }

        // Commit transaction successfully
        db()->commit();

        // Log authentication and database update operations
        logOperations($clinicId, $status);

        return '{"success": "Clinic status updated"}';

