import os
import concurrent.futures
import logging
import gzip
import shutil

class FileMerger:
    def __init__(self):
        self.logger = logging.getLogger('FileMerger')
        self.logger.setLevel(logging.INFO)

    def merge_files(self, file_paths, dest_path, buffer_size=1048576, compression=False):
        if not file_paths or not all(os.path.exists(file) for file in file_paths):
            raise FileNotFoundError("One or more files do not exist")

        try:
            with open(dest_path, 'wb') as dest_file:
                with concurrent.futures.ThreadPoolExecutor(max_workers=os.cpu_count()) as executor:
                    futures = []
                    for file in file_paths:
                        futures.append(executor.submit(self.read_file, file, buffer_size))

                    total_bytes = 0
                    for future in concurrent.futures.as_completed(futures):
                        bytes_read, file_name = future.result()
                        dest_file.write(bytes_read)
                        total_bytes += bytes_read
                        self.logger.info(f"Merged {file_name} with {bytes_read} bytes")

            if compression:
                with gzip.open(dest_path, 'wb') as gz_dest_file:
                    shutil.copyfile(dest_path, gz_dest_file)

            self.logger.info(f"File merging completed successfully: {dest_path}, size: {total_bytes} bytes")

        except Exception as e:
            for i in range(1, 4):
                try:
                    if compression:
                        os.remove(dest_path)
                    raise
                except FileNotFoundError:
                    pass

                time.sleep(2 ** i)

            raise

    def read_file(self, file_path, buffer_size):
        with open(file_path, 'rb') as file:
            bytes_read = file.read(buffer_size)
            while bytes_read:
                yield bytes_read
                bytes_read = file.read(buffer_size)
        return b'', os.path.basename(file_path)

if __name__ == "__main__":
    merger = FileMerger()
