```javascript
const cache = {};
const fetchScript = (src) => {
    return new Promise((resolve, reject) => {
        const request = new XMLHttpRequest();
        request.open('GET', src);
        request.onload = () => {
            if (request.status === 200) {
                resolve(request.responseText);
            } else {
                reject(new Error(`Failed to load script: ${src}`));
            }
        };
        request.onerror = () => {
            reject(new Error(`Network error loading script: ${src}`));
        };
        request.send();
    });
};

const validateScript = (script) => {
    if (!script.src || !script.type || !script.key) {
        throw new Error('Invalid script object');
    }
    return script;
};

const getMetadata = async (scriptId) => {
    const response = await fetch(`https://config-service.com/script-metadata/${scriptId}`);
    const metadata = await response.json();
    return metadata;
};

const renderScript = (script, metadata) => {
    if (!script.src) {
        script.src = metadata.fallbackUrl;
    }
    const scriptTag = `<script src="${script.src}" type="${script.type}" data-key="${script.key}"></script>`;
    return scriptTag;
};

const renderFooterScripts = async (scripts) => {
    try {
        const validScripts = scripts.filter(validateScript);
        await Promise.all(validScripts.map(async (script) => {
            if (!cache[script.key]) {
                cache[script.key] = await fetchScript(script.src);
            }
            return getMetadata(script.key).then((metadata) => renderScript(script, metadata));
        }));
    } catch (error) {
        console.error(error);
        return '<p>Error rendering scripts: ' + error.message + '</p>';
    }
};

export default renderFooterScripts;
