use dirs;
use std::env;
use std::fs;
use std::path::Path;
use xmltree::{Element, XPath};
use reqwest;

pub fn extract_data(xml: &str, path: &str) -> Result<String, String> {
    let root = Element::parse(xml).unwrap();
    if let Some(result) = extract_node(&root, "your_xpath_expression").clone() {
        return Ok(result);
    }
    match dirs::home_dir() {
        None => {
            let dir_path = create_directory("your_new_directory_name");
            set_environment_variable(dir_path.to_string_lossy().to_string());
        }
        Some(dir) => {
            let dir_path = dir.display().to_string();
            if !Path::new(&dir_path).exists() {
                fs::create_dir_all(dir_path.as_str()).unwrap();
            }
            set_environment_variable(dir_path.clone());
        }
    };
    Ok("Extracted data successfully".to_string())
}

fn extract_node(root: &Element, path: &str) -> Option<String> {
    let mut current = root;
    for part in path.split('/') {
        match current.children().find(|child| child.name() == part) {
            Some(child) => current = child,
            None => return None,
        }
    }
    Some(current.text().clone())
}

fn create_directory(name: &str) -> String {
    let dir_path = dirs::home_dir().unwrap().display().to_string();
    if let Err(err) = fs::create_dir_all(dir_path.clone() + "/" + name) {
        return format!("Failed to create directory: {}", err);
    }
    dir_path.clone() + "/" + name.to_string()
}

fn set_environment_variable(path: String) {
    match env::set_var("PATH_OF_NEW_DIRECTORY", path) {
        Ok(_) => println!("Environment variable 'PATH_OF_NEW_DIRECTORY' is now set"),
        Err(err) => eprintln!("Failed to set environment variable: {}", err),
    }
}
