EVP_CIPHER_CTX* get_des_cipher(const char* mode, const unsigned char* key, size_t key_len,
                                const unsigned char* iv, size_t iv_len) {
    EVP_CIPHER_CTX* ctx = NULL;
    int key_len_int = (int)key_len;
    int iv_len_int = (int)iv_len;

    if (!mode || !key || !iv) {
        // Handle invalid input
        return NULL;
    }

    switch (strlen(mode)) {
        case 3: { // ECB, EDE, or EDE3
            if (!strcmp(mode, "ECB")) {
                ctx = EVP_CIPHER_CTX_new();
                EVP_DecryptInit_ex(ctx, EVP_des_ecb(), NULL, key, &key_len_int);
                break;
            }
            else if (!strcmp(mode, "EDE") || !strcmp(mode, "EDe")) {
                ctx = EVP_CIPHER_CTX_new();
                EVP_DecryptInit_ex(ctx, EVP_des_ede(), NULL, key, &key_len_int);
                break;
            }
            else if (!strcmp(mode, "ED3") || !strcmp(mode, "EDE3")) {
                ctx = EVP_CIPHER_CTX_new();
                EVP_DecryptInit_ex(ctx, EVP_des_ede3(), NULL, key, &key_len_int);
                break;
            }
        }
        case 4: { // CFB
            if (!strncmp(mode, "CFB", 3)) {
                if (iv_len_int > EVP_des_block_size()) {
                    // Handle invalid IV length for CFB mode
                    return NULL;
                }
                ctx = EVP_CIPHER_CTX_new();
                EVP_DecryptInit_ex(ctx, EVP_des_cfb(), NULL, key, &key_len_int);
                EVP_CipherUpdate(ctx, iv, &iv_len_int);
                break;
            }
        }

    // Handle null encryption for testing purposes
    if (!strcmp(mode, "NULL")) {
        ctx = EVP_CIPHER_CTX_new();
        EVP_DecryptInit_ex(ctx, EVP_null(), NULL, key, &key_len_int);
        break;
    }

    return ctx;
}
