import asyncio
from concurrent.futures import ThreadPoolExecutor
from functools import wraps

def async_retry(max_attempts=3, delay=1):
    def decorator(func):
        @wraps(func)
        async def wrapper(*args, **kwargs):
            for attempt in range(1, max_attempts + 1):
                try:
                    return await func(*args, **kwargs)
                except Exception as e:
                    if attempt < max_attempts:
                        print(f"Attempt {attempt} failed: {str(e)}")
                        await asyncio.sleep(delay)
                    else:
                        raise
        return wrapper
    return decorator

def async_callback(callback):
    def callback_decorator(func):
        @wraps(func)
        async def wrapped_func(*args, **kwargs):
            try:
                result = await func(*args, **kwargs)
            except Exception as e:
                print(f"Error in callback: {str(e)}")
                return None
            return result
        return wrapped_func
    return callback_decorator

def deploy_package(package_path, config, timeout):
    # Validate deployment package
    if not validate_package(package_path):
        return "Invalid deployment package"

    # Parallelize deployment process
    loop = asyncio.get_event_loop()
    with ThreadPoolExecutor(max_workers=len(config["servers"])) as executor:
        tasks = []
        for server in config["servers"]:
            task = loop.run_in_executor(executor, deploy_server, package_path, server, timeout)
            tasks.append(task)
        results = await asyncio.gather(*tasks)

    # Check if any deployments failed
    for result in results:
        if not result:
            return "Deployment failed"

    return "Deployment successful"

@async_retry(max_attempts=3, delay=2)
async def deploy_server(package_path, server, timeout):
    # Execute installation scripts on the server
    for script in config["scripts"]:
        try:
            await run_script(script, server, package_path)
        except Exception as e:
            print(f"Error running script: {str(e)}")
            return False

    # Monitor deployment progress and update callback function
    while True:
        await asyncio.sleep(timeout)
        status = await get_status(server)
        if not callback(status):
            return False
        if status == "complete":
            return True

@async_callback(config["callback"])
async def run_script(script, server, package_path):
    # Execute script on the server
    try:
        result = await subprocess.run(["bash", "-c", f"cd {package_path} && {script}"], stdout=subprocess.PIPE)
        return result.stdout.decode()
    except Exception as e:
        print(f"Error running script: {str(e)}")
        return None

async def get_status(server):
    # Get deployment status from the server
    try:
        response = await requests.get(f"http://{server['ip']}/status")
        return response.json()["status"]
    except Exception as e:
        print(f"Error getting status: {str(e)}")
        return None
