import requests

def get_risks(product):
    risk_levels = {
        'electronic': {'low': ['static electricity'], 'medium': ['electromagnetic interference'], 'high': []},
        'chemical': {'low': [], 'medium': ['skin irritation'], 'high': ['fire hazard', 'explosion']},
        'food': {'low': ['allergens'], 'medium': ['microbial contamination'], 'high': ['toxic chemicals']}
    }

    api_url = f'https://risk-assessment-api.com/{product.category}'

    try:
        response = requests.get(api_url)
        response.raise_for_status()  # Raise an exception for HTTP errors
        additional_risks = response.json()['risks']

        if product.category in risk_levels:
            return ', '.join([risk_level for risk_level, risks in risk_levels[product.category].items() if any(risk in additional_risks for risk in risks)])
        else:
            return 'Unknown category'
    except requests.exceptions.RequestException as e:
        return f'Failed to retrieve risks: {e}'
