import json
import asyncio
from typing import Dict, List

class Config:
    def __init__(self):
        self.config = {}
        self.validation_rules = {
            "physics_simulation": lambda x: 0 < float(x) <= 100,
            "rendering_settings": lambda x: len(str(x)) > 1,
            "input_handling": lambda x: isinstance(x, list)
        }

    def load_config(self, file_path: str):
        try:
            with open(file_path, 'r') as file:
                self.config = json.load(file)
        except FileNotFoundError:
            print(f"Error: File {file_path} not found.")
        except json.JSONDecodeError as e:
            print(f"Error: Malformed JSON in file {file_path}. {e}")

    def validate_config(self):
        for key, value in self.config.items():
            if key in self.validation_rules:
                rule = self.validation_rules[key]
                if not rule(value):
                    print(f"Warning: Configuration {key} with value {value} may cause performance issues.")

    async def hot_reload(self, file_path: str):
        while True:
            try:
                self.load_config(file_path)
                await asyncio.sleep(1)
            except Exception as e:
                print(f"Error: Hot-reloading failed. {e}")

class GameEngine:
    def __init__(self, config: Config):
        self.config = config
        self.physics_simulation = None
        self.rendering_settings = None
        self.input_handling = None

    async def start(self):
        await asyncio.create_task(self.load_config())
        await asyncio.create_task(self.apply_config())

    async def load_config(self):
        await asyncio.sleep(1)
        print("Config loaded.")

    async def apply_config(self):
        await asyncio.sleep(1)
        print("Config applied.")
        self.physics_simulation = "Physics Simulation started."
        self.rendering_settings = "Rendering settings set."
        self.input_handling = "Input handling enabled."

def main():
    config = Config()
    config.load_config("config.json")
    config.validate_config()

    game_engine = GameEngine(config)
    asyncio.run(game_engine.start())

    while True:
        print("Press Ctrl+C to stop hot-reloading.")
        try:
            loop = asyncio.get_running_loop()
            loop.create_task(config.hot_reload("config.json"))
            await asyncio.sleep(1)
        except KeyboardInterrupt:
            break

if __name__ == "__main__":
    main()
