class PushNotificationProtocol(ABC):
    @abstractmethod
    def send_notification(self, device_token: str, notification_data: Dict[str, Any]) -> bool:
        pass

class APNsPushNotificationProtocol(PushNotificationProtocol):
    def __init__(self, apns_cert_path: str):
        self.apns_cert_path = apns_cert_path

    def send_notification(self, device_token: str, notification_data: Dict[str, Any]) -> bool:
        # implementation for sending push notifications using APNs
        pass

class FCMPushNotificationProtocol(PushNotificationProtocol):
    def __init__(self, fcm_api_key: str):
        self.fcm_api_key = fcm_api_key

    def send_notification(self, device_token: str, notification_data: Dict[str, Any]) -> bool:
        # implementation for sending push notifications using FCM
        pass

class PushNotificationManager:
    def __init__(self):
        self.protocols = {}
        self.cache = {}
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)

    def register_protocol(self, protocol: PushNotificationProtocol) -> None:
        self.protocols[protocol.__class__.__name__] = protocol

    def select_protocol(self, device_type: str) -> PushNotificationProtocol:
        if device_type in self.protocols:
            return self.protocols[device_type]
        else:
            # default protocol to use if no specific one is registered
            return next(iter(self.protocols.values()))

    def send_notification(self, device_token: str, notification_data: Dict[str, Any]) -> bool:
        device_type = self.get_device_type(device_token)
        if device_type not in self.protocols:
            self.logger.warning(f"Unknown device type '{device_type}'")
            return False

        protocol = self.select_protocol(device_type)
        if device_token in self.cache and self.cache[device_token] is not None:
            # reuse cached notification data
            return True

        try:
            result = protocol.send_notification(device_token, notification_data)
            if result:
                # cache successful notifications
                self.cache[device_token] = notification_data
            else:
                # log error and retry or handle failure as needed
                self.logger.error(f"Failed to send push notification for device '{device_token}'")
        except Exception as e:
            self.logger.error(f"Error sending push notification: {str(e)}")

        return result

    def get_device_type(self, device_token: str) -> str:
        # implementation to determine the device type based on the token
