int dynamicTestLoader(int numStructures, pthread_mutex_t *mutex) {
    NFAPI_CRC_INDICATION_PDU_T *structures = NULL;
    int i;

    // Initialize the list
    structures = (NFAPI_CRC_INDICATION_PDU_T *)malloc(numStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        printf("Error: Memory allocation failed.\n");
        return -1;
    }

    pthread_mutex_lock(mutex);
    for (i = 0; i < numStructures; i++) {
        structures[i].crcFlag = i;
        printf("[%s] Created structure with CRC flag %d\n", asctime(time(NULL)), structures[i].crcFlag);
    }
    pthread_mutex_unlock(mutex);

    // Store the list in the distributed database
    if (!store_structures_in_database(structures, numStructures)) {
        printf("Error: Database communication failed.\n");
        free(structures);
        return -1;
    }

    printf("[%s] List of %d structures stored successfully\n", asctime(time(NULL)), numStructures);

    // Retrieve the list from the database
    NFAPI_CRC_INDICATION_PDU_T *retrieved_structures = retrieve_structures_from_database();
    if (!retrieved_structures) {
        printf("Error: Database communication failed.\n");
        return -1;
    }

    for (i = 0; i < numStructures; i++) {
