    const dirPath = path.join(__dirname, dirName);
    try {
      if (!fs.existsSync(dirPath)) {
        fs.mkdirSync(dirPath);
        process.env.DIRECTORY_PATH = dirPath;
      }
    } catch (error) {
      console.error(`Error creating directory: ${error}`);
    }
  }

  // Set the environment variable
  function setEnvironmentVariable(name, value) {
    try {
      if (!process.env[name]) {
        process.env[name] = value;
      }
    } catch (error) {
      console.error(`Error setting environment variable: ${error}`);
    }
  }

  // Periodically scan the filesystem for old, unused directories and delete them
  function cleanup() {
    const maxDirsToKeep = config.maxDirectories;
    const interval = config.cleanupInterval * 1000; // Convert to milliseconds

    setInterval(() => {
      fs.readdir(__dirname, (err, files) => {
        if (err) {
          console.error(`Error reading directory: ${err}`);
          return;
        }

        files.forEach((file) => {
          const filePath = path.join(__dirname, file);
          try {
            if (!fs.statSync(filePath).isDirectory()) {
              fs.unlinkSync(filePath);
            }
          } catch (error) {
            console.error(`Error deleting file: ${error}`);
          }
        });

        // Keep only the last 'maxDirsToKeep' directories
        files.slice(maxDirsToKeep).forEach((file) => {
          const filePath = path.join(__dirname, file);
          try {
            fs.rmdirSync(filePath);
          } catch (error) {
            console.error(`Error deleting directory: ${error}`);
          }
        });
      });
    }, interval);
  }

  // Record metadata of the directories in an external database or data store
  function recordDirectoryMetadata(dirName, creationTime, lastAccessTime, referenceStatus) {
    const db = require('./database.js');
    try {
      db.insert({ dirName, creationTime, lastAccessTime, referenceStatus });
    } catch (error) {
      console.error(`Error recording metadata: ${error}`);
    }
  }

  // Periodically scan the filesystem and update the database with the latest directory metadata
  function updateDatabase() {
    const interval = config.updateInterval * 1000; // Convert to milliseconds

    setInterval(() => {
      fs.readdir(__dirname, (err, files) => {
        if (err) {
          console.error(`Error reading directory: ${err}`);
          return;
        }

        files.forEach((file) => {
          const filePath = path.join(__dirname, file);
          try {
            const stats = fs.statSync(filePath);
            recordDirectoryMetadata(file, stats.birthtime, stats.mtime, stats.isDirectory());
          } catch (error) {
            console.error(`Error updating database: ${error}`);
          }
        });
      });
    }, interval);
  }

  // Main function to manage directories
  return {
    create: createDirectory,
    setEnvironmentVariable,
    cleanup,
    recordMetadata: recordDirectoryMetadata,
    updateDatabase,
  };
}

// Example usage:
const directoryManager = manageDirectories(['resource1', 'resource2'], ['field1', 'field2']);
directoryManager.create('myNewDir');
directoryManager.setEnvironmentVariable('MY_VAR', 'path/to/my/dir');
directoryManager.cleanup();
directoryManager.recordMetadata('myExistingDir', Date.now(), new Date().getTime(), true);
directoryManager.updateDatabase();
