#define NFAPI_CRC_INDICATION_PDU_T_COUNT 1000000
#define CRCFLAG_MAX 255

typedef struct {
    uint16_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* dynamicTestLoader(int db_timeout) {
    RedisContext* ctx = redisConnect("localhost", 6379);
    if (!ctx) {
        log_error("Connection to Redis failed");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* ndata = (NFAPI_CRC_INDICATION_PDU_T*)malloc(NFAPI_CRC_INDICATION_PDU_T_COUNT * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!ndata) {
        log_error("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < NFAPI_CRC_INDICATION_PDU_T_COUNT; i++) {
        ndata[i].crcflag = i % CRCFLAG_MAX;
        // Store in Redis with unique key and expiration
        redisAppendCommand(ctx, "HSET ndata:%d crcflag %d", i, ndata[i].crcflag);
    }

    for (int i = 0; i < NFAPI_CRC_INDICATION_PDU_T_COUNT; i++) {
        // Retrieve from Redis with unique key and expiration
        char* data = redisGetReply(ctx, "HGET ndata:%d crcflag", i);
        if (!data) {
            log_error("Redis error");
            break;
        }
        uint16_t retrieved_crcflag = atoi(data);
        if (retrieved_crcflag != ndata[i].crcflag) {
            log_error("CRC flag conflict detected");
            free(ndata);
            return NULL;
        }
    }

    // Reset blueslip mocking library
    resetBlueslip();

    // Log creation and population process
    log_info("Dynamic test loader completed with %d structures", NFAPI_CRC_INDICATION_PDU_T_COUNT);

    redisFreeReply(ctx);
    free(ndata);
    return ndata;
}
