import subprocess
import logging
from blueslip import reset

def modify_kickstart_file(kickstart_path, password):
    # Replace placeholders with actual values
    with open(kickstart_path, "r+") as file:
        contents = file.read().replace("PLACEHOLDER", "ACTUAL_VALUE")
        file.seek(0)
        file.write(contents)

    # Append encrypted password to a new line
    encrypted_password = encrypt_password(password)
    with open(kickstart_path, "a") as file:
        file.write("\n" + encrypted_password)

def encrypt_password(password):
    try:
        # Execute sed command to generate new file with encrypted password
        process = subprocess.Popen(["sed", "-e", "'s/PLACEHOLDER/ACTUAL_VALUE/g'"], stdout=subprocess.PIPE)
        output, _ = process.communicate(input=password.encode())
        return output.decode().strip()
    except Exception as e:
        raise Exception("Command failure: " + str(e))

def main():
    kickstart_path = "path/to/kickstart/file"
    password = "your_password"

    try:
        # Modify Kickstart file with actual values and encrypted password
        modify_kickstart_file(kickstart_path, password)
    except Exception as e:
        logging.error("Error modifying Kickstart file: " + str(e))

if __name__ == "__main__":
    main()
