import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

import org.jsonwebtoken.JwtException;
import org.jsonwebtoken.Jwts;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

public class JwtValidator {

    private final ConfigLoader configLoader;
    private final JWTValidator jwtValidator;
    private final CacheStorage cacheStorage;
    private final ExternalAPIClient externalAPIClient;

    public JwtValidator(ConfigLoader configLoader, JWTValidator jwtValidator, 
                        CacheStorage cacheStorage, ExternalAPIClient externalAPIClient) {
        this.configLoader = configLoader;
        this.jwtValidator = jwtValidator;
        this.cacheStorage = cacheStorage;
        this.externalAPIClient = externalAPIClient;
    }

    public Map<String, Object> validateJwt(String jwtToken) throws IOException {
        // Load configuration
        Map<String, String> config = configLoader.loadConfig();

        // Validate JWT
        try {
            JsonNode node = Jwts.parser().setSigningKey(config.get("jwt.secret"))
                    .parseClaimsJws(jwtToken).getBody();

            // Check issuer and audience claims
            if (!node.get("iss").equals(config.get("jwt.issuer")) || 
                !node.get("aud").equals(config.get("jwt.audience"))) {
                throw new JwtException("Invalid JWT: Issuer or Audience mismatch");
            }

            // Extract user information
            String username = node.get("sub").asText();
            Map<String, Object> roles = new HashMap<>();
            for (JsonNode role : node.get("role")) {
                roles.put(role.asText(), true);
            }
            long expirationTime = node.getExpiration().getTime();

            // Store validated JWT in cache
            cacheStorage.store(jwtToken, node);

            return Map.of("username", username, "roles", roles, "expirationTime", expirationTime);

        } catch (JwtException e) {
            throw new IOException("Invalid JWT: " + e.getMessage());
        }
    }

    public boolean isRevoked(String jwtToken) throws IOException {
        try {
            // Check if token has been revoked
            return !externalAPIClient.checkRevocation(jwtToken);
        } catch (IOException e) {
            throw new IOException("Error checking token revocation: " + e.getMessage());
        }
    }

    public interface ConfigLoader {
        Map<String, String> loadConfig();
    }

    public interface JWTValidator {
        JsonNode parseClaimsJws(String jwtToken) throws JwtException;
    }

    public interface CacheStorage {
        void store(String jwtToken, JsonNode node);
    }

    public interface ExternalAPIClient {
        boolean checkRevocation(String jwtToken) throws IOException;
    }
}
