import os
import hashlib
import boto3
from google.cloud import storage
from azure.storage.blob import BlobServiceClient

class FileAggregator:
    def __init__(self, cloud_storage_service: str):
        self.cloud_storage_service = cloud_storage_service
        self.checksum_algorithm = None
        self.validator = None

        if cloud_storage_service == 'AWS':
            self.s3_client = boto3.client('s3')
        elif cloud_storage_service == 'GCS':
            self.gcs_client = storage.Client()
        elif cloud_storage_service == 'Azure':
            self.azure_blob_client = BlobServiceClient()

    def aggregate_files(self, files: list):
        for file in files:
            if not os.path.exists(file):
                continue

            with open(file, 'rb') as f:
                file_hash = hashlib.sha256(f.read()).hexdigest()
                if self.checksum_algorithm == 'SHA-256':
                    file_checksum = file_hash
                elif self.checksum_algorithm == 'MD5':
                    file_checksum = hashlib.md5(f.read()).hexdigest()

            if not self.validate_file(file, file_checksum):
                print(f"File {file} has invalid checksum")
                continue

            if self.cloud_storage_service == 'AWS':
                self.s3_client.put_object(Body=open(file, 'rb'), Bucket='your-bucket', Key=os.path.basename(file))
            elif self.cloud_storage_service == 'GCS':
                bucket = self.gcs_client.bucket('your-bucket')
                blob = bucket.blob(os.path.basename(file))
                blob.upload_from_file(file)
            elif self.cloud_storage_service == 'Azure':
                container_client = self.azure_blob_client.get_container_client('your-container')
                blob_client = container_client.get_blob_client(os.path.basename(file))
                blob_client.upload_blob(open(file, 'rb'))

    def validate_file(self, file: str, checksum: str) -> bool:
        if self.validator:
            return self.validator.validate(checksum)
        else:
            return True

class Validator:
