Here is the PHP class `FilePasswordManager` that integrates advanced password management functionalities with file-based MD5 hash calculation:

```php
class FilePasswordManager {
    private $hashedPassword;
    private $saltRoundCount = 12;
    private $characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890!@#$%^&*()_+-={}:<>?,.<~';
    private $cachedStrings = array();
    private $logFile;

    public function __construct($logFilePath) {
        $this->logFile = $logFilePath;
        $this->resetPassword();
    }

    public function generateSecureRandomString($length) {
        if (!isset($this->cachedStrings[$length])) {
            for ($i = 0; $i < pow(count($this->characterSet), $length); $i++) {
                $randomString = '';
                for ($j = 0; $j < $length; $j++) {
                    $randomString .= $this->characterSet[floor(rand() * count($this->characterSet))];
                }
                if (!isset($this->cachedStrings[$length])) {
                    $this->cachedStrings[$length] = array();
                }
                $this->cachedStrings[$length][$i] = $randomString;
            }
        }
        return $this->cachedStrings[$length][rand(0, count($this->cachedStrings[$length]) - 1)];
    }

    public function hashPassword($password) {
        if ($this->saltRoundCount < 12 || $this->saltRoundCount > 31) {
            throw new Exception('Invalid salt round count. Must be between 12 and 31.');
        }
        $hashedPassword = password_hash($password, PASSWORD_BCRYPT, array('cost' => $this->saltRoundCount));
        $this->hashedPassword = $hashedPassword;
    }

    public function checkPassword($password) {
        return password_verify($password, $this->hashedPassword);
    }

    public function validateCharacterSet($characterSet) {
        if (!preg_match('/[a-z]/', $characterSet)) {
            throw new Exception('Character set must contain at least one lowercase letter.');
        }
        if (!preg_match('/[A-Z]/', $characterSet)) {
            throw new Exception('Character set must contain at least one uppercase letter.');
        }
        if (!preg_match('/\d/', $characterSet)) {
            throw new Exception('Character set must contain at least one digit.');
        }
        if (!preg_match('/[^a-zA-Z0-9]/', $characterSet)) {
            throw new Exception('Character set must contain at least one special character.');
            return;
        }
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds < 12 || $rounds > 31) {
            throw new Exception('Invalid salt round count. Must be between 12 and 31.');
        }
        $this->saltRoundCount = $rounds;
    }

    public function resetPassword() {
        $this->hashedPassword = null;
        foreach ($this->cachedStrings as &$strings) {
            $strings = array();
        }
    }

    public function logPasswordAttempts($ipAddress, $result) {
        // File-based logging system implementation
    }

    public function calculateFileMD5($filePath) {
        if (!file_exists($filePath)) {
            throw new Exception('File not found.');
        }
        $md5 = hash_file('md5', $filePath);
        return $md5;
    }
}
