# Load configuration file
config = json.load(open('config.json'))
container_name = config['container_name']
delay_range = (int(config['min_delay']), int(config['max_delay']))
slack_webhook_url = config['slack_webhook_url']

logging.basicConfig(level=logging.INFO)

def send_slack_notification(status, message):
    try:
        client = WebClient(token=slack_webhook_url)
        client.chat_postMessage(channel='#docker-containers', text=f"{status}: {message}")
    except Exception as e:
        logging.error(f"Failed to send Slack notification: {e}")

def start_container():
    try:
        container = docker.from_env().containers.get(container_name)
        if not container.status == 'running':
            container.start()
            logging.info(f"Container started: {container_name}")
            send_slack_notification('started', f"Container '{container_name}' started")
    except Exception as e:
        logging.error(f"Failed to start container: {e}")

def stop_container():
    try:
        container = docker.from_env().containers.get(container_name)
        if not container.status == 'exited':
            container.stop()
            logging.info(f"Container stopped: {container_name}")
            send_slack_notification('stopped', f"Container '{container_name}' stopped")
    except Exception as e:
        logging.error(f"Failed to stop container: {e}")

while True:
    delay = random.randint(*delay_range)
    time.sleep(delay)

    if random.choice([True, False]):
        start_container()
    else:
        stop_container()

if __name__ == '__main__':
