// Config file for OAuth 2.0 and IDP integration
require_once 'config.php';

// Initialize session and set expiration time (1 hour)
session_start();
$_SESSION['expiration'] = time() + 3600;

class HealthcareAPI {
    // Function to authenticate user via OAuth 2.0
    public function AuthenticateUser($username, $password) {
        // Validate input parameters
        if (!isset($username) || !isset($password)) {
            http_response_code(400);
            echo json_encode(['error' => 'Invalid request']);
            return;
        }

        // Integrate with IDP for user validation
        $authResponse = $this->idpAuthenticate($username, $password);

        // Check if authentication was successful
        if (!$authResponse) {
            http_response_code(401);
            echo json_encode(['error' => 'Authentication failed']);
            return;
        }

        // Store access token in session variable with expiration mechanism
        $_SESSION['access_token'] = $authResponse['access_token'];
        $_SESSION['expiration'] = time() + 3600;

        http_response_code(200);
        echo json_encode(['message' => 'Authentication successful']);
    }

    // Function to update clinic status and last modified date
    public function UpdateClinicStatus($clinicId, $status) {
        // Validate input parameters
        if (!isset($clinicId) || !isset($status)) {
            http_response_code(400);
            echo json_encode(['error' => 'Invalid request']);
            return;
        }

        // Connect to database and update clinic status
        try {
            $db = new PDO('mysql:host=localhost;dbname=healthcare', 'username', 'password');
            $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

            $stmt = $db->prepare("UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE id = ?");
            $stmt->execute([$status, $_SERVER['REMOTE_ADDR'], date('Y-m-d H:i:s'), $clinicId]);

            http_response_code(200);
            echo json_encode(['message' => 'Clinic status updated successfully']);
        } catch (PDOException $e) {
            http_response_code(500);
            echo json_encode(['error' => 'Database error: ' . $e->getMessage()]);
        }
    }

    // Function to calculate file hash and support resumable uploads
    public function CalculateFileHash($file) {
        // Initialize file hash calculation
        $hash = hash_init('sha256');

        // Read file in chunks for memory-efficient processing
        $chunkSize = 1024 * 1024; // 1 MB chunk size
        $fileStream = fopen($file, 'rb');
        while (!feof($fileStream)) {
            $chunk = fread($fileStream, $chunkSize);
            hash_update($hash, $chunk);
        }
        fclose($fileStream);

        // Combine private key and certificate into a single PEM file
        $pemFile = 'path/to/pem/file.pem';
        file_put_contents($pemFile, hash_final($hash));

        http_response_code(200);
        echo json_encode(['message' => 'File hash calculation successful']);
    }
}

// Initialize API instance
$api = new HealthcareAPI();

// Process API requests
if (isset($_GET['action'])) {
    switch ($_GET['action']) {
        case 'authenticate':
            $api->AuthenticateUser();
            break;
        case 'update_clinic_status':
            $api->UpdateClinicStatus();
            break;
        case 'calculate_file_hash':
            $api->CalculateFileHash();
            break;
        default:
            http_response_code(400);
            echo json_encode(['error' => 'Invalid request']);
    }
}

