Here is the C code for the semaphore management system:

```c
#include <semaphore.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a struct to hold the data and semaphores for each named semaphore
typedef struct {
    sem_t *mutex;
    int value;
} SemaphoreData;

// Function to create a new named semaphore with the given name and initial value
SemaphoreData* create_semaphore(const char* name, int initial_value) {
    // Create the semaphore using the named semaphore system call
    SemaphoreData* data = (SemaphoreData*)mmap(NULL, sizeof(SemaphoreData), PROT_READ | PROT_WRITE,
        MAP_SHARED | MAP_ANONYMOUS, -1, 0);

    if (!data) {
        return NULL;
    }

    // Initialize the semaphore with the given initial value
    sem_init(&data->mutex, 1, initial_value);
    data->value = initial_value;

    return data;
}

// Function to delete a named semaphore and release its resources
void destroy_semaphore(SemaphoreData* data) {
    if (!data) {
        return;
    }

    // Destroy the semaphore
    sem_destroy(&data->mutex);
    munmap((void*)data, sizeof(SemaphoreData));
}

// Function to increment the value of a named semaphore
int increment_semaphore(SemaphoreData* data) {
    if (!data) {
        return -1;
    }

    // Decrement and then increment to ensure thread safety
    int result = sem_getvalue(&data->mutex);
    sem_wait(&data->mutex);
    result++;
    sem_post(&data->mutex);

    return result;
}

// Function to decrement the value of a named semaphore
int decrement_semaphore(SemaphoreData* data) {
    if (!data) {
        return -1;
    }

    // Decrement and then increment to ensure thread safety
    int result = sem_getvalue(&data->mutex);
    sem_wait(&data->mutex);
    result--;
    sem_post(&data->mutex);

    return result;
}

// Function to get the value of a named semaphore
int get_semaphore_value(SemaphoreData* data) {
    if (!data) {
        return -1;
    }

    int result = sem_getvalue(&data->mutex);
    return result;
}
```

And here is the JavaScript code for the `asyncArrayReduce` function:

```javascript
async function asyncArrayReduce(arr, initialValue, callbackFunction) {
    // Define a semaphore to control concurrency level
    let semaphore = 0;

    try {
        // Use a Promise to handle the reduction process
        return new Promise((resolve, reject) => {
            (async () => {
                // Initialize accumulator and index
                let accumulatedValue = initialValue;
                let index = 0;

                while (index < arr.length) {
                    try {
                        // Wait for semaphore to be available before proceeding
                        await new Promise(resolve => setTimeout(() => resolve(semaphore++), 10));

                        // Perform the reduction operation with the callback function
                        accumulatedValue = await callbackFunction(accumulatedValue, arr[index]);

                        index++;

                        // If an error occurs during the reduction process, reject the promise
                    } catch (error) {
                        reject(error);
                    }
                }

                // Release semaphore and report progress
                setTimeout(() => resolve(semaphore--), 10);

                return accumulatedValue;
            })();
        });
    } catch (error) {
        throw error;
    }
}
