import logging
from typing import List, Dict
import requests
import time
import os
import hashlib

class Script:
    def __init__(self, id: str, src: str, fallback_content: str):
        self.id = id
        self.src = src
        self.fallback_content = fallback_content

def get_script_tag(script: Script, versioned_src: str) -> str:
    tag = f"<script id='{script.id}' src='{versioned_src}'></script>"
    return tag

def get_fallback_tag(script: Script, script_type: str) -> str:
    if script_type == "javascript":
        fallback_tag = f"<script>window.__fallback_js_content = '{script.fallback_content}';</script>"
    elif script_type == "image":
        fallback_tag = f"<img src='{script.fallback_content}' alt='{script.id}-Fallback'>"
    elif script_type == "audio":
        fallback_tag = f"<audio controls><source src='{script.fallback_content}' type='audio/{os.path.splitext(script.fallback_content)[1][1:]}'></audio>"
    else:
        fallback_tag = f"<div id='{script.id}-Fallback'>{script.fallback_content}</div>"
    return fallback_tag

def get_cache_key(versioned_src: str) -> str:
    cache_key = hashlib.sha256(versioned_src.encode()).hexdigest()
    return cache_key

def load_script(script: Script, cache_dir: str) -> Dict[str, str]:
    versioned_src = f"{script.src}?v={int(time.time())}"
    cache_file_path = os.path.join(cache_dir, get_cache_key(versioned_src))

    if not os.path.exists(cache_file_path):
        try:
            response = requests.get(script.src)
            if response.status_code == 200:
                with open(cache_file_path, "wb") as f:
                    f.write(response.content)
        except Exception as e:
            logging.error(f"Failed to load script {script.id}: {str(e)}")

    cache_content = None
    try:
        with open(cache_file_path, "rb") as f:
            cache_content = f.read()
    except FileNotFoundError:
        pass

    if cache_content is not None:
        return {"tag": get_script_tag(script, versioned_src), "content": cache_content.decode()}
    else:
        return {"tag": get_script_tag(script, versioned_src), "content": script.fallback_content}

def fetch_and_load_scripts(scripts: List[Script], cache_dir: str) -> str:
    html = ""
    for script in scripts:
        result = load_script(script, cache_dir)
        if result["content"] is not None:
            html += result["tag"]
        else:
            fallback_type = "javascript"  # default to js
            if script.src.lower().endswith(".jpg") or script.src.lower().endswith(".png"):
                fallback_type = "image"
            elif script.src.lower().endswith(".mp3") or script.src.lower().endswith(".ogg"):
                fallback_type = "audio"
            html += get_fallback_tag(script, fallback_type)

    if not scripts:
        return ""

    return f"<footer>{html}</footer>"
