    public async Task<decimal> ProcessAsync(XPathNodeIterator nodes, decimal initialValue, 
                                            Dictionary<string, string> options)
    {
        int parallelism = 5; // default value for parallelism
        int throttleRate = 10; // default value for throttling rate

        if (options.ContainsKey("parallelism"))
            parallelism = int.Parse(options["parallelism"]);
        if (options.ContainsKey("throttleRate"))
            throttleRate = int.Parse(options["throttleRate"]);

        decimal accumulator = initialValue;
        Dictionary<string, string> cache = new Dictionary<string, string>();

        await Task.Run(() =>
        {
            foreach (XPathNodeIterator node in nodes)
            {
                if (!node.MoveNext())
                    continue;

                string path = GetPath(node);

                if (cache.ContainsKey(path))
                {
                    // use cached result
                    accumulator += decimal.Parse(cache[path]);
                    continue;
                }

                try
                {
                    string data = ExtractData(node);
                    cache.Add(path, data);

                    Task task = ThrottledApiCall(data);
                    await task;

                    accumulator += GetAccumulatorValue(data);
                }
                catch (Exception ex)
                {
                    // handle exception gracefully
                    Console.WriteLine("Error: " + ex.Message);
                    return;
                }

                ReportProgress(accumulator, path);
            }
        });

        return accumulator;
    }

    string GetPath(XPathNodeIterator node)
    {
        StringBuilder path = new StringBuilder();
        while (node.MoveNext())
        {
            path.Append(node.Current.Name).Append("/");
        }
        return path.ToString().TrimEnd('/');
