function asyncStreamReducer(stream, { initialValue = 0, accumulatorFunc = (acc, val) => acc + val, throttleMs = 1000, cacheSize = 10, reportProgress = false, timeoutSecs = 5 } = {}) {
  const throttledStream = stream
    .throttle(throttleMs)
    .on('data', (chunk) => {
      const promises = chunk.map((val) =>
        Promise.race([
          simulateApiCall(val).timeout(timeoutSecs * 1000),
          setTimeout(() => {
            console.log(`Timeout for ${val} after ${timeoutSecs} seconds`);
          }, timeoutSecs * 1000)
        ])
      );

      if (reportProgress) {
        console.log(`Processing chunk of size ${chunk.length}`);
      }

      Promise.all(promises).then((results) => {
        const reducedChunk = accumulatorFunc(initialValue, results.reduce((acc, val) => acc + val, 0));
        cacheSize > 0 && cache.push(reducedChunk);

        if (reportProgress) {
          console.log(`Chunk processed: ${reducedChunk}`);
        }
      });
    })
    .on('error', (err) => {
      console.error(err);
    })
    .on('end', () => {
      if (cacheSize > 0 && cache.length > 0) {
        const finalResult = accumulatorFunc(initialValue, cache.reduce((acc, val) => acc + val, 0));
        return [finalResult];
      }
      return [];
    });

  let cache = [];
  let paused = false;

  async function* asyncReduce() {
    for await (const chunk of throttledStream) {
      while (paused) {
        yield;
      }

      if (!chunk.length) continue;

      const promises = chunk.map((val) =>
        Promise.race([
          simulateApiCall(val).timeout(timeoutSecs * 1000),
          setTimeout(() => {
            console.log(`Timeout for ${val} after ${timeoutSecs} seconds`);
          }, timeoutSecs * 1000)
        ])
      );

      if (reportProgress) {
        console.log(`Processing chunk of size ${chunk.length}`);
      }

      try {
        const results = await Promise.all(promises);
        yield accumulatorFunc(initialValue, results.reduce((acc, val) => acc + val, 0));
      } catch (err) {
        console.error(err);
      }
    }
  }

  return asyncReduce();
}

async function simulateApiCall(val) {
  // Your API call logic here
  await new Promise((resolve) => setTimeout(() => resolve({ data: val }), 2000));
  return { data: val };
}
