import subprocess
import os
import hashlib

class KickstartConfigUpdater:
    def __init__(self, encryption_service):
        self.encryption_service = encryption_service

    def update_config(self, kickstart_file_path, user_id, new_value):
        try:
            if not os.path.exists(kickstart_file_path):
                raise FileNotFoundError("Kickstart file not found")

            with open(kickstart_file_path, 'r') as f:
                kickstart_config = f.read()

            # Replace placeholders with actual values
            updated_kickstart_config = kickstart_config.replace('<user_id>', user_id).replace('<value>', new_value)

            # Append encrypted password to the end of the file
            encrypted_password = self.encryption_service.encrypt(str(new_value))
            updated_kickstart_config += f'\n{encrypted_password}'

            with open(kickstart_file_path, 'w') as f:
                f.write(updated_kickstart_config)

            # Validate integrity of appended password
            if not self.validate_password_hash(encrypted_password):
                raise Exception("Password hash validation failed")

        except subprocess.CalledProcessError as e:
            print(f"Command failure: {e}")
            raise
        except FileNotFoundError as e:
            print(f"Kickstart file not found: {e}")
            raise
        except Exception as e:
            print(f"Error updating config: {e}")
            raise

    def validate_password_hash(self, encrypted_password):
        password_hash_file_path = 'password_hash.txt'
        if not os.path.exists(password_hash_file_path):
            return True

        with open(password_hash_file_path, 'r') as f:
            expected_hash = f.read()

        return hashlib.sha256(encrypted_password.encode()).hexdigest() == expected_hash
