            int compressLevelInt = Integer.parseInt(compressionLevel);

            // Check if input directory exists
            Path dirPath = Paths.get(inputDir);
            if (!Files.exists(dirPath)) {
                System.out.println("Error: Input directory does not exist.");
                return;
            }

            // Delete existing ZIP file
            try (BufferedWriter writer = Files.newBufferedWriter(Paths.get(outputZip), StandardCharsets.UTF_8)) {
                writer.write("");
                Files.deleteIfExists(Paths.get(outputZip));
            } catch (IOException e) {
                System.out.println("Error deleting ZIP file: " + e.getMessage());
                return;
            }

            // Set up logger
            Logger logger = Logger.getLogger(ZipDirectory.class.getName());
            Handler handler = new ConsoleHandler();
            handler.setLevel(Level.INFO);
            logger.addHandler(handler);

            while (!zipCreated) {
                try {
                    // Execute command-line utility to compress directory
                    ProcessBuilder builder = new ProcessBuilder("zip", "-r", "-9", outputZip, inputDir);
                    Process process = builder.start();

                    // Monitor compression progress
                    BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                    String line;
                    while ((line = reader.readLine()) != null) {
                        System.out.println(line);
                    }

                    // Wait for command to complete
                    int exitValue = process.waitFor();
                    if (exitValue == 0) {
                        zipCreated = true;
                    } else {
                        logger.log(Level.SEVERE, "Error compressing directory: " + new String(process.getErrorStream().readAllBytes(), StandardCharsets.UTF_8));
                    }
                } catch (IOException | InterruptedException e) {
                    logger.log(Level.SEVERE, "Error compressing directory: " + e.getMessage());
                    if (retryCount < 3) {
                        retryCount++;
                        System.out.println("Compression failed. Retrying in 5 seconds...");
                        Thread.sleep(5000);
                    } else {
                        zipCreated = false;
                    }
                }
            }

        } catch (NumberFormatException e) {
            System.out.println("Error: Invalid compression level.");
        } catch (IOException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }

    private static String getArgument(String argName, String defaultValue) {
        for (String arg : new String[]{argName}) {
            if (System.getProperty(arg) != null) {
                return System.getProperty(arg);
            }
        }
        return defaultValue;
    }
}

