using System.Net.Http;
using System.Text;
using Newtonsoft.Json;

public class ApiProcessor
{
    private readonly HttpClient _httpClient = new HttpClient();
    private readonly object _cacheLock = new object();
    private readonly Dictionary<string, DataTableReader> _cache = new Dictionary<string, DataTableReader>();

    public async Task<DataTableReader> ProcessByteArrayAsync(byte[] data)
    {
        try
        {
            // Serialize byte array to JSON string
            var json = JsonConvert.SerializeObject(data);

            // Add caching mechanism
            if (_cache.ContainsKey(json))
                return _cache[json];

            // Send JSON string to API for processing
            using (var requestStream = await _httpClient.PostAsync("api endpoint", new StringContent(json, Encoding.UTF8, "application/json")))
            {
                if (!requestStream.IsSuccessStatusCode)
                    throw new HttpRequestException($"API returned {requestStream.StatusCode} status code");

                // Read response from API as JSON string
                using (var responseStream = await requestStream.Content.ReadAsStreamAsync())
                {
                    var jsonData = await JsonSerializer.SerializeAsync(responseStream);

                    // Deserialize JSON string to DataTableReader object
                    var reader = JsonConvert.DeserializeObject<DataTableReader>(jsonData);

                    // Add caching mechanism
                    lock (_cacheLock)
                        _cache.Add(json, reader);

                    return reader;
                }
            }
        }
        catch (HttpRequestException ex)
        {
            throw new Exception("Failed to process byte array", ex);
        }
        catch (JsonSerializationException ex)
        {
            throw new Exception("Failed to deserialize API response", ex);
        }
    }
}
