EVP_CIPHER_CTX* choose_cipher(int mode) {
    EVP_CIPHER_CTX* ctx = NULL;
    const EVP_CIPHER* cipher = NULL;

    switch (mode) {
        case 0:
            // ECB mode
            cipher = EVP_des_ecb();
            break;
        case 1:
            // EDE mode
            cipher = EVP_des_ede();
            break;
        case 2:
            // EDE3 mode
            cipher = EVP_des_ede3();
            break;
        case 3:
            // CFB mode with null encryption for testing purposes
            cipher = EVP_des_cfb();
            break;
        default:
            // Invalid mode, return NULL
            return NULL;
    }

    ctx = EVP_CIPHER_CTX_new();
    EVP_CIPHER_CTX_set_cipher(ctx, cipher);
    return ctx;
}

int choose_cfb_iv(EVP_CIPHER_CTX* ctx, unsigned char iv[], int iv_len) {
    if (iv_len == 8) {
        // Fixed-length IV for CFB mode
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_CFB_IV_LEN, 8, NULL);
    } else {
        // Variable-length IV for CFB mode
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_CFB_IV_LEN, iv_len, NULL);
    }
    return 1;
}

