using System;
using System.Xml.XPath;
using System.IO;
using System.Collections.Generic;

public class XmlParser
{
    private readonly Dictionary<string, XPathDocument> _cache = new Dictionary<string, XPathDocument>();
    private readonly IConfigLoader _configLoader;
    private readonly ICachedStorage _cachedStorage;

    public XmlParser(IConfigLoader configLoader, ICachedStorage cachedStorage)
    {
        _configLoader = configLoader;
        _cachedStorage = cachedStorage;
    }

    public XmlNode GetElement(string documentName, string elementName)
    {
        try
        {
            if (_cache.TryGetValue(documentName, out XPathDocument cacheEntry))
            {
                return FindElement(cacheEntry, elementName);
            }
            else
            {
                string xmlPath = _configLoader.GetXmlFilePath(documentName);
                if (string.IsNullOrEmpty(xmlPath))
                {
                    throw new FileNotFoundException("XML file not found", documentName);
                }

                XPathDocument doc = new XPathDocument(xmlPath);
                _cache[documentName] = doc;
                return FindElement(doc, elementName);
            }
        }
        catch (XPathException ex)
        {
            throw new XmlParserException($"Invalid XPath query: {ex.Message}", ex);
        }
        catch (FileNotFoundException ex)
        {
            throw new XmlParserException("XML file not found", ex);
        }
        catch (Exception ex)
        {
            throw new XmlParserException("An error occurred while parsing the XML document", ex);
        }
    }

    private XmlNode FindElement(XPathDocument doc, string elementName)
    {
        try
        {
            XPathNodeIterator nodes = doc.SelectSingleNode($"//{elementName}", null);
            if (nodes == null || !nodes.MoveNext())
            {
                throw new XmlParserException($"No elements found with name '{elementName}'", null);
            }
            return nodes.Current;
        }
        catch (XPathException ex)
        {
            throw new XmlParserException($"Invalid XPath query: {ex.Message}", ex);
        }
    }

    public void ClearCache()
    {
        _cache.Clear();
        _cachedStorage.Clear();
    }
}

public class ConfigLoader : IConfigLoader
{
    private readonly string _configFilePath;

    public ConfigLoader(string configFilePath)
    {
        _configFilePath = configFilePath;
    }

    public string GetXmlFilePath(string documentName)
    {
        // Implement your configuration file parsing logic here.
        return "path/to/your/xml/file.xml";
    }
}

public class CachedStorage : ICachedStorage
{
    private readonly Dictionary<string, XPathDocument> _cache = new Dictionary<string, XPathDocument>();

    public void Clear()
    {
        _cache.Clear();
    }

    // Implement your caching logic here.
}

public interface IConfigLoader
{
    string GetXmlFilePath(string documentName);
}

public interface ICachedStorage
