                print(f"Error: {e}")

    def process_url(self, url: str) -> Dict[str, any]:
        # Fetch HTTP headers and content length from URL
        resp = requests.head(url, timeout=10)
        if resp.status_code == 200:
            return {"headers": dict(resp.headers), "content_length": int(resp.headers.get("Content-Length", -1))}
        else:
            return {}

    def validate_url(self, url: str) -> bool:
        # Validate the URL to ensure it is well-formed and within acceptable length limits
        try:
            result = urlparse(url)
            if not (result.scheme in ["http", "https"] and result.netloc):
                return False
            return True
        except ValueError:
            return False

    def cache_response(self, url: str, response: Dict[str, any]) -> None:
        # Cache the response for future reference
        with self.lock:
            if len(self.cache) > 1000:  # Adjust this value based on your needs
                least_recently_used = min((key for key in self.cache), key=lambda k: self.cache[k]["last_accessed"])
                del self.cache[least_recently_used]
            response["last_accessed"] = int(time.time())
            self.cache[url] = response

    def get_response_from_cache(self, url: str) -> Dict[str, any]:
        # Retrieve the cached response
        with self.lock:
            return self.cache.get(url)

    def fetch_and_cache(self, url: str) -> None:
        # Fetch and cache the HTTP headers and content length from URL
        try:
            response = self.process_url(url)
            if response:
                self.cache_response(url, response)
        except Exception as e:
            print(f"Error fetching {url}: {e}")

    def fetch_and_cache_all(self) -> None:
        # Fetch and cache all URLs in the queue
        while not self.url_queue.empty():
            url = self.url_queue.get()
            self.fetch_and_cache(url)

# Example usage:
if __name__ == "__main__":
    service = HTTPService()
    service.configure()
    service.start()
