const bluebird = require('bluebird');
const logger = require('pino')();
const providers = [
  {
    name: 'AWS S3',
    url: 'https://s3.amazonaws.com',
    auth: (bucket) => ({
      accessKeyId: process.env.AWS_ACCESS_KEY_ID,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
    }),
  },
  {
    name: 'Google Cloud Storage',
    url: 'https://storage.cloud.google.com',
    auth: (bucket) => ({
      keyFile: 'path/to/credentials.json',
    }),
  },
];

const getBestProvider = async (criteria) => {
  const providersWithCosts = await Promise.all(
    providers.map((provider) =>
      provider.name === 'AWS S3'
        ? {
            name: provider.name,
            cost: await getAWS3Cost(),
          }
        : { name: provider.name, cost: await getGCSPrice() },
    ),
  );
  const bestProvider = providersWithCosts.reduce((acc, current) => {
    if (!acc || current.cost < acc.cost) return current;
    return acc;
  }, null);
  return bestProvider;
};

const uploadFile = async (file, provider) => {
  const { url, auth } = provider;
  const bucketName = 'my-bucket';
  const fileKey = 'path/to/file.txt';

  try {
    const s3 = await getSignedUrl(url, auth, bucketName, fileKey);
    const response = await s3.putObject({ Bucket: bucketName, Key: fileKey, Body: file });
    return `${url}/${bucketName}/${fileKey}`;
  } catch (error) {
    logger.error(`Error uploading file: ${error}`);
    throw error;
  }
};

const getSignedUrl = async (url, auth, bucket, key) => {
  const s3 = bluebird.promisifyAll(require('aws-sdk'));
  await new Promise((resolve) =>
    s3.config.update({
      accessKeyId: auth.accessKeyId,
      secretAccessKey: auth.secretAccessKey,
    });
  );
  return s3.S3.getSignedUrl('putObject', {
    Bucket: bucket,
    Key: key,
    Expires: 3600, // 1 hour
  }).promise();
};

const upload = async (file) => {
  try {
    const bestProvider = await getBestProvider(['cost']);
    return await uploadFile(file, bestProvider);
  } catch (error) {
    logger.error(`Error uploading file: ${error}`);
    throw error;
  }
};

module.exports = { upload };
