Here is the Java method that establishes a connection to a remote address using a non-blocking SocketChannel and handles multiple concurrent connections efficiently:

```java
import java.io.IOException;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;

public class AsyncSocketHandler {
    private static final int POOL_SIZE = 10;
    private static final int READ_BUFFER_SIZE = 1024;
    private Selector selector;
    private SocketChannel[] socketChannels;

    public AsyncSocketHandler() throws IOException {
        selector = Selector.open();
        socketChannels = new SocketChannel[POOL_SIZE];
    }

    public void handleConnection(String remoteAddress, int port) throws IOException {
        for (int i = 0; i < POOL_SIZE; i++) {
            if (socketChannels[i] == null || !socketChannels[i].isConnected()) {
                socketChannels[i] = SocketChannel.open();
                socketChannels[i].configureBlocking(false);
                socketChannels[i].bind(null);
                break;
            }
        }

        if (socketChannels[i] != null) {
            socketChannels[i].connect(new InetSocketAddress(remoteAddress, port));
            selector.wakeup();
            selector.select();
        }
    }

    public void readData(SocketChannel channel) throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(READ_BUFFER_SIZE);
        while (channel.read(buffer) > 0) {
            // Process the received data
            buffer.flip();
            // ...
            buffer.clear();
        }
    }
}
