void insertString(std::forward_list<std::string>& list, const std::string& str1, const std::string& str2) {
    auto it = list.begin();
    while (it != list.end()) {
        if (*it == str1) {
            list.insert_after(it++, str2);
            return;
        }
        ++it;
    }
    list.append(str2);
}
