using System;
using System.Threading.Tasks;
using System.Data.SqlClient;

namespace ConfigManager
{
    public class ConfigurationUpdater
    {
        private readonly ILogger _logger;
        private readonly IVCS _vcs;
        private readonly IBitmapCache _bitmapCache;
        private readonly Dictionary<string, ConnectionString> _databaseConnections;

        public async Task UpdateConfigurationAsync(string userId, string configName, string value)
        {
            try
            {
                // Retrieve the user-specific configuration from the distributed database system
                var config = await GetConfigFromDatabaseAsync(userId, configName);

                if (config != null)
                {
                    // Update the existing configuration with the new value
                    config.Value = value;
                }
                else
                {
                    // Create a new configuration entry if it doesn't exist
                    config = new ConfigurationEntry(userId, configName, value);
                    await SaveConfigToDatabaseAsync(config);
                }

                // Cache the updated configuration for faster access
                _bitmapCache.Set(configName, config.Value);

                // Integrate with external version control API to track changes
                await _vcs.TrackChangeAsync(userId, configName, value);

                // Log the update operation
                _logger.LogInformation($"Updated configuration '{configName}' for user '{userId}' to '{value}'.");
            }
            catch (Exception ex)
            {
                // Handle errors and exceptions gracefully
                _logger.LogError(ex, "Error updating configuration");
            }
        }

        private async Task<ConfigurationEntry> GetConfigFromDatabaseAsync(string userId, string configName)
        {
            using (var connection = new SqlConnection(_databaseConnections[userId]))
            {
                await connection.OpenAsync();

                var command = new SqlCommand("SELECT * FROM configurations WHERE user_id = @user_id AND name = @name", connection);
                command.Parameters.AddWithValue("@user_id", userId);
                command.Parameters.AddWithValue("@name", configName);

                using (var reader = command.ExecuteReader())
                {
                    if (reader.Read())
                    {
                        return new ConfigurationEntry(userId, configName, reader["value"].ToString());
                    }
                }
            }

            return null;
        }

        private async Task SaveConfigToDatabaseAsync(ConfigurationEntry config)
        {
            using (var connection = new SqlConnection(_databaseConnections[config.UserId]))
            {
                await connection.OpenAsync();

                var command = new SqlCommand("INSERT INTO configurations VALUES (@user_id, @name, @value)", connection);
                command.Parameters.AddWithValue("@user_id", config.UserId);
                command.Parameters.AddWithValue("@name", config.Name);
                command.Parameters.AddWithValue("@value", config.Value);

                await command.ExecuteNonQueryAsync();
            }
        }
    }

    public class ConfigurationEntry
    {
        public string UserId { get; set; }
        public string Name { get; set; }
        public string Value { get; set; }

        public ConfigurationEntry(string userId, string name, string value)
        {
            UserId = userId;
            Name = name;
            Value = value;
        }
    }
}

