class LogProcessor:
    def __init__(self):
        self.config = configparser.ConfigParser()
        self.config.read("config.ini")
        self.api_key = self.config["API"]["key"]
        self.api_endpoint = self.config["API"]["endpoint"]

    def process_log_file(self, filename):
        with gzip.open(filename, "rt") as f:
            for line in f:
                # parse each line to extract relevant HTTP request information
                ip_address, request_time, response_status_code = parse_line(line)

                # aggregate data to calculate average response time
                if not hasattr(self, "ip_to_response_times"):
                    self.ip_to_response_times = {}
                if ip_address not in self.ip_to_response_times:
                    self.ip_to_response_times[ip_address] = []
                self.ip_to_response_times[ip_address].append(int(response_status_code))

        for ip, response_times in self.ip_to_response_times.items():
            # calculate average response time
            average_response_time = sum(response_times) / len(response_times)

            # report aggregated statistics to API
            requests.post(self.api_endpoint, json={"ip": ip, "average_response_time": average_response_time}, headers={"API-Key": self.api_key})

    def detect_suspicious_patterns(self):
