class FileUploader:
    def __init__(self):
        self.max_file_size = 1024 * 1024 * 100  # 100MB
        self.bucket_permissions = {"admin": True, "user": False}

    async def upload_file(self, file_name: str, file_size: int, metadata: Dict[str, Any]) -> Dict[str, Any]:
        if not file_name or file_size > self.max_file_size:
            return {"error": "Invalid file name or size"}

        if "user" in self.bucket_permissions and not self.bucket_permissions["user"]:
            return {"error": "User does not have permissions to upload files"}

        try:
            # Validate metadata
            if not metadata.get("type") or not metadata.get("description"):
                return {"error": "Invalid metadata"}

            # Start background task for file upload
            loop = asyncio.get_event_loop()
            task = loop.run_in_executor(None, self.upload_file_async, file_name, file_size, metadata)
            result = await task

            if result["success"]:
                # Notify connected clients via WebSocket
                await self.notify_clients(file_name)

            return result
        except Exception as e:
            return {"error": str(e)}

    async def upload_file_async(self, file_name: str, file_size: int, metadata: Dict[str, Any]) -> Dict[str, Any]:
        try:
            # Start exponential backoff and retry logic for file upload
            attempts = 0
            while attempts < 3:
                try:
                    await asyncio.sleep(2 ** attempts)
                    await self.cloud_storage_upload(file_name, file_size, metadata)
                    return {"success": True}
                except Exception as e:
                    attempts += 1

            return {"error": "File upload failed"}
        finally:
            # Close the cloud storage connection
            pass

    async def notify_clients(self, file_name: str):
        # Send WebSocket notification to all connected clients
        pass

    async def cloud_storage_upload(self, file_name: str, file_size: int, metadata: Dict[str, Any]):
