import csv
import sqlite3
import threading
import time

class Semaphore:
    def __init__(self):
        self._value = 0
        self._mutex = threading.Lock()
        self._cv = threading.Condition()

    def acquire(self, value=1):
        with self._mutex:
            while self._value < value:
                self._cv.wait_for(lambda: self._value >= value)
            self._value -= 1

    def release(self):
        with self._mutex:
            self._value += 1
            self._cv.notify_all()

class CSVProcessor:
    def __init__(self, db_file='data.db'):
        self._db = sqlite3.connect(db_file)
        self._cursor = self._db.cursor()
        self._cache = {}
        self._semaphore = Semaphore()

    def process(self, query):
        if 'field1' in query and 'field2' in query:
            result = self._cursor.execute('SELECT * FROM table WHERE field1=? AND field2=?', (query['field1'], query['field2'])).fetchall()
            for row in result:
                yield row
        else:
            raise ValueError('Invalid query')

    def close(self):
        self._db.close()

