class Semaphore {
  constructor() {
    this.semaphoreValue = 0;
    this.mutex = new Map();
    this.conditionVariable = new Promise((resolve, reject) => {
      this.resolve = resolve;
      this.reject = reject;
    });
  }

  acquire(value = 1) {
    return new Promise((resolve, reject) => {
      this.mutex.set(this.semaphoreValue++, () => {
        if (this.semaphoreValue >= value) {
          this.conditionVariable.resolve();
        } else {
          this.conditionVariable.reject(new Error("Semaphore value is less than the required value"));
        }
      });
    });
  }

  release() {
    return new Promise((resolve, reject) => {
      const callback = this.mutex.get(this.semaphoreValue - 1);
      if (callback) {
        callback();
        this.mutex.delete(this.semaphoreValue - 1);
      } else {
        this.conditionVariable.reject(new Error("Semaphore value is out of range"));
      }
    });
  }
}

class AsyncArrayReduce {
  async arrayReduce(arr, initialValue, callback) {
    const semaphore = new Semaphore();
    let accumulatedValue = initialValue;

    for (let num of arr) {
      try {
        const awaitable = await callback(num, accumulatedValue);
        if (awaitable && typeof awaitable === "object" && "value" in awaitable) {
          accumulatedValue = awaitable.value;
        } else {
          accumulatedValue = awaitable;
        }
        await semaphore.acquire(5);
      } catch (e) {
        console.error(`Error: ${e}`);
        return null;
      } finally {
        await semaphore.release();
      }
    }

    return accumulatedValue;
  }

  async arrayReduceWithThrottling(arr, initialValue, callback) {
    const throttleValue = 5;
    let throttleSemaphore = new Semaphore();

    for (let num of arr) {
      try {
        const awaitable = await callback(num, initialValue);
        if (awaitable && typeof awaitable === "object" && "value" in awaitable) {
          initialValue = awaitable.value;
        } else {
          initialValue = awaitable;
        }
        await throttleSemaphore.acquire(throttleValue);
        await new Promise((resolve, reject) => setTimeout(() => resolve(), 10));
        await throttleSemaphore.release();
      } catch (e) {
        console.error(`Error: ${e}`);
        return null;
      }
    }

    return initialValue;
  }

  async arrayReduceWithCaching(arr, initialValue, callback) {
    const cache = {};

    for (let num of arr) {
      try {
        const awaitable = await callback(num, initialValue);
        if (awaitable && typeof awaitable === "object" && "value" in awaitable) {
          initialValue = awaitable.value;
        } else {
          initialValue = awaitable;
        }
        cache[num] = initialValue;
      } catch (e) {
        console.error(`Error: ${e}`);
        return null;
      }
    }

    return cache;
  }
}

// Example usage:
async function main() {
  const asyncArrayReduce = new AsyncArrayReduce();
  let result = await asyncArrayReduce.arrayReduce([1, 2, 3], 0, (num, initialValue) => num * 2);
  console.log(result); // Output: 6

  let cachedResult = await asyncArrayReduce.arrayReduceWithCaching([1, 2, 3], 0, (num, initialValue) => num * 2);
  console.log(cachedResult); // Output: { 1: 2, 2: 4, 3: 6 }
}

main();
