using System.Xml;
using System.Xml.Xsl;

public class XmlParser : IDisposable
{
    private readonly Dictionary<string, XPathNavigator> _cache = new Dictionary<string, XPathNavigator>();
    private readonly object _lock = new object();
    private readonly ILogger _logger;
    private readonly XsltSettings _xsltSettings;

    public XmlParser(ILogger logger, XsltSettings xsltSettings)
    {
        _logger = logger;
        _xsltSettings = xsltSettings;
    }

    public void Dispose()
    {
        _cache.Clear();
    }

    public string GetSingleElementValue(string xpathExpression)
    {
        if (_cache.TryGetValue(xpathExpression, out var navigator))
        {
            return navigator.SelectSingleNode(string.Empty).Value as string;
        }

        try
        {
            using (var stream = new MemoryStream())
            {
                var writer = new XmlTextWriter(stream);
                // Load your XML file into the stream
                writer.WriteStartDocument();
                // ...
                writer.WriteEndDocument();
                writer.Flush();

                navigator = XPathDocument.Load(stream.ToArray()).CreateNavigator();
                _cache.Add(xpathExpression, navigator);

                return navigator.SelectSingleNode(string.Empty).Value as string;
            }
        }
        catch (Exception ex)
        {
            if (_logger.IsEnabled(LogLevel.Error))
            {
                _logger.LogError(ex, "Failed to get single element value");
            }

            throw new FileNotFoundException("No element found", xpathExpression);
        }
    }

    public List<string> GetElementsValues(string xpathExpression)
    {
        if (_cache.TryGetValue(xpathExpression, out var navigator))
        {
            return navigator.Select(string.Empty).Cast<XmlNode>().Select(x => x.Value as string).ToList();
        }

        try
        {
            using (var stream = new MemoryStream())
            {
                var writer = new XmlTextWriter(stream);
                // Load your XML file into the stream
                writer.WriteStartDocument();
                // ...
                writer.WriteEndDocument();
                writer.Flush();

                navigator = XPathDocument.Load(stream.ToArray()).CreateNavigator();
                _cache.Add(xpathExpression, navigator);

                return navigator.Select(string.Empty).Cast<XmlNode>().Select(x => x.Value as string).ToList();
            }
        }
        catch (Exception ex)
        {
            if (_logger.IsEnabled(LogLevel.Warning))
            {
                _logger.LogWarning(ex, "Failed to get elements values");
            }

            return new List<string>();
        }
    }

    public Dictionary<string, string> ExtractAttributes(string xpathExpression)
    {
        if (_cache.TryGetValue(xpathExpression, out var navigator))
        {
            return navigator.Select(string.Empty).Cast<XmlNode>().ToDictionary(x => x.Name, x => x.GetAttribute("your_attribute_name") as string);
        }

        try
        {
            using (var stream = new MemoryStream())
            {
                var writer = new XmlTextWriter(stream);
                // Load your XML file into the stream
                writer.WriteStartDocument();
                // ...
                writer.WriteEndDocument();
                writer.Flush();

                navigator = XPathDocument.Load(stream.ToArray()).CreateNavigator();
                _cache.Add(xpathExpression, navigator);

                return navigator.Select(string.Empty).Cast<XmlNode>().ToDictionary(x => x.Name, x => x.GetAttribute("your_attribute_name") as string);
            }
        }
        catch (Exception ex)
        {
            if (_logger.IsEnabled(LogLevel.Warning))
            {
                _logger.LogWarning(ex, "Failed to extract attributes");
            }

            return new Dictionary<string, string>();
        }
    }

    public void ManipulateTextNodes(string xpathExpression, Func<string, string> transformation)
    {
        if (_cache.TryGetValue(xpathExpression, out var navigator))
        {
            foreach (var node in navigator.Select(string.Empty).Cast<XmlNode>())
            {
                // Apply the transformation to each text node
                node.Value = transformation(node.Value);
            }
        }

        try
        {
            using (var stream = new MemoryStream())
            {
                var writer = new XmlTextWriter(stream);
                // Load your XML file into the stream
                writer.WriteStartDocument();
                // ...
                writer.WriteEndDocument();
                writer.Flush();

                navigator = XPathDocument.Load(stream.ToArray()).CreateNavigator();
                _cache.Add(xpathExpression, navigator);

                foreach (var node in navigator.Select(string.Empty).Cast<XmlNode>())
                {
                    // Apply the transformation to each text node
                    node.Value = transformation(node.Value);
                }
            }
        }
        catch (Exception ex)
        {
            if (_logger.IsEnabled(LogLevel.Error))
            {
                _logger.LogError(ex, "Failed to manipulate text nodes");
            }

            throw new Exception("Manipulation failed", ex);
        }
    }

    public void TransformDocument(XsltArgumentList arguments)
    {
        try
        {
            using (var stream = new MemoryStream())
            {
                var writer = new XmlTextWriter(stream);
                // Load your XML file into the stream
                writer.WriteStartDocument();
                // ...
                writer.WriteEndDocument();
                writer.Flush();

                var xslDoc = new XslCompiledQuery(_xsltSettings).Load("your_xslt_file.xsl");
                var result = xslDoc.Execute(arguments);

                using (var reader = new XmlTextReader(stream))
                {
                    result.Transform(reader, null);
                }
            }
        }
        catch (Exception ex)
        {
            if (_logger.IsEnabled(LogLevel.Error))
            {
                _logger.LogError(ex, "Failed to transform the document");
            }

            throw new Exception("Transformation failed", ex);
        }
    }
