import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.*;
import org.apache.commons.lang3.tuple.Pair;

public class FileHasher {

    private static final int DEFAULT_MAX_THREADS = 5;
    private static final int DEFAULT_CACHE_SIZE = 1000;
    private static final long DEFAULT_TIMEOUT_MILLIS = 60000; // 1 minute

    private int maxThreads;
    private int cacheSize;
    private long timeoutMillis;

    private Map<String, Pair<String, String>> cache = new LinkedHashMap<>(DEFAULT_CACHE_SIZE);
    private ExecutorService threadPool = Executors.newFixedThreadPool(DEFAULT_MAX_THREADS);

    public FileHasher(int maxThreads, int cacheSize) {
        this.maxThreads = maxThreads;
        this.cacheSize = cacheSize;
        this.timeoutMillis = DEFAULT_TIMEOUT_MILLIS;
    }

    public Pair<String, String> computeFileHash(String filePath) throws Exception {
        if (filePath == null || filePath.length() > 1000) {
            throw new IllegalArgumentException("Invalid file path");
        }

        try {
            MessageDigest md5 = MessageDigest.getInstance("MD5");
            MessageDigest sha256 = MessageDigest.getInstance("SHA-256");

            Path path = Path.of(filePath);
            byte[] buffer = new byte[1024 * 64]; // adjust this size as needed
            int bytesRead;

            FileInputStream fis = new FileInputStream(path.toFile());
            try (ByteArrayOutputStream bos = new ByteArrayOutputStream()) {
                for (; (bytesRead = fis.read(buffer)) != -1; ) {
                    bos.write(buffer, 0, bytesRead);
                }

                byte[] fileBytes = bos.toByteArray();
                md5.update(fileBytes);
                sha256.update(fileBytes);

                String md5Hash = bytesToHex(md5.digest());
                String sha256Hash = bytesToHex(sha256.digest());

                Pair<String, String> result = new Pair<>(md5Hash, sha256Hash);

                // Add the file path and its hash values to the cache
                synchronized (cache) {
                    if (cache.size() >= cacheSize) {
                        cache.remove(cache.headMap(cache.firstKey()).clear());
                    }
                    cache.put(filePath, result);
                }

                return result;
            } finally {
                fis.close();
            }
        } catch (Exception e) {
            // Log the error and re-throw it
            logger.error("Error computing file hash: {}", e.getMessage(), e);
            throw e;
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
