using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class SecureDataProcessor : IDisposable
{
    private readonly ILogger _logger;

    public SecureDataProcessor(ILogger logger)
    {
        _logger = logger;
    }

    public void Dispose()
    {
        _logger.Dispose();
    }

    private static class HashAlgorithmFactories
    {
        public static Func<string, Task<string>> Md5Factory => input => GenerateMd5Async(input);
        public static Func<byte[], Task<string>> Md5FactoryByte => input => GenerateMd5Async(input);

        public static Func<string, Task<string>> Sha1Factory => input => GenerateSha1Async(input);
        public static Func<byte[], Task<string>> Sha1FactoryByte => input => GenerateSha1Async(input);

        public static Func<string, Task<string>> Sha256Factory => input => GenerateSha256Async(input);
        public static Func<byte[], Task<string>> Sha256FactoryByte => input => GenerateSha256Async(input);
    }

    private async Task<string> GenerateHashAsync(Func<string, string> factory, string input)
    {
        using var hash = (HashAlgorithm)Activator.CreateInstance(factories.GetNamedType(factory.Method.Name));
        await ComputeHashAsync(hash, input);
        return ConvertToHex(hash.ComputeHash(Encoding.UTF8.GetBytes(input)));
    }

    private async Task<string> GenerateHashAsync(Func<byte[], string> factory, byte[] input)
    {
        using var hash = (HashAlgorithm)Activator.CreateInstance(factories.GetNamedType(factory.Method.Name));
        await ComputeHashAsync(hash, input);
        return ConvertToHex(hash.ComputeHash(input));
    }

    private async Task ComputeHashAsync(HashAlgorithm hash, byte[] data)
    {
        await Task.Run(() =>
        {
            using (var ms = new MemoryStream(data))
            {
                hash.Initialize();
                ms.Position = 0;
                var sr = new StreamReader(ms);
                string input;
                while ((input = sr.ReadLine()) != null)
                {
                    hash.ComputeHash(ASCIIEncoding.GetBytes(input));
                }
                hash.ComputeHash();
            }
        });
    }

    private static string ConvertToHex(byte[] data)
    {
        return BitConverter.ToString(data).Replace("-", "").ToLower();
    }

    public async Task<string> GenerateMd5Async(string input) => await GenerateHashAsync(HashAlgorithmFactories.Md5Factory, input);

    public async Task<string> GenerateMd5Async(byte[] input) => await GenerateHashAsync(HashAlgorithmFactories.Md5FactoryByte, input);

    public async Task<string> GenerateSha1Async(string input) => await GenerateHashAsync(HashAlgorithmFactories.Sha1Factory, input);

    public async Task<string> GenerateSha1Async(byte[] input) => await GenerateHashAsync(HashAlgorithmFactories.Sha1FactoryByte, input);

    public async Task<string> GenerateSha256Async(string input) => await GenerateHashAsync(HashAlgorithmFactories.Sha256Factory, input);

    public async Task<string> GenerateSha256Async(byte[] input) => await GenerateHashAsync(HashAlgorithmFactories.Sha256FactoryByte, input);

    private static class CompressionFactories
    {
        public static Func<string, Task<string>> GzipFactory => input => CompressDataAsync(input);
        public static Func<byte[], Task<string>> GzipFactoryByte => input => CompressDataAsync(input);
    }

    public async Task<string> CompressDataAsync(string input) => await CompressDataAsync(input);

    public async Task<string> CompressDataAsync(byte[] input) => await CompressDataAsync(input);

    private async Task<string> CompressDataAsync(string input)
    {
        using var ms = new MemoryStream();
        using var gzip = new GZipStream(ms, CompressionMode.Compress);
        using (var sw = new StreamWriter(gzip))
        {
            await sw.WriteAsync(input);
        }
        return ConvertToHex(ms.ToArray());
    }

    private async Task<string> CompressDataAsync(byte[] input)
    {
        using var ms = new MemoryStream();
        using var gzip = new GZipStream(ms, CompressionMode.Compress);
        await gzip.WriteAsync(input, 0, input.Length);
        return ConvertToHex(ms.ToArray());
    }

    private static class EncryptionFactories
    {
        public static Func<string, Task<string>> AesFactory => input => EncryptDataAsync(input);
        public static Func<byte[], Task<string>> AesFactoryByte => input => EncryptDataAsync(input);
    }

    public async Task<string> EncryptDataAsync(string input) => await EncryptDataAsync(input);

    public async Task<string> EncryptDataAsync(byte[] input) => await EncryptDataAsync(input);

    private async Task<string> EncryptDataAsync(string input)
    {
        using var aes = Aes.Create();
        using var ms = new MemoryStream();
        using (var cs = new CryptoStream(ms, aes.CreateEncryptor(), CryptoStreamMode.Write))
        {
            using (var sw = new StreamWriter(cs))
            {
                await sw.WriteAsync(input);
            }
        }
        return ConvertToHex(ms.ToArray());
    }

    private async Task<string> EncryptDataAsync(byte[] input)
    {
        using var aes = Aes.Create();
        using var ms = new MemoryStream();
        using (var cs = new CryptoStream(ms, aes.CreateEncryptor(), CryptoStreamMode.Write))
        {
            await cs.WriteAsync(input, 0, input.Length);
        }
        return ConvertToHex(ms.ToArray());
    }

