// Define a variadic template function to record transactions
template<typename... Args>
void recordTransaction(Args&&... args) {
    // Define error codes for different failure scenarios
    enum class ErrorCode { DatabaseFailure, LogFileFailure, PaymentProcessorFailure };

    // Define the recording mechanism based on configuration settings
    void (*recorder)(std::stringstream&, bool) = nullptr;

    if (config.useDatabase) {
        recorder = &recordToDatabase;
    } else if (config.useLogFile) {
        recorder = &recordToLogFile;
    } else {
        recorder = &recordToPaymentProcessor;
    }

    // Call the selected recording mechanism
    try {
        std::stringstream ss;
        recorder(ss, true);
    } catch (const std::runtime_error& e) {
        // Handle database connection failure or log file write error
        ErrorCode errorCode = config.useDatabase ? ErrorCode::DatabaseFailure : ErrorCode::LogFileFailure;

        // Attempt a fallback mechanism if primary recording fails
        try {
            ss << "Fallback: ";
            recorder(ss, false);
        } catch (...) {
            // Re-throw the original exception with updated error code
            throw std::runtime_error(std::move(e)).withError(ErrorCode::DatabaseFailure);
        }
    }

    // Handle payment processor API failure
    try {
        ss << "Payment Processor: ";
        recorder(ss, true);
    } catch (const std::runtime_error& e) {
        // Re-throw the original exception with updated error code
        throw std::runtime_error(std::move(e)).withError(ErrorCode::PaymentProcessorFailure);
    }
}

// Define a function to record transactions to a database
void recordToDatabase(std::stringstream&, bool);

// Define a function to record transactions to a log file
void recordToLogFile(std::stringstream&, bool);

// Define a function to record transactions to an external payment processor API
void recordToPaymentProcessor(std::stringstream&, bool);
