use reqwest;
use tokio;
use actix_web::{web, App, HttpResponse};
use serde_json::json;

#[tokio::main]
async fn main() {
    let app = App::new()
        .service(web::resource("/weather").to(get_weather))
        // Add more API routes here
        ;

    app.listen("127.0.0.1:8080").await.unwrap();
}

async fn get_weather(req: web::HttpRequest) -> HttpResponse {
    let location = req.match_info().get("location").unwrap_or("default");
    let mut client = reqwest::Client::new();

    // Configure the rate limiter
    let limiter = client.rate_limiter(
        "https://api.weather.com",
        100, // requests per minute
        5000, // milliseconds between requests
    );

    let response = limiter.get("https://api.weather.com/location/").await.unwrap();
    let data = response.json::<HashMap<String, String>>().await.unwrap();

    HttpResponse::Ok()
        .insert_header(("Content-Type", "application/json"))
        .body(serde_json::to_string_pretty(&data).unwrap())
}

struct RateLimiter {
    api_key: String,
    rate_limit: (u32, u64),
    requests: usize,
}

impl reqwest::rate_limiter::RateLimiter for RateLimiter {
    async fn check(&self) -> Result<(), reqwest::rate_limiter::Error> {
        if self.requests >= self.rate_limit.0 {
            tokio::time::sleep(std::time::Duration::from_millis(self.rate_limit.1)).await;
            self.requests = 0;
        }
        Ok(())
    }

    async fn increment(&mut self) -> Result<(), reqwest::rate_limiter::Error> {
        self.requests += 1;
        Ok(())
    }
}
