    // Initialize a new dynamic array to store the expanded state list
    int* newStates = (int*)malloc((stateListSize + 1) * sizeof(int));
    if (!newStates) {
        printf("Error: Unable to allocate memory for the new state list.\n");
        return;
    }

    // Initialize the current state index in the new array
    int newStateIndex = 0;

    // Traverse the original state list and create a copy of the states that have transitions defined in the FSA
    for (int i = 0; i < stateListSize; i++) {
        if (fsa->transitions[stateList[i]].valid) {
            newStates[newStateIndex] = stateList[i];
            newStateIndex++;
        }
    }

    // Fetch additional states from the external data source, if necessary
