import requests
import hashlib
import os
import sqlite3

def renderFooterScripts(scripts):
    rendered_scripts = []
    for script in scripts:
        if not isinstance(script, dict) or 'src' not in script or 'type' not in script or 'key' not in script:
            continue
        try:
            response = requests.get(script['src'])
            response.raise_for_status()
            script_content = response.text.encode('utf-8')
            file_hash = hashlib.md5(script_content).hexdigest()
            rendered_script = f'<script src="{script["src"]}" type="{script["type"]}" data-key="{script["key"]} data-hash="{file_hash}"></script>'
            rendered_scripts.append(rendered_script)
        except requests.exceptions.RequestException as e:
            print(f"Error fetching script {script['src']}: {e}")
    return '\n'.join(rendered_scripts)

def update_resource(resource_id, updated_data):
    try:
        conn = sqlite3.connect('resources.db')
        c = conn.cursor()
        c.execute("UPDATE resources SET data=? WHERE id=?", (json.dumps(updated_data), resource_id))
        conn.commit()
        response = requests.put(f'http://example.com/api/resources/{resource_id}', json=updated_data)
        if response.status_code == 200:
            return {'status': 'OK', 'message': 'Resource updated successfully'}
        else:
            return {'status': 'ERROR', 'message': f'Failed to update resource: {response.text}'}
    except sqlite3.Error as e:
        print(f"Database error: {e}")
        return {'status': 'ERROR', 'message': 'Database error'}
    except requests.exceptions.RequestException as e:
        print(f"Error updating resource: {e}")
        return {'status': 'ERROR', 'message': 'Failed to update resource'}
