#include <forward_list>
#include <string>
#include <algorithm>

void updateForwardList(std::forward_list<std::string>& list, const std::string& searchStr, const std::string& updateStr) {
    auto newEnd = list.end();
    bool found = false;

    for (auto it = list.begin(); !found && it != newEnd; ++it) {
        if (*it == searchStr) {
            found = true;
            break;
        }
    }

    if (!found) {
        list.emplace_back(updateStr);
        return;
    }

    list.insert_after(list.begin() + std::distance(list.begin(), it), updateStr);
}
