int dynamic_crypto_extension() {
    // Load dependencies
    if (!OPENSSL_init_crypto(0, NULL)) {
        return -1; // Error initializing OpenSSL
    }

    // Register AES and Camellia block ciphers
    if (!AES_register()) {
        return -2; // Error registering AES
    }
    if (!Camellia_register()) {
        return -3; // Error registering Camellia
    }

    // Register MD5 and SHA primitives
    if (!MD5_register()) {
        return -4; // Error registering MD5
    }
    if (!SHA_register()) {
        return -5; // Error registering SHA
    }

    // Register RSA with SHA1 primitive
    if (!RSA_register_with_SHA1()) {
        return -6; // Error registering RSA with SHA1
    }

    return 0; // Successful extension of OpenSSL library
}
