import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Service;
import org.springframework.util.FileUtils;
import javax.xml.bind.DatatypeConverter;
import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

@Service
@ConfigurationProperties(prefix = "file-hashing")
public class FileHashingService {

    private final int BUFFER_SIZE = 16384; //adjust buffer size as needed

    public String computeMd5Hash(String filePath) throws Exception {
        if (!isValidFilePath(filePath)) {
            throw new InvalidFileException("Invalid file path: " + filePath);
        }

        try (InputStream inputStream = new FileInputStream(filePath)) {
            MessageDigest md5 = MessageDigest.getInstance("MD5");
            DigestInputStream dis = new DigestInputStream(inputStream, md5);

            byte[] buffer = new byte[BUFFER_SIZE];
            int bytesRead;

            while ((bytesRead = dis.read(buffer)) != -1) {
                dis.update(buffer, 0, bytesRead);
            }

            return DatatypeConverter.printHexBinary(md5.digest());
        } catch (Exception e) {
            throw new FileOperationException("Failed to read file: " + filePath, e);
        }
    }

    private boolean isValidFilePath(String filePath) {
        try {
            File file = new File(filePath);
            return file.exists() && file.isFile();
        } catch (SecurityException | IOException e) {
            // Handle exceptions as needed
        }
        return false;
    }
}
