```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKETS 1000000
#define SEQUENCE_NUMBER_LENGTH 16
#define FLAG_LENGTH 8

typedef struct {
    int sequence_number;
    char flag[FLAG_LENGTH];
} NCP_Packet;

NCP_Packet *packets[MAX_PACKETS];
int packet_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;

void* packetGenerator(void* arg) {
    int i;
    for (i = 0; i < MAX_PACKETS; i++) {
        NCP_Packet* packet = (NCP_Packet*)malloc(sizeof(NCP_Packet));
        if (packet == NULL) {
            perror("Memory allocation failed");
            return NULL;
        }

        // Generate unique sequence number
        sprintf(packet->sequence_number, "%016d", i);

        // Initialize flag as all zeros
        memset(packet->flag, '\0', FLAG_LENGTH);

        pthread_mutex_lock(&lock);
        packets[packet_count] = packet;
        packet_count++;
        pthread_mutex_unlock(&lock);
    }

    return NULL;
}

int main() {
    int i;
    pthread_t thread;

    // Create a new NCP packet generator thread
    pthread_create(&thread, NULL, packetGenerator, NULL);

    // Wait for the thread to complete
    pthread_join(thread, NULL);

    printf("Generated %d packets.\n", packet_count);

    return 0;
}
