import os
import hashlib
import json
from typing import Dict, Any

class Aggregator:
    def __init__(self):
        self.file_map = {}

    def add_file(self, file_path: str) -> None:
        if not os.path.exists(file_path):
            raise FileNotFoundError(f"File {file_path} not found")
        with open(file_path, 'rb') as f:
            file_content = f.read()
        checksum = hashlib.md5(file_content).hexdigest()
        self.file_map[file_path] = {'content': file_content, 'checksum': checksum}

    def merge_files(self) -> bytes:
        merged_content = b''
        for _, file_info in self.file_map.items():
            merged_content += file_info['content']
        return merged_content

    def validate_checksum(self, content: bytes) -> str:
        checksum = hashlib.md5(content).hexdigest()
        return checksum

    def validate_json_token_response(self, json_response: str) -> bool:
        try:
            response = json.loads(json_response)
            if 'access_token' not in response or 'expires_in' not in response or 'token_type' not in response:
                return False
            if response['token_type'] != 'Bearer' or not isinstance(response['expires_in'], int) or response['expires_in'] < 0:
                return False
            return True
        except json.JSONDecodeError:
            return False

class FileUploader:
    def __init__(self, api_endpoint: str):
        self.api_endpoint = api_endpoint

    def upload_file(self, file_path: str, token: str) -> None:
        if not os.path.exists(file_path):
            raise FileNotFoundError(f"File {file_path} not found")
        with open(file_path, 'rb') as f:
            content = f.read()
        headers = {'Authorization': f'Bearer {token}'}
        response = requests.post(self.api_endpoint, data=content, headers=headers)
        if response.status_code != 201:
            raise Exception(f"Failed to upload file. Status code: {response.status_code}")

def main():
    aggregator = Aggregator()
    uploader = FileUploader("https://example.com/api/upload")

    # Add files
    aggregator.add_file("file1.txt")
    aggregator.add_file("file2.bin")

    # Merge files
    merged_content = aggregator.merge_files()

    # Validate checksum
    checksum = aggregator.validate_checksum(merged_content)

    # Get OAuth2 token
    token_response = requests.post("https://example.com/oauth/token", json={"grant_type": "client_credentials"})
    if not aggregator.validate_json_token_response(token_response.text):
        raise Exception("Invalid token response")

    # Upload merged file
    uploader.upload_file("merged_file.txt", token_response.json()["access_token"])

if __name__ == "__main__":
    main()
