async function robustReduce(arr, initValue, callback) {
  const results = [];
  for await (const num of arr) {
    try {
      const data = await fetchAdditionalData(num);
      const reductionResult = await callback(initValue, num, data);
      results.push(reductionResult);
      initValue = reductionResult;
    } catch (error) {
      console.error(`Error occurred during reduction for number ${num}:`, error);
      results.push({ error: true, message: error.message });
    }
  }
  return { result: results.reduce((acc, cur) => acc + cur), errors: results.filter((item) => item.error).map((item) => item.message) };
}

async function fetchAdditionalData(num) {
  // Implement your API integration logic here
  // For demonstration purposes, assume it takes some time to retrieve data
  await new Promise((resolve) => setTimeout(() => resolve(), 500));
  return { additionalData: `Fetched data for number ${num}` };
}

