class AdvancedWebSecurityManager {
    private $cache;
    private $saltRoundCount = 12;

    public function __construct() {
        $this->cache = cache('recent_strings');
    }

    public function generateSecureRandomString($length, $characterSet) {
        if (!$this->validateCharacterSet($characterSet)) {
            return 'Invalid character set. Please use a combination of uppercase and lowercase letters, digits, and special characters.';
        }
        $possibleCharacters = implode('', array_merge(range('A', 'Z'), range('a', 'z'), range(0, 9), ['~', '^', '#', '$']));

        if (isset($this->cache[$length])) {
            return $this->cache[$length];
        }

        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $possibleCharacters[random_int(0, strlen($possibleCharacters) - 1)];
        }
        $this->cache[$length] = $randomString;
        return $randomString;
    }

    public function hashPassword($password, $saltRoundCount = null) {
        if ($saltRoundCount > 31 || $saltRoundCount < 12) {
            throw new Exception('Invalid salt round count. Please use a value between 12 and 31.');
        }
        $this->setSaltRoundCount($saltRoundCount);
        return password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->getSaltRoundCount()]);
    }

    public function checkPassword($hashedPassword, $password) {
        return password_verify($password, $hashedPassword);
    }

    public function validateCharacterSet($characterSet) {
        if (!preg_match('/[A-Z]/', $characterSet) || !preg_match('/[a-z]/', $characterSet) || !preg_match('/\d/', $characterSet) || !preg_match('/[^A-Za-z0-9]/', $characterSet)) {
            return false;
        }
        return true;
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds > 31 || $rounds < 12) {
            throw new Exception('Invalid salt round count. Please use a value between 12 and 31.');
        }
        $this->saltRoundCount = $rounds;
    }

    public function resetPassword() {
        $this->cache->flush();
    }

    public function logPasswordAttempts($ipAddress, $result) {
        // Implement logging mechanism
    }
}
