```
function renderFooterScripts(scripts) {
  const cachedScripts = {};
  const fetchScript = async (script) => {
    try {
      if (!cachedScripts[script.key]) {
        const response = await fetch(script.src);
        const scriptContent = await response.text();
        cachedScripts[script.key] = scriptContent;
      }
      return cachedScripts[script.key];
    } catch (error) {
      if (error.name === 'AbortError') {
        // Network request was aborted
        return null;
      }
      console.error(`Failed to fetch script ${script.src}:`, error);
      await new Promise((resolve, reject) => setTimeout(() => {
        try {
          const response = await fetch(script.src);
          const scriptContent = await response.text();
          cachedScripts[script.key] = scriptContent;
          resolve();
        } catch (error) {
          reject(error);
        }
      }, 5000));
    }
  };

  async function validateScriptKeys() {
    try {
      const configResponse = await fetch('https://config-service.com/script-keys');
      const configData = await configResponse.json();
      scripts.forEach((script) => {
        if (!configData.includes(script.key)) {
          console.log(`Skipped script ${script.src} due to invalid key`);
          return false;
        }
        return true;
      });
    } catch (error) {
      console.error('Failed to validate script keys:', error);
    }
  };

  async function renderScripts() {
    await validateScriptKeys();
    for (const script of scripts) {
      try {
        const scriptContent = await fetchScript(script);
        if (!scriptContent) continue;
        if (!script.key) throw new Error('Missing key');
        if (!script.src || !script.type) throw new Error('Invalid script properties');
        const fallbackUrl = 'https://fallback-config.com/script-fallback';
        try {
          const response = await fetch(fallbackUrl);
          const fallbackScriptContent = await response.text();
          cachedScripts[script.key] = fallbackScriptContent;
        } catch (error) {
          console.error(`Failed to fetch script fallback ${fallbackUrl}:`, error);
        }
      } catch (error) {
        console.error(`Error rendering script ${script.src}:`, error);
      }
    }
  };

  async function renderFooter() {
    await renderScripts();
    const footerScripts = scripts.map((script) => `<script type="${script.type}" src="${script.src}"></script>`).join('');
    document.getElementById('footer-scripts').innerHTML = footerScripts;
  };

  window.renderFooterScripts = () => renderFooter();

  // Set up initial rendering and caching
  await renderFooter();
}

