    async def execute_task(specs: List):
        results = []
        for spec in specs:
            try:
                result = await spec()
                print(f"Task {spec.__name__} completed with result: {result}")
                results.append(result)
            except Exception as e:
                print(f"Error in task {spec.__name__}: {e}")
        return results

