#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    HASH,
    CIPHER
} algorithm_type;

typedef struct {
    char* name;
    void (*function)(void*, int);
    void* param;
} algorithm_struct;

// Function to dynamically load algorithms from a library
algorithm_struct** load_algorithms(int* count, const char* lib_path) {
    // Load the library and get its symbols
    // For simplicity, we'll assume this is done using dlopen/dlsym
    void* lib = dlopen(lib_path, RTLD_LAZY);
    if (!lib) return NULL;

    // Get a list of available algorithms from the library
    char** algorithm_names = (char**)dlsym(lib, "get_algorithms");
    if (!algorithm_names) {
        dlclose(lib);  // Close the library if the symbol lookup fails
        return NULL;
    }

    int num_algorithms = 0;
    for (int i = 0; algorithm_names[i]; i++) {
        num_algorithms++;
    }
    algorithm_struct** algorithms = (algorithm_struct**)malloc((num_algorithms + 1) * sizeof(algorithm_struct*));

    // Iterate over the list of algorithms and create structs
    for (int i = 0, j = 0; algorithm_names[i]; i++) {
        char* name = algorithm_names[i];
        void (*func)(void*, int);
        void* param;
        // Get the corresponding function pointer and parameter from the library
        // For simplicity, we'll assume this is done using dlsym again
        func = (void (*)(void*, int))dlsym(lib, name);
        if (!func) {
            dlclose(lib);  // Close the library if the symbol lookup fails
            free(algorithms);
            return NULL;
        }

        algorithms[j] = malloc(sizeof(algorithm_struct));
        algorithms[j]->name = strdup(name);
        algorithms[j]->function = func;
        algorithms[j++]->param = param;  // Set the parameter as needed

        free(algorithm_names[i]);  // Release the algorithm name
    }
    free(algorithm_names);  // Release the list of algorithm names

    *count = num_algorithms;
    return algorithms;
}

// Function to query available algorithms from a library without loading the entire library
algorithm_struct* query_algorithm(const char* lib_path, const char* algorithm_name) {
    // Load the library and get its symbols
    // For simplicity, we'll assume this is done using dlopen/dlsym
    void* lib = dlopen(lib_path, RTLD_LAZY);
    if (!lib) return NULL;

    // Get the corresponding function pointer from the library
    // For simplicity, we'll assume this is done using dlsym again
    void (*func)(void*, int);
    func = (void (*)(void*, int))dlsym(lib, algorithm_name);

    if (!func) {
        dlclose(lib);  // Close the library if the symbol lookup fails
        return NULL;
    }

    // Create a struct for the queried algorithm and return it
    algorithm_struct* algorithm = malloc(sizeof(algorithm_struct));
    algorithm->name = strdup(algorithm_name);
    algorithm->function = func;
    // Set the parameter as needed

    dlclose(lib);  // Close the library after use

    return algorithm;
}

// Function to iterate over available algorithms and perform an action
void iterate_algorithms(algorithm_struct** algorithms, int count, void (*action)(algorithm_struct*)) {
    for (int i = 0; i < count; i++) {
        action(algorithms[i]);
        free(algorithms[i]->name);
        free(algorithms[i]);  // Release the algorithm struct
    }
}

// Function to release memory allocated for algorithms
void release_algorithms(algorithm_struct** algorithms, int count) {
    for (int i = 0; i < count; i++) {
        free(algorithms[i]->name);
        free(algorithms[i]);  // Release the algorithm struct
    }
    free(algorithms);  // Release the list of algorithms
}

// Example action function to demonstrate usage
void print_algorithm_info(algorithm_struct* algorithm) {
    printf("%s: %p\n", algorithm->name, algorithm->function);
}
