int processNFALIST(int num_structures, NFAPI_CRC_INDICATION_PDU_T **nfalist, int *crc_flag_rules, int max_threads, char *ip_address, int port) {
    // Initialize sequence generator
    int seq = 0;

    // Allocate memory for the list of structures
    *nfalist = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structures);

    if (*nfalist == NULL) {
        log_structure_operation("Memory allocation failed", LOG_ERROR);
        return -1;
    }

    // Initialize thread-safe data structures
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &(*nfalist)[i];

        // Set RX_UE_INFORMATION_TAG and RNTI values
        pdu->RX_UE_INFORMATION_TAG = seq++;
        pdu->RNTI = seq++;

        // Set CRCFLAG based on the corresponding rule in crc_flag_rules
        if (crc_flag_rules[i % sizeof(crc_flag_rules) / sizeof(int)] != 0) {
            pdu->CRCFLAG = crc_flag_rules[i % sizeof(crc_flag_rules) / sizeof(int)];
        } else {
            pdu->CRCFLAG = CRCFLAG_INVALID;
        }

        // Use a separate thread to send the populated structure over the network
        pthread_t thread;
        pthread_create(&thread, NULL, send_structure, (void *)pdu);
    }

    // Wait for all threads to finish before freeing memory
    for (int i = 0; i < num_structures; i++) {
        pthread_join(thread, NULL);
    }

    free(*nfalist);

    return 1;
}

void *send_structure(void *args) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = args;

    // Send the populated structure over the network
    if (network_send(pdu, ip_address, port) == -1) {
        log_structure_operation("Network communication error", LOG_ERROR);
        return NULL;
    }

    // Log the transmission of the structure
    log_structure_operation("Structure sent successfully", LOG_INFO);

    return NULL;
}
