import os
import threading
import logging
import time
from queue import Queue
from concurrent.futures import ThreadPoolExecutor

class FileMergger:
    def __init__(self, file_paths, dest_path, max_retries=5, buffer_size=4096):
        self.file_paths = file_paths
        self.dest_path = dest_path
        self.max_retries = max_retries
        self.buffer_size = buffer_size
        self.logger = logging.getLogger(__name__)
        self.lock = threading.Lock()
        self.queue = Queue()

    def merge_files(self, segment_size=1024*1024):
        with open(self.dest_path, 'wb') as dest_file:
            with ThreadPoolExecutor() as executor:
                for file_path in self.file_paths:
                    executor.submit(self.read_and_write, file_path, dest_file, segment_size)

    def read_and_write(self, file_path, dest_file, segment_size):
        try:
            with open(file_path, 'rb') as file:
                while True:
                    data = file.read(segment_size)
                    if not data:
                        break
                    for _ in range(self.max_retries):
                        dest_file.write(data)
                        if self.queue.full():
                            self.queue.get()
                            self.queue.put(f"Written {len(data)} bytes from {file_path} to {self.dest_path}")
                    else:
                        raise IOError("Failed to write data")
        except Exception as e:
            self.logger.error(f"Error merging file {file_path}: {str(e)}")

    def log_progress(self):
        while True:
            try:
                if not self.queue.empty():
                    print(self.queue.get())
            except:
                pass
            time.sleep(1)

if __name__ == "__main__":
    merger = FileMergger(['file1.txt', 'file2.txt'], 'merged_file.txt')
    merger.merge_files()
