const express = require('express');
const cors = require('cors');
const mongoose = require('mongoose');
const passport = require('passport');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');
const { User, Channel } = require('./models');
const { Message } = require('./messageModel');
const { Notification } = require('./notificationModel');

// Set up the express app
const app = express();

// Enable CORS for client-side requests
app.use(cors());

// Connect to MongoDB
mongoose.connect('mongodb://localhost/chat-app', { useNewUrlParser: true, useUnifiedTopology: true });

// Initialize Passport.js
passport.initialize();
passport.session();

// Define authentication routes
app.post('/login', (req, res) => {
  const { username, password } = req.body;
  User.findOne({ username })
    .then((user) => {
      if (!user || !bcrypt.compareSync(password, user.password)) {
        return res.status(401).send('Invalid credentials');
      }
      const token = jwt.sign({ _id: user._id }, process.env.SECRET_KEY, { expiresIn: '1h' });
      return res.send({ token });
    })
    .catch((err) => {
      console.error(err);
      return res.status(500).send('Internal Server Error');
    });
});

app.get('/logout', (req, res) => {
  req.logout();
  res.send('Logged out successfully');
});

// Define message routes
app.post('/messages', async (req, res) => {
  const { channelName, message } = req.body;
  try {
    const channel = await Channel.findOne({ name: channelName });
    if (!channel) {
      return res.status(404).send('Channel not found');
    }
    const newMessage = await Message.create({
      text: message,
      channel: channel._id,
      author: req.user._id,
    });
    // Send message to clients connected to the channel
    channel.clients.forEach((client) => {
      client.emit('newMessage', { message: newMessage.text, author: req.user.username });
    });
  } catch (err) {
    console.error(err);
    return res.status(500).send('Internal Server Error');
  }
});

// Define notification routes
app.post('/notifications', async (req, res) => {
  const { channelName, type } = req.body;
  try {
    const channel = await Channel.findOne({ name: channelName });
    if (!channel) {
      return res.status(404).send('Channel not found');
    }
    const newNotification = await Notification.create({
      type,
      channel: channel._id,
      recipient: req.user._id,
    });
  } catch (err) {
    console.error(err);
    return res.status(500).send('Internal Server Error');
  }
});

// Start the server
app.listen(3000, () => {
  console.log('Server started on port 3000');
});
