#include <openssl/rsa.h>
#include <openssl/err.h>
#include <openssl/engine.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <pthread.h>
#include <unistd.h>

int convert_images_to_pdf(const char *input_dir, const char *private_key_file, const char *password) {
    // Initialize OpenSSL
    ERR_load_crypto_strings();
    ENGINE_load_builtin_engines();

    // Load private key and derive encryption/decryption keys from password
    RSA *rsa_ctx = RSA_new();
    if (!RSA_key_from_private_key(private_key_file, NULL, &rsa_ctx)) {
        ERR_error_f();
        return -1;
    }

    // Initialize progress callback mechanism
    int num_conversions = 0;
    pthread_t threads[10];
    int thread_count = 0;

    DIR *dir = opendir(input_dir);
    if (!dir) {
        fprintf(stderr, "Error opening directory: %s\n", input_dir);
        return -1;
    }

    struct dirent *ent;
    while ((ent = readdir(dir))) {
        char path[1024];
        sprintf(path, "%s/%s", input_dir, ent->d_name);

        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue;

        int result = pthread_create(&threads[thread_count], NULL, &convert_image_to_pdf, path);
        if (result != 0) {
            fprintf(stderr, "Error creating thread: %s\n", strerror(result));
            return -1;
        }
        thread_count++;
    }

    closedir(dir);

    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
        num_conversions++;
    }

    // Cleanup
    RSA_free(rsa_ctx);
    ENGINE_free();

    return num_conversions;
}

void *convert_image_to_pdf(void *arg) {
    // Convert image to PDF using third-party tool (e.g. ImageMagick)
    const char *path = (const char *) arg;

    // Handle errors from the conversion process
    if (system("convert -density 300 -resize 1024x768 -quality 92 output.pdf input.jpg") != 0) {
        fprintf(stderr, "Error converting image: %s\n", path);
    }

    return NULL;
}

