import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

public class ServiceManager {
    private final ExecutorService executor = Executors.newFixedThreadPool(10);
    private final List<ServiceInstance> instances = new ArrayList<>();
    private final Config config;

    public ServiceManager(Config config) {
        this.config = config;
    }

    public void start() {
        for (int i = 0; i < config.getNumInstances(); i++) {
            ServiceInstance instance = new ServiceInstance(executor, config);
            instances.add(instance);
            executor.submit(() -> instance.start());
        }
    }

    public void stop() {
        for (ServiceInstance instance : instances) {
            executor.submit(() -> instance.stop());
        }
    }

    public void checkHealth() {
        for (ServiceInstance instance : instances) {
            executor.submit(() -> instance.checkHealth());
        }
    }

    private class ServiceInstance implements Runnable {
        private final ExecutorService executor;
        private final Config config;

        public ServiceInstance(ExecutorService executor, Config config) {
            this.executor = executor;
            this.config = config;
        }

        @Override
        public void run() {
            while (true) {
                try {
                    // Call the service API to start/stop/check health
                    if (ThreadLocalRandom.current().nextInt(config.getMaxRetryAttempts()) == 0) {
                        // Simulate a failure or network latency
                        Thread.sleep(500);
                    }
                    if (shouldStart()) {
                        startService();
                    } else if (shouldStop()) {
                        stopService();
                    } else {
                        checkHealthStatus();
                    }
                    Thread.sleep(config.getIntervalBetweenOperations());
                } catch (InterruptedException e) {
                    return;
                }
            }
        }

        private void startService() {
            // Call the service API to start
            try {
                // Simulate a random delay using geometric distribution
                int delay = GeometricDistribution.next(config.getMinDelay(), config.getMaxDelay());
                Thread.sleep(delay);
                // Report status update to the centralized monitoring system
                System.out.println("Started instance " + this);
            } catch (Exception e) {
                // Handle failure or network latency
                try {
                    Thread.sleep(500);
                } catch (InterruptedException ignored) {}
            }
        }

        private void stopService() {
            // Call the service API to stop
            try {
                // Simulate a random delay using geometric distribution
                int delay = GeometricDistribution.next(config.getMinDelay(), config.getMaxDelay());
                Thread.sleep(delay);
                // Report status update to the centralized monitoring system
                System.out.println("Stopped instance " + this);
            } catch (Exception e) {
                // Handle failure or network latency
                try {
                    Thread.sleep(500);
                } catch (InterruptedException ignored) {}
            }
        }

        private void checkHealthStatus() {
            // Call the service API to check health
            try {
                // Simulate a random delay using geometric distribution
                int delay = GeometricDistribution.next(config.getMinDelay(), config.getMaxDelay());
                Thread.sleep(delay);
                // Report status update to the centralized monitoring system
                System.out.println("Checked health of instance " + this);
            } catch (Exception e) {
                // Handle failure or network latency
                try {
                    Thread.sleep(500);
                } catch (InterruptedException ignored) {}
            }
        }

        private boolean shouldStart() {
            return ThreadLocalRandom.current().nextBoolean();
        }

        private boolean shouldStop() {
            return ThreadLocalRandom.current().nextBoolean();
        }
    }

    public static class Config {
        private int numInstances;
        private int maxRetryAttempts;
        private int minDelay;
        private int maxDelay;
        private int intervalBetweenOperations;

        public Config(int numInstances, int maxRetryAttempts, int minDelay, int maxDelay, int intervalBetweenOperations) {
            this.numInstances = numInstances;
            this.maxRetryAttempts = maxRetryAttempts;
            this.minDelay = minDelay;
            this.maxDelay = maxDelay;
            this.intervalBetweenOperations = intervalBetweenOperations;
        }

        public int getNumInstances() {
            return numInstances;
        }

        public int getMaxRetryAttempts() {
            return maxRetryAttempts;
        }

        public int getMinDelay() {
            return minDelay;
        }

        public int getMaxDelay() {
            return maxDelay;
        }

        public int getIntervalBetweenOperations() {
            return intervalBetweenOperations;
        }
    }
