import org.apache.commons.io.FilenameUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.IOException;
import java.io.Reader;
import java.io.UnreadableFileException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;

public class DirectoryProcessor {
    private static final Logger logger = LoggerFactory.getLogger(DirectoryProcessor.class);
    private static final int MAX_FILE_SIZE = 1024 * 1024; // 1MB
    private static final int DEFAULT_CACHE_CAPACITY = 100;
    private static final String DEFAULT_CACHE_KEY = "file-contents-cache";

    public static String processDirectoryContents(String directoryPath, String extensionFilter, String encoding, boolean includeHashes) throws IOException {
        if (directoryPath == null || directoryPath.length() > 1000) {
            throw new IllegalArgumentException("Invalid directory path");
        }

        Path directory = Paths.get(directoryPath);
        if (!Files.exists(directory)) {
            return "";
        }

        ExecutorService executor = Executors.newFixedThreadPool(5); // adjust the thread pool size based on your system's capabilities
        ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
        int cacheCapacity = DEFAULT_CACHE_CAPACITY;
        String cacheKey = DEFAULT_CACHE_KEY;

        try (Reader reader = Files.newBufferedReader(directory, StandardOpenOption.READ)) {
            reader.lines().map(line -> line.split("\t")).forEach(parts -> {
                Path file = Paths.get(parts[0]);
                if (!Files.exists(file) || !Files.isRegularFile(file)) {
                    return; // skip non-file entries
                }

                String fileExtension = FilenameUtils.getExtension(file.toString());
                if (extensionFilter != null && !fileExtension.equalsIgnoreCase(extensionFilter)) {
                    return; // filter out files not matching the extension
                }

                try {
                    byte[] fileBytes;
                    if (encoding.equals("UTF-8")) {
                        fileBytes = Files.readAllBytes(file);
                    } else if (encoding.equals("ASCII")) {
                        fileBytes = Files.readAllBytes(Files.readAllBytes(Files.readAllBytes(Files.readAllBytes(file)))); // adjust for ASCII encoding
                    } else {
                        throw new UnsupportedOperationException("Unsupported encoding: " + encoding);
                    }

                    int fileSize = fileBytes.length;
                    if (fileSize > MAX_FILE_SIZE) {
                        logger.warn("Large file found: {}", file);
                        return; // skip large files
                    }

                    String fileContent = new String(fileBytes, encoding);
                    String cacheKeyForFile = file.toString();

                    try {
                        String cachedContent = cache.get(cacheKeyForFile);
                        if (cachedContent != null) {
                            logger.info("Using cached content for file: {}", file);
                            return; // use the cached content
                        }
                    } catch (Exception e) {
                        logger.error("Error accessing cache", e);
                    }

                    try {
                        String hashedContent;
                        if (includeHashes) {
                            MessageDigest md = MessageDigest.getInstance("SHA-256");
                            byte[] hashBytes = md.digest(fileContent.getBytes(encoding));
                            String fileContentWithHash = new String(hashBytes, Base64.getEncoder());

                            md = MessageDigest.getInstance("MD5");
                            hashBytes = md.digest(fileContent.getBytes(encoding));
                            String fileHash = new String(hashBytes, Base64.getEncoder());

                            hashedContent = fileContent + "\n" + fileContentWithHash + "\n" + fileHash;
                        } else {
                            hashedContent = fileContent;
                        }

                        cache.put(cacheKeyForFile, hashedContent);
                    } catch (Exception e) {
                        logger.error("Error processing file content", e);
                    }

                    executor.submit(() -> {
                        try {
                            // write the file content to Redis for persistent caching
                            String redisKey = "file:contents:" + cacheKeyForFile;
                            Jedis jedis = new Jedis();
                            jedis.set(redisKey, hashedContent);
                            jedis.close();
                        } catch (Exception e) {
                            logger.error("Error writing to Redis", e);
                        }
                    });
                } catch (UnreadableFileException e) {
                    logger.error("Error reading file: {}", file, e);
                }
            });
        } finally {
            executor.shutdown();
        }

        return "";
    }
}
