#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure definition
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG[4];
} NFAPI_CRC_INDICATION_PDU_T;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void createCRCIndicationPduList(int N, NFAPI_CRC_INDICATION_PDU_T** list) {
    // Create an array of pointers to NFAPI_CRC_INDICATION_PDU_T structs
    *list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    for (int i = 0; i < N; i++) {
        // Create a new NFAPI_CRC_INDICATION_PDU_T struct
        (*list)[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Set random CRC flags
        for (int j = 0; j < 4; j++) {
            (*list)[i]->CRCFLAG[j] = rand() % 256;
        }

        // Set other fields to some default values
        (*list)[i]->RX_UE_INFORMATION_TAG = i;
        (*list)[i]->RNTI = i;

        // Add the struct to the list
        printf("Created and populated CRC indication PDU %d\n", i);
    }
}

int main() {
    int N = 100000; // example value

    NFAPI_CRC_INDICATION_PDU_T** list;
    createCRCIndicationPduList(N, &list);

    for (int i = 0; i < N; i++) {
        printf("CRC indication PDU %d: RX_UE_INFORMATION_TAG = %u, RNTI = %u\n",
              i, (*list)[i]->RX_UE_INFORMATION_TAG, (*list)[i]->RNTI);
    }

    // Free memory
    for (int i = 0; i < N; i++) {
        free((*list)[i]);
    }
    free(list);

    return 0;
}
