using System;
using System.Data.SqlClient;
using Newtonsoft.Json;
using System.Net.Http;
using System.Threading.Tasks;

namespace EmployeeWeatherAPI
{
    public class EmployeeWeatherService
    {
        private readonly string _connectionString = "Server=localhost;Database=EmployeeDB;User ID=myUsername;Password=myPassword;";
        private readonly HttpClient _httpClient = new HttpClient();

        public async Task<string> GetEmployeeWeatherData(int supervisorId, int pageIndex, int pageSize)
        {
            try
            {
                using (SqlConnection connection = new SqlConnection(_connectionString))
                {
                    connection.Open();
                    SqlCommand command = new SqlCommand("GetSupervisorEmployees", connection);
                    command.CommandType = System.Data.CommandType.StoredProcedure;
                    command.Parameters.AddWithValue("@supervisorId", supervisorId);

                    SqlDataReader reader = await command.ExecuteReaderAsync();

                    List<Employee> employees = new List<Employee>();

                    while (await reader.ReadAsync())
                    {
                        Employee employee = new Employee();
                        employee.Name = reader["Name"].ToString();
                        employee.City = reader["City"].ToString();
                        employee.Address = reader["Address"].ToString();

                        employees.Add(employee);
                    }

                    reader.Close();

                    int totalEmployees = await GetTotalEmployees(supervisorId);

                    return JsonConvert.SerializeObject(new
                    {
                        employees,
                        totalCount = totalEmployees,
                        pageIndex,
                        pageSize,
                        totalPages = (int)Math.Ceiling((decimal)totalEmployees / pageSize)
                    });
                }
            }
            catch (Exception ex)
            {
                // Handle error
                throw;
            }
        }

        private async Task<int> GetTotalEmployees(int supervisorId)
        {
            using (SqlConnection connection = new SqlConnection(_connectionString))
            {
                connection.Open();
                SqlCommand command = new SqlCommand("GetSupervisorEmployeeCount", connection);
                command.CommandType = System.Data.CommandType.StoredProcedure;
                command.Parameters.AddWithValue("@supervisorId", supervisorId);

                object result = await command.ExecuteScalarAsync();

                return Convert.ToInt32(result);
            }
        }

        public async Task<string> GetWeatherData(string city)
        {
            try
            {
                using (HttpResponseMessage response = await _httpClient.GetAsync($"http://api.openweathermap.org/data/2.5/weather?q={city}&appid=YOUR_API_KEY"))
                {
                    response.EnsureSuccessStatusCode();

                    string responseBody = await response.Content.ReadAsStringAsync();
                    return responseBody;
                }
            }
            catch (Exception ex)
            {
                // Handle error
                throw;
            }
        }
    }

    public class Employee
    {
        public string Name { get; set; }
        public string City { get; set; }
        public string Address { get; set; }
    }
}
