```java
import java.util.*;
import java.lang.reflect.*;

public class CacheManager {
    private Map<String, SessionCache> sessionCaches;
    private ThreadLocal<Map<String, Session>> cacheMap;
    private int maxSize;
    private int maxLoadFactor;
    private long evictionThreshold;
    private Logger logger;

    public CacheManager(int maxSize, int maxLoadFactor, long evictionThreshold) {
        this.maxSize = maxSize;
        this.maxLoadFactor = maxLoadFactor;
        this.evictionThreshold = evictionThreshold;
        sessionCaches = new HashMap<>();
        cacheMap = ThreadLocal.withInitial(() -> new ConcurrentHashMap<>());
        logger = Logger.getLogger(CacheManager.class.getName());
    }

    public void putSession(String sessionId, Session session) {
        int currentSize = cacheMap.get().size();
        if (currentSize > maxSize) {
            evictOldestSessions(currentSize - maxSize);
        }
        cacheMap.get().put(sessionId, session);
        logger.info("Cache hit: " + sessionId);
    }

    public Session getSession(String sessionId) {
        Session session = cacheMap.get().get(sessionId);
        if (session == null) {
            logger.warning("Cache miss: " + sessionId);
        }
        return session;
    }

    private void evictOldestSessions(int numEvictions) {
        SortedSet<Map.Entry<String, Session>> entries = new TreeSet<>(cacheMap.get().entrySet());
        for (int i = 0; i < numEvictions; i++) {
            Map.Entry<String, Session> oldestEntry = entries.first();
            cacheMap.get().remove(oldestEntry.getKey(), oldestEntry.getValue());
            logger.info("Cache eviction: " + oldestEntry.getKey());
        }
    }

    public void invalidateSession(String sessionId) {
        cacheMap.get().remove(sessionId);
        logger.info("Cache invalidation: " + sessionId);
    }

    public void invalidateAllSessions() {
        Map<String, Session> sessionMap = new HashMap<>(cacheMap.get());
        for (String sessionId : sessionMap.keySet()) {
            cacheMap.get().remove(sessionId);
        }
        logger.info("Cache invalidated");
    }

    public void logCacheStats(Logger logger) {
        int cacheHits = 0;
        int cacheMisses = 0;
        for (Session session : cacheMap.get().values()) {
            if (session != null) {
                cacheHits++;
            } else {
                cacheMisses++;
            }
        }
        logger.info("Cache hits: " + cacheHits);
        logger.info("Cache misses: " + cacheMisses);
    }

    public void integrateWithMonitoringSystem(MonitoringSystem monitoringSystem) {
        // TO DO: implement integration with external monitoring system
    }
}
