import os
import gzip
import heapq
from concurrent.futures import ThreadPoolExecutor, ProcessPoolExecutor
from multiprocessing import cpu_count
from io import BytesIO
from time import sleep
from logging import getLogger, basicConfig

class FileMerger:
    def __init__(self):
        self.logger = getLogger(__name__)
        self.config = {'buffer_size': 1024*1024, 'threads': cpu_count(), 'processes': 1}

    def set_config(self, config):
        self.config.update(config)

    def merge_files(self, file_paths, destination_path):
        try:
            with ThreadPoolExecutor(max_workers=self.config['threads']) as executor:
                futures = [executor.submit(self.merge_file, file_path) for file_path in file_paths]
                merged_file = BytesIO()
                with ProcessPoolExecutor() as process_pool:
                    writer = process_pool.submit(self.write_to_buffer, merged_file)
                    for future in futures:
                        data = future.result()
                        if not data:
                            continue
                        writer.send(data)
            self.compress_and_write(merged_file.getvalue(), destination_path)
        except Exception as e:
            self.logger.error(f"Error merging files: {e}")
        finally:
            self.logger.info("File merger completed")

    def merge_file(self, file_path):
        try:
            with open(file_path, 'rb') as file:
                data = file.read()
                return data
        except Exception as e:
            raise

    def write_to_buffer(self, buffer, data):
        try:
            buffer.write(data)
            return None
        except Exception as e:
            raise

    def compress_and_write(self, data, destination_path):
        try:
            with open(destination_path, 'wb') as file:
                if self.config['compress']:
                    with gzip.open(file.name, 'wb') as compressed_file:
                        compressed_file.write(data)
                else:
                    file.write(data)
        except Exception as e:
            raise

if __name__ == "__main__":
    basicConfig(level=logging.INFO)

    merger = FileMerger()
    merger.set_config({'compress': True})

    destination_path = 'merged_file.txt'
    file_paths = ['file1.txt', 'file2.txt', ...]  # list of files to merge
    merger.merge_files(file_paths, destination_path)
