#include "configuration.h"
#include "logger.h"

void establishDatabaseConnection(struct Configuration* config) {
    if (!config->url || !config->username || !config->password) {
        logger(config->logger, ILogger::ERROR, "Invalid database connection configuration");
        return;
    }

    if (strlen(config->url) == 0 || strlen(config->username) == 0 || strlen(config->password) == 0) {
        logger(config->logger, ILogger::ERROR, "Database URL, username, or password is empty");
        return;
    }

    // Validate connection settings
    if (config->connection_settings.timeout <= 0 || config->connection_settings.max_retries < 1 ||
        config->connection_settings.concurrency_level < 0) {
        logger(config->logger, ILogger::ERROR,
               "Invalid connection settings: timeout must be positive, max retries should be at least 1, and concurrency level should be non-negative");
        return;
    }

    // Establish database connection
    while (true) {
        try {
            // Attempt to connect to the database
            // ...

            break; // Connection established successfully

        } catch (const std::exception& e) {
            logger(config->logger, ILogger::ERROR, "Error establishing database connection: %s", e.what());

            if (config->connection_settings.max_retries > 0) {
                int retryDelay = (1 << (config->connection_settings.max_retries - 1));
                std::this_thread::sleep_for(std::chrono::milliseconds(retryDelay));

                config->connection_settings.max_retries--;
            } else {
                logger(config->logger, ILogger::ERROR,
                       "Maximum retries exceeded; unable to establish database connection");
                return;
            }
        }
    }

    // Connection established successfully
}
