#include <octree.h>

void initializeOctree(float featureSize, int numInitialLeafNodes, int maxDataCapacity) {
    // Dynamic memory allocation for octree nodes
    OctreeNode* root = new OctreeNode(featureSize);

    // Dynamic memory allocation for prefix leaf nodes
    LeafNode** leafNodes = new LeafNode*[8];
    for (int i = 0; i < 8; i++) {
        leafNodes[i] = new LeafNode();
    }

    // Dynamic memory allocation for data array
    float* dataPoints = new float[3 * numInitialLeafNodes];

    try {
        // Initialize octree nodes and prefix leaf nodes
        root->setFeatureSize(featureSize);
        for (int i = 0; i < 8; i++) {
            leafNodes[i]->setRoot(root);
        }

        // Insert data points into the octree
        for (int i = 0; i < numInitialLeafNodes; i++) {
            // Calculate the node index and depth based on the feature size
            int nodeIndex = i % 8;
            int depth = (int)log2(featureSize);

            // Insert data point into the leaf node
            leafNodes[nodeIndex]->insertDataPoint(dataPoints + 3 * i);
        }

        // Balance the octree when new points are added
        balanceOctree(root, maxDataCapacity);
    } catch (std::exception& e) {
        throw;
    } finally {
        // Free dynamically allocated memory
        delete[] leafNodes;
        delete[] dataPoints;
        delete root;
    }
}

void balanceOctree(OctreeNode* root, int maxDataCapacity) {
    // Check if the octree needs to be rebalanced
    if (root->getNumPoints() > maxDataCapacity / 2) {
        // Recursively traverse the octree and rebalance nodes
        for (int i = 0; i < 8; i++) {
            OctreeNode* childNode = root->getChild(i);
            if (childNode != nullptr) {
                balanceOctree(childNode, maxDataCapacity);
            }
        }
    }
}
