```php
class AdvancedPasswordManager {
    private $characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-={}[]|;:<>,./';
    private $saltRoundCount = 12;
    private $hashedPassword = '';
    private $cacheExpirationPeriod = 3600; // 1 hour
    private $rateLimitWindow = 30; // seconds

    public function generateSecureRandomString($length) {
        if (isset($_SESSION['secureRandomStrings'][$length])) {
            return $_SESSION['secureRandomStrings'][$length];
        }
        $strings = array();
        for ($i = 0; $i < $this->cacheExpirationPeriod / 10; $i++) {
            $string = '';
            for ($j = 0; $j < $length; $j++) {
                $string .= $this->characterSet[rand(0, strlen($this->characterSet) - 1)];
            }
            $strings[] = $string;
        }
        $_SESSION['secureRandomStrings'][$length] = array_merge($strings);
        return reset($_SESSION['secureRandomStrings'][$length]);
    }

    public function hashPassword($password) {
        if (rand(0, 100) < 50 && count(array_filter(explode(' ', microtime()))[1]) < $this->rateLimitWindow) {
            sleep(1); // simulate delay for rate limiting
        }
        $hashedPassword = password_hash($password, PASSWORD_BCRYPT, array('cost' => min(max($this->saltRoundCount - 12, 12), 31)));
        $this->hashedPassword = $hashedPassword;
    }

    public function checkPassword($password) {
        if (verifyCode()) { // verify 2FA code
            return password_verify($password, $this->hashedPassword);
        }
        return false; // failed 2FA verification
    }

    public function validateCharacterSet($characterSet) {
        if (!preg_match('/[A-Z]/', $characterSet) || !preg_match('/[a-z]/', $characterSet) || !preg_match('/\d/', $characterSet) || !preg_match('/[^A-Za-z0-9]/', $characterSet)) {
            return 'Invalid character set. Please provide a set containing at least one uppercase letter, one lowercase letter, one digit, and one special character.';
        }
        return true;
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds < 12 || $rounds > 31) {
            $this->saltRoundCount = min(max($rounds - 12, 12), 31);
        } else {
            $this->saltRoundCount = $rounds;
        }
    }

    public function resetPassword() {
        $this->hashedPassword = password_hash($this->generateSecureRandomString(12), PASSWORD_BCRYPT, array('cost' => min(max($this->saltRoundCount - 12, 12), 31)));
        invalidateCache(); // invalidate previous password length cache
        logEvent(LOG_INFO, 'Reset password for user ' . $_SERVER['REMOTE_ADDR'] . ' at ' . date(DATE_ISO8601));
    }

    public function logPasswordAttempts($ipAddress, $result) {
        // implement database or file-based logging system
    }

    public function enforceTwoFactorAuthentication() {
        if (verifyCode()) { // verify 2FA code
            return true;
        }
        return false; // failed 2FA verification
    }
}
