import json
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs
import requests
import logging
import os
import socket
import ssl
from concurrent.futures import ThreadPoolExecutor

class RequestHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        self.send_response(200)
        self.end_headers()
        self.wfile.write(b"Hello from Python!")

def create_server(port, host, log_file_path=None, error_mode="default"):
    server_address = (host, port)
    Handler = type("RequestHandler", (RequestHandler,), {})
    httpd = HTTPServer(server_address, Handler)

    if log_file_path:
        logging.basicConfig(filename=log_file_path, level=logging.INFO)
    else:
        logging.basicConfig(level=logging.INFO)

    return httpd

def load_config(config_file):
    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
        return config
    except FileNotFoundError:
        print("Error: Configuration file not found.")
        return None
    except Exception as e:
        print(f"Error loading configuration file: {e}")
        return None

def main():
    import sys

    if len(sys.argv) > 1:
        for arg in sys.argv[1:]:
            if arg.startswith('--port='):
                port = int(arg.split('=')[1])
            elif arg.startswith('--host='):
                host = arg.split('=')[1]
            elif arg.startswith('--log-file-path='):
                log_file_path = arg.split('=')[1]
            elif arg.startswith('--error-mode='):
                error_mode = arg.split('=')[1]

    config_file = "config.json"

    try:
        config = load_config(config_file)
    except Exception as e:
        print(f"Error loading configuration file: {e}")
        return

    if not config:
        sys.exit(1)

    server_port = 8000
    server_host = 'localhost'
    error_mode = "default"

    if port and host and log_file_path and error_mode:
        httpd = create_server(port, host, log_file_path, error_mode)
    else:
        httpd = create_server(server_port, server_host)

    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        print("\nShutting down...")
        httpd.server_close()

if __name__ == "__main__":
    main()
