                file_get_contents("$this->cmsUrl/application-settings?instance=$this->selectedCmsInstance"),
                true
            );
            if ($response) {
                return $response;
            }
        } catch (Exception $e) {
            // fallback to local settings
            return array();
        }
    }

    public function setCacheExpirationTime($time) {
        $this->cacheExpirationTime = $time;
    }
}
