**Queue-Based System**

```csharp
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class MessageProcessorQueue {
    private readonly ILogger _logger;
    private readonly Queue<MessageProcessingRequest> _queue;

    public MessageProcessorQueue(ILogger logger) {
        _logger = logger;
        _queue = new Queue<MessageProcessingRequest>();
    }

    public void EnqueueMessage(string base64EncodedMessage) {
        _queue.Enqueue(new MessageProcessingRequest(base64EncodedMessage));
    }

    public async Task<string> ProcessNextMessageAsync() {
        while (_queue.Count > 0) {
            MessageProcessingRequest request = _queue.Dequeue();
            try {
                string decryptedMessage = await new SecureMessageProcessor().DecryptMessageAsync(request.Message);
                return decryptedMessage;
            } catch (Exception e) {
                // log and retry
                _logger.LogError(e);
                await Task.Delay(1000); // configurable delay
            }
        }
    }
}

public class MessageProcessingRequest {
    public string Message { get; set; }

    public MessageProcessingRequest(string message) {
        Message = message;
    }
}
