const { promisify } = require('util');
const { RateLimiter } = require('limiter');
const { asyncFetch } = require('./async-fetch');
const { cache } = require('./cache');

function asyncArrayReduce(array, initialAccumulator, ...reductionOperations) {
  const rateLimiter = new RateLimiter({
    points: 10,
    duration: 1,
  });

  return async (progressCallback = () => {}) => {
    try {
      const { externalWordList } = await fetchExternalWordList();
      const cachedWordList = cache.get('wordList');
      if (cachedWordList) {
        console.log(`Cache hit for word list.`);
        array.forEach((element, index) => {
          const reducedElement = reductionOperations.reduce(
            (accumulator, operation) =>
              operation(accumulator, element),
            initialAccumulator
          );
          // ...
        });
      } else if (!rateLimiter.remaining()) {
        console.log(`Rate limit exceeded. Waiting for 1 second.`);
        await new Promise((resolve) => setTimeout(resolve, 1000));
      } else {
        const fetchResult = await rateLimiter.consume(() =>
          asyncFetch('https://example.com/word-list')
        );
        if (fetchResult.error) {
          console.log(`Error fetching word list: ${fetchResult.error}`);
        } else {
          cache.set('wordList', fetchResult.data);
          array.forEach((element, index) => {
            const reducedElement = reductionOperations.reduce(
              (accumulator, operation) =>
                operation(accumulator, element),
              initialAccumulator
            );
            // ...
          });
        }
      }

      if (!array.every((element) => !element)) {
        console.log(`Completed reduction process.`);
      } else {
        console.log(`Aborted reduction process due to empty array.`);
      }
    } catch (error) {
      console.error(`Error during reduction: ${error}`);
    } finally {
      progressCallback();
    }
  };

  async function fetchExternalWordList() {
    try {
      const response = await asyncFetch('https://example.com/word-list');
      return JSON.parse(response);
    } catch (error) {
      throw new Error(`Error fetching word list: ${error}`);
    }
  }

  // ...
}

// Example usage:
const array = [...];
const initialAccumulator = 'initial value';
const reductionOperations = [
  (accumulator, element) => accumulator + element,
  (accumulator, element) => accumulator * element,
];

asyncArrayReduce(array, initialAccumulator, ...reductionOperations).then((result) => {
  console.log(result);
});
