const rateLimit = require('rate-limit');

app.use(session({
    store: redisStore,
    secret: 'secret',
    resave: false,
    saveUninitialized: true,
    cookie: { secure: true }
}));

app.use(rateLimit({
    max: 500, // limit to 500 requests per minute
    windowMs: 60000, // 1 minute
    message: 'Too many requests from this IP, please try again in a moment'
}));

const inventory = require('./inventory');
const logisticsProvider = require('./logistics-provider');
const imageConverter = require('./image-converter');

app.get('/products/:id', (req, res) => {
    const productId = req.params.id;
    // get product information from database
    const product = inventory.getProduct(productId);
    if (!product) return res.status(404).send({ error: 'Product not found' });

    // handle concurrent request
    const semaphore = new POSIXSemaphore(1);
    async function getImages() {
        try {
            await semaphore.acquire();
            const images = imageConverter.convert(product.images);
            semaphore.release();
            res.send(images);
        } catch (err) {
            res.status(500).send({ error: 'Failed to retrieve product images' });
        }
    }

    // call third-party logistics provider for shipment tracking
    const shipmentId = logisticsProvider.getShipmentId(productId);
    getImages();

    // automatically restock based on predefined thresholds
    if (product.inventoryLevel < 10) {
        inventory.restock(product.id, 50);
    }
});

app.post('/products/:id', (req, res) => {
    const productId = req.params.id;
    // update product information in database
    inventory.updateProduct(productId, req.body);

    // handle PDF generation from images using a third-party tool
    imageConverter.generatePDF(productId).then((pdf) => {
        res.set('Content-Type', 'application/pdf');
        res.send(pdf);
    }).catch((err) => {
        res.status(500).send({ error: 'Failed to generate product PDF' });
    });
});

