#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_INTS 1000
#define MAX_THREADS 5

int ints[MAX_INTS];
int count = 0;
pthread_mutex_t mutex;

void* readInts(void* arg) {
    int tid = *(int*)arg;
    for(int i = 0; i < 10; i++) {
        pthread_mutex_lock(&mutex);
        ints[count++] = tid * (i + 1);
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

void findLargestInteger() {
    int max = INT_MIN;
    pthread_mutex_lock(&mutex);
    for(int i = 0; i < count; i++) {
        if(ints[i] > max) {
            max = ints[i];
        }
    }
    pthread_mutex_unlock(&mutex);
    printf("The largest integer is %d\n", max);
}

int main() {
    pthread_t threads[MAX_THREADS];
    int thread_args[MAX_THREADS];

    for(int i = 0; i < MAX_THREADS; i++) {
        thread_args[i] = i;
        pthread_create(&threads[i], NULL, readInts, &thread_args[i]);
    }

    for(int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    findLargestInteger();

    return 0;
}

