const express = require('express');
const app = express();
const paymentGatewayAPI = require('stripe');
const { updateOrderStatus } = require('./order-status-updater');
const crypto = require('crypto');

app.use(express.json());

// Initialize the payment gateway API
const stripe = paymentGatewayAPI({
  // Your Stripe secret key
  secretKey: 'YOUR_STRIPE_SECRET_KEY',
});

// Calculate SHA-256 hash of a payment transaction record
function generatePaymentHash(transaction) {
  const hash = crypto.createHash('sha256');
  hash.update(JSON.stringify(transaction));
  return hash.digest('hex');
}

// Process payment and update order status
async function processPaymentAndUpdateOrderStatus(req, res) {
  try {
    const { amount, paymentMethod } = req.body;
    let transaction;

    switch (paymentMethod) {
      case 'credit-card':
        transaction = await stripe.charges.create({
          amount,
          currency: 'usd',
          source: req.body.card,
        });
        break;
      case 'paypal':
        // Handle PayPal payment
        break;
      default:
        res.status(400).send({ message: 'Invalid payment method' });
        return;
    }

    const paymentHash = generatePaymentHash(transaction);
    await updateOrderStatus(req.orderId, paymentMethod);

    res.send({ transactionId: transaction.id, paymentHash });
  } catch (error) {
    if (error.code === 'rate_exceeded') {
      // Handle rate limiting errors
      res.status(429).send({ message: 'Rate limit exceeded. Please try again later.' });
    } else if (error.type === 'invalid_request_error') {
      // Handle invalid payment information errors
      res.status(400).send({ message: 'Invalid payment information' });
    } else {
      // Handle other errors, such as network failures or API integration issues
      res.status(500).send({ message: 'An error occurred. Please try again later.' });
    }
  }
}

// Endpoint for processing payments and updating order status
app.post('/process-payment', processPaymentAndUpdateOrderStatus);

module.exports = app;
