import json
from io import BytesIO
from urllib.parse import urlparse, urlunparse

class Script:
    def __init__(self, src, fallback=None):
        self.src = src
        self.fallback = fallback
        self.loaded = False

def generate_footer(scripts, fallback_content):
    footer = ""
    for script in scripts:
        if not script.loaded and (not fallback_content or script.fallback is None):
            footer += f"<script src='{script.src}'></script>"
        elif script.fallback is not None:
            footer += f"{script.fallback}"
    return footer

class CDNService:
    def __init__(self, base_url):
        self.base_url = base_url
        self.cached_scripts = {}

    def get_script(self, src):
        if src in self.cached_scripts:
            return self.cached_scripts[src]
        response = BytesIO()
        # Make HTTP request and cache the script
        response.write(b"<script>alert('Hello!');</script>")
        self.cached_scripts[src] = response.getvalue()
        return response.getvalue()

class FooterGenerator:
    def __init__(self, scripts, fallback_content):
        self.scripts = scripts
        self.fallback_content = fallback_content

    def generate(self):
        for script in self.scripts:
            if not script.loaded and (not self.fallback_content or script.fallback is None):
                # Render loading spinner
                print("<div>Loading...</div>")
        footer = generate_footer(self.scripts, self.fallback_content)
        return footer

    def load_script(self, src):
        response = CDNService("https://cdn.example.com/").get_script(src)
        if response:
            script = Script(response.decode(), fallback=self.fallback_content)
            self.scripts.append(script)
            return True
        return False

    def health_check(self):
        for script in self.scripts:
            if not script.loaded and (not self.fallback_content or script.fallback is None):
                # Render loading spinner
                print("<div>Loading...</div>")
        return all(script.loaded for script in self.scripts)

# Example usage:
scripts = [Script("script1.js"), Script("script2.js")]
fallback_content = "No JavaScript, using fallback content."
footer_generator = FooterGenerator(scripts, fallback_content)
footer = footer_generator.generate()
print(footer)
