use reqwest::{blocking::get, header};
use std::{
    error::Error,
    sync::Arc,
};

pub struct HttpClient {
    client: Arc<reqwest::Client>,
}

impl HttpClient {
    pub async fn new(disable_certificate_validation: bool) -> Result<Self, Box<dyn Error>> {
        let client = Arc::new(reqwest::Client::builder())
            .timeout_read(None)
            .timeout_write(None)
            .redirect(true)
            .build()?;

        if disable_certificate_validation {
            // Set certificate verification to false
            client.set_verify(false);
        }

        Ok(HttpClient { client })
    }

    pub async fn get(&self, url: &str) -> Result<reqwest::Response, Box<dyn Error>> {
        let mut builder = self.client.get(url);

        if let Some(headers) = get_custom_headers() {
            for (key, value) in headers {
                builder.header(key.as_str(), value);
            }
        }

        Ok(builder.send().await?)
    }

    // Other methods to set custom headers, timeouts, and handle redirects
}

// Example method to set custom headers
fn get_custom_headers() -> Option<Vec<(header::HeaderName, String)>> {
    // Implement your logic here to return the custom headers as a vector of tuples
    Some(vec![("X-Custom-Header".to_string(), "custom-value".to_string())])
}
