import json
import requests
import logging

class PushNotificationModule:
    def __init__(self):
        self.protocols = {'apns': 'https://api.push.apple.com', 'fcm': 'https://fcm.googleapis.com'}
        self.cache = {}

    def select_protocol(self, device_type):
        if device_type == 'ios':
            return 'apns'
        elif device_type == 'android':
            return 'fcm'
        else:
            raise ValueError('Unknown device type')

    def send_notification(self, device_token, message, protocol='auto'):
        if protocol == 'auto':
            protocol = self.select_protocol(device_token.split(':')[0])

        auth_header = f'Bearer YOUR_API_KEY'  # Replace with your API key

        try:
            response = requests.post(f'{self.protocols[protocol]}/messages', headers={'Authorization': auth_header}, json={'message': message})
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException as e:
            logging.error(f'Error sending notification: {e}')
            return None

    def cache_notification(self, device_token, message):
        self.cache[device_token] = {'message': message}
