```
import json
import os
import yaml
from functools import lru_cache
from threading import Lock
from typing import Dict, Any, Type

class JSONBase:
    _registry: Dict[str, Type['JSONBase']]
    _lock = Lock()

    def __init__(self):
        self._registry = {}

    @classmethod
    def load_yaml_registry(cls, file_path: str) -> None:
        with open(file_path, 'r') as f:
            registry_data = yaml.safe_load(f)
            for factory_id, subclass_info in registry_data.items():
                cls.register_subclass(factory_id, subclass_info['module'], subclass_info['class'])

    @classmethod
    def save_registry(cls, file_path: str) -> None:
        with open(file_path, 'w') as f:
            yaml.safe_dump({factory_id: {'module': subclass.__module__, 'class': subclass.__name__} for factory_id, subclass in cls._registry.items()}, f)

    @classmethod
    def register_subclass(cls, factory_id: str, module_name: str, subclass_type: Type['JSONBase']) -> None:
        with cls._lock:
            if factory_id not in cls._registry:
                cls._registry[factory_id] = subclass_type

    @classmethod
    def discover_subclasses(cls, directory: str) -> None:
        for root, dirs, files in os.walk(directory):
            for file in files:
                if file.startswith('json_'):
                    module_name = f'{root}.{file[:-5]}'
                    with open(os.path.join(root, file), 'r') as f:
                        subclass_data = yaml.safe_load(f)
                        cls.register_subclass(subclass_data['id'], module_name, type('', (), **subclass_data))

    @classmethod
    def to_json(cls, data: Any) -> str:
        return json.dumps(data)

    @classmethod
    @lru_cache(maxsize=None)
    def from_json(cls, json_string: str) -> 'JSONBase':
        try:
            data = json.loads(json_string)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON string: {str(e)}")
        return cls._registry.get(data['factory_id']).from_json_data(data)

    @classmethod
    def get_subclass(cls, factory_id: str) -> Type['JSONBase']:
        if factory_id not in cls._registry:
            raise ValueError(f"Unknown factory ID: {factory_id}")
        return cls._registry[factory_id]

    @classmethod
    def clean_up_registry(cls) -> None:
        for factory_id, subclass_type in list(cls._registry.items()):
            if any(instance is not None for instance in [getattr(subclass, 'instance', None) for name, subclass in locals().items() if isinstance(subclass, type) and subclass.__name__ == subclass_type.__name__]):
                continue
            cls._registry.pop(factory_id)

    @classmethod
    def get_registry(cls) -> Dict[str, Type['JSONBase']]:
        return cls._registry

