using System.Threading.Tasks;

public class WebsiteManager
{
    private readonly IConfigurationDatabase _configDb;
    private readonly ILogger _logger;

    public WebsiteManager(IConfigurationDatabase configDb, ILogger logger)
    {
        _configDb = configDb;
        _logger = logger;
    }

    public async Task AddWebsiteAsync(string directoryPath)
    {
        if (!Directory.Exists(directoryPath))
        {
            throw new DirectoryNotFoundException($"The directory '{directoryPath}' does not exist.");
        }

        var websiteConfig = await GetWebsiteConfigAsync(directoryPath);
        if (websiteConfig == null)
        {
            // Generate default config and prompt user to review
            _logger.Warn($"No web.config found in directory '{directoryPath}'. Generating default configuration...");
            // Generate default config...
            // Prompt user to review...
        }

        try
        {
            await StartWebsiteAsync(directoryPath, websiteConfig);
        }
        catch (Exception ex)
        {
            _logger.Error(ex, $"Failed to start website at '{directoryPath}'.");
            throw;
        }
    }

    private async Task<WebsiteConfig> GetWebsiteConfigAsync(string directoryPath)
