// Load Balancing (using Node.js cluster module)
const { Worker } = require('worker_threads');

function loadBalance(workers) {
  const workerPool = new WorkerPool(workers);

  function distributeWork(taskQueue) {
    while (taskQueue.length > 0) {
      const task = taskQueue.shift();
      workerPool.nextAvailableWorker().then((worker) => {
        worker.postMessage(task);
      });
    }
  }

  // ...
}

class WorkerPool {
  constructor(numWorkers) {
    this.workers = [];
    for (let i = 0; i < numWorkers; i++) {
      this.workers.push(new Worker());
    }
  }

  nextAvailableWorker() {
    return new Promise((resolve, reject) => {
      let availableWorkerIndex = -1;
      for (let i = 0; i < this.workers.length; i++) {
        if (!this.workers[i].isBusy()) {
          availableWorkerIndex = i;
          break;
        }
      }

      if (availableWorkerIndex === -1) {
        setTimeout(() => resolve(this.nextAvailableWorker()), 0);
      } else {
        resolve(this.workers[availableWorkerIndex]);
      }
    });
  }
}
