public class KafkaLogProcessor {
    private static final Logger logger = LoggerFactory.getLogger(KafkaLogProcessor.class);
    private Map<String, Function<JSONObject, ?> metricExtractors;
    private JedisPool jedisPool;
    private KafkaProducer<String, String> kafkaProducer;
    private RateLimiter rateLimiter;

    public KafkaLogProcessor(JedisPool jedisPool, KafkaProducer<String, String> kafkaProducer) {
        this.jedisPool = jedisPool;
        this.kafkaProducer = kafkaProducer;
        this.metricExtractors = new HashMap<>();
    }

    public void processLogs() {
        try (KafkaConsumer<String, String> consumer = createKafkaConsumer()) {
            consumer.subscribe(Collections.singleton("your_topic_name"));
            while (true) {
                ConsumerRecords<String, String> records = consumer.poll(Duration.ofSeconds(1));
                for (ConsumerRecord<String, String> record : records) {
                    try {
                        JSONObject log = new JSONObject(record.value());
                        for (String metricName : getMetricsToExtract()) {
                            Function<JSONObject, ?> extractor = metricExtractors.get(metricName);
                            if (extractor != null) {
                                Object value = extractor.apply(log);
                                // Process and store the extracted value in Redis
                                jedisPool.getResource().set("metric:" + metricName, JSONValue.toJSONString(value));
                                kafkaProducer.send("your_target_topic", "message with extracted value");
                            }
                        }
                    } catch (Exception e) {
                        logger.error("Error processing log: {}", e.getMessage());
                    }
                }
                consumer.commitSync();
            }
        } catch (Exception e) {
            // Retry mechanism for failed Kafka fetches
            retryKafkaFetch(e);
        }
    }

    private KafkaConsumer<String, String> createKafkaConsumer() {
        // Configure Kafka consumer properties
        Properties props = new Properties();
        props.put("bootstrap.servers", "your_kafka_broker");
        props.put("key.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        props.put("value.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        return new KafkaConsumer<>(props);
    }

    private List<String> getMetricsToExtract() {
        // Implement dynamic metric definition and retrieval
        // ...
    }

    private void retryKafkaFetch(Exception e) {
        // Configure backoff strategy for retries
        ExponentialBackoffStrategy backoff = new ExponentialBackoffStrategy();
        for (int i = 0; i < 3; i++) {
            try {
                processLogs(); // Try processing logs again
                return;
            } catch (Exception e2) {
                if (i >= 2) {
                    logger.error("Maximum retries exceeded. Quitting.", e);
                    System.exit(1);
                }
                backoff.sleep();
            }
        }
    }

    public void addMetricExtractor(String metricName, Function<JSONObject, ?> extractor) {
        this.metricExtractors.put(metricName, extractor);
    }

    public void startProcessing() {
        // Start processing logs
        processLogs();
    }
}
