const fs = require('fs');
const path = require('path');
const logging = require('./logging');

function fetchAndProcessFiles({
  serverUrl,
  filePaths,
  extensions = ['*'],
  concurrency = 5,
  retries = 3,
  backoffTime = 5000,
  cacheDuration = 60 * 1000
}) {
  const promises = [];
  let cachedFiles = {};

  async function processFile(file) {
    if (cachedFiles[file]) return caching.load(cachedFiles, file);

    try {
      const fileBuffer = await fs.promises.readFile(file, { encoding: 'utf8' });
      const fileContent = fileBuffer.toString();

      // process file content here
      console.log(`Processed file: ${file}`);

      cachedFiles[file] = caching.store(fileContent);
    } catch (error) {
      if (retries > 0) {
        setTimeout(() => processFile(file), backoffTime);
      } else {
        logging.error('Failed to retrieve or process file:', error);
      }
    }
  }

  async function fetchFiles() {
    for await (const file of fs.promises.readdir(serverUrl, { withFileTypes: true })) {
      const filePath = path.join(serverUrl, file.name);

      if (!extensions.includes(path.extname(filePath).slice(1)) || !file.isFile()) continue;

      promises.push(processFile(filePath));
    }
  }

  async function main() {
    await fetchFiles();

    try {
      await Promise.all(promises);
    } catch (error) {
      logging.error('Error processing files:', error);
    }
  }

  main();
}

module.exports = { fetchAndProcessFiles };
