import asyncio
import aiohttp

async def fetch_profile(session, user_id):
    try:
        async with session.get(f'https://api.example.com/user/{user_id}') as response:
            if response.status == 200:
                return await response.json()
            else:
                raise Exception('API returned an error')
    except aiohttp.ClientError:
        return None

async def process_profiles(user_ids, initial_value, callback):
    async with aiohttp.ClientSession() as session:
        tasks = [fetch_profile(session, user_id) for user_id in user_ids]
        profiles = await asyncio.gather(*tasks)

        accumulated_value = initial_value
        reduced_profiles = []

        for profile in profiles:
            if profile is not None:
                if callback(accumulated_value, profile['user_id'], profile):
                    reduced_profiles.append(profile)
                accumulated_value += 1

    return reduced_profiles

def main():
    user_ids = [1, 2, 3, 4, 5]
    initial_value = 0
    def my_callback(value, user_id, profile):
        if profile['name'].startswith('A'):
            print(f'Fetched profile for {user_id}: {profile}')
            return True
        else:
            return False

    loop = asyncio.get_event_loop()
    result = loop.run_until_complete(process_profiles(user_ids, initial_value, my_callback))
    print(result)

if __name__ == "__main__":
    main()
