class BibleTextAnalyzer {
  static readonly OLD_TESTAMENT = new RegExp('\\b' + ['Genesis', 'Exodus', 'Leviticus', 'Numbers', 'Deuteronomy', 'Joshua', 'Judges', 'Ruth', '1 Samuel', '2 Samuel', '1 Kings', '2 Kings', '1 Chronicles', '2 Chronicles', 'Ezra', 'Nehemiah', 'Esther', 'Job', 'Psalms', 'Proverbs', 'Ecclesiastes', 'Song of Solomon', 'Isaiah', 'Jeremiah', 'Lamentations', 'Ezekiel', 'Daniel', 'Hosea', 'Joel', 'Amos', 'Obadiah', 'Jonah', 'Micah', 'Nahum', 'Habakkuk', 'Zephaniah', 'Haggai', 'Zechariah', 'Malachi'].join('\\b|'), 'i');
  static readonly NEW_TESTAMENT = new RegExp('\\b' + ['Matthew', 'Mark', 'Luke', 'John', 'Acts', 'Romans', '1 Corinthians', '2 Corinthians', 'Galatians', 'Ephesians', 'Philippians', 'Colossians', '1 Thessalonians', '2 Thessalonians', '1 Timothy', '2 Timothy', 'Titus', 'Philemon', 'Hebrews', 'James', '1 Peter', '2 Peter', '1 John', '2 John', '3 John', 'Jude', 'Revelation'].join('\\b|'), 'i');

  static analyzeText(text) {
    if (!text || typeof text !== 'string') {
      throw new Error('Invalid input: expected a string');
    }

    const oldTestamentBooks = this.OLD_TESTAMENT.exec(text);
    const newTestamentBooks = this.NEW_TESTAMENT.exec(text);

    const bookCounts = {};

    if (oldTestamentBooks) {
      for (const book of oldTestamentBooks) {
        bookCounts[book] = (bookCounts[book] || 0) + 1;
      }
    }

    if (newTestamentBooks) {
      for (const book of newTestamentBooks) {
        bookCounts[book] = (bookCounts[book] || 0) + 1;
      }
    }

    return bookCounts;
  }
}
