const net = require('net');
const { createInterface } = require('readline');
const { rateLimit } = require('p-lint');
const log4js = require('log4js');

// Set up logging
log4js.configure({
  appenders: [
    {
      type: 'console',
      layout: { pattern: ':date :level [${loggerName}]: %m%n' },
    },
  ],
});
const logger = log4js.getLogger('server');
const log = (message) => logger.info(message);

// Set up rate limiting
const rl = createInterface({
  input: process.stdin,
  output: process.stdout,
});

let cache = {};
let connectionCount = 0;
let maxConnections = 100;

const server = net.createServer((socket) => {
  // Handle new connections
  socket.on('connect', () => {
    log(`New connection from ${socket.remoteAddress}`);
    connectionCount++;

    // Rate limit connections
    if (connectionCount > maxConnections) {
      socket.end();
      return;
    }
  });

  socket.on('data', (data) => {
    // Handle incoming data
    const message = data.toString();
    log(`Received message from ${socket.remoteAddress}: ${message}`);

    // Update cache
    cache[socket.remoteAddress] = message;

    // Check for client disconnection
    socket.on('end', () => {
      log(`Client disconnected: ${socket.remoteAddress}`);
      delete cache[socket.remoteAddress];
      connectionCount--;
    });
  });

  socket.on('error', (err) => {
    // Handle errors
    log(`Error from ${socket.remoteAddress}: ${err.message}`);
    socket.end();
  });

  socket.on('close', () => {
    // Handle client disconnection
    log(`Client disconnected: ${socket.remoteAddress}`);
    delete cache[socket.remoteAddress];
    connectionCount--;
  });
});

// Set up rate limiting for new connections
const limiter = rateLimit({
  points: 10, // Limit to 10 connections per minute
  duration: 1, // Minute
});

server.on('connection', (socket) => {
  // Apply rate limiting for new connections
  limiter(socket.remoteAddress);
});

// Start the server
server.listen(3000, () => {
  log(`Server listening on port 3000`);
});

// Implement graceful shutdown
process.on('SIGINT', () => {
  log('Shutting down...');
  server.close(() => {
    log('All connections closed');
    process.exit();
  });
});
