// Function to convert image file to PDF and update environment variable
int manage_log_files(const char *file_name, const char *output_file_name, const char *format) {
    // Create log file path
    char log_file[256];
    sprintf(log_file, log_file_path, file_name, format);

    // Convert image to PDF using third-party tool
    if (system((char *)sprintf("%s %s -o %s", tool_name, file_name, output_file_name) ) != 0) {
        return 1; // Error during conversion
    }

    // Update environment variable pointing to current log file
    setenv("LOG_FILE", log_file, 1);

    return 0;
}

// Function to run cleanup process and remove old log files
void run_cleanup() {
    // Read configuration file
    FILE *config_file = fopen(CONFIG_FILE, "r");
    if (!config_file) {
        return; // Configuration file not found
    }

    int max_log_files = MAX_LOG_FILES;
    char path_format[256];

    while (fgets(path_format, sizeof(path_format), config_file)) {
        // Parse configuration file and set variables
        // ...
    }

    fclose(config_file);

    // Remove old log files based on modification timestamps
    DIR *dir = opendir(".");
    if (!dir) {
        return; // Error opening directory
    }

    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL) {
        char file_name[256];
        sprintf(file_name, "%s-%s.log", ent->d_name, "pdf");

        struct stat file_stat;
        if (stat(file_name, &file_stat) == 0) {
            // Check if log file is still referenced by environment variable
            if (!strcmp(getenv("LOG_FILE"), file_name)) {
                // Remove old log file
                unlink(file_name);
            }
        }

        closedir(dir);
    }
}

