from PIL import Image

class ProfileImageCacher:
    def __init__(self):
        self.redis = redis.Redis(host='localhost', port=6379, db=0)
        self.s3 = boto3.client('s3')
        self.image_sizes = {'avatar': (200, 200), 'banner': (800, 400)}

    def get_image(self, user_id: str, image_type: str) -> Any:
        cache_key = f'{user_id}:{image_type}'
        cached_image = self.redis.get(cache_key)
        if cached_image:
            return cached_image

        s3_response = self.s3.get_object(Bucket='your-bucket', Key=f'images/{user_id}/{image_type}.jpg')
        if s3_response['ResponseMetadata']['HTTPStatusCode'] == 200:
            image_data = s3_response['Body'].read()
            self.redis.set(cache_key, image_data)
            return Image.open(BytesIO(image_data))

    def update_image(self, user_id: str, image_type: str) -> None:
        cache_key = f'{user_id}:{image_type}'
        if not self.redis.exists(cache_key):
            return

        s3_response = self.s3.get_object(Bucket='your-bucket', Key=f'images/{user_id}/{image_type}.jpg')
        if s3_response['ResponseMetadata']['HTTPStatusCode'] == 200:
            image_data = s3_response['Body'].read()
            self.redis.set(cache_key, image_data)
        else:
            self.redis.delete(cache_key)

    def invalidate_image(self, user_id: str) -> None:
        for image_type in self.image_sizes:
            cache_key = f'{user_id}:{image_type}'
            if self.redis.exists(cache_key):
                self.redis.delete(cache_key)
