def cache_hit_or_miss(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        if 'cache_key' in kwargs:
            cache_key = kwargs['cache_key']
        else:
            cache_key = None
        result = func(*args, **kwargs)
        if cache_key is not None:
            if cache.get(cache_key) is None:
                # Cache miss, store the result
                cache.set(cache_key, result, timeout=3600)  # 1 hour TTL
            else:
                # Cache hit, retrieve the cached result
                result = cache.get(cache_key)
        return result
    return wrapper

@app.route('/image/<username>')
@cache_hit_or_miss
def get_image(username):
    if current_user.username != username:
        return 'Unauthorized', 401
    image_url = s3.generate_presigned_url('get_object',
                                           Params={'Bucket': 'your-bucket-name', 'Key': f'profile/{username}/avatar.png'},
                                           ExpiresIn=3600)  # 1 hour expiration
    if cache.get(f'avatar:{username}') is None:
        # Cache miss, download the image from S3 and store it in Redis
        s3.download_file('your-bucket-name', f'profile/{username}/avatar.png', 'temp_avatar.png')
        with open('temp_avatar.png', 'rb') as f:
            redis_client.set(f'avatar:{username}', f.read())
    return redirect(image_url)

