    cache_key = f'{username}:{size}'
    if redis_client.get(cache_key) is None:
        # Cache miss, resize the image and store it in Redis
        image_data = s3.download_file('your-bucket-name', image_path, 'temp_image.png')
        with open('temp_image.png', 'rb') as f:
            resized_image_data = Image.open(f).resize(image_sizes[size], Image.LANCZOS).tobytes()
        redis_client.set(cache_key, resized_image_data)
    return redirect(f'{cdn_domain}/{username}/{size}.png')

