const app = express();
const Stripe = require('stripe')('YOUR_STRIPE_SECRET_KEY');
const PayPal = require('paypal-rest-sdk');

app.use(express.json());

// Process payment and update order status
async function processPaymentAndUpdateOrderStatus(paymentMethod, paymentDetails) {
  try {
    // Determine the payment gateway based on the method
    let paymentGateway;
    switch (paymentMethod) {
      case 'credit_card':
        paymentGateway = Stripe;
        break;
      case 'paypal':
        paymentGateway = PayPal;
        break;
      default:
        throw new Error('Unsupported payment method');
    }

    // Create a charge request for the payment gateway
    const chargeRequest = {
      amount: paymentDetails.amount,
      currency: 'usd',
      source: paymentDetails.card.number,
      expiration_month: paymentDetails.card.expirationMonth,
      expiration_year: paymentDetails.card.expirationYear,
    };

    // Process the payment asynchronously
    await paymentGateway.charges.create(chargeRequest);

    // Update order status in database
    // ( omitted for brevity, assume a function to update order status )

  } catch (error) {
    console.error(error);
  }
}

// Rate limiting mechanism using Redis
const redis = require('ioredis');
app.use((req, res, next) => {
  const rateLimit = req.ip;
  if (!redis.get(rateLimit)) {
    redis.set(rateLimit, '1', { EX: 60 }); // 1 request per minute
  }
  next();
});

// API endpoint for processing payments
app.post('/process-payment', (req, res) => {
  const paymentMethod = req.body.payment_method;
  const paymentDetails = req.body.payment_details;

  processPaymentAndUpdateOrderStatus(paymentMethod, paymentDetails)
    .then(() => res.json({ message: 'Payment processed successfully' }))
    .catch((error) => res.status(500).json({ error }));
});
