using System;
using System.IO;
using UnityEngine;

public class ValueGenerator : IDisposable
{
    private float minFloat;
    private float maxFloat;
    private int minInt;
    private int maxInt;
    private Vector3 minVector;
    private Vector3 maxVector;
    private long seed;
    private bool loggingEnabled;
    private string logFilePath;

    public ValueGenerator(float minFloat, float maxFloat, int minInt = 0, int maxInt = 100, Vector3 minVector = default(Vector3), Vector3 maxVector = default(Vector3), long seed = 1)
    {
        this.minFloat = minFloat;
        this.maxFloat = maxFloat;
        this.minInt = minInt;
        this.maxInt = maxInt;
        this.minVector = minVector;
        this.maxVector = maxVector;
        this.seed = seed;
        loggingEnabled = true;
        logFilePath = "random_values.log";
    }

    public float GenerateRandomFloat()
    {
        return UnityEngine.Random.Range(minFloat, maxFloat);
    }

    public int GenerateRandomInt()
    {
        return UnityEngine.Random.Range(minInt, maxInt + 1);
    }

    public Vector3 GenerateRandomVector()
    {
        return new Vector3(UnityEngine.Random.Range(minVector.x, maxVector.x), UnityEngine.Random.Range(minVector.y, maxVector.y), UnityEngine.Random.Range(minVector.z, maxVector.z));
    }

    public override string ToString()
    {
        return $"Range: ({minFloat}, {maxFloat}) for float, ({minInt}, {maxInt}) for int, and ({minVector}, {maxVector}) for vector";
    }

    public void Dispose()
    {
        loggingEnabled = false;
    }

    private void LogRandomValue(float value)
    {
        if (!loggingEnabled) return;

        try
        {
            using (StreamWriter writer = File.AppendText(logFilePath))
            {
                writer.WriteLine($"Timestamp: {DateTime.Now}, Value: {value}");
            }
        }
        catch (Exception ex)
        {
            Debug.LogError("Error while logging random value:", ex);
        }
    }

    public void LogGeneratedValues()
    {
        if (!loggingEnabled) return;

        try
        {
            using (StreamWriter writer = File.AppendText(logFilePath))
            {
                writer.WriteLine($"Timestamp: {DateTime.Now}, Random Float Value: {GenerateRandomFloat()}");
                writer.WriteLine($"Timestamp: {DateTime.Now}, Random Int Value: {GenerateRandomInt()}");
                writer.WriteLine($"Timestamp: {DateTime.Now}, Random Vector Value: {GenerateRandomVector()}");
            }
        }
        catch (Exception ex)
        {
            Debug.LogError("Error while logging generated random values:", ex);
        }
    }

    public void SaveGeneratedValuesInCompressedFormat()
    {
        // Implement compression logic here
    }
}
