import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class MultiCommandExecutor {

    private static final int MAX_RETRIES = 3;
    private static final long RETRY_DELAY_MILLIS = 1000; // 1 second

    public static void main(String[] args) {
        List<Command> commands = new ArrayList<>();
        commands.add(new Command("mkdir", "mydir"));
        commands.add(new Command("touch", "myfile.txt"));
        commands.add(new Command("ls", "-l"));

        executeCommands(commands);
    }

    private static void executeCommands(List<Command> commands) {
        try (Process process;
             BufferedReader in = new BufferedReader(new InputStreamReader(process.getInputStream()));
             BufferedReader err = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {

            for (Command command : commands) {
                System.out.println("Executing command: " + command.getName());
                if (!deleteFileIfExist(command.getFileName())) {
                    System.out.println("Failed to delete file: " + command.getFileName());
                }

                int retries = 0;
                while (retries < MAX_RETRIES) {
                    try {
                        process = Runtime.getRuntime().exec(command.getName(), null);
                        in.readLines(process.getInputStream()).forEach(line -> System.out.println(line));
                        err.readLines(process.getErrorStream()).forEach(line -> System.out.println("Error: " + line));
                        break;
                    } catch (IOException e) {
                        if (retries >= MAX_RETRIES - 1) {
                            System.err.println("Command execution failed after " + MAX_RETRIES + " retries. Aborting.");
                            return;
                        }
                        try {
                            Thread.sleep(RETRY_DELAY_MILLIS);
                        } catch (InterruptedException ex) {
                            Thread.currentThread().interrupt();
                        }
                    }
                    retries++;
                }

                // Log command execution result in database
                logCommandResult(command.getName(), process.exitValue() == 0);

                System.out.println("Command executed successfully.");
            }
        } catch (IOException e) {
            System.err.println("Error executing commands: " + e.getMessage());
        }
    }

    private static boolean deleteFileIfExist(String fileName) {
        // Implement file deletion logic here
        return false;
    }

    private static void logCommandResult(String commandName, boolean isSuccess) {
        // Implement database logging logic here
    }
}

