import java.io.*;
import java.util.concurrent.*;

public class StateLoader {
    private static final Logger logger = LoggerFactory.getLogger(StateLoader.class);
    private static final int MAX_CACHE_SIZE = 1000;
    private Map<String, MoSTState> cache = new ConcurrentHashMap<>();
    private ExecutorService executor = Executors.newSingleThreadExecutor();
    private StateService stateService;

    public MoSTState loadStateFromFile(String stateId) {
        MoSTState state = (MoSTState) getStateFromCache(stateId);
        if (state != null) {
            return state;
        }

        try {
            state = (MoSTState) getStateFromDisk(stateId);
        } catch (Exception e) {
            logger.error("Error loading state from file: {}", e.getMessage());
            return null;
        }
    }

    private MoSTState getStateFromCache(String stateId) {
        return cache.getOrDefault(stateId, null);
    }

    private MoSTState getStateFromDisk(String stateId) {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream("states/" + stateId + ".ser"))) {
            return (MoSTState) ois.readObject();
        } catch (IOException e) {
            logger.error("Error reading object from file: {}", e.getMessage());
            return null;
        }
    }

    public void startSync() {
        executor.submit(() -> syncCache());
    }

    private void syncCache() {
        while (true) {
            try {
                Map<String, MoSTState> updatedStates = stateService.getUpdatedStates();
                for (Map.Entry<String, MoSTState> entry : updatedStates.entrySet()) {
                    if (!cache.containsKey(entry.getKey())) {
                        cache.put(entry.getKey(), entry.getValue());
                    } else if (isOutdated(entry.getKey(), entry.getValue())) {
                        cache.remove(entry.getKey());
                    }
                }

                logger.info("Cache synced with external service");
            } catch (Exception e) {
                logger.error("Error syncing cache: {}", e.getMessage);
            }

            try {
                Thread.sleep(10000); // sync every 10 seconds
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private boolean isOutdated(String stateId, MoSTState state) {
        // implement your logic to check if the state is outdated here
        return false;
    }
}
