```c
#include <semaphore.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

#define QUEUE_CAPACITY 10
#define NUM_PRODUCERS 5
#define NUM_CONSUMERS 3

typedef struct {
    char* url;
} FileUpload;

sem_t queueSem, producerSem, consumerSem;
pthread_mutex_t mutex;
int queueSize = 0;
FileUpload* queue[QUEUE_CAPACITY];
pthread_t producers[NUM_PRODUCERS], consumers[NUM_CONSUMERS];

void* producerThread(void* arg) {
    int i = *(int*)arg;
    for (int j = 0; j < 10; j++) {
        sem_wait(&producerSem);
        pthread_mutex_lock(&mutex);
        FileUpload fileUpload;
        fileUpload.url = malloc(100);
        sprintf(fileUpload.url, "file_%d.txt", i * j);
        queue[queueSize++] = &fileUpload;
        pthread_mutex_unlock(&mutex);
        sem_post(&queueSem);
    }
    free(arg);
    return NULL;
}

void* consumerThread(void* arg) {
    int i = *(int*)arg;
    while (1) {
        sem_wait(&queueSem);
        pthread_mutex_lock(&mutex);
        if (queueSize > 0) {
            FileUpload* fileUpload = queue[--queueSize];
            pthread_mutex_unlock(&mutex);
            char* url = fileUpload->url;
            // Upload the file using a library of your choice
            printf("Uploading file %s...\n", url);
            free(fileUpload->url);
        } else {
            sem_post(&queueSem);
            break;
        }
    }
    free(arg);
    return NULL;
}

int main() {
    sem_init(&queueSem, 0, 1);
    sem_init(&producerSem, 0, NUM_PRODUCERS);
    sem_init(&consumerSem, 0, NUM_CONSUMERS);

    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < QUEUE_CAPACITY; i++) {
        queue[i] = NULL;
    }

    int* producerArgs[NUM_PRODUCERS];
    int* consumerArgs[NUM_CONSUMERS];

    for (int i = 0; i < NUM_PRODUCERS; i++) {
        producerArgs[i] = malloc(sizeof(int));
        *(producerArgs[i]) = i;
        pthread_create(&producers[i], NULL, producerThread, producerArgs[i]);
    }

    for (int i = 0; i < NUM_CONSUMERS; i++) {
        consumerArgs[i] = malloc(sizeof(int));
        *(consumerArgs[i]) = i;
        pthread_create(&consumers[i], NULL, consumerThread, consumerArgs[i]);
    }

    // Wait for all threads to finish
    for (int i = 0; i < NUM_PRODUCERS; i++) {
        pthread_join(producers[i], NULL);
    }
    for (int i = 0; i < NUM_CONSUMERS; i++) {
        pthread_join(consumers[i], NULL);
    }

    // Terminate all threads
    for (int i = 0; i < QUEUE_CAPACITY; i++) {
        if (queue[i] != NULL) {
            free(queue[i]->url);
        }
    }

    sem_destroy(&queueSem);
    sem_destroy(&producerSem);
    sem_destroy(&consumerSem);

    return 0;
}

