const pokeApi = require('poke-api');
const { Pool } = require('pg');

class PokemonReducer {
  constructor(maxConcurrentRequests = 5) {
    this.pool = new Pool({
      user: 'your_username',
      host: 'your_host',
      database: 'your_database',
      port: 5432,
      maxConnections: maxConcurrentRequests,
    });
    this.typeCache = {};
    this.nameCache = {};
  }

  async reduce(arr, callback) {
    if (!Array.isArray(arr)) throw new Error('Invalid input: array expected');
    if (arr.length === 0) return;

    let currentPage = 1;
    const chunkSize = 50; // adjust according to your needs

    const cachePokemonData = async (pokemon) => {
      try {
        const response = await pokeApi.getPokemon(pokemon.name);
        this.typeCache[pokemon.name] = response.type;
        this.nameCache[pokemon.name] = response.name;
      } catch (err) {
        console.error(err);
      }
    };

    const handlePokemon = async (pokemon) => {
      try {
        await cachePokemonData(pokemon);
        switch (this.typeCache[pokemon.name]) {
          case 'grass':
            // implement logic for grass-type Pokémon
            break;
          case 'fire':
            // implement logic for fire-type Pokémon
            break;
          default:
            // handle unknown or other types
        }
      } catch (err) {
        console.error(err);
      }
    };

    const reducePage = async (page) => {
      const chunk = arr.slice((page - 1) * chunkSize, page * chunkSize);
      await Promise.all(chunk.map(handlePokemon));
    };

    for (let i = Math.ceil(arr.length / chunkSize); i > 0; i--) {
      try {
        await reducePage(i);
      } catch (err) {
        console.error(err);
      }
    }

    callback(null, arr.reduce((acc, pokemon) => ({ ...acc }), {}));
  }

  cancel() {
    this.pool.end();
  }

  logProgress(current, total) {
    console.log(`Reducing Pokémon array... (${current} of ${total})`);
  }
}

module.exports = PokemonReducer;
