#include <semaphore.h>
#include <pthread.h>
#include <mysql/mysql.h>
#include <messaging_queue.h>
#include <config_parser.h>

// Configuration variables
int SEMAPHORE_DEFAULT_VALUE = 0;
int SEMAPHORE_MAX_LIMIT = 100;

// Database connection
MYSQL *db_conn;

// Messaging queue instance
messaging_queue_t *queue;

// Semaphore management structure
semaphore_t {
    int value; // current semaphore value
    int max_limit; // maximum allowed value
    pthread_mutex_t lock; // distributed locking mechanism
    sem_t sem_id; // semaphore identifier
};

// Function to create a new semaphore with initial value and max limit
void create_semaphore(int value, int max_limit) {
    // Create a new semaphore structure
    semaphore_t *sem = malloc(sizeof(semaphore_t));
    sem->value = value;
    sem->max_limit = max_limit;

    // Initialize the distributed locking mechanism
    pthread_mutex_init(&sem->lock, NULL);

    // Create the semaphore identifier
    sem_id = sem_open("/my_semaphore", O_CREAT | O_EXCL, 0644);
    if (sem_id == SEM_FAILED) {
        perror("Error creating semaphore");
        exit(1);
    }

    // Store the semaphore structure in the database
    db_query("INSERT INTO semaphores SET value = %d, max_limit = %d", value, max_limit);

    // Add the semaphore to the messaging queue for asynchronous communication
    queue_enqueue(queue, sem);
}

// Function to delete a semaphore
void delete_semaphore(int semaphore_id) {
    // Lock the semaphore structure
    pthread_mutex_lock(&sem->lock);

    // Decrease the reference count of the semaphore
    int ref_count = db_query("SELECT COUNT(*) FROM semaphore_references WHERE semaphore_id = %d", semaphore_id);
    if (ref_count > 0) {
        // If there are still references to the semaphore, do not delete it
        pthread_mutex_unlock(&sem->lock);
        return;
    }

    // Delete the semaphore identifier
    sem_close(sem_id);

    // Remove the semaphore structure from the database and messaging queue
    db_query("DELETE FROM semaphores WHERE id = %d", semaphore_id);
    queue_dequeue(queue, semaphore_id);

    pthread_mutex_unlock(&sem->lock);
}

// Function to manipulate a semaphore value
void set_semaphore_value(int semaphore_id, int new_value) {
    // Lock the semaphore structure
    pthread_mutex_lock(&sem->lock);

    // Check if the new value is within the allowed range
    if (new_value < 0 || new_value > sem->max_limit) {
        perror("Error: New value out of range");
        exit(1);
    }

    // Update the semaphore value and notify other nodes
    sem->value = new_value;
    queue_broadcast(queue, SEMAPHORE_UPDATED);

    pthread_mutex_unlock(&sem->lock);
}

// Function to get the current semaphore value
int get_semaphore_value(int semaphore_id) {
    // Lock the semaphore structure
    pthread_mutex_lock(&sem->lock);

    // Return the current semaphore value
    int value = sem->value;

    pthread_mutex_unlock(&sem->lock);
    return value;
}

// Web-based interface for managing semaphore operations
void web_interface() {
    // Create a web server and handler functions
    httpd_t *httpd;
    http_handler_t *handler;

    // Define the URL patterns for managing semaphores
    char *patterns[] = {"semaphores", "create_semaphore", "delete_semaphore", "set_semaphore_value"};

    // Start the web server
    httpd_start(httpd);

    // Listen for incoming requests and handle them accordingly
    while (1) {
        http_request_t *req;
        req = httpd_accept_request(httpd);
        if (req != NULL) {
            handler(req);
        }
    }

    // Stop the web server when done
    httpd_stop(httpd);
}

int main() {
    // Initialize the database connection and messaging queue instance
    db_conn = mysql_init(NULL);
    queue = messaging_queue_create();

    // Create a new semaphore with initial value and max limit
    create_semaphore(SEMAPHORE_DEFAULT_VALUE, SEMAPHORE_MAX_LIMIT);

    // Start the web-based interface for managing semaphore operations
    web_interface();

    return 0;
}
