        logger = logging.getLogger('file_merger')
        file_handler = logging.FileHandler(self.log_file_path)
        formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
        file_handler.setFormatter(formatter)
        logger.addHandler(file_handler)
        return logger

    def merge_files(self, source_paths, destination_path):
        with ThreadPoolExecutor() as executor:
            futures = []
            for source_path in source_paths:
                futures.append(executor.submit(self.read_file, source_path))

            merged_data = b''
            for future in futures:
                merged_data += future.result()

            self.write_to_destination(merged_data, destination_path)

    def read_file(self, file_path):
        try:
            with open(file_path, 'rb') as f:
                return f.read()
        except OSError as e:
            self.logger.error(f"Error reading file {file_path}: {e}")
            raise

    def write_to_destination(self, data, destination_path):
        try:
            with open(destination_path, 'wb') as f:
                f.write(data)
        except OSError as e:
            self.logger.error(f"Error writing to destination {destination_path}: {e}")
            raise

class FileMergerCLI:
    def __init__(self, file_merger):
        self.file_merger = file_merger

    def run(self):
        while True:
            try:
                source_paths = input("Enter the paths of files to merge (comma-separated): ")
                destination_path = input("Enter the desired destination path: ")

                if not source_paths or not destination_path:
                    self.file_merger.logger.error("Invalid input. Please provide valid file paths and destination.")
                else:
                    source_paths = [path.strip() for path in source_paths.split(',')]
                    self.file_merger.merge_files(source_paths, destination_path)
                    break
            except KeyboardInterrupt:
                print("\nMerge process interrupted.")
                break
            except Exception as e:
                self.file_merger.logger.error(f"An error occurred: {e}")
                continue

if __name__ == "__main__":
    log_file_path = 'file_merger.log'
    file_merger = FileMerger(log_file_path)
    cli = FileMergerCLI(file_merger)
    cli.run()
