```python
import json
from datetime import datetime
from uuid import UUID
from decimal import Decimal

class JSONSerializable:
    registry = {}

    @classmethod
    def add_factory_function(cls, id, factory_func):
        cls.registry[id] = factory_func

    @classmethod
    def create_instance_from_id(cls, id, data):
        if id in cls.registry:
            return cls.registry[id](data)
        else:
            raise ValueError(f"Unsupported ID: {id}")

    @classmethod
    def to_json(cls, obj):
        return json.dumps(obj, default=lambda o: {
            'datetime': str(o) if isinstance(o, datetime) else None,
            'uuid': str(o) if isinstance(o, UUID) else None,
            'decimal': str(o) if isinstance(o, Decimal) else None,
            '__class__': type(o).__name__,
        })

    @classmethod
    def from_json(cls, json_str):
        data = json.loads(json_str)
        if data.get('__class__'):
            cls_name = data.pop('__class__')
            return getattr(JSONSerializable.create_instance_from_id(cls_name, data), 'from_dict')(data)
        else:
            raise ValueError("Invalid JSON object")
