public class ImageOptimizer {
    public void optimizeImageCompression(String inputImagePath, long targetFileSize, int maxAllowedQualityReduction) throws IOException {
        // Load the image
        BufferedImage image = ImageIO.read(new File(inputImagePath));

        // Determine the original file size and quality
        long originalFileSize = new File(inputImagePath).length();
        int originalQuality = getOriginalImageQuality(image);

        // Initialize the best compression settings found so far
        double bestCompressionRatio = 1.0;
        int bestCompressionQuality = originalQuality;
        String bestCompressionFormat = null;

        // Try different compression formats and qualities
        List<String> compressionFormats = new ArrayList<>();
        compressionFormats.add("JPEG");
        compressionFormats.add("PNG");
        for (String format : compressionFormats) {
            try {
                // Set the image compression settings based on the format
                BufferedImage compressedImage = setImageCompression(image, format);

                // Calculate the compressed file size and quality
                long compressedFileSize = new File(inputImagePath + "." + format).length();
                int compressedQuality = getCompressedImageQuality(compressedImage);

                // Check if we've met or exceeded the target file size while maintaining acceptable quality
                if (compressedFileSize <= targetFileSize && isAcceptableCompressionQuality(compressedQuality, maxAllowedQualityReduction)) {
                    // Update the best compression settings found so far
                    bestCompressionRatio = getCompressionRatio(originalFileSize, compressedFileSize);
                    bestCompressionQuality = compressedQuality;
                    bestCompressionFormat = format;
                }
            } catch (IOException e) {
                // Handle errors and exceptions during image compression
                System.out.println("Error compressing image: " + e.getMessage());
            }
        }

        // Save the optimally compressed image to the specified output path
        if (bestCompressionFormat != null) {
            File outputFile = new File(inputImagePath + "_" + bestCompressionFormat);
            ImageIO.write(compressedImage, bestCompressionFormat, outputFile);
            System.out.println("Optimized image saved: " + outputFile.getAbsolutePath());
        } else {
            System.out.println("Failed to optimize image compression. Original file will be used.");
        }
    }

