#include <semaphore.h>
#include <openssl/aes.h>

// Semaphore Management System Functions

sem_t* createSemaphore(const char* name) {
    sem_t* sem = sem_open(name, O_CREAT | O_RDWR, S_IRUSR | S_IWUSR, 1);
    if (sem == SEM_FAILED) {
        sem_close(sem);
        return NULL;
    }
    return sem;
}

int deleteSemaphore(sem_t* sem) {
    return sem_close(sem);
}

void incrementSemaphore(sem_t* sem) {
    sem_post(sem);
}

void decrementSemaphore(sem_t* sem) {
    sem_wait(sem);
}

sem_t* getSemaphore(const char* name) {
    sem_t* sem = sem_open(name, O_RDWR | O_NONBLOCK);
    if (sem == SEM_FAILED) {
        return NULL;
    }
    return sem;
}

// Dynamic Trim and Capitalize Function

char* dynamicTrimAndCapitalize(char* inputStr, int maxLength) {
    // Fetch word list asynchronously
    char* wordList = fetchWordList();

    int totalChars = 0;
    for (int i = 0; wordList[i]; i++) {
        totalChars += strlen(wordList + i) + 1;
    }
    int adjustedMaxLength = maxLength - totalChars / averageWordLength(wordList);
    if (adjustedMaxLength < 0) return NULL;

    char* trimmedStr = trimWords(inputStr, wordList);
    for (int i = 0; trimmedStr[i]; i++) {
        trimmedStr[i] = toupper(trimmedStr[i]);
    }
    return trimmedStr;
}

// OpenSSL Function

EVP_CIPHER_CTX* encryptString(const char* inputStr, const char* key) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    AES_context aes_ctx;
    aes_ctx.key = (unsigned char*)key;
    aes_ctx.length = strlen(key);

    int cipherLen = strlen(inputStr);
    unsigned char* cipherBytes = (unsigned char*)malloc(cipherLen + 1);
    EVP_EncryptInit_ex(ctx, &aes_ctx, inputStr, cipherBytes);
    if (!EVP_EncryptUpdate(ctx, cipherBytes, cipherLen)) {
        free(cipherBytes);
        return NULL;
    }

    return ctx;
}
