import json
import boto3
from redis import StrictRedis
from datetime import datetime, timedelta

class CacheManager:
    def __init__(self, s3_bucket_name):
        self.s3 = boto3.client('s3')
        self.redis_client = StrictRedis(host='localhost', port=6379, db=0)
        self.config = None
        self.memory_budget = 1024 * 1000000  # 1 GB

    def get_config(self):
        if not self.config:
            config_file = self.s3.get_object(Bucket=self.s3_bucket_name, Key='cache_config.json')['Body'].read().decode('utf-8')
            self.config = json.loads(config_file)
        return self.config

    def update_config(self):
        self.config = None
        self.get_config()

    def put_object(self, key, value, expiration=3600):  # 1 hour default
        if not isinstance(value, bytes):
            value = json.dumps(value).encode('utf-8')
        if len(value) > self.memory_budget:
            return False  # memory exceeded, eviction needed
        try:
            self.redis_client.setex(key, expiration, value)
            return True
        except Exception as e:
            print(f"Error putting object {key}: {e}")
            return False

    def get_object(self, key):
        try:
            value = self.redis_client.get(key).decode('utf-8')
            if not value:
                return None  # cache miss
            return json.loads(value)
        except Exception as e:
            print(f"Error getting object {key}: {e}")
            return None

    def delete_object(self, key):
        try:
            self.redis_client.delete(key)
            return True
        except Exception as e:
            print(f"Error deleting object {key}: {e}")
            return False

    def evict_object(self, key):
        try:
            self.redis_client.expire(key, 1)  # expire immediately
            return True
        except Exception as e:
            print(f"Error evicting object {key}: {e}")
            return False

    def manage_cache(self):
        while True:
            config = self.get_config()
            if not config:
                continue  # no config, skip update
            for key in list(self.redis_client.keys()):
                if int(self.redis_client.get(key).decode('utf-8')) < time.time():
                    self.evict_object(key)
            if not self.config or 'cache_purge' not in self.config:
                continue  # no purge config, skip
            purge_keys = [key for key in list(self.redis_client.keys())]
            for key in purge_keys:
                if self.config['cache_purge'].get('age', None) and int(self.redis_client.get(key).decode('utf-8')) > self.config['cache_purge']['age']:
                    self.evict_object(key)
            break
        print(f"Cache managed at {datetime.now()}")
```

