```python
from flask import Flask, request, jsonify
import requests
from pyjwt import JWT
from functools import lru_cache

app = Flask(__name__)

# Load configuration from environment variables or a config file
OAUTH_PROVIDERS = {
    "github": {"client_id": "YOUR_GITHUB_CLIENT_ID", "client_secret": "YOUR_GITHUB_CLIENT_SECRET"},
    # Add more providers here...
}
SECRET_KEY = "YOUR_SECRET_KEY"

@lru_cache(maxsize=128)  # Cache user profiles for performance
def get_user_profile(oauth_token):
    # Make API call to fetch user profile using validated OAuth token
    headers = {"Authorization": f"Bearer {oauth_token}"}
    response = requests.get("https://example.com/user/profile", headers=headers)
    return response.json()

def generate_jwt(user_profile):
    # Generate JWT with custom claims (roles, expiration time, etc.)
    payload = {
        "sub": user_profile["username"],
        "name": user_profile["name"],
        "email": user_profile["email"],
        "roles": ["admin", "user"],  # Example roles
        "exp": int(time.time() + 3600)  # Expiration time (1 hour)
    }
    jwt = JWT(payload, SECRET_KEY)
    return jwt.encode()

@app.route("/auth", methods=["POST"])
def authenticate():
    try:
        oauth_token = request.json["oauth_token"]
        provider = request.json["provider"]

        if provider not in OAUTH_PROVIDERS:
            return jsonify({"error": "Unsupported OAuth provider"}), 400

        # Validate OAuth access token
        auth_response = requests.post(
            f"https://api.{provider}.com/oauth/access_token",
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            data={"grant_type": "client_credentials", "client_id": OAUTH_PROVIDERS[provider]["client_id"], "client_secret": OAUTH_PROVIDERS[provider]["client_secret"]},
        )
        if auth_response.status_code != 200:
            return jsonify({"error": "Invalid OAuth token"}), 401

        # Fetch user profile using validated OAuth token
        user_profile = get_user_profile(oauth_token)

        # Generate JWT with user's profile information and custom claims
        jwt = generate_jwt(user_profile)
        return jsonify({"jwt": jwt})

    except Exception as e:
        app.logger.error(f"Authentication failed: {str(e)}")
        return jsonify({"error": "Internal Server Error"}), 500

if __name__ == "__main__":
    app.run(debug=True, port=8000)
```
