using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading;

public class EncryptionHandler
{
    public static string DecryptAndValidate(string encryptedMessage, string key, string iv)
    {
        try
        {
            // Convert Base64-encoded message to byte array
            var decodedBytes = Convert.FromBase64String(encryptedMessage);

            // Initialize Triple DES encryption provider with the given key and IV
            using var tripleDesProvider = new TripleDESCryptoServiceProvider { Key = Convert.FromBase64String(key), IV = Convert.FromBase64String(iv) };

            // Decrypt message using Triple DES
            var decryptedBytes = decrypt(tripleDesProvider, decodedBytes);

            // Initialize HMAC SHA256 provider with the same key
            using var hmacProvider = new HMACSHA256 { Key = Convert.FromBase64String(key) };

            // Compute HMAC signature over decrypted message
            var hmacSignature = computeHmac(hmacProvider, decryptedBytes);

            // Validate HMAC signature against expected value (not implemented for brevity)
            // ...

            // Return decrypted message as a string if HMAC validation passes
            return Encoding.UTF8.GetString(decryptedBytes);
        }
        catch (Exception ex)
        {
            throw new AuthenticationException("Decryption or authentication failed", ex);
        }
    }

    private static byte[] decrypt(TripleDESCryptoServiceProvider provider, byte[] encryptedBytes)
    {
        using var ms = new MemoryStream();
        using var cs = new CryptoStream(ms, provider.CreateDecryptor(), CryptoStreamMode.Write);

        cs.Write(encryptedBytes, 0, encryptedBytes.Length);
        cs.FlushFinalBlock();

        return ms.ToArray();
    }

    private static byte[] computeHmac(HMACSHA256 hmacProvider, byte[] message)
    {
        using var ms = new MemoryStream();
        using var cs = new CryptoStream(ms, hmacProvider, CryptoStreamMode.Write);

        cs.Write(message, 0, message.Length);
        cs.FlushFinalBlock();

        return ms.ToArray();
    }
}
