function manageClinicOperations($operationType, $clinicId, $data = []) {
    // Initialize rate limiting variables
    $ipAddress = $_SERVER['REMOTE_ADDR'];
    $lastOperationTime = 0;
    $maxOperationsPerHour = 100;

    switch ($operationType) {
        case 'create':
            // Create a new clinic record
            createClinic($data);
            break;
        case 'update':
            // Update an existing clinic record
            updateClinic($clinicId, $data);
            break;
        case 'delete':
            // Delete an existing clinic record
            deleteClinic($clinicId);
            break;
    }

    function createClinic($data) {
        if (rateLimitCheck($ipAddress)) {
            return json_encode(['error' => 'Rate limit exceeded. Please try again after 1 hour.']);
        }

        // Create a new clinic record
        $dbConnection = dbConnect();
        $query = "INSERT INTO clinics SET name=?, status='open', location=?, capacity=?";
        $stmt = $dbConnection->prepare($query);
        $stmt->execute([$data['name'], $data['location'], $data['capacity']]);

        // Update patient scheduling system
        updateSchedulingSystem();
    }

    function updateClinic($clinicId, $data) {
        if (rateLimitCheck($ipAddress)) {
            return json_encode(['error' => 'Rate limit exceeded. Please try again after 1 hour.']);
        }

        // Update an existing clinic record
        $dbConnection = dbConnect();
        $query = "UPDATE clinics SET status=?, lastModifiedIP=? WHERE id=?";
        $stmt = $dbConnection->prepare($query);
        $stmt->execute([$data['status'], $_SERVER['REMOTE_ADDR'], $clinicId]);

        // Update patient scheduling system if clinic status changes
        if ($data['status'] == 'closed' || $data['status'] == 'emergency') {
            updateSchedulingSystem();
            notifyEmergencyResponseTeam();
            notifyExternalAPIService($data);
        }
    }

    function deleteClinic($clinicId) {
        // Delete an existing clinic record
        $dbConnection = dbConnect();
        $query = "DELETE FROM clinics WHERE id=?";
        $stmt = $dbConnection->prepare($query);
        $stmt->execute([$clinicId]);

        // Remove associated patient bookings
        removeBookings($clinicId);
    }

    function rateLimitCheck($ipAddress) {
        $lastOperationTime = getLastOperationTime($ipAddress);
        if ($lastOperationTime + 3600 < time()) {
            return false;
        }

        $operationsPerHour = getOperationsPerHour($ipAddress);
        if ($operationsPerHour >= $maxOperationsPerHour) {
            return true;
        }

        updateOperationsCount($ipAddress, 1);
