And here's the Python script for processing CSV files:

```python
import csv
import argparse

def process_csv_files(input_file_names, output_file_name, column_names, separator=',', filter_condition=None):
    with open(output_file_name, 'w') as output_file:
        writer = csv.writer(output_file)

        for file_name in input_file_names:
            try:
                with open(file_name, 'r') as file:
                    reader = csv.reader(file, delimiter=separator)

                    if column_names:
                        header = next(reader)
                        if not set(column_names).issubset(set(header)):
                            raise ValueError("Invalid column names")

                    for row in reader:
                        if filter_condition and not eval(filter_condition, {'row': row}):
                            continue

                        writer.writerow([col_val for col_name, col_val in zip(column_names, row)])
            except (FileNotFoundError, csv.Error) as e:
                print(f"Error processing file {file_name}: {e}")

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Process CSV files")
    parser.add_argument('-i', '--input_file_names', type=str, nargs='+', required=True)
    parser.add_argument('-o', '--output_file_name', type=str, required=True)
    parser.add_argument('-c', '--column_names', type=str, nargs='+')
    parser.add_argument('-s', '--separator', type=str, default=',')
    parser.add_argument('-f', '--filter_condition', type=str)

    args = parser.parse_args()

    process_csv_files(args.input_file_names, args.output_file_name, args.column_names, separator=args.separator, filter_condition=args.filter_condition)

