function asyncReduceArray(arr, initialValue, callback) {
  let accumulator = initialValue;
  let attempts = 0;

  return new Promise((resolve, reject) => {
    (async () => {
      try {
        for await (let num of arr) {
          attempts = 0;
          while (true) {
            try {
              accumulator = callback(accumulator, num);
              break;
            } catch (error) {
              if (attempts < 5) {
                setTimeout(() => {
                  console.error(`Retry attempt ${attempts + 1} failed: ${error}`);
                  attempts++;
                  asyncReduceArray(arr, initialValue, callback).then(resolve, reject);
                }, Math.pow(2, attempts) * 1000);
              } else {
                throw error;
              }
            }
          }
        }
        resolve(accumulator);
      } catch (error) {
        reject(error);
      }
    })();
  });
}

class ProcessedTransactionResult {
  constructor(weightSum, transactionId) {
    this.weightSum = weightSum;
    this.transactionId = transactionId;
  }
}

