struct JsonSerializable<T> {
    value: T,
}

impl<T> JsonSerializable<T>
where
    T: Serialize + DeserializeOwned,
{
    fn to_json(&self) -> String {
        let serializable = self.value;
        serde_json::to_string_pretty(&serializable).unwrap()
    }

    fn from_json(json_str: &str) -> Self {
        let json = json_str.parse::<serde_json::Value>().unwrap();
        JsonSerializable { value: json } as Self
    }
}

struct FactoryRegistry {
    factories: std::collections::HashMap<String, Box<dyn Fn() -> Box<dyn Any + Send>>>,
}

impl FactoryRegistry {
    fn new() -> Self {
        FactoryRegistry {
            factories: std::collections::HashMap::new(),
        }
    }

    fn add_factory(&mut self, id: &str, factory: Box<dyn Fn() -> Box<dyn Any + Send>>) {
        self.factories.insert(id.to_string(), factory);
    }

    fn get_factory(&self, id: &str) -> Option<Box<dyn Fn() -> Box<dyn Any + Send>>> {
        self.factories.get(id).cloned()
    }
}

fn main() {
