from typing import Dict, List
from enum import Enum

class DeviceType(Enum):
    ANDROID = 1
    iOS = 2

class NotificationService:
    def __init__(self, api_keys: Dict[str, str], cache_duration: int):
        self.api_keys = api_keys
        self.cache_duration = cache_duration
        self.cache: Dict[str, Dict] = {}

    def get_notification_service(self, device_type: DeviceType) -> 'NotificationService':
        if device_type == DeviceType.ANDROID:
            return AndroidNotificationService(self.api_keys)
        elif device_type == DeviceType.iOS:
            return IosNotificationService(self.api_keys)
        else:
            raise ValueError("Unsupported device type")

    def send_notification(self, device_type: DeviceType, token: str, message: str) -> bool:
        service = self.get_notification_service(device_type)

        if token in self.cache and (self.cache_duration - (int(time.time()) - self.cache[token]['timestamp'])) > 0:
            return service.send_notification(token, message, self.cache[token])

        try:
            response = service.send_notification(token, message)
            if response.status_code == 200:
                self.cache[token] = {'message': message, 'timestamp': int(time.time())}
                return True
        except Exception as e:
            logging.error(f"Error sending notification: {e}")
            if token in self.cache:
                del self.cache[token]

        return False

class AndroidNotificationService(NotificationService):
    def send_notification(self, token: str, message: str) -> requests.Response:
        # FCM API implementation
        pass

class IosNotificationService(NotificationService):
    def send_notification(self, token: str, message: str) -> requests.Response:
        # APNs API implementation
        pass

class OneSignalNotificationService(NotificationService):
    def send_notification(self, token: str, message: str) -> requests.Response:
        # OneSignal API implementation
        pass

if __name__ == "__main__":
