#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define LOG_FILE "log.txt"
#define CHUNK_SIZE 4096
#define MAX_FIELDS 10

typedef struct {
    char ip[16];
    time_t request_time;
    int response_code;
} LogEntry;

int process_log(const char *file_path) {
    FILE *fp = fopen(file_path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening file: %s\n", file_path);
        return 1;
    }

    LogEntry *entry;
    size_t total_entries = 0;

    while (1) {
        char buffer[CHUNK_SIZE];
        size_t read = fread(buffer, 1, CHUNK_SIZE, fp);
        if (ferror(fp)) {
            fprintf(stderr, "Error reading file: %s\n", file_path);
            fclose(fp);
            return 1;
        }

        // Process each line in the chunk
        for (size_t i = 0; i < read; i++) {
            buffer[i] = '\0';  // Null-terminate the string

            entry = malloc(sizeof(LogEntry));
            if (!entry) {
                fprintf(stderr, "Memory allocation failed\n");
                fclose(fp);
                return 1;
            }

            // Extract fields from each line
            char *fields[MAX_FIELDS];
            size_t num_fields = 0;
            char *token = strtok(buffer + i, ", ");
            while (token && num_fields < MAX_FIELDS) {
                fields[num_fields] = token;
                token = strtok(NULL, ", ");
                num_fields++;
            }

            // Convert IP address to numeric form
            inet_pton(AF_INET, fields[0], entry->ip);

            // Process the rest of the fields
            // ...

            // Print the processed line in comma-separated format
            printf("%s, %ld, %d", entry->ip, entry->request_time, entry->response_code);

            // Calculate and print the average response time
            // ...

            free(entry);
        }
    }

    fclose(fp);
    return 0;
}

int main() {
    process_log(LOG_FILE);
    return 0;
}
