    // Main conversion method with multi-threading support
    void convertAndSave(const std::string& inputFile, const std::string& outputFile, const std::string& format, int qualitySettings = 0);

    // Get the status of the conversion process
    Status getConversionStatus() { return status; }

    // Report progress and intermediate status messages
    int reportProgress(int percentage) {
        if (percentage > 100)
            percentage = 100;
        currentPercentage = percentage;
        return currentPercentage;
    }

    // Cancel ongoing conversions
    void cancelConversions() {
        mutex.lock();
        while (conversionsRunning > 0) {
            --conversionsRunning;
        }
        mutex.unlock();
    }

    // Set quality settings for different image formats
    void setQualitySettings(int compressionLevel, int transparencyOption) {}

private:
    Status status = Status::SUCCESS;
    int currentPercentage = 0;

    std::mutex mutex;   // Mutex for thread-safe access
    std::vector<std::thread> threads;  // Thread pool
    std::map<std::string, bool> conversionsRunning;  // Map of ongoing conversions
    int maximumConversions;                  // Maximum number of concurrent conversions
};

