#include <iostream>
#include <json/json.h>
#include <memory>

class Settings {
public:
    std::shared_ptr<Settings> load(const std::string& filePath) {
        // Load JSON data from file
        std::ifstream ifs(filePath);
        if (!ifs.is_open()) {
            throw std::runtime_error("Failed to open file");
        }
        Json::Value root;
        ifs >> root;
        ifs.close();

        // Create and validate settings
        _settings = std::make_shared<JsonSettings>(root);

        return _settings;
    }

    const std::string& get(const std::string& key) {
        if (_settings->get(key).isNull()) {
            throw std::runtime_error("Setting not found");
        }
        return _settings->get(key).asString();
    }

    void save() {
        // Save settings to JSON file
        std::ofstream ofs(filePath_);
        if (!ofs.is_open()) {
            throw std::runtime_error("Failed to open file for saving");
        }
        _settings->write(ofs);
        ofs.close();
    }

private:
    class JsonSettings {
    public:
        JsonSettings(const Json::Value& root) : _root(root) {}
        const Json::Value& get(const std::string& key) { return _root[key.c_str()]; }
        void write(std::ofstream& stream) { _root.write(stream); }

    private:
        Json::Value _root;
    };

    std::shared_ptr<JsonSettings> _settings;
    std::string filePath_;
};
