function asyncReduce(arr, initial, callback) {
  const DB_URL = 'https://api.example.com/data';

  let result = initial;
  let error = null;
  let inProgress = 0; // count of ongoing reduce operations

  async function reduce(item, cb) {
    if (Array.isArray(item)) {
      return Promise.all(item.map(i => reduce(i, cb))).then(values => cb(result + values.reduce((a, b) => a + b, 0)));
    } else if (!isNaN(item)) {
      inProgress++;
      const dbResponse = await fetch(DB_URL);
      const data = await dbResponse.json();
      result += item * data.length;
      inProgress--;
      return result;
    } else {
      error = new Error('Non-numeric value encountered');
      return Promise.reject(error);
    }
  }

  function handleError(err) {
    console.error('Error occurred:', err);
    if (error) {
      throw error;
    }
  }

  try {
    arr.forEach(item => reduce(item, callback));
    while (inProgress > 0) await new Promise(resolve => setTimeout(() => resolve(), 1));
    return result;
  } catch (err) {
    handleError(err);
    return null;
  } finally {
    inProgress = 0; // cleanup
  }
}

// Test cases:
async function test() {
  const arr1 = [1, 2, 3];
  const arr2 = [[1, 2], [3, 4]];
  const arr3 = [];

  try {
    console.log(await asyncReduce(arr1, 0, (a, b) => a + b));
    console.log(await asyncReduce(arr2, 0, (a, b) => a + b));
    console.log(await asyncReduce(arr3, 0, (a, b) => a + b));
  } catch (err) {
    console.error(err);
  }
}

test();
