import java.util.*;
import com.google.cloud.tasks.*;

public class DistributedTaskQueue {

    private final TaskQueue taskQueue;
    private final JobScheduler jobScheduler;

    public DistributedTaskQueue(TaskQueue taskQueue, JobScheduler jobScheduler) {
        this.taskQueue = taskQueue;
        this.jobScheduler = jobScheduler;
    }

    public void submitTask(String taskName, String taskPayload) throws Exception {
        try {
            Task task = new Task().setName(taskName).setPayload(taskPayload);
            taskQueue.createTask(task);
            log.info("Task submitted: " + taskName);
        } catch (Exception e) {
            handleSubmissionError(e);
        }
    }

    private void handleSubmissionError(Exception e) throws Exception {
        // implement retry policy here
        throw new Exception("Failed to submit task", e);
    }

    public static class JobScheduler {

        private final Scheduler scheduler;

        public JobScheduler(Scheduler scheduler) {
            this.scheduler = scheduler;
        }

        public void scheduleTask(String taskName, String taskPayload) throws Exception {
            try {
                scheduler.createJob(taskName).setPayload(taskPayload);
                log.info("Task scheduled: " + taskName);
            } catch (Exception e) {
                handleSchedulingError(e);
            }
        }

        private void handleSchedulingError(Exception e) throws Exception {
            // implement retry policy here
            throw new Exception("Failed to schedule job", e);
        }
    }
}
