const { AsyncQueue } = require('async');
const { LRUCache } = require('lru-cache');

function asyncArrayAggregate(arr, initialValue, callback, config) {
  const cache = new LRUCache({ max: 10000 });
  const queue = new AsyncQueue();
  let aggregateValue = initialValue;
  let currentAggregationFunction;

  function executeAggregation(item, index) {
    try {
      if (typeof item === 'string' && !isNaN(Number(item))) {
        item = Number(item);
      }
      if (currentAggregationFunction) {
        aggregateValue = currentAggregationFunction(aggregateValue, item, index);
      } else {
        throw new Error('No aggregation function provided');
      }
    } catch (error) {
      callback(error, null, -1);
    }
  }

  function fetchAndAggregate() {
    return queue.defer(() => {
      const [data, response] = yield asyncFetchApiCall(config.apiEndpoint);
      const cachedResponse = cache.get(response.url);
      if (cachedResponse) {
        data.forEach((item, index) => executeAggregation(item, index));
      } else {
        cache.set(response.url, response);
        data.forEach((item, index) => {
          setTimeout(() => executeAggregation(item, index), config.requestTimeout);
        });
      }
    });
  }

  function asyncFetchApiCall(url) {
    return new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      xhr.open('GET', url, true);
      xhr.onload = () => {
        if (xhr.status === 200) {
          resolve([JSON.parse(xhr.responseText), { url: url }]);
        } else {
          reject(new Error(`Failed to fetch data from ${url}`));
        }
      };
      xhr.onerror = () => {
        reject(new Error('Network error'));
      };
      xhr.send();
    });
  }

  function progressReporter() {
    const completedOperations = arr.length;
    callback(null, aggregateValue, 'completed');
  }

  function throttleFetchAndAggregate() {
    let throttleTimeoutId;
    return queue.defer(() => {
      clearTimeout(throttleTimeoutId);
      throttleTimeoutId = setTimeout(() => {
        fetchAndAggregate();
      }, config.throttleTimeout);
    });
  }

  function startAggregation() {
    if (!currentAggregationFunction) {
      throw new Error('No aggregation function provided');
    }
    for (let i = 0; i < arr.length; i++) {
      executeAggregation(arr[i], i);
    }
    progressReporter();
  }

  config = config || {};
  currentAggregationFunction = config.aggregationFunction;
  startAggregation();
}

module.exports = asyncArrayAggregate;
