<?php

namespace UserAccountManagement;

use Psr\Log\LoggerInterface;
use GuzzleHttp\Client;
use Firebase\JWT\JWT;
use Monolog\Logger;

class UserAccountManagementService {
    private $dbConnectionPool;
    private $logger;
    private $paymentGatewayApi;
    private $emailVerificationService;
    private $jwtSecretKey;
    private $rateLimitingConfig;

    public function __construct(
        LoggerInterface $logger,
        DBConnectionPool $dbConnectionPool,
        PaymentGatewayAPI $paymentGatewayApi,
        EmailVerificationService $emailVerificationService,
        JWT $jwt,
        RateLimiter $rateLimiter
    ) {
        $this->logger = $logger;
        $this->dbConnectionPool = $dbConnectionPool;
        $this->paymentGatewayApi = $paymentGatewayApi;
        $this->emailVerificationService = $emailVerificationService;
        $this->jwtSecretKey = $jwt->getSecretKey();
        $this->rateLimitingConfig = $rateLimiter->getConfig();
    }

    public function createAccount(Request $request) {
        // Validate request data
        if (!$request->hasValidEmail() || !$request->hasValidPassword()) {
            return json_encode(['status' => 'error', 'message' => 'Invalid email or password']);
        }

        // Verify email address through third-party service
        if (!$this->emailVerificationService->verify($request->getEmail())) {
            return json_encode(['status' => 'error', 'message' => 'Invalid email address']);
        }

        // Create user account in database
        $user = new User();
        $user->setEmail($request->getEmail());
        $user->setPassword($request->getPassword());
        $this->dbConnectionPool->saveUser($user);

        // Generate JWT token for the new user
        $jwtToken = JWT::encode(['id' => $user->getId()], $this->jwtSecretKey);

        return json_encode([
            'status' => 'success',
            'message' => 'User account created successfully',
            'data' => [
                'id' => $user->getId(),
                'name' => $request->getName(),
                'email' => $request->getEmail(),
                'role' => 'new_user'
            ]
        ]);
    }

    public function updateAccount(Request $request) {
        // Validate request data
        if (!$request->hasValidEmail() || !$request->hasValidPassword()) {
            return json_encode(['status' => 'error', 'message' => 'Invalid email or password']);
        }

        // Verify email address through third-party service
        if (!$this->emailVerificationService->verify($request->getEmail())) {
            return json_encode(['status' => 'error', 'message' => 'Invalid email address']);
        }

        // Update user account in database
        $user = $this->dbConnectionPool->getUserById($request->getId());
        $user->setEmail($request->getEmail());
        $user->setPassword($request->getPassword());
        $this->dbConnectionPool->saveUser($user);

        // Generate JWT token for the updated user
        $jwtToken = JWT::encode(['id' => $user->getId()], $this->jwtSecretKey);

        return json_encode([
            'status' => 'success',
            'message' => 'User account updated successfully',
            'data' => [
                'id' => $user->getId(),
                'name' => $request->getName(),
                'email' => $request->getEmail(),
                'role' => $user->getRole()
            ]
        ]);
    }

    public function deleteAccount(Request $request) {
        // Validate request data
        if (!$request->hasValidId()) {
            return json_encode(['status' => 'error', 'message' => 'Invalid user ID']);
        }

        // Delete user account from database
        $this->dbConnectionPool->deleteUser($request->getId());

        return json_encode([
            'status' => 'success',
            'message' => 'User account deleted successfully'
        ]);
    }

    public function getAccount(Request $request) {
        // Validate request data
        if (!$request->hasValidId()) {
            return json_encode(['status' => 'error', 'message' => 'Invalid user ID']);
        }

        // Retrieve user account from database
        $user = $this->dbConnectionPool->getUserById($request->getId());

        if (!$user) {
            return json_encode(['status' => 'error', 'message' => 'User not found']);
        }

        return json_encode([
            'status' => 'success',
            'message' => 'User account retrieved successfully',
            'data' => [
                'id' => $user->getId(),
                'name' => $user->getName(),
                'email' => $user->getEmail(),
                'role' => $user->getRole()
            ]
        ]);
    }

    public function authenticate(Request $request) {
        // Validate request data
        if (!$request->hasValidEmail() || !$request->hasValidPassword()) {
            return json_encode(['status' => 'error', 'message' => 'Invalid email or password']);
        }

        // Verify user credentials through authentication system
        if (!$this->authenticateSystem->verify($request->getEmail(), $request->getPassword())) {
            return json_encode(['status' => 'error', 'message' => 'Invalid email or password']);
        }

        // Generate JWT token for the authenticated user
        $jwtToken = JWT::encode(['id' => $user->getId()], $this->jwtSecretKey);

        return json_encode([
            'status' => 'success',
            'message' => 'User authenticated successfully',
            'data' => [
                'id' => $user->getId(),
                'name' => $user->getName(),
                'email' => $user->getEmail(),
                'role' => $user->getRole()
            ]
        ]);
    }

    public function processPayment(Request $request) {
        // Validate request data
        if (!$request->hasValidId()) {
            return json_encode(['status' => 'error', 'message' => 'Invalid user ID']);
        }

        // Process payment through payment gateway API
        if (!$this->paymentGatewayApi->process($request->getAmount())) {
            return json_encode(['status' => 'error', 'message' => 'Payment failed']);
        }

        // Update user account in database
        $user = $this->dbConnectionPool->getUserById($request->getId());
        $user->setBalance($user->getBalance() + $request->getAmount());
        $this->dbConnectionPool->saveUser($user);

        return json_encode([
            'status' => 'success',
            'message' => 'Payment processed successfully'
        ]);
    }

    public function sendVerificationEmail(Request $request) {
        // Validate request data
        if (!$request->hasValidId()) {
            return json_encode(['status' => 'error', 'message' => 'Invalid user ID']);
        }

        // Send email verification through third-party service
        if (!$this->emailVerificationService->send($request->getId())) {
            return json_encode(['status' => 'error', 'message' => 'Failed to send verification email']);
        }

        return json_encode([
            'status' => 'success',
            'message' => 'Verification email sent successfully'
        ]);
    }
}

