import json
import os
import requests
from threading import Thread

class HashFunction:
    def __init__(self, name, func):
        self.name = name
        self.func = func

def load_javascript_files(config_file):
    try:
        with open(config_file) as f:
            config = json.load(f)
    except FileNotFoundError:
        print("Configuration file not found")
        return []

    files = []
    for file in config['files']:
        if os.path.exists(file):
            files.append(file)
        else:
            print(f"File {file} not found")

    dependencies = {}
    for file in config['files']:
        with open(file) as f:
            deps = json.load(f)['dependencies']
            for dep in deps:
                if dep not in dependencies:
                    dependencies[dep] = []
                dependencies[dep].append(file)

    def load_file(file):
        try:
            with requests.get(file, stream=True) as r:
                if r.status_code == 200:
                    js_files.append(file)
                    print(f"Loaded {file}")
                else:
                    print(f"Failed to load {file} (status code: {r.status_code})")
        except Exception as e:
            print(f"Error loading {file}: {str(e)}")

    js_files = []
    for file in files:
        Thread(target=load_file, args=(file,)).start()

    return dependencies

def sort_hash_functions(hash_functions):
    hash_functions.sort(key=lambda x: x.name)

def extract_sequence_number(line):
    parts = line.split(':')
    if len(parts) == 2 and parts[0].isdigit():
        return int(parts[0])
    return None

def load_json_file(file):
    try:
        with open(file) as f:
            data = json.load(f)
        return data
    except FileNotFoundError:
        print(f"File {file} not found")
        return {}

def cache_invalidate(cache, file):
    if file in cache:
        del cache[file]

def main():
    config_file = "config.json"
    js_files = load_javascript_files(config_file)

    hash_functions_file = "hash_functions.txt"
    with open(hash_functions_file) as f:
        lines = f.readlines()
    hash_functions = [HashFunction(line.strip(), None) for line in lines]
    sort_hash_functions(hash_functions)
    sequence_number = extract_sequence_number(lines[-1].strip())
    print(f"Last sequence number: {sequence_number}")

if __name__ == "__main__":
    main()
