            _timer = new Timer(TimerCallback, null, TimeSpan.Zero, TimeSpan.FromMilliseconds(100));
        }

        public void LoadSettings()
        {
            try
            {
                var config = ConfigurationManager.AppSettings;
                TileSize = int.Parse(config["TileSize"]);
                WorldDimensions = new Vector3D(float.Parse(config["WorldWidth"]), float.Parse(config["WorldHeight"]), float.Parse(config["WorldDepth"]));
                CameraSpeed = float.Parse(config["CameraSpeed"]);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error loading settings: {ex.Message}");
            }
        }

        public void UpdateSettings(string settingName, string value)
        {
            try
            {
                ConfigurationManager.AppSettings[settingName] = value;
                LoadSettings();
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error updating setting '{settingName}': {ex.Message}");
            }
        }

        public void Dispose()
        {
            _timer.Change(Timeout.Infinite, Timeout.Infinite);
        }

        private void TimerCallback(object state)
        {
            try
            {
                LoadSettings();
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error updating settings: {ex.Message}");
            }
        }
    }

    public class Vector3D
    {
        public float X { get; set; }
        public float Y { get; set; }
        public float Z { get; set; }

        public Vector3D(float x, float y, float z)
        {
            X = x;
            Y = y;
            Z = z;
        }
    }
}
