)

const (
	maxAttempts = 3
	retryDelay = 1 * time.Second
)

type Product struct {
	ID        string `json:"id"`
	Name      string `json:"name"`
	Description string `json:"description"`
	Price     float64 `json:"price"`
}

func main() {
	// Initialize database and redis connections
	db, err := sql.Open("postgres", "user:password@localhost/database")
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	redisClient := redis.NewClient(&redis.Options{
		Addr:     "localhost:6379",
		Password: "",
		DB:       0,
	})

	// Initialize product catalog and inventory management
	productCatalog := make(map[string]Product)
	inventoryManagement := &InventoryManagement{}

	// Start HTTP server
	http.HandleFunc("/products", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != "GET" {
			http.Error(w, "Invalid request method", http.StatusBadRequest)
			return
		}
		productID := r.URL.Query().Get("id")
		if productID == "" {
			http.Error(w, "Missing product ID", http.StatusBadRequest)
			return
		}
		product, ok := productCatalog[productID]
		if !ok {
			http.Error(w, "Product not found", http.StatusNotFound)
			return
		}
		json.NewEncoder(w).Encode(product)
	})

	http.HandleFunc("/inventory", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != "GET" {
			http.Error(w, "Invalid request method", http.StatusBadRequest)
			return
		}
		productID := r.URL.Query().Get("id")
		if productID == "" {
			http.Error(w, "Missing product ID", http.StatusBadRequest)
			return
		}
		inventoryLevel, err := inventoryManagement.GetInventoryLevel(productID)
		if err != nil {
			http.Error(w, "Error fetching inventory level", http.StatusInternalServerError)
			return
		}
		json.NewEncoder(w).Encode(inventoryLevel)
	})

	http.ListenAndServe(":8080", nil)

}

type InventoryManagement struct {
	mu      sync.Mutex
	inventories map[string]int
}

func (im *InventoryManagement) GetInventoryLevel(productID string) (int, error) {
	im.mu.Lock()
	defer im.mu.Unlock()
	level, ok := im.inventories[productID]
	if !ok {
		return 0, fmt.Errorf("product %s not found in inventory", productID)
	}
	return level, nil
}

func (im *InventoryManagement) UpdateInventoryLevel(productID string, newLevel int) error {
	im.mu.Lock()
	defer im.mu.Unlock()
	im.inventories[productID] = newLevel
	return nil
}
