const { Semaphore } = require('async-semaphore');
const { promisify } = require('util');

class AsyncArrayReduce {
  constructor({
    concurrency,
    callbackFunction,
    initialValue,
  }) {
    this.concurrency = concurrency;
    this.callbackFunction = callbackFunction;
    this.initialValue = initialValue;
    this.semaphore = new Semaphore(concurrency);
  }

  async execute(arr) {
    const results = [];
    let accumulator = this.initialValue;

    for await (const num of arr) {
      if (!this.semaphore.take()) {
        return { error: 'Concurrent limit exceeded' };
      }

      try {
        const result = await thisEXTERNAL_API_CALL(num);
        accumulator = this.callbackFunction(accumulator, result);
        results.push(result);
      } catch (error) {
        this.semaphore.release();
        return { error: 'Error in callback function', details: error.message };
      } finally {
        this.semaphore.release();
      }
    }

    if (results.length === 0) {
      return accumulator;
    }

    const [lastResult, ...restResults] = results;
    let total = lastResult;

    for await (const result of restResults) {
      total += result;
    }

    return total;
  }

  async EXTERNAL_API_CALL(num) {
    // Simulate the API call using a mock function
    return promisify(() => new Promise((resolve, reject) => setTimeout(() => resolve(num * num), 500)))(num);
  }
}

module.exports = AsyncArrayReduce;
