```rust
use std::fs::{create_dir_all, File};
use std::io::{Read, Write};
use std::path::Path;
use std::sync::{atomic, Arc};
use std::time::{Duration, Instant};
use log::{info, error};

struct Cache {
    path: String,
    dir_path: String,
    file_map: std::collections::HashMap<String, (Instant, File)>,
}

impl Cache {
    fn new(dir_name: &str, cleanup_interval: Duration) -> Arc<Self> {
        let cache = Arc::new(Cache {
            path: "".to_string(),
            dir_path: format!("/tmp/{}", dir_name),
            file_map: std::collections::HashMap::new(),
        });
        cache.create_dir();
        cache.set_env_var(dir_name);
        cache.cleanup_interval = cleanup_interval;
        cache
    }

    fn create_dir(&self) {
        if let Err(e) = create_dir_all(&Path::new(&self.dir_path)) {
            error!("Error creating cache directory: {}", e);
        } else {
            info!("Cache directory created at {}", self.dir_path);
        }
    }

    fn set_env_var(&self, dir_name: &str) {
        std::env::set_var("CACHE_DIR", self.dir_path.clone());
    }

    fn cleanup(&self) {
        let now = Instant::now();
        for (file_name, (timestamp, _)) in self.file_map.iter() {
            if now - timestamp > self.cleanup_interval {
                info!("Deleting old file: {}", file_name);
                if let Err(e) = File::create(self.dir_path.clone()).write_all(b"") {
                    error!("Error deleting old file: {}", e);
                }
                self.file_map.remove(file_name);
            }
        }
    }

    fn write(&self, file_name: &str, contents: &[u8]) -> Result<(), std::io::Error> {
        let now = Instant::now();
        if let Err(e) = File::create(self.dir_path.clone()).write_all(contents) {
            error!("Error writing to cache file: {}", e);
            return Err(e);
        }
        self.file_map.insert(file_name.to_string(), (now, File::create(self.dir_path.clone())?));
        Ok(())
    }

    fn read(&self, file_name: &str) -> Result<Vec<u8>, std::io::Error> {
        if let Some((_, file)) = self.file_map.get(file_name) {
            let mut contents = vec![];
            file.seek(std::io::SeekStart)?;
            file.read_to_end(&mut contents)?;
            return Ok(contents);
        }
        Err(std::io::Error::new(std::io::ErrorKind::NotFound, "File not found"))
    }
}

fn main() {
    let cache = Cache::new("my_cache", Duration::from_secs(24 * 60 * 60));
    // Use the cache
}
