    def __init__(self, log_config: Dict):
        self.log_file = None

    def record_transaction(self, transaction_id: str, details: str) -> Tuple[bool, int]:
        if not self.log_file:
            try:
                self.log_file = open(**log_config)
            except FileNotFoundError as e:
                logging.error(f"Failed to open the log file: {e}")
                return False, 500
        with self.log_file:
            self.log_file.write(f"{transaction_id}: {details}\n")
        return True, 200

def process_and_record_transaction(should_record: bool, record_type: str, transaction_details: Dict, config: Dict) -> Tuple[bool, int]:
    if should_record and record_type == "database":
        db_manager = DatabaseManager(config["db_config"])
        success, status_code = db_manager.record_transaction(transaction_id=transaction_details["id"], details=transaction_details["details"])
        return success, status_code
    elif should_record and record_type == "log_file":
        log_manager = LogFileManager(config["log_config"])
        success, status_code = log_manager.record_transaction(transaction_id=transaction_details["id"], details=transaction_details["details"])
        return success, status_code
    else:
        # Process transaction without recording
        response = requests.post("https://example.com/api/transactions", json=transaction_details)
        if response.status_code == 200:
            return True, 200
        elif response.status_code >= 400 and response.status_code < 500:
            # Handle API failure with exponential backoff and retries
            for _ in range(3):
                time.sleep(2**_ * 5)  # Exponential backoff
                response = requests.post("https://example.com/api/transactions", json=transaction_details)
                if response.status_code == 200:
                    return True, 200
        else:
            return False, 500

