from flask_restx import Api, Resource, fields

api = Api()

# Initialize cache with an empty dictionary
cache = {}

# Define the resource model
resource_model = api.model('Resource', {
    'id': fields.String,
    'name': fields.String,
    'description': fields.String
})

# Define the update request body model
update_request_body = api.model('UpdateRequest', {
    'name': fields.String,
    'description': fields.String
})

# Define the delete request body model (empty for now)
delete_request_body = api.model('DeleteRequest', {})

# Update Resource Function
class UpdateResource(Resource):
    @api.expect(update_request_body)
    def put(self, id):
        # Validate request body
        update_data = request.json

        # Check if the resource exists and validate user permissions before updating
        if id in cache:
            resource = cache[id]
            if validate_user_permissions(resource['owner']):
                # Update the resource
                resource['name'] = update_data.get('name', resource['name'])
                resource['description'] = update_data.get('description', resource['description'])

                # Cache the updated resource
                cache[id] = resource

                return jsonify({'message': 'Resource updated successfully'}), 200
            else:
                return jsonify({'error': 'Unauthorized access'}), 401
        else:
            return jsonify({'error': 'Resource not found'}), 404

# Delete Resource Function
class DeleteResource(Resource):
    def delete(self, id):
        # Check if the resource exists and validate user permissions before deleting
        if id in cache:
            resource = cache.pop(id)
            if validate_user_permissions(resource['owner']):
                return jsonify({'message': 'Resource deleted successfully'}), 200
            else:
                return jsonify({'error': 'Unauthorized access'}), 401
        else:
            return jsonify({'error': 'Resource not found'}), 404

# Define the main API route
api.add_resource(UpdateResource, '/resources/<string:id>')
api.add_resource(DeleteResource, '/resources/<string:id>/delete')
