const fetch = require('node-fetch');
const asyncReduce = (arr, callback) => {
  if (!Array.isArray(arr)) {
    throw new Error("Input must be an array");
  }
  const queue = arr.map((item, index) => ({
    index,
    value: item,
    callback: callback.bind(null, index),
  }));

  let result;
  (async function reducer() {
    while (queue.length > 0) {
      const { index, value, callback } = await queue.shift();
      if (!isNaN(value)) {
        try {
          value = await callback(value);
        } catch (error) {
          console.error('Error at index', index, ': ', error);
          return Promise.reject(error);
        }
      } else {
        // skip non-numeric values
        continue;
      }
      if (Array.isArray(value)) {
        queue.unshift(...value.map((item) => ({ index: -1, value: item, callback })));
      } else {
        if (!result) result = value;
        if (isNaN(result)) {
          result = 0;
        }
        result += value;
      }
    }
    return Promise.resolve(result);
  })()
    .then((res) => res)
    .catch((error) => Promise.reject(error));
};

const fetchArrayData = async () => {
  try {
    const response = await fetch('https://example.com/arraydata');
    const data = await response.json();
    return data;
  } catch (error) {
    throw new Error("Failed to fetch array data: ", error);
  }
};

// Example usage
const myArray = [1, 2, 3, [[4], 5]];
fetchArrayData().then((data) => asyncReduce(data, (acc, curr) => acc + curr)).then((result) => console.log(result));

// Test cases
describe('asyncReduce', () => {
  it('should reduce empty array to undefined', async () => {
    expect(await asyncReduce([], (a, b) => a + b)).toBeUndefined();
  });

  it('should skip non-numeric values', async () => {
    expect(await asyncReduce([1, 'hello', 3], (a, b) => a + b)).toBe(4);
  });

  it('should handle very large numbers', async () => {
    const arr = new Array(100000).fill(1234567890);
    expect(await asyncReduce(arr, (a, b) => a + b)).toBe(12345678900 * 100000);
  });

  it('should handle network failure during data fetching', async () => {
    await fetchArrayData().catch(() => null);
  });

  it('should reduce nested array correctly', async () => {
    expect(await asyncReduce(myArray, (a, b) => a + b)).toBe(15);
  });
});
