class ApiQueue {
  constructor( WeatherDataFetcher, maxConcurrentRequests = 5) {
    this.queue = [];
    this.fetcher = WeatherDataFetcher;
    this.maxConcurrentRequests = maxConcurrentRequests;
    this.retryDelay = 1000; // initial retry delay in ms
  }

  async enqueue(request) {
    this.queue.push(request);
    await this.processQueue();
  }

  async processQueue() {
    while (this.queue.length > 0 && this.queue.length <= this.maxConcurrentRequests) {
      const request = this.queue.shift();
      try {
        await this.fetcher.fetchWeather(request.latitude, request.longitude);
      } catch (error) {
        // handle failed requests
        await new Promise((resolve) => setTimeout(() => resolve(), this.retryDelay));
        this.queue.unshift(request);
      }
    }
  }

  async retryFailedRequests() {
    // implement logic to retry failed requests with exponential back-off intervals
  }
}

