using System.Xml.Linq;

public class XmlCache
{
    private readonly Dictionary<string, XmlDocument> _cache = new();
    private readonly HttpClient _httpClient;
    private readonly ILogger _logger;
    private readonly Configuration _config;
    private readonly Lock _lock = new();

    public XmlCache(Configuration config, ILogger logger)
    {
        _config = config;
        _logger = logger;
        _httpClient = new HttpClient();
    }

    public void LoadXml(string source)
    {
        if (_cache.ContainsKey(source))
            return;

        lock (_lock)
        {
            XmlDocument doc;
            try
            {
                switch (source)
                {
                    case "file":
                        doc = LoadFromFileSync();
                        break;
                    case "db":
                        doc = LoadFromDatabaseSync();
                        break;
                    case "http":
                        doc = LoadFromHttpAsync().Result;
                        break;
                    default:
                        throw new ArgumentException("Invalid source");
                }

                _cache.Add(source, doc);
            }
            catch (Exception e)
            {
                _logger.LogError(e, "Error loading XML from {source}", source);
            }
        }
    }

    public XmlDocument GetXml(string source, string xpathQuery)
    {
        if (!_cache.ContainsKey(source))
            return null;

        try
        {
            lock (_lock)
            {
                var doc = _cache[source];
                var result = doc.DocumentElement.XPathEvaluate(xpathQuery);

                if (result == null)
                    throw new XmlException("XPath query not found");

                return new XmlDocument(result);
            }
        }
        catch (XmlException e)
        {
            _logger.LogError(e, "Error processing XPath query for {source}", source);
            return null;
        }
    }

    private async Task<XmlDocument> LoadFromHttpAsync()
    {
        // implement HTTP API loading logic
    }

    private XmlDocument LoadFromFileSync()
    {
        // implement file system loading logic
    }

    private XmlDocument LoadFromDatabaseSync()
    {
        // implement database loading logic
    }
}

public class Configuration
{
    public Dictionary<string, int> Priorities { get; set; } = new();
    public List<string> Sources { get; set; } = new();
}

public interface ILogger
{
    void LogError(Exception e, string message);
}

public interface ILock
{
    void Lock();
