from aiohttp import ClientSession
import logging

class ImageCrawler:
    def __init__(self, max_concurrent_downloads=5):
        self.max_concurrent_downloads = max_concurrent_downloads
        self.image_processor = None

    async def download_images(self, urls):
        async with ClientSession() as session:
            tasks = []
            for url in urls:
                tasks.append(self._download_image(session, url))
            await asyncio.gather(*tasks)

    async def _download_image(self, session, url):
        try:
            async with session.get(url) as response:
                image_data = await response.read()
                # Process the image using an external library
                processed_image = self.image_processor.process(image_data)
                # Store the processed image
                logging.info(f"Downloaded and processed {url}")
        except Exception as e:
            logging.error(f"Failed to download {url}: {str(e)}")

    def set_image_processor(self, processor):
        self.image_processor = processor

# Example usage:
crawler = ImageCrawler()
crawler.set_image_processor(ImageProcessor())  # Replace with your image processing library
urls = ['https://example.com/image1.jpg', 'https://example.com/image2.jpg']
asyncio.run(crawler.download_images(urls))
