```python
import subprocess

def modify_kickstart_config(kickstart_file, config_dict):
    try:
        with open(kickstart_file, 'r') as file:
            kickstart_data = file.read()
    except FileNotFoundError:
        raise Exception(f"Failed to read {kickstart_file}")

    for key, value in config_dict.items():
        sed_command = f'sed -i "s/{key}/{{value}}/g"'  # Replace with actual values
        try:
            subprocess.run(sed_command.split(' '), check=True)
        except subprocess.CalledProcessError as e:
            raise Exception(f"Failed to modify {kickstart_file}: {str(e)}")

    new_kickstart_file = f"{kickstart_file}.modified"
    with open(new_kickstart_file, 'w') as file:
        file.write(kickstart_data)

    return new_kickstart_file
