```
import asyncio
import logging
from queue import Queue
from functools import wraps
from typing import List, Dict, Any

class TaskQueue:
    def __init__(self, max_concurrent_tasks: int = 5):
        self.max_concurrent_tasks = max_concurrent_tasks
        self.task_queue = Queue()
        self.results = []
        self.logger = logging.getLogger(__name__)

    async def _run_task(self, task: Dict[str, Any]) -> Any:
        try:
            return await asyncio.wait_for(task['function'](*task['args']), timeout=task.get('timeout', 30))
        except Exception as e:
            self.logger.error(f"Task {task['id']} failed: {str(e)}")
            raise

    def add_task(self, task: Dict[str, Any]) -> None:
        self.task_queue.put(task)

    async def run_tasks(self) -> List[Any]:
        tasks = []
        while not self.task_queue.empty():
            for _ in range(min(self.max_concurrent_tasks, self.task_queue.qsize())):
                task = self.task_queue.get()
                tasks.append(asyncio.create_task(self._run_task(task)))
        await asyncio.wait(tasks)
        return [task.result() for task in tasks]

    def get_results(self) -> List[Any]:
        return self.results

def rate_limited(max_concurrent: int):
    async def decorator(func):
        @wraps(func)
        async def wrapper(*args, **kwargs):
            loop = asyncio.get_running_loop()
            if len(loop.tasks) >= max_concurrent:
                await asyncio.sleep(0.1)
            return await func(*args, **kwargs)

        return wrapper
    return decorator

def task_queue_example():
    queue = TaskQueue(max_concurrent_tasks=10)

    tasks = [
        {'id': 1, 'function': lambda: print("Task 1"), 'args': ()},
        {'id': 2, 'function': lambda: print("Task 2"), 'args': ()},
        {'id': 3, 'function': lambda: print("Task 3"), 'args': ()}
    ]

    queue.add_task(tasks[0])
    queue.add_task(tasks[1])
    queue.add_task(tasks[2])

    results = asyncio.run(queue.run_tasks())
    for result in results:
        print(result)

if __name__ == "__main__":
    task_queue_example()
```

