```rust
use reqwest::blocking::{get, RequestBuilder};
use reqwest::header;
use std::time::Duration;

pub fn make_request(url: &str, disable_cert_validation: bool, custom_headers: Option<(&[&str], &[&str])>, timeout: Option(Duration)) -> Result<RequestBuilder, reqwest::Error> {
    let mut client = match get(url) {
        Ok(client) => client,
        Err(_) => return Err(reqwest::Error::new(reqwest::ErrorKind::InvalidUrl, "Invalid URL")),
    };

    if disable_cert_validation {
        client = client.danger_accept_invalid_certs();
    }

    if let Some((_, headers)) = custom_headers {
        for (key, value) in headers.iter() {
            client = client.header(key, value);
        }
    }

    if let Some(timeout) = timeout {
        client = client.timeout(timeout);
    }

    Ok(client)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn test_make_request() {
        // Test a valid URL
        assert!(make_request("https://www.example.com", false, None, None).is_ok());

        // Test an invalid URL
        let result = make_request("not-a-url", false, None, None);
        match result {
            Err(e) => match e.kind() {
                reqwest::ErrorKind::InvalidUrl => assert!(true),
                _ => panic!("Expected InvalidUrl error"),
            },
            _ => panic!("Expected an error"),
        }

        // Test custom headers
        let headers = [("Authorization", "Bearer YOUR_TOKEN"), ("Content-Type", "application/json")];
        let result = make_request("https://www.example.com", false, Some(&headers, &[]), None);
        match result {
            Ok(_) => assert!(true),
            _ => panic!("Expected a successful request"),
        }
    }
}
