// Import required libraries
const fs = require('fs');
const childProcess = require('child_process');
const path = require('path');

// Configuration management system API
const configAPI = require('./config-api');

// Load configuration file asynchronously
async function loadConfig() {
  try {
    const config = await configAPI.getConfig();
    return config;
  } catch (error) {
    console.error(`Error loading configuration: ${error}`);
    return null;
  }
}

// Load and execute multiple JavaScript files
function loadAndExecuteFiles(files, callback) {
  if (!files || !Array.isArray(files)) {
    callback(new Error('Invalid file list'));
    return;
  }

  const executionOrder = [];
  let currentFileIndex = 0;

  function loadNextFile() {
    if (currentFileIndex >= files.length) {
      callback();
      return;
    }
    const file = files[currentFileIndex];
    fs.readFile(file, 'utf8', (err, code) => {
      if (err) {
        console.error(`Error loading file ${file}: ${err}`);
        loadNextFile(); // Load next file on error
      } else {
        try {
          eval(code);
        } catch (execErr) {
          console.error(`Error executing file ${file}: ${execErr}`);
        }
        currentFileIndex++;
        loadNextFile();
      }
    });
  }

  loadNextFile();
}

// Main program entry point
async function main() {
  const config = await loadConfig();
  if (!config) return;

  // Load and execute files according to the configuration
  loadAndExecuteFiles(config.files, () => {
    console.log('Execution complete');
  });
}

main();
