    public void ProcessFileAndExecuteRemoteCommands(byte[] fileData, Configuration config, int timeout)
    {
        // Read local configuration file asynchronously
        Task<string> configFileTask = ReadConfigFileAsync(config.LocalConfigurationFilePath);
        string configFileContent = configFileTask.Result;

        // Validate configuration file content
        if (!ValidateConfigFileContent(configFileContent))
        {
            throw new Exception("Invalid configuration file");
        }

        // Establish secure connection to remote host
        using (WebClient client = new WebClient())
        {
            client.Credentials = new NetworkCredential(config.RemoteHost, config.RemotePort);
        }

        // Execute command list on remote host using batch processing mechanism
        foreach (string command in config.CommandList)
        {
            try
            {
                string output = ExecuteRemoteCommandAsync(client, command, timeout).Result;
                // Map commands to their respective outputs
                Console.WriteLine($"Command '{command}' executed successfully. Output: {output}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error executing command '{command}': {ex.Message}");
                // Retry logic for failed command executions
                if (ShouldRetry(ex))
                {
                    await Task.Delay(500); // Wait for 0.5 seconds before retrying
                    ExecuteRemoteCommandAsync(client, command, timeout).Wait(); // Retry execution
                }
            }
        }
    }

