use {
    tokio::runtime::Runtime,
    tokio_postgres::{connect, NoTls},
    tokio_postgres::row::{Row, RowTrait},
    std::env,
};

struct DatabaseConnection {
    conn: connect,
}

impl DatabaseConnection {
    async fn new() -> Self {
        let (mut conn, _) = connect(
            &format!("host={} port={}", env::var("PGHOST").unwrap(), env::var("PGPORT").unwrap()),
            NoTls,
        ).await.unwrap();

        DatabaseConnection { conn }
    }

    async fn query(&self, query: &str) -> Result<RowTrait, Box<dyn std::error::Error>> {
        self.conn.query(query).await.unwrap()
    }

    async fn close(self) {
        self.conn.close().unwrap();
    }
}

#[tokio::main]
async fn main() {
    let runtime = Runtime::new().unwrap();

    let args: Vec<String> = std::env::args().collect();
    if args.len() != 2 {
        eprintln!("Usage: {} <user_id>", &args[0]);
        return;
    }

    let user_id = &args[1];

    let max_connections = env::var("MAX_CONCURRENT_CONNECTIONS").unwrap_or("10".to_string()).parse().unwrap();
    let mut connections = vec![];

    for _ in 0..max_connections {
        let connection = DatabaseConnection::new().await;
        connections.push(connection);
    }

    runtime.block_on(async move {
        for connection in &connections {
            let query = format!("SELECT * FROM users WHERE id = '{}'", user_id);

            match connection.query(&query).await {
                Ok(row) => println!("{}", row),
                Err(err) => eprintln!("Error: {}", err),
            }
        }

        for connection in connections {
            connection.close().await;
        }
    });
}
