using System;
using System.IO;
using System.Security.Cryptography;
using RabbitMQ.Client;
using RabbitMQ.Client.Extensions;

public class BatchProcessor
{
    private const string KeyFile = "keys.txt";
    private const string IvFile = "ivs.txt";

    public void ProcessBatch(string[] messages)
    {
        using (var rsa = new RSACryptoServiceProvider())
        {
            rsa.ImportParameters(File.ReadAllBytes(KeyFile), File.ReadAllBytes(IvFile));

            var queue = ConnectionFactory.CreateConnection().CreateModel();
            queue.QueueBind("decrypted_messages", "messages", "#", true);

            Parallel.ForEach(messages, message =>
            {
                try
                {
                    byte[] encryptedMessage = Convert.FromBase64String(message);
                    byte[] decryptedMessage = rsa.Decrypt(encryptedMessage, false);

                    if (decryptedMessage == null)
                        throw new CryptographicException("Decryption failed");

                    byte[] hmacBytes = HMACSHA256Hash(encryptedMessage, rsa);
                    string decryptedMessageText = Encoding.UTF8.GetString(decryptedMessage);
                    queue.BasicPublish(exchange: "", routingKey: "messages", body: Encoding.UTF8.GetBytes(decryptedMessageText));

                    Console.WriteLine($"Message '{decryptedMessageText}' processed successfully.");
                }
                catch (CryptographicException ex)
                {
                    Console.WriteLine($"Decryption failed for message '{message}': {ex.Message}");
                }
                catch (FormatException ex)
                {
                    Console.WriteLine($"Invalid Base64 encoding for message '{message}': {ex.Message}");
                }
                catch (RabbitMQ.Client.Exceptions.AbsoluteTimeoutException)
                {
                    Console.WriteLine("RabbitMQ connection timed out.");
                }
            });
        }
    }

    private byte[] HMACSHA256Hash(byte[] message, RSACryptoServiceProvider rsa)
    {
        using (var hmac = new HMACSHA256(rsa))
        {
            return hmac.ComputeHash(message);
        }
    }
}

public class Program
{
    public static void Main()
    {
        var processor = new BatchProcessor();
        string[] messages = { "Base64-encoded message 1", "Base64-encoded message 2" };
        processor.ProcessBatch(messages);
    }
}
