import redis.clients.jedis.Jedis;
import redis.clients.jedis.JedisPool;
import redis.clients.jedis.JedisPoolConfig;

import java.util.List;
import java.util.Map;
import java.util.Optional;

public class JwtValidator {

    private final JedisPool jedisPool;
    private final ConfigLoader configLoader;
    private final JwtProcessor jwtProcessor;
    private final ExternalApiClients apiClients;

    public JwtValidator(JedisPool jedisPool, ConfigLoader configLoader, JwtProcessor jwtProcessor, ExternalApiClients apiClients) {
        this.jedisPool = jedisPool;
        this.configLoader = configLoader;
        this.jwtProcessor = jwtProcessor;
        this.apiClients = apiClients;
    }

    public void validateJwt(String jwtToken) {
        Optional<Map<String, Object>> validatedToken = validateToken(jwtToken);
        if (validatedToken.isPresent()) {
            Map<String, Object> tokenMetadata = getMetadata(validatedToken.get());
            // Process and store the validated JWT
            processToken(tokenMetadata);
        } else {
            // Handle invalid JWT or missing claims
            handleInvalidJwt();
        }
    }

    private Optional<Map<String, Object>> validateToken(String jwtToken) {
        // Load configuration for JWT validation rules
        List<ValidationRule> validationRules = configLoader.loadValidationRules();

        // Validate the JWT using the loaded rules and store it in Redis
        Jedis jedis = jedisPool.getResource();
        try {
            Map<String, Object> validatedToken = jwtProcessor.validate(jwtToken, validationRules);
            if (validatedToken != null) {
                // Store the validated JWT in Redis with metadata
                jedis.hmset("jwt:metadata", validatedToken);
                return Optional.of(validatedToken);
            }
        } finally {
            jedis.close();
        }
        return Optional.empty();
    }

    private Map<String, Object> getMetadata(Map<String, Object> token) {
        // Retrieve the stored JWT metadata from Redis
        Jedis jedis = jedisPool.getResource();
        try {
            return jedis.hgetAll("jwt:metadata");
        } finally {
            jedis.close();
        }
    }

    private void processToken(Map<String, Object> tokenMetadata) {
        // Extract and process specific user information (e.g., username, roles)
        String username = (String) tokenMetadata.get("username");
        List<String> roles = (List<String>) tokenMetadata.get("roles");

        // Check for token revocation using external APIs
        boolean revoked = false;
        for (ExternalApiClient apiClient : apiClients.clients()) {
            try {
                Map<String, Object> response = apiClient.checkRevocation(tokenMetadata);
                if ((boolean) response.get("revoked")) {
                    revoked = true;
                    break;
                }
            } catch (Exception e) {
                // Handle API failure and fallback mechanism
                handleApiFailure(e);
            }
        }

        // Update token metadata with revocation status
        tokenMetadata.put("revoked", revoked);

        // Store the processed token metadata in Redis
        Jedis jedis = jedisPool.getResource();
        try {
            jedis.hmset("jwt:metadata", tokenMetadata);
        } finally {
            jedis.close();
        }
    }

    private void handleInvalidJwt() {
        // Handle invalid JWT or missing claims
    }

    private void handleApiFailure(Exception e) {
        // Handle API failure and fallback mechanism
    }
}
