import json
import os
import yaml
import threading
import time

class JSONBase:
    def __init__(self):
        self.registry = {}

    def to_json(self, data):
        return json.dumps(data)

    def from_json(self, json_string):
        return json.loads(json_string)

    def register_factory(self, factory_func):
        self.registry[factory_func.__name__] = factory_func

    def discover_subclasses(self, directory: str):
        for filename in os.listdir(directory):
            if filename.endswith(".py"):
                module_name = filename[:-3]
                __import__(module_name)
                subclass_module = globals()[module_name]

                for name in dir(subclass_module):
                    obj = getattr(subclass_module, name)
                    if callable(obj) and hasattr(obj, "__name__") and not (obj.__name__.endswith("_factory") or obj.__name__.endswith("Subclass")):
                        factory_func = obj
                        self.register_factory(factory_func)

    def load_from_yaml(self, yaml_path: str):
        with open(yaml_path, "r") as file:
            data = yaml.safe_load(file)
            for key, value in data.items():
                if callable(value):
                    self.register_factory(value)

    def save_to_file(self, file_path: str):
        with open(file_path, "w") as file:
            yaml.dump({key: value.__name__ for key, value in self.registry.items()}, file, default=str)

    def get_factory_func(self, factory_name):
        return self.registry.get(factory_name)


class Registry:
    registry = {}

    @classmethod
    def register_factory(cls, factory_func):
        cls.registry[factory_func.__name__] = factory_func

    @classmethod
    def discover_subclasses(cls, directory: str):
        for filename in os.listdir(directory):
            if filename.endswith(".py"):
                module_name = filename[:-3]
                __import__(module_name)
                subclass_module = globals()[module_name]

                for name in dir(subclass_module):
                    obj = getattr(subclass_module, name)
                    if callable(obj) and hasattr(obj, "__name__") and not (obj.__name__.endswith("_factory") or obj.__name__.endswith("Subclass")):
                        factory_func = obj
                        cls.register_factory(factory_func)

    @classmethod
    def load_from_yaml(cls, yaml_path: str):
        with open(yaml_path, "r") as file:
            data = yaml.safe_load(file)
            for key, value in data.items():
                if callable(value):
                    cls.register_factory(value)

    @classmethod
    def save_to_file(cls, file_path: str):
        with open(file_path, "w") as file:
