import java.util.*;
import org.apache.commons.lang3.tuple.*;

public class PacketProcessor {
    private Map<String, List<Packet>> packetsBySource;
    private Map<Integer, List<Packet>> packetsByDestinationPort;
    private Queue<Packet> recentPackets;
    private final int WINDOW_SIZE = 1000;

    public PacketProcessor() {
        this.packetsBySource = new HashMap<>();
        this.packetsByDestinationPort = new HashMap<>();
        this.recentPackets = new LinkedList<>();
    }

    public void process(Packet packet) throws Exception {
        // Filter packets based on size, source IP address, destination port, and arrival time
        if (packet.getSize() > 1024 || !isValidSource(packet.getSource()) 
            || !isValidDestinationPort(packet.getDestinationPort())) {
            return;
        }

        recentPackets.add(packet);
        if (recentPackets.size() > WINDOW_SIZE) {
            recentPackets.poll();
        }

        // Update packet counters
        updateCounters(packet);

        // Handle concurrent processing and thread safety
        synchronized (this) {
            processPacketInDatabase(packet);
            logPacket(packet);
        }
    }

    private void updateCounters(Packet packet) {
        int totalPackets = recentPackets.size();
        double averagePacketSize = calculateAveragePacketSize();
        System.out.println("Filtered packets: " + totalPackets + ", Average Packet Size: " + averagePacketSize);
    }

    private boolean isValidSource(String source) {
        // Implement your own validation logic for the source IP address
        return true;
    }

    private boolean isValidDestinationPort(int port) {
        // Implement your own validation logic for the destination port
        return true;
    }

    private double calculateAveragePacketSize() {
        int totalBytes = 0;
        for (Packet packet : recentPackets) {
            totalBytes += packet.getSize();
        }
        return (double) totalBytes / recentPackets.size();
    }

    private void processPacketInDatabase(Packet packet) {
        // Implement your own logic for processing packets in the database
    }

    private void logPacket(Packet packet) {
        // Implement your own logging mechanism
    }
}

class Packet {
    private int size;
    private String source;
    private int destinationPort;
    private long arrivalTime;

    public int getSize() {
        return size;
    }

    public String getSource() {
        return source;
