        printf("\nReceived termination signal. Exiting.\n");
        exit(0);
    }
}

int main(int argc, char **argv) {
    int verbose = 0;
    char *output_file = NULL;
    FILE *log_file = stderr;

    // Parse command line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0 || strcmp(argv[i], "-h") == 0) {
            printf("Usage: %s [options] input_file\n", argv[0]);
            printf("Options:\n");
            printf("  --help, -h   Display this help message and exit.\n");
            printf("  --verbose    Enable verbose mode.\n");
            printf("  -cs          Specify a custom separator character.\n");
            printf("  -o output_file Specify the output file name.\n");
            return 0;
        } else if (strcmp(argv[i], "--verbose") == 0) {
            verbose = 1;
        } else if (strcmp(argv[i], "-cs") == 0 && i < argc - 1) {
            // TODO: implement custom separator character support
            i++;
        } else if (strcmp(argv[i], "-o") == 0 && i < argc - 1) {
            output_file = argv[i + 1];
            i++;
        }
    }

    char *input_file = NULL;
    for (int i = 1; i < argc; i++) {
        if (argv[i][0] != '-') {
            input_file = argv[i];
            break;
        }
    }

    if (!input_file) {
        LOG_ERR("No input file provided. Usage: %s [options] input_file\n", argv[0]);
        return 1;
    }

    // Open the input file
    FILE *file = fopen(input_file, "r");
    if (file == NULL) {
        LOG_ERR("Error opening input file '%s': %s\n", input_file, strerror(errno));
        return 1;
    }

    int line_count = 0;

    // Read and process the file line by line
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        if (verbose) {
            printf("%s", buffer);
        }
        line_count++;
    }

    fclose(file);

    if (output_file) {
        FILE *output = fopen(output_file, "w");
        fprintf(output, "%d\n", line_count);
        fclose(output);
    } else {
        printf("%d\n", line_count);
    }

    return 0;
}
