import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.RecursiveTask;

public class HashCalculator {

    private static final int MAX_THREADS = 10;
    private static final int CACHE_SIZE = 1000;
    private static final int RATE_LIMIT_PER_IP = 5;
    private static final int RATE_LIMIT_PER_SESSION = 2;

    private final ForkJoinPool threadPool;
    private final Cache<String, byte[]> cache;
    private final RateLimiter rateLimiter;
    private final RedisClient redisClient;

    public HashCalculator() {
        this.threadPool = new ForkJoinPool(MAX_THREADS);
        this.cache = new Cache<>(CACHE_SIZE);
        this.rateLimiter = new RateLimiter(RATE_LIMIT_PER_IP, RATE_LIMIT_PER_SESSION);
        this.redisClient = new RedisClient();
    }

    public void setThreadPoolSize(int size) {
        threadPool.setParallelism(size);
    }

    public void setCacheSize(int size) {
        cache.setMaxEntries(size);
    }

    public void setRateLimitsPerIp(int rateLimit) {
        rateLimiter.setRateLimitPerIp(rateLimit);
    }

    public void setRateLimitsPerSession(int rateLimit) {
        rateLimiter.setRateLimitPerSession(rateLimit);
    }

    public byte[] getHash(String input, String encoding) throws IOException {
        if (input == null || input.length() > 1000) {
            return null;
        }
        try {
            return computeHash(input, encoding);
        } catch (Exception e) {
            logger.error("Error computing hash: {}", e.getMessage(), e);
            return null;
        }
    }

    private byte[] computeHash(String input, String encoding) throws IOException {
        byte[] bytes = input.getBytes(encoding.equals("UTF-8") ? StandardCharsets.UTF_8 : StandardCharsets.ASCII);
        return threadPool.invoke(new HashTask(bytes));
    }

    private class HashTask extends RecursiveTask<byte[]> {

        private final byte[] data;

        public HashTask(byte[] data) {
            this.data = data;
        }

        @Override
        protected byte[] compute() {
            MessageDigest md5 = MessageDigest.getInstance("MD5");
            MessageDigest sha256 = MessageDigest.getInstance("SHA-256");

            for (int i = 0; i < data.length; i += 1024) {
                byte[] chunk = Arrays.copyOfRange(data, i, Math.min(i + 1024, data.length));
                md5.update(chunk);
                sha256.update(chunk);
            }

            return new byte[]{md5.digest(), sha256.digest()};
        }
    }
}
