public class DynamicServiceManager {

    private Map<String, ServiceFactory> serviceFactories = new HashMap<>();
    private Map<String, ServiceRegistry> tenantRegistries = new HashMap<>();
    private ObjectMapper objectMapper = new ObjectMapper();

    public void addService(String serviceName, ServiceFactory factory) {
        serviceFactories.put(serviceName, factory);
    }

    public void addTenant(String tenantId) {
        tenantRegistries.put(tenantId, new ServiceRegistry());
    }

    public void startService(String tenantId, String serviceName, JsonNode config) throws Exception {
        ServiceRegistry registry = tenantRegistries.get(tenantId);
        ServiceFactory factory = serviceFactories.get(serviceName);

        if (!registry.containsKey(serviceName)) {
            // Create a new instance based on the JSON configuration
            ServiceInstance instance = factory.createInstance(config);
            registry.put(serviceName, instance);
        }

        // Start the service and resolve dependencies
        startService(registry, serviceName, config);
    }

    private void startService(ServiceRegistry registry, String serviceName, JsonNode config) throws Exception {
        ServiceInstance instance = registry.get(serviceName);

        if (instance != null && !instance.isRunning()) {
            // Start the service and handle any dependencies
            startService(instance, config);
        }
    }

    private void startService(ServiceInstance instance, JsonNode config) throws Exception {
        // Handle health checks for the service
        instance.checkHealth();

        // Wait until all dependencies are resolved
        instance.waitForDependencies();

        // Start the service
        instance.start();
    }

    public void stopService(String tenantId, String serviceName) {
        ServiceRegistry registry = tenantRegistries.get(tenantId);
        if (registry.containsKey(serviceName)) {
            registry.get(serviceName).stop();
        }
    }

    public void updateConfiguration(String tenantId, String serviceName, JsonNode config) throws Exception {
