class NetworkClientManager:
    def __init__(self):
        self._lock = Lock()
        self._cond = Condition(self._lock)
        self._servers = []
        self._api_gateway_url = None
        self._auth_settings = {}
        self._rate_limiting = {}
        self._connection_pool = {}

    @property
    def servers(self) -> List[Dict[str, Any]]:
        with self._cond:
            return self._servers[:]

    @property
    def api_gateway_url(self) -> str:
        with self._lock:
            return self._api_gateway_url

    @api_gateway_url.setter
    def api_gateway_url(self, value: str):
        with self._lock:
            self._api_gateway_url = value

    @property
    def auth_settings(self) -> Dict[str, Any]:
        with self._lock:
            return self._auth_settings.copy()

    @auth_settings.setter
    def auth_settings(self, settings: Dict[str, Any]):
        with self._lock:
            self._auth_settings = settings

    @property
    def rate_limiting(self) -> Dict[str, Any]:
        with self._lock:
            return self._rate_limiting.copy()

    @rate_limiting.setter
    def rate_limiting(self, limits: Dict[str, Any]):
        with self._lock:
            self._rate_limiting = limits

    def add_server(self, server: Dict[str, Any]):
        with self._cond:
            self._servers.append(server)

    def remove_server(self, server_id: str):
        with self._cond:
            self._servers = [s for s in self._servers if s['id'] != server_id]

    def get_server(self, server_id: str) -> Dict[str, Any]:
