// Create a model for Old Testament books
const BookModel = mongoose.model('Book', bookSchema);

// Configure Redis for caching and storing book names
redis.createClient({ host: 'localhost', port: 6379 });

// Define the regular expression pattern to match Old Testament book names
const regexPattern = /[\w\s]+/gi;

// Create a rate limiter for API requests
const rateLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5,
  delayAfter: 3
});

app.use(rateLimiter);

// Define the logging configuration
const logConfig = {
  appenders: [
    { type: 'file', filename: 'logs/application.log' },
    { type: 'console' }
  ],
  categories: {
    default: { appenders: ['console'], level: 'INFO' }
  }
};

log4js.configure(logConfig);

// Create a logger instance
const logger = log4js.getLogger();

// Define the notification system configuration
const notificationConfig = {
  email: {
    from: 'old.testament.books@example.com',
    to: 'admin@example.com'
  },
  sms: {
    accountSid: 'your_account_sid',
    authToken: 'your_auth_token',
    from: '+1234567890',
    to: '+9876543210'
  }
};

// Define the API endpoints
app.get('/books', async (req, res) => {
  try {
    const books = await BookModel.find();
    res.json(books);
  } catch (error) {
    logger.error(`Error fetching books: ${error}`);
    res.status(500).send({ message: 'Internal Server Error' });
  }
});

app.post('/process', async (req, res) => {
  try {
    const textData = req.body;
    const regexMatches = textData.text.match(regexPattern);
    const bookCounts = {};

    for (const match of regexMatches) {
      const bookName = match.toLowerCase();
      if (!bookCounts[bookName]) {
        bookCounts[bookName] = 0;
      }
      bookCounts[bookName]++;
    }

    res.json(bookCounts);
  } catch (error) {
    logger.error(`Error processing data: ${error}`);
    res.status(500).send({ message: 'Internal Server Error' });
  }
});

// Start the server
const port = process.env.PORT || 3000;
app.listen(port, () => {
  logger.info(`Server started on port ${port}`);
});
