#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAX_LINE_LENGTH 1024
#define MAX_FIELDS 10

double calculateAverage(double sum, int count) {
    return (sum / count);
}

void printAverages(char *line, double *avgSums, int *counts) {
    printf("%f, %f, %f\n", avgSums[0], avgSums[1], avgSums[2]);
}

int main() {
    FILE *fp = fopen("input.txt", "r");

    if (fp == NULL) {
        fprintf(stderr, "Error opening file.\n");
        return -1;
    }

    char *line = (char *)malloc(MAX_LINE_LENGTH);
    double avgSums[3] = {0.0};
    int counts[3] = {0};

    while (fgets(line, MAX_LINE_LENGTH, fp) != NULL) {
        char *field = strtok(line, " ");
        int fieldCount = 0;

        for (; field != NULL; field = strtok(NULL, " ")) {
            if (++fieldCount > MAX_FIELDS) {
                fprintf(stderr, "Error: Line exceeds maximum number of fields.\n");
                free(line);
                fclose(fp);
                return -1;
            }

            char *endPtr;
            double val = strtod(field, &endPtr);

            if (*endPtr != '\0') {
                fprintf(stderr, "Error parsing field %s on line '%s'.\n", field, line);
                free(line);
                fclose(fp);
                return -1;
            }

            if (fieldCount > 3) {
                avgSums[2] += val;
                counts[2]++;
            } else if (fieldCount > 2) {
                avgSums[1] += val;
                counts[1]++;
            } else {
                avgSums[0] += val;
                counts[0]++;
            }
        }

        printf("%f, %f, %f\n", avgSums[0], avgSums[1], avgSums[2]);
    }

    free(line);
    fclose(fp);

    return 0;
}
