namespace SecureMessageHandler
{
    public class SecureMessageHandler : IDisposable
    {
        private readonly CryptographicServiceProvider _csp;
        private readonly KeyManagementService _kms;
        private readonly object _syncLock = new object();
        private readonly Queue<Task> _decryptionTasks = new Queue<Task>();

        public SecureMessageHandler(CryptographicServiceProvider csp, KeyManagementService kms)
        {
            _csp = csp;
            _kms = kms;
        }

        public async Task<string> DecryptBase64EncodedMessage(string base64EncodedMessage)
        {
            byte[] encryptedBytes = Convert.FromBase64String(base64EncodedMessage);
            using (MemoryStream ms = new MemoryStream(encryptedBytes))
            {
                using (CryptoStream cs = _csp.CreateDecryptingStream(ms, out string iv))
                {
                    // Perform decryption here
                    return Encoding.UTF8.GetString(cs.ToArray());
                }
            }
        }

        public async Task StartDecryptionTask(string base64EncodedMessage)
        {
            Task task = new Task(() =>
            {
                try
                {
                    DecryptBase64EncodedMessage(base64EncodedMessage);
                }
                catch (Exception ex)
                {
                    // Handle decryption errors here
                }
            });
            _decryptionTasks.Enqueue(task);
            task.Start();
        }

        public async Task StartDecryptionTaskBatch(int count, string base64EncodedMessage)
        {
            for (int i = 0; i < count; i++)
            {
                await StartDecryptionTask(base64EncodedMessage);
            }
        }

        public void Dispose()
        {
            // Dispose of resources here
        }
    }
}
