import os
from PIL import Image
from io import BytesIO
from django.conf import settings
from django.core.files.base import ContentFile
from django.core.cache.backends.filebased import FileBasedCache
from django.core.cache import cache
from django.utils.decorators import decorator_from_fn
from django.utils.functional import lru_cache
from django.views.generic import View

class StickerUploader(View):
    @lru_cache(maxsize=None)
    def get_sticker(self, sticker_id):
        try:
            # Retrieve the sticker from the file system or database
            sticker_path = f"{settings.MEDIA_ROOT}/stickers/{sticker_id}"
            if not os.path.exists(sticker_path):
                return None
            with open(sticker_path, 'rb') as f:
                return ContentFile(f.read())
        except Exception as e:
            print(f"Error getting sticker: {e}")
            return None

    @lru_cache(maxsize=None)
    def get_sticker_info(self, sticker_id):
        try:
            # Retrieve the sticker metadata from the database
            sticker = StickerModel.objects.get(id=sticker_id)
            return {
                "id": sticker.id,
                "name": sticker.name,
                "description": sticker.description,
                "size": os.path.getsize(f"{settings.MEDIA_ROOT}/stickers/{sticker_id}")
            }
        except Exception as e:
            print(f"Error getting sticker info: {e}")
            return None

    @decorator_from_fn
    def handle_upload(self, request):
        if not request.FILES:
            return HttpResponse("No file uploaded", status=400)
        sticker_file = request.FILES['sticker']
        if not sticker_file.name.endswith(('.png', '.gif')):
            return HttpResponse("Invalid file type", status=415)

        # Validate and compress the uploaded sticker
        try:
            img = Image.open(BytesIO(sticker_file.read()))
            img = img.convert('RGB').resize((100, 100), Image.LANCZOS)  # Resize to optimize storage
            img.save(f"{settings.MEDIA_ROOT}/stickers/{request.FILES['sticker'].name}", "PNG")
        except Exception as e:
            print(f"Error processing sticker: {e}")
            return HttpResponse("Invalid file", status=400)

        # Cache the sticker and its metadata
        cache.set(request.FILES['sticker'].name, {'id': request.FILES['sticker'].name}, settings.CACHE_TTL)

        return HttpResponse("Sticker uploaded successfully")

    @decorator_from_fn
    def handle_download(self, request):
        if not request.GET.get('sticker_id'):
            return HttpResponse("Invalid request", status=400)
        sticker_id = request.GET.get('sticker_id')
        sticker_info = cache.get(sticker_id)
        if not sticker_info:
            return HttpResponse("Sticker not found", status=404)

        # Serve the cached sticker
        try:
            sticker_file = self.get_sticker(sticker_id)
            if not sticker_file:
                return HttpResponse("Sticker not found", status=404)
            response = HttpResponse(content=sticker_file.read(), content_type='image/png')
            response['Content-Length'] = str(len(sticker_file))
            return response
        except Exception as e:
            print(f"Error serving sticker: {e}")
            return HttpResponse("Error serving sticker", status=500)

class StickerModel(models.Model):
    name = models.CharField(max_length=255)
    description = models.TextField()
    file = models.FileField(upload_to='stickers/')

# Unit tests
from django.test import TestCase

class StickerUploaderTests(TestCase):
    def test_get_sticker(self):
        uploader = StickerUploader()
        sticker_id = 'test_sticker'
        cached_sticker = uploader.get_sticker(sticker_id)
        self.assertIsInstance(cached_sticker, ContentFile)

    def test_get_sticker_info(self):
        uploader = StickerUploader()
        sticker_id = 'test_sticker'
        sticker_info = uploader.get_sticker_info(sticker_id)
        self.assertIsNotNone(sticker_info)

    def test_handle_upload(self):
        # Test successful upload
        request = HttpRequest()
        request.FILES['sticker'] = File('path/to/test_sticker.png', name='test_sticker.png')
        response = StickerUploader().handle_upload(request)
        self.assertEqual(response.status_code, 200)

        # Test invalid file type
        request.FILES['sticker'] = File('path/to/invalid_file.txt', name='test_sticker.txt')
        response = StickerUploader().handle_upload(request)
        self.assertEqual(response.status_code, 415)

    def test_handle_download(self):
        # Test successful download
        request = HttpRequest()
        request.GET['sticker_id'] = 'test_sticker'
        response = StickerUploader().handle_download(request)
        self.assertEqual(response.status_code, 200)

        # Test sticker not found
        request.GET['sticker_id'] = 'nonexistent_sticker'
        response = StickerUploader().handle_download(request)
        self.assertEqual(response.status_code, 404)

    def test_concurrent_uploads(self):
