```rust
use std::collections::{HashMap, HashSet};
use std::fs::File;
use std::io::{BufReader, BufRead};
use std::path::Path;
use serde::{Deserialize, Serialize};
use reqwest;
use tokio::time::{sleep, Duration};
use log::{info, warn, error};

#[derive(Debug, Deserialize, Serialize)]
struct Config {
    intervals: HashMap<String, (u64, u64)>,
}

fn fetch_data(api_url: &str, config_interval: (u64, u64)) -> Result<(), reqwest::Error> {
    let sleep_duration = Duration::from_millis(config_interval.0);
    let retry_max_attempts = config_interval.1 as u32;

    loop {
        match reqwest::get(api_url) {
            Ok(response) => {
                if response.status().is_success() {
                    return Ok(());
                }
                warn!("API request failed with status code {}", response.status());
            },
            Err(err) => {
                error!("Error fetching data: {}", err);
            },
        }

        let sleep_duration = Duration::from_millis(sleep_duration.as_millis() * 2);
        if sleep_duration.as_secs() > retry_max_attempts as u64 {
            return Err(reqwest::Error::new("Too many retries".to_string()));
        }
        sleep(sleep_duration).await?;
    }
}

async fn fetch_weather_data(location: &str, config: &Config) -> Result<String, reqwest::Error> {
    let (weather_interval, _) = config.intervals.get("weather").unwrap();
    if weather_interval.0 > 0 {
        info!("Fetching weather data for {}...", location);
        fetch_data(&format!("https://weather-api.com/{}", location), (*weather_interval).clone()).await?;
    }
    Ok(format!("Weather data for {} fetched successfully", location))
}

async fn fetch_air_quality_data(location: &str, config: &Config) -> Result<String, reqwest::Error> {
    let (air_quality_interval, _) = config.intervals.get("air-quality").unwrap();
    if air_quality_interval.0 > 0 {
        info!("Fetching air quality data for {}...", location);
        fetch_data(&format!("https://air-quality-api.com/{}", location), (*air_quality_interval).clone()).await?;
    }
    Ok(format!("Air quality data for {} fetched successfully", location))
}

async fn fetch_pollen_count_data(location: &str, config: &Config) -> Result<String, reqwest::Error> {
    let (pollen_interval, _) = config.intervals.get("pollen-count").unwrap();
    if pollen_interval.0 > 0 {
        info!("Fetching pollen count data for {}...", location);
        fetch_data(&format!("https://pollen-api.com/{}", location), (*pollen_interval).clone()).await?;
    }
    Ok(format!("Pollen count data for {} fetched successfully", location))
}

async fn main(config_file_path: &str) -> Result<(), reqwest::Error> {
    let config = serde_yaml::from_reader(BufReader::new(File::open(config_file_path)?))?;

    // Initialize the cache with a default expiration time
    let mut cache = tokio::sync::RwLock::new(HashMap::<String, String>::default());

    loop {
        for (location, interval) in config.intervals.iter() {
            match (
                fetch_weather_data(location, &config).await,
                fetch_air_quality_data(location, &config).await,
                fetch_pollen_count_data(location, &config).await,
            ) {
                Ok((_, _, _)) => {
                    info!("Data fetched successfully for {}", location);
                }
                Err(err) => {
                    error!("Error fetching data for {}: {}", location, err);
                }
            }

            // Update the cache with new data
            let mut cache = cache.write().await;
            cache.insert(location.to_string(), String::from("Data updated"));

            sleep(Duration::from_millis(interval.0)).await?;
        }
    }
}

fn main() {
    tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .build()
        .unwrap()
        .block_on(main("config.yaml"));
}
