typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int populateAndValidateNFAPIList(struct connection *connection) {
    if (strlen(connection->password) == 0 || connection->password == NULL ||
        strlen(connection->title) == 0 || connection->callback == NULL)
        return -1; // error code

    srand(time(NULL));

    int list_size = 10;
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(list_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < list_size; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 100;
        list[i].RNTI = rand() % 10000;
        list[i].CRC_INDICATION_REL8_TAG = rand() % 2 ? 1 : 0; // random CRCFLAG
    }

    FILE *file = fopen("state.bin", "rb");
    if (file == NULL)
        return -1; // error code

    ObjectInputStream ois = new ObjectInputStream(file);
    try {
        MoSTState state = (MoSTState)ois.readObject();
        fclose(file);
        free(list); // safe to do this since the file was closed
        return state;
    } catch (Exception e) {
        fclose(file);
        free(list); // safe to do this since an exception occurred
        return null; // or some other indication of failure
    }
}

int main() {
    struct connection conn;
    // ... initialize the connection structure ...

    MoSTState state = populateAndValidateNFAPIList(&conn);
    if (state != null)
        // use the loaded state object ...
