import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class LoadBalancer {
    private Map<String, Server> serverPool = new HashMap<>();
    private Selector selector;
    private int listenPort;
    private List<Server> availableServers;
    private Map<String, Integer> connectionCounts;

    public LoadBalancer(int listenPort) throws IOException {
        this.listenPort = listenPort;
        selector = Selector.open();
        availableServers = new ArrayList<>();
        connectionCounts = new HashMap<>();

        ServerSocketChannel serverSocketChannel = ServerSocketChannel.open();
        serverSocketChannel.configureBlocking(false);
        serverSocketChannel.bind(new InetSocketAddress(listenPort));
        serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);

        // Initialize server pool
        for (int i = 0; i < 3; i++) {
            Server server = new Server("localhost", 8080 + i);
            availableServers.add(server);
            connectionCounts.put(server.getServerId(), 0);
        }
    }

    public void run() throws IOException {
        while (true) {
            selector.select();
            List<SelectionKey> selectedKeys = selector.selectedKeys().aliases();

            for (SelectionKey key : selectedKeys) {
                if (key.isAcceptable()) {
                    ServerSocketChannel channel = (ServerSocketChannel) key.channel();
                    channel.accept();
                    System.out.println("Accepted new connection");
                }
            }

            // Distribute connections across available servers
            distributeConnections();
        }
    }

    private void distributeConnections() {
        for (SelectionKey key : selector.keys()) {
            ServerSocketChannel channel = (ServerSocketChannel) key.channel();
            if (channel.isBlocking()) {
                continue;
            }

            int connectionCount = connectionCounts.getOrDefault(channel.socket().getLocalPort(), 0);
            Server server = getLeastLoadedServer();

            // Assign new connection to the least loaded server
            channel.register(server.getSelectionKey());
            connectionCounts.put(server.getServerId(), connectionCount + 1);

            System.out.println("Assigned new connection to " + server.getServerId() + " with " + connectionCount + " connections");
        }
    }

    private Server getLeastLoadedServer() {
        // Implement a strategy to determine the least loaded server
        // For simplicity, assume the least loaded server is the one with the lowest connection count
        return availableServers.stream().min((server1, server2) -> Integer.compare(connectionCounts.get(server1.getServerId()), connectionCounts.get(server2.getServerId()))).get();
    }
}

class Server {
    private String serverId;
    private int listenPort;

    public Server(String serverId, int listenPort) throws IOException {
        this.serverId = serverId;
        this.listenPort = listenPort;
        // Initialize the server channel
    }

    public SelectionKey getSelectionKey() {
        // Implement a strategy to determine the selection key for the server channel
        // For simplicity, assume the selection key is the same as the server's connection count
        return new SelectionKey();
    }
}
