```cpp
#include <iostream>
#include <memory>
#include <thread>
#include <mutex>

class OctreeNode {
public:
    enum class NodeType { EMPTY, PREFIX_LEAF, DATA };

    std::unique_ptr<OctreeNode> children[3];

    NodeData data;
    bool isDirty = false;

    OctreeNode(NodeType type) : data(), children(nullptr) {
        if (type == NodeType::PREFIX_LEAF) {
            for (int i = 0; i < 8; ++i) {
                children[i] = nullptr;
            }
        } else if (type == NodeType::DATA) {
            // Initialize data structure
        }
    }

    ~OctreeNode() {
        for (auto& child : children) {
            if (child) {
                child.reset();
            }
        }
    }
};

class Octree {
public:
    OctreeNode* root;
    std::mutex mtx;

    Octree(int depth = 0) : root(nullptr), depth(depth) {}

    ~Octree() {
        deleteRecursive(root);
    }

    void addNode(OctreeNode* node) {
        if (root == nullptr) {
            root = node;
        } else {
            traverse(node, root);
        }
    }

private:
    int depth;

    void deleteRecursive(OctreeNode* node) {
        for (auto& child : node->children) {
            if (child) {
                deleteRecursive(child.get());
            }
        }
        delete node;
    }

    void traverse(OctreeNode* newNode, OctreeNode* current) {
        if (!current || !newNode) return;

        int i = 0;
        for (i = 0; i < 3 && !newNode->children[i]; ++i);

        if (i == 3) {
            // Node is at the correct location
            new (&(current->data)) NodeData(newNode->data);
            current->isDirty = false;
        } else {
            OctreeNode* child = new OctreeNode(current->depth > 0 ? OctreeNode::NodeType::EMPTY : OctreeNode::NodeType::DATA);
            child->children[1] = current;

            // Traverse the octree
            traverse(newNode, child.get());
        }
    }
};
