fn get_config_dir() -> String {
    let mut config_dir = dirs::app_data().unwrap_or_default().to_string();
    if config_dir.is_empty() {
        config_dir += "user_settings";
    }

    loop {
        match std::fs::create_dir(&config_dir) {
            Ok(_) => return config_dir,
            Err(err) => {
                log::error!("Failed to create config directory: {}", err);
                // retry up to 3 times
                if err.kind() == std::io::ErrorKind::PermissionDenied && config_dir.len() > 0 {
                    thread::sleep(std::time::Duration::from_millis(500));
                } else {
                    return "".to_string();
