```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* parseAndFormatDate(const char* input_date, const char* output_format) {
    if (input_date == NULL || strlen(input_date) != 10) {
        fprintf(stderr, "Invalid date: %s\n", input_date);
        return NULL;
    }

    // Split the input date into its year, month, and day components
    int year = atoi(strtok(input_date, "-"));
    int month = atoi(strtok(NULL, "-"));
    int day = atoi(strtok(NULL, ""));

    // Validate the date components
    if (year < 1 || year > 9999 || month < 1 || month > 12 || day < 1 || day > 31) {
        fprintf(stderr, "Invalid date: %s\n", input_date);
        return NULL;
    }

    size_t output_length = 0;
    for (const char* p = output_format; *p; p++) {
        if (*p == '%') {
            switch (*(p + 1)) {
                case 'Y': output_length += 4; break;
                case 'm': output_length += month < 10 ? 2 : 3; break;
                case 'd': output_length += day < 10 ? 2 : 3; break;
                default: continue;
            }
        } else {
            output_length++;
        }
    }

    char* result = malloc(output_length + 1);
    if (result == NULL) {
        fprintf(stderr, "Memory allocation failure.\n");
        return NULL;
    }

    int pos = 0;
    for (const char* p = output_format; *p; p++) {
        if (*p == '%') {
            switch (*(p + 1)) {
                case 'Y': sprintf(result + pos, "%04d", year); pos += 4; break;
                case 'm': sprintf(result + pos, "%02d", month); pos += month < 10 ? 2 : 3; break;
                case 'd': sprintf(result + pos, "%02d", day); pos += day < 10 ? 2 : 3; break;
                default: continue;
            }
        } else {
            result[pos++] = *p;
        }
    }

    result[output_length] = '\0';
    return result;
}

int main() {
    char* result = parseAndFormatDate("2023-10-05", "%Y-%m-%d");
    if (result) {
        printf("%s\n", result); // Should print "2023-10-05"
        free(result);
    } else {
        printf("Invalid date or memory allocation failure.\n");
    }

    result = parseAndFormatDate("2023-10-05", "%d/%m/%Y");
    if (result) {
        printf("%s\n", result); // Should print "05/10/2023"
        free(result);
    } else {
