#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure for named semaphores
typedef struct {
    char name[256];
    pthread_mutex_t lock;
    int count;
} NamedSemaphore;

// Define the structure for tenant information
typedef struct {
    char id[16]; // Tenant ID
    pthread_mutex_t lock; // Lock for this tenant's semaphores
    int numSemaphores; // Number of named semaphores
    NamedSemaphore* semaphores; // Array of named semaphores
} Tenant;

// Define the main structure for the semaphore management library
typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t cond; // Condition variable for waiting threads
    int numTenants; // Number of tenants
    Tenant* tenants; // Array of tenant information
} SemaphoreManager;

// Function to initialize a named semaphore
void initNamedSemaphore(NamedSemaphore* sem, char* name) {
    strcpy(sem->name, name);
    sem->count = 1;
    pthread_mutex_init(&sem->lock, NULL);
}

// Function to acquire a named semaphore
int acquireNamedSemaphore(NamedSemaphore* sem) {
    int result = 0;
    pthread_mutex_lock(&sem->lock);
    if (sem->count > 0) {
        sem->count--;
        result = 1;
    }
    pthread_mutex_unlock(&sem->lock);
    return result;
}

// Function to release a named semaphore
void releaseNamedSemaphore(NamedSemaphore* sem) {
    pthread_mutex_lock(&sem->lock);
    sem->count++;
    pthread_mutex_unlock(&sem->lock);
}

// Function to initialize a tenant and its semaphores
Tenant* initTenant(char* id, int numSemaphores) {
    Tenant* tenant = (Tenant*)malloc(sizeof(Tenant));
    strcpy(tenant->id, id);
    pthread_mutex_init(&tenant->lock, NULL);
    tenant->numSemaphores = numSemaphores;
    tenant->semaphores = (NamedSemaphore*)malloc(numSemaphores * sizeof(NamedSemaphore));
    for (int i = 0; i < numSemaphores; i++) {
        initNamedSemaphore(&tenant->semaphores[i], id);
    }
    return tenant;
}

// Function to initialize the semaphore management library
SemaphoreManager* initSemaphoreManager() {
    SemaphoreManager* manager = (SemaphoreManager*)malloc(sizeof(SemaphoreManager));
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);
    manager->numTenants = 0;
    manager->tenants = NULL;
    return manager;
}

// Function to add a tenant to the semaphore management library
void addTenant(SemaphoreManager* manager, Tenant* tenant) {
    manager->numTenants++;
    if (manager->numTenants == 1) {
        manager->tenants = (Tenant*)malloc(manager->numTenants * sizeof(Tenant));
    } else {
        manager->tenants = (Tenant*)realloc(manager->tenants, manager->numTenants * sizeof(Tenant));
    }
    manager->tenants[manager->numTenants - 1] = tenant;
}

// Function to free the semaphore management library
void freeSemaphoreManager(SemaphoreManager* manager) {
    for (int i = 0; i < manager->numTenants; i++) {
        for (int j = 0; j < manager->tenants[i]->numSemaphores; j++) {
            pthread_mutex_destroy(&manager->tenants[i]->semaphores[j].lock);
        }
        free(manager->tenants[i]->semaphores);
        pthread_mutex_destroy(&manager->tenants[i]->lock);
        free(manager->tenants[i]);
    }
    free(manager->tenants);
    pthread_cond_destroy(&manager->cond);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
