int transmitNFAPIData(int num_structures, NFAPI_CRC_INDICATION_PDU_T **nfalist, int *crc_flag_rules, int max_threads, char *ip_address, int port, const char *data_source_url, size_t max_memory_allocation) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    // Initialize logging function
    log_structure_operation("Transmit NFAPIData started");

    // Calculate total memory required for structures
    size_t total_memory_required = num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    // Check if allocation exceeds max_memory_allocation
    if (total_memory_required > max_memory_allocation) {
        log_structure_operation("Memory allocation exceeded; adjusting structure count");
        num_structures = max_memory_allocation / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    // Dynamically allocate memory for structures
    *nfalist = (NFAPI_CRC_INDICATION_PDU_T **)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (*nfalist == NULL) {
        log_structure_operation("Memory allocation failed; exiting");
        return -1;
    }

    // Initialize sequence generator
    seq_gen_t seq_gen;
    fetch_sequence_generator(data_source_url, &seq_gen);

    // Populate structures and set CRC flags
    pthread_t threads[max_threads];
    for (int i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T *structure = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (structure == NULL) {
            log_structure_operation("Memory allocation failed; exiting");
            return -1;
        }

        // Set RX_UE_INFORMATION_TAG and RNTI values
        setRXUEInformationTag(&structure->RX_UE_INFORMATION_TAG, &seq_gen);
        setRNTI(&structure->RNTI, &seq_gen);

        // Set CRC flag based on rule
        int crc_flag = get_crc_flag(crc_flag_rules[i % max_threads]);
        structure->CRCFLAG = crc_flag;

        // Send structure over network
        send_structure(ip_address, port, structure);

        // Log operation
        log_structure_operation("Structure created and transmitted");

        pthread_create(&threads[i], NULL, (void (*)(void *))send_structure, (void *)structure);
    }

    // Join threads
    for (int i = 0; i < num_structures; i++) {
        pthread_join(threads[i], NULL);
    }

    // Release memory and close sequence generator
    free(*nfalist);
    release_sequence_generator(&seq_gen);

    log_structure_operation("Transmit NFAPIData completed");
    return 0;
}
