        public XmlParser()
        {
            _cacheManager = new CacheManager();
            _configurationManager = new ConfigurationManager();
            _schemaValidator = new SchemaValidator();
            _logger = new Logger();
        }

        public Element FindElement(string xpathQuery)
        {
            // Get the XML document path from the configuration file
            string xmlDocumentPath = _configurationManager.GetXmlDocumentPath();

            // Load and parse the XML document using XPath and namespace handling
            XDocument xDocument;
            if (_cacheManager.Contains(xmlDocumentPath))
            {
                xDocument = _cacheManager.Get(xmlDocumentPath);
            }
            else
            {
                xDocument = ParseXmlDocument(xmlDocumentPath);
                _cacheManager.Set(xmlDocumentPath, xDocument, TimeSpan.FromDays(30));
            }

            // Evaluate the XPath query and return the first matching element
            try
            {
                XNode node = xDocument.XPathEvaluate(xpathQuery);
                if (node is XElement element)
                {
                    return element;
                }
                else
                {
                    throw new Exception($"No element found with name '{xpathQuery}'");
                }
            }
            catch (Exception ex)
            {
                // Log the error and rethrow it
                _logger.LogError(ex);
                throw;
            }
        }

        private XDocument ParseXmlDocument(string xmlDocumentPath)
        {
            // Load the XML document using a try-catch block to handle exceptions
            try
            {
                return XDocument.Load(xmlDocumentPath);
            }
            catch (IOException ex)
            {
                _logger.LogError(ex, "Failed to load XML document");
                throw;
            }
        }

