import json
import os
import importlib.util
import yaml

class JSONBase:
    def __init__(self):
        self.registry = {}

    @staticmethod
    def to_json(obj):
        pass

    @staticmethod
    def from_json(json_string):
        pass

    def register_factory(self, factory_name: str, factory_function):
        if not hasattr(factory_function, "@Registry.register_factory"):
            raise ValueError("Invalid decorator applied")
        self.registry[factory_name] = factory_function

    def load_from_yaml(self, yaml_path: str):
        with open(yaml_path, 'r') as f:
            data = yaml.safe_load(f)
        for factory_name, factory_info in data.items():
            if "factory_function" not in factory_info:
                raise ValueError("Invalid YAML format")
            self.register_factory(factory_name, factory_info["factory_function"])

    def save_to_file(self, file_path: str):
        with open(file_path, 'w') as f:
            yaml.dump({k: {"factory_function": v} for k, v in self.registry.items()}, f)

    @staticmethod
    def discover_subclasses(directory: str):
        for root, dirs, files in os.walk(directory):
            for file in files:
                if file.endswith(".py"):
                    module_name = os.path.splitext(file)[0]
                    spec = importlib.util.spec_from_file_location(module_name, os.path.join(root, file))
                    module = importlib.util.module_from_spec(spec)
                    spec.loader.exec_module(module)
                    subclass = getattr(module, f"{module_name}")
                    if hasattr(subclass, "@Registry.register_factory"):
                        JSONBase().register_factory(f"{module_name}", subclass)

    def to_json(self, obj):
        pass

    def from_json(self, json_string: str) -> object:
        pass
