import logging
import os
import time
import datetime
from logging.handlers import RotatingFileHandler
from functools import lru_cache
import requests
import json

LOG_LEVELS = {"DEBUG": logging.DEBUG, "INFO": logging.INFO, 
              "WARNING": logging.WARNING, "ERROR": logging.ERROR, "CRITICAL": logging.CRITICAL}

@lru_cache(maxsize=None)
def get_log_dir(config):
    if 'log_dir' in config:
        return os.path.join(config['log_dir'], f"logs_run_{int(time.time())}")
    else:
        return os.path.join("/var/log/myapp/", f"logs_run_{int(time.time())}")

@lru_cache(maxsize=None)
def get_log_file(log_dir):
    if not os.path.exists(log_dir):
        os.makedirs(log_dir, exist_ok=True)
    log_file = os.path.join(log_dir, f"log{datetime.datetime.now().strftime('%Y-%m-%d')}.log")
    return log_file

@lru_cache(maxsize=None)
def get_log_aggregator(config):
    if 'log_agg_service' in config:
        service_name = config['log_agg_service']
        if service_name == "splunk":
            from splunk.client import Splunk
            return Splunk()
        elif service_name == "elk_stack":
            # Implement ELK Stack integration
            pass
        else:
            raise ValueError(f"Unsupported log aggregation service: {service_name}")
    else:
        return None

def setup_logging(config):
    root_logger = logging.getLogger()
    root_logger.setLevel(logging.DEBUG)

    log_dir = get_log_dir(config)
    if not os.path.exists(log_dir):
        os.makedirs(log_dir, exist_ok=True)

    log_file = get_log_file(log_dir)
    file_handler = RotatingFileHandler(log_file, maxBytes=1000000, backupCount=5)
    file_handler.setLevel(logging.DEBUG)

    console_handler = logging.StreamHandler()
    console_handler.setLevel(logging.INFO)

    formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
    file_handler.setFormatter(formatter)
    console_handler.setFormatter(formatter)

    root_logger.addHandler(file_handler)
    root_logger.addHandler(console_handler)

    log_level = config.get('log_level', 'INFO')
    if log_level.upper() in LOG_LEVELS:
        root_logger.setLevel(LOG_LEVELS[log_level.upper()])
    else:
        raise ValueError(f"Invalid log level: {log_level}")

    if get_log_aggregator(config):
        aggregator = get_log_aggregator(config)
        aggregator.set_config(config)

def main():
    config = {
        'log_dir': '/var/log/myapp/',
        'log_agg_service': 'splunk',
        'log_level': 'INFO'
    }
    setup_logging(config)

if __name__ == "__main__":
    main()
