using System;
using System.Security.Cryptography;
using System.Text;

public class SecureMessageProcessor
{
    private readonly ICspService _primaryCsp;
    private readonly ICspService _backupCsp;
    private readonly object _lock = new object();

    public SecureMessageProcessor(ICspService primaryCsp, ICspService backupCsp)
    {
        _primaryCsp = primaryCsp;
        _backupCsp = backupCsp;
    }

    public void ProcessDecryptionRequests(List<Message> messages)
    {
        foreach (var message in messages)
        {
            DecryptMessage(message);
        }
    }

    private void DecryptMessage(Message message)
    {
        using (var tripleDesAlg = TripleDESCryptoServiceProvider.Create())
        {
            var encryptionKey = GetEncryptionKey();
            var initializationVector = GetInitializationVector();

            tripleDesAlg.Key = encryptionKey;
            tripleDesAlg.IV = initializationVector;

            var encryptedData = Convert.FromBase64String(message.Data);
            var decryptedData = Decrypt(encryptedData, tripleDesAlg);

            message.DecryptedText = Encoding.UTF8.GetString(decryptedData);
        }
    }

    private byte[] GetEncryptionKey()
    {
        // Call the CSP service to get the decryption key
        return _primaryCsp.GetDecryptionKey();
    }

    private byte[] GetInitializationVector()
    {
        // Call the CSP service to get the initialization vector
        return _primaryCsp.GetInitializationVector();
    }

    private byte[] Decrypt(byte[] data, TripleDESCryptoServiceProvider tripleDesAlg)
    {
        using (var memoryStream = new MemoryStream())
        {
            using (var cryptoStream = new CryptoStream(memoryStream, tripleDesAlg.CreateDecryptor()))
            {
                cryptoStream.Write(data, 0, data.Length);
                cryptoStream.FlushFinalBlock();
                return memoryStream.ToArray();
            }
        }
    }

    public void RotateKeys()
    {
        // Call the CSP service to rotate decryption keys
        _primaryCsp.RotateDecryptionKeys();
    }

    public void FailoverToBackupCsp()
    {
        lock (_lock)
        {
            if (!_primaryCsp.IsAvailable())
            {
                // Switch to backup CSP
                _primaryCsp = _backupCsp;
            }
        }
    }
}

public interface ICspService
{
    byte[] GetDecryptionKey();
    byte[] GetInitializationVector();
    void RotateDecryptionKeys();
    bool IsAvailable();
}

// Testing framework
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public class SecureMessageProcessorTests
{
    [TestMethod]
    public void TestDecryptMessage()
    {
        // Arrange
        var message = new Message { Data = "base64 encoded data" };
        var secureMessageProcessor = new SecureMessageProcessor(new PrimaryCspService(), new BackupCspService());

        // Act
        secureMessageProcessor.ProcessDecryptionRequests(new List<Message> { message });

        // Assert
        Assert.AreEqual("decrypted text", message.DecryptedText);
    }

    [TestMethod]
    public void TestRotateKeys()
    {
        // Arrange
        var secureMessageProcessor = new SecureMessageProcessor(new PrimaryCspService(), new BackupCspService());

        // Act
        secureMessageProcessor.RotateKeys();

        // Assert
        // Verify key rotation with the CSP service
    }

    [TestMethod]
    public void TestFailoverToBackupCsp()
    {
        // Arrange
        var primaryCsp = new PrimaryCspService();
        primaryCsp.IsAvailable = false;
        var backupCsp = new BackupCspService();

        var secureMessageProcessor = new SecureMessageProcessor(primaryCsp, backupCsp);

        // Act
        secureMessageProcessor.FailoverToBackupCsp();

