/**
 * Asynchronous reduce for an array of numbers and numeric strings
 * @param {Array<number|string>} arr - Input array to be reduced
 * @param {(a: number, b: number) => number} fn - Reduction function
 * @param {number} [concurrency=10] - Number of parallel operations
 * @returns {*} Reduced value or error if encountered
 */
async function asyncReduce(arr, fn, concurrency = 10) {
  const logger = console.log;

  // Helper function to convert numeric strings to integers and handle errors
  function parseNumber(val) {
    try {
      return parseInt(val);
    } catch (err) {
      throw new Error(`Invalid number format: ${val}`);
    }
  }

  // Caching mechanism for subarray results
  const cache = new Map();

  async function reduce(arr, fn, offset, callback) {
    if (!arr.length) return callback(null);

    const chunkSize = Math.floor(arr.length / concurrency);
    let start = offset;

    while (start < arr.length) {
      const end = Math.min(start + chunkSize, arr.length);
      const subarray = arr.slice(start, end);

      try {
        // Convert numeric strings to integers and perform reduction
        const reducedValue = await Promise.all(subarray.map((num) => parseNumber(num)).map((num) => fn(num, cache.get(num.toString()))));
        cache.set(reducedValue.toString(), reducedValue);
        start = end;
      } catch (err) {
        if (err instanceof Error && err.message.includes('Invalid number format')) {
          logger.error(`Invalid number format: ${JSON.stringify(subarray)}`);
          return callback(err);
        }
        throw err;
      }

      // Rate-limiting to control parallel operations
      await new Promise((resolve) => setTimeout(resolve, 10));
    }

    return callback(null, reducedValue);
  }

  const result = await reduce(arr, fn, 0, (err, value) => {
    if (err) {
      logger.error(err.message);
      process.exit(1); // Exit with an error code
    } else {
      logger.info(`Reduced value: ${value}`);
      return value;
    }
  });

  return result;
}
