import json
from datetime import datetime
import uuid
from decimal import Decimal

class JSONSerializable:
    _factory_registry = {}

    @classmethod
    def register_factory(cls, name: str):
        return cls._factory_registry.setdefault(name, lambda: None)

    @classmethod
    def get_factory(cls, name: str):
        return cls._factory_registry.get(name, None)

    @classmethod
    def from_json(cls, data: str) -> object:
        try:
            obj = json.loads(data)
            factory_name = type(obj).__name__
            factory = cls.get_factory(factory_name)
            if factory:
                return factory(obj)
            raise ValueError(f"Unsupported type {type(obj).__name__}")
        except json.JSONDecodeError as e:
            raise ValueError("Invalid JSON input") from e

    @classmethod
    def to_json(cls, obj: object) -> str:
        factory_name = type(obj).__name__
        factory = cls.get_factory(factory_name)
        if factory:
            return json.dumps(factory(obj))
        raise ValueError(f"Unsupported type {type(obj).__name__}")

    @classmethod
    def deserialize_datetime(cls, data):
        if isinstance(data, dict) and 'iso' in data:
            return datetime.fromisoformat(data['iso'])
        return None

    @classmethod
    def serialize_datetime(cls, dt: datetime) -> dict:
        return {'iso': dt.isoformat()}

    @classmethod
    def deserialize_uuid(cls, data):
        if isinstance(data, str):
            return uuid.UUID(data)
        return None

    @classmethod
    def serialize_uuid(cls, uuid: uuid.UUID) -> str:
        return str(uuid)

    @classmethod
    def deserialize_decimal(cls, data):
        if isinstance(data, dict) and 'value' in data and 'scale' in data:
            value = Decimal(str(data['value']))
            scale = data['scale']
            return value / (10 ** -scale)
        return None

    @classmethod
    def serialize_decimal(cls, dec: Decimal) -> dict:
        scale = 0 if int(dec) == dec else 10
        return {'value': str(int(dec)), 'scale': scale}
