import org.apache.commons.pool2.impl.GenericObjectPoolConfig;
import redis.clients.jedis.Jedis;

import javax.annotation.concurrent.ThreadSafe;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.*;
import java.util.function.Function;

@ThreadSafe
public class ConfigurationManager {
    private static final int MAX_THREADS = Integer.parseInt(System.getProperty("config.max.threads", "5"));
    private static final int CACHE_SIZE = Integer.parseInt(System.getProperty("config.cache.size", "1000"));
    private static final ObjectMapper mapper = new ObjectMapper(new Jdk8Module());
    private static final ExecutorService executor = new ThreadPoolExecutor(MAX_THREADS, MAX_THREADS, 0L, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<Runnable>());
    private static final Jedis jedis = new Jedis("localhost");

    private Map<String, Function<String, Configuration>> parsers;
    private ConcurrentLinkedQueue<Configuration> cache;

    public ConfigurationManager() {
        parsers = new HashMap<>();
        cache = new ConcurrentLinkedQueue<>();
    }

    public void addParser(String type, Function<String, Configuration> parser) {
        parsers.put(type, parser);
    }

    public Configuration parseConfig(String type, String configStr) throws IOException {
        return parsers.get(type).apply(configStr);
    }

    public boolean saveConfig(String type, Configuration config) {
        // serialize and save to Redis
        jedis.set("config:" + type, mapper.writeValueAsString(config));
        return true;
    }

    public void loadConfig(String type) {
        // deserialize from Redis
        String configStr = jedis.get("config:" + type);
        if (configStr != null) {
            Configuration config = mapper.readValue(configStr, Configuration.class);
            cache.add(config);
        }
    }

    public boolean notifyServices(Configuration config) {
        // send notification to connected services
        return true;
    }
}
