    int currentCooldown;
    std::mutex energyMutex;
    std::mutex cooldownMutex;

    void selectAndExecuteAttack(Attack& selectedAttack) {
        if (!isReady(selectedAttack)) {
            return; // Attack is still in cooldown or lacks sufficient energy
        }

        try {
            updateEnergy(-selectedAttack.getEnergyCost());
            currentCooldown = selectedAttack.getCoolDownTime();
            executeAttack(selectedAttack);
        } catch (const std::exception& e) {
            logError("Error executing attack: " + e.what());
        }
    }

private:
    bool isReady(const Attack& attack) {
        return energyLevel >= attack.getEnergyCost() && currentCooldown == 0;
    }

    void updateEnergy(int delta) {
        std::lock_guard<std::mutex> lock(energyMutex);
