#include <stdlib.h>
#include <stdio.h>

int generateNfalist(int num_structures, NFAPI_CRC_INDICATION_PDU_T **nfalist, int *crc_flag_rules, int log_level) {
    // Allocate memory for the list of structures and check for allocation failure.
    *nfalist = (NFAPI_CRC_INDICATION_PDU_T **)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (*nfalist == NULL) {
        return -1; // Allocation failed
    }

    int i;
    for (i = 0; i < num_structures; i++) {
        // Populate each structure with unique RX_UE_INFORMATION_TAG and RNTI values within a specified range.
        NFAPI_CRC_INDICATION_PDU_T *nfa_pdu_t = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (nfa_pdu_t == NULL) {
            return -1; // Allocation failed
        }

        nfa_pdu_t->RX_UE_INFORMATION_TAG = i + 1;
        nfa_pdu_t->RNTI = i % 9000 + 1000;

        // Set the CRCFLAG based on the corresponding rule in crc_flag_rules.
        nfa_pdu_t->CRCFLAG = (i % 2 == 0) ? crc_flag_rules[i] : !crc_flag_rules[i];

        // Log the creation of each structure using the external logging function log_structure_creation at the given log_level.
        printf("Structure created with tag %d and RNTI %d, CRC flag set to %d.\n", i + 1, nfa_pdu_t->RNTI, nfa_pdu_t->CRCFLAG);

        // Add the structure to the list of structures
        (*nfalist)[i] = nfa_pdu_t;
    }

    return 0; // Structures created successfully
}

