        const metadata = await this.getMetadata(file);
        // process file using the metadata
      } catch (error) {
        console.error(`Error processing file: ${file}`, error);
      }
    }
  }

  async readConfigurationFile() {
    const content = await fs.promises.readFile(this.configurationFile, 'utf8');
    return JSON.parse(content).map(file => path.resolve(file));
