def process_file(file_path: str, keyword_filter: str = None, logger: logging.Logger = None) -> int:
    if logger is None:
        logger = logging.getLogger(__name__)
        logger.addHandler(logging.StreamHandler())
        logger.setLevel(logging.ERROR)

    sequence_numbers = []
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            for line in file:
                parts = line.strip().split(':')
                if len(parts) != 2:
                    logger.error(f"Improperly formatted line: {line}")
                    continue
                seq_num, data = parts
                if keyword_filter and keyword_filter not in data:
                    continue
                sequence_numbers.append(int(seq_num))
    except IOError as e:
        logger.error(f"Error reading file: {e}")
    except ValueError as e:
        logger.error(f"Invalid sequence number: {e}")

    try:
        sequence_numbers.sort()
        return int(sequence_numbers[-1])
    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
