```
function loadDynamicContent(contents) {
  const concurrencyLimit = 3;
  const timeoutMs = 5000;
  let scriptQueue = [];
  let renderQueue = [];

  contents.forEach((content) => {
    if (content.url) {
      scriptQueue.push({ url: content.url, key: content.key });
    } else {
      renderQueue.push(content.code);
    }
  });

  async function loadScript(script) {
    return new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      xhr.open('GET', script.url, true);
      xhr.onload = () => {
        if (xhr.status === 200) {
          resolve(xhr.responseText);
        } else {
          reject(new Error(`Failed to load script: ${script.url}`));
        }
      };
      xhr.onerror = () => {
        reject(new Error(`Error loading script: ${script.url}`));
      };
      xhr.send();
    });
  }

  async function renderContent(content) {
    return new Promise((resolve, reject) => {
      if (content.key) {
        const scriptTag = document.createElement('script');
        scriptTag.src = content.url;
        scriptTag.onload = () => resolve();
        scriptTag.onerror = () => reject(new Error(`Error loading script: ${content.url}`));
        document.querySelector('footer').appendChild(scriptTag);
      } else {
        resolve(content.code);
      }
    });
  }

  async function render() {
    const promises = [];
    let concurrentRequests = 0;

    for (const content of scriptQueue) {
      if (concurrentRequests >= concurrencyLimit) {
        await Promise.any(promises);
        promises = [];
        concurrentRequests = 0;
      }
      promises.push(loadScript(content));
      concurrentRequests++;
    }

    await Promise.all(promises);

    for (const code of renderQueue) {
      const scriptTag = document.createElement('script');
      scriptTag.textContent = code;
      document.querySelector('footer').appendChild(scriptTag);
    }
  }

  return render();
}
