```
import asyncio
import os
import logging
from typing import List

logging.basicConfig(level=logging.INFO)

class FileMergingError(Exception):
    pass

class FileMerger:
    def __init__(self, source_files: List[str], destination_file: str):
        self.source_files = source_files
        self.destination_file = destination_file
        self.total_size = 0
        self.chunk_size = 1024 * 1024
        self.max_retries = 5
        self.backoff_interval = 2

    async def merge(self) -> None:
        try:
            self.validate_source_files()
            await self.merge_files()
        except FileMergingError as e:
            logging.error(f"File merging failed: {e}")

    def validate_source_files(self) -> None:
        for file in self.source_files:
            if not os.path.exists(file):
                raise FileMergingError(f"Source file '{file}' does not exist")
            if not os.path.isfile(file):
                raise FileMergingError(f"'{file}' is not a regular file")

    async def merge_files(self) -> None:
        tasks = []
        for file in self.source_files:
            task = asyncio.create_task(self.read_file(file))
            tasks.append(task)

        while len(tasks) > 0:
            done, pending = await asyncio.wait(tasks)
            for task in done:
                if task.exception():
                    raise task.exception()

        with open(self.destination_file, "wb") as dest_file:
            for file in self.source_files:
                try:
                    with open(file, "rb") as src_file:
                        while True:
                            data = await asyncio.create_task(self.read_chunk(src_file))
                            dest_file.write(data)
                            if len(data) < self.chunk_size:
                                break
                except OSError as e:
                    logging.error(f"I/O error reading file '{file}': {e}")
                    raise FileMergingError(f"File merging failed: {e}")

        logging.info("File merging complete")

    async def read_file(self, file_path: str) -> bytes:
        try:
            with open(file_path, "rb") as file:
                return await asyncio.create_task(self.read_chunk(file))
        except OSError as e:
            raise FileMergingError(f"I/O error reading file '{file_path}': {e}")

    async def read_chunk(self, file: asyncio.StreamReader) -> bytes:
        data = bytearray()
        while True:
            chunk = await file.read(self.chunk_size)
            if len(chunk) < self.chunk_size:
                break
            data.extend(chunk)
        return bytes(data)

if __name__ == "__main__":
    merger = FileMerger(["file1.txt", "file2.txt"], "merged_file.txt")
    asyncio.run(merger.merge())
```

