```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

public class XmlParser : IXmlParser
{
    private readonly XmlDocument _document;
    private readonly Dictionary<string, XElement> _cache = new();
    private readonly ILogger _logger;
    private bool _isAsynchronousModeEnabled = false;

    public XmlParser(XmlDocument document, ILogger logger)
    {
        _document = document;
        _logger = logger;
    }

    public void EnableAsynchronousMode()
    {
        _isAsynchronousModeEnabled = true;
    }

    public void DisableAsynchronousMode()
    {
        _isAsynchronousModeEnabled = false;
    }

    public string GetSingleElementValue(string xpathExpression)
    {
        if (_isAsynchronousModeEnabled)
        {
            return GetSingleElementValueAsync(xpathExpression).Result;
        }
        else
        {
            return GetSingleElementValueSync(xpathExpression);
        }
    }

    private string GetSingleElementValueSync(string xpathExpression)
    {
        var elements = _document.SelectNodes(xpathExpression);

        if (elements == null || elements.Count < 1)
        {
            throw new FileNotFoundException("No element found matching the XPath expression.", xpathExpression);
        }
        else if (elements.Count > 1)
        {
            throw new MultipleElementException("More than one element found matching the XPath expression.", xpathExpression);
        }

        return elements.FirstOrDefault()?.InnerText;
    }

    private async Task<string> GetSingleElementValueAsync(string xpathExpression)
    {
        var elements = await _document.SelectNodesAsync(xpathExpression);

        if (elements == null || elements.Count < 1)
        {
            throw new FileNotFoundException("No element found matching the XPath expression.", xpathExpression);
        }
        else if (elements.Count > 1)
        {
            throw new MultipleElementException("More than one element found matching the XPath expression.", xpathExpression);
        }

        return await Task.Run(() => elements.FirstOrDefault()?.InnerText);
    }

    public List<string> GetElementsValues(string xpathExpression)
    {
        var results = _cache.GetOrAdd(xpathExpression, () =>
        {
            var elements = _document.SelectNodes(xpathExpression);

            if (elements == null) return new List<string>();

            return elements?.Select(e => e.InnerText).ToList();
        });

        return results;
    }

    public Dictionary<string, string> ExtractAttributes(string xpathExpression)
    {
        try
        {
            var element = _document.SelectSingleNode(xpathExpression);
            if (element == null) return new Dictionary<string, string>();

            return element.Attributes?.ToDictionary(a => a.Name, a => a.Value);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error extracting attributes for XPath expression: {0}", xpathExpression);
            return new Dictionary<string, string>();
        }
    }

    public void ManipulateTextNodes(string xpathExpression, Func<string, string> manipulator)
    {
        try
        {
            var elements = _document.SelectNodes(xpathExpression);

            if (elements == null) return;

            foreach (var element in elements)
            {
                var textNodes = element.SelectNodes("text()");

                if (textNodes == null || textNodes.Count < 1) continue;

                foreach (var textNode in textNodes)
                {
                    textNode.InnerText = manipulator(textNode.InnerText);
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error manipulating text nodes for XPath expression: {0}", xpathExpression);
        }
    }
}
