// Define a struct for log entry
typedef struct {
    char ip_address[16];
    time_t timestamp;
    int response_status_code;
} LogEntry;

// Function to parse and process log entries
void* process_log_entries(void* arg) {
    // Define the structure of the log format
    static const char* LOG_FORMAT = "%15s %10ld %3d";

    // Open a file for writing statistics
    FILE* stats_file = fopen("stats.txt", "w");

    // Initialize variables to store aggregated statistics
    int max_status_code = 0;
    int total_requests = 0;

    while (1) {
        // Read a log entry from the standard input
        LogEntry log_entry;
        if (!fscanf(stdin, LOG_FORMAT, log_entry.ip_address, &log_entry.timestamp, &log_entry.response_status_code)) {
            break;  // End of file or error reading log entry
        }

        // Update aggregated statistics
        total_requests++;
        max_status_code = (log_entry.response_status_code > max_status_code) ? log_entry.response_status_code : max_status_code;
    }

    // Calculate and write aggregated statistics to the stats file
    fprintf(stats_file, "Total requests: %d\n", total_requests);
    fprintf(stats_file, "Max response status code: %d\n", max_status_code);

    fclose(stats_file);
}

int main() {
    int num_threads = 4;  // Adjust this value based on available CPU resources

    // Create an array of threads
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        if (pthread_create(&threads[i], NULL, process_log_entries, NULL) != 0) {
            perror("Thread creation failed");
            exit(EXIT_FAILURE);
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
