import json
import yaml
import logging

class ConfigurationManager:
    def __init__(self, config_data):
        self.config_data = config_data

def load_configuration_manager(config_file_path: str) -> 'ConfigurationManager':
    try:
        with open(config_file_path, 'r') as file:
            file_content = file.read()

        if file_content.startswith('---'):
            config_data = yaml.safe_load(file_content)
        else:
            config_data = json.loads(file_content)

    except Exception as e:
        logging.error(f"Error parsing configuration file: {e}")
        raise ValueError("Invalid or corrupted configuration file")

    try:
        manager_class_name = config_data.pop('manager_class')
        manager_class = globals().get(manager_class_name)

        if not isinstance(manager_class, type):
            raise ValueError(f"Configuration manager class '{manager_class_name}' does not exist")

        manager_instance = manager_class(**config_data)

        return manager_instance

    except Exception as e:
        logging.error(f"Error creating configuration manager: {e}")
        raise ValueError("Invalid or corrupted configuration file")

