const { parallel, map } = require('p-map');
const rateLimiter = require('rate-limiter-flexible');

function asyncReduce(arr, initialValue, callback) {
  if (!Array.isArray(arr)) throw new Error('Input must be an array');
  if (typeof initialValue !== 'number') throw new Error('Initial value must be a number');
  if (typeof callback !== 'function') throw new Error('Callback function is required');

  const initialDbValue = fetchInitialValueFromDatabase();
  let currentAccumulator = initialValue;

  // Rate limiter for database queries
  const dbRateLimiter = rateLimiter({
    points: 5, // Allow up to 5 concurrent queries
    duration: 1, // Per second
  });

  function processChunk(chunk) {
    return map(chunk, (num) => {
      currentAccumulator = callback(currentAccumulator, num);
      return { value: currentAccumulator };
    });
  }

  async function reduce() {
    const chunkSize = Math.floor(Math.sqrt(arr.length));
    let start = 0;

    while (start < arr.length) {
      const end = start + chunkSize;
      const chunk = arr.slice(start, end);

      try {
        // Process the chunk in parallel
        const results = await parallel(processChunk.bind(null, chunk));
        currentAccumulator = reduceChunk(results);
      } catch (error) {
        // Handle errors during processing
        console.error('Error during processing:', error);
        return null;
      }

      start = end;
    }

    return { value: currentAccumulator };
  }

  async function storeFinalResult() {
    try {
      await storeValueInDatabase(currentAccumulator);
    } catch (error) {
      // Handle errors during storage
      console.error('Error storing final result:', error);
      return null;
    }
  }

  async function run() {
    const initialResult = await reduce();
    if (!initialResult) return;

    const finalResult = await storeFinalResult();
    if (!finalResult) return;

    return finalResult.value;
  }

  return run();
}

