const express = require('express');
const app = express();
const redis = require('redis');
const client = redis.createClient({ host: 'localhost', port: 6379 });
const { userManagement } = require('./user-management-service');
const { paymentGateway } = require('./payment-gateway-api');
const { logisticsProvider } = require('./logistics-provider-api');

app.use(express.json());
app.use(express.urlencoded({ extended: true }));

app.use((req, res, next) => {
  const token = req.header('Authorization');
  if (!token) {
    return res.status(401).send({ error: 'Unauthorized' });
  }
  userManagement.validateToken(token)
    .then(() => next())
    .catch(() => res.status(401).send({ error: 'Invalid token' }));
});

app.get('/products/:id', async (req, res) => {
  const id = req.params.id;
  try {
    const product = await client.get(`product:${id}`);
    if (!product) return res.status(404).send({ error: 'Product not found' });
    res.json(JSON.parse(product));
  } catch (error) {
    console.error(error);
    res.status(500).send({ error: 'Internal Server Error' });
  }
});

app.get('/products', async (req, res) => {
  try {
    const products = await client.lrange('products', 0, -1);
    if (!products) return res.status(404).send({ error: 'No products found' });
    res.json(products.map(JSON.parse));
  } catch (error) {
    console.error(error);
    res.status(500).send({ error: 'Internal Server Error' });
  }
});

app.put('/products/:id', async (req, res) => {
  const id = req.params.id;
  try {
    await client.set(`product:${id}`, JSON.stringify(req.body));
    res.json({ message: 'Product updated successfully' });
  } catch (error) {
    console.error(error);
    if (error.message.includes(' EEXIST')) {
      res.status(409).send({ error: 'Conflict: product already exists' });
    } else {
      res.status(500).send({ error: 'Internal Server Error' });
    }
  }
});

app.delete('/products/:id', async (req, res) => {
  const id = req.params.id;
  try {
    await client.del(`product:${id}`);
    await paymentGateway.cancelOrder(id);
    logisticsProvider.updateStatus(id, 'deleted');
    res.json({ message: 'Product deleted successfully' });
  } catch (error) {
    console.error(error);
    if (error.message.includes('ENODATA')) {
      res.status(404).send({ error: 'Product not found' });
    } else {
      res.status(500).send({ error: 'Internal Server Error' });
    }
  }
});

app.put('/products/:id', async (req, res) => {
  const id = req.params.id;
  try {
    await client.set(`product:${id}`, JSON.stringify(req.body));
    res.json({ message: 'Product updated successfully' });
  } catch (error) {
    console.error(error);
    if (error.message.includes(' EEXIST')) {
      res.status(409).send({ error: 'Conflict: product already exists' });
    } else {
      res.status(500).send({ error: 'Internal Server Error' });
    }
  }
});

app.use((req, res) => {
  res.set('Content-Type', 'application/json');
  res.json({ message: 'Invalid request' });
});

const rateLimit = require('express-rate-limit');

app.use(rateLimit({
  windowMs: 60000, // 1 minute
  max: 500, // 500 requests per windowMs
}));

app.listen(3000, () => {
  console.log('API listening on port 3000');
});
