#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int max_message_length;
    bool logging_enabled;
} config_t;

config_t *config = NULL;

void logConditionalMessage(bool condition, const char *language, const char *format, ...) {
    if (!condition || !config->logging_enabled) return;

    va_list args;
    va_start(args, format);

    static char message[1024];
    int len = vsnprintf(message, sizeof(message), format, args);
    if (len < 0 || len >= config->max_message_length) {
        fprintf(stderr, "Error: Message too long. Truncated.\n");
        return;
    }

    FILE *log_file = fopen("error.log", "a+");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    pthread_mutex_lock(&log_file->lock);
    fwrite(message, 1, len + 1, log_file);
    fflush(log_file);
    pthread_mutex_unlock(&log_file->lock);

    fclose(log_file);
}

void set_config(config_t *cfg) {
    config = cfg;
}
