import java.io.*;
import java.util.*;
import java.time.*;

public class StateLoader {

    private static final int MAX_CACHE_SIZE = 10000;
    private static final long DEFAULT_EXPIRATION_TIME_MILLIS = 30 * 24 * 60 * 60 * 1000; // 30 days

    private Map<String, State> cache;
    private StateManager stateManager;
    private Logger logger;

    public StateLoader(StateManager stateManager, int maxCacheSize, long expirationTimeMillis) {
        this.stateManager = stateManager;
        this.cache = new LRU Cache<>(maxCacheSize);
        this.logger = Logger.getLogger(StateLoader.class.getName());
    }

    public State loadState(String id) {
        State cachedState = cache.get(id);
        if (cachedState != null && !isExpired(cachedState.getLastUpdate())) {
            logger.info("Cache hit for state " + id);
            return cachedState;
        }

        try {
            State stateFromService = stateManager.getState(id);
            if (stateFromService != null) {
                // Check version and update cache if necessary
                if (!cachedState.getVersion().equals(stateFromService.getVersion())) {
                    cachedState = stateFromService;
                }
                logger.info("Loaded state " + id + " from service");
            } else {
                logger.warning("Failed to load state " + id);
            }

            return cachedState;
        } catch (Exception e) {
            logger.error("Error loading state " + id, e);
            // Fallback strategy: Try to load from cache
            if (cachedState != null) {
                return cachedState;
            }
            return null;
        } finally {
            // Always close the InputStream
            try {
                stateManager.closeInputStream();
            } catch (Exception e) {
                logger.error("Error closing stream", e);
            }
        }
    }

    public State loadState(String id, int version) {
        State cachedState = cache.get(id);
        if (cachedState != null && !isExpired(cachedState.getLastUpdate()) && cachedState.getVersion() == version) {
            logger.info("Cache hit for state " + id + " with version " + version);
            return cachedState;
        }

        try {
            State stateFromService = stateManager.getState(id, version);
            if (stateFromService != null) {
                // Update cache
                cachedState = stateFromService;
                logger.info("Loaded state " + id + " with version " + version + " from service");
            } else {
                logger.warning("Failed to load state " + id + " with version " + version);
            }

            return cachedState;
        } catch (Exception e) {
            logger.error("Error loading state " + id + " with version " + version, e);
            // Fallback strategy: Try to load from cache
            if (cachedState != null) {
                return cachedState;
            }
            return null;
        } finally {
            try {
                stateManager.closeInputStream();
            } catch (Exception e) {
                logger.error("Error closing stream", e);
            }
        }
    }

    public void startBackgroundJob() {
        // Start a background job to clean up expired or unused state objects from the cache
        new Timer().schedule(new TimerTask() {
            @Override
            public void run() {
                cleanUpCache();
            }
        }, 0, 60 * 1000); // Run every minute

        // Periodically synchronize the cache with the external state management service to ensure data consistency
        new Timer().schedule(new TimerTask() {
            @Override
            public void run() {
                syncCacheWithService();
            }
        }, 30 * 60 * 1000, 60 * 60 * 1000); // Run every 30 minutes and then every hour
    }

    private boolean isExpired(long lastUpdate) {
        return System.currentTimeMillis() - lastUpdate > expirationTimeMillis;
    }

    private void cleanUpCache() {
        // Implement cache cleaning logic here
    }

    private void syncCacheWithService() {
        // Implement cache synchronization logic here
    }
}
