import importlib
import os
import logging
from multiprocessing import Process
from queue import Queue
from threading import Lock

class DatabaseDriverPool:
    def __init__(self, config_file):
        self.config_file = config_file
        self.supported_drivers = []
        self.driver_modules = {}
        self.connection_pool = {}
        self.lock = Lock()
        self.queue = Queue()

    def load_config(self):
        with open(self.config_file, 'r') as f:
            config = json.load(f)
        return config

    def load_drivers(self, config):
        for driver in config['drivers']:
            try:
                module_name = f"database_driver_{driver}"
                module = importlib.import_module(module_name)
                self.driver_modules[module_name] = module
                self.supported_drivers.append(driver)
            except ImportError:
                logging.error(f"Failed to load {module_name}. Skipping.")

    def add_driver(self, driver):
        if driver not in self.supported_drivers:
            return False
        try:
            self.connection_pool[driver] = []
            return True
        except Exception as e:
            logging.error(str(e))
            return False

    def get_connection(self, driver):
        if driver not in self.connection_pool:
            return None
        try:
            connection = self.connection_pool[driver].pop(0)
            return connection
        except IndexError:
            return None

    def put_connection(self, driver, connection):
        if driver not in self.connection_pool:
            return False
        with self.lock:
            self.connection_pool[driver].append(connection)
        return True

    def clean_up_connections(self):
        for driver in self.connection_pool:
            while len(self.connection_pool[driver]) > 1:
                self.put_connection(driver, self.get_connection(driver))
