function renderFooterScripts(scriptObjects) {
  const cachedScripts = {};
  const priorityScripts = scriptObjects.filter(s => s.priority);
  const normalScripts = scriptObjects.filter(s => !s.priority);

  return fetchScripts(priorityScripts, 'high').then(highScripts => {
    return fetchScripts(normalScripts, 'low', highScripts).then(lowScripts => {
      const scriptsHTML = highScripts.reduce((acc, current) => `${acc}<script src="${current.src}" type="${current.type}" key="${current.key}"></script>`, '');
      scriptsHTML += lowScripts.reduce((acc, current) => `${acc}<script src="${current.src}" type="${current.type}" key="${current.key}"></script>`, '');

      return scriptsHTML;
    });
  }).catch(error => {
    console.error('Error fetching scripts:', error);
    return '';
  });

  async function fetchScripts(scripts, priority, cached = []) {
    const maxParallelRequests = 4;

    if (priority) {
      for (const script of scripts) {
        try {
          const response = await fetchScript(script, 'high');
          if (!response.ok) {
            throw new Error(`Failed to fetch high-priority script ${script.src}`);
          }
          cachedScripts[script.key] = await response.text();
        } catch (error) {
          console.error('Error fetching high-priority script:', error);
          await retryFetchScript(script, 'high');
        }
      }
    } else {
      for (const script of scripts) {
        try {
          const response = await fetchScript(script, 'low', cached);
          if (!response.ok) {
            throw new Error(`Failed to fetch low-priority script ${script.src}`);
          }
          cachedScripts[script.key] = await response.text();
        } catch (error) {
          console.error('Error fetching low-priority script:', error);
          await retryFetchScript(script, 'low', cached);
        }
      }
    }

    async function retryFetchScript(script, priority, cached = []) {
      for (let i = 0; i < 3; i++) {
        try {
          const response = await fetchScript(script, priority, cached);
          if (!response.ok) {
            throw new Error(`Failed to fetch script ${script.src} after retries`);
          }
          cachedScripts[script.key] = await response.text();
          return;
        } catch (error) {
          console.error('Error fetching script:', error);
          await waitBeforeNextAttempt(i * 500);
        }
      }
    }

    async function waitBeforeNextAttempt(ms) {
      await new Promise(resolve => setTimeout(() => resolve(), ms));
    }

    async function fetchScript(script, priority, cached = []) {
      const client = new HTTPClient();
      const metadataResponse = await client.get(`https://metadata-service.com/script-metadata?key=${script.key}`);
      if (!metadataResponse.ok) {
        throw new Error(`Failed to fetch script metadata for ${script.key}`);
      }
      const metadata = await metadataResponse.json();

      if (priority === 'high') {
        return client.get(metadata.highPriorityFallback);
      } else {
        return client.get(script.src || metadata.fallback);
      }
    }

    async function checkScriptIntegrity(script, cached) {
      const client = new HTTPClient();
      const response = await client.get(`https://integrity-service.com/script-integrity?key=${script.key}`);
      if (!response.ok) {
        throw new Error(`Failed to fetch script integrity for ${script.key}`);
      }
      const metadata = await response.json();

      if (metadata.valid) {
        return cached;
      } else {
        return [];
      }
    }

    async function renderScripts(scripts, priority, cached) {
      let scriptsHTML = '';
      for (const script of scripts) {
        try {
          const metadataResponse = await fetchScriptMetadata(script);
          if (!metadataResponse.ok) {
            throw new Error(`Failed to fetch metadata for ${script.key}`);
          }
          const metadata = await metadataResponse.json();
          if (priority === 'high' && !metadata.valid) {
            continue;
          }

          if (script.inline) {
            scriptsHTML += `<script>${script.content}</script>`;
          } else {
            scriptsHTML += `<script src="${script.src}" type="${script.type}" key="${script.key}"></script>`;
          }
        } catch (error) {
          console.error('Error fetching script metadata:', error);
        }
      }

      return scriptsHTML;
    }

    function fetchScriptMetadata(script) {
      const client = new HTTPClient();
      if (!script.priority || !script.inline) {
        return client.get(`https://metadata-service.com/script-metadata?key=${script.key}`);
      } else {
        return client.get(`https://metadata-service.com/script-metadata?inline=true&key=${script.key}`);
      }
    }
  }
}
