#include <semaphore.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>

// Define the structure to represent a semaphore
typedef struct {
    sem_t sem;
    int value;
    int priority;
} Semaphore;

// Define the structure to represent a named semaphore
typedef struct {
    char name[20];
    Semaphore* semaphores[100];
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} NamedSemaphore;

// Function to create a new named semaphore with an initial value and priority
void create_named_semaphore(char* name, int value, int priority) {
    // Create the named semaphore structure
    NamedSemaphore* semaphore = (NamedSemaphore*)malloc(sizeof(NamedSemaphore));
    strcpy(semaphore->name, name);

    // Initialize the semaphores array
    for(int i=0; i<100; i++) {
        semaphore->semaphores[i] = NULL;
    }

    // Create the mutex and condition variable
    pthread_mutex_init(&semaphore->mutex, NULL);
    pthread_cond_init(&semaphore->cond, NULL);

    // Initialize the first semaphore with the given value and priority
    Semaphore* sem = (Semaphore*)malloc(sizeof(Semaphore));
    sem->value = value;
    sem->priority = priority;
    sem->sem = sem_open(name, O_CREAT | O_EXCL | O_RDWR, S_IRUSR | S_IWUSR);
    if (sem->sem == SEM_FAILED) {
        perror("sem_open");
        exit(EXIT_FAILURE);
    }

    // Add the semaphore to the named semaphore structure
    semaphore->semaphores[0] = sem;
}

// Function to delete a named semaphore
void delete_named_semaphore(char* name) {
    // Find the named semaphore structure
    NamedSemaphore* semaphore = NULL;
    for(int i=0; i<100; i++) {
        if (strcmp(semaphore->name, name) == 0) {
            semaphore = &semaphore[i];
            break;
        }
    }

    // Check if the named semaphore exists
    if (semaphore == NULL) {
        printf("Named semaphore %s does not exist.\n", name);
        return;
    }

    // Delete all semaphores in the named semaphore structure
    for(int i=0; i<100; i++) {
        Semaphore* sem = semaphore->semaphores[i];
        if (sem != NULL) {
            sem_close(sem->sem);
            free(sem);
            semaphore->semaphores[i] = NULL;
        }
    }

    // Free the named semaphore structure
    pthread_mutex_destroy(&semaphore->mutex);
    pthread_cond_destroy(&semaphore->cond);
    free(semaphore);
}

// Function to increment a semaphore
void sem_post(Semaphore* sem) {
    if (sem->value > 0) {
        sem_post(sem->sem);
        sem->value--;
    }
}

// Function to decrement a semaphore
void sem_wait(Semaphore* sem, int timeout) {
    if (sem->value <= 0) {
        // Wait for the semaphore or timeout
        struct timespec timeout_spec;
        timeout_spec.tv_sec = timeout / 1000;
        timeout_spec.tv_nsec = (timeout % 1000) * 1000000;

        sem_wait(sem->sem, &timeout_spec);
    } else {
        sem->value--;
    }
}

// Function to get the value of a semaphore
int sem_get_value(Semaphore* sem) {
    return sem->value;
}
