```csharp
using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using RabbitMQ.Client;

public class EncryptedMessageProcessor
{
    private readonly string _desKey;
    private readonly byte[] _desIv;
    private readonly string _hmacKey;

    public EncryptedMessageProcessor(string desKey, byte[] desIv, string hmacKey)
    {
        _desKey = desKey;
        _desIv = desIv;
        _hmacKey = hmacKey;
    }

    public void ProcessEncryptedMessages(ConcurrentQueue<string> messages, RabbitMQ.IConnection rabbitMqConnection)
    {
        var decryptedMessages = new ConcurrentBag<string>();

        Parallel.ForEach(messages, message =>
        {
            try
            {
                string decryptedMessage = Decrypt(message);
                if (IsValid(decryptedMessage))
                {
                    decryptedMessages.Add(decryptedMessage);
                    PublishToRabbitMQ(rabbitMqConnection, decryptedMessage);
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error processing message: " + ex.Message);
            }
        });

        foreach (var message in decryptedMessages)
        {
            Console.WriteLine(message);
        }
    }

    private string Decrypt(string encryptedMessage)
    {
        try
        {
            using var des = TripleDESCryptoServiceProvider.Create();
            des.Key = Convert.FromBase64String(_desKey);
            des.IV = _desIv;

            using var memoryStream = new MemoryStream(Convert.FromBase64String(encryptedMessage));
            using var cryptStream = new CryptoStream(memoryStream, des.CreateDecryptor(), CryptoStreamMode.Read);

            byte[] decryptedBytes = new byte[memoryStream.Length];
            cryptStream.Read(decryptedBytes, 0, decryptedBytes.Length);
            return Encoding.UTF8.GetString(decryptedBytes);
        }
        catch (Exception ex)
        {
            throw new Exception("Decryption failed: " + ex.Message);
        }
    }

    private bool IsValid(string message)
    {
        try
        {
            using var hmac = HMACSHA256.Create();
            hmac.Key = Convert.FromBase64String(_hmacKey);

            byte[] messageBytes = Encoding.UTF8.GetBytes(message);
            byte[] hash = hmac.ComputeHash(messageBytes);

            string expectedHmac = Convert.ToBase64String(hash);
            return expectedHmac == message.Substring(message.Length - 32, 32);
        }
        catch (Exception ex)
        {
            throw new Exception("Validation failed: " + ex.Message);
        }
    }

    private void PublishToRabbitMQ(IConnection rabbitMqConnection, string message)
    {
        using var channel = rabbitMqConnection.CreateChannel();
        channel.BasicPublish(exchange: "", routingKey: "decrypted_messages", body: Encoding.UTF8.GetBytes(message));
    }

    public void InsertIntoQueue(ConcurrentQueue<string> queue, string value1, string value2)
    {
        try
        {
            int index = 0;
            foreach (var item in queue)
            {
                if (item == value1)
                {
                    queue.Enqueue(value2);
                    return;
                }
                index++;
            }

            queue.Enqueue(value2);
        }
        catch (Exception ex)
        {
            throw new Exception("Error inserting into the queue: " + ex.Message);
        }
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        using var connection = RabbitMQ.Connection.Create("amqp://guest:guest@localhost");
        EncryptedMessageProcessor processor = new EncryptedMessageProcessor("your_des_key", Convert.FromBase64String("your_des_iv"), "your_hmac_key");

        ConcurrentQueue<string> messages = new ConcurrentQueue<string>();
        // Add your messages here

        processor.ProcessEncryptedMessages(messages, connection);

        // Use the InsertIntoQueue method
        processor.InsertIntoQueue(messages, "value1", "value2");
    }
}
