const cache = new Map();

function queryElements(root, selector, filterOptions) {
  // Check if the result is already cached
  const cachedResult = cache.get(`${selector}${JSON.stringify(filterOptions)}`);
  if (cachedResult) return cachedResult;

  let results = [];

  function traverse(node) {
    // Match elements based on the given selector
    const matches = node.querySelectorAll(selector);

    for (const match of matches) {
      // Check filter options and recursively traverse child nodes
      if (filterOptions && !match.hasAttributes(filterOptions)) continue;
      results.push(match);
      traverse(match);
    }
  }

  traverse(root);

  function fetchAdditionalData(node) {
    return new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      xhr.open('GET', `https://api.example.com/${node.getAttribute('data-type')}`, true);
      xhr.onload = () => {
        if (xhr.status === 200) {
          node.setAttribute('aria-label', xhr.responseText);
          resolve();
        } else reject(new Error(`Failed to load data for ${node.nodeName}`));
      };
      xhr.onerror = () => reject(new Error('Network error'));
      xhr.send();
    });
  }

  // Fetch additional data for elements that require it
  Promise.all(results.map(fetchAdditionalData)).then(() => {
    cache.set(`${selector}${JSON.stringify(filterOptions)}`, results);
  });

  return results;
}

// Example usage:
const root = document.getElementById('root');
const result = queryElements(root, '.my-class', { 'data-type': 'example' });
console.log(result);

