using System;
using System.IO;
using System.Xml;
using Microsoft.Extensions.Configuration;

public class ConfigMerger
{
    public void MergeConfigs(string[] xmlFiles, string appSettingsJson)
    {
        var config = new ConfigurationBuilder()
            .AddInMemoryCollection()
            .AddXmlFiles(xmlFiles, reloadOnChange: true);

        // Prioritize newer files over older ones
        foreach (var file in xmlFiles)
        {
            if (!File.Exists(file))
                continue;
            try
            {
                config = config.AddXmlFile(file);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error parsing {file}: {ex.Message}");
            }
        }

        // Apply appsettings.json values last
        config.AddJsonFile(appSettingsJson);

        var mergedConfig = config.Build();

        // Update environment variables with the merged configuration
        foreach (var pair in mergedConfig.AsEnumerable())
        {
            Environment.SetEnvironmentVariable(pair.Key, pair.Value);
        }
    }
}
