use std::env;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use std::thread;
use chrono::prelude::*;

pub fn create_directory(name: &str) {
    let mut dir_path = get_dir_path();
    if is_dir_path_set(&dir_path) {
        dir_path = create_subdirectory(&dir_path);
    } else {
        set_dir_path(&name, &mut dir_path);
    }
    ensure_uniqueness(&mut dir_path);
    log_creation(&dir_path);
    delete_temp_subdirectory(&dir_path);
}

fn get_dir_path() -> String {
    env::var("DIR_PATH").unwrap_or_else(|_| "home".to_string())
}

fn is_dir_path_set(dir_path: &str) -> bool {
    Path::new(dir_path).exists()
}

fn set_dir_path(name: &str, dir_path: &mut String) {
    let timestamp = Utc::now().format("%Y%m%d_%H%M%S").to_string();
    *dir_path = format!("{}_{}/", name, timestamp);
    env::set_var("DIR_PATH", dir_path.as_str());
}

fn create_subdirectory(dir_path: &str) -> String {
    let mut path = PathBuf::from(dir_path);
    let subdirectory_name = "run_".to_string() + &Utc::now().format("%Y%m%d_%H%M%S").to_string();
    path.push(subdirectory_name.clone());
    if let Err(err) = fs::create_dir_all(&path) {
        eprintln!("Failed to create directory: {}", err);
    }
    format!("{}", path.display())
}

fn ensure_uniqueness(dir_path: &mut String) {
    let mut i = 0;
    loop {
        match fs::create_dir_all(dir_path.as_str()) {
            Ok(_) => return,
            Err(err) if err.kind() == io::ErrorKind::AlreadyExists => {
                *dir_path += &format!("_{}", i);
                i += 1;
            }
            Err(err) => eprintln!("Failed to create directory: {}", err),
        }
    }
}

fn log_creation(dir_path: &str) {
    let now = Utc::now();
    println!("Directory created at {}: {}", now, dir_path);
    // Add logging functionality
}

fn delete_temp_subdirectory(dir_path: &str) {
    if is_dir_path_set(dir_path) {
        match fs::remove_dir_all(Path::new(dir_path)) {
            Ok(_) => println!("Temporary directory deleted"),
            Err(err) => eprintln!("Failed to delete temporary directory: {}", err),
        }
    }
}

fn main() {
    // Add command-line options
}
