import json
import re
from collections import OrderedDict

class CryptographicModule:
    def __init__(self):
        self.cache = {}

    def load_module(self, name):
        if name in self.cache:
            return self.cache[name]
        try:
            module = __import__(name)
            self.cache[name] = module
            return module
        except ImportError as e:
            logging.error(f"Error loading module {name}: {e}")
            raise

    def read_config(self, config_file):
        with open(config_file, 'r') as f:
            data = json.load(f)
            functions = OrderedDict()
            for entry in data:
                name = entry['name']
                sequence_number = int(re.match(r'(\d+)$', entry['sequence_number']).group(1))
                functions[name] = {'reference': self.load_module(name),
                                   'parameters': entry.get('parameters', {}),
                                   'sequence_number': sequence_number}
            return list(functions.keys())

if __name__ == '__main__':
    cm = CryptographicModule()
    config_file = 'config.json'
    print(cm.read_config(config_file))
