use std::process::{Command, exit};
use std::time::{Instant, Duration};
use rustc_driver::catch_with_exit_code;
use log::{info, warn, error};

lazy_static! {
    static ref LOGGER: slog::Logger = slog:: Logger::root(slog::DefaultFormat.of_logger_name(), slog::LevelFilter::Info);
}

fn measure_compilation() -> i32 {
    let start_time = Instant::now();
    let mut rustc = Command::new("rustc");
    let peak_rss = std::mem::MaybeUninit::uninitialized();

    match catch_with_exit_code(move |log, err| {
        let log_duration = Duration::from_secs_f64(start_time.elapsed().as_seconds() as f64);
        let log_peak_rss = peak_rss.as_inner().unwrap_or(0);

        info!(LOGGER, "Compilation started at {} with RSS: {}", start_time, log_peak_rss);
        err.map(|e| {
            error!(LOGGER, "Compilation failed: {}", e);
            warn!(LOGGER, "Peak RSS reached during compilation: {}", log_peak_rss);
        });
        info!(LOGGER, "Compilation completed in {} with RSS: {}", log_duration, log_peak_rss);

        exit(e.unwrap_or(0));
    }, rustc, |log| {
        let start = Instant::now();
        peak_rss.set(log.rss());
        rustc.arg("--crate-if-macros").arg("main.rs");
        if let Err(e) = rustc.output() {
            early_error(&mut log, &e);
        }
    });

    0
}

fn main() {
    measure_compilation();
}
