        _csp = new CryptoServiceProvider();
        _rsaKeys = new Dictionary<string, RSAParameters>();
        _tripleDesKeys = new Dictionary<string, TripleDESAlgorithmKey[]>();
    }

    public async Task<string> DecryptAsync(string base64Message, string clearanceLevel)
    {
        if (string.IsNullOrEmpty(base64Message))
            throw new ArgumentException("Base64 message cannot be null or empty.");

        try
        {
            // Validate the message structure
            var messageBytes = Convert.FromBase64String(base64Message);
            var timestampIndicator = BitConverter.ToInt32(messageBytes, 0);
            var checksum = BitConverter.ToInt32(messageBytes, 4);

            if (timestampIndicator != 1 || checksum != 0)
                throw new Exception("Invalid message format");

            // Retrieve the decryption key and IV
            var key = GetDecryptionKey(clearanceLevel);
            var iv = GetInitializationVector();

            // Decrypt the message
            using var ms = new MemoryStream();
            using var cryptoStream = new CryptoStream(ms, _csp.CreateDecryptor(key, iv));
            await cryptoStream.WriteAsync(messageBytes);
            await cryptoStream.FlushFinalBlockAsync();
            var decryptedMessageBytes = ms.ToArray();

            return Convert.ToBase64String(decryptedMessageBytes);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error decrypting message");
            throw;
        }
    }

    private RSAParameters GetDecryptionKey(string clearanceLevel)
    {
        // Implement key retrieval logic based on security clearance level
