using System;
using System.Xml.XInclude;
using System.Xml.XPath;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Caching.Memory;

public class XmlParser
{
    private readonly IConfiguration _config;
    private readonly IMemoryCache _cache;

    public XmlParser(IConfiguration config, IMemoryCache cache)
    {
        _config = config;
        _cache = cache;
    }

    public IEnumerable<XElement> ParseXml(string xpathQuery, int limit = 1000)
    {
        string xmlFilePath = _config["XmlFilepath"];

        if (string.IsNullOrEmpty(xmlFilePath))
            throw new ArgumentException("XML file path is not specified");

        string cachedKey = $"cached-xml-{xpathQuery}-{limit}";
        CachedXmlDocument document;

        try
        {
            document = _cache.GetOrCreate(cachedKey, 
                entry =>
                {
                    XmlDocument xmlDocument = new XmlDocument();
                    xmlDocument.Load(xmlFilePath);

                    XPathNavigator navigator = xmlDocument.CreateNavigator();

                    string namespaceManager = _config["Namespace"];

                    XmlNamespaceManager manager = new XmlNamespaceManager(navigator);
                    manager.AddNamespace("namespace", namespaceManager);

                    XPathExpression expression = navigator.Compile(xpathQuery);
                    expression.NamespaceManager = manager;

                    var result = navigator.Select(expression);

                    if (!result.MoveNext())
                        throw new InvalidOperationException($"No elements found for XPath query: {xpathQuery}");

                    int count = 0;
                    List<XElement> elements = new List<XElement>();

                    while (result.MoveNext() && count < limit)
                    {
                        XElement element = (XElement)xmlDocument.CreateNavigator().SelectSingleNode(result.Current);
                        elements.Add(element);
                        count++;
                    }

                    return document;
                });
        }
        catch (Exception ex)
        {
            throw new Exception("Error parsing XML", ex);
        }

        return document.SelectNodes(xpathQuery).Cast<XElement>();
    }
}
