Here's an example code in C that manages a named semaphore with the given requirements:

```c
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>

#define SEMAPHORE_NAME_MAX_LENGTH 100

typedef struct {
    sem_t *sem;
    int initial_value;
} semaphore_t;

semaphore_t* create_semaphore(const char* name, int initial_value) {
    semaphore_t* sem = (semaphore_t*)malloc(sizeof(semaphore_t));
    if (!sem) {
        return NULL;
    }

    sem->initial_value = initial_value;

    const int len = strlen(name);
    char* path = malloc(len + 1);
    strcpy(path, "/semaphores/");
    strcat(path, name);
    free((void*)name);

    sem->sem = sem_open(path, O_CREAT | O_EXCL, S_IRUSR | S_IWUSR, initial_value);
    if (sem == SEM_FAILED) {
        free(sem);
        return NULL;
    }

    sem_close(sem->sem);
    free(path);
    return sem;
}

void delete_semaphore(semaphore_t* sem) {
    if (!sem) {
        return;
    }
    sem_close(sem->sem);
    sem_unlink("/semaphores/" + strlen(sem->initial_value));
    free(sem);
}

int acquire_semaphore(semaphore_t* sem, int timeout) {
    if (!sem) {
        return -1; // invalid semaphore
    }

    if (timeout == 0) {
        if (sem_wait(sem->sem)) {
            return -2; // failed to acquire semaphore
        }
    } else {
        if (sem_timedwait(sem->sem, timeout * 1000) == -1) {
            return -3; // timed out acquiring semaphore
        }
    }

    int current_value = sem_getvalue(sem->sem);
    printf("Acquired semaphore with value %d at time %ld\n", current_value, time(NULL));
    return 0;
}

int release_semaphore(semaphore_t* sem) {
    if (!sem) {
        return -1; // invalid semaphore
    }

    if (sem_post(sem->sem)) {
        return -2; // failed to release semaphore
    }

    printf("Released semaphore at time %ld\n", time(NULL));
    return 0;
}

int main(int argc, char** argv) {
    int initial_value = 1;
    const char* name = "my_semaphore";
    int timeout = 10;

    if (argc > 1) {
        initial_value = atoi(argv[1]);
    }
    if (argc > 2) {
        name = argv[2];
    }
    if (argc > 3) {
        timeout = atoi(argv[3]);
    }

    semaphore_t* sem = create_semaphore(name, initial_value);
    if (!sem) {
        return -1; // failed to create semaphore
    }

    for (int i = 0; i < 5; i++) {
        int result = acquire_semaphore(sem, timeout);
        if (result != 0) {
            printf("Failed to acquire semaphore: %d\n", result);
            break;
        }
        sleep(1);
        release_semaphore(sem);
    }

    delete_semaphore(sem);

    return 0;
}
