import { loadModules, cacheModules, invalidateCache } from './utils';
import { getModuleByVersion, resolveDependencies } from './registry';

class ModuleLoader {
  constructor(config) {
    this.config = config;
    this.modules = {};
    this.cache = new Map();
  }

  async loadModules() {
    const modulesToLoad = this.config.modules;
    for (const moduleName of Object.keys(modulesToLoad)) {
      try {
        const module = await loadModules(moduleName, modulesToLoad[moduleName]);
        this.modules[moduleName] = module;
        cacheModules(this.modules);
      } catch (error) {
        console.error(`Error loading module ${moduleName}:`, error);
      }
    }
  }

  async executeModules() {
    for (const moduleName of Object.keys(this.modules)) {
      try {
        await this.modules[moduleName].execute();
      } catch (error) {
        console.error(`Error executing module ${moduleName}:`, error);
      }
    }
  }

  async start() {
    await this.loadModules();
    await this.executeModules();
  }
}

// registry.js
