    const response = await axios.get(`${this.baseUrl}/modules/${moduleName}/${version}`);
    return response.data;
  }

  async resolveDependencies(moduleName) {
    const response = await axios.get(`${this.baseUrl}/modules/${moduleName}/dependencies`);
    return response.data;
  }
}

