// Directory Management Function
function manageDirectories(fields) {
  const dirCache = {};

  function refreshDir(id, callback) {
    if (dirCache[id]) {
      // Return cached result
      return callback(null, dirCache[id]);
    }

    // Fetch directory data from API or DB
    api.getDirectory(id)
      .then(response => {
        dirCache[id] = response;
        callback(null, response);
      })
      .catch(error => {
        console.error(`Error refreshing directory ${id}: ${error}`);
        callback(error);
      });
  }

  function cleanupDirs(fields) {
    fields.forEach(field => {
      const id = field.value.id;

      // Check if directory exists
      if (!dirCache[id]) return;

      // Send refresh request
      refreshDir(id, (err, data) => {
        if (err) {
          console.error(`Error refreshing directory ${id}: ${err}`);
        } else {
          // Update dialog field with refreshed data
          const pagination = data.pagination;
          if (!pagination) return;

          // Implement pagination and caching for large datasets
          const cachedData = dirCache[id].slice(0, 10);
          field.value.data = cachedData;
        }
      });
    });
  }

  function createDirs(fields) {
    fields.forEach(field => {
      const id = field.value.id;

      // Check if directory exists
      if (dirCache[id]) return;

      // Create new directory and cache result
      api.createDirectory(id)
        .then(response => {
          dirCache[id] = response;
          console.info(`Created directory ${id}`);
        })
        .catch(error => {
          console.error(`Error creating directory ${id}: ${error}`);
        });
    });
  }

  // Main function to manage directories
  return (fields) => {
    createDirs(fields);
    cleanupDirs(fields);
  };
}

