{
    public event EventHandler<DecryptionEvent> Decrypted;

    private readonly ICspProvider _cspProvider;
    private readonly object _lock = new();
    private readonly Queue<MessageContext> _messageQueue = new();

    public SecureMessageHandler(ICspProvider cspProvider)
    {
        _cspProvider = cspProvider;
    }

    public void ProcessMessage(string base64EncodedMessage)
    {
        var messageContext = GetMessageContext(base64EncodedMessage);
        _messageQueue.Enqueue(messageContext);

        if (_messageQueue.Count > 1)
            ThreadPool.QueueUserWorkItem(QueueWorker);
    }

    private MessageContext GetMessageContext(string base64EncodedMessage)
    {
        // Implement your logic to extract the context ID and other parameters from the message
        return new MessageContext();
    }

    private void QueueWorker(object state)
    {
        while (_messageQueue.Count > 0)
        {
            var messageContext = _messageQueue.Dequeue();

            if (messageContext == null)
                continue;

            TryDecryptMessage(messageContext);
        }
    }

    private void TryDecryptMessage(MessageContext messageContext)
    {
        try
        {
            using var csp = _cspProvider.GetCsp();
            using var decryptor = csp.CreateDecryptor();

            var decryptedBytes = decryptor.Decrypt(base64EncodedMessage);

            // Implement your logic to process the decrypted message

            Decrypted?.Invoke(this, new DecryptionEvent(decryptedBytes));
        }
        catch (Exception ex)
        {
            HandleDecryptionError(ex);
        }
    }

