public static void ConvertImagesToPdf(string directoryPath, string outputFileName, List<string> imageFilenames, string outputFileFormat = "PDF", bool embedMetadata = true)
{
    // Create a semaphore to manage concurrent processing
    using SemaphoreSlim semaphore = new(5, 5);

    // Check if the specified directory exists
    if (!Directory.Exists(directoryPath))
    {
        throw new FileNotFoundException($"The directory '{directoryPath}' does not exist.", "directory");
    }

    // Process and combine multiple image files into a single PDF report
    using (var pdfWriter = new PdfReportWriter())
    {
        foreach (string filename in imageFilenames)
        {
            try
            {
                semaphore.Wait();
                Task.Run(() =>
                {
                    // Process the image file
                    ImageFileProcessor processor = new(directoryPath, filename);
                    ImageMetadata metadata = processor.ProcessImage(embedMetadata);

                    // Embed thumbnail at specified intervals
                    if (outputFileFormat == "PDF")
                    {
                        pdfWriter.AddPage(processor.GetThumbnail(), metadata);
                    }
                    else if (outputFileFormat == "DOCX" || outputFileFormat == "JPEG")
                    {
                        // Handle other file formats as needed
                    }

                }).Wait();
            }
            catch (Exception ex)
            {
                // Log error with timestamp, error code, and specific error message
                Console.WriteLine($"Error processing image '{filename}': {ex.Message}");
            }
            finally
            {
                semaphore.Release();
            }
        }
    }

    // Generate the output file based on the specified format
    if (outputFileFormat == "PDF")
    {
        using (var pdfStream = new FileStream(outputFileName, FileMode.Create))
        {
            pdfWriter.Save(pdfStream);
        }
    }
    else if (outputFileFormat == "DOCX" || outputFileFormat == "JPEG")
    {
        // Handle other file formats as needed
    }

    // Monitor resource usage and ensure it remains within acceptable limits
    Console.WriteLine($"Resource usage: Memory {MemoryUsage}%, CPU {CpuUsage}%");
}

