{
    public void AddPage(Bitmap image, ImageMetadata metadata) => throw new NotImplementedException();

    public void Save(Stream stream) => throw new NotImplementedException();
}

public class ImageFileProcessor : IDisposable
{
    public ImageMetadata ProcessImage(bool embedMetadata) => throw new NotImplementedException();

    public Bitmap GetThumbnail() => throw new NotImplementedException();
}

