<?php

namespace DynamicImageCrawler;

use PDO;
use PDOException;
use Psr\Log\LoggerInterface;
use Symfony\Component\HttpFoundation\JsonResponse;
use Symfony\Component\HttpFoundation\Request;
use Symfony\Component\HttpFoundation\Response;
use Symfony\Component\Security\Core\Exception\InvalidCredentialsException;
use Symfony\Component\Security\Core\User\UserNotFoundException;

class UserController
{
    private $dbConfig;
    private $logger;
    private $sessionTokenManager;
    private $rateLimiter;

    public function __construct(array $dbConfig, LoggerInterface $logger, SessionTokenManager $sessionTokenManager, RateLimiter $rateLimiter)
    {
        $this->dbConfig = $dbConfig;
        $this->logger = $logger;
        $this->sessionTokenManager = $sessionTokenManager;
        $this->rateLimiter = $rateLimiter;
    }

    public function createUser(Request $request): JsonResponse
    {
        if (!$this->rateLimiter->isAllowed()) {
            return new JsonResponse(['status' => 'error', 'message' => 'Rate limit exceeded'], 429);
        }

        try {
            $user = new User();
            $user->setName($request->get('name'));
            $user->setEmail($request->get('email'));
            $user->setPassword($request->get('password'));

            // Validate email uniqueness
            if (!empty($this->dbConfig['unique_email'])) {
                $existingUser = $this->getUserByEmail($user->getEmail());
                if ($existingUser) {
                    return new JsonResponse(['status' => 'error', 'message' => 'Email already exists'], 400);
                }
            }

            // Validate password complexity
            if (!empty($this->dbConfig['password_complexity'])) {
                $passwordComplexity = $this->dbConfig['password_complexity'];
                if (!preg_match($passwordComplexity, $user->getPassword())) {
                    return new JsonResponse(['status' => 'error', 'message' => 'Invalid password'], 400);
                }
            }

            // Create user in database
            $this->saveUser($user);

            return new JsonResponse(['status' => 'success', 'message' => 'User created successfully'], 201);
        } catch (PDOException $e) {
            return new JsonResponse(['status' => 'error', 'message' => 'Database error: ' . $e->getMessage()], 500);
        }
    }

    public function updateUser(Request $request): JsonResponse
    {
        // Validate session token and rate limiting
        if (!$this->sessionTokenManager->isValid($request->get('token')) || !$this->rateLimiter->isAllowed()) {
            return new JsonResponse(['status' => 'error', 'message' => 'Invalid session token or rate limit exceeded'], 401);
        }

        try {
            $user = $this->getUserById((int) $request->get('id'));
            if (!$user) {
                return new JsonResponse(['status' => 'error', 'message' => 'User not found'], 404);
            }

            // Update user information
            $user->setName($request->get('name'));
            $user->setEmail($request->get('email'));

            // Validate email uniqueness (if configured)
            if (!empty($this->dbConfig['unique_email'])) {
                $existingUser = $this->getUserByEmail($user->getEmail());
                if ($existingUser && $existingUser->getId() !== $user->getId()) {
                    return new JsonResponse(['status' => 'error', 'message' => 'Email already exists'], 400);
                }
            }

            // Save updated user information
            $this->saveUser($user);

            return new JsonResponse(['status' => 'success', 'message' => 'User account updated successfully'], 200);
        } catch (PDOException $e) {
            return new JsonResponse(['status' => 'error', 'message' => 'Database error: ' . $e->getMessage()], 500);
        }
    }

    public function deleteUser(Request $request): JsonResponse
    {
        // Validate session token and rate limiting
        if (!$this->sessionTokenManager->isValid($request->get('token')) || !$this->rateLimiter->isAllowed()) {
            return new JsonResponse(['status' => 'error', 'message' => 'Invalid session token or rate limit exceeded'], 401);
        }

        try {
            $user = $this->getUserById((int) $request->get('id'));
            if (!$user) {
                return new JsonResponse(['status' => 'error', 'message' => 'User not found'], 404);
            }

            // Delete user account
            $this->deleteUser($user);

            return new JsonResponse(['status' => 'success', 'message' => 'User account deleted successfully'], 200);
        } catch (PDOException $e) {
            return new JsonResponse(['status' => 'error', 'message' => 'Database error: ' . $e->getMessage()], 500);
