function dynamicClinicScheduler($action, $clinicId, $data = array())
{
    // Rate limiting and IP blocking
    if (isset($_SERVER['HTTP_X_REAL_IP']) && is_array($blockedIps = ip_blocklist())) {
        foreach ($blockedIps as $ip) {
            if ($_SERVER['HTTP_X_REAL_IP'] === $ip) {
                http_response_code(429);
                echo 'Too many requests from this IP. Please try again later.';
                exit;
            }
        }
    }

    // Database connection
    $db = db_connect();

    // Clinic data caching
    $clinicDataCache = array();
    if (isset($data['clinicId'])) {
        $clinicDataCache[$data['clinicId']] = get_clinic_data($data['clinicId']);
    }

    switch ($action) {
        case 'create':
            // Create new clinic record with initial status, location, and capacity
            if (!empty($data['location']) && !empty($data['capacity'])) {
                $query = "INSERT INTO clinics (status, location, capacity) VALUES ('open', ?, ?)";
                $stmt = $db->prepare($query);
                $stmt->execute(array($data['location'], $data['capacity']));
            }
            break;
        case 'update':
            // Update clinic status and notify relevant systems
            if (!empty($data['status'])) {
                $query = "UPDATE clinics SET status = ? WHERE id = ?";
                $stmt = $db->prepare($query);
                $stmt->execute(array($data['status'], $clinicId));

                // Notify relevant systems based on clinic status and time
                notify_systems($data['status'], date('H:i:s'));

                // Update patient scheduling system
                update_patient_scheduling_system($data['status']);

                // Update third-party logistics service
                update_third_party_logistics_service($data['status']);
            }
            break;
        case 'delete':
            // Delete clinic record and transition associated data
            if (!empty($clinicId)) {
                $query = "DELETE FROM clinics WHERE id = ?";
                $stmt = $db->prepare($query);
                $stmt->execute(array($clinicId));

                // Trigger process to redistribute affected appointments
