// crypto_modular.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>
#include <openssl/ssl.h>

#define MODULE_AES "aes"
#define MODULE_CAMELLIA "camellia"
#define MODULE_MD5 "md5"
#define MODULE_SHA "sha"
#define MODULE_RSA "rsa"

typedef struct {
    void *handle;
    char *name;
} module_t;

void *load_module(const char *name) {
    void *handle = dlopen(name, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Error loading module %s: %s\n", name, dlerror());
        return NULL;
    }
    return handle;
}

int unload_module(void *handle) {
    int ret = dlclose(handle);
    if (ret != 0) {
        fprintf(stderr, "Error unloading module: %s\n", dlerror());
    }
    return ret;
}

void load_modules(const char **modules) {
    for (const char **module = modules; *module; module++) {
        void *handle = load_module(*module);
        if (!handle) break;
        // ...
    }
}

void unload_modules(void **handles, int count) {
    for (int i = 0; i < count; i++) {
        unload_module(handles[i]);
    }
}
