function runTests(moduleLabel, testSuites, config) {
  const concurrency = config.concurrent;
  const timeout = config.timeout;

  let suiteResults = {};
  let testCount = 0;

  async function runSuite(suite) {
    try {
      await test.run(suite, { concurrency, timeout });
      suiteResults[suite.name] = 'passed';
    } catch (error) {
      suiteResults[suite.name] = 'failed';
    }
    testCount++;
  }

  await Promise.all(testSuites.map(runSuite));

  console.log(`Test results: ${Object.values(suiteResults).join(', ')}`);
}

module.exports = runTests;
