#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

char* dynamicTrimAndCapitalize(char* input, int sizeLimit) {
    // Fetch word list from external data source
    char** words = fetchWordList();

    if (!words || !input) return NULL;

    int totalWords = countWords(words);
    int avgWordLength = calculateAvgWordLength(words, totalWords);
    int adjustedSizeLimit = sizeLimit - (totalWords * avgWordLength);

    // Trim input string based on word list
    char* trimmedInput = trimString(input, words);

    if (!trimmedInput || strlen(trimmedInput) > adjustedSizeLimit) return NULL;

    // Capitalize first letter of each word in the resulting string
    char* capitalizedInput = capitalizeString(trimmedInput);

    free(words);
    free(trimmedInput);

    return capitalizedInput;
}
