**JavaScript - asyncArrayReduce**
```javascript
const { promisify, throttle } = require('util');
const cache = require('memory-cache');

async function asyncArrayReduce(arr, initialValue, callback) {
  const semaphore = new Semaphore(4); // control concurrency level
  let accumulatedValue = initialValue;
  let completedOperations = 0;

  arr.forEach((num) => {
    semaphore.take(() => {
      try {
        accumulatedValue = callback(accumulatedValue, num);
      } catch (error) {
        console.error(`Error during reduction: ${error}`);
        return null;
      } finally {
        semaphore.release();
        completedOperations++;
        process.stdout.write(`Completed operations: ${completedOperations}\r`);
      }
    });
  });

  return accumulatedValue;
}

class Semaphore {
  constructor(concurrencyLevel) {
    this.semaphore = concurrencyLevel;
    this.queue = [];
  }

  take(callback) {
    if (this.semaphore <= 0) {
      // queue up pending operations
      this.queue.push(callback);
    } else {
      callback();
      this.semaphore--;
    }
  }

  release() {
    if (this.queue.length > 0) {
      const callback = this.queue.shift();
      callback();
      this.semaphore++;
    }
  }
}
