use std::time::{Instant, Duration};

fn compileDirectory(directory_path: &str) -> (f64, usize, u32) {
    let start = Instant::now();
    let mut total_compile_time = 0.0;
    let mut warnings = 0;

    for entry in fs::read_dir(directory_path).unwrap() {
        let path = entry.unwrap().path();
        if path.is_file() && path.extension() == Some("rs") {
            let start = Instant::now();
            let output = cargo_build(&path.to_string_lossy());
            let duration = start.elapsed().as_secs_f64();

            total_compile_time += duration;
            warnings += count_warnings(&output);

            println!("File: {}, Compile Time: {:.2f} seconds, Warnings: {}", path.file_name().unwrap(), duration, warnings);
        }
    }

    (total_compile_time, warnings, fs::get_resident_set_size().unwrap())
}
