        self.log_file_path = log_file_path
        self.thread_pool_executor = ThreadPoolExecutor()

    def parse_log(self):
        with open(self.log_file_path, 'r') as f:
            lines = f.readlines()

        unique_ips = set()
        response_times = {}

        for chunk in iter(lambda: lines[:1000], []):  # Process in parallel chunks
            with self.thread_pool_executor as executor:
                futures = []
                for line in chunk:
                    ip, response_time = parse_line(line)
                    if ip not in unique_ips:
                        unique_ips.add(ip)
                    if ip not in response_times:
                        response_times[ip] = []
                    response_times[ip].append(float(response_time))

        # Calculate average response time for each IP
        for ip, times in response_times.items():
            avg_response_time = sum(times) / len(times)

            # Aggregate data safely to avoid race conditions and ensure data integrity
            with lock:
                response_times[ip] = avg_response_time

