const bookReferences = require('./book-references');
const apiClient = require('./api-client');

class TextAnalysisModule {
  constructor(options) {
    this.options = options;
    this.bookDatabase = new Map();
  }

  async analyzeText(text) {
    const references = [];
    const textSegments = this.splitTextIntoSegments(text);

    for (const segment of textSegments) {
      try {
        const matchedReferences = await this.extractBookReferences(segment);
        if (matchedReferences.length > 0) {
          references.push(...matchedReferences);
        }
      } catch (error) {
        // handle invalid input or error
      }
    }

    return references;
  }

  splitTextIntoSegments(text) {
    const segments = [];
    let currentSegment = '';

    for (const char of text) {
      if (char === ' ') {
        segments.push(currentSegment);
        currentSegment = '';
      } else {
        currentSegment += char;
      }
    }

    segments.push(currentSegment);

    return segments;
  }

  async extractBookReferences(textSegment) {
    const references = [];
    const matchedReferences = bookReferences.matchReferences(textSegment, this.options.bookDatabase);

    for (const reference of matchedReferences) {
      try {
        const verifiedReference = await apiClient.verifyReference(reference);
        if (verifiedReference) {
          references.push(verifiedReference);
        }
      } catch (error) {
        // handle error
      }
    }

    return references;
  }
}

module.exports = TextAnalysisModule;
