```
import os
import io
from OpenSSL import crypto
from cryptography.hazmat.primitives.serialization import load_pem_private_key
from urllib.parse import urlparse
import logging
import requests
import functools
import threading
from typing import Dict, Any

LOG = logging.getLogger(__name__)

class CertificateCache:
    _cache: Dict[str, bytes] = {}
    _lock = threading.RLock()

    def get(self, key: str) -> bytes:
        with self._lock:
            return self._cache.get(key)

    def set(self, key: str, value: bytes):
        with self._lock:
            self._cache[key] = value

class CertificateFetcher:
    _config: Dict[str, Any]
    _cache: CertificateCache

    def __init__(self, config: Dict[str, Any]):
        self._config = config
        self._cache = CertificateCache()

    @functools.lru_cache(maxsize=None)
    def fetch(self, request: str) -> bytes:
        try:
            url = urlparse(request).path
            key = os.path.basename(url)

            if cache := self._cache.get(key):
                return cache

            for source in self._config['sources']:
                if not source['enabled']:
                    continue

                try:
                    response = requests.get(source['url'], stream=True)
                    response.raise_for_status()
                    with io.BytesIO() as pem_file:
                        for chunk in response.iter_content(1024):
                            pem_file.write(chunk)
                        pem_file.seek(0)

                        key_file, cert_file = self._extract_key_cert(pem_file.read())

                        if os.path.exists(key_file) and os.path.exists(cert_file):
                            with open(key_file, 'rb') as f:
                                private_key = load_pem_private_key(f.read(), password=None)

                            with open(cert_file, 'rb') as f:
                                certificate = crypto.load_certificate(crypto.FILETYPE_PEM, f.read())

                            pem_file.seek(0)
                            pem_file.write(crypto.dump_certificate(crypto.FILETYPE_PEM, certificate) + b'-----BEGIN PRIVATE KEY-----\n' + private_key.decode() + b'\n-----END PRIVATE KEY-----')
                            pem_file.seek(0)

                            self._cache.set(key, pem_file.read())
                            return pem_file.getvalue()
                except requests.exceptions.RequestException as e:
                    LOG.error(f"Failed to fetch certificate from {source['url']}: {e}")
            else:
                LOG.warning("All sources failed. Using fallback mechanism.")
                for fallback in self._config.get('fallbacks', []):
                    try:
                        response = requests.get(fallback, stream=True)
                        response.raise_for_status()
                        with io.BytesIO() as pem_file:
                            for chunk in response.iter_content(1024):
                                pem_file.write(chunk)
                            pem_file.seek(0)

                            return pem_file.getvalue()
                    except requests.exceptions.RequestException as e:
                        LOG.error(f"Failed to fetch fallback certificate: {e}")
                raise Exception("All sources and fallbacks failed")

    def _extract_key_cert(self, pem_data: bytes) -> (str, str):
        lines = pem_data.decode().split('\n')
        for i, line in enumerate(lines):
            if line.startswith('-----BEGIN CERTIFICATE-----'):
                cert_start = i
                break

        cert_lines = lines[cert_start:]
        key_start = None
        for i, line in enumerate(reversed(lines)):
            if line.startswith('-----END PRIVATE KEY-----'):
                key_end = len(lines) - i - 1
                key_start = key_end
                break

        return lines[key_start+1:key_end].join('\n'), '\n'.join(cert_lines)

if __name__ == '__main__':
    config = {
        'sources': [
            {'url': 'https://example.com/cert1.pem', 'enabled': True},
            {'url': 'https://example.com/cert2.pem', 'enabled': False}
        ],
        'fallbacks': ['https://fallback.example.com']
    }

    fetcher = CertificateFetcher(config)
    certificate = fetcher.fetch('https://example.com/cert.pem')
