#include <json/json.h>
#include <unordered_map>
#include <mutex>
#include <memory>

class DeviceSettings {
public:
    static std::shared_ptr<DeviceSettings> load(const std::vector<std::string>& files) {
        auto settings = std::make_shared<DeviceSettings>();
        for (const auto& file : files) {
            try {
                settings->loadFile(file);
            } catch (const std::runtime_error& e) {
                std::cerr << "Error loading device settings from " << file << ": " << e.what() << std::endl;
            }
        }
        return settings;
    }

    void save(const std::string& filename) const {
        try {
            std::ofstream file(filename);
            file << to_json();
        } catch (const std::runtime_error& e) {
            std::cerr << "Error saving device settings to " << filename << ": " << e.what() << std::endl;
        }
    }

    template<typename K, typename V>
    std::optional<V> get(const K& key) const {
        auto it = settings.find(key);
        if (it == settings.end()) return std::nullopt;

        validateSetting(it->second);

        return it->second;
    }

private:
    struct SettingsObserver {
        virtual void onSettingsChanged() = 0;
        virtual ~SettingsObserver() {}
    };

    class SettingsManager {
    public:
        SettingsManager(const DeviceSettings& settings) : settings_(settings) {}

        template<typename K, typename V>
        void addObserver(SettingsObserver* observer) const {
            observers_.insert(observer);
        }

        void notifyObservers() const {
            for (auto observer : observers_) {
                observer->onSettingsChanged();
            }
        }

    private:
        const DeviceSettings& settings_;
        std::unordered_set<SettingsObserver*> observers_;
    };

    DeviceSettings() = default;

    void loadFile(const std::string& filename) {
        std::ifstream file(filename);
        if (!file.is_open()) throw std::runtime_error("Failed to open file");

        try {
            auto json = Json::load(file);
            for (auto& device : json["devices"]) {
                for (auto& setting : device["settings"]) {
                    settings[setting["key"]] = setting["value"];
                }
            }
        } catch (const std::runtime_error& e) {
            throw std::runtime_error("Error parsing JSON file: " + filename);
        }

        notifyObservers();
    }

    void to_json(Json::Value& json) const {
        Json::Value devices;
        for (auto& setting : settings) {
            auto device = devices.append(Json::Value());
            device["settings"].append(Json::Value(setting.first, setting.second));
        }
        json["devices"] = devices;
    }

    void validateSetting(const std::any& value) const {
        // Add validation logic here
    }

    mutable SettingsManager settings_manager_;
    std::unordered_map<std::string, std::any> settings_;
};
