import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class CommandExecutor {
    private static final int DEFAULT_MAX_RETRIES = 3;
    private static final long DEFAULT_RETRY_DELAY_MILLIS = 1000L;

    private ExecutorService executor;
    private DatabaseManager databaseManager;
    private RestApi restApi;

    public CommandExecutor() {
        this.executor = Executors.newFixedThreadPool(5);
        this.databaseManager = new DatabaseManager();
        this.restApi = new RestApi();
    }

    public void executeCommands(String[] commands) throws IOException, SQLException {
        // Delete the file if it exists
        deleteFile("example.txt");

        for (String command : commands) {
            CommandRunnable commandRunnable = new CommandRunnable(command);
            Future<String> future = executor.submit(commandRunnable);

            try {
                String output = future.get();
                processOutput(output);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException(e);
            } catch (ExecutionException e) {
                handleExecutionException(e);
            }
        }

        // Close the executor and database connection
        executor.shutdown();
        databaseManager.close();
    }

    private void deleteFile(String filename) {
        Runtime.getRuntime().exec("rm " + filename);
    }

    private class CommandRunnable implements Runnable {
        private String command;

        public CommandRunnable(String command) {
            this.command = command;
        }

        @Override
        public void run() {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(Runtime.getRuntime().exec(command).getInputStream()))) {
                StringBuilder outputBuilder = new StringBuilder();
                String line;
                while ((line = reader.readLine()) != null) {
                    outputBuilder.append(line);
                    outputBuilder.append("\n");
                }
                System.out.println(outputBuilder.toString());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }

    private void processOutput(String output) {
