<?php

class ConfigManager {
    private $primaryCms;
    private $secondaryCms = [];
    private $fallbackConfig;

    public function __construct($primaryCms, array $secondaryCms, $fallbackConfig) {
        $this->primaryCms = $primaryCms;
        $this->secondaryCms = $secondaryCms;
        $this->fallbackConfig = $fallbackConfig;
    }

    public function loadConfig() {
        // Load config from primary CMS
        $config = json_decode($this->loadFromCms($this->primaryCms), true);

        // Check if secondary CMS instances are available and their responses are faster than the primary CMS
        foreach ($this->secondaryCms as $cms) {
            $responseTime = $this->getResponseTime($cms);
            if ($responseTime < $this->getPrimaryResponseTime()) {
                // Update config with data from faster secondary CMS instance
                $config = json_decode($this->loadFromCms($cms), true);
            }
        }

        // Fallback to local configuration if all CMS instances are unavailable
        if (empty($config)) {
            $config = $this->fallbackConfig;
        }

        return $config;
    }

    private function loadFromCms($cms) {
        // Load config from the given CMS instance
        // This method should implement the logic to connect to the CMS and retrieve the configuration data
    }

    private function getPrimaryResponseTime() {
        // Get response time of primary CMS
        // This method should implement the logic to measure the response time of the primary CMS
    }
}

