let fileList = [];
let cachedFiles = {};

async function loadAndExecuteFiles(files) {
  fileList = files;
  await Promise.all(fileList.map(async (file) => {
    if (!cachedFiles[file]) {
      try {
        const fileContent = await fetch(`script/${file}.js`).then((res) => res.text());
        eval(fileContent);
        cachedFiles[file] = fileContent;
      } catch (error) {
        console.error(`Error loading and executing ${file}:`, error);
      }
    }
  }));
}

async function updateFileList() {
