Here is the PHP code block for the `updateUserPassword` function:
```
function updateUserPassword($username, $oldPassword, $newPassword) {
    require_once 'DAO.php';
    $dao = new DAO();

    if (!$dao->verifyUsernameAndPassword($username, $oldPassword)) {
        return false; // invalid username or password
    }

    if (!validateNewPassword($newPassword)) {
        return false; // new password does not meet requirements
    }

    $hashedOldPassword = $dao->getHashedPassword($username);
    if ($hashedOldPassword !== hash('sha256', $oldPassword, true)) {
        return false; // invalid old password
    }

    $dao->updateUserPassword($username, hash('sha256', $newPassword, true));
    return true;
}

function validateNewPassword($password) {
    if (strlen($password) < 8) {
        return false; // minimum length not met
    }
    if (!preg_match('/[A-Z]/', $password)) {
        return false; // no uppercase letter
    }
    if (!preg_match('/[a-z]/', $password)) {
        return false; // no lowercase letter
    }
    if (!preg_match('/\d/', $password)) {
        return false; // no digit
    }
    if (!preg_match('/[^A-Za-z0-9]/', $password)) {
        return false; // no special character
    }
    if (strpos($password, $username) !== false || strpos($password, substr($username, 1)) !== false) {
        return false; // username or part of it found in password
    }
    return true;
}
