#include <iostream>
#include <vector>
#include <string>
#include <fstream>
#include <thread>
#include <mutex>

class OctreeNode {
public:
    int id;
    std::vector<OctreeNode*> children;
    bool isLeaf;
};

class Octree {
public:
    OctreeNode* root;
    int maxDepth;
    int dataSize;

    void buildAndManageOctree(int featureSize, int numInitialLeafNodes, int maxDataCapacity) {
        // Initialize octree parameters
        this->maxDepth = 0;
        this->dataSize = 0;

        // Start building the octree from scratch
        root = new OctreeNode();
        root->id = 1;
        root->isLeaf = false;
        root->children.resize(8);

        // Initialize the first level of leaf nodes
        for (int i = 0; i < 8; i++) {
            root->children[i] = new OctreeNode();
            root->children[i]->id = i + 2;
            root->children[i]->isLeaf = true;

            // Set the initial capacity for each leaf node
            root->children[i]->dataSize = numInitialLeafNodes;
        }

        // Start managing and building the octree
        buildOctree(root, featureSize);

        // Print the constructed octree summary
        std::cout << "Octree built successfully with a depth of: " << maxDepth << " and a total data size of: " << dataSize << std::endl;
    }

private:
    void buildOctree(OctreeNode* node, int featureSize) {
        // Check if the current node is a leaf node
        if (node->isLeaf) {
            // If it's a leaf node, calculate its depth and data size
            int depth = 1;
            int dataSize = 0;

            // Iterate through the children of this leaf node
            for (int i = 0; i < 8; i++) {
                if (node->children[i] != nullptr) {
                    depth++;
                    dataSize += node->children[i]->dataSize;
                }
            }

            // Set the depth and data size of this leaf node
            node->depth = depth;
            node->dataSize = dataSize;

            return;
        }

        // If it's not a leaf node, iterate through its children
        for (int i = 0; i < 8; i++) {
            if (node->children[i] != nullptr) {
                buildOctree(node->children[i], featureSize);
            }
        }

        // Calculate the depth and data size of this non-leaf node
        int depth = 1;
        int dataSize = 0;

        // Iterate through its children again to calculate their depths and data sizes
        for (int i = 0; i < 8; i++) {
            if (node->children[i] != nullptr) {
                depth++;
                dataSize += node->children[i]->depth * node->children[i]->dataSize;
            }
        }

        // Set the depth and data size of this non-leaf node
        node->depth = depth;
        node->dataSize = dataSize;
    }
};

int main() {
    Octree octree;

    int featureSize = 10; // Input your desired feature size here
    int numInitialLeafNodes = 1000; // Input your desired initial leaf nodes count here
    int maxDataCapacity = 500000; // Input your desired maximum data capacity here

    octree.buildAndManageOctree(featureSize, numInitialLeafNodes, maxDataCapacity);

    return 0;
}

