use std::fs;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};
use tokio::fs::{create_dir_all, read_dir, read_to_end};
use tokio::process::Command;
use serde_json;

async fn create_config_dir(dir_name: &str) -> Result<PathBuf, String> {
    let dir_path = Path::new("config");
    let remote_repo = Arc::new(serde_json::from_str(include_str!("remote_repo.json")).unwrap());

    if fs::read_link(&dir_path).is_ok() {
        return Ok(dir_path.to_path_buf());
    }

    let local_dir_path = create_dir_all(dir_path).await?;
    let repo_url = &remote_repo["url"];
    let repo_username = &remote_repo["username"];
    let repo_password = &remote_repo["password"];

    if !fs::metadata(&local_dir_path).unwrap().is_dir() {
        return Err("Failed to create local directory".to_string());
    }

    match Command::new("git")
        .arg("init")
        .arg("-quiet")
        .current_dir(local_dir_path.clone())
        .output()
    {
        Ok(output) => {
            if !output.status().unwrap().is_success() {
                return Err("Failed to initialize local Git repository".to_string());
            }
        }
        Err(err) => {
            println!("Error initializing Git repository: {}", err);
        }
    };

    match Command::new("git")
        .arg("remote")
        .arg("add")
        .arg("-f")
        .arg(repo_url)
        .arg("--username")
        .arg(repo_username)
        .arg("--password")
        .arg(repo_password)
        .current_dir(local_dir_path.clone())
        .output()
    {
        Ok(output) => {
            if !output.status().unwrap().is_success() {
                return Err("Failed to add remote repository".to_string());
            }
        }
        Err(err) => {
            println!("Error adding remote repository: {}", err);
        }
    };

    match Command::new("git")
        .arg("sync")
        .arg("-f")
        .current_dir(local_dir_path.clone())
        .output()
    {
        Ok(output) => {
            if !output.status().unwrap().is_success() {
                return Err("Failed to synchronize local and remote repositories".to_string());
            }
        }
        Err(err) => {
            println!("Error synchronizing repositories: {}", err);
        }
    };

    Ok(local_dir_path)
}
