function mergeBuffers(...sources) {
  const buffers = [];
  for (const source of sources) {
    if (source instanceof Buffer || source instanceof Uint8Array) {
      buffers.push({ type: 'buffer', buffer: source });
    } else if ('file' in source && 'stream' in source) {
      buffers.push({ type: 'file', file: source.file, stream: source.stream });
    }
  }

  const result = Buffer.alloc(0);
  for (const { type, buffer } of buffers) {
    switch (type) {
      case 'buffer':
        mergeBuffer(buffer, result);
        break;
      case 'file':
        mergeFile(buffer.file, buffer.stream, result);
        break;
    }
  }

  return result;

  function mergeBuffer(src, dst) {
    const { length } = src;
    let pos = 0;
    while (pos < length) {
      const chunk = src.slice(pos, pos + 1024 * 64);
      pos += chunk.length;
      if (!dst.write(chunk)) return false;
    }
    return true;

    function write(dst, chunk) {
      const { writable } = dst;
      if (!writable) throw new Error('Buffer is not writable');
      dst.write(chunk);
      return dst.writable();
    }
  }

  function mergeFile(file, stream, dst) {
    let pos = 0;
    try {
      while (pos < file.size) {
        const chunk = stream.readSync(pos, Math.min(1024 * 64, file.size - pos));
        if (!dst.write(chunk)) return false;
        pos += chunk.length;
      }
    } catch (err) {
      throw err;
    }
    return true;

    function write(dst, chunk) {
      const { writable } = dst;
      if (!writable) throw new Error('Buffer is not writable');
      dst.write(chunk);
      return dst.writable();
    }
  }
}
