```java
import java.util.*;
import java.io.*;

public class PacketProcessor {
    private Map<String, Integer> config;
    private Queue<Packet> packetQueue;
    private Map<String, Integer> metrics;

    public PacketProcessor() {
        this.config = new HashMap<>();
        this.packetQueue = new LinkedList<>();
        this.metrics = new HashMap<>();

        // Initialize default configuration and metrics
        config.put("packetSizeThreshold", 1024);
        config.put("sourceIPRange", "0.0.0.0/0");
        config.put("destinationPortRange", "1-65535");
        config.put("packetArrivalTimeThreshold", 100);

        metrics.put("filteredPackets", 0);
        metrics.put("totalPackets", 0);
        metrics.put("averagePacketSize", 0);

        // Start processing packets
        new Thread(this::processPackets).start();
    }

    public void processPackets() {
        while (true) {
            Packet packet = packetQueue.poll();

            if (packet != null) {
                if (filterPacket(packet)) {
                    metrics.put("filteredPackets", metrics.getOrDefault("filteredPackets", 0) + 1);
                } else {
                    metrics.put("totalPackets", metrics.getOrDefault("totalPackets", 0) + 1);

                    // Update average packet size
                    int average = (metrics.get("averagePacketSize") * metrics.get("totalPackets") + packet.getSize()) / (metrics.get("totalPackets") + 1);
                    metrics.put("averagePacketSize", average);
                }
            }

            // Check for system dependencies updates
            checkSystemDependencies();
        }
    }

    public boolean filterPacket(Packet packet) {
        if (packet.getSize() > config.getInt("packetSizeThreshold")) {
            return true;
        }

        if (!packet.getSourceIP().matches(config.getString("sourceIPRange"))) {
            return true;
        }

        if (!packet.getDestinationPort() >= config.getInt("destinationPortRange").getMinimum()
                || packet.getDestinationPort() > config.getInt("destinationPortRange").getMaximum()) {
            return true;
        }

        long arrivalTime = System.currentTimeMillis();
        if (arrivalTime - packet.getArrivalTime() > config.getLong("packetArrivalTimeThreshold")) {
            return true;
        }

        return false;
    }

    public void addPacket(Packet packet) {
        packetQueue.add(packet);
    }

    public Map<String, Integer> getMetrics() {
        return metrics;
    }

    public Map<String, Integer> getConfig() {
        return config;
    }
}
