    // Thread-safe octree operations
    void addNode(int id, bool isLeaf = true) {
        std::lock_guard<std::mutex> lock(mtx);
        if (!root) {
            root = new OctreeNode(id);
        } else {
            insertNode(root, id, isLeaf);
        }
    }

    void removeNode(int id) {
        std::lock_guard<std::mutex> lock(mtx);
        removeNode(root, id);
