use std::env;
use std::fs;
use std::path::{Path, PathBuf};

fn create_directory(dir_name: &str) -> Result<String, String> {
    let current_dir = env::var("CURRENT_DIR")?;
    let dir_path = Path::new(&current_dir).join(dir_name);

    if fs::create_dir_all(&dir_path).is_err() {
        return Err(format!("Failed to create directory '{}'", dir_name));
    }

    let dir_path_str = dir_path.to_str().unwrap_or("");
    env::set_var("NEW_DIR", dir_path_str)?;

    Ok(dir_path_str.into())
}

fn main() {
    match create_directory("my_new_dir") {
        Ok(path) => println!("Directory created: {}", path),
        Err(error) => eprintln!("{}", error),
    }
}
