```java
import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class CommandExecutor {

    private static final int MAX_CONCURRENT_PROCESSES = 5;
    private static final int COMMAND_EXECUTION_TIMEOUT = 30000; // milliseconds

    public void executeCommands(String[] commands) throws IOException, InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_PROCESSES);

        for (String command : commands) {
            executor.submit(() -> {
                try {
                    File fileToDelete = new File(command);
                    if (fileToDelete.exists()) {
                        fileToDelete.delete();
                    }

                    Process process = Runtime.getRuntime().exec(command);

                    BufferedReader outputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                    String outputLine;
                    StringBuilder outputBuilder = new StringBuilder();

                    while ((outputLine = outputReader.readLine()) != null) {
                        outputBuilder.append(outputLine).append("\n");
                    }

                    BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
                    String errorLine;
                    StringBuilder errorBuilder = new StringBuilder();

                    while ((errorLine = errorReader.readLine()) != null) {
                        errorBuilder.append(errorLine).append("\n");
                    }

                    int exitValue = process.waitFor(COMMAND_EXECUTION_TIMEOUT, TimeUnit.MILLISECONDS);

                    if (exitValue == 0) {
                        System.out.println("Command executed successfully: " + command);
                        System.out.println("Output: " + outputBuilder.toString());
                        System.out.println("Error: " + errorBuilder.toString());
                    } else {
                        System.err.println("Command execution failed: " + command);
                        System.err.println("Exit value: " + exitValue);
                    }
                } catch (IOException | InterruptedException e) {
                    System.err.println("An error occurred while executing the command: " + command);
                    System.err.println("Error message: " + e.getMessage());
                }
            });
        }

        executor.shutdown();
    }
}
