#include <iostream>
#include <memory>
#include <string>

class DatabaseConfig {
public:
    std::shared_ptr<std::string> url;
    std::shared_ptr<std::string> username;
    std::shared_ptr<std::string> password;
    int* timeout;
    int* maxRetries;
    void (*errorCallback)(const std::string&);
};

void establishDbConnection(DatabaseConfig config) {
    if (!config.url || !config.username || !config.password) {
        throw std::runtime_error("Invalid database configuration: URL, username, or password is null or empty.");
    }

    if (*config.timeout <= 0 || *config.maxRetries < 1) {
        throw std::invalid_argument("Invalid connection timeout or maximum retries. Timeout must be positive and max retries must be at least 1.");
    }

    try {
        // Integrate with the third-party database driver API
        auto dbConn = std::make_shared<DatabaseDriver>(config.url, config.username, config.password);

        if (!dbConn->connect(*config.timeout, *config.maxRetries)) {
            throw std::runtime_error("Failed to establish database connection.");
        }

        // Log successful connection
        config.errorCallback(std::string("Connected to ") + *config.url);
    } catch (const std::exception& e) {
        // Log error and propagate the exception
        config.errorCallback(std::string("Error connecting to ") + *config.url + ": " + e.what());
        throw;
    }
}
