        // Handle deletion
        if (isset($requestData['id'])) {
            // Delete user account with the provided ID
            $userToDelete = getUserAccountFromDB($requestData['id']);
            if ($userToDelete) {
                deleteUserAccount($userToDelete);
                $response['message'] = 'User account deleted successfully';
            } else {
                $response['message'] = 'Error deleting user account: invalid ID';
                $response['status_code'] = 400;
