class BatchFileProcessor:
    def __init__(self):
        self.cache = {}
        self.max_file_size_for_compression = 1024 * 1024 * 50
        self.concurrent_operations = 5

    @lru_cache(maxsize=1000)
    def process_file(self, file_path, read_func=None, write_func=None, compress_func=None):
        if not os.path.exists(file_path):
            logger.error(f"File {file_path} does not exist")
            return

        file_size = os.path.getsize(file_path)

        if file_size > self.max_file_size_for_compression:
            compression_result = self.compress_file(file_path, compress_func)
            self.cache[file_path] = compression_result
        else:
            compression_result = None

        operations_queue = LifoQueue()
        progress_report_callback = None

        def process_read():
            result = read_func(file_path)
            operations_queue.put(result)

        def process_write():
            write_func(file_path, operations_queue.get())

        def process_compress():
            if compression_result is not None:
                write_func(file_path, compression_result)

        threads = []
        for func in [process_read, process_write, process_compress]:
            thread = threading.Thread(target=func)
            thread.start()
            threads.append(thread)

        while any(thread.is_alive() for thread in threads):
            result = operations_queue.get()
            progress_report_callback(f"File {file_path} processed. Operations: {result['operations']}. Time taken: {result['time']}")

        for thread in threads:
            thread.join()

    def compress_file(self, file_path, compress_func):
        # Implement compression logic here
        pass

    def start_processing(self, file_paths, read_func=None, write_func=None, compress_func=None, progress_report_callback=None):
        for file_path in file_paths:
            self.process_file(file_path, read_func, write_func, compress_func)
            if progress_report_callback is not None:
                progress_report_callback(f"File {file_path} processed")
