                        "1 Kings", "2 Kings", "1 Chronicles", "2 Chronicles", "Ezra", "Nehemiah", "Esther", "Job", "Psalms", "Proverbs",
                        "Ecclesiastes", "Song of Solomon", "Isaiah", "Jeremiah", "Lamentations", "Ezekiel", "Daniel", "Hosea", "Joel",
                        "Amos", "Obadiah", "Jonah", "Micah", "Nahum", "Habakkuk", "Zephaniah", "Haggai", "Zechariah", "Malachi"]

NEW_TESTAMENT_BOOKS = ["Matthew", "Mark", "Luke", "John", "Acts", "Romans", "1 Corinthians", "2 Corinthians", "Galatians", "Ephesians",
                        "Philippians", "Colossians", "1 Thessalonians", "2 Thessalonians", "1 Timothy", "2 Timothy", "Titus", "Philemon",
                        "Hebrews", "James", "1 Peter", "2 Peter", "1 John", "2 John", "3 John", "Jude", "Revelation"]

def ExtractBooksFromTextAdvanced(text: str, callback: Callable[[int], None] = None) -> Dict[str, int]:
    if not isinstance(text, str):
        raise ValueError("Invalid input type. Input must be a string.")

    text = re.sub(r'[^\w\s]', '', text).lower()

    book_counts: Dict[str, int] = {}

    for word in text.split():
        if word in OLD_TESTAMENT_BOOKS:
            book_counts[word] = book_counts.get(word, 0) + 1
        elif word in NEW_TESTAMENT_BOOKS:
            book_counts[word] = book_counts.get(word, 0) + 1

    if callback is not None:
        for i, (book, count) in enumerate(book_counts.items()):
            callback(i)

    return book_counts
