function extractBibleBooks(text, ignoreList = []) {
  const oldTestamentRegex = /Act|Amos|Ezra|Ezekiel|Esther|Exodus|Gensis|Habakkuk|Haggai|Hebrews|Hosea|Isaiah|Jeremiah|Job|Joel|Jonah|Joshua|Judges|Lamentations|Leviticus|Malachi|Micah|Numbers|Obadiah|Philemon|Philippians|Proverbs|Psalm|Ruth|Song|Titus|
    3John|1Corinthians|2Corinthians|Galatians|Hebrews|James|Romans|1Thessalonians|2Thessalonians/i;
  const newTestamentRegex = /Matthew|Mark|Luke|John|Acts/i;

  let bibleBooks = {};
  let textNoPunctuation = text.replace(/[^\w\s]/g, '');
  let matches = [];

  if (textNoPunctuation) {
    matches = oldTestamentRegex.exec(textNoPunctuation) || newTestamentRegex.exec(textNoPunctuation);

    while (matches) {
      const bookName = matches[0].toLowerCase();

      if (!ignoreList.includes(bookName)) {
        bibleBooks[bookName] = (bibleBooks[bookName] || 0) + 1;
      }

      matches = oldTestamentRegex.exec(textNoPunctuation) || newTestamentRegex.exec(textNoPunctuation);
    }

    if (Object.keys(bibleBooks).length === 0) {
      return `No Bible books found in the text. Consider specifying a custom ignore list or checking for typos.`;
    } else {
      return bibleBooks;
    }
  } else {
    return 'Invalid input. Please provide a string of text.';
  }
}
