Here is the Java application code using Spring Framework for a WebSocket server with message broadcasting, connection timeouts, thread safety, role-based authentication, and detailed logging:

```java
@Configuration
@EnableWebSocket
public class WebSocketConfig extends SimplewebsocketConfigurer {

    @Bean
    public WebSocketHandler webSocketHandler() {
        return new MyWebsocketHandler();
    }
}

@ServerEndpoint("/my-websocket")
public class MyWebsocketHandler implements WebSocketHandler {

    private final Logger logger = LoggerFactory.getLogger(MyWebsocketHandler.class);

    private Map<Session, String> sessions;

    @OnOpen
    public void onOpen(Session session) {
        sessions.put(session, null);
        logger.info("New connection from {}", session.getRemoteAddress());
    }

    @OnClose
    public void onClose(Session session) {
        logger.info("Connection closed by {}.", session.getRemoteAddress());
        sessions.remove(session);
    }

    @OnError
    public void onError(Session session, Throwable throwable) {
        logger.error("Error occurred on connection {}", session.getRemoteAddress(), throwable);
    }

    @OnMessage
    public void onMessage(Session session, String message) {
        // Handle message from client
        logger.info("Received message '{}' from {}.", message, session.getRemoteAddress());
        // Broadcast to all connected clients
        sessions.forEach((k, v) -> k.sendMessage(message));
    }
}

@Configuration
public class SecurityConfig extends WebSecurityConfigurerAdapter {

    @Override
    protected void configure(HttpSecurity http) throws Exception {
        http.authorizeRequests()
                .antMatchers("/my-websocket").hasRole("USER")
                .anyRequest().authenticated()
                .and()
                .httpBasic();
    }
}

@Configuration
public class LogConfig extends WebMvcConfigurer {

    @Value("${log.level}")
    private String logLevel;

    @Bean
    public Logger logger() {
        return LoggerFactory.getLogger(LogConfig.class);
    }

    @Override
    public void configureWebLogging(WebLoggingConfigurer configurer) {
        configurer.logLevel(logLevel.toUpperCase());
    }
}
