```php
<?php

require 'vendor/autoload.php';

use GuzzleHttp\Client;

class UserAccountManagementMicroservice {

    private $db;
    private $emailVerificationService;
    private $paymentGatewayApi;
    private $socialMediaLoginProvider;
    private $rateLimiter;
    private $sessionManager;
    private $kubernetesScaler;

    public function __construct() {
        $this->db = new PDO('mysql:host=localhost;dbname=ecommerce', 'root', '');
        $this->emailVerificationService = new Client(['base_uri' => 'https://email-verification-service.com']);
        $this->paymentGatewayApi = new Client(['base_uri' => 'https://payment-gateway-api.com']);
        $this->socialMediaLoginProvider = new SocialMediaLoginProvider();
        $this->rateLimiter = new RateLimiter();
        $this->sessionManager = new SessionManager();
        $this->kubernetesScaler = new KubernetesScaler();

        // Initialize role-based access control
        $this->roleBasedAccessControl = new RoleBasedAccessControl();
    }

    public function createUser($request) {
        $email = trim($request['email']);
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            return json_encode(['status' => 'error', 'message' => 'Invalid email address']);
        }

        // Validate uniqueness of provided email
        $existingUser = $this->db->prepare('SELECT * FROM users WHERE email = :email')->execute([':email' => $email])->fetch();
        if ($existingUser) {
            return json_encode(['status' => 'error', 'message' => 'Email already exists']);
        }

        // Validate password complexity
        $password = trim($request['password']);
        if (!preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*#?&])[A-Za-z\d@$!#*%?&]{8,}$/', $password)) {
            return json_encode(['status' => 'error', 'message' => 'Password must meet complexity requirements']);
        }

        // Validate MFA
        if (!$this->validateMfa($request['mfa'])) {
            return json_encode(['status' => 'error', 'message' => 'Multi-factor authentication failed']);
        }

        // Create user account
        $userId = $this->db->prepare('INSERT INTO users (email, password, role) VALUES (:email, :password, :role)')->execute([':email' => $email, ':password' => password_hash($password, PASSWORD_DEFAULT), ':role' => 'user'])->insertId;

        // Send verification email
        $this->sendVerificationEmail($email);

        return json_encode(['status' => 'success', 'message' => 'User account created successfully', 'data' => ['id' => $userId]]);
    }

    public function updateUser($request) {
        // Validate user role for updates
        if (!$this->roleBasedAccessControl->canUpdateAccount()) {
            return json_encode(['status' => 'error', 'message' => 'Insufficient permissions']);
        }

        // Validate email uniqueness
        $email = trim($request['email']);
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            return json_encode(['status' => 'error', 'message' => 'Invalid email address']);
        }

        // Validate password complexity (only required for role-based updates)
        if ($this->roleBasedAccessControl->canUpdateAccount()) {
            $password = trim($request['password']);
            if (!preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*#?&])[A-Za-z\d@$!#*%?&]{8,}$/', $password)) {
                return json_encode(['status' => 'error', 'message' => 'Password must meet complexity requirements']);
            }
        }

        // Validate MFA
        if (!$this->validateMfa($request['mfa'])) {
            return json_encode(['status' => 'error', 'message' => 'Multi-factor authentication failed']);
        }

        // Update user account
        $this->db->prepare('UPDATE users SET email = :email, password = :password WHERE id = :id')->execute([':email' => $email, ':password' => password_hash($request['password'], PASSWORD_DEFAULT), ':id' => $request['userId']]);

        return json_encode(['status' => 'success', 'message' => 'User account updated successfully', 'data' => ['id' => $request['userId']]]);
    }

    public function deleteUser($request) {
        // Validate user role for deletions
        if (!$this->roleBasedAccessControl->canDeleteAccount()) {
            return json_encode(['status' => 'error', 'message' => 'Insufficient permissions']);
        }

        // Delete user account
        $this->db->prepare('DELETE FROM users WHERE id = :id')->execute([':id' => $request['userId']]);

        return json_encode(['status' => 'success', 'message' => 'User account deleted successfully', 'data' => ['id' => $request['userId']]]);
    }

    // Social media login integration
    public function handleSocialMediaLogin($request) {
        // Authenticate user through social media provider
        $authResponse = $this->socialMediaLoginProvider->authenticate($request);

        if (!$authResponse) {
            return json_encode(['status' => 'error', 'message' => 'Authentication failed']);
        }

        // Validate email uniqueness
        $email = trim($authResponse['email']);
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            return json_encode(['status' => 'error', 'message' => 'Invalid email address']);
        }

        // Create or update user account based on social media provider's response
        if ($this->db->prepare('SELECT * FROM users WHERE email = :email')->execute([':email' => $email])->fetch()) {
            // Update existing user account
            $this->db->prepare('UPDATE users SET role = :role WHERE id = :id')->execute([':role' => 'social-media-user', ':id' => $authResponse['userId']]);
        } else {
            // Create new user account
            $userId = $this->db->prepare('INSERT INTO users (email, password, role) VALUES (:email, :password, :role)')->execute([':email' => $email, ':password' => password_hash($request['password'], PASSWORD_DEFAULT), ':role' => 'social-media-user'])->insertId;
        }

        return json_encode(['status' => 'success', 'message' => 'Social media login successful', 'data' => ['id' => $authResponse['userId']]]);
    }
}

class RateLimiter {
    private $ipAddress;
    private $requestsPerMinute;

    public function __construct() {
        $this->ipAddress = $_SERVER['REMOTE_ADDR'];
        $this->requestsPerMinute = 500;
