Here is the C# class library that dynamically loads, caches, and parses XML documents from various sources (local file systems, network shares, Azure Blob Storage) using XPath:

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Xml;
using Microsoft.Azure.Storage;
using Microsoft.Azure.Storage.Blob;

namespace XmlParser
{
    public class XmlDocumentLoader
    {
        private readonly Dictionary<string, XmlDocument> _cachedDocuments = new();
        private readonly object _cacheLock = new();
        private readonly TimeSpan _cacheExpiration = TimeSpan.FromHours(1);
        private readonly CloudBlobClient _blobClient;
        private readonly string _schemaValidationDatabaseConnectionString;

        public XmlDocumentLoader(CloudBlobClient blobClient, string schemaValidationDatabaseConnectionString)
        {
            _blobClient = blobClient;
            _schemaValidationDatabaseConnectionString = schemaValidationDatabaseConnectionString;
        }

        public XmlDocument LoadXmlDocument(string sourceUri)
        {
            lock (_cacheLock)
            {
                if (_cachedDocuments.TryGetValue(sourceUri, out XmlDocument document))
                {
                    return document;
                }
            }

            string xmlString = LoadXmlFromSource(sourceUri);
            XmlDocument document = ParseXml(xmlString);

            lock (_cacheLock)
            {
                _cachedDocuments.Add(sourceUri, document);
                // Set cache expiration
                _cachedDocuments.Add($"{sourceUri}_expiration", new DateTime(DateTime.Now.Add(_cacheExpiration).Ticks));
            }

            return document;
        }

        private string LoadXmlFromSource(string sourceUri)
        {
            if (sourceUri.StartsWith("file://"))
            {
                return File.ReadAllText(sourceUri.Substring(7));
            }
            else if (sourceUri.StartsWith("http://") || sourceUri.StartsWith("https://"))
            {
                // Download XML from network share
                using var webClient = new System.Net.WebClient();
                return webClient.DownloadString(sourceUri);
            }
            else if (sourceUri.StartsWith("azblob://"))
            {
                string blobUri = sourceUri.Substring(8);
                CloudBlobDownloadInfo downloadInfo = _blobClient.Download_blob(blobUri).WithProgressHandler((send, complete, percentage) =>
                {
                    Console.WriteLine($"Downloading {percentage}%");
                }).GetResult();
                return Encoding.UTF8.GetString(downloadInfo.Content);
            }
            else
            {
                throw new Exception("Unknown source URI");
            }
        }

        private XmlDocument ParseXml(string xmlString)
        {
            XmlDocument document = new();
            XmlTextReader reader = new(XmlString: xmlString);
            document.Load(reader);
            return document;
        }

        public void ValidateSchema(XmlDocument document, string schemaUri)
        {
            using var stream = _blobClient.Download_blob(schemaUri).WithProgressHandler((send, complete, percentage) =>
            {
                Console.WriteLine($"Downloading {percentage}%");
            }).GetResult().Content;
            XmlSchemaSet schemas = new();
            XmlTextReader reader = new(XmlString: stream.ToString());
            schemas.Add(null, reader);
            document.Validate(schemas);
        }
    }
}
