// Function to read a text file and print contents in comma-separated format
void printFileContents(const char* filePath) {
    FILE* file = fopen(filePath, "r");
    if (file == NULL) {
        printf("Error opening file '%s'\n", filePath);
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        size_t len = strlen(line);
        line[len - 1] = '\0'; // Remove newline character
        printf("%s,", line); // Print each line in comma-separated format
    }
    fclose(file);
}

// Function to calculate average of last two fields in a line
double calculateAverage(char* line) {
    size_t pos = strlen(line) - 2; // Find the position of the last comma
    char* field1 = &line[pos];
    double val1, val2;
    sscanf(field1, "%lf", &val1); // Convert last two fields to doubles
    field1 = strchr(line, ',');
    field1++;
    sscanf(field1, "%lf", &val2);
    return (val1 + val2) / 2.0; // Calculate and return the average
}

