    if os.environ.get('LOG_LEVEL'):
        logging.basicConfig(level=os.environ.get('LOG_LEVEL').upper())
    else:
        logging.basicConfig(level=logging.INFO)

    for logger_name in ['app.logger', 'module1.logger', 'module2.logger']:
        log_config = {
            'class': 'logging.config.DictConfigurator',
            'dictConfig': {
                'version': 1,
                'formatters': {'standard': {'format': '%(asctime)s - %(name)s - %(levelname)s: %(message)s'}},
                'handlers': {'console': {'class': 'logging.StreamHandler', 'formatter': 'standard'}},
                'loggers': {logger_name.split('.')[0]: {'level': os.environ.get('LOG_LEVEL', 'INFO').upper()}}
            }
        }
        dictConfigFromDict(log_config, logging.getLogger(logger_name))

def rotate_log_files():
    for handler in [handler for handler in logging.root.handlers if isinstance(handler, RotatingFileHandler)]:
        if time.time() - handler.tumptime > float(os.environ.get('LOG_ROTATION_INTERVAL', 60)):
            with open(handler.baseFilename + '.' + str(int(time.time())), 'w'):
                pass
            os.rename(handler.baseFilename, handler.baseFilename + '.' + str(int(time.time())))
            handler.doRollover()

def compress_log_files():
    for handler in [handler for handler in logging.root.handlers if isinstance(handler, RotatingFileHandler)]:
        if handler.backupCount > int(os.environ.get('LOG_BACKUP_COUNT', 5)):
            os.remove(handler.baseFilename + '.' + str(int(time.time()) - (int(os.environ.get('LOG_ROTATION_INTERVAL', 60)) * int(os.environ.get('LOG_BACKUP_COUNT', 5)))))
