```rust
use reqwest;
use std::path::{Path, PathBuf};
use std::fs;
use chrono::{DateTime, Utc};

async fn fetch_and_process_data(
    url: &str,
    log_dir_name: &str,
    max_file_size: usize,
) -> Result<(), Box<dyn std::error::Error>> {
    let log_dir = get_or_create_log_directory(log_dir_name)?;

    tokio::spawn(async move {
        if download_json(url, &log_dir).await.is_err() {
            error!("Failed to fetch JSON");
        }
    });

    tokio::spawn(async move {
        if download_xml(url, &log_dir).await.is_err() {
            error!("Failed to fetch XML");
        }
    });

    tokio::spawn(async move {
        if download_csv(url, &log_dir).await.is_err() {
            error!("Failed to fetch CSV");
        }
    });

    Ok(())
}

async fn download_json(url: &str, log_dir: &Path) -> Result<(), Box<dyn std::error::Error>> {
    let request = reqwest::get(&format!("{}/json", url));
    if let Err(err) = request.send().await {
        handle_download_failure("JSON", err)?;
        return Ok(());
    }

    let response = request.await?;
    if !response.status().is_success() {
        error!("Failed to fetch JSON: {}", response.status());
        return Ok(());
    }

    let file_path = log_dir.join("json_data.json");
    let mut file = fs::File::create(&file_path)?;
    file.write_all(response.bytes().await?)?;

    Ok(())
}

async fn download_xml(url: &str, log_dir: &Path) -> Result<(), Box<dyn std::error::Error>> {
    let request = reqwest::get(&format!("{}/xml", url));
    if let Err(err) = request.send().await {
        handle_download_failure("XML", err)?;
        return Ok(());
    }

    let response = request.await?;
    if !response.status().is_success() {
        error!("Failed to fetch XML: {}", response.status());
        return Ok(());
    }

    let file_path = log_dir.join("xml_data.xml");
    let mut file = fs::File::create(&file_path)?;
    file.write_all(response.bytes().await?)?;

    Ok(())
}

async fn download_csv(url: &str, log_dir: &Path) -> Result<(), Box<dyn std::error::Error>> {
    let request = reqwest::get(&format!("{}/csv", url));
    if let Err(err) = request.send().await {
        handle_download_failure("CSV", err)?;
        return Ok(());
    }

    let response = request.await?;
    if !response.status().is_success() {
        error!("Failed to fetch CSV: {}", response.status());
        return Ok(());
    }

    let file_path = log_dir.join("csv_data.csv");
    let mut file = fs::File::create(&file_path)?;
    file.write_all(response.bytes().await?)?;

    Ok(())
}

fn get_or_create_log_directory(log_dir_name: &str) -> Result<PathBuf, Box<dyn std::error::Error>> {
    if !Path::new(log_dir_name).exists() {
        fs::create_dir_all(log_dir_name)?;
    }
    let log_dir = PathBuf::from(log_dir_name);
    Ok(log_dir)
}

fn handle_download_failure(format: &str, err: reqwest::Error) -> Result<(), Box<dyn std::error::Error>> {
    error!("Failed to fetch {}: {}", format, err);
    Ok(())
}
