class SemaphoreManager:
    def __init__(self):
        self.semaphores = {}

    def create_semaphore(self, name: str, value: int) -> None:
        self.semaphores[name] = value

    def delete_semaphore(self, name: str) -> None:
        if name in self.semaphores:
            del self.semaphores[name]
        else:
            raise KeyError(f"Semaphore '{name}' does not exist")

    def increment_semaphore(self, name: str, value: int) -> None:
        if name in self.semaphores:
            self.semaphores[name] += value
        else:
            raise KeyError(f"Semaphore '{name}' does not exist")

    def decrement_semaphore(self, name: str, value: int) -> None:
        if name in self.semaphores:
            self.semaphores[name] -= value
        else:
            raise KeyError(f"Semaphore '{name}' does not exist")

