// Predefined list of supported file types
char* supportedFileTypes[] = {"txt", "jpg", "png", "pdf"};

// Function to parse the original filename and extract the base name and extension
void parseFilename(char* filename, char** baseName, char** extension) {
    *baseName = strtok(filename, ".");
    *extension = strrchr(filename, '.');
}

// Function to determine the appropriate number of digits based on the file type
int determineDigits(char* fileType) {
    int digits;
    if (strcmp(fileType, "jpg") == 0 || strcmp(fileType, "png") == 0) {
        digits = 3;
    } else if (strcmp(fileType, "pdf") == 0) {
        digits = 5;
    } else {
        digits = 4; // Default for other file types
    }
    return digits;
}

// Function to validate the file type against the predefined list of supported types
int validateFileType(char* fileType) {
    int i;
    for (i = 0; i < sizeof(supportedFileTypes) / sizeof(supportedFileTypes[0]); i++) {
        if (strcmp(fileType, supportedFileTypes[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

// Function to update the file extension based on the specified file type
void setFileType(char* baseName, char* originalExtension, char* fileType, char** newExtension) {
    sprintf(*newExtension, ".%s", fileType);
}

// Function to construct the new filename using the parsed base name, determined digits, and updated file type
char* createNewFilename(char* baseName, int digits, char* extension) {
    // Dynamic memory allocation for the new filename
    size_t len = strlen(baseName) + (digits >= 0 ? (int)strlen(extension) : 0);
    char* newFilename = malloc(len + 1);
    sprintf(newFilename, "%s%05d%s", baseName, digits, extension);
    return newFilename;
}

// Function to handle errors and provide appropriate feedback to the caller
void errorHandling(char* errorMessage) {
    // Log the error using an external logging system
    printf("Error: %s\n", errorMessage);
}

