import os
import shutil
import logging
from datetime import datetime
from contextlib import contextmanager
import atexit

LOG_ROTATION_SETTINGS = {
    'log_dir': os.environ.get('LOG_DIR', '/var/log'),
    'rotation_interval': os.environ.get('ROTATION_INTERVAL', 'daily'),
    'backup_count': int(os.environ.get('BACKUP_COUNT', 7)),
}

class LogRotator:
    def __init__(self):
        self.log_dir = LOG_ROTATION_SETTINGS['log_dir']
        self.rotation_interval = LOG_ROTATION_SETTINGS['rotation_interval']
        self.backup_count = LOG_ROTATION_SETTINGS['backup_count']

    @contextmanager
    def atomic_operation(self, op):
        try:
            os.makedirs(self.log_dir, exist_ok=True)
            yield
        finally:
            if not os.path.exists(self.log_dir):
                raise

    def rotate_logs(self):
        if self.rotation_interval == 'daily':
            self.rotate_daily()
        elif self.rotation_interval == 'size-based':
            self.rotate_size_based()

    def rotate_daily(self):
        current_date = datetime.now().strftime('%Y-%m-%d')
        log_file_name = f'logs-{current_date}.log'
        backup_count = self.backup_count

        with self.atomic_operation(lambda: shutil.move(f'{self.log_dir}/{log_file_name}', f'{self.log_dir}/backup/{log_file_name}')):
            for i in range(1, backup_count + 1):
                if os.path.exists(f'{self.log_dir}/backup/logs-{datetime.now().strftime('%Y-%m-%d')}-{i}.log'):
                    shutil.move(f'{self.log_dir}/backup/logs-{datetime.now().strftime('%Y-%m-%d')}-{i}.log', f'{self.log_dir}/backup/logs-{(datetime.now() - timedelta(days=1)).strftime('%Y-%m-%d')}-{i+1}.log')
                else:
                    break
            os.rename(f'{self.log_dir}/{log_file_name}', f'{self.log_dir}/logs.log')

    def rotate_size_based(self):
        log_files = [f for f in os.listdir(self.log_dir) if f.startswith('logs-')]
        sorted_log_files = sorted(log_files, key=lambda x: os.path.getsize(f'{self.log_dir}/{x}'), reverse=True)
        backup_count = self.backup_count

        with self.atomic_operation(lambda: shutil.move(f'{self.log_dir}/{sorted_log_files[0]}, f'{self.log_dir}/backup/{sorted_log_files[0]}')):
            for i in range(1, backup_count + 1):
                if os.path.exists(f'{self.log_dir}/backup{logs}-{datetime.now().strftime('%Y-%m-%d')}-{i}.log'):
                    shutil.move(f'{self.log_dir}/backup/logs-{datetime.now().strftime('%Y-%m-%d')}-{i}.log', f'{self.log_dir}/backup/logs-{(datetime.now() - timedelta(days=1)).strftime('%Y-%m-%d')}-{i+1}.log')
                else:
                    break
            os.rename(f'{self.log_dir}/{sorted_log_files[0]}, f'{self.log_dir}/logs.log')

    def configure_environment(self):
        os.environ['LOG_DIR'] = self.log_dir

def main():
    atexit.register(LogRotator().rotate_logs)
    print('Log rotation initialized. Running in the background.')

if __name__ == '__main__':
    main()
