import json
import os
import boto3
from functools import lru_cache

class ConfigManager:
    def __init__(self, ssm_endpoint=None, local_file_path=None):
        self.ssm = boto3.client('ssm', endpoint_url=ssm_endpoint)
        self.local_file_path = local_file_path
        self.cache_expiration_time = 3600  # Default cache expiration time in seconds

    @lru_cache(maxsize=128)  # Cache size for better performance
    def get_config(self):
        try:
            local_config = self.load_local_config()
            remote_config = self.load_remote_config()
            if remote_config and remote_config != local_config:
                return remote_config
            return local_config or {}
        except Exception as e:
            print(f"Error fetching config: {e}")
            return {}

    def load_local_config(self):
        try:
            with open(self.local_file_path, 'r') as f:
                return json.load(f)
        except FileNotFoundError:
            pass

    def load_remote_config(self):
        try:
            response = self.ssm.get_parameter(Name='my_config', WithDecryption=False)
            if response and 'ParameterValue' in response:
                return json.loads(response['ParameterValue'])
        except Exception as e:
            print(f"Error fetching remote config: {e}")
            return {}

    def invalidate_local_cache(self):
        try:
            os.remove(self.local_file_path)
        except FileNotFoundError:
            pass

    def set_config(self, data):
        self.ssm.put_parameter(Name='my_config', Value=json.dumps(data), Overwrite=True)

if __name__ == '__main__':
    config_manager = ConfigManager(ssm_endpoint='https://your-ssm-endpoint.com', local_file_path='config.json')
    print(config_manager.get_config())
