type User struct {
	ID       int64     `json:"id"`
	Username string    `json:"username"`
	Email     string   `json:"email"`
	Channels  []string `json:"channels"`
}

// Define struct for channel metadata
type Channel struct {
	ID        int64     `json:"id"`
	Name      string    `json:"name"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
	Messages  []Message `json:"messages"`
	Subscribers []User   `json:"subscribers"`
}

// Define struct for message data
type Message struct {
	ID        int64     `json:"id"`
	Sender    User      `json:"sender"`
	Text      string    `json:"text"`
	Timestamp time.Time `json:"timestamp"`
	IsRead    bool      `json:"is_read"`
}

// Initialize database connection and logrus logger
func init() {
	db, err := sql.Open("postgres", "user:password@localhost/chatdb?sslmode=disable")
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	logrus.SetLevel(logrus.InfoLevel)

	http.HandleFunc("/api/channels/{channel_id}", func(w http.ResponseWriter, r *http.Request) {
		channelID := chi.URLParam(r, "channel_id")
		channels, err := getChannel(channelID)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		json.NewEncoder(w).Encode(channels)
	})

	http.HandleFunc("/api/messages/{message_id}", func(w http.ResponseWriter, r *http.Request) {
		messageID := chi.URLParam(r, "message_id")
		messages, err := getMessage(messageID)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		json.NewEncoder(w).Encode(messages)
	})

	http.HandleFunc("/api/users/{user_id}", func(w http.ResponseWriter, r *http.Request) {
		userID := chi.URLParam(r, "user_id")
		users, err := getUser(userID)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		json.NewEncoder(w).Encode(users)
	})

	http.ListenAndServe(":8080", nil)

