use tokio::sync::{mpsc, oneshot};
use reqwest;
use serde_json::json;

#[tokio::main]
async fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        println!("Usage: weather_api <city>");
        return;
    }

    let city = &args[1];
    fetch_weather(city).await.unwrap();
}

async fn fetch_weather(city: &str) -> Result<(), reqwest::Error> {
    // Set the API endpoint URL and headers
    let url = "https://api.openweathermap.org/data/2.5/weather";
    let token = "YOUR_API_TOKEN"; // Replace with your OpenWeatherMap API token

    // Create a client instance with rate limiting
    let client = reqwest::Client::builder()
        .rate_limiting(reqwest::rate_limiter::FixedRate::new(10, 60))
        .build()?;

    // Send a GET request to the API endpoint
    let res = client.get(&url)
        .header("x-api-key", token)
        .query(&json!({"q": city}))
        .send().await?;

    if res.status().is_success() {
        // Parse the JSON response
        let data: serde_json::Value = res.json().await?;
        println!("Current weather in {}: {}", city, data["weather"][0]["description"]);
        fetch_forecast(city).await?
    } else {
        eprintln!("Error fetching weather data: {} {}", res.status(), res.text().await?);
    }

    Ok(())
}

async fn fetch_forecast(city: &str) -> Result<(), reqwest::Error> {
    // Set the API endpoint URL and headers
    let url = "https://api.openweathermap.org/data/2.5/forecast";
    let token = "YOUR_API_TOKEN"; // Replace with your OpenWeatherMap API token

    // Create a client instance with rate limiting
    let client = reqwest::Client::builder()
        .rate_limiting(reqwest::rate_limiter::FixedRate::new(10, 60))
        .build()?;

    // Send a GET request to the API endpoint
    let res = client.get(&url)
        .header("x-api-key", token)
        .query(&json!({"q": city}))
        .send().await?;

    if res.status().is_success() {
        // Parse the JSON response
        let data: serde_json::Value = res.json().await?;
        for forecast in data["list"].as_array().unwrap() {
            println!("Forecast for {}: {}°C", city, forecast["main"]["temp"]);
        }
    } else {
        eprintln!("Error fetching forecast data: {} {}", res.status(), res.text().await?);
    }

    Ok(())
}
