use std::env;
use std::fs;
use std::path::{Path, PathBuf};

pub fn create_directory(dir_name: &str) -> Result<String, String> {
    let dir_path = format!("{}{}", dirs::temp_dir().display(), dir_name);
    if !fs::create_dir_all(&Path::new(&dir_path)) {
        return Err("Failed to create directory".to_string());
    }
    env::set_var("MY_ENV_VAR", &dir_path);
    Ok(dir_path.to_string())
}

pub fn get_environment_variable() -> Result<String, String> {
    match env::var("MY_ENV_VAR") {
        Ok(value) => Ok(value),
        Err(_) => Err("Environment variable not set".to_string()),
    }
}
