```
import asyncio
import json
from collections import defaultdict
from aiohttp import ClientSession
from sortedcontainers import SortedList

class DataAggregator:
    def __init__(self):
        self.api_sessions = {}
        self.data_streams = defaultdict(SortedList)
        self.consolidated_stream = SortedList()

    async def fetch_data(self, api_name: str) -> dict:
        if api_name not in self.api_sessions:
            self.api_sessions[api_name] = ClientSession()
        try:
            response = await self.api_sessions[api_name].get(f"{api_name}/data")
            return json.loads(await response.text())
        except Exception as e:
            print(f"Error fetching data from {api_name}: {e}")

    async def merge_streams(self):
        while True:
            for api_name, stream in self.data_streams.items():
                try:
                    data = await self.fetch_data(api_name)
                    if data:
                        self.data_streams[api_name].extend(data)
                except Exception as e:
                    print(f"Error processing {api_name} stream: {e}")
            for stream in list(self.data_streams.values()):
                if not stream:
                    del self.data_streams[stream]
            await asyncio.sleep(0.1)

    async def process_data(self):
        while True:
            for stream in self.data_streams.values():
                self.consolidated_stream.update(stream)
                stream.clear()
            await asyncio.sleep(0.01)

    async def handle_api_failure(self, api_name: str):
        if api_name in self.api_sessions:
            await self.api_sessions[api_name].close()

    async def start_service(self):
        tasks = [self.merge_streams(), self.process_data()]
        while True:
            done, pending = await asyncio.wait(tasks, return_when=asyncio.FIRST_COMPLETED)
            for task in done:
                if task == tasks[0]:
                    await self.handle_api_failure("high-priority_api")
                elif task == tasks[1]:
                    if not self.consolidated_stream:
                        break
            await asyncio.sleep(0.01)

    async def start(self):
        await asyncio.gather(self.start_service())

def main():
    aggregator = DataAggregator()
    asyncio.run(aggregator.start())

if __name__ == "__main__":
    main()

