class SecureWebFileManager {
    private $hashedPassword;
    private $saltRoundCount = 12;
    private $cachedStrings = [];
    private $characterSet;

    public function __construct() {
        // Initialize character set to a default value
        $this->characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*';
    }

    public function generateSecureRandomString($length) {
        if (!isset($this->cachedStrings[$length])) {
            for ($i = 0; $i < $length; $i++) {
                $this->characterSet .= substr(str_shuffle($this->characterSet), 0, 1);
            }
            $this->cachedStrings[$length] = $this->characterSet;
            $this->characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*';
        }
        return substr($this->cachedStrings[$length], 0, $length);
    }

    public function hashPassword($password) {
        if (!isset($this->$hashedPassword)) {
            $this->$hashedPassword = password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
        }
    }

    public function checkPassword($password) {
        return password_verify($password, $this->$hashedPassword);
    }

    public function validateCharacterSet($characterSet) {
        if (preg_match('/[a-z]/', $characterSet) && preg_match('/[A-Z]/', $characterSet) && preg_match('/\d/', $characterSet) && preg_match('/[^a-zA-Z\d\s]/', $characterSet)) {
            return true;
        } else {
            $this->characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*';
            return false;
        }
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds >= 12 && $rounds <= 31) {
            $this->saltRoundCount = $rounds;
        } else {
            $this->saltRoundCount = 12;
        }
    }

    public function resetPassword() {
        unset($this->$hashedPassword);
        $this->$hashedPassword = null;
        foreach ($this->cachedStrings as $length => $string) {
            unset($this->cachedStrings[$length]);
        }
        $this->cachedStrings = [];
    }

    public function logPasswordAttempts($ipAddress, $result) {
        // Implement logging mechanism here
    }

    public function sanitizeInput($input) {
        // Implement sanitization logic here
    }

    public function validateFileExtension($file, $allowedExtensions) {
