public class DynamicServiceManager {
    private Map<String, ServiceRegistry> tenantRegistries = new HashMap<>();
    private Map<String, ServiceConfig> serviceConfigs = new HashMap<>();
    private Map<String, ServiceInstance> runningServices = new HashMap<>();

    public void addTenant(String tenantId) {
        tenantRegistries.put(tenantId, new ServiceRegistry());
    }

    public void registerService(String tenantId, String serviceName, ServiceInstance service) {
        tenantRegistries.get(tenantId).registerService(serviceName, service);
    }

    public void startService(String tenantId, String serviceName) {
        // Resolve dependencies
        for (ServiceDependency dependency : getDependencies(tenantId, serviceName)) {
            resolveDependency(tenantId, serviceName, dependency);
        }

        // Start the service
        ServiceInstance instance = tenantRegistries.get(tenantId).getService(serviceName);
        if (!runningServices.containsKey(serviceName)) {
            runningServices.put(serviceName, instance);
        } else {
            throw new Exception("Service " + serviceName + " is already running");
        }
    }

    public void stopService(String tenantId, String serviceName) {
        // Stop the service
        ServiceInstance instance = runningServices.remove(serviceName);
        if (instance != null) {
            instance.stop();
        } else {
            throw new Exception("Service " + serviceName + " is not running");
        }
    }

    public void startHealthCheck(String tenantId, String serviceName) {
        // Start health check
        ServiceInstance instance = runningServices.get(serviceName);
        if (instance != null) {
            instance.startHealthCheck();
        } else {
            throw new Exception("Service " + serviceName + " is not running");
        }
    }

    public void stopHealthCheck(String tenantId, String serviceName) {
        // Stop health check
        ServiceInstance instance = runningServices.get(serviceName);
        if (instance != null) {
            instance.stopHealthCheck();
        } else {
            throw new Exception("Service " + serviceName + " is not running");
        }
    }

    public void scaleService(String tenantId, String serviceName, int numInstances) {
        // Scale the service
        ServiceInstance instance = runningServices.get(serviceName);
        if (instance != null) {
            instance.scale(numInstances);
        } else {
            throw new Exception("Service " + serviceName + " is not running");
