#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <sys/ipc.h>
#include <sys/sem.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>

// Configuration structure
typedef struct {
    int max_semaphores;
    int max_semaphore_value;
    int timeout_ms;
} Config;

// Semaphore group structure
typedef struct {
    char* name;
    int num_semaphores;
    sem_t** sems;
} SemaphoreGroup;

// Logging function
void log_operation(char* operation, char* semaphore_name, int value) {
    time_t current_time = time(NULL);
    printf("[%ld] %s: Operation %s on semaphore '%s' with value %d\n", 
           (long)current_time, pthread_self(), operation, semaphore_name, value);
}

// Create a named semaphore
int sem_create(char* name) {
    key_t key = ftok(name, 0);
    int id = semget(key, 1, IPC_CREAT | IPC_EXCL | S_IRUSR | S_IWUSR);
    if (id < 0) {
        perror("semget");
        return -1;
    }
    semctl(id, 0, SETVAL, 0);
    return id;
}

// Delete a named semaphore
int sem_delete(char* name) {
    key_t key = ftok(name, 0);
    int id = semget(key, 1, IPC_RMID);
    if (id < 0) {
        perror("semget");
        return -1;
    }
    return 0;
}

// Increment a named semaphore
int sem_inc(char* name, int value) {
    key_t key = ftok(name, 0);
    int id = semget(key, 1, IPC_STAT);
    if (id < 0) {
        perror("semget");
        return -1;
    }
    struct sembuf sb = {0, value, SEM_OP_SETVAL};
    if (semop(id, &sb, 1) < 0) {
        perror("semop");
        return -1;
    }
    return 0;
}

// Decrement a named semaphore
int sem_dec(char* name, int value) {
    key_t key = ftok(name, 0);
    int id = semget(key, 1, IPC_STAT);
    if (id < 0) {
        perror("semget");
        return -1;
    }
    struct sembuf sb = {0, -value, SEM_OP_SETVAL};
    if (semop(id, &sb, 1) < 0) {
        perror("semop");
        return -1;
    }
    return 0;
}

// Create a named semaphore group
int sem_group_create(char* name, int num_semaphores) {
    SemaphoreGroup* group = malloc(sizeof(SemaphoreGroup));
    group->name = strdup(name);
    group->num_semaphores = num_semaphores;
    group->sems = malloc(num_semaphores * sizeof(sem_t*));
    for (int i = 0; i < num_semaphores; i++) {
        group->sems[i] = sem_create(strcat(strcpy(strdup(name), "/"), itoa(i)));
    }
    return 0;
}

// Delete a named semaphore group
int sem_group_delete(char* name) {
    SemaphoreGroup* group = malloc(sizeof(SemaphoreGroup));
    group->name = strdup(name);
    for (int i = 0; i < group->num_semaphores; i++) {
        sem_delete(strcat(strcpy(strdup(name), "/"), itoa(i)));
    }
    free(group);
    return 0;
}

// Increment a named semaphore group
int sem_group_inc(char* name, int value) {
    SemaphoreGroup* group = malloc(sizeof(SemaphoreGroup));
    group->name = strdup(name);
    for (int i = 0; i < group->num_semaphores; i++) {
        sem_inc(strcat(strcpy(strdup(name), "/"), itoa(i)), value);
    }
    free(group);
    return 0;
}

// Decrement a named semaphore group
int sem_group_dec(char* name, int value) {
    SemaphoreGroup* group = malloc(sizeof(SemaphoreGroup));
    group->name = strdup(name);
    for (int i = 0; i < group->num_semaphores; i++) {
        sem_dec(strcat(strcpy(strdup(name), "/"), itoa(i)), value);
    }
    free(group);
    return 0;
}

