use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use log::{debug, info, warn, error};

const RETENTION_POLICY: usize = 5; // number of recent directories to keep

struct DirectoryManager {
    dir_path: String,
    retention_policy: usize,
}

impl DirectoryManager {
    fn new(dir_name: &str) -> Self {
        let dir_path = format!("{}/{}", env::var("TMP").unwrap(), dir_name);
        DirectoryManager { dir_path, retention_policy: RETENTION_POLICY }
    }

    fn create_dir(&self) -> Result<(), std::io::Error> {
        fs::create_dir_all(&PathBuf::from(self.dir_path.clone()))?;
        Ok(())
    }

    fn set_env_var(&self) -> Result<(), env::VarError> {
        let path = &self.dir_path;
        env::set_var("MY_DIR", path)?;
        Ok(())
    }
}

// Other implementation details...

async fn periodic_cleanup(dir_manager: Arc<Mutex<DirectoryManager>>) {
    loop {
        // wait for 5 minutes
        tokio::time::sleep(std::time::Duration::from_secs(300)).await;

        let mut dir_manager = dir_manager.lock().await;
        if dir_manager.retention_policy > 0 {
            // get a list of all directories under the main directory
            let dirs = fs::read_dir(&PathBuf::from(dir_manager.dir_path.clone()))?;
            let mut recent_dirs: Vec<PathBuf> = vec![];

            for entry in dirs {
                let path = entry?.path();
                if path.is_dir() && path.file_name().unwrap_or("") != " oldest" {
                    // determine the age of this directory
                    let metadata = fs::metadata(&path)?;
                    let last_access_time = metadata.modified()?;
                    let time_diff = Instant::now() - last_access_time;
                    if time_diff.as_secs() > 300 * 24 * 60 * 60 { // older than 30 days
                        recent_dirs.push(path);
                    }
                }
            }

            for dir in recent_dirs.iter().take(dir_manager.retention_policy) {
                fs::remove_dir_all(&dir)?;
            }
        }
    }
}

#[tokio::main]
async fn main() {
    env_logger::init();

    let dir_name = "my_directory";
    let dir_manager = Arc::new(Mutex::new(DirectoryManager::new(dir_name)));

    periodic_cleanup(dir_manager).await;
}
