    return;
  }

  const fileContent = fs.readFileSync(filePath, 'utf8');
  try {
    eval(fileContent);
    callback();
  } catch (err) {
    console.error(`Error loading ${filePath}:`, err);
  }
}

function loadFiles(files, callback) {
  let loadedCount = 0;
  function onFileLoaded() {
    loadedCount++;
    if (loadedCount === files.length) {
      callback();
    }
  }

  files.forEach((file) => {
    const dependencies = file.dependencies;
    loadFile(file.path, dependencies, () => {
      onFileLoaded();
    });
  });
}

function checkAvailability(filePath, callback) {
  fs.stat(filePath, (err, stats) => {
    if (err || !stats.isFile()) {
      console.error(`File ${filePath} not found`);
      callback(false);
    } else {
      callback(true);
    }
  });
}

function loadFilesAsync(files, callback) {
  let loadedCount = 0;
  function onFileLoaded() {
    loadedCount++;
    if (loadedCount === files.length) {
      callback();
    }
  }

  files.forEach((file) => {
    const dependencies = file.dependencies;
    checkAvailability(file.path, (available) => {
      if (!available) return;
      loadFile(file.path, dependencies, () => {
        onFileLoaded();
      });
    });
  });
}

function isDevelopment() {
  return process.env.NODE_ENV !== 'production';
}

function hotReload() {
  if (!isDevelopment()) return;

  function fileChanged(filePath) {
    console.log(`File ${filePath} changed`);
    loadFilesAsync(config.files, () => {
      console.log('Hot reloading complete');
    });
  }

  fs.watch('./', { recursive: true }, (eventType, filePath) => {
    if (eventType === 'change' || eventType === 'remove') {
      fileChanged(filePath);
    }
  });
}

hotReload();

loadFilesAsync(config.files, () => {
  console.log('All files loaded');
});
