import java.util.concurrent.*;
import org.apache.kafka.clients.producer.*;

public class ServicePoolManager {
    private int numServices;
    private int maxMessagesPerService;
    private int minDelayMs;
    private int maxDelayMs;
    private KafkaProducer<String, String> kafkaProducer;

    public ServicePoolManager(int numServices, int maxMessagesPerService, 
                               int minDelayMs, int maxDelayMs) {
        this.numServices = numServices;
        this.maxMessagesPerService = maxMessagesPerService;
        this.minDelayMs = minDelayMs;
        this.maxDelayMs = maxDelayMs;
    }

    public void startServices() {
        ExecutorService threadPool = Executors.newFixedThreadPool(numServices);
        for (int i = 0; i < numServices; i++) {
            ServiceThread service = new ServiceThread();
            threadPool.submit(service);
        }
    }

    public void stopServices() {
        ExecutorService threadPool = Executors.newFixedThreadPool(numServices);
        for (int i = 0; i < numServices; i++) {
            ServiceThread service = new ServiceThread();
            threadPool.submit(() -> {
                try {
                    Thread.sleep((long) (Math.random() * (maxDelayMs - minDelayMs) + minDelayMs));
                    service.stop();
                    kafkaProducer.send("Stopped", "Service stopped");
                } catch (Exception e) {
                    // Handle error
                }
            });
        }
    }

    public class ServiceThread implements Runnable {
        private boolean isRunning = true;
        private int messagesProcessed;

        @Override
        public void run() {
            while (isRunning && messagesProcessed < maxMessagesPerService) {
                try {
                    Thread.sleep((long) (Math.random() * (maxDelayMs - minDelayMs) + minDelayMs));
                    messagesProcessed++;
                    // Process message here
                } catch (Exception e) {
                    // Handle error
                }
            }
            stop();
        }

        public void stop() {
            isRunning = false;
        }
    }
}
