class LogProcessor:
    def __init__(self, log_file):
        self.log_file = log_file
        self.request_data = {}
        self.api_token = None

    def process_log(self):
        with open(self.log_file, 'r') as file:
            chunk_size = 1024 * 1024  # Process in chunks of 1MB
            for i in range(0, len(file.read()), chunk_size):
                chunk = file.seek(i).read(chunk_size)
                self.process_chunk(chunk)

    def process_chunk(self, chunk):
        lines = chunk.decode().splitlines()
        for line in lines:
            if line:
                try:
                    ip, request_time, status_code, url = parse_line(line)
                    key = f"{ip}:{url}"
                    if key not in self.request_data:
                        self.request_data[key] = {'requests': 0, 'total_response_time': 0}
                    self.request_data[key]['requests'] += 1
                    self.request_data[key]['total_response_time'] += calculate_response_time(line)
                except Exception as e:
                    logging.error(f"Error processing chunk: {e}")

    def send_api_request(self):
        if not self.api_token or time.time() - self.api_token['timestamp'] > 3600:  # Token expired
            self.refresh_api_token()
        try:
            response = requests.post(API_URL, json=self.request_data)
            response.raise_for_status()
        except Exception as e:
            logging.error(f"Error sending API request: {e}")
            time.sleep(1)  # Retry after 1 second
            self.send_api_request()

    def refresh_api_token(self):
        try:
            response = requests.post(OAuth_TOKEN_URL, json={'grant_type': 'refresh_token'})
            response.raise_for_status()
            token_data = response.json()
            self.api_token = {'token': token_data['access_token'], 'timestamp': time.time()}
        except Exception as e:
            logging.error(f"Error refreshing API token: {e}")

    def start(self):
        self.process_log()
        while True:
            self.send_api_request()
            time.sleep(5)  # Send API request every 5 seconds

