        try:
            with open(self.config_file, 'r') as file:
                self.config_data = json.load(file)
        except Exception as e:
            logging.error(f"Error reading configuration file: {e}")
        return self.config_data

    def get_cryptographic_functions(self) -> List[str]:
        functions = []
        if self.config_data:
            for key, value in sorted(self.config_data.items()):
                if key.startswith('function_'):
                    functions.append(key[9:])
        return functions

    def get_cryptographic_ciphers(self) -> List[str]:
        ciphers = []
        if self.config_data:
            for key, value in sorted(self.config_data.items()):
                if key.startswith('cipher_'):
                    ciphers.append(key[7:])
        return ciphers

    def update_config(self, new_function: str, new_cipher: str):
        try:
            with open(self.config_file, 'w') as file:
                json.dump({**self.config_data, f'function_{new_function}': None}, file)
                json.dump({**self.config_data, f'cipher_{new_cipher}': None}, file)
        except Exception as e:
            logging.error(f"Error updating configuration file: {e}")
