#include <openssl/err.h>
#include <openssl/aes.h>
#include <openssl/rand.h>
#include <stdlib.h>

typedef struct {
    unsigned char* salt;
    int salt_len;
} CipherConfig;

CipherConfig* cipher_config_new(int salt_len) {
    CipherConfig* config = malloc(sizeof(CipherConfig));
    config->salt = NULL;
    config->salt_len = salt_len;
    return config;
}

void cipher_config_free(CipherConfig* config) {
    if (config != NULL) {
        free(config->salt);
        free(config);
    }
}

int generate_salt(unsigned char** salt, int* salt_len) {
    *salt = OPENSSL_malloc(16); // 128 bits
    *salt_len = 16;
    RAND_bytes(*salt, 16);
    return 1;
}

void cipher_config_free(CipherConfig* config) {
    if (config != NULL) {
        free(config->salt);
        free(config);
    }
}

int derive_key(const char* password, int iterations, unsigned char** salt, int salt_len, CipherConfig* config, unsigned char** key, int* key_len) {
    EVP_PBE_Cipher *pbkdf2 = EVP_PBE_method();
    if (pbkdf2 == NULL) {
        return 0;
    }

    // Initialize the PBKDF2 context
    unsigned char* derived_key = OPENSSL_malloc(pbkdf2->ciphersize);
    int derived_key_len = pbkdf2->ciphersize;

    int ret = PBKDF2(password, strlen(password), *salt, salt_len, "pbkdf2", NULL, 0, derived_key, &derived_key_len, iterations);
    if (ret != 1) {
        OPENSSL_free(derived_key);
        return 0;
    }

    // Derive the encryption key
    unsigned char* aes_key = OPENSSL_malloc(AES_BLOCK_SIZE);
    int aes_key_len = AES_BLOCK_SIZE;

    ret = EVP_BytesToKey(pbkdf2, NULL, *salt, salt_len, password, strlen(password), iterations, aes_key, &aes_key_len);
    if (ret != 1) {
        OPENSSL_free(aes_key);
        OPENSSL_free(derived_key);
        return 0;
    }

    // Store the derived key
    *key = aes_key;
    *key_len = aes_key_len;

    // Free temporary resources
    OPENSSL_free(derived_key);

    return 1;
}

int init_aes_cipher(const char* password, int iterations, CipherConfig* config, unsigned char** salt, int salt_len, unsigned char** key, int key_len, AES_CTX** ctx) {
    // Initialize the cipher context
    *ctx = OPENSSL_malloc(sizeof(AES_CTX));
    if (*ctx == NULL) {
        return 0;
    }

    // Set up the cipher parameters
    int cipher_len = AES_BLOCK_SIZE;

    // Derive the encryption key
    int ret = derive_key(password, iterations, salt, salt_len, config, key, &cipher_len);
    if (ret != 1) {
        OPENSSL_free(*ctx);
        return 0;
    }

    // Initialize the cipher context
    AES_CTX *aes_ctx = *ctx;
    aes_ctx->key = *key;
    aes_ctx->key_len = cipher_len;

    // Initialize the IV
    unsigned char* iv = OPENSSL_malloc(AES_BLOCK_SIZE);
    RAND_bytes(iv, AES_BLOCK_SIZE);

    // Initialize the cipher
    ret = AES_set_encrypt_key(aes_ctx->key, aes_ctx->key_len, &aes_ctx->iv);
    if (ret != 1) {
        OPENSSL_free(*ctx);
        return 0;
    }

    return 1;
}

void cleanup_aes_cipher(AES_CTX* ctx) {
    if (ctx != NULL) {
        free(ctx->key);
        free(ctx->iv);
        free(ctx);
    }
}
