        self.config = config
        self.logger = logger
        self.providers = {}

    def load_providers(self) -> None:
        for provider_config in self.config['providers']:
            self.providers[provider_config['name']] = CloudStorageProvider(provider_config, self.logger)

    def download_and_verify_file(self, file_path: str) -> str:
