            md5_hash = hashlib.md5()
            chunk_size = 1024 * 1024  # adjust this value based on your memory constraints
            while True:
                data = file.read(chunk_size)
                if not data:
                    break
                md5_hash.update(data)

        return md5_hash.hexdigest()

    def run(self) -> None:
