const { promisify } = require('util');
const { mkdirp, rm } = require('mkdirp-promise');
const { unzip, gzip } = require('adm-zip');
const fs = require('fs');
const path = require('path');
const axios = require('axios');
const logger = require('./logger');
const config = require('./config');

async function fetchAndProcessFiles({
  url,
  extensions,
  concurrency,
  backoff,
  maxRetries,
  retryCondition,
  cacheExpiration,
}) {
  const fileSystem = require('./file-system')();
  const caching = require('./caching')();

  async function processFile(file) {
    try {
      const response = await axios.get(`${url}/${file}`);
      if (!response.data) throw new Error(`Failed to retrieve ${file}`);

      const fileBuffer = Buffer.from(response.data, 'binary');
      const fileStream = fs.createWriteStream(`./${file}`, { flags: 'w' });
      fileStream.write(fileBuffer);

      await caching.set(file, response.data);
    } catch (error) {
      logger.error(`Error processing ${file}:`, error);
      if (!retryCondition || retryCondition(file)) {
        await wait(backoff);
        await fetchAndProcessFiles({
          url,
          extensions,
          concurrency,
          backoff,
          maxRetries: Math.min(maxRetries - 1, 0),
          retryCondition,
        });
      }
    }
  }

  async function wait(backoff) {
    return new Promise((resolve) => setTimeout(() => resolve(), backoff));
  }

  const concurrentFetches = [];
  for await (const file of fs.readdirSync(url)) {
    if (!extensions.includes(path.extname(file))) continue;
    concurrentFetches.push(async () => {
      try {
        await processFile(file);
      } catch (error) {
        logger.error(`Error processing ${file}:`, error);
      }
    });
  }

  await Promise.all(concurrentFetches.map((fetcher, index) =>
    setTimeout(() => fetcher(), Math.min(index * concurrency, concurrentFetches.length - 1))
  ));

  async function clearCache() {
    const cache = caching.get();
    for (const file in cache) {
      if (!cacheExpiration || Date.now() > cacheExpiration[file]) {
        await rm(`./${file}`);
        delete caching.cache[file];
      }
    }
  }

  try {
    await clearCache();
  } catch (error) {
    logger.error('Error clearing cache:', error);
  }
}

fetchAndProcessFiles({
  url: 'https://example.com/files',
  extensions: ['.zip', '.gz'],
  concurrency: 5,
  backoff: 1000,
  maxRetries: 3,
  retryCondition: (file) => file.size > 1048576,
  cacheExpiration: { zip: 604800000, gz: 86400000 },
});
