public class PaymentProcessor {
    private static final int MAX_PARALLEL_TRANSACTIONS = 10;
    private static final String HMAC_ALGORITHM = "HmacSHA256";
    private static final String AES_ALGORITHM = "AES/CBC/PKCS5Padding";
    private KeyPair keyPair;
    private ExecutorService executor;

    public PaymentProcessor(String privateKey, String publicKey) throws Exception {
        KeyFactory factory = KeyFactory.getInstance("RSA");
        PrivateKey privKey = new RSAKey.privateKey(privateKey);
        PublicKey pubKey = new RSAKey.publicKey(publicKey);
        this.keyPair = new KeyPair(privKey, pubKey);
    }

    public void processTransactions(List<Transaction> transactions) {
        executor = Executors.newFixedThreadPool(MAX_PARALLEL_TRANSACTIONS);
        for (Transaction transaction : transactions) {
            executor.submit(() -> processTransaction(transaction));
        }
        executor.shutdown();
    }

    private void processTransaction(Transaction transaction) {
        try {
            String paymentToken = transaction.getPaymentToken();
            if (!validatePaymentToken(paymentToken)) {
                // invalid token
                return;
            }
            String payload = decryptPayload(transaction);
            List<Item> items = parseItems(payload);
            if (!validateItems(items)) {
                // item validation failed
                return;
            }
            processTransactionThroughGateway(transaction, items);
        } catch (Exception e) {
            // log and handle error
            System.out.println("Error processing transaction: " + e.getMessage());
        } finally {
            // clean up cryptographic resources
            if (executor != null) {
                executor.shutdownNow();
            }
        }
    }

    private boolean validatePaymentToken(String paymentToken) throws Exception {
        String secretKey = getSecretKey();
        Signature signature = Signature.getInstance(HMAC_ALGORITHM);
        signature.init(new PrivateKey(), new javax.crypto.spec.SecretKeySpec(secretKey.getBytes(), HMAC_ALGORITHM));
        byte[] hash = signature.sign(paymentToken.getBytes());
        return MessageDigest.isEqual(hash, paymentToken.getBytes());
    }

    private String decryptPayload(Transaction transaction) throws Exception {
        Cipher cipher = Cipher.getInstance(AES_ALGORITHM);
        cipher.init(Cipher.DECRYPT_MODE, keyPair.getPrivate(), new javax.crypto.spec.IvParameterSpec(transaction.getIv().getBytes()));
        return new String(cipher.doFinal(Base64.getDecoder().decode(transaction.getPayload())));
