const fs = require('fs');
const path = require('path');
const axios = require('axios');

class ReadDirectoryFiles {
  constructor({
    directory,
    extension,
    bufferSize,
    maxConcurrentReads,
    retries,
    corsConfig
  }) {
    this.directory = directory;
    this.extension = extension;
    this.bufferSize = bufferSize;
    this.maxConcurrentReads = maxConcurrentReads;
    this.retries = retries;
    this.corsConfig = corsConfig;

    this.fileContentStrings = [];
    this.fileCounts = [];
  }

  async readDirectoryFiles() {
    const files = await this.getFiles();
    const filePromises = files.map((file) => this.readFile(file));
    const results = await Promise.all(filePromises);

    return this.concatenateResults(results);
  }

  getFiles() {
    return new Promise((resolve, reject) => {
      fs.readdir(this.directory, (err, files) => {
        if (err) reject(err);
        else resolve(files.filter((file) => path.extname(file) === `.${this.extension}`));
      });
    });
  }

  async readFile(file) {
    const filePromise = new Promise((resolve, reject) => {
      let retries = this.retries;
      let attempt = 0;

      function read() {
        fs.readFile(`${this.directory}/${file}`, 'utf8', (err, data) => {
          if (err) {
            if (retries-- > 0) {
              setTimeout(() => read(), 100);
            } else {
              reject(err);
            }
          } else {
            resolve({ file: file, content: data.toString('utf8') });
          }
        });
      }

      read();
    });

    return filePromise;
  }

  concatenateResults(results) {
    const fileContentStrings = results
      .filter((result) => result)
      .map((result) => result.content);

    return fileContentStrings.join('\n');
  }

  logFileInformation(file, contentLength) {
    console.log(`Processing ${file} with length ${contentLength}`);
  }
}

module.exports = ReadDirectoryFiles;
