```
function renderScriptsFooter(scriptArray) {
  const footer = document.getElementById('scripts-footer');
  if (!footer) return '';

  // Remove previously rendered scripts
  while (footer.lastChild) footer.removeChild(footer.lastChild);

  let html = '';
  scriptArray.forEach(script => {
    if (!script || !script.key || !script.innerHTML) return;

    const scriptTag = document.createElement('script');
    scriptTag.setAttribute('key', script.key);
    scriptTag.innerHTML = script.innerHTML;
    footer.appendChild(scriptTag);
    html += `<script key="${script.key}">${script.innerHTML}</script>`;
  });

  return html;
}
