#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define log entry structure
typedef struct {
    char ip[16];
    int request_time;
    int response_code;
} LogEntry;

// Define statistics structure
typedef struct {
    int total_requests;
    int unique_ips;
    float average_response_time;
    float error_rate;
} Statistics;

// Function to parse log entry and extract metrics
void process_log_entry(char* buffer, LogEntry* entry) {
    // Parse IP address
    sscanf(buffer, "%15s", entry->ip);

    // Extract request time and response code
    int time_code;
    sscanf(buffer + strlen(entry->ip) + 1, "%d", &time_code);
    entry->request_time = time_code / 1000; // Convert to seconds
    entry->response_code = time_code % 1000;
}

// Function to update statistics and send updates to monitoring API
void update_statistics(LogEntry* entry, Statistics* stats) {
    // Update total requests
    stats->total_requests++;

    // Update unique IPs
    int found = 0;
    for (int i = 0; i < stats->unique_ips; i++) {
        if (!strcmp(entry->ip, (stats->unique_ips)[i])) {
            found = 1;
            break;
        }
    }
    if (!found) {
        stats->unique_ips++;
    }

    // Update average response time
    float new_avg = (stats->average_response_time * (stats->total_requests - 1) + entry->request_time) / stats->total_requests;
    stats->average_response_time = new_avg;

    // Update error rate
    if (entry->response_code >= 400 && entry->response_code <= 599) {
        stats->error_rate += 1.0 / stats->total_requests;
    }
}

// Function to handle corrupt or malformed log entries
void handle_error(char* buffer, Statistics* stats) {
    printf("Corrupt log entry: %s\n", buffer);
    // Log the error and continue processing
}

// Function to process log stream in chunks
void process_log_stream(FILE* file, int chunk_size, Statistics* stats) {
    char buffer[1024];
    LogEntry entry;

    while (fgets(buffer, 1024, file)) {
        for (int i = 0; i < chunk_size; i++) {
            // Read log entries in chunks
            if (fscanf(file, "%15s %d", entry.ip, &entry.request_time) != 2 || fscanf(file, " %d\n", &entry.response_code) != 1) {
                handle_error(buffer, stats);
                break;
            }
            process_log_entry(buffer, &entry);
            update_statistics(&entry, stats);
        }
    }
}

int main() {
    // Initialize statistics
    Statistics stats = {0};

    // Open log file for processing
    FILE* file = fopen("log_file.log", "r");

    // Process log stream in chunks
    process_log_stream(file, 10); // Process 10 entries at a time

    // Close log file
    fclose(file);

    return 0;
}
