from collections import OrderedDict

class WeatherAPI:
    def __init__(self):
        self._cache = OrderedDict()
        self._logger = logging.getLogger(__name__)
        self._max_cache_size = 100
        self._max_cache_age = 3600  # 1 hour

    async def fetch_weather_data(self, location: str) -> dict:
        if location not in self._cache or (self._cache[location]['age'] > self._max_cache_age):
            try:
                async with aiohttp.ClientSession() as session:
                    url = f"https://api.weather.com/{location}"
                    async with session.get(url) as response:
                        if response.status == 200:
                            data = await response.json()
                            self._cache[location] = {'data': data, 'age': int(asyncio.create_task(asyncio.sleep(0)).result())}
                        else:
                            raise ValueError(f"Failed to retrieve weather data for {location} with status {response.status}")
            except (aiohttp.ClientError, asyncio.TimeoutError) as e:
                self._logger.warning(f"Failed to retrieve weather data for {location}: {e}")
                return None
        return self._cache[location]['data']

    async def prioritize_frequent_locations(self):
        # Mechanism to prioritize frequently requested locations
        pass

    async def manage_cache(self):
        while True:
            await asyncio.sleep(60)  # Check cache every minute
            for location in list(self._cache.keys()):
                if self._cache[location]['age'] > self._max_cache_age or len(self._cache) > self._max_cache_size:
                    del self._cache[location]
