import json
from abc import ABCMeta, abstractmethod
from typing import Dict, Any

class CloudResourceOrchestrator(metaclass=ABCMeta):
    def __init__(self):
        self.registry = {}

    @abstractmethod
    def allocate(self, config: Dict[str, Any]) -> None:
        pass

    @abstractmethod
    def deallocate(self, resource_id: str) -> None:
        pass

class CloudResourceFactory(metaclass=ABCMeta):
    @abstractmethod
    def create_resource(self, config: Dict[str, Any], orchestrator: CloudResourceOrchestrator) -> None:
        pass

class ResourceConfig:
    def __init__(self, resource_id: str, type: str, config: Dict[str, Any], provider: str):
        self.resource_id = resource_id
        self.type = type
        self.config = config
        self.provider = provider

class CloudResourceOrchestratorImpl(CloudResourceOrchestrator):
    def allocate(self, config: Dict[str, Any]) -> None:
        factory = self.registry.get(config['provider'])
        if not factory:
            raise Exception(f"Unsupported cloud provider {config['provider']}")
        try:
            resource = factory.create_resource(config, self)
            print(f"Allocated resource {resource.resource_id} of type {resource.type}")
        except Exception as e:
            print(f"Error allocating resource: {str(e)}")

    def deallocate(self, resource_id: str) -> None:
        if resource_id not in self.registry:
            raise Exception(f"Resource {resource_id} not found")
        factory = self.registry[resource_id]['factory']
        try:
            factory.deallocate(resource_id)
            print(f"Dereleased resource {resource_id}")
        except Exception as e:
            print(f"Error deallocating resource: {str(e)}")

    def register_factory(self, provider: str, factory: CloudResourceFactory) -> None:
        self.registry[provider] = {'factory': factory}

def main():
    orchestrator = CloudResourceOrchestratorImpl()

    # Register factories for different cloud providers
    aws_factory = CloudResourceFactory()
    azure_factory = CloudResourceFactory()
    gcp_factory = CloudResourceFactory()

    orchestrator.register_factory('aws', aws_factory)
    orchestrator.register_factory('azure', azure_factory)
    orchestrator.register_factory('gcp', gcp_factory)

    # Allocate and deallocate resources
    config = {'provider': 'aws', 'type': 'ec2_instance', 'config': {'instance_type': 't3.micro'}}
    orchestrator.allocate(config)

    resource_id = 'resource-123'
    orchestrator.deallocate(resource_id)

if __name__ == "__main__":
    main()
