import argparse
import http.server
import ssl
import socketserver
import logging
from urllib.parse import urlparse, unquote_plus
from io import StringIO
import queue
import threading
import time
import base64

class Config:
    def __init__(self):
        self.port = None
        self.host = None
        self.ssl_cert_path = None
        self.ssl_key_path = None
        self.allowed_ips = []
        self.logging_level = logging.INFO
        self.debug_mode = False
        self.log_file = 'server.log'
        self.ssl_enabled = True

class SecureServer:
    def __init__(self, config):
        self.config = config
        self.httpd = socketserver.TCPServer((config.host, config.port), RequestHandler)
        if config.ssl_cert_path and config.ssl_key_path:
            self.httpd.socket = ssl.wrap_socket(
                self.httpd.socket,
                keyfile=config.ssl_key_path,
                certfile=config.ssl_cert_path,
                server_side=True
            )
        else:
            self.config.ssl_enabled = False

    def start(self):
        if not self.config.debug_mode:
            logging.basicConfig(filename=self.config.log_file, level=self.config.logging_level)
        try:
            self.httpd.serve_forever()
        except KeyboardInterrupt:
            self.httpd.server_close()

class RequestHandler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        path = urlparse(self.path).path
        if not path or path == '/':
            self.send_response(200)
            self.end_headers()
            self.wfile.write(b'Hello, World!')
        elif path.startswith('/auth/'):
            auth_data = unquote_plus(path[6:])
            username, password = base64.b64decode(auth_data.encode()).decode().split(':')
            if username == 'admin' and password == 'password':
                self.send_response(200)
                self.end_headers()
                self.wfile.write(b'Authorized.')
            else:
                self.send_response(401)
                self.end_headers()
        elif path.startswith('/upload/'):
            file_name = unquote_plus(path[8:])
            with open(file_name, 'wb') as f:
                while True:
                    chunk = self.rfile.read(4096)
                    if not chunk:
                        break
                    f.write(chunk)
            self.send_response(201)
            self.end_headers()
            self.wfile.write(b'File uploaded.')
        else:
            self.send_response(404)
            self.end_headers()

class AuthHandler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        if not 'Authorization' in self.headers:
            self.send_response(401)
            self.end_headers()
            return
        auth_data = unquote_plus(self.headers['Authorization'].encode()).decode().split(':')
        username, password = base64.b64decode(auth_data[1].encode()).decode().split(':')
        if username == 'admin' and password == 'password':
            self.send_response(200)
            self.end_headers()
            self.wfile.write(b'Authorized.')
        else:
            self.send_response(401)
            self.end_headers()

def main():
    parser = argparse.ArgumentParser(description='Secure HTTP Server')
    parser.add_argument('--config', type=str, help='Path to the configuration file')
    parser.add_argument('-d', '--debug', action='store_true', help='Start server in debug mode')
    parser.add_argument('-l', '--log-file', type=str, help='Alternative log file')
    parser.add_argument('-n', '--no-ssl', action='store_false', help='Disable SSL encryption')
    args = parser.parse_args()
    config = Config()
    if args.config:
        with open(args.config) as f:
            lines = f.readlines()
            for line in lines:
                key, value = line.strip().split('=')
                setattr(config, key.strip(), value.strip())
    if args.debug:
        config.debug_mode = True
    if args.log_file:
        config.log_file = args.log_file
    if not args.no_ssl:
        config.ssl_enabled = True
    server = SecureServer(config)
    try:
        server.start()
    except Exception as e:
        logging.error('Error starting the server: %s', str(e))

if __name__ == '__main__':
    main()

