import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;

public class CommandExecutor {
    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(5);

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(Runtime.getRuntime().exec("rm -rf /path/to/file").getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {}

            // Execute commands in sequence
            executor.submit(() -> executeCommand("mkdir dir1"));
            executor.submit(() -> executeCommand("touch file.txt"));
            executor.submit(() -> executeCommand("ls -l"));
        } catch (IOException e) {
            System.out.println("Error executing command: " + e.getMessage());
        }

        // Close the executor
        executor.shutdown();
    }

    private static void executeCommand(String command) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(Runtime.getRuntime().exec(command).getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        } catch (IOException e) {
            System.out.println("Error executing command: " + e.getMessage());
        }
    }
}

