        # Create a new buffer for transaction data
        buffer = Buffer.allocUnsafe(1024)

        # Copy transaction details to the buffer
        buffer.copy(Buffer.from(json.dumps(transaction_details)))

        # Process the payment request with the payment gateway API
        response = process_payment_request(payment_request, access_token, buffer)

        if response['status'] == 'success':
            # Update the customer's account balance and transaction history in the database
            update_customer_account_and_transaction_history(customer_id, response['transaction_id'])

            return {'status': 'success', 'transaction_id': response['transaction_id']}
        else:
