def cached_view(timeout=300):  # 5 minutes
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            cache_key = f"inventory-{func.__name__}-{request.url}"
            if cache.get(cache_key):
                return jsonify({"message": "Cache hit!"})
            else:
                result = func(*args, **kwargs)
                cache.set(cache_key, True, timeout)
                return result
        return wrapper
    return decorator

