def retry_on_request_exception(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        for _ in range(3):  # Max 2 retries
            try:
                return func(*args, **kwargs)
            except RequestException as e:
                if _ < 2:  # Retry if request exception occurs
                    continue
                else:
                    raise
    return wrapper

