function renderScriptsFooter(scripts) {
  const queue = [];
  const maxConcurrentRequests = 3;
  let externalScriptCount = 0;

  scripts.forEach((script) => {
    if (script.url) {
      queue.push({
        type: 'external',
        script,
        resolve: () => {
          externalScriptCount++;
        },
      });
    } else {
      const scriptTag = document.createElement('script');
      scriptTag.key = `script-${Date.now()}`;
      scriptTag.innerHTML = script.code;
      document.body.appendChild(scriptTag);
    }
  });

  (async () => {
    while (queue.length > 0) {
      await loadExternalScripts(queue.splice(0, maxConcurrentRequests));
    }

    // Fallback mechanism for failed external scripts
    if (externalScriptCount < queue.length) {
      const fallbackMessage = 'Failed to load script(s)';
      // Display user-friendly message instead of script content
    }
  })();
}

async function loadExternalScripts(scriptsToLoad) {
  for await (const { type, script } of scriptsToLoad) {
    if (type === 'external') {
      try {
        const response = await fetch(script.url);
        const code = await response.text();
        const scriptTag = document.createElement('script');
        scriptTag.key = `script-${Date.now()}`;
        scriptTag.innerHTML = code;
        document.body.appendChild(scriptTag);
      } catch (error) {
        // Handle errors gracefully
      }
    }
  }
}
