const express = require('express');
const app = express();
const rateLimit = require('express-rate-limit');
const lruCache = require('lru-cache');
const axios = require('axios');
const { API_KEY, API_SECRET } = process.env;

app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
}));

class Aggregator {
  constructor(apiKey, apiSecret) {
    this.apiKey = apiKey;
    this.apiSecret = apiSecret;
    this.cache = lruCache({ max: 5000 });
    this.conversions = new Map();
  }

  async convertValue(value) {
    if (typeof value === 'string') {
      try {
        const numValue = parseFloat(value);
        return numValue;
      } catch (err) {
        throw new Error(`Invalid numeric value: ${value}`);
      }
    }
    return value;
  }

  async aggregate(data) {
    let aggregated = 0;
    for await (const val of data) {
      const converted = await this.convertValue(val);
      if (!this.conversions.has(converted)) {
        try {
          const response = await axios.get(`https://api.example.com/convert?apiKey=${this.apiKey}&value=${converted}`, { headers: { 'Authorization': `Basic ${this.apiSecret}` } });
          const rate = response.data.rate;
          this.conversions.set(converted, rate);
          this.cache.set(converted, rate);
        } catch (err) {
          console.error('Error fetching conversion rate:', err);
          continue;
        }
      }
      aggregated += converted * this.conversions.get(converted);
    }
    return aggregated;
  }

  async processBatch(data) {
    const results = [];
    for await (const chunk of data.chunk(100)) {
      try {
        const aggregated = await this.aggregate(chunk);
        results.push(aggregated);
      } catch (err) {
        console.error('Error aggregating values:', err);
        return [];
      }
    }
    return results.reduce((acc, val) => acc + val, 0);
  }

  async run(data) {
    const progress = { completed: 0, total: data.length };
    let aggregated = 0;
    for await (const value of data) {
      try {
        aggregated += await this.processBatch([value]);
      } catch (err) {
        console.error('Error processing value:', err);
        continue;
      }
      progress.completed++;
      process.stdout.write(`Aggregated: ${aggregated} - Completed: ${progress.completed}/${progress.total}\r`);
    }
  }
}

const aggregator = new Aggregator(API_KEY, API_SECRET);

app.post('/aggregate', async (req, res) => {
  try {
    const data = req.body.data;
    const result = await aggregator.run(data);
    res.json({ aggregated: result });
  } catch (err) {
    res.status(500).send({ error: err.message });
  }
});

app.listen(3000, () => {
  console.log('Aggregation service listening on port 3000');
});
