            } else {
                println!("Creating a new directory and setting the environment variable CONFIG_DIR.");
                std::env::set_var("CONFIG_DIR", &path)?;
            }
        },
        Err(e) => {
            eprintln!("Failed to create directory: {}", e);
            exit(1);
        }
    }

    Ok(())
}
