```javascript
const OT_BOOKS = ['genesis', 'exodus', 'leviticus', 'numbers', 'deuteronomy', 'joshua', 'judges', 'ruth', '1samuel', '2samuel', '1kings', '2kings', '1chronicles', '2chronicles', 'ezra', 'nehemiah', 'ester'];
const NT_BOOKS = ['matthew', 'mark', 'luke', 'john', 'acts', 'romans', '1corinthians', '2corinthians', 'galatians', 'ephesians', 'philippians', 'colossians', 'philemon', 'hebrews', 'james', '1peter', '2peter', '1john', '2john', '3john', 'jude', 'revelation'];

function extractBookNames(text) {
  let otRegex = new RegExp(`\\b(${OT_BOOKS.join('|')})\\b`, 'gi');
  let ntRegex = new RegExp(`\\b(${NT_BOOKS.join('|')})\\b`, 'gi');

  const bookCounts = {};

  for (let regex of [otRegex, ntRegex]) {
    let matches = text.match(regex);
    if (matches) {
      matches.forEach((match) => {
        if (!bookCounts[match.toLowerCase()]) {
          bookCounts[match.toLowerCase()] = 0;
        }
        bookCounts[match.toLowerCase()]++;
      });
    }
  }

  return bookCounts;
}
