@app.route('/file-hash/<path:path>')
def calculate_file_hash(path):
    try:
        md5 = hashlib.md5()
        with open(path, 'rb') as file:
            chunk = file.read(4096)
            while chunk:
                md5.update(chunk)
                chunk = file.read(4096)
        return jsonify({'hash': md5.hexdigest()})
    except Exception as e:
        logging.error(f"Error calculating hash for file {path}: {str(e)}")
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)

