Here is the C program that reads a large text file line by line, processes each line, calculates the sum and average of the last three fields on each line, and prints these averages in a comma-separated format:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <inttypes.h>
#include <stdarg.h>

// Function prototypes
void process_file(const char*, int, int, FILE**, const char*);
double calculate_average(double *, int);

int main() {
    // Initialize variables
    int start_line = 1;
    int end_line = 1000;
    int num_threads = 4;
    const char* output_file = NULL;

    // Parse command-line arguments
    int c;
    while ((c = getopt(1, "s:e:t:o:", "start_line:end_line:threads:output_file:")) != -1) {
        switch (c) {
            case 's':
                start_line = atoi(optarg);
                break;
            case 'e':
                end_line = atoi(optarg);
                break;
            case 't':
                num_threads = atoi(optarg);
                break;
            case 'o':
                output_file = optarg;
                break;
        }
    }

    // Open the input file
    FILE* file = fopen("input.txt", "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening input file: %s\n", strerror(errno));
        return 1;
    }

    // Initialize logging system
    int log_level = INFO;
    char log_file[] = "log.txt";
    FILE* log_fp = fopen(log_file, "w");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Start processing file in parallel
    process_file(file, start_line, end_line, &log_fp, output_file);

    // Close the input and log files
    fclose(file);
    fclose(log_fp);

    return 0;
}

void process_file(const char* filename, int start_line, int end_line, FILE** log_fps, const char* output_file) {
    // Open the file
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        return;
    }

    // Initialize variables for parallel processing
    pthread_t threads[num_threads];
    int thread_id;

    // Create and start each thread
    for (int i = 0; i < num_threads; i++) {
        thread_id = i;
        pthread_create(&threads[i], NULL, process_line, (void*)file);
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Close the file
    fclose(file);
}

void* process_line(void* file_ptr) {
    FILE* file = (FILE*)file_ptr;
    char buffer[1024];
    int line_num = 1;

    while (fgets(buffer, sizeof(buffer), file)) {
        // Process the line
        double sum = 0.0;
        int num_fields = 0;
        char* token = strtok(buffer, " ");
        while (token != NULL) {
            // Check if the field is numeric
            double value = strtod(token, NULL);
            if (errno == EINVAL || errno == ERANGE) {
                // Skip non-numeric fields
                continue;
            }
            sum += value;
            num_fields++;
            token = strtok(NULL, " ");
        }

        // Calculate and print the averages
        if (num_fields >= 3) {
            double average = calculate_average(&sum, num_fields);
            printf("%.2f", average);
            if (line_num < end_line) {
                printf(",");
            }
            line_num++;
        }
    }

    return NULL;
}

double calculate_average(double* sum, int num_fields) {
    return (*sum / num_fields);
}
