                                  DisplayAdjustor displayAdjustor, 
                                  UserPreferencesDatabase userPreferencesDatabase) {
        this.weatherDataProvider = weatherDataProvider;
        this.displayAdjustor = displayAdjustor;
        this.userPreferencesDatabase = userPreferencesDatabase;
        this.scheduledExecutorService = Executors.newSingleThreadScheduledExecutor();
    }

    public void start() {
        scheduledExecutorService.scheduleWithFixedDelay(this::fetchAndApplyWeatherData, 
            0, // initial delay
            30 * 1000, // period in milliseconds
            TimeUnit.MILLISECONDS);
    }

    private void fetchAndApplyWeatherData() {
        WeatherData weatherData = weatherDataProvider.getWeatherData();
        if (weatherData != null) {
            displayAdjustor.adjustDisplay(weatherData);
        }
    }
}

