Here is the Java code for the `DatabaseConnectionManager` class:

```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class DatabaseConnectionManager {
    private int initialSize;
    private int maxSize;
    private String connectionString;
    private List<Connection> connections;
    private Lock lock = new ReentrantLock();
    private long maxIdleTime = 300000; // 5 minutes
    private boolean testOnBorrow = true;

    public DatabaseConnectionManager(int initialSize, int maxSize, String connectionString) {
        this.initialSize = initialSize;
        this.maxSize = maxSize;
        this.connectionString = connectionString;
        connections = new ArrayList<>();
    }

    public void initializePool() throws SQLException {
        for (int i = 0; i < initialSize; i++) {
            try {
                Connection conn = DriverManager.getConnection(connectionString);
                connections.add(conn);
            } catch (SQLException e) {
                // Handle exceptions gracefully
            }
        }
    }

    public Connection getConnection() throws InterruptedException, SQLException {
        lock.lock();
        try {
            while (connections.size() == 0) {
                Thread.sleep(100);
            }
            Connection conn = connections.remove(0);
            return conn;
        } finally {
            lock.unlock();
        }
    }

    public void releaseConnection(Connection conn) {
        lock.lock();
        try {
            if (!connections.contains(conn)) {
                connections.add(conn);
            }
        } finally {
            lock.unlock();
        }
    }

    public void testConnection(Connection conn) throws SQLException {
        // Test connection logic
    }

    public void resetPool() throws InterruptedException, SQLException {
        for (Connection conn : new ArrayList<>(connections)) {
            try {
                conn.close();
            } catch (SQLException e) {
                // Handle exceptions gracefully
            }
        }
        connections.clear();
        initializePool();
    }

    public void setMaxIdleTime(long maxIdleTime) {
        if (maxIdleTime < 0) {
            // Handle invalid input
        }
        this.maxIdleTime = maxIdleTime;
    }

    public void setTestOnBorrow(boolean testOnBorrow) {
        this.testOnBorrow = testOnBorrow;
    }

    public void logConnectionUsage(String ipAddress, String action, String databaseName) {
        // Logging framework implementation
    }

    public void monitorPoolStatus() {
        System.out.println("Active connections: " + connections.size());
        System.out.println("Idle connections: " + (maxSize - connections.size()));
        System.out.println("Total connections: " + maxSize);
    }

    public String sanitizeSQLQuery(String query) {
        // Sanitization logic
    }
}
