const { promisify } = require('util');
const { setTimeout } = require('timers');

const asyncArrayReduce = (wordsListAPI, arrayToReduce, callback, accumulator) => {
  const semaphore = new Semaphore(5); // Set a default concurrency level
  const throttlingTimeout = 1000; // Initial throttling timeout

  return async (callback) => {
    let result;
    try {
      await semaphore.acquire();
      const response = await promisify(fetch)(wordsListAPI, { headers: { 'Authorization': 'Bearer <your_api_token>' } });
      const wordList = await response.json();

      if (!wordList || !Array.isArray(wordList)) {
        throw new Error('Invalid response from API');
      }

      result = arrayToReduce.reduce((acc, current) => {
        let accumulatorResult;

        try {
          accumulatorResult = accumulator(acc, current);
        } catch (error) {
          // Log and return error if accumulator function fails
          console.error(`Error in accumulator function: ${error}`);
          return callback(new Error('Accumulator function failed'));
        }

        if (!semaphore.available()) {
          await setTimeout(() => {
            semaphore.release();
          }, throttlingTimeout);
          throttlingTimeout *= 2; // Double the timeout for each concurrent request
        } else {
          semaphore.release();
        }

        return accumulatorResult;
      }, 0);

      callback(null, result);
    } catch (error) {
      // Log and report error if any step fails
      console.error(`Error in asyncArrayReduce: ${error}`);
      callback(error, null);
    } finally {
      semaphore.release();
    }
  };

  function Semaphore(maxConcurrencyLevel) {
    this.maxConcurrencyLevel = maxConcurrencyLevel;
    this.available = () => this._count <= this.maxConcurrencyLevel;
    this.acquire = () => new Promise((resolve) => {
      if (this._count < this.maxConcurrencyLevel) {
        this._count++;
        resolve();
      } else {
        setTimeout(() => {
          this._count--;
          resolve();
        }, 0);
      }
    });
    this.release = () => {
      if (this._count > 0) {
        this._count--;
      }
    };

    let _count = 0;
  }
};
