import json
import os
from collections import defaultdict
from functools import lru_cache
from typing import Dict, List

class BaseClass:
    def __init__(self):
        self.registry = {}
        self.json_registry: Dict[str, str] = {}

    @lru_cache()
    def to_json(self, obj) -> str:
        return json.dumps(obj)

    @lru_cache()
    def from_json(self, data: str) -> object:
        return json.loads(data)

    def register_factory(self, func):
        ...

    def discover_subclasses(self, directory: str):
        for file in os.listdir(directory):
            if file.endswith(".py"):
                module = __import__(file[:-3])
                for subclass_name in dir(module):
                    ifsubclass := getattr(module, subclass_name)
                    if issubclass(subclass, self):
                        self.register_factory(subclass)

    def load_from_yaml(self, yaml_path: str) -> Dict:
        with open(yaml_path, "r") as file:
            return json.load(file)

    def save_to_file(self, file_path: str):
        with open(file_path, "w") as file:
            json.dump(self.json_registry, file)

    def __getitem__(self, name):
        if name in self.registry:
            return self.registry[name]
        raise KeyError(f"Subclass '{name}' not found")

    def __setitem__(self, name, factory):
        self.registry[name] = factory

    def get_subclasses(self) -> List:
        return list(self.registry.keys())

    def __contains__(self, name):
        return name in self.get_subclasses()
