#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>

#define SEMAPHORE_MAX 1000
#define WORD_LIST_SIZE 100

typedef struct {
    char *words;
    int count;
} word_list;

sem_t *named_semaphores[SEMAPHORE_MAX];
int semaphore_count = 0;

void init_semaphore_system() {
    for (int i = 0; i < SEMAPHORE_MAX; i++) {
        sem_init(&named_semaphores[i], 1, 1);
    }
}

void destroy_semaphore_system() {
    for (int i = 0; i < SEMAPHORE_MAX; i++) {
        sem_destroy(&named_semaphores[i]);
    }
}

sem_t *create_named_semaphore(const char *name) {
    if (semaphore_count >= SEMAPHORE_MAX) {
        return NULL;
    }

    named_semaphores[semaphore_count] = &named_semaphores[semaphore_count++];

    sem_init(named_semaphores[semaphore_count - 1], 0, 1);

    return named_semaphores[semaphore_count - 1];
}

void delete_named_semaphore(sem_t *sem) {
    sem_destroy(sem);
    sem = NULL;
}

int increment_semaphore(sem_t *sem) {
    int result;

    pthread_mutex_lock(&sem->mutex);
    result = sem_getvalue(sem, &sem->val);
    if (result < 0) {
        perror("Semaphore error");
        exit(EXIT_FAILURE);
    }
    sem_post(sem);

    pthread_mutex_unlock(&sem->mutex);

    return result;
}

int decrement_semaphore(sem_t *sem) {
    int result;

    pthread_mutex_lock(&sem->mutex);
    sem_getvalue(sem, &sem->val);
    if (sem->val <= 0) {
        perror("Semaphore underflow");
        exit(EXIT_FAILURE);
    }
    sem_wait(sem);

    pthread_mutex_unlock(&sem->mutex);

    return result;
}

