            if version:
                return self.config_cache.get(name, {}).get(version)
            else:
                return next((config for config in self.local_config_files + list(self.config_cache.values()) if config['name'] == name), None)
        except StopIteration:
            print(f"Config {name} not found")
            return None

    def set_config(self, name, value):
        with self.config_lock:
            if name in self.config_cache:
                self.config_cache[name] = value
            else:
                try:
                    response = self.remote_config_service.put_parameter(Name=name, Value=json.dumps(value), Type='String')
                    print(f"Config {name} updated successfully")
                except Exception as e:
                    print(f"Error updating config: {e}")
                    if not self.config_cache.get(name):
                        self.config_cache[name] = value

    def get_config_version(self, name):
