#include <openssl/aes.h>
#include <openssl/err.h>
#include <openssl/pbkdf2.h>

AES_CTX* init_AES_cipher(const char* password, int iteration_count) {
    AES_CTX* ctx = OPENSSL_malloc(sizeof(AES_CTX));
    if (!ctx) return NULL; // Memory allocation failed

    unsigned char *password_bytes = (unsigned char *)password;
    int password_len = strlen(password);
    if (password_len > 31) { // Maximum password length for PBKDF2
        ERR_error_f("Password too long");
        OPENSSL_free(ctx);
        return NULL; 
    }

    // Derive the key using PBKDF2 with given iteration count
    unsigned char *key = OPENSSL_malloc(32);
    if (!key) {
        ERR_error_f("Key allocation failed");
        OPENSSL_free(ctx);
        return NULL;
    }
    int ret = PBKDF2(key, 32, password_bytes, password_len, (unsigned char *)"AES-256-CBC", 12, iteration_count, 32);
    if (!ret) {
        ERR_error_f("PBKDF2 failed");
        OPENSSL_free(ctx); 
        return NULL;
    }

    // Generate a random IV
    unsigned char *iv = OPENSSL_malloc(16);
    if (!iv) {
        ERR_error_f("IV allocation failed");
        OPENSSL_free(ctx);
        OPENSSL_free(key);
        return NULL; 
    }
    RAND_bytes(iv, 16);

    // Initialize the AES-256-CBC cipher context
    ctx->key = key;
    ctx->iv = iv;
    ctx->ctx = AES_new();
    if (!ctx->ctx) {
        ERR_error_f("AES initialization failed");
        OPENSSL_free(ctx);
        return NULL; 
    }

    int err = AES_set_key(ctx->ctx, 32, key) | AES_set_iv(ctx->ctx, 16, iv);
    if (err) {
        ERR_error_f("AES setup failed");
        AES_free(ctx->ctx);
        ctx->ctx = NULL;
        OPENSSL_free(key);
        OPENSSL_free(iv);
        OPENSSL_free(ctx); 
        return NULL; 
    }

    return ctx;
}

void clean_up_AES_cipher(AES_CTX* ctx) {
    if (!ctx) return;

    // Disable the cipher
    AES_free(ctx->ctx);

    // Clean up memory
    OPENSSL_free(ctx->iv);
    OPENSSL_free(ctx->key);
    OPENSSL_free(ctx);

    return;
}
