    public JsonNode parseJson(String json) throws IOException {
        return mapper.readTree(json);
    }

    public Object extractData(JsonNode node, String path) {
        try {
            if (node.isArray()) {
                for (JsonNode child : node) {
                    if (child.has(path)) {
                        // Handle multiple matching nodes
                        return child.get(path);
                    }
                }
            } else if (node.isObject()) {
                ObjectNode object = (ObjectNode) node;
                if (object.has(path)) {
                    return object.get(path);
                }
            }
        } catch (Exception e) {
            // Handle exceptions gracefully
            return null;
        }
        return null;
    }

    public void validateData(JsonNode data, String schema) throws IOException {
        if (!validators.containsKey(schema)) {
            // Initialize validator for the given schema
            validators.put(schema, new Validator(mapper, schema));
        }
        validators.get(schema).validate(data);
    }

    public class Validator {
        private final ObjectMapper mapper;
        private final String schema;

        public Validator(ObjectMapper mapper, String schema) throws IOException {
            this.mapper = mapper;
            this.schema = schema;
        }

        public void validate(JsonNode data) throws IOException {
            // Validate JSON node against the given schema
            // Handle different status codes based on validation outcomes
        }
    }

}
