import logging
from kubernetes import client, config
from queue import Queue
import threading

class DeploymentManager:
    def __init__(self):
        self.config = None
        self.queue = Queue()
        self.lock = threading.Lock()

    def set_k8s_config(self, context, namespace):
        try:
            config.load_kubeconfig(config_file='~/.kube/config', context=context, namespace=namespace)
        except Exception as e:
            logging.error(f"Failed to load Kubernetes configuration: {e}")

    def deploy_container(self, image_name):
        with self.lock:
            if self.queue.full():
                return "Deployment queue is full."

            try:
                v1 = client.V1Api()
                deployment = client.V1Deployment()
                deployment.metadata = client.V1ObjectMeta(name=image_name)
                deployment.spec = client.V1DeploymentSpec(template=client.V1PodTemplateSpec(linux_config=client.V1LinuxConfiguration(image=image_name)))
                v1.create_namespaced_deployment(namespace='default', body=deployment)

            except Exception as e:
                logging.error(f"Failed to deploy container {image_name}: {e}")

    def get_deployment_status(self, image_name):
        with self.lock:
            try:
                v1 = client.V1Api()
                deployment = v1.read_namespaced_deployment(name=image_name, namespace='default')
                return deployment.status

            except Exception as e:
                logging.error(f"Failed to retrieve deployment status for {image_name}: {e}")

    def start(self):
        worker_thread = threading.Thread(target=self.process_queue)
        worker_thread.start()

    def process_queue(self):
        while True:
            try:
                image_name, = self.queue.get(block=False)
                if not image_name:
                    break

                logging.info(f"Processing deployment for {image_name}...")
                self.deploy_container(image_name)

                # Implement queuing mechanism to manage deployment requests
                self.queue.task_done()

            except queue.Empty:
                pass

