async function asyncArrayReduce(array, initial, callback) {
    let accumulator = initial;
    let concurrencyLevel = 5; // you can adjust this value based on your requirements
    let semaphore = new Semaphore(concurrencyLevel);

    try {
        await Promise.all(array.map((num, index) => {
            return new Promise((resolve, reject) => {
                semaphore.wait();
                callback(accumulator, num, (accu, cur) => {
                    accumulator = accu;
                    resolve();
                }, error => {
                    reject(error);
                });
            }).finally(() => {
                semaphore.signal();
            });
        }));

        return accumulator;
    } catch (error) {
        return Promise.reject(error);
    }
}
