import requests
import time
from functools import wraps
from cachetools import TTLCache
from logging import getLogger

class PaymentGateway:
    def __init__(self, api_key, secret_key):
        self.api_key = api_key
        self.secret_key = secret_key

class TransactionProcessor:
    def __init__(self):
        self.payment_gateways = {
            'stripe': StripePaymentGateway('your_stripe_api_key', 'your_stripe_secret_key'),
            'paypal': PayPalPaymentGateway('your_paypal_client_id', 'your_paypal_client_secret'),
            'braintree': BraintreePaymentGateway('your_braintree_merchant_id', 'your_braintree_public_key')
        }
        self.cache = TTLCache(maxsize=1000, ttl=60)  # cache for 1 minute
        self.logger = getLogger()

    def process_transaction(self, transaction):
        gateway_config = self.get_gateway_config(transaction)
        if not gateway_config:
            return None

        try:
            response = requests.post(gateway_config['api_url'], json=transaction, headers=gateway_config['headers'])
            response.raise_for_status()
            self.cache.set(response.json(), 60)  # cache for 1 minute
            return response.json()

        except requests.exceptions.RequestException as e:
            self.logger.error(f"Error processing transaction: {e}")
            time.sleep(2**self.retry_count)  # exponential backoff
            self.retry_count += 1

    def get_gateway_config(self, transaction):
        user_preferences = UserPreferences().get_payment_gateway(transaction.get('user_id'))
        available_services = PaymentGatewayServices().get_available_services()

        if user_preferences:
            return {key: value for key, value in self.payment_gateways.items() if value == user_preferences['payment_gateway']}

        elif available_services:
            return {key: value for key, value in self.payment_gateways.items() if key in available_services}

        else:
            return None

    @wraps(requests.post)
    def retry_request(self, func, *args, **kwargs):
        for _ in range(3):  # max retries
            try:
                return func(*args, **kwargs)
            except requests.exceptions.RequestException as e:
                self.logger.error(f"Error processing transaction: {e}")
                time.sleep(2**self.retry_count)  # exponential backoff
                self.retry_count += 1

        return None

    @property
    def retry_count(self):
        if not hasattr(self, '_retry_count'):
            self._retry_count = 0
        return self._retry_count

def log_exceptions(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            logging.error(f"Error in {func.__name__}: {e}")
            raise

    return wrapper

