use std::fs::{self, DirEntry};
use std::path::{Path, PathBuf};
use regex::Regex;
use rand::thread_rng;
use crypto::digest::Digest;
use crypto::pbkdf2::PBKDF2;

struct ConfigManager {
    repo_url: String,
    branch: String,
    config_dir: String,
}

impl ConfigManager {
    fn new(repo_url: &str, branch: &str) -> Self {
        ConfigManager {
            repo_url: repo_url.to_string(),
            branch: branch.to_string(),
            config_dir: format!("{}/{}", "config", branch),
        }
    }

    fn sync_config(&self) -> Result<(), String> {
        let dir = Path::new(&self.config_dir);
        if !dir.exists() {
            fs::create_dir_all(dir)?;
        }

        let mut files = vec![];
        for entry in dir.read_dir().unwrap() {
            match entry {
                Ok(entry) => {
                    let path = entry.path();
                    if path.is_file() {
                        files.push(path.to_str().unwrap().to_string());
                    }
                },
                Err(_) => return Err("Failed to read directory".to_string()),
            }
        }

        files.sort_unstable();

        let last_entry = &files.last().unwrap();
        let last_sequence = match last_entry.find('_') {
            Some(i) => i + 1,
            None => 0,
        };

        for file in &files {
            if !self.decrypt_config(file)? {
                return Err(format!("Failed to decrypt {}", file));
            }
        }

        Ok(())
    }

    fn decrypt_config(&self, file: &str) -> Result<bool, String> {
        let hash = match self.get_hash(file) {
            Some(hash) => hash,
            None => return Err("Invalid file".to_string()),
        };

        let encrypted_data = fs::read_to_string(file)?;
        let decrypted_data = PBKDF2
            .new_with_password("password", "salt", &encrypted_data, 1024)
            .last_10_bytes();

        if !decrypted_data.contains(hash) {
            return Err(format!("Invalid hash for file {}", file));
        }

        Ok(true)
    }

    fn get_hash(&self, file: &str) -> Option<String> {
        let re = Regex::new(r"_(\w+)$").unwrap();
        match re.captures(file) {
            Some(cap) => Some(cap.get(1).unwrap().as_str().to_string()),
            None => None,
        }
    }
}

fn main() {
    let cm = ConfigManager::new("https://github.com/user/repo", "main");
    if let Err(err) = cm.sync_config() {
        eprintln!("{}", err);
    } else {
        println!("Config synced successfully!");
    }
}
