import json
import os
import time
from typing import Dict, List
import boto3
import redis
from cryptography.hazmat.primitives import hashes
from concurrent.futures import ThreadPoolExecutor, as_completed
import logging
from functools import lru_cache

logger = logging.getLogger(__name__)

class ConfigManager:
    def __init__(self):
        self.local_configs = {}
        self.ssm_config = None
        self.redis_client = redis.Redis(host='localhost', port=6379, db=0)
        self.cache_size = 1000
        self.thread_pool = ThreadPoolExecutor(max_workers=5)

    @lru_cache(maxsize=self.cache_size)
    def get_config(self, key: str) -> Dict:
        if key in self.local_configs:
            return self.local_configs[key]
        elif self.ssm_config is not None and self.ssm_config.get(key):
            return self.ssm_config[key]
        else:
            raise KeyError(f"Configuration key '{key}' not found")

    def load_local_configs(self, path: str) -> None:
        if not os.path.exists(path):
            return
        with open(path, 'r') as f:
            self.local_configs = json.load(f)

    def load_ssm_config(self) -> None:
        ssm = boto3.client('ssm', region_name='your-region')
        response = ssm.get_parameter(Name='your-parameter-name', WithDecryption=False)
        if response['Parameter']['Value']:
            self.ssm_config = json.loads(response['Parameter']['Value'])

    def hash_string(self, input_string: str) -> Dict:
        md5_hash = hashes.hash_md5(input_string.encode()).hexdigest()
        sha256_hash = hashes.hash_sha256(input_string.encode()).hexdigest()
        return {'md5': md5_hash, 'sha256': sha256_hash}

    @lru_cache(maxsize=self.cache_size)
    def get_hashes(self, input_string: str) -> Dict:
        if input_string in self.redis_client:
            return json.loads(self.redis_client.get(input_string))
        else:
            future = self.thread_pool.submit(self.hash_string, input_string)
            result = future.result()
            self.redis_client.set(input_string, json.dumps(result), ex=60*60)
            return result

    def run(self) -> None:
        while True:
            try:
                # Load local and remote configurations
                self.load_local_configs('config.json')
                self.load_ssm_config()

                # Retrieve hashes for repeated requests
                input_string = 'your-input-string'
                hashes_result = self.get_hashes(input_string)
                logger.info(f"Hashes for '{input_string}': {hashes_result}")

            except Exception as e:
                logger.error(f"Error: {e}")
            finally:
                time.sleep(1)

if __name__ == "__main__":
    config_manager = ConfigManager()
    config_manager.run()
