def process_transactions(gateways, transactions):
    metrics = {'success_rate': {}, 'weighted_sum_max': None}
    max_weighted_sum = 0

    for transaction in transactions:
        # Filter transactions based on criteria
        if not filter_transactions(transaction):
            continue

        available_gateways = [g for g in gateways if g.rate_limit > sum(g.process_transaction(t) for t in transactions)]
        gateway = random.choice(available_gateways)

