class ImageConverter {
public:
    ImageConverter(const std::string& inputFilePath, const std::string& outputFilePath, const std::string& formatType)
        : inputFilePath_(inputFilePath), outputFilePath_(outputFilePath), formatType_(formatType) {}

    void setQualityLevel(int quality) {
        quality_ = quality;
    }

    void batchConvertAndSave(const std::vector<std::string>& inputFiles, const std::vector<std::string>& outputFiles) {
        for (int i = 0; i < inputFiles.size(); ++i) {
            Magick::Image image(Magick::Read(inputFiles[i]));
            image.modifyImage();
            if (formatType_ == "JPEG") {
                image.write(outputFiles[i].c_str(), quality_);
            } else if (formatType_ == "PNG") {
                image.write(outputFiles[i].c_str());
            }
            // Log conversion process
        }
    }

private:
    std::string inputFilePath_;
    std::string outputFilePath_;
    std::string formatType_;
    int quality_;
};
