import os
import hashlib
import logging
from flask import Flask, request, jsonify
from flask_caching import Cache
from flask_sse import sse
from threading import Thread, Lock
from queue import Queue

app = Flask(__name__)
cache = Cache(app, config={'CACHE_TYPE': 'SimpleCache', 'CACHE_THRESHOLD_PERCENTAGE': 0.5})
sse = SSE(app)

MAX_THREADS = int(os.environ.get('MAX_THREADS', 10))
CACHE_SIZE = int(os.environ.get('CACHE_SIZE', 1000))

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class HashCalculator:
    def __init__(self):
        self._hash_values = {}
        self._lock = Lock()
        self._queue = Queue()

    def _calculate_hash(self, file_path):
        try:
            with open(file_path, 'rb') as f:
                content = f.read()
                md5 = hashlib.md5(content).hexdigest()
                sha256 = hashlib.sha256(content).hexdigest()
                return {'md5': md5, 'sha256': sha256}
        except Exception as e:
            logger.error(f"Error calculating hash for {file_path}: {str(e)}")

    def get_hash(self, file_path):
        with self._lock:
            if file_path in self._hash_values:
                return self._hash_values[file_path]
            result = self._queue.get()
            while not self._queue.empty():
                self._queue.get()
            if result is None:
                result = self._calculate_hash(file_path)
                self._queue.put(result)
            self._hash_values[file_path] = result
            return result

class ThreadPool:
    def __init__(self, max_threads):
        self.max_threads = max_threads
        self.pool = []

    def submit(self, task):
        if len(self.pool) < self.max_threads:
            self.pool.append(Thread(target=task))
            self.pool[-1].start()
        else:
            logger.warning("ThreadPool is at maximum capacity")

    def shutdown(self):
        for thread in self.pool:
            thread.join()

@app.route('/update-metadata', methods=['PUT'])
def update_metadata():
    # ...

@app.route('/calculate-hash', methods=['POST'])
def calculate_hash():
    file_path = request.form['file_path']
    if not os.path.exists(file_path) or len(file_path) > 1000:
        return jsonify({'error': 'Invalid file path'}), 400

    thread_pool = ThreadPool(MAX_THREADS)
    thread_pool.submit(lambda: HashCalculator().get_hash(file_path))
    # ...

if __name__ == '__main__':
    app.run(debug=True, use_reloader=False)

