#include <openssl/evp.h>
#include <jansson/jansson.h>

EVP_CIPHER_CTX* getEncryptionCipher(int mode, const char* key, unsigned int key_len) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();

    switch (mode) {
        case 0: // ECB
            EVP_EncryptInit_ex(ctx, EVP_des_ecb(), NULL, (unsigned char*)key, key_len);
            break;
        case 1: // EDE
            EVP_EncryptInit_ex(ctx, EVP_des_ede(), NULL, (unsigned char*)key, key_len);
            break;
        case 2: // EDE3
            EVP_EncryptInit_ex(ctx, EVP_des_ede3(), NULL, (unsigned char*)key, key_len);
            break;
        case 3: // CFB
            EVP_EncryptInit_ex(ctx, EVP_des_cfb64(), NULL, (unsigned char*)key, key_len);
            break;
        default:
            ERR_error_string(ERR_R_BAD_MODE, (char*)malloc(20));
            return NULL;
    }

    return ctx;
}
