const { Buffer } = require('buffer');
const { Transform, pipeline } = require('stream');

class DataChunkTransformer extends Transform {
  _transform(chunk, encoding, callback) {
    this.push(chunk);
    callback();
  }
}

function copyDataChunks(dataChunks, byteRange = null, callback) {
  const totalBytes = dataChunks.reduce((acc, chunk) => acc + chunk.length, 0);
  if (byteRange && byteRange[1] > totalBytes) {
    throw new Error(`Requested byte range exceeds available data. Total bytes: ${totalBytes}`);
  }

  const desiredBytes = byteRange ? Math.max(0, Math.min(totalBytes, byteRange[1] - byteRange[0])) : totalBytes;
  const copiedDataChunks = [];
  let accumulatedBytes = 0;

  pipeline(
    new DataChunkTransformer(),
    (err) => {
      if (err) callback(err);
      else callback(null, Buffer.concat(copiedDataChunks));
    }
  );

  dataChunks.forEach((chunk) => {
    const chunkBytes = chunk.length;
    let remainingBytes = Math.min(desiredBytes - accumulatedBytes, chunkBytes);

    while (remainingBytes > 0) {
      const copiedChunk = new Buffer(Math.min(remainingBytes, chunkBytes));
      chunk.copy(copiedChunk, 0, 0, remainingBytes);
      copiedDataChunks.push(copiedChunk);
      accumulatedBytes += remainingBytes;
      remainingBytes = Math.max(0, chunkBytes - remainingBytes);
    }
  });
}

module.exports = copyDataChunks;
