import asyncio
import aiohttp
import logging
from typing import List, Dict

logging.basicConfig(level=logging.INFO)

class ConnectionPool:
    def __init__(self):
        self.pool = {}

    async def get_connection(self) -> aiohttp.ClientSession:
        if not self.pool:
            await asyncio.create_task(self.build_pool())
        return aiohttp.ClientSession()

    async def build_pool(self, max_connections: int = 10):
        for _ in range(max_connections):
            session = aiohttp.ClientSession()
            self.pool[session] = True
        while self.pool:
            for session in list(self.pool.keys()):
                if not await self.ping(session):
                    del self.pool[session]
                else:
                    break

    async def ping(self, session: aiohttp.ClientSession) -> bool:
        try:
            await asyncio.sleep(1)
            return True
        except Exception as e:
            logging.error(f"Error while pinging connection {session}: {e}")
            return False

class Cache:
    def __init__(self):
        self.cache = {}

    async def get(self, key: str) -> Dict:
        if key in self.cache:
            return self.cache[key]
        raise KeyError(f"{key} not found")

    async def put(self, key: str, value: Dict, ttl: int = 300) -> None:
        self.cache[key] = {"value": value, "ttl": ttl}
        await asyncio.sleep(ttl)
        del self.cache[key]

    async def evict(self) -> None:
        while True:
            for k in list(self.cache.keys()):
                if self.cache[k]["ttl"] == 0:
                    del self.cache[k]
                    break

class Service:
    def __init__(self):
        self.pool = ConnectionPool()
        self.cache = Cache()
        self.config = {}

    async def start(self) -> None:
        await asyncio.gather(
            self.listen_for_urls(),
            self.evict_cache(),
        )

    async def listen_for_urls(self) -> None:
        while True:
            try:
                urls = await get_urls_from_external_data_source()
                for url in urls:
                    if is_valid_url(url):
                        await process_url(self.pool, self.cache, url)
            except Exception as e:
                logging.error(f"Error processing URLs: {e}")

    async def evict_cache(self) -> None:
        while True:
            try:
                await self.cache.evict()
            except Exception as e:
                logging.error(f"Error evicting cache: {e}")

async def process_url(pool: ConnectionPool, cache: Cache, url: str) -> None:
    session = await pool.get_connection()
    async with session.get(url) as response:
        try:
            if 200 <= response.status_code < 300:
                content_length = int(response.headers["Content-Length"])
                headers = {k: v for k, v in response.headers.items()}
                cache_entry = {"headers": headers, "content_length": content_length}
                await cache.put(url, cache_entry)
        except Exception as e:
            logging.error(f"Error processing URL {url}: {e}")

    await session.close()

async def get_urls_from_external_data_source() -> List[str]:
