#include <curl/curl.h>
#include <stdio.h>
#include <stdarg.h>

int log_to_server(const char *url, int level, const char *message, va_list args) {
    CURL *curl;
    CURLcode res;
    char buffer[1024] = {0};
    va_list args_copy;

    va_copy(args_copy, args);

    sprintf(buffer, "level=%d&message=%s", level, message);
    int length = strlen(buffer);

    // Create a new curl session
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if(curl) {
        // Set the URL and headers
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, buffer);

        do {
            res = curl_easy_perform(curl);
            if(res != CURLE_OK) {
                printf("cURL error: %s\n", curl_easy_strerror(res));
                // Handle network errors gracefully
                if(res == CURLE_RECVFAIL || res == CURLE_FAILED_INIT) {
                    // Retry the request after a short delay
                    CURL *temp = curl;
                    curl_easy_cleanup(temp);
                    sleep(1);  // or use a better retry mechanism
                    curl_easy_init();
                    curl = temp;
                }
            }
        } while(res != CURLE_OK && res == CURLE_RECVFAIL);

        // Clean up resources
        curl_easy_cleanup(curl);
    }

    va_end(args_copy);

    return res == CURLE_OK ? 0 : -1;
}

