#include <vector>
#include <string>
#include <thread>
#include "third_party_library.h" // include your third-party library here

class ImageConverter {
public:
    ImageConverter(int quality = 80) : quality_(quality) {}

    void convert(const std::vector<std::tuple<std::string, std::string, std::string>>& inputs) {
        threads_.clear();
        conversions_.clear();

        for (const auto& input : inputs) {
            std::thread t([this, &input]() { this->convertThread(input); });
            threads_.push_back(t);
        }

        for (auto& thread : threads_) {
            thread.join();
        }
    }

private:
    void convertThread(const std::tuple<std::string, std::string, std::string>& input) {
        // log start time
        LOG_INFO("Converting " + std::get<0>(input));

        try {
            thirdPartyLibraryConvert(std::get<0>(input), std::get<1>(input), std::get<2>(input));
        } catch (const std::exception& e) {
            // log error
            LOG_ERROR("Conversion failed: " + std::get<0>(input) + " - " + e.what());
        }

        // log end time and quality used
        LOG_INFO("Conversion complete for " + std::get<0>(input) + " (quality: " + std::to_string(quality_) + ")");
    }

    int quality_;
    std::vector<std::thread> threads_;
    std::vector<void*> conversions_; // store conversion results
};
